# llama-server can serve HTTP 200 while running a model entirely on CPU when a
# GPU backend fails to init (#5807 / #5106 / #5830). Classify the startup log so
# Unsloth can warn. Priority: explicit "offloaded N/M layers to GPU" counts
# (authoritative), then GPU "model buffer size" lines (host-pinned _Host
# excluded), then the "device_info:" device table (disconfirm only).
_GPU_OFFLOAD_MARKERS = (
    "CUDA",
    "ROCm",
    "ROCM",
    "HIP",
    "Metal",
    "Vulkan",
    "OpenCL",
    "SYCL",
    "MUSA",
    "CANN",
)
_OFFLOADED_LAYERS_RE = re.compile(
    r"offloaded\s+(\d+)\s*/\s*(\d+)\s+layers?\s+to\s+gpu", re.IGNORECASE
)
_DEVICE_ROW_RE = re.compile(
    r"-\s*(CUDA|ROCm|ROCM|HIP|Metal|Vulkan|SYCL|OpenCL|MUSA|CANN|CPU)\w*\s*:",
    re.IGNORECASE,
)
_GPU_DEVICE_PREFIXES = (
    "cuda",
    "rocm",
    "hip",
    "metal",
    "vulkan",
    "sycl",
    "opencl",
    "musa",
    "cann",
)


def classify_gpu_offload_lines(lines: "list[str]") -> Optional[bool]:
    """True if the model landed on a GPU, False if it stayed on CPU despite GPU
    intent, None when the log has no usable signal."""
    # Counted offload is authoritative, keyed on the model with the most layers.
    # A separate MTP/draft model logs its own (much smaller) "offloaded N/M"
    # line, so decide on the largest-M line: a drafter that fits on GPU must not
    # mask a main model running on CPU. N>0 on that model is True, 0 is False.
    max_total = -1
    offloaded_at_max = 0
    for line in lines:
        match = _OFFLOADED_LAYERS_RE.search(line)
        if not match:
            continue
        offloaded, total = int(match.group(1)), int(match.group(2))
        if total > max_total or (total == max_total and offloaded > offloaded_at_max):
            max_total, offloaded_at_max = total, offloaded
    if max_total >= 0:
        return offloaded_at_max > 0

    # GPU marker on a *model* buffer; _Host buffers are CPU-pinned, not offload.
    # Buffer lines are authoritative: present but none on a GPU means CPU-only,
    # so do not let the device table below override that.
    saw_model_buffer = False
    for line in lines:
        if "model buffer size" not in line:
            continue
        saw_model_buffer = True
        if "_Host" not in line and any(m in line for m in _GPU_OFFLOAD_MARKERS):
            return True
    if saw_model_buffer:
        return False

    # device_info: lists *available* devices (printed whenever a GPU backend is
    # visible), not where the model loaded, so it can only disconfirm: an
    # all-CPU table means no usable GPU. A visible GPU device is not proof the
    # model used it, so it does not return True. Rows after the header only.
    after_header = False
    saw_device_row = False
    saw_gpu_device = False
    for line in lines:
        if "device_info:" in line:
            after_header = True
            continue
        if not after_header:
            continue
        match = _DEVICE_ROW_RE.search(line)
        if not match:
            continue
        saw_device_row = True
        if match.group(1).lower().startswith(_GPU_DEVICE_PREFIXES):
            saw_gpu_device = True
    if saw_device_row and not saw_gpu_device:
        return False
    return None


def _wsl_system_rocm_lib_dirs() -> "list[str]":
    """System ROCm lib dir(s) to load before a prebuilt's bundled HIP, on WSL.

    The bundled bare-metal HIP can't drive WSL's /dev/dxg and segfaults on the
    first GPU call; the system ROCm libs (libamdhip64 + librocdxg) can, while
    the bundle still supplies libggml-hip / librocblas (gfx1151 kernels).
    Mirrors install_llama_prebuilt._wsl_system_rocm_lib_dirs so a prebuilt that
    passed install validation runs the same at serve time. No-op off a ROCDXG
    WSL host (needs /dev/dxg, "microsoft" /proc/version, librocdxg in /opt/rocm).
    """
    try:
        if not os.path.exists("/dev/dxg"):
            return []
        with open("/proc/version", encoding = "utf-8", errors = "replace") as fh:
            if "microsoft" not in fh.read().lower():
                return []
    except (OSError, UnicodeDecodeError):
        return []
    out: "list[str]" = []
    for d in ("/opt/rocm/lib", "/opt/rocm/lib64"):
        if os.path.exists(os.path.join(d, "librocdxg.so")) or os.path.exists(
            os.path.join(d, "librocdxg.so.1")
        ):
            out.append(d)
    return out


def _bundled_hip_present(binary_dir: str) -> bool:
    """True when a prebuilt bundle ships its own HIP backend library."""
    if not binary_dir:
        return False
    try:
        # Glob the version suffix (libggml-hip.so, .so.0, .so.0.11.1) the same
        # way the installer's runtime health check matches libggml-hip.so*.
        return any(Path(str(binary_dir)).glob("libggml-hip.so*"))
    except OSError:
        return False


def _native_linux_system_rocm_lib_dirs(binary_dir: str = "") -> "list[str]":
    """System ROCm lib dir(s) to prepend before a prebuilt's bundled HIP, on native Linux.

    The bundled bare-metal HIP runtime can mismatch the host amdkfd driver and crash
    in hsa_init(); prepending the whole system ROCm lib dir loads a driver-matched,
    version-consistent stack (libhsa-runtime64 / libamdhip64 / librocblas) ahead of it.
    The whole dir is deliberate: mixing the bundle's rocBLAS with a different-version
    system HIP/ROCR risks missing symbols, and when it does load_model retries once
    with the bundle only. UNSLOTH_LLAMA_NO_SYSTEM_ROCM=1 skips the prepend up front,
    for a host whose system ROCm lacks this arch. No-op on WSL / non-Linux.
    """
    if os.environ.get("UNSLOTH_LLAMA_NO_SYSTEM_ROCM") == "1":
        return []
    if sys.platform != "linux" or os.path.exists("/dev/dxg"):
        return []
    if not os.path.exists("/dev/kfd"):
        return []
    if not _bundled_hip_present(binary_dir):
        return []
    # Env-configured ROCm root first; /opt/rocm only as a fallback so a stale
    # /opt/rocm doesn't shadow the driver-matching install these vars point at.
    candidates = []
    for var in ("HIP_PATH", "HIP_PATH_57", "ROCM_PATH"):
        val = os.environ.get(var)
        if val:
            candidates.append(val)
    candidates.append("/opt/rocm")
    out: "list[str]" = []
    seen: "set[str]" = set()
    for base in candidates:
        for lib_sub in ("lib", "lib64"):
            d = os.path.join(base, lib_sub)
            if d in seen:
                continue
            seen.add(d)
            if os.path.exists(os.path.join(d, "libhsa-runtime64.so")) or os.path.exists(
                os.path.join(d, "libhsa-runtime64.so.1")
            ):
                out.append(d)
                # ROCm keeps LLVM's versioned runtime under <root>/lib/llvm, so a
                # lib64 host still finds it under lib. Probe both and keep them
                # ahead of the bundle, else system libamd_comgr binds to the
                # bundle's incompatible libLLVM.so.*.
                for _sub in (lib_sub, "lib"):
                    llvm_lib = os.path.join(base, _sub, "llvm", "lib")
                    if llvm_lib not in seen and os.path.isdir(llvm_lib):
                        seen.add(llvm_lib)
                        out.append(llvm_lib)
    return out


# Plan-without-action re-prompt state now lives in tool_call_parser (imported above).

# Default max_tokens to the effective context when known. The floor is high
# enough for reasoning-heavy GGUFs and max_tokens-omitting API clients.
_DEFAULT_MAX_TOKENS_FLOOR = 32768
_DEFAULT_FIRST_TOKEN_TIMEOUT_S = 1200.0  # 20 min


def _conversation_recall_reserve(thread_id: Optional[str]) -> int:
    """Room to hold back during a fit for the turns recalled straight after it."""
    if not thread_id:
        return 0
    try:
        from core.rag import config as rag_config
        from core.rag import conversation_archive

        # Eligibility, not just availability. A temporary chat is never archived, so the
        # reserve stays empty while still being subtracted from the trim target. Measured
        # on a 4K chat: 15 tokens of conversation survived instead of 1,615.
        if not conversation_archive.can_archive(thread_id):
            return 0
        # And that it works: sqlite-vec can be present while the embedder cannot start,
        # so archiving fails quietly and the reserved room is pure loss on every
        # compaction, forgetting more history than having the feature off.
        if conversation_archive.degraded():
            return 0
        return max(0, int(rag_config.CONVERSATION_RECALL_RESERVE_TOKENS))
    except Exception:
        return 0


def _keeps_compaction_boundary(thread_id: Optional[str]) -> bool:
    """Whether this request's boundary will be there to restore next time.

    The boundary rides on the assistant turn's saved metadata, so a thread with no saved
    messages (incognito, or an API caller that persists nothing) never gets one back. The
    fit uses this to decide whether cutting deeper than needed buys anything.
    """
    if not thread_id:
        return False
    try:
        from storage import studio_db
        return bool(studio_db.chat_thread_has_messages(str(thread_id)))
    except Exception:
        return False


def _archive_branch_transcript(
    branch_messages: Optional[list[dict]], roles: Optional[tuple[str, ...]] = None
) -> Optional[list[str]]:
    """The active branch, one normalised string per message, or None if there is nothing."""
    if not branch_messages:
        return None
    try:
        from core.rag import conversation_archive
        return conversation_archive.branch_message_texts(branch_messages, roles)
    except Exception:
        return None


def _branch_boundary(conversation: list[dict], branch: Optional[list[dict]]) -> int:
    """How many of the REQUEST's own leading messages a fit has evicted.

    The boundary is persisted and re-applied to the NEXT request's saved transcript, so it
    must be counted in those terms. ``dropped_messages`` is not: the tool loop refits each
    iteration and the client sums the counts, so a long agent run also counts the tool
    exchanges it created, which the next request's transcript does not contain.

    Counted by identity. Instruction messages are skipped rather than treated as the front
    of the branch, or an Unsloth request (always system-prefixed) would report zero on every
    compaction and the boundary would slide every turn again. Everything from the newest
    USER turn on is excluded: it is never evicted, and an inline recall rewrites that turn
    into a new dict, which an identity scan reads as an eviction. Excluding just the last
    message is not the same thing, since a continued assistant message follows it.

    Every evicted message is counted, not just the leading run, because that is what the
    replay consumes: ``truncate_oldest_messages``'s ``min_dropped`` counts dropped messages
    and SKIPS protected groups. Stopping at the first survivor matched that only while
    eviction was a clean prefix, which a protected group (an instruction pin, an anchored
    recall) breaks, leaving live turns on both sides. Under a checkpoint reset that
    understated the boundary enough to un-compact the epoch: the removed turns returned on
    the next request, one turn after the user was told they were compacted away. Where
    eviction IS a prefix, which is every pin-free rolling case, the count is unchanged.
    """
    messages = list(branch or ())
    cutoff = max(
        (index for index, message in enumerate(messages) if message.get("role") == "user"),
        default = max(0, len(messages) - 1),
    )
    messages = messages[:cutoff]
    live = {id(message) for message in conversation}
    count = 0
    for message in messages:
        if message.get("role") in ("system", "developer"):
            continue
        if id(message) not in live:
            count += 1
    return count


def _records_boundary(truncation: dict) -> bool:
    """Whether a fit removed turns from the prompt it sent, so its depth is worth saving.

    Not ``fits``: a rescue reports false yet really did evict, and the client reads this
    depth to place the compaction notice, so recording nothing compacts silently. Saving
    is not replaying -- `_sticky_compaction_boundary` still declines any `fits` false
    record, which is where a missed reserve belongs.
    """
    return bool(truncation.get("fits")) or bool(truncation.get("dropped_messages"))


def _effective_headroom_ratio(compaction_headroom_ratio: Optional[float] = None) -> float:
    """The extra-trim share this request's rolling fit actually used."""
    ratio = clamp_compaction_headroom_ratio(compaction_headroom_ratio)
    return _COMPACTION_HEADROOM_RATIO if ratio is None else ratio


def _boundary_metadata(
    fitted: list[dict],
    before: Optional[list[dict]],
    compaction_headroom_ratio: Optional[float] = None,
) -> dict:
    """Where this fit put the boundary, and under how much extra trim.

    The ratio rides with the depth because the depth cannot be read without it: phase one
    of `fit_rolling_context` re-applies the saved count before anything else and stops once
    the result fits, so a chat whose setting has moved either way would replay the old cut
    and never reach the phase that consults the new one.
    """
    return {
        "boundary_messages": _branch_boundary(fitted, before),
        "boundary_anchor": _branch_boundary_anchor(fitted, before),
        "boundary_headroom_ratio": _effective_headroom_ratio(compaction_headroom_ratio),
    }


def _branch_non_system(branch: Optional[list[dict]]) -> list[dict]:
    """The branch as ``_branch_boundary`` counts it: system and developer turns removed."""
    return [
        message for message in (branch or ()) if message.get("role") not in ("system", "developer")
    ]


def _branch_boundary_anchor(conversation: list[dict], branch: Optional[list[dict]]) -> str:
    """The text of the first message a fit kept AFTER everything it dropped, or "".

    ``boundary_messages`` is a count against one particular transcript, and the next
    request's transcript is not guaranteed to be that one plus new turns: deleting an
    already-evicted prompt shortens the front, so replaying the count unchanged lands the
    boundary two messages too deep and evicts history that is still live. The anchor names
    the message the boundary was meant to land ON, which survives a deletion in front of it.

    After the LAST eviction, not simply the first survivor. Eviction is a clean prefix only
    while nothing is protected mid-list; an instruction pin or an anchored recall leaves
    live turns on both sides, and the first survivor is then the pin itself, sitting near
    the front. `_sticky_compaction_boundary` clamps the count down to the anchor's index,
    so anchoring on the pin cut the replayed boundary back to the pin and handed back every
    turn compacted after it -- one turn after the user was told they were compacted away,
    which is the same un-compaction `_branch_boundary`'s own count was fixed to prevent.

    Text, not an id or an index: ids are per-request objects and an index is the very thing
    that goes stale. Read back by ``_sticky_compaction_boundary``, which only ever lets the
    anchor make the boundary SHALLOWER, so a stale or ambiguous anchor costs one extra
    compaction and can never evict a live turn.
    """
    messages = _branch_non_system(branch)
    live = {id(message) for message in conversation}
    last_dropped = max(
        (index for index, message in enumerate(messages) if id(message) not in live),
        default = -1,
    )
    for message in messages[last_dropped + 1 :]:
        if id(message) in live:
            return _anchor_text(message)
    return ""


# Bounded so one long tool argument cannot bloat the metadata the UI stores per turn. The
# name plus the head of the arguments is already enough to tell two calls apart.
_ANCHOR_ARGS_CHARS = 200
# And the anchor as a whole. It rides in every `context_truncated` event and is persisted
# on every assistant turn for as long as the boundary stays sticky, so returning a large
# pasted prompt whole duplicated it across the thread's SSE payloads and history rows. A
# head is enough to name a message, and the read side clamps only ever SHALLOWER, so two
# messages sharing a head cost one extra compaction rather than a live turn.
_ANCHOR_TEXT_CHARS = 200


def _anchor_text(message: dict) -> str:
    """A message as the anchor spells it: its text, or its tool calls when it has none.

    A normal OpenAI assistant tool-call message carries empty ``content`` and puts its
    substance in ``tool_calls``. Reading only ``content`` recorded an empty anchor there,
    which silently disables the rebase: the next request cannot re-derive the boundary
    against a shortened transcript and replays the stale count, evicting one more live
    message per deleted one. Both sides of the comparison use this, so what is written is
    what is looked for.
    """
    text = _archive_message_text(message.get("content"))
    if text:
        return text[:_ANCHOR_TEXT_CHARS]
    parts = []
    for call in message.get("tool_calls") or ():
        function = (call or {}).get("function") or {}
        name = str(function.get("name") or "tool")
        arguments = str(function.get("arguments") or "").strip()[:_ANCHOR_ARGS_CHARS]
        parts.append(f"{name}: {arguments}" if arguments else name)
    return "\n".join(parts)[:_ANCHOR_TEXT_CHARS]


def _archive_message_text(content) -> str:
    """One stored message flattened the way the branch check flattens it, or ""."""
    try:
        from core.rag import conversation_archive
        return conversation_archive.message_text(content)
    except Exception:
        return ""


def _archive_content_on_branch(content, transcript: Optional[list[str]]) -> bool:
    if transcript is None:
        return True
    try:
        from core.rag import conversation_archive
        return conversation_archive.content_on_branch(content, transcript)
    except Exception:
        return True


def _sticky_compaction_state(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> tuple[int, bool]:
    """How many leading messages this thread last compacted away, and who compacted them.

    The provenance decides which fitter may consume the count. A rolling boundary handed
    to `fit_checkpoint_context` reads as an epoch already in force, so the fit returns
    `checkpoint_started` false and `_archive_and_recall` skips the recall the rolling
    fallback would have run. Mixed provenance across surviving rows counts as rolling:
    `min(boundaries)` below may pick either row, so the safe reading is the one that still
    recalls.

    The fit is otherwise stateless: the client re-sends the whole transcript each request,
    so "keep the newest N tokens" slides forward every turn, which tells the user nothing
    useful and throws away llama-server's prefix cache each time the head moves. Reading
    the boundary back makes compaction an occasional event.

    Read from the thread's newest assistant turn, which already persists this number for
    the UI, so nothing new is stored and it survives a restart. Never raises: no history,
    a non-persisting API client, or a storage error all mean "no boundary".
    """
    if not thread_id:
        return 0, False
    requested_ratio = _effective_headroom_ratio(compaction_headroom_ratio)
    try:
        from storage import studio_db

        # The stored rows are the whole DAG, so the newest assistant turn can belong to a
        # sibling branch left by Retry, whose boundary is sized for history this branch
        # does not have. Skip rows the request's own messages do not contain.
        # Assistant messages only: the rows being checked are assistant replies, and
        # against every role a short abandoned one ("Done") rides in on a live user
        # message that merely contains it ("not done yet"), taking its boundary with it.
        _branch = _archive_branch_transcript(branch_messages, ("assistant",))
        if branch_messages and not _branch:
            # A branch with no reply of its own has no boundary to restore.
            return 0, False
        candidates = [
            message
            for message in reversed(studio_db.list_chat_messages(thread_id) or [])
            if message.get("role") == "assistant"
            and _archive_content_on_branch(message.get("content"), _branch)
        ]
        if not candidates:
            return 0, False

        # The newest on-branch assistant turn decides, except that the branch check is
        # textual, so two Retry siblings that both read "Done" are indistinguishable here
        # and the first match could apply a much deeper branch's boundary. Where the text
        # cannot separate them, take the SMALLEST boundary: too small costs one extra
        # compaction, too large evicts live history.
        # That check is also a substring test (an archived turn is matched against
        # fragments of itself), so an abandoned "Done" can ride in on a live "Not done
        # yet" and then decide the boundary alone. Prefer exact matches where any exist.
        _live = set(_branch or ())
        _exact = [
            message
            for message in candidates
            if _archive_message_text(message.get("content")) in _live
        ]
        if _exact:
            candidates = _exact

        newest = _archive_message_text(candidates[0].get("content"))
        boundaries = []
        origins = []
        for message in candidates:
            if _archive_message_text(message.get("content")) != newest:
                continue
            metadata = message.get("metadata") or {}
            if not isinstance(metadata, dict):
                return 0, False
            truncation = metadata.get("contextTruncation") or (metadata.get("custom") or {}).get(
                "contextTruncation"
            )
            if not isinstance(truncation, dict):
                return 0, False
            # Only a fit that SUCCEEDED describes a boundary worth restoring.
            if not truncation.get("fits"):
                return 0, False
            # A boundary is valid only under the fit that will consume it, and the two
            # directions fail differently.
            #
            # A checkpoint boundary is the depth of a RESET, affordable only because the
            # block is rebuilt on every replay. Under rolling nothing rebuilds it, so the
            # depth replays with nothing handed back (18 evicted where rolling picks 6).
            # Refused HERE, not at the fit: `boundary_messages` is re-recorded every turn,
            # so a rolling turn that inherited 18 would persist it with no `checkpoint` key
            # and make the reset-sized window permanent.
            #
            # The other way, a rolling boundary reaching `fit_checkpoint_context` reads as
            # an epoch already in force, so the reset returns `checkpoint_started` false
            # and the automatic recall never runs. That only happens where the request may
            # actually reset; `_can_reset_epoch` false means the fit stays rolling whatever
            # the process policy says, and there the rolling boundary is the right one to
            # replay. Rejecting it there instead let the boundary slide every turn for any
            # model whose template cannot render tools.
            recorded_checkpoint = bool(truncation.get("checkpoint"))
            effective_checkpoint = _request_uses_checkpoint(context_policy)
            if recorded_checkpoint and not effective_checkpoint:
                return 0, False
            if not recorded_checkpoint and effective_checkpoint and can_reset:
                return 0, False
            # Changing the extra trim has to change something. Phase one of
            # `fit_rolling_context` re-applies this count before anything else and stops
            # once the result fits, so a boundary cut under a DIFFERENT ratio never reaches
            # the phase that reads the new one, in either direction: measured on a
            # 121-message transcript at context_length 1600, a stored boundary of 86 gave
            # `dropped 86` whether the request asked for 0.05 or 0.25. Refusing it makes
            # the fit recompute, which is the only place the new ratio is read. Absent on
            # rows saved before the ratio was recorded, which keep replaying as they did.
            if not recorded_checkpoint:
                recorded_ratio = truncation.get("boundary_headroom_ratio")
                if (
                    recorded_ratio is not None
                    and abs(float(recorded_ratio) - requested_ratio) > 1e-9
                ):
                    return 0, False
            # Counted against the request's own transcript, which is what it is applied
            # to. `dropped_messages` is the fallback for turns saved before that was
            # recorded: equal for a single fit, too large for a turn that refit often.
            recorded = truncation.get("boundary_messages")
            if recorded is None:
                recorded = truncation.get("dropped_messages")
            recorded = max(0, int(recorded or 0))
            # A count is only valid against the transcript it was counted on. Deleting an
            # already-evicted turn shortens the front, and replaying the count then evicts
            # that many LIVE messages instead. Re-derive it from the anchor's position on
            # this request's own branch. Only ever downward: an anchor that has moved back
            # (a repeated text, an edited turn) must not deepen the cut.
            anchor = truncation.get("boundary_anchor")
            if isinstance(anchor, str) and anchor:
                for index, message in enumerate(_branch_non_system(branch_messages)):
                    if _anchor_text(message) == anchor[:_ANCHOR_TEXT_CHARS]:
                        recorded = min(recorded, index)
                        break
            boundaries.append(recorded)
            origins.append(recorded_checkpoint)
        if not boundaries:
            return 0, False
        return min(boundaries), all(origins)
    except Exception:
        return 0, False


def _sticky_compaction_boundary(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> int:
    """`_sticky_compaction_state` without the provenance, for callers that only fit."""
    return _sticky_compaction_state(
        thread_id,
        branch_messages,
        context_policy = context_policy,
        can_reset = can_reset,
        compaction_headroom_ratio = compaction_headroom_ratio,
    )[0]


def _prefix_user_text(message: dict, prefix: str) -> dict:
    """Copy of ``message`` with ``prefix`` in front of its text. Never mutates."""
    content = message.get("content")
    if isinstance(content, str) or content is None:
        return {**message, "content": prefix + (content or "")}
    if isinstance(content, list):
        parts = list(content)
        for index, part in enumerate(parts):
            if isinstance(part, dict) and part.get("type") in ("text", "input_text"):
                parts[index] = {**part, "text": prefix + str(part.get("text") or "")}
                return {**message, "content": parts}
        return {**message, "content": [{"type": "text", "text": prefix}] + parts}
    return message


# A readable local name for the shared `context_window` policy, not a second implementation.
_retrieval_budget = retrieval_budget


def _recall_top_k(budget_tokens: int) -> int:
    """How many archived chunks actually fit in the room a fit obtained.

    The reserve is what the fit AIMS to hold back, not what it gets: protected messages
    (system, latest turn, anchored recalls) can stop the trim reaching its target while
    still passing the prompt budget. Injecting a full reserve on top then overflows the
    window -- reproduced at ctx 8000: fit accepted at 6900, recall took it to 8948. So
    size the recall from the room actually left.
    """
    try:
        from core.rag import config as rag_config
        chunk = max(1, int(rag_config.CHUNK_TOKENS))
        cap = max(0, int(rag_config.CONVERSATION_ARCHIVE_TOP_K))
    except Exception:
        return 0
    fits = int(budget_tokens) // chunk
    if fits <= 0 and int(budget_tokens) > 0:
        # One attempt whenever there is ANY room. `CHUNK_TOKENS` is a ceiling, not the
        # size of a turn: most archived turns are far smaller, so flooring to zero
        # disabled recall on exactly the tight windows that need it. The exact recount
        # below is what actually decides, and it rejects a chunk that does not fit.
        fits = 1
    return max(0, min(cap, fits))


def _archive_and_recall(
    conversation: list[dict],
    before: list[dict],
    *,
    thread_id: Optional[str],
    style: str,
    recall_done: bool,
    force_recall: bool = True,
    recall_budget_tokens: int = 0,
    count_tokens: Optional[Callable[[list[dict]], int]] = None,
    branch_messages: Optional[list[dict]] = None,
) -> dict:
    """Keep the turns this fit evicted, then pull the relevant ones back.

    Returns ``{"conversation", "events", "counts", "recalled"}``. Never raises: every
    failure degrades to the plain fitted messages. Recall fires at most once per request,
    or the tool loop's per-iteration refit would stack a recall block onto each pass.
    """
    result = {
        "conversation": conversation,
        "events": [],
        "counts": {},
        "recalled": False,
        "anchored": [],
    }
    if not thread_id:
        return result
    try:
        from core.inference.tools import build_conversation_recall
        from core.rag import conversation_archive

        if not conversation_archive.enabled():
            return result

        gone = evicted_messages(before, conversation)
        # `conversation` is the fitted prompt, so it says which repeats of a turn the model
        # can still read. Without it a twice-said turn is archived twice and spends two
        # recall slots on text already in the prompt.
        archived = (
            conversation_archive.archive_turns(
                thread_id, gone, live = conversation, branch = branch_messages or conversation
            )
            if gone
            else 0
        )
        counts = {"archived_messages": archived}

        if recall_done:
            result["counts"] = counts
            return result
        if not force_recall:
            # Checkpoint mode, past the first turn of the epoch. Archiving still ran above
            # (it must, or the epoch stops being searchable), but the automatic lookup fires
            # only on the turn that reset the conversation; after that the model has
            # `search_conversation` and decides for itself.
            result["counts"] = counts
            return result

        top_k = _recall_top_k(recall_budget_tokens)
        if top_k <= 0:
            # No room obtained. Archiving still happened, so the turns stay searchable
            # and the next fit can recall them.
            result["counts"] = counts
            return result

        # An EXACT recount decides affordability: the chunk arithmetic above is doubly an
        # estimate, since CHUNK_TOKENS is an embedding-token limit rather than the chat
        # template's cost and neither it nor the budget covers the wrapper text.
        # When the recount says no, ask for FEWER turns rather than giving up: with the
        # shipped defaults a full top-K of long turns lands just over the reserve once
        # wrapped, and dropping it would disable recall on exactly the long conversations
        # this exists for. Halving is bounded (4 -> 2 -> 1), one small query per attempt.
        attempts = []
        attempt_k = top_k
        while True:
            attempts.append(attempt_k)
            if attempt_k <= 1:
                break
            attempt_k = max(1, attempt_k // 2)

        for index, k in enumerate(attempts):
            recall = build_conversation_recall(
                conversation,
                thread_id,
                style = style,
                top_k = k,
                branch_messages = branch_messages,
            )
            if not recall:
                result["counts"] = counts
                return result

            candidate = _inject_recall(conversation, recall, style)
            if candidate is None:
                result["counts"] = counts
                return result

            grew = None
            if count_tokens is not None and recall_budget_tokens > 0:
                try:
                    grew = count_tokens(candidate["conversation"]) - count_tokens(conversation)
                except Exception:
                    grew = None
            if grew is not None and grew > recall_budget_tokens:
                logger.info(
                    "conversation_recall.over_budget grew=%s budget=%s top_k=%s",
                    grew,
                    recall_budget_tokens,
                    k,
                )
                if index + 1 < len(attempts):
                    continue
                logger.info(
                    "conversation_recall.dropped_over_budget budget=%s", recall_budget_tokens
                )
                result["counts"] = counts
                return result

            result["conversation"] = candidate["conversation"]
            result["events"] = candidate["events"]
            result["anchored"] = candidate["anchored"]
            break

        counts["recalled_chunks"] = int(recall.get("sources") or 0)
        result["counts"] = counts
        result["recalled"] = True
    except Exception as exc:
        logger.warning("Could not archive or recall compacted turns: %s", exc)
    return result


def _inject_recall(conversation: list[dict], recall: dict, style: str) -> Optional[dict]:
    """The conversation with ``recall`` added, or None if there was nowhere to put it.

    ``anchored`` is only what this injection added: the two synthetic tool messages, or
    the rewritten user message inline. The caller protects those from a later refit, and
    anything else would pin a real turn the fit is entitled to evict.
    """
    if style == "inline":
        prefix = recall.get("prefix") or ""
        updated = list(conversation)
        for index in range(len(updated) - 1, -1, -1):
            if updated[index].get("role") == "user":
                updated[index] = _prefix_user_text(updated[index], prefix)
                break
        else:
            return None
        return {"conversation": updated, "events": [], "anchored": [updated[index]]}
    added = list(recall["messages"])
    return {
        "conversation": list(conversation) + added,
        "events": list(recall["events"]),
        "anchored": added,
    }


# A transport error can arrive before the child is reapable; a request path cannot
# afford the 5s the background MTP reload spends on the same race.
_RESPAWN_REAP_GRACE_S = 1.0


def _finalize_reasoning_only_cumulative(
    cumulative: str, reasoning_text: str, finish_reason: Optional[str], promote_reasoning_only: bool
) -> str:
    """Close a live thinking block and promote it only after a clean stop.

    Local inference streams cumulative snapshots. Replacing ``<think>...`` with
    bare reasoning at EOF makes the final snapshot shorter, so suffix-based
    route consumers drop the intended fallback. Keep the snapshot append-only.
    A length-truncated thought is not a final answer, so close it without
    promotion and let the client surface the ``length`` terminal state. Raw
    consumers that do not split reasoning from visible content can disable the
    fallback to avoid returning the same reasoning twice.
    """
    visible_fallback = (
        reasoning_text if promote_reasoning_only and finish_reason != "length" else ""
    )
    return cumulative + "</think>" + visible_fallback


# Only large streamed tool payloads get an early provisional card; render_html
# is exempt because it needs immediate artifact feedback.
_PROVISIONAL_ARGS_MIN_CHARS = 256
_DEFAULT_STREAM_STALL_TIMEOUT_S = 120.0  # 2 min
# Cap tool calls from a single TEXTUAL-fallback turn (mirrors the safetensors
# loop). Structured delta.tool_calls are grammar-bounded by llama-server; text
# parsed from content is not, so one runaway turn could fan out unbounded.
_MAX_TOOL_CALLS_PER_TURN = 8
# How far back the classifier looks for llama.cpp's argument-parsing error. It
# prints one and exits, so it is always at the end; generous enough to survive a
# usage hint printed after it, small enough that a 10 MB unterminated line (which
# _drain_stdout keeps whole) stays cheap to scan.
_FAILURE_SCAN_TAIL_CHARS = 64 * 1024
# How much of a quoted fragment from the child's own output an error message carries.
# Long enough for any real flag or reason, short enough that a wrapper printing
# megabytes cannot make the API error unreadable.
_FAILURE_QUOTE_CHARS = 200
# Obligation phrasing INTENT_SIGNAL leaves alone ("I need to call ..."), paired with
# an action verb. Sentence-anchored: mid-sentence the same words are prose that names
# a tool ("The API I should invoke is foo() because ..."), and suppressing that loses
# a real answer. "should"/"must" sit outside the need|have|ought group because they
# take a bare infinitive. "invoke"/"query" stay out of the verb list: they read as
# technical prose far more often than as a stall.
_FORCED_PLAN_INTENT = re.compile(
    r"(?:^|[.!?]\s+)\s*"
    r"(?:i\s+(?:(?:need|have|ought)\s+to|should|must)|need\s+to|going\s+to|must|should)"
    r"\s+(?:\w+\s+){0,2}?(?:call|use|run|search|fetch|render)\b",
    re.I | re.M,
)
# "the answer is not in the context" announces a *missing* answer, so the negated
# forms are excluded or the plan behind them would ship as the final response.
_FINAL_ANSWER_SIGNAL = re.compile(
    r"\b(?:final\s+answer|answer\s*:|here\s+is|here's|in\s+summary|result\s*:"
    r"|(?:the\s+)?answer\s+is(?!\s+(?:not|unavailable|unknown|unclear|missing)\b))\b",
    re.I,
)
# A plan that pivots ("I should call web_search, but Tokyo is the capital") has an
# answer attached, so the turn must survive. Leaking a plan sentence is cosmetic;
# dropping an answer is not, so the doubtful case keeps the output. The pivot has to
# carry text of its own: "I should call web_search, though." answers nothing.
_ANSWER_PIVOT = re.compile(
    r"\b(?:but|however|although|though|that\s+said|in\s+the\s+meantime|meanwhile)\b"
    r"[\W_]*(?:\w+[\W_]+){1,}\w",
    re.I,
)


def _gguf_active_tool_names(active_tools: list[dict]) -> list[str]:
    names = [
        (tool.get("function") or {}).get("name")
        for tool in (active_tools or [])
        if isinstance(tool, dict) and isinstance(tool.get("function"), dict)
    ]
    return [name for name in names if name]


# Rehearsal NAME chars (word + hyphen, matching the parser); the lookbehind excludes the
# Mistral [CALL_ID]...[ARGS] shape.
_GGUF_REHEARSAL_ARGS_RE = re.compile(r"(?<!\[CALL_ID\])\b([\w-]+)\[ARGS\]")


def _gguf_rehearsal_signal_pos(text: str, active_tools: list[dict]) -> int:
    """Index of the first ``NAME[ARGS]`` whose NAME is an active tool, else -1. A
    bare/inactive-name ``foo[ARGS]`` in prose is not a call; mirrors the safetensors
    ``_earliest_tool_signal`` name-gating (no unrestricted GGUF mode)."""
    active = set(_gguf_active_tool_names(active_tools))
    if not active:
        return -1
    for m in _GGUF_REHEARSAL_ARGS_RE.finditer(text):
        if m.group(1) in active:
            return m.start()
    return -1


def _gguf_has_genuine_tool_signal(text: str, signals, active_tools: list[dict]) -> bool:
    """True when ``text`` holds a genuine tool-call boundary for one of ``signals``.

    Unambiguous markers (``<tool_call>``, ``[TOOL_CALLS]``, ``<function=``) count on a
    plain substring hit; an ``[ARGS]`` hit is genuine only when an active tool name
    precedes it, so inactive-name prose is neither drained nor parsed."""
    for sig in signals:
        if sig == "[ARGS]":
            if _gguf_rehearsal_signal_pos(text, active_tools) >= 0:
                return True
            continue
        if sig in text:
            return True
    return False


_TEXT_TOOL_NAME_RE = re.compile(r'"name"\s*:\s*"([\w.\-]+)"')
_TEXT_TOOL_GEMMA_RE = re.compile(r"\s*call:([\w.\-]+)")
_TEXT_TOOL_REHEARSAL_RE = re.compile(r"\s*([\w.\-]+)\s*\[ARGS\]")


def _sniff_text_tool_name(text: str, enabled_names: set) -> str:
    """Best-effort tool name from a partially drained TEXT tool call, gated on
    enabled names so prose can never spawn a card. Used only to open the live
    argument pane early; the authoritative parse still happens at stream end."""
    m = _TEXT_TOOL_NAME_RE.search(text[:4096])
    if m and m.group(1) in enabled_names:
        return m.group(1)
    m = _TEXT_TOOL_GEMMA_RE.match(text[:256])
    if m and m.group(1) in enabled_names:
        return m.group(1)
    m = _TEXT_TOOL_REHEARSAL_RE.match(text[:256])
    if m and m.group(1) in enabled_names:
        return m.group(1)
    return ""


def _is_rehearsal_prefix(stripped: str, active_tools: list[dict]) -> bool:
    """True if ``stripped`` is a (possibly partial) prefix of ``NAME[ARGS]`` for an
    active tool -- the bare tool name arriving in its own chunk before ``[ARGS]{...}``.
    Mirrors the safetensors loop so the split rehearsal call is not streamed."""
    if not stripped or any(ch.isspace() for ch in stripped):
        return False
    for name in _gguf_active_tool_names(active_tools):
        if stripped == name or f"{name}[ARGS]".startswith(stripped):
            return True
    return False


def _held_rehearsal_tail_len(text: str, active_tools: list[dict]) -> int:
    """Length of a trailing bare tool-name token that may be a split rehearsal call
    (``...web_search`` with ``[ARGS]{...}`` still to arrive), so STREAMING can hold it
    instead of leaking the name. Returns 0 for ordinary prose. Mirrors safetensors."""
    i = len(text)
    while i > 0 and not text[i - 1].isspace():
        i -= 1
    tail = text[i:]
    return len(tail) if tail and _is_rehearsal_prefix(tail, active_tools) else 0


def _should_suppress_forced_no_tool_output(text: str, previous: str = "") -> bool:
    """Suppress only repeated forced-turn planning text, not final answers.

    ``previous`` is the stall text that triggered the nudge, so a retry that
    moved on can be told from one that just said the same thing again.
    """
    stripped = text.strip()
    if not stripped or len(stripped) >= _REPROMPT_MAX_CHARS:
        return False
    if _FINAL_ANSWER_SIGNAL.search(stripped):
        return False
    plan = _FORCED_PLAN_INTENT.search(stripped)
    if plan is not None:
        # Only the plan itself is safe to drop; anything the turn pivots to after it
        # is the answer the user is waiting for.
        return _ANSWER_PIVOT.search(stripped[plan.end() :]) is None
    if not _is_short_intent_without_action(stripped):
        return False
    # INTENT_SIGNAL also fires on lead-ins to a real answer ("Now I have the results.
    # The capital is Tokyo."), so a bare intent match is a stall only when the retry
    # adds nothing. No ``previous`` keeps the standalone "is this a stall?" contract.
    return not previous or _is_reprompt_restatement(stripped, previous)


# ── Pre-compiled patterns for GGUF shard detection ───────────
_SHARD_FULL_RE = re.compile(r"^(.*)-(\d{5})-of-(\d{5})\.gguf$", re.IGNORECASE)
_SHARD_RE = re.compile(r"^(.*)-\d{5}-of-\d{5}\.gguf$", re.IGNORECASE)


# ── Sliding-window-pattern resolver ───────────────────────────
# Resolves the per-layer SWA mask when a GGUF reports a sliding window but
# no `sliding_window_pattern` field. Tier order in `_resolve_swa_pattern`:
# GGUF metadata, on-disk cache, bootstrap dict below, transformers
# introspection, HF Hub config.json, legacy 1/4 fallback. Period N means
# layer i is SWA iff `(i + 1) % N != 0`, matching transformers. Skipped on
# purpose: phi3 (no key/val length in GGUF, window >= ctx anyway), qwen2
# family (converter strips sliding_window when use_sliding_window=False),
# mistral v0.1/v0.2 (all-SWA can't be a period).
_BOOTSTRAP_SWA_DEFAULTS: dict[str, int] = {
    "gemma2": 2,  # Gemma2Config.sliding_window_pattern
    "gemma3": 6,  # Gemma3TextConfig.sliding_window_pattern
    "gemma3n": 5,  # text_config.layer_types: SWA*4 + FULL
    "gpt_oss": 2,  # text_config.layer_types: alternating
    "cohere2": 4,  # Cohere2Config.sliding_window_pattern
}

# Process-wide cache backed by JSON on disk. Values are int period or
# list[bool] mask. Lazy-loaded.
_SWA_CACHE: Optional[dict] = None
_SWA_CACHE_LOCK = threading.Lock()


def _hf_endpoint_host() -> str:
    """Host of the configured hub endpoint (HF_ENDPOINT aware)."""
    from utils.utils import hf_endpoint_host
    return hf_endpoint_host()


def _probe_dns_dead(host: Optional[str] = None, timeout: float = 2.0) -> bool:
    """Quick DNS check on a daemon thread, so concurrent sockets aren't
    affected by socket.setdefaulttimeout. Defaults to the configured endpoint's host."""
    from utils.utils import dns_host_dead, hf_endpoint_host
    return dns_host_dead(host or hf_endpoint_host(), timeout)


def _hf_env_offline() -> bool:
    """True when an HF offline env var is set to any truthy value (1/true/yes/on).

    Mirrors utils.models.model_config._env_offline so a user-set HF_HUB_OFFLINE=true
    (not just "1") still routes through the local-cache reuse path below.
    """
    try:
        from utils.models.model_config import _env_offline
        return _env_offline()
    except Exception:
        return os.environ.get("HF_HUB_OFFLINE", "").strip().lower() in {"1", "true", "yes", "on"}


def _hf_unreachable() -> bool:
    """True when the Hub can't be reached: dead DNS, or DNS that resolves with no egress.

    DNS alone misses the common shapes (WAN down behind a live router, captive portal,
    stale cache), leaving every hub call to burn its retry backoff. The DNS shortcut stands
    down when a proxy is configured, since the proxy resolves the host.
    """
    try:
        from utils.utils import hf_dns_dead, hf_reachability_memo, hf_unreachable
    except Exception:
        return False
    # A fresh verdict already answers this. One request opens several guards, and the DNS
    # shortcut is only cheap when DNS is fast: a slow resolver costs its full timeout per
    # guard and leaves a stuck thread behind each time. Peek only, never record: a dead
    # lookup fails fast anyway, and recording it would make recovery sticky for the TTL.
    memo = hf_reachability_memo()
    if memo is not None:
        return memo
    if hf_dns_dead():
        return True
    return hf_unreachable()


# Separates "nothing remembered" from a remembered verdict of None (not a media GGUF).
_MISS = object()


# GGUF unsigned value-type id -> byte width (uint8, uint16, uint32, uint64).
_GGUF_UINT_WIDTHS = {0: 1, 2: 2, 4: 4, 10: 8}


@contextlib.contextmanager
def _hf_offline_if_unreachable():
    """Force HF offline for this block only when the Hub is unreachable; restores on exit
    so a transient hiccup can't quarantine the process. No-op if the USER set the env var.

    Env vars alone are too late mid-process (the offline constants are read at import), so
    this holds a refcounted force_hf_offline window. Overlapping requests each take their
    own reference: no-opping would let another guard's exit restore the network
    mid-operation and drop this request back onto the retry path.
    """
    try:
        from utils.utils import force_hf_offline, force_hf_offline_state, hf_env_offline
    except Exception:
        yield False
        return

    ours, hf_hub_env_present = force_hf_offline_state()
    # Membership preserves HF_HUB_OFFLINE=0 as an explicit stay-online override.
    # Read it with the refcount so a concurrent guard cannot look user-owned.
    if hf_hub_env_present and not ours:
        yield False
        return
    # TRANSFORMERS_OFFLINE alone still asks for offline, and the hub does not read it.
    # Honour it directly: probing would put network traffic in an explicitly offline process.
    if not ours and hf_env_offline():
        with force_hf_offline():
            yield True
        return
    # Already forced by an in-flight guard: reuse that verdict and hold a reference.
    if not ours and not _hf_unreachable():
        yield False
        return

    if not ours:
        logger.warning("Hugging Face endpoint unreachable; using local HF cache for this load.")
    with force_hf_offline():
        yield True


def _hf_offline_if_unreachable_for(model_name):
    """Guard, but only for remote repo ids: a local path is served from disk and never
    reaches the hub, so probing would add seconds per request and prevent no retry."""
    try:
        from utils.paths import is_local_path
        if isinstance(model_name, str) and is_local_path(model_name):
            return contextlib.nullcontext()
    except Exception:
        pass
    return _hf_offline_if_unreachable()


try:
    _SLOT_SAVE_MAX_BYTES = int(os.environ.get("UNSLOTH_SLOT_SAVE_MAX_BYTES") or (10 << 30))
except ValueError:
    _SLOT_SAVE_MAX_BYTES = 10 << 30

# The idle loop holds the lifecycle gate across a slot save, so a newly arriving
# request waits on the in-flight save's HTTP call. Bound it (was 120s) so a slow
# or stuck save can't stall the next request for minutes; best-effort save just
# falls back to a plain unload. Override with UNSLOTH_SLOT_SAVE_TIMEOUT (seconds).
try:
    _SLOT_SAVE_HTTP_TIMEOUT = float(os.environ.get("UNSLOTH_SLOT_SAVE_TIMEOUT") or 30.0)
except ValueError:
    _SLOT_SAVE_HTTP_TIMEOUT = 30.0
if _SLOT_SAVE_HTTP_TIMEOUT <= 0:
    _SLOT_SAVE_HTTP_TIMEOUT = 30.0


def _swa_cache_path() -> Path:
    home = os.environ.get("UNSLOTH_STUDIO_HOME") or os.environ.get("STUDIO_HOME")
    base = Path(home) if home else Path.home() / ".unsloth" / "studio"
    return base / "swa_cache.json"


def _load_swa_cache() -> dict:
    global _SWA_CACHE
    with _SWA_CACHE_LOCK:
        if _SWA_CACHE is not None:
            return _SWA_CACHE
        try:
            with open(_swa_cache_path(), encoding = "utf-8-sig") as f:
                _SWA_CACHE = json.load(f)
                if not isinstance(_SWA_CACHE, dict):
                    _SWA_CACHE = {}
        except (FileNotFoundError, json.JSONDecodeError, OSError, UnicodeDecodeError):
            _SWA_CACHE = {}
        return _SWA_CACHE


def _save_swa_cache(cache: dict) -> None:
    try:
        path = _swa_cache_path()
        path.parent.mkdir(parents = True, exist_ok = True)
        tmp = path.with_suffix(".json.tmp")
        with open(tmp, "w", encoding = "utf-8") as f:
            json.dump(cache, f, indent = 2, sort_keys = True)
        tmp.replace(path)
    except (OSError, UnicodeDecodeError):
        pass


def _period_from_layer_types(layer_types: list) -> Optional[int]:
    """Smallest period N where `(i+1) % N != 0` matches the SWA mask, else None."""
    if not layer_types:
        return None
    is_swa = ["full" not in str(t).lower() for t in layer_types]
    n = len(is_swa)
    for N in range(1, n + 1):
        if all(((i + 1) % N != 0) == is_swa[i] for i in range(n)):
            return N
    return None


def _swa_entry_from_layer_types(lt) -> Optional[object]:
    """Period int, or per-layer bool mask, from a transformers ``layer_types`` list."""
    if isinstance(lt, list) and lt:
        return _period_from_layer_types(lt) or ["full" not in str(t).lower() for t in lt]
    return None


def _fetch_swa_entry_from_hf(repo_id: str) -> Optional[object]:
    try:
        from huggingface_hub import hf_hub_download
        from utils.hf_cache_settings import active_hf_hub_cache
        from utils.hf_probe import hf_file_definitely_absent

        # Avoid caching the expected 404 for GGUF repos without config.json.
        if hf_file_definitely_absent(repo_id, "config.json"):
            return None
        cfg_path = hf_hub_download(
            repo_id,
            "config.json",
            repo_type = "model",
            cache_dir = active_hf_hub_cache(),
        )
        with open(cfg_path, encoding = "utf-8-sig") as f:
            cfg = json.load(f)
    except Exception:
        return None

    src = cfg.get("text_config") if isinstance(cfg.get("text_config"), dict) else cfg
    period = src.get("sliding_window_pattern")
    if isinstance(period, int) and period > 0:
        return period
    return _swa_entry_from_layer_types(src.get("layer_types"))


def _arch_aliases(arch: str) -> tuple:
    # GGUF emits `falcon-h1`; HF model_type is `falcon_h1`. Normalise both ways.
    seen = []
    for a in (arch, arch.replace("-", "_"), arch.replace("_", "-")):
        if a and a not in seen:
            seen.append(a)
    return tuple(seen)


def _swa_entry_from_config_obj(cfg) -> Optional[object]:
    src = getattr(cfg, "text_config", None) or cfg
    period = getattr(src, "sliding_window_pattern", None)
    if isinstance(period, int) and period > 0:
        return period
    return _swa_entry_from_layer_types(getattr(src, "layer_types", None))


_SWA_PATTERN_SOURCE_RE = re.compile(r"sliding_window_pattern\s*(?::\s*[\w\[\], ]*)?\s*=\s*(\d+)")


def _resolve_swa_entry_from_transformers(arch: str) -> Optional[object]:
    """Default-instantiate the matching Config; on failure, regex-parse its
    source for `sliding_window_pattern = N`."""
    try:
        from transformers.models.auto.configuration_auto import (
            CONFIG_MAPPING,
            CONFIG_MAPPING_NAMES,
        )
    except Exception:
        return None

    cfg_class = None
    for alias in _arch_aliases(arch):
        if alias in CONFIG_MAPPING_NAMES:
            try:
                cfg_class = CONFIG_MAPPING[alias]
                break
            except Exception:
                cfg_class = None
    if cfg_class is None:
        return None

    try:
        if (entry := _swa_entry_from_config_obj(cfg_class())) is not None:
            return entry
    except Exception:
        pass

    import inspect

    candidates = [cfg_class]
    text_cfg_class = getattr(cfg_class, "sub_configs", {}).get("text_config")
    if text_cfg_class is not None:
        candidates.append(text_cfg_class)
    for cls in candidates:
        try:
            src = inspect.getsource(cls)
        except (OSError, TypeError):
            continue
        if m := _SWA_PATTERN_SOURCE_RE.search(src):
            period = int(m.group(1))
            if period > 0:
                return period
    return None


def _resolve_swa_pattern(
    arch: Optional[str],
    n_layers: Optional[int],
    source_repo_candidates: tuple = (),
    *,
    allow_network: Optional[bool] = None,
) -> Optional[list]:
    if not arch or not n_layers:
        return None
    if allow_network is None:
        allow_network = os.environ.get("UNSLOTH_STUDIO_OFFLINE", "0") not in (
            "1",
            "true",
            "True",
            "yes",
        )

    cache = _load_swa_cache()

    def _entry_to_mask(entry):
        if isinstance(entry, int) and entry > 0:
            return [(i + 1) % entry != 0 for i in range(n_layers)]
        if isinstance(entry, list) and entry:
            return [bool(entry[i % len(entry)]) for i in range(n_layers)]
        return None

    def _persist(entry):
        with _SWA_CACHE_LOCK:
            cache[arch] = entry
        _save_swa_cache(cache)

    if (entry := cache.get(arch)) is not None:
        if (mask := _entry_to_mask(entry)) is not None:
            return mask

    if (entry := _BOOTSTRAP_SWA_DEFAULTS.get(arch)) is not None:
        return _entry_to_mask(entry)

    entry = _resolve_swa_entry_from_transformers(arch)
    if entry is not None:
        _persist(entry)
        return _entry_to_mask(entry)

    # Tier 3: live HF fetch (result persistently cached)
    if allow_network:
        for repo_id in source_repo_candidates:
            if not repo_id:
                continue
            entry = _fetch_swa_entry_from_hf(repo_id)
            if entry is not None:
                _persist(entry)
                return _entry_to_mask(entry)

    return None


def _hf_repo_from_url(url: Optional[str]) -> Optional[str]:
    """Strip `https://huggingface.co/owner/name(/...)` -> `owner/name`."""
    if not url or "huggingface.co/" not in url:
        return None
    tail = url.split("huggingface.co/", 1)[1].rstrip("/")
    parts = tail.split("/")
    if len(parts) < 2:
        return None
    return f"{parts[0]}/{parts[1]}"


# Lazy import to avoid pulling transformers in at module level.
def _extract_model_size_b(model_id: str):
    from utils.models import extract_model_size_b
    return extract_model_size_b(model_id)


_TOOL_TEMPLATE_MARKERS = (
    "{%- if tools %}",
    "{%- if tools -%}",
    "{% if tools %}",
    "{% if tools -%}",
    # Defensive templates guard with `tools is defined` before truth-testing
    # (e.g. Inkling: `{%- if tools is defined and tools -%}`).
    "{%- if tools is defined",
    "{% if tools is defined",
    '"role" == "tool"',
    "'role' == 'tool'",
    'message.role == "tool"',
    "message.role == 'tool'",
    # DeepSeek: no top-level ``{% if tools %}`` block; it gates emission on
    # ``message['role'] == 'tool'`` plus ``message['tool_calls'] is defined``.
    "message['role'] == 'tool'",
    'message["role"] == "tool"',
    "message['tool_calls']",
    'message["tool_calls"]',
    "tool_calls is defined",
)


# Canonical reasoning_effort levels, weakest -> strongest. Used to read the
# discrete set a template branches on (e.g. GLM-5.2 uses 'high' | 'max', Inkling
# uses the full 'none'..'max' ladder) so we only ever offer levels the template
# actually understands.
_REASONING_EFFORT_SCALE = ("none", "minimal", "low", "medium", "high", "xhigh", "max")

# Match a Qwen3.8 path/repo segment without treating future names such as
# Qwen3.80 as part of the family. Official ids continue after the version with
# a dash (for example Qwen3.8-27B-GGUF).
_QWEN38_MODEL_RE = re.compile(r"(?:^|[^a-z0-9])qwen3\.8(?:$|[-_/\\])", re.IGNORECASE)


def _extract_reasoning_effort_levels(chat_template: str) -> list:
    """Return the reasoning_effort levels a template references, in canonical
    (weakest -> strongest) order.

    Looks for the quoted literals (e.g. ``'high'`` / ``"max"``) the template
    compares ``reasoning_effort`` against, so we surface exactly the levels it
    branches on and nothing else.
    """
    return [
        level
        for level in _REASONING_EFFORT_SCALE
        if f"'{level}'" in chat_template or f'"{level}"' in chat_template
    ]


def detect_reasoning_flags(
    chat_template: Optional[str],
    model_identifier: Optional[str] = None,
    *,
    log_source: Optional[str] = None,
) -> dict:
    """Classify a chat template's reasoning and tool-calling capabilities.

    Returns the same seven keys as the GGUF sniffer: ``supports_reasoning``,
    ``reasoning_style`` (``"enable_thinking"`` | ``"reasoning_effort"`` |
    ``"enable_thinking_effort"``), ``reasoning_always_on``,
    ``reasoning_effort_levels``, ``supports_preserve_thinking``,
    ``preserve_thinking_default``, ``supports_tools``. A falsy
    ``chat_template`` yields the all-default dict.
    Used by both the llama-server backend at load time and the
    safetensors/transformers paths in ``routes/inference`` so they agree on
    what the frontend sees.
    """
    flags = {
        "supports_reasoning": False,
        "reasoning_style": "enable_thinking",
        "reasoning_always_on": False,
        "reasoning_effort_levels": [],
        "supports_preserve_thinking": False,
        "preserve_thinking_default": False,
        "supports_tools": False,
    }
    if not chat_template:
        return flags
    tpl = chat_template
    prefix = f"{log_source}: " if log_source else ""

    # 'none' is this style's disable sentinel, not an effort level: the off
    # switch is enable_thinking=false, and the Think menu already hides it.
    # Left in, it is the weakest level, so a stored effort the model does not
    # offer clamps onto it and silently disables thinking (Kimi-K3).
    effort_levels = (
        [lv for lv in _extract_reasoning_effort_levels(tpl) if lv != "none"]
        if ("reasoning_effort" in tpl and "enable_thinking" in tpl)
        else []
    )
    if effort_levels:
        # DeepSeek-V4's encoder accepts reasoning_effort {'high', 'max'} but its
        # template only branches on 'max', so the literal scan misses 'high'. Add it
        # (matched on whole repo-name segments, so 'deepseek-v40' won't false-match)
        # to expose the full high/max ladder instead of max alone.
        segments = re.split(r"[-_.]", (model_identifier or "").lower().split("/")[-1])
        is_dsv4 = "deepseek4" in segments or any(
            a == "deepseek" and b == "v4" for a, b in zip(segments, segments[1:])
        )
        if is_dsv4 and "high" not in effort_levels:
            effort_levels = sorted(set(effort_levels) | {"high"}, key = _REASONING_EFFORT_SCALE.index)
        # GLM-5.2-style: an enable_thinking on/off gate PLUS a reasoning_effort
        # level among a discrete set (e.g. 'high' | 'max'). Distinct from
        # gpt-oss (reasoning_effort only, no on/off gate) and Qwen
        # (enable_thinking only). Disabling is enable_thinking=false; the levels
        # are the quoted effort literals the template actually branches on.
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "enable_thinking_effort"
        flags["reasoning_effort_levels"] = effort_levels
        logger.info(
            f"{prefix}model supports reasoning "
            f"(enable_thinking + reasoning_effort: {effort_levels})"
        )
    elif "enable_thinking" in tpl:
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "enable_thinking"
        logger.info(f"{prefix}model supports reasoning (enable_thinking)")
    elif "reasoning_effort" in tpl:
        # gpt-oss / Harmony use reasoning_effort
        # ("low" | "medium" | "high"), not a boolean. Inkling maps a wider
        # named ladder ('none'..'max'); surface the levels the template
        # actually branches on so the Think menu offers exactly those and
        # nothing more ('none' renders as thinking off: effort 0). Guard:
        # trust the scan only when it includes the core 'low' and 'high'
        # literals, so a template that quotes e.g. 'none' for an unrelated
        # comparison keeps the default low/medium/high set.
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "reasoning_effort"
        scanned = _extract_reasoning_effort_levels(tpl)
        if "low" in scanned and "high" in scanned:
            flags["reasoning_effort_levels"] = scanned
        logger.info(
            f"{prefix}model supports reasoning "
            f"(reasoning_effort: {flags['reasoning_effort_levels'] or 'default levels'})"
        )
    elif "thinking" in tpl:
        # DeepSeek uses 'thinking', not 'enable_thinking'
        normalized_id = (model_identifier or "").lower()
        if "deepseek" in normalized_id:
            flags["supports_reasoning"] = True
            logger.info(f"{prefix}model supports reasoning (DeepSeek thinking)")

    # Hardcoded <think> tags or reasoning_content in the template mean
    # thinking is always on (no toggle).
    if not flags["supports_reasoning"]:
        if ("<think>" in tpl and "</think>" in tpl) or "reasoning_content" in tpl:
            flags["supports_reasoning"] = True
            flags["reasoning_always_on"] = True
            logger.info(f"{prefix}model always reasons (<think> tags in template)")

    # preserve_thinking: independent kwarg on some Qwen templates that
    # keeps historical <think> blocks in prior assistant turns.
    if "preserve_thinking" in tpl:
        flags["supports_preserve_thinking"] = True
        # Qwen3.8 deliberately changed the family default from the off behavior
        # used by Qwen3.6 and Gemma 4. Keep the product override family-scoped:
        # other templates that happen to expose the same kwarg stay off.
        flags["preserve_thinking_default"] = bool(_QWEN38_MODEL_RE.search(model_identifier or ""))
        logger.info(f"{prefix}model supports preserve_thinking")

    if any(marker in tpl for marker in _TOOL_TEMPLATE_MARKERS):
        flags["supports_tools"] = True
        logger.info(f"{prefix}model supports tool calling")

    return flags


# Gemma 4 ships MTP as a separate drafter (no "-mtp" in the name). Gemma 3n
# ships no drafter, so it is excluded -- it takes the normal non-MTP path.
_GEMMA_MTP_FAMILY_RE = re.compile(r"gemma[-_]?4[-_]", re.IGNORECASE)


def _is_gemma_mtp_family(name: Optional[str]) -> bool:
    """Match Gemma 4 by name."""
    return bool(name) and bool(_GEMMA_MTP_FAMILY_RE.search(name))


def _is_gemma_mtp_name(model_identifier: Optional[str], gguf_path: Optional[str] = None) -> bool:
    """Match Gemma 4 by id or GGUF filename."""
    return _is_gemma_mtp_family(model_identifier) or _is_gemma_mtp_family(
        Path(gguf_path).name if gguf_path else None
    )


def _is_mtp_model_name(model_identifier: Optional[str], gguf_path: Optional[str] = None) -> bool:
    """Name-based MTP detector. Fallback for the metadata signal."""
    for cand in (model_identifier, Path(gguf_path).name if gguf_path else None):
        if cand and "-mtp" in cand.lower():
            return True
        # Recognise Gemma 4 too, so a failed drafter download surfaces a
        # fallback reason instead of silently defaulting.
        if cand and _is_gemma_mtp_family(cand):
            return True
    return False


# Mirrors hub.utils.gguf._DRAFTER_KINDS / _DRAFTER_DIR_KINDS.
_DRAFTER_KINDS = ("mtp", "dspark", "dflash")
_DRAFTER_DIR_KINDS = ("mtp", "dspark")

# Human label per resolved spec mode, for launch logging and the UI notice.
_DRAFTER_DISPLAY_LABELS = {"dspark": "DSpark", "dflash": "DFlash"}


def _drafter_path_kind(path: str) -> Optional[str]:
    """Drafter kind naming *path*: basename prefix, or exact parent dir for
    ``_DRAFTER_DIR_KINDS``. Never a substring: the kind names double as family
    names, so ``Qwen3.6-35B-A3B-DFlash-Q4_K_M.gguf`` IS the model, as is anything
    in a user's ``dflash/`` folder."""
    p = path.replace("\\", "/").lower()
    if not p.endswith(".gguf"):
        return None
    parts = [segment for segment in p.split("/") if segment]
    name, parents = parts[-1], parts[:-1]
    for kind in _DRAFTER_KINDS:
        if name.startswith(f"{kind}-"):
            return kind
    for kind in _DRAFTER_DIR_KINDS:
        if kind in parents:
            return kind
    return None


_IMATRIX_TOKEN_RE = re.compile(r"^imatrix(?:[._\-]|$)|[._\-]imatrix$", re.IGNORECASE)


def _is_companion_gguf_path(path: str) -> bool:
    """True for a non-main GGUF: vision mmproj, a calibration imatrix, or a separate
    drafter (repo-root ``mtp-*.gguf``, the ``MTP/`` subdir copies for Gemma 4, the ``dspark/``
    drafters for DeepSeek V4 Flash). Mirrors hub.utils.gguf so variant resolution
    never picks a companion as the main model -- a Gemma ``Q8_0`` request must not
    resolve to ``MTP/...-Q8_0-MTP.gguf``, which sorts ahead of the real weight.

    EXCLUSION ONLY. Use ``_is_mtp_only_drafter_path`` to pick a drafter to launch.
    """
    p = path.lower()
    if not p.endswith(".gguf"):
        return False
    if "mmproj" in p:
        return True
    # Mirrors hub.utils.gguf.is_imatrix_filename: an imatrix is a valid GGUF container
    # holding calibration statistics, so only the name rules it out.
    if _IMATRIX_TOKEN_RE.search(Path(p).stem):
        return True
    return _drafter_path_kind(path) is not None


def _is_mtp_only_drafter_path(path: str) -> bool:
    """MTP only, not the other companion GGUFs. Each drafter kind needs its own
    ``--spec-type``, so discovery narrows to one kind rather than reusing the
    broad companion predicate, which exists to EXCLUDE companions from menus."""
    return _drafter_path_kind(path) == "mtp"


def _is_dspark_drafter_path(path: str) -> bool:
    """True for a DSpark sidecar, excluding the separate DFlash method.

    Broader than model_config.detect_dspark_file, which additionally requires a
    published drafter NAME: a repo's ``dspark/`` directory holds only sidecars,
    while a user's local folder may hold anything. Only ever used against repo
    listings and cache snapshots for that reason.
    """
    return _drafter_path_kind(path) == "dspark"


def _is_dflash_drafter_path(path: str) -> bool:
    """True for a DFlash sidecar, excluding the separate DSpark method.

    Prefix only: ``dflash`` doubles as a family name a publisher puts on real
    weights, so ``Qwen3.6-35B-A3B-DFlash-Q4_K_M.gguf`` IS the model, and a
    user's ``dflash/`` folder holds whatever they put there (``dflash`` is
    absent from ``_DRAFTER_DIR_KINDS`` for that reason). Only a root-level
    ``dflash-*.gguf`` names a sidecar.

    Broader than model_config.detect_dflash_file, which additionally confirms
    ``general.architecture = dflash`` in the header. Only ever used against repo
    listings and cache snapshots, where a header read is not available.
    """
    return _drafter_path_kind(path) == "dflash"


def _is_root_dflash_drafter_path(path: str) -> bool:
    """A DFlash sidecar as a repo listing or cache snapshot offers one: the
    ``dflash-`` prefix AND the repository root.

    _is_dflash_drafter_path tests the basename, which is all its other callers
    have (a bare filename carries no parent to look at). Remote discovery does
    have the repository-relative path, and needs it: the local contract is root
    level only, so ``quants/dflash-model-Q8_0.gguf`` is an ordinary weight that
    detect_dflash_file would never offer. Going by basename there made it a
    candidate, and since the header can only be read once the bytes are here,
    the whole weight was downloaded before the rejection.

    Checked here rather than inside the basename predicate so the prefix-only
    naming rule stays exactly as it is for the callers that share it.
    """
    normalized = path.replace("\\", "/")
    return "/" not in normalized and _is_dflash_drafter_path(normalized)


_BIG_ENDIAN_GGUF_FILENAME_RE = re.compile(r"(^|[-_])be(?:[._-]|$)", re.IGNORECASE)
_GGUF_KNOWN_QUANT_RE = re.compile(
    r"(UD-)?"
    r"(MXFP[0-9]+(?:_[A-Z0-9]+)*"
    r"|IQ[0-9]+_[A-Z]+(?:_[A-Z0-9]+)?"
    r"|TQ[0-9]+_[0-9]+"
    r"|Q[0-9]+_K_[A-Z]+"
    r"|Q[0-9]+_[0-9]+"
    r"|Q[0-9]+_K"
    r"|BF16|F16|F32)",
    re.IGNORECASE,
)


def _is_big_endian_gguf_path(path: str, variant_key: str = "") -> bool:
    normalized = path.replace("\\", "/")
    name = normalized.rsplit("/", 1)[-1]
    stem = name.rsplit(".", 1)[0].lower()
    variant_key = variant_key.strip().lower()
    variant_index = stem.find(variant_key) if variant_key else -1
    parent = normalized.rsplit("/", 1)[0].lower() if "/" in normalized else ""
    variant_in_parent_only = (
        bool(parent)
        and variant_index < 0
        and (
            (variant_key and variant_key in parent)
            or (not variant_key and _GGUF_KNOWN_QUANT_RE.search(parent) is not None)
        )
    )
    for match in _BIG_ENDIAN_GGUF_FILENAME_RE.finditer(stem):
        if variant_index >= 0 and variant_index < match.start():
            return True
        tail = stem[match.end() :].lstrip("._-")
        if not tail or _GGUF_KNOWN_QUANT_RE.search(tail) is None:
            return not variant_in_parent_only
    return False


def _gguf_snapshot_files(snapshot: Path) -> list[str]:
    return [
        p.relative_to(snapshot).as_posix()
        for p in snapshot.rglob("*")
        if p.is_file() and p.name.lower().endswith(".gguf") and not is_appledouble_metadata(p)
    ]


def _cached_hf_snapshot_file(
    repo_id: str,
    filename: str,
    *,
    expected_size: Optional[int] = None,
    cache_dir: Optional[str] = None,
) -> Optional[str]:
    """Return a cached snapshot file even when HF's current-ref probe misses it."""
    if not filename:
        return None
    parts = [part for part in filename.replace("\\", "/").split("/") if part]
    if not parts or any(part in (".", "..") for part in parts):
        return None
    try:
        if cache_dir is None:
            from utils.models.model_config import _iter_hf_cache_snapshots
            snapshots = _iter_hf_cache_snapshots(repo_id)
        else:
            from hub.utils.hf_cache_state import iter_active_repo_cache_dirs
            snapshots = (
                snapshot
                for repo_dir in iter_active_repo_cache_dirs(
                    "model",
                    repo_id,
                    root = Path(cache_dir),
                )
                for snapshot in (repo_dir / "snapshots").glob("*")
                if snapshot.is_dir()
            )
        for snap in snapshots:
            candidate = snap.joinpath(*parts)
            if not candidate.is_file():
                continue
            if expected_size:
                try:
                    if candidate.stat().st_size < expected_size:
                        continue
                except OSError:
                    continue
            return str(candidate)
    except Exception as e:
        logger.debug("Snapshot cache lookup failed for %s/%s: %s", repo_id, filename, e)
    return None


def _snapshot_has_all_shards(
    main_path: str, main_filename: str, shards: Iterable[str], expected_sizes: dict[str, int]
) -> bool:
    """True when every shard sits beside ``main_path`` in the same cache snapshot.

    llama.cpp loads a split GGUF by resolving its siblings from the main shard's
    directory, so a cached main shard is only safe to reuse when the rest of the
    set is co-located; otherwise the caller must fetch the whole set together.
    """
    root = Path(main_path)
    for _ in [part for part in main_filename.replace("\\", "/").split("/") if part]:
        root = root.parent
    for shard in shards:
        parts = [part for part in shard.replace("\\", "/").split("/") if part]
        if not parts or any(part in (".", "..") for part in parts):
            return False
        sibling = root.joinpath(*parts)
        try:
            if not sibling.is_file():
                return False
            expected = expected_sizes.get(shard)
            if expected and sibling.stat().st_size < expected:
                return False
        except OSError:
            return False
    return True


def _resolve_repo_id_casing(hf_repo: str) -> str:
    """Map a requested repo id to its cached canonical casing, or return it unchanged.

    A case-variant request (for example a lowercased id) resolves to the
    canonical-cased cache directory so the main GGUF and its companions
    (mmproj / MTP drafter) all read the same cache entry. Returns ``hf_repo``
    unchanged when resolution is unavailable or errors.
    """
    try:
        from utils.paths import resolve_cached_repo_id_case
        return resolve_cached_repo_id_case(hf_repo)
    except Exception:
        return hf_repo


def _cached_colocated_split_main(
    repo_id: str, main_filename: str, shards: Iterable[str], expected_sizes: dict[str, int]
) -> Optional[str]:
    """Main-shard path from a cache snapshot that also holds every sibling shard.

    A newer snapshot may hold only the first shard while an older snapshot has the
    complete split set. ``_cached_hf_snapshot_file`` would return that newer partial
    main and the co-location check would then force a refetch, so scan snapshots for
    one where the whole set is present and return that main path instead. None when
    no snapshot holds the full set.
    """
    main_parts = [part for part in main_filename.replace("\\", "/").split("/") if part]
    if not main_parts or any(part in (".", "..") for part in main_parts):
        return None
    try:
        from utils.models.model_config import _iter_hf_cache_snapshots
        for snap in _iter_hf_cache_snapshots(repo_id):
            main_path = snap.joinpath(*main_parts)
            if not main_path.is_file():
                continue
            expected_main = expected_sizes.get(main_filename)
            try:
                if expected_main and main_path.stat().st_size < expected_main:
                    continue
            except OSError:
                continue
            if _snapshot_has_all_shards(str(main_path), main_filename, shards, expected_sizes):
                return str(main_path)
    except Exception as e:
        logger.debug("Co-located split snapshot lookup failed for %s: %s", repo_id, e)
    return None


def _cached_variant_resolution(repo_id: str, hf_variant: str) -> tuple[Optional[str], list[str]]:
    """Find a cached main GGUF and its shards for a variant."""
    candidate = next(_cached_variant_candidates(repo_id, hf_variant), None)
    if candidate is None:
        return None, []
    _, main, shards, _ = candidate
    return main, shards


def _cached_variant_candidates(
    repo_id: str,
    hf_variant: str,
    *,
    require_mmproj: bool = False,
) -> Generator[tuple[str, str, list[str], Path], None, None]:
    """Yield complete cached variant copies in snapshot preference order."""
    try:
        from utils.models.model_config import _iter_hf_cache_snapshots
        for snap in _iter_hf_cache_snapshots(repo_id):
            cached_files = _gguf_snapshot_files(snap)
            matches = _gguf_files_for_variant(cached_files, hf_variant)
            if not matches:
                continue
            main = matches[0]
            shards = _gguf_extra_shards(matches, main)
            split = _SHARD_FULL_RE.match(main)
            if split:
                numbers = {
                    int(match.group(2))
                    for path in [main, *shards]
                    if (match := _SHARD_FULL_RE.match(path))
                }
                if numbers != set(range(1, int(split.group(3)) + 1)):
                    continue
            main_path = snap.joinpath(*main.replace("\\", "/").split("/"))
            if not main_path.is_file() or not _snapshot_has_all_shards(
                str(main_path), main, shards, {}
            ):
                continue
            if require_mmproj and not _pick_mmproj(cached_files):
                continue
            yield str(main_path), main, shards, snap
    except Exception as e:
        logger.debug(f"Cache lookup for variant failed: {e}")


def _cached_variant_sizes(
    repo_id: str, hf_variant: str, main_path: str
) -> Optional[tuple[tuple[str, int], ...]]:
    """Sorted ``(filename, size)`` pairs for the cached variant copy at ``main_path``.

    None when no complete cached copy resolves to that path. ``_cached_variant_candidates``
    owns the shard set and every read is local, so recording this and comparing it later
    catches a truncated, resized or dropped file without a Hub lookup.
    """
    target = os.path.abspath(main_path)
    for cached_main, main, shards, snap in _cached_variant_candidates(repo_id, hf_variant):
        if os.path.abspath(cached_main) != target:
            continue
        try:
            return tuple(
                sorted(
                    (name, os.path.getsize(snap.joinpath(*name.replace("\\", "/").split("/"))))
                    for name in (main, *shards)
                )
            )
        except OSError:
            return None
    return None


def _cached_candidate_matches_revision_size(
    repo_id: str, candidate: tuple[str, str, list[str], Path], hf_token: Optional[str]
) -> bool:
    """Check cached byte sizes against the snapshot's own Hub revision.

    A snapshot pointer is normally published only after its blob is complete.
    When the old revision is still queryable, also compare every weight file's
    size so a manually truncated cache entry is not treated as reusable. If
    metadata cannot be reached, retain the cache's normal offline semantics.
    """
    main_path, main, shards, snap = candidate
    paths = [main, *shards]
    try:
        from huggingface_hub import get_paths_info
        infos = list(
            get_paths_info(
                repo_id,
                paths,
                revision = snap.name,
                token = hf_token,
            )
        )
    except Exception as e:
        logger.debug(
            "Could not size-check cached GGUF %s at revision %s: %s",
            repo_id,
            snap.name,
            e,
        )
        return True

    if not infos:
        # The Hub answers an unknown (e.g. force-pushed away) revision with an
        # empty result, not an error; treat it like unreachable metadata.
        return True
    expected_sizes = {info.path: info.size for info in infos if info.size is not None}
    if any(path not in expected_sizes for path in paths):
        return False
    try:
        if os.path.getsize(main_path) < expected_sizes[main]:
            return False
    except OSError:
        return False
    return _snapshot_has_all_shards(main_path, main, shards, expected_sizes)


def _cached_complete_candidate(
    repo_id: str, gguf_filename: Optional[str], shards: list[str]
) -> Optional[tuple[str, str, list[str], Path]]:
    """Return one complete exact-filename cache candidate with snapshot context."""
    if not gguf_filename:
        return None
    if shards:
        main_path = _cached_colocated_split_main(repo_id, gguf_filename, shards, {})
    else:
        m = _SHARD_FULL_RE.match(gguf_filename)
        if m and int(m.group(3)) > 1:
            return None
        main_path = _cached_hf_snapshot_file(repo_id, gguf_filename)
    if main_path is None:
        return None
    snap = _snapshot_dir_of(main_path)
    if snap is None:
        return None
    return main_path, gguf_filename, shards, snap


def cached_gguf_for_load(
    hf_repo: str,
    hf_variant: Optional[str],
    *,
    require_mmproj: bool = False,
    verify_sizes: bool = False,
    hf_token: Optional[str] = None,
) -> Optional[str]:
    """Return a cached GGUF that can be loaded without downloading."""
    if not hf_variant:
        return None
    hf_repo = _resolve_repo_id_casing(hf_repo)
    for candidate in _cached_variant_candidates(
        hf_repo,
        hf_variant,
        require_mmproj = require_mmproj,
    ):
        if verify_sizes and not _cached_candidate_matches_revision_size(
            hf_repo, candidate, hf_token
        ):
            continue
        return candidate[0]
    return None


def _snapshot_dir_of(path: str) -> Optional[Path]:
    """Return the HF cache snapshot containing path, if any."""
    try:
        p = Path(os.path.abspath(path))
    except OSError:
        return None
    for ancestor in p.parents:
        if ancestor.parent.name == "snapshots":
            return ancestor
    return None


def _hub_cache_dir_for_snapshot_path(path: Optional[str]) -> Optional[str]:
    """Return the HF Hub cache root that owns a snapshot-contained path."""
    if not path:
        return None
    snapshot = _snapshot_dir_of(path)
    if snapshot is None or snapshot.parent.name != "snapshots":
        return None
    return str(snapshot.parent.parent.parent)


def _companion_snapshot_sibling(
    near_path: str, pick: Callable[[list[str]], Optional[str]]
) -> Optional[str]:
    """Find a companion in the same snapshot as near_path."""
    snap = _snapshot_dir_of(near_path)
    if snap is None:
        return None
    try:
        sibling = pick(_gguf_snapshot_files(snap))
    except Exception:
        return None
    if not sibling:
        return None
    candidate = snap / sibling
    if not candidate.is_file():
        return None
    # A split companion is usable only as a whole set (llama-server resolves the
    # siblings from this path's directory), so a snapshot holding shard 1 alone
    # is not a reuse -- reporting it would skip the download that completes it and
    # leave the load with a drafter the server cannot open. Same rule the local
    # scan applies. Non-split names are a complete one-file set, so this is a
    # no-op for every companion published today.
    from utils.models.model_config import _drafter_split_is_complete

    return str(candidate) if _drafter_split_is_complete(candidate) else None


def _pick_dspark(candidates: list[str]) -> Optional[str]:
    """The DSpark drafter a listing offers, or None. Module level for the same reason
    ``_pick_mmproj`` is: both are handed a live repo listing as well as a snapshot."""
    from hub.utils.gguf import drop_shadowed_appledouble_names
    from utils.models.model_config import dspark_preference_key

    # Every GGUF under dspark/ qualifies, so a sidecar ranks equal to its sibling and sorts first.
    files = sorted(
        (
            name
            for name in drop_shadowed_appledouble_names(list(candidates))
            if _is_dspark_drafter_path(name)
        ),
        key = dspark_preference_key,
    )
    return files[0] if files else None


def _pick_mtp(candidates: list[str]) -> Optional[str]:
    """The MTP drafter a listing offers, or None. Module level for the same reason
    ``_pick_dspark`` is: both are handed a live repo listing as well as a snapshot,
    and ``/kv-cache-estimate`` has to price the drafter the launch will open."""
    # Root-level only: MTP/ subdir copies now share the mtp- prefix but
    # are explicit-selection, not auto-fetch (they'd sort ahead of root).
    # The mtp- prefix also excludes AppleDouble shadows ("._mtp-x.gguf"), which
    # is why this picker needs no drop_shadowed_appledouble_names of its own.
    mtp_files = sorted(
        f
        for f in candidates
        if f.lower().endswith(".gguf") and "/" not in f and Path(f).name.lower().startswith("mtp-")
    )
    return mtp_files[0] if mtp_files else None


def _pick_mmproj(candidates: list[str]) -> Optional[str]:
    from hub.utils.gguf import drop_shadowed_appledouble_names

    # "._mmproj-F16.gguf" satisfies the F16 preference and sorts ahead of the real adapter.
    candidates = drop_shadowed_appledouble_names(list(candidates))
    mmproj_files = sorted(
        f for f in candidates if f.lower().endswith(".gguf") and "mmproj" in Path(f).name.lower()
    )
    if not mmproj_files:
        return None
    return next((f for f in mmproj_files if f.lower().endswith("-f16.gguf")), mmproj_files[0])


def _hub_download_in_flight(hf_repo: str) -> bool:
    try:
        from hub.utils.download_registry import get_models_registry
        return bool(get_models_registry().active_job_refs(hf_repo))
    except Exception:
        return False


def _hub_download_blocks_gguf_load(
    hf_repo: str,
    hf_variant: Optional[str],
    *,
    require_mmproj: bool = False,
    hf_token: Optional[str] = None,
) -> bool:
    """Whether an active Hub job makes this GGUF load unsafe.

    Same-variant jobs can reclaim the stale snapshot a load would reuse, so
    they always block. Other jobs block only when this load lacks a complete
    cached copy and would write to the shared cache itself.
    """
    try:
        from hub.utils.download_registry import get_models_registry

        registry = get_models_registry()
        if not registry.active_job_refs(hf_repo):
            return False
        if registry.has_active_variant(hf_repo, hf_variant):
            return True
    except Exception:
        return False
    return (
        cached_gguf_for_load(
            hf_repo,
            hf_variant,
            require_mmproj = require_mmproj,
            verify_sizes = True,
            hf_token = hf_token,
        )
        is None
    )


# Active GGUF loads by normalized repo ID.
_LOADS_IN_FLIGHT: dict[str, int] = {}
_LOADS_IN_FLIGHT_LOCK = threading.Lock()


@contextlib.contextmanager
def gguf_load_in_flight(hf_repo: Optional[str]):
    """Track an HF GGUF load until the context exits."""
    key = (hf_repo or "").strip().lower()
    if not key:
        yield
        return
    with _LOADS_IN_FLIGHT_LOCK:
        _LOADS_IN_FLIGHT[key] = _LOADS_IN_FLIGHT.get(key, 0) + 1
    try:
        yield
    finally:
        with _LOADS_IN_FLIGHT_LOCK:
            remaining = _LOADS_IN_FLIGHT.get(key, 1) - 1
            if remaining <= 0:
                _LOADS_IN_FLIGHT.pop(key, None)
            else:
                _LOADS_IN_FLIGHT[key] = remaining


# Chat loads in flight, repo-agnostic (local paths and safetensors included). The repo-keyed counter above answers the download manager; this one answers the GPU arbiter, which must know before llama-server spawns.
_CHAT_LOADS_IN_FLIGHT = 0


@contextlib.contextmanager
def chat_load_in_flight():
    """Track a chat load from before its download until the load call returns."""
    global _CHAT_LOADS_IN_FLIGHT
    with _LOADS_IN_FLIGHT_LOCK:
        _CHAT_LOADS_IN_FLIGHT += 1
    try:
        yield
    finally:
        with _LOADS_IN_FLIGHT_LOCK:
            _CHAT_LOADS_IN_FLIGHT = max(0, _CHAT_LOADS_IN_FLIGHT - 1)


def chat_load_active() -> bool:
    """Whether a chat load is in flight, spawned or not.

    ``is_active`` only covers a live llama-server process, which an HF load does not have
    until its GGUF finished downloading -- minutes during which the arbiter's evictor would
    find nothing to cancel and grant the GPU to a second workload.
    """
    with _LOADS_IN_FLIGHT_LOCK:
        return _CHAT_LOADS_IN_FLIGHT > 0


def zero_vram_chat_load(
    gpu_memory_mode: str,
    gpu_layers: int,
    extra_args: Optional[list] = None,
    needs_mmproj: bool = False,
    speculative_type: Optional[str] = None,
) -> bool:
    """Whether a GGUF load will hold no VRAM at all, decided from the request.

    A deliberate manual zero-offload load runs on the CPU and is launched with the GPUs hidden
    from the child (see ``_cpu_only_zero_offload``), so it neither needs the GPU arbiter nor
    should evict an image/video pipeline for it. This mirrors that launch-time mask so both
    agree: an mmproj, a GPU drafter, a device pin or a surviving tensor mode all keep the GPUs
    visible, and the mask is skipped on Vulkan. ``--mmproj`` and ``--model-draft`` are added by
    the backend rather than being present in ``extra_args``, so their intent is passed in.
    """
    if gpu_memory_mode != "manual" or gpu_layers != 0:
        return False
    # Any speculative mode may launch a GPU drafter and only the request's own knobs are known here, so treat every selection as GPU-bearing except
    # "off". Canonicalize first: the UI sends the literal "off", which a bare truthiness test read as "speculation requested".
    # ...and an ABSENT mode is not a quiet "off": every consumer resolves None to
    # "auto", where a sidecar can still be discovered and GPU-offloaded. Grouping None
    # with "off" let a defaulted load skip acquire_for(CHAT) while the launch-time mask
    # -- reading the FINISHED argv, drafter included -- kept the GPUs visible: no
    # arbiter, real VRAM, free to OOM a resident image pipeline.
    spec_mode = _canonicalize_spec_mode(speculative_type) or "auto"
    if needs_mmproj or spec_mode != "off":
        return False
    if LlamaCppBackend._is_vulkan_backend():
        return False
    return not LlamaCppBackend._zero_offload_keeps_gpu_visible(
        [str(arg) for arg in (extra_args or [])], os.environ
    )


def hf_gguf_load_in_flight(hf_repo: str) -> bool:
    """Return whether a GGUF load is active for hf_repo."""
    key = (hf_repo or "").strip().lower()
    if not key:
        return False
    with _LOADS_IN_FLIGHT_LOCK:
        return _LOADS_IN_FLIGHT.get(key, 0) > 0


def _with_gguf_load_marker(load: Callable):
    """Keep an HF repo marked for the full synchronous load call."""

    @functools.wraps(load)
    def wrapped(
        self,
        intent: GgufLoadIntent,
        load_cancel_event: Optional[threading.Event] = None,
    ):
        hf_repo = intent.hf_repo
        with gguf_load_in_flight(hf_repo):
            if hf_repo and _hub_download_blocks_gguf_load(
                hf_repo,
                intent.hf_variant,
                # Mirrors the download gate below EXACTLY, which is the whole point:
                # this load fetches the projector whenever the repo ships one and the
                # extras have not opted out, switch or no switch, because only the
                # file's metadata says whether it is an image tower or an audio
                # encoder. So the switch must not relax the interlock here. It did
                # briefly, and the two together let a vision-off load skip the 409 and
                # then write into the shared Hub cache next to a running download job,
                # which is the race this check exists to stop.
                require_mmproj = bool(
                    intent.is_vision and not extra_args_disable_mmproj(intent.extra_args)
                ),
                hf_token = intent.hf_token,
            ):
                raise RuntimeError(
                    f"'{hf_repo}' is currently being downloaded by the download manager"
                )
            return load(self, intent, load_cancel_event = load_cancel_event)

    return wrapped


def _drafter_set_bytes(sizes: Mapping[str, int], name: str) -> int:
    """Total listed bytes of ``name``'s whole shard set (its own size when single)."""
    return (sizes.get(name, 0) or 0) + sum(
        sizes.get(shard, 0) or 0 for shard in _gguf_extra_shards(sizes, name)
    )


def _gguf_extra_shards(files: Iterable[str], first_shard: str) -> list[str]:
    m = _SHARD_FULL_RE.match(first_shard)
    if not m:
        return []
    prefix = m.group(1)
    total = m.group(3)
    sibling_pat = re.compile(
        r"^" + re.escape(prefix) + r"-\d{5}-of-" + re.escape(total) + r"\.gguf$",
        re.IGNORECASE,
    )
    return sorted(f for f in files if f != first_shard and sibling_pat.match(f))


def _quant_label_for_endian(path: str) -> Optional[str]:
    """The file's own quant label, for ``_is_big_endian_gguf_path``, or None when unreadable.

    Best-effort: with no label the caller keeps its previous argument rather than dropping the
    endian test, which would admit a genuinely big-endian build."""
    try:
        from hub.utils.gguf import extract_quant_token
        return extract_quant_token(path)
    except Exception:  # noqa: BLE001 -- an unreadable label must not sink the resolution
        return None


def _gguf_files_for_variant(files: Iterable[str], variant: str) -> list[str]:
    """Return main GGUF files matching a requested variant.

    Prefer exact quant-label matches over loose substring matches so a request
    for ``stories260K`` does not resolve to ``stories260K-be.gguf``.
    """
    from hub.utils.gguf import drop_shadowed_appledouble_names

    variant_key = variant.strip().lower()
    # A repo listing has no bytes to read; a local one arrives already filtered on its headers.
    main_files = [
        f
        for f in drop_shadowed_appledouble_names(list(files))
        if f.lower().endswith(".gguf")
        and not _is_companion_gguf_path(f)
        # The endian predicate reads a quant TOKEN -- it decides whether the quant came from the
        # parent directory only -- so it gets the file's own label, never the requested key. Handed
        # a path-qualified key it cannot find that string in either the basename or the parent and
        # reads distilled/Q4_K_M/foo-be.gguf as big-endian, dropping the one file the key owns:
        # the row is advertised and downloadable but never resolves for loading. Same reason
        # gguf_plan and the auto-download map pass the label here.
        and not _is_big_endian_gguf_path(f, _quant_label_for_endian(f) or variant_key)
    ]
    if not variant_key:
        return sorted(main_files)

    try:
        from utils.models.model_config import _extract_quant_label, _gguf_variant_key
    except Exception:
        _extract_quant_label = None
        _gguf_variant_key = None

    if _gguf_variant_key is not None:
        try:
            # The variant's own files first. In a repo holding several checkpoints at
            # one quant the label alone names all of them, and handing llama-server a
            # mixed set makes it read another checkpoint's weights as a shard.
            owned = sorted(f for f in main_files if _gguf_variant_key(f).lower() == variant_key)
            if owned:
                return owned
        except Exception as e:
            logger.warning("Failed to derive GGUF variant keys: %s", e)

    if _extract_quant_label is not None:
        try:
            exact = sorted(f for f in main_files if _extract_quant_label(f).lower() == variant_key)
            if exact:
                return exact
        except Exception as e:
            logger.warning("Failed to extract GGUF quant labels: %s", e)

    boundary = re.compile(r"(?<![a-zA-Z0-9])" + re.escape(variant_key) + r"(?![a-zA-Z0-9])")
    return sorted(f for f in main_files if boundary.search(f.lower()))


def _resolve_variant_gguf_files(
    hf_repo: str,
    hf_variant: Optional[str],
    hf_token: Optional[str] = None,
) -> tuple[Optional[str], list[str]]:
    """Which file in ``hf_repo`` this variant means, plus its extra shards.

    Repo listing, then the local HF cache, then a name synthesised from the repo id; every
    tier fails soft (``(None, [])`` means "no opinion"). Module level, not inside
    ``_download_gguf``, so the pre-teardown header probe resolves exactly the file the
    download will open -- two copies of this cascade would let the two drift.
    """
    gguf_filename: Optional[str] = None
    gguf_extra_shards: list[str] = []
    if not hf_variant:
        return None, []
    try:
        from huggingface_hub import list_repo_files

        files = list_repo_files(hf_repo, token = hf_token)
        gguf_files = _gguf_files_for_variant(files, hf_variant)
        if gguf_files:
            gguf_filename = gguf_files[0]
            gguf_extra_shards = _gguf_extra_shards(gguf_files, gguf_filename)
    except Exception as e:
        logger.warning(f"Could not list repo files: {e}")

    # Fall back to the local cache when the repo listing is unavailable.
    if not gguf_filename:
        cached_name, cached_shards = _cached_variant_resolution(hf_repo, hf_variant)
        if cached_name:
            gguf_filename = cached_name
            gguf_extra_shards = cached_shards
            logger.info(
                "Resolved variant %s -> %s from local HF cache",
                hf_variant,
                gguf_filename,
            )

    if not gguf_filename:
        repo_name = hf_repo.split("/")[-1].replace("-GGUF", "")
        gguf_filename = f"{repo_name}-{hf_variant}.gguf"
    return gguf_filename, gguf_extra_shards


# Below this many B params, draft-mtp regresses vs spec-off (bench in
# _build_speculative_flags); auto mode drops MTP under it.
_MTP_MIN_SIZE_B = 3.0

# Cap total GPU occupancy at this fraction of the card. The fit reserves an
# absolute (1 - frac) * total per GPU when total VRAM is known, else a fraction
# of free (see _fit_context_to_vram), plus a byte-accurate MTP draft reserve.
# 3%: the context-linear compute buffer is now modelled (_compute_buffer_ctx_bytes),
# so this cushion no longer covers it - only fragmentation, the per-device CUDA
# context on a multi-GPU split, and MoE routing, which measure ~2-3% (Qwen3.5-397B on
# 3 GPUs under-predicts by 2.7%). Below 3% one fragmentation spike overflows to CPU.
_CTX_FIT_VRAM_FRACTION = 0.97

# Apple unified memory is shared with the OS, so tighter than VRAM. Matches the
# 0.85 MLX uses in mlx_inference.py (_configure_memory_limits); not kept in sync.
_APPLE_UNIFIED_MEMORY_FRACTION = 0.85

# _fit_context_to_vram's floor: the shortest context the search will settle for, so a
# value equal to it is that floor rather than a measurement. The Metal branch re-prices
# from _FIT_FLOOR_MIN_CTX (the search's 256 alignment step) before trusting it.
#
# 8192, not llama.cpp's own 4096 (common_params.fit_params_min_ctx). 4096 is too short
# to be useful for chat once tools and a system prompt are in the window, and the fit
# search would settle there rather than spilling weights it could spill instead. The two
# floors are now deliberately different numbers: llama.cpp's still governs ITS fitter,
# and Unsloth does not pass -fitc, so a launch that hands llama.cpp an explicit -c can
# still be reduced below this by the child's own fit step.
#
# Every arm now floors here, Metal included. The Apple arm used to hold a separate
# hardcoded 4096, which made a Mac publish half the context a discrete GPU published
# for the same model. Being BELOW llama.cpp's own floor is what made that safe to
# raise: -c 8192 is a request the child's --fit can still reduce, down to its 4096,
# so the arm hands over a ceiling rather than a commitment. The one arm still on a
# bare 4096 is _plan_tensor_parallel's no-KV fallback, which cannot prove a safe cap
# at all and is a different question from this floor.
_FIT_MIN_CTX = 8192
_FIT_FLOOR_MIN_CTX = 256

# llama.cpp's OWN reduction floor: common_params.fit_params_min_ctx, 4096
# (common/common.h), the smallest context its --fit step will shrink a request to.
# Named because the paragraph above spends the whole justification for _FIT_MIN_CTX on
# it: -c 8192 is safe to hand a Mac only as a ceiling the child's fitter can still come
# down from, and this is how far down. A launch that hands over 8192 with the fitter
# NOT running has no such backstop, so it must hand over this number itself rather than
# the ceiling that assumed one.
_LLAMA_FIT_MIN_CTX = 4096

# Auto only reaches this path when no discrete-GPU subset can hold the model.
# llama.cpp must offload layers to host RAM either way, so prefer a context that
# remains useful for chat. Separate from _FIT_MIN_CTX: that value is also a search
# and Apple unified-memory safety floor.
_AUTO_OFFLOAD_CTX = 8192

# Keep this at or above the fit search floor. Not a style rule, a correctness one:
# the Auto offload branch re-checks whether a subset holds the model at the reduced
# context, and that re-check can only award residency BELOW the floor, since a subset
# winnable at or above it was already taken by the fit loop that runs first. Moving
# this constant is therefore free of placement changes only while it stays on the dead
# side of that floor. Below it the re-check hands over a device and flips --fit off,
# which is a placement decision rather than a display one.
#
# The floor in question is the ``min_ctx = 4096`` DEFAULT on _fit_context_to_vram and
# _cap_ctx_to_per_device_reserve, not _FIT_MIN_CTX: neither auto call site passes the
# argument, and _FIT_MIN_CTX is only handed in explicitly on the Apple arm. The three
# numbers agree today and nothing here makes them; test_auto_offload_ctx_invariants.py
# pins both defaults to _FIT_MIN_CTX and this constant above it, so the agreement
# cannot lapse silently.

# How far amd-smi's total VRAM may sit from HIP's before the two are reporting
# different memory scopes rather than one pool (an APU carve-out against the GTT
# pool, a partition against the whole card). Same 10% margin
# utils/hardware/hardware.py::_rocm_system_wide_vram_by_index gates its overlay on.
_AMD_SMI_TOTAL_TOLERANCE = 0.10

# Flat MTP reserve, used only when GGUF dims are too sparse for the byte-accurate
# reserve (_estimate_mtp_overhead_bytes). Applied to both the fit budget and pin.
_MTP_VRAM_RESERVE_FRAC = 0.05


# Left on every card even at 100%, matching the --fit-target margin llama.cpp
# keeps for its own fitter.
_VRAM_FLOOR_RESERVE_MIB = 512.0

# llama-server's own --fit-target default ("target margin per device for --fit,
# ... default: 1024"): what the fallback fitter leaves when we pass nothing.
_LLAMA_FIT_TARGET_DEFAULT_MIB = 1024.0


def _vram_reserve_floor_mib(total_mib: float) -> float:
    """Smallest margin a card keeps: 512 MiB, or the default's own reserve if smaller.

    Capping it at the default keeps the budget monotonic. A flat 512 MiB would
    RAISE the reserve the moment the slider passed the default on any card under
    about 17 GiB, where 3% is already less than that: an 8 GiB card offers 7946 MiB
    at 0.97 but only 7680 at 0.971, so nudging the slider up would hand back less
    context, the opposite of what the control promises. Capped, the reserve never
    rises with the fraction, and at or below the default the percentage term always
    wins, so an unset budget is untouched on every card size.
    """
    return min(_VRAM_FLOOR_RESERVE_MIB, (1.0 - _CTX_FIT_VRAM_FRACTION) * total_mib)


def _vram_usable_mib(
    free_mib: float,
    total_mib: float,
    frac: float,
    *,
    pooled: bool = False,
) -> float:
    """Free MiB one card offers a load at ``frac``, unclamped.

    ``pooled`` marks an already absolute budget summed over cards that have each
    paid their own reserve; charging it again would double count. Everything else
    is one device, including a probe reporting free memory with no total, which
    still has to keep a margin: there the free reading is the only scale available,
    and it agrees with the known-total form at the default.
    """
    if total_mib and total_mib > 0:
        reserve = max((1.0 - frac) * total_mib, _vram_reserve_floor_mib(total_mib))
        return free_mib - reserve
    if pooled:
        return free_mib * frac
    return min(free_mib * frac, free_mib - _vram_reserve_floor_mib(free_mib))


def _active_vram_fraction() -> float:
    """The user's VRAM budget, or ``_CTX_FIT_VRAM_FRACTION`` when they set none.

    The settings module clamps to a supported range and swallows a corrupt stored
    value, so this cannot widen the budget past 1.0 or hand back a NaN. Imported
    lazily to keep the settings/storage layer off this module's import path, and
    read per call so a change applies to the next load without a restart.
    """
    try:
        from utils.vram_budget_settings import get_vram_budget_fraction
        return get_vram_budget_fraction()
    except Exception:
        # Settings are a convenience; a load must never fail because of them.
        return _CTX_FIT_VRAM_FRACTION


def _kv_bytes_per_elem(cache_type: Optional[str]) -> float:
    """Bytes per KV-cache element for a llama.cpp cache type (f16 default)."""
    return {
        "f32": 4.0,
        "f16": 2.0,
        "bf16": 2.0,
        "q8_0": 34 / 32,
        "q5_1": 0.75,
        "q5_0": 0.6875,
        "q4_1": 0.625,
        "q4_0": 0.5625,
        "iq4_nl": 0.5625,
    }.get((cache_type or "f16").strip().lower(), 2.0)


def _pad_kv_cells(cells: int) -> int:
    return ((cells + 255) // 256) * 256


def _kv_cache_cell_layout(n_ctx: int, n_parallel: int, kv_unified: bool) -> tuple[int, int, int]:
    """Return llama.cpp's slot count, stream count, and cells per stream."""
    slots = max(1, n_parallel)
    padded_ctx = _pad_kv_cells(n_ctx)
    streams = 1 if kv_unified else slots
    if padded_ctx <= 0:
        return slots, streams, 0
    cells_per_stream = padded_ctx if kv_unified else _pad_kv_cells(padded_ctx // slots)
    return slots, streams, cells_per_stream


def _env_main_cache_type_for_budget(env: Optional[Mapping[str, str]] = None) -> Optional[str]:
    """Heavier (max bytes/elem) of the set LLAMA_ARG_CACHE_TYPE_K/_V env types
    when it budgets differently from the f16 default, else None. Unsloth emits
    --cache-type only for the param/extras path, so an env type would otherwise
    reach the child unbudgeted: f32 under-reserves the KV, and a quantized type
    skips the dequant compute scratch (on Inkling the dense fallback it forces
    dwarfs the banded rate). The caller adopts the type for the reserve only;
    _cache_type_from_env keeps it out of the emitted flags."""
    e = os.environ if env is None else env
    # An UNSET axis is not absent, it is llama.cpp's f16 default, so it joins the max.
    # Dropping it let a lone CACHE_TYPE_V=q4_0 return q4_0 and price K as q4 while the
    # child ran it at f16, under-reserving the larger tensor when key_length >
    # value_length -- and tensor mode has no --fit valve to absorb that.
    axis_types = [
        (e.get(var) or "").strip().lower() or "f16"
        for var in ("LLAMA_ARG_CACHE_TYPE_K", "LLAMA_ARG_CACHE_TYPE_V")
    ]
    if all(t == "f16" for t in axis_types):
        return None
    heaviest = max(axis_types, key = _kv_bytes_per_elem)
    if _kv_bytes_per_elem(heaviest) == _kv_bytes_per_elem("f16"):
        return None
    return heaviest


def _extra_args_main_cache_type_for_budget(extra_args: Optional[Iterable[str]]) -> Optional[str]:
    """Heavier (max bytes/elem) of the explicit --cache-type-k/-v extras, or None.

    Extras are appended last and win per axis, so an asymmetric K=f32,V=f16 must be
    budgeted by its heavier axis. resolve_cache_type_kv returns only the last-wins
    single type, which under-reserves the heavier axis when the lighter one is last."""
    k, v = parse_cache_override_per_axis(extra_args)
    candidates = [c for c in (k, v) if c]
    if not candidates:
        return None
    return max(candidates, key = _kv_bytes_per_elem)


def _effective_main_cache_types(
    args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> tuple[str, str]:
    """Effective main K/V cache types after environment and CLI precedence."""
    source_env = os.environ if env is None else env
    env_k = (source_env.get("LLAMA_ARG_CACHE_TYPE_K") or "f16").strip().lower()
    env_v = (source_env.get("LLAMA_ARG_CACHE_TYPE_V") or "f16").strip().lower()
    arg_k, arg_v = parse_cache_override_per_axis(args)
    return (
        (arg_k or env_k).strip().lower(),
        (arg_v or env_v).strip().lower(),
    )


def _planned_main_cache_types(
    cache_type_kv: Optional[str],
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
) -> tuple[str, str]:
    """Main K/V types the loader's managed flags and user extras will produce."""
    args = list(extra_args or ())
    emitted_type = _extra_args_main_cache_type_for_budget(args) or cache_type_kv
    if emitted_type:
        args = [
            "--cache-type-k",
            emitted_type,
            "--cache-type-v",
            emitted_type,
            *args,
        ]
    return _effective_main_cache_types(args, env)


# What kv_cache_type_from_str accepts, so the only types Unsloth emits. Module scope
# because the budget must know whether a type will reach the child before the command
# is assembled.
_VALID_CACHE_TYPES = frozenset(
    {"f16", "bf16", "q8_0", "q4_0", "q4_1", "q5_0", "q5_1", "iq4_nl", "f32"}
)


def _planned_scratch_cache_type(
    cache_type_kv: Optional[str],
    extra_args: Optional[Iterable[str]] = None,
    env: Optional[Mapping[str, str]] = None,
) -> str:
    """LIGHTEST planned axis: the type that decides the compute-buffer scratch rate.

    The KV-byte reserve takes the HEAVIER axis (max over _planned_main_cache_types),
    which is conservative for storage but hides a paired quantized axis -- an f16
    budget hides a q4_0 K. _compute_buffer_ctx_bytes charges the per-device dequant
    scratch only when its cache type is under f16, so handing it the heavier axis
    silently drops that scratch for an asymmetric pair. Taking the lighter axis here
    makes any quantized axis select the quantized rate, leaving the two terms
    independently conservative (heavier for bytes, lighter for scratch)."""
    return min(_planned_main_cache_types(cache_type_kv, extra_args, env), key = _kv_bytes_per_elem)


def _auto_mode_drops_mtp(
    req_mode: Optional[str],
    size_b: Optional[float],
    *,
    has_separate_drafter: bool = False,
) -> bool:
    """Auto mode drops MTP below _MTP_MIN_SIZE_B for an embedded draft head
    (its per-token cost regresses there); a separate drafter (Gemma) is a tiny
    standalone model that still speeds up below 3B, so it never drops. Forced
    mtp / mtp+ngram engage regardless of size."""
    if has_separate_drafter:
        return False
    return req_mode == "auto" and size_b is not None and size_b < _MTP_MIN_SIZE_B


def _mla_mtp_auto_enabled() -> bool:
    """Whether Auto may pick embedded MTP for an MLA model (GLM-5.2/DeepSeek/Kimi).

    Off by default: llama.cpp's MLA/DSA MTP path keeps a duplicated full target-KV
    context and recomputes the sparse-attention indexer every draft step, so it runs
    ~2x slower than no speculation (GLM-5.2 bench: 27 vs 45 tok/s, flat across draft
    depth and 96-100% acceptance) -- the opposite of the vLLM/SGLang speedup on the
    same model. Set UNSLOTH_MLA_MTP_ENABLED=1 to let Auto promote MLA MTP again once
    that path is optimized upstream. Forced mtp / mtp+ngram ignore this gate."""
    return os.environ.get("UNSLOTH_MLA_MTP_ENABLED", "0").strip().lower() in (
        "1",
        "true",
        "yes",
        "on",
    )


def _extra_args_set_spec_type(extra_args: Optional[Iterable[str]]) -> bool:
    """User passed --spec-type / --spec-default? llama-server takes one
    --spec-type (comma-separated to chain), so suppress auto-emit."""
    return _extra_args_set_any_flag(extra_args, {"--spec-type", "--spec-default"})


# Layer-offload override detection. Single-sourced from llama_server_args, which
# also strips these (plus the MoE flags) from inherited extras; sharing the layer
# set keeps detection and stripping from drifting.
_GPU_OFFLOAD_OVERRIDE_FLAGS = _LAYER_OFFLOAD_FLAGS
# Extras that keep weights on the CPU regardless of the layer count, so a
# full offload cannot be inferred from -ngl alone. -ncmoe carries a COUNT, and
# zero places nothing, so it is parsed rather than merely spotted; the rest are
# presence-only (-cmoe takes no value, and an -ot pattern is not worth guessing
# at, which matches how the env side reads LLAMA_ARG_OVERRIDE_TENSOR).
_CPU_MOE_COUNT_FLAGS = frozenset({"-ncmoe", "--n-cpu-moe"})
_CPU_PLACEMENT_PRESENCE_FLAGS = (_MOE_OFFLOAD_FLAGS - _CPU_MOE_COUNT_FLAGS) | frozenset(
    {"-ot", "--override-tensor"}
)
_CPU_PLACEMENT_FLAGS = _MOE_OFFLOAD_FLAGS | frozenset({"-ot", "--override-tensor"})
_THREAD_OVERRIDE_FLAGS = frozenset({"-t", "--threads"})
_TENSOR_SPLIT_FLAGS = frozenset({"--tensor-split", "-ts"})


def _strip_flag_pairs(args: Iterable[str], flags: frozenset[str]) -> list[str]:
    """Drop each ``flag value`` pair naming one of ``flags``."""
    out: list[str] = []
    skip = False
    for arg in args:
        if skip:
            skip = False
            continue
        if str(arg) in flags:
            skip = True
            continue
        out.append(str(arg))
    return out


# common_params defaults in the bundled llama.cpp runtime.
_DEFAULT_LLAMA_N_BATCH = 2048
_DEFAULT_LLAMA_N_UBATCH = 512
_LLAMA_ARG_TRUE_VALUES = frozenset({"on", "enabled", "true", "1"})
_LLAMA_ARG_FALSE_VALUES = frozenset({"off", "disabled", "false", "0"})
_LLAMA_ARG_AUTO_VALUES = frozenset({"auto", "-1"})
_LLAMA_ARG_TRUE_OR_AUTO_VALUES = _LLAMA_ARG_TRUE_VALUES | _LLAMA_ARG_AUTO_VALUES
_LLAMA_ARG_TRUE_FALSE_AUTO_VALUES = _LLAMA_ARG_TRUE_OR_AUTO_VALUES | _LLAMA_ARG_FALSE_VALUES


def _extra_args_set_any_flag(extra_args: Optional[Iterable[str]], flags: Collection[str]) -> bool:
    if not extra_args:
        return False
    for raw in extra_args:
        flag = _flag_name(str(raw))
        if flag in flags:
            return True
    return False


def _diffusion_manual_ngl(gpu_memory_mode: str, gpu_layers: int) -> Optional[int]:
    """The --ngl the diffusion runner would launch with, or None for its default.

    Only an explicit manual count reaches the child; Auto (-1) and Unsloth mode defer.
    Shared with both dedup guards, so an inert manual preference cannot loop.
    """
    return int(gpu_layers) if (gpu_memory_mode == "manual" and int(gpu_layers) >= 0) else None


def _scale_diffusion_required_gb(required_gb: float, ngl: int, n_layers: Optional[int]) -> float:
    """GPU share of a partially offloaded diffusion GGUF, for the training guard.

    Only the ``ngl`` resident layers compete for VRAM; sizing the whole file 409s a
    split that fits. An unknown layer count keeps the full estimate."""
    if not n_layers or n_layers <= 0 or ngl >= n_layers:
        return required_gb
    return required_gb * (ngl / n_layers)


def _source_declares_option(source: str, option: str) -> bool:
    """True iff ``source`` really registers ``option`` on an argparse parser.

    Parsed, not grepped: a substring test matches the flag in a comment and misses it
    when quoted differently. Falls back to a substring scan when the file will not parse.
    """
    try:
        tree = ast.parse(source)
    except (SyntaxError, ValueError):
        return option in source
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if not (isinstance(func, ast.Attribute) and func.attr == "add_argument"):
            continue
        for arg in node.args:
            if isinstance(arg, ast.Constant) and arg.value == option:
                return True
    return False


def _shim_supports_ngl(shim_cmd: List[str]) -> bool:
    """Whether the resolved diffusion shim accepts --ngl.

    The package floor still allows an unsloth_zoo without the flag and argparse exits
    on an unknown option, so emitting it blindly breaks the launch. Read the source
    rather than spawning a probe: the launch path is already slow.
    """
    # _find_diffusion_assets emits a file override ([python, <path>]) or the installed
    # package ([python, -m, <module>]). Key on the shape, not the suffix (an override may
    # be extensionless, .pyw or SHIM.PY), and probe that exact file: a sibling shim.py
    # answers for a different shim than argparse will run.
    if len(shim_cmd) >= 2 and "-m" not in shim_cmd:
        candidates = [Path(shim_cmd[-1])]
    else:
        candidates = []
        try:
            import importlib.util
            spec = importlib.util.find_spec("unsloth_zoo")
            if spec is not None and spec.submodule_search_locations:
                pkg_dir = Path(list(spec.submodule_search_locations)[0])
                candidates.append(pkg_dir / "diffusion_studio" / "shim.py")
        except Exception:
            return False
    for path in candidates:
        try:
            source = path.read_text(encoding = "utf-8", errors = "ignore")
        except OSError:
            continue
        if _source_declares_option(source, "--ngl"):
            return True
    return False


def _swa_full_from_args_or_env(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """Whether llama.cpp receives the enable-only full-size SWA option."""
    if _extra_args_set_any_flag(extra_args, {"--swa-full"}):
        return True
    value = (os.environ if env is None else env).get("LLAMA_ARG_SWA_FULL")
    return value in _LLAMA_ARG_TRUE_VALUES


def _env_asks_for_the_native_context(env: Optional[Mapping[str, str]] = None) -> bool:
    """Whether an inherited LLAMA_ARG_CTX_SIZE is 0.

    llama.cpp resolves the variable through -c's own handler, so 0 pins the
    native length here exactly as on the command line. Anything unparseable is
    left to llama.cpp to reject."""
    value = (os.environ if env is None else env).get("LLAMA_ARG_CTX_SIZE")
    try:
        return int(str(value).strip()) == 0
    except (AttributeError, TypeError, ValueError):
        return False


def _kv_offload_from_args(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """Resolve llama.cpp's environment and last-wins KV-offload flags (default on):
    LLAMA_ARG_KV_OFFLOAD parses before argv, and ``-kvo`` / ``--kv-offload`` is the
    positive form, so a CLI re-enable beats a false env.

    Both env spellings, as with the projector pair above. ``-kvo`` is registered with
    a negative form (``{"-nkvo", "--no-kv-offload"}``, common/arg.cpp), so
    ``common_arg::get_value_from_env`` rewrites LLAMA_ARG_ to LLAMA_ARG_NO_, and if
    that variable EXISTS it forces the value to "0" and never reads the affirmative
    one (common/arg.cpp:127-141). Presence, empty value included, because llama.cpp
    tests it with getenv. Missing it is the optimistic direction here: the whole KV
    cache is then on the host (llama-kv-cache.cpp only upgrades a layer's buffer
    type inside ``if (offload)``) while the fit still lets free VRAM pay for it.
    """
    source_env = os.environ if env is None else env
    enabled = True
    if source_env.get("LLAMA_ARG_NO_KV_OFFLOAD") is not None:
        enabled = False
    else:
        value = source_env.get("LLAMA_ARG_KV_OFFLOAD")
        if value in _LLAMA_ARG_FALSE_VALUES:
            enabled = False
        elif value in _LLAMA_ARG_TRUE_VALUES:
            enabled = True
    for raw in extra_args or ():
        flag = _flag_name(str(raw))
        if flag in {"-kvo", "--kv-offload"}:
            enabled = True
        elif flag in {"-nkvo", "--no-kv-offload"}:
            enabled = False
    return enabled


def _is_positive_int(value: Optional[str]) -> bool:
    """Whether ``value`` parses as an int > 0 (llama.cpp's std::stoi)."""
    try:
        return int(str(value).strip()) > 0
    except (TypeError, ValueError):
        return False


def _args_place_tensors_on_cpu(extra_args: Optional[Iterable[str]] = None) -> bool:
    """True when extras keep weights on the CPU, whatever the layer count says.

    The arg-side twin of ``_env_places_tensors_on_cpu``, including its rule that
    a CPU-MoE count only counts when positive: ``--n-cpu-moe 0`` places nothing.
    """
    values = [str(raw) for raw in extra_args or ()]
    for i, raw in enumerate(values):
        flag = _flag_name(raw)
        # Any -ot counts even if it matches nothing: the list need only be
        # non-empty, and guessing at the pattern is not worth it.
        if flag in _CPU_PLACEMENT_PRESENCE_FLAGS:
            return True
        if flag in _CPU_MOE_COUNT_FLAGS:
            _, eq, inline = raw.partition("=")
            if _is_positive_int(inline if eq else (values[i + 1] if i + 1 < len(values) else "")):
                return True
    return False


def _env_places_tensors_on_cpu(env: Optional[Mapping[str, str]] = None) -> bool:
    """True when inherited env keeps weights on the CPU, whatever the argv says.

    The child inherits these, so they survive stripping the equivalent flags.
    Shared with the Model Memory host-residency gate, which must not call a load
    fully offloaded while one of them is holding tensors in RAM.
    """
    source_env = os.environ if env is None else env
    return bool(
        source_env.get("LLAMA_ARG_OVERRIDE_TENSOR")
        or source_env.get("LLAMA_ARG_CPU_MOE") in _LLAMA_ARG_TRUE_VALUES
        or _is_positive_int(source_env.get("LLAMA_ARG_N_CPU_MOE"))
    )


def _env_fixes_gpu_layers(env: Optional[Mapping[str, str]] = None) -> bool:
    """True when an inherited ``LLAMA_ARG_N_GPU_LAYERS`` owns the layer placement.

    The env twin of ``_GPU_LAYER_FLAGS``, and it bites harder than the tokens do:
    the fitting path emits ``--fit on`` and no ``-ngl`` at all, so an inherited
    count is the ONLY layer policy the child sees. llama.cpp's fitter then refuses
    to touch it -- ``common_params_fit_impl`` throws "n_gpu_layers already set by
    user" (common/fit.cpp:377) on any value but the default, and the caller
    downgrades that to a warning (common/fit.cpp:805) -- so the launch proceeds
    with the count as given, placing a prefix of the weights and running the rest
    out of host RAM the fit just credited to a card.

    ``auto`` / ``-1`` is that default (common/common.h:465,
    llama-model.cpp:2453), so it leaves the fitter free to choose and is not an
    override. Everything else is, ``all`` included: a count that stands is a count
    this fit did not price. Empty counts as unset -- llama.cpp's ``std::stoi``
    would throw on it and the child would never start.
    """
    raw = (os.environ if env is None else env).get("LLAMA_ARG_N_GPU_LAYERS")
    value = str(raw or "").strip().lower()
    return bool(value) and value not in _LLAMA_ARG_AUTO_VALUES


def _pipeline_parallel_disabled_by_args(
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
    n_layers: Optional[int] = None,
) -> bool:
    """Whether the launch turns OFF llama.cpp's pipeline parallelism, i.e. the 4x in
    ``_CTX_COMPUTE_SPLIT_MULT``. llama-context.cpp requires ``-sm layer``, KV offload
    on and an empty tensor-override list (among other things); anything here is back to
    1x, and charging the multiplier anyway would waste context. Unsloth passes none of
    it, but extra_args and the environment can.

    ``-cmoe`` / ``-ncmoe`` count: both push into ``tensor_buft_overrides`` exactly like
    ``-ot`` (common/arg.cpp). ``-otd`` does not - it targets the draft model.
    LLAMA_ARG_SPLIT_MODE is not read here: the launch pops a non-layer inherited value
    on the layer path, so it never reaches the child. Ambiguous input resolves to
    "still pipelined" - over-reserving only costs context, under-reserving OOMs the
    split. ``n_layers`` is the GGUF block count for the ``-ngl`` check below; None/0
    means unknown."""
    source_env = os.environ if env is None else env
    if _env_places_tensors_on_cpu(source_env):
        return True
    if not _kv_offload_from_args(extra_args, env = env):
        return True
    # -sm none/row keep the layer path and pass through, so they really do disable
    # it. -sm tensor does not: the layer branch is only reached after a downgrade,
    # which strips the flag (strip_split_mode_only) and leaves the child on layer.
    split_mode = parse_split_mode_override(extra_args)
    if split_mode is not None and split_mode.strip().lower() not in {"layer", "tensor"}:
        return True
    # Pipelining needs n_gpu_layers > n_layer_all, so a user -ngl (appended after
    # Unsloth's -ngl -1, last-wins) that cannot exceed the count loads a prefix and
    # turns it off. Negative (all layers) or above the count keeps the step, even
    # in between: n_layers is block_count, which IS n_layer_all (llama-model.cpp
    # reads the key straight into it); hparams.n_layer() is the smaller MTP-less one.
    if n_layers:
        try:
            gpu_layers = parse_gpu_layers_override(extra_args)
        except ValueError:
            gpu_layers = None  # malformed: unknown, so keep the step
        if gpu_layers is not None and 0 <= gpu_layers <= n_layers:
            return True
    # Same predicate the Model Memory host-residency gate uses; -ncmoe 0 pushes
    # no override, so it leaves pipelining on.
    return _args_place_tensors_on_cpu(extra_args)


def _kv_unified_from_args(
    extra_args: Optional[Iterable[str]],
    default: bool = False,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Resolve llama.cpp's environment and last-wins unified KV flags."""
    enabled = False
    value = (os.environ if env is None else env).get("LLAMA_ARG_KV_UNIFIED")
    if value in _LLAMA_ARG_TRUE_VALUES:
        enabled = True
    elif value in _LLAMA_ARG_FALSE_VALUES:
        enabled = False
    if default:
        # Unsloth's managed --kv-unified flag is appended after environment
        # parsing and before user extras.
        enabled = True
    for raw in extra_args or ():
        flag = _flag_name(str(raw))
        if flag in {"-kvu", "--kv-unified"}:
            enabled = True
        elif flag in {"-no-kvu", "--no-kv-unified"}:
            enabled = False
    return enabled


def _flash_attn_enabled_from_args(
    args: Optional[Iterable[str]],
    default: bool = True,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Resolve llama.cpp's environment and last-wins flash-attention settings."""
    enabled = default
    # llama.cpp applies LLAMA_ARG_FLASH_ATTN before parsing argv (arg.cpp set_env),
    # so the CLI still wins. --flash-attn has no args_neg, so no LLAMA_ARG_NO_ twin.
    value = (os.environ if env is None else env).get("LLAMA_ARG_FLASH_ATTN")
    if value in _LLAMA_ARG_FALSE_VALUES:
        enabled = False
    elif value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
        enabled = True
    values = [str(arg) for arg in args] if args else []
    for i, raw in enumerate(values):
        if _flag_name(raw) not in {"-fa", "--flash-attn"}:
            continue
        _, eq, inline = raw.partition("=")
        value = inline if eq else "on"
        if not eq and i + 1 < len(values) and values[i + 1] in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES:
            value = values[i + 1]
        if value in _LLAMA_ARG_FALSE_VALUES:
            enabled = False
        elif value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
            enabled = True
    return enabled


def _effective_spec_type(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    """The last --spec-type label a launch carries: final CLI --spec-type (or
    --spec-default, which resolves non-MTP), else LLAMA_ARG_SPEC_TYPE. A display and
    comparison label only, NOT what llama.cpp enables: types accumulate there, so ask
    _extra_args_requests_mtp whether MTP is on. None if neither sets it."""
    args = [str(a) for a in extra_args] if extra_args else []
    cli_present = False
    cli_value: Optional[str] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag == "--spec-default":
            cli_present = True
            cli_value = "default"
            continue
        if flag != "--spec-type":
            continue
        cli_present = True
        cli_value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
    if cli_present:
        return cli_value
    return (os.environ if env is None else env).get("LLAMA_ARG_SPEC_TYPE")


def _child_spec_env(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Mapping[str, str]:
    """The spec env the child will actually see: empty unless extras name a
    --spec-type, because the launch scrubs LLAMA_ARG_SPEC_* whenever Unsloth owns the
    spec block. Predict from this, not os.environ, or you describe a server that is
    not the one being started."""
    if not _extra_args_set_spec_type(extra_args):
        return {}
    return os.environ if env is None else env


# The speculative types llama.cpp gives the TARGET context recurrent-state rollback
# snapshots for -- n_rs_seq = --spec-draft-n-max, per
# common_params_speculative::need_n_rs_seq. Every draft-model type but draft-simple,
# and both MTP spellings, since which one a build advertises varies.
_TARGET_ROLLBACK_SPEC_TYPES = frozenset(
    {"mtp", "draft-mtp", "draft-eagle3", "draft-dflash", "draft-dspark"}
)


# Architectures whose TARGET context leaves the embedded MTP/NextN blocks out of
# its KV cache, so block_count must lose them before the target is priced.
#
# This is NOT every architecture that carries {arch}.nextn_predict_layers.
# llama_hparams::n_layer() subtracts nextn everywhere (llama-hparams.cpp:297),
# but llama_kv_cache walks hparams.n_layer_all (llama-kv-cache.cpp:100) and drops
# blocks only through an optional per-arch filter (:169). That filter is installed
# for the hybrids at llama-model.cpp:2289 (Qwen3-Next/Qwen3.5/MiniMax-01 and, via
# is_recr, Nemotron-H), for GLM-DSA and DeepSeek3.2 at :2129, and for the
# STEP35/HY_V3/MIMO2 group at :2356. Everywhere else -- deepseek2, glm4, glm4moe,
# bailingmoe2, cohere2moe, exaone4 -- filter is nullptr and the trailing MTP block
# DOES get target KV, so subtracting it under-reserves.
#
# Fail closed: an arch not named here keeps every block, because over-reserving
# costs context while under-reserving OOMs the load. Recurrent state is the one
# thing that always excludes nextn, llama_memory_recurrent sizing on n_layer()
# directly (llama-memory-recurrent.cpp:29), which is why
# _mamba_recurrent_state_bytes subtracts unconditionally.
_TARGET_KV_EXCLUDES_NEXTN_ARCHS = frozenset(
    {
        # Hybrid attention + recurrent, llama-model.cpp:2289
        "qwen3next",
        "qwen35",
        "qwen35moe",
        "minimax-01",
        "nemotron_h",
        "nemotron_h_moe",
        # MLA/DSA trunk with a dense MTP head, llama-model.cpp:2129
        "glm-dsa",
        "deepseek32",
        # Plain attention trunk with an explicit nextn filter, llama-model.cpp:2356
        "step35",
        "hy_v3",
        "mimo2",
    }
)


def _accumulated_spec_types(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> set:
    """Every speculative type a launch carries, lowercased. Types accumulate rather
    than replace: llama.cpp applies the env first through the same handler and every
    --spec-type inserts at the end, so a later flag cannot clear an earlier one (even
    --spec-type none only appends NONE). Look at all of them, not just the last."""
    values = []
    args = [str(a) for a in extra_args] if extra_args else []
    for i, raw in enumerate(args):
        _, eq, inline = raw.partition("=")
        if _flag_name(raw) == "--spec-type":
            values.append(inline if eq else (args[i + 1] if i + 1 < len(args) else ""))
    env_value = (os.environ if env is None else env).get("LLAMA_ARG_SPEC_TYPE")
    if env_value:
        values.append(env_value)
    return {p.strip().lower() for v in values for p in v.split(",") if p.strip()}


def _extra_args_requests_mtp(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True if MTP lands in llama.cpp's spec-type vector, so the budget must reserve
    for it and the slots must clamp. Per _accumulated_spec_types, ANY source counts."""
    return bool(_accumulated_spec_types(extra_args, env) & {"mtp", "draft-mtp"})


def _extra_args_requests_dspark(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True if DSpark lands in llama.cpp's accumulated spec-type vector."""
    return "draft-dspark" in _accumulated_spec_types(extra_args, env)


def _extra_args_requests_dflash(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True if DFlash lands in llama.cpp's accumulated spec-type vector."""
    return "draft-dflash" in _accumulated_spec_types(extra_args, env)


@functools.lru_cache(maxsize = 1)
def _metal_device_is_paravirtual() -> bool:
    """True when Metal is a virtualised Apple GPU, whose offload can corrupt output.

    Seen on our own macos-14/15 runners: offload returned an ordered walk through the
    character set while gpu_layers=0 on the same model, quant and binary was coherent,
    and MLX stayed correct. It does not reproduce on every build or quant (gemma-3-270m
    Q4_K_M on b9000 and b10090 was byte identical at gpu_layers 0 and 99), so
    UNSLOTH_ALLOW_PARAVIRTUAL_METAL=1 keeps the GPU on a VM known good. Physical Apple
    Silicon never matches.

    Three probes, cheapest first. MLX names the device outright (~40 ms) but is not on
    every Mac. hw.model then answers the headless case that matters most: measured on
    macos-14/15, SPDisplaysDataType returns zero bytes on a VM with no display so it
    cannot see a cloud or CI Mac at all, while hw.model still reports VirtualMac2,1 or
    VMM-x86_64 against Mac<n>,<n> on real hardware. SPDisplaysDataType stays last for
    desktop VMs, which do have a display and do name the paravirtual chipset.
    """
    if sys.platform != "darwin":
        return False
    if os.environ.get("UNSLOTH_ALLOW_PARAVIRTUAL_METAL", "").strip().lower() in (
        "1",
        "true",
        "yes",
    ):
        logger.info("UNSLOTH_ALLOW_PARAVIRTUAL_METAL set: keeping Metal offload.")
        return False
    name = ""
    try:
        import mlx.core as mx
        name = str(mx.device_info().get("device_name") or "")
    except Exception:
        name = ""
    if "paravirtual" not in name.lower():
        for _probe_cmd, _match in (
            # VMM-x86_64 is the Intel-guest identifier and contains neither
            # "virtual" nor "paravirtual"; upstream ships Metal on macOS x64 too.
            (["sysctl", "-n", "hw.model"], ("virtual", "vmm-")),
            (["system_profiler", "SPDisplaysDataType"], ("paravirtual",)),
        ):
            try:
                probe = subprocess.run(
                    _probe_cmd,
                    capture_output = True,
                    text = True,
                    timeout = 30,
                    encoding = "utf-8",
                    errors = "replace",
                )
            except Exception:
                continue
            _out = (probe.stdout or "").lower()
            if any(m in _out for m in _match):
                name = f"{name} {probe.stdout}".strip()
                break
    _low = name.lower()
    if "paravirtual" in _low or "virtual" in _low or "vmm-" in _low:
        logger.warning(
            "Metal device looks virtualised (%s). Offload can return corrupt output on "
            "paravirtual Apple GPUs, so GGUF inference will run on CPU. MLX is "
            "unaffected. Set UNSLOTH_ALLOW_PARAVIRTUAL_METAL=1 to keep the GPU.",
            name.strip()[:120] or "unknown",
        )
        return True
    return False


def _paravirtual_probe_answered(server_caps: Mapping[str, object]) -> bool:
    """False when the --help probe failed, so every capability read as absent.

    Both companion flags predate the oldest build Unsloth can launch (--no-mmproj-offload
    is b5178, --gpu-layers-draft is from 2023, and the base argv already requires b6325),
    so "capability missing" means the probe did not answer, not that the build lacks it:
    one malformed inherited LLAMA_ARG_* makes llama-server --help exit non-zero and the
    all-false result is cached for the process. Dropping the projector or the drafter on
    that would be a self-inflicted outage, so drops require a conclusive probe and the
    pins cover the unanswered case.
    """
    return not server_caps.get("mtp_probe_inconclusive")


def _paravirtual_draft_ngl_flag(server_caps: Mapping[str, object]) -> Optional[str]:
    """The draft-layer flag to pin with, or None only when the build truly lacks one."""
    flag = server_caps.get("spec_draft_ngl_flag")
    if flag:
        return str(flag)
    # Unanswered probe: use the spelling every launchable build has had since 2023
    # rather than treating the drafter as unpinnable.
    if not _paravirtual_probe_answered(server_caps):
        return "--gpu-layers-draft"
    return None


def _paravirtual_mmproj_pinnable(server_caps: Mapping[str, object]) -> bool:
    """True when --no-mmproj-offload can be emitted, including on an unanswered probe."""
    return bool(
        server_caps.get("supports_no_mmproj_offload")
        or not _paravirtual_probe_answered(server_caps)
    )


def _mmproj_env_is_audio_only(path: Optional[str]) -> bool:
    """True only when *path* names a readable projector with no vision tower.

    Anything else -- unset, absent from disk, unreadable, or declaring images -- is
    False, so the caller clears it. Deliberately asymmetric: keeping a projector the
    user switched off is the worse mistake of the two, and an unknown declaration
    reads image-capable upstream.
    """
    if not path:
        return False
    try:
        from utils.models.gguf_metadata import mmproj_capabilities
        has_audio, accepts_image = mmproj_capabilities(str(path))
    except Exception as e:
        logger.debug(f"inherited mmproj capability read failed: {e}")
        return False
    return has_audio and not accepts_image


# Both spellings of the projector-placement boolean. llama.cpp pairs them as one
# option and takes the last occurrence, so naming either one in the pass-through
# extras is the user taking ownership of the placement.
_MMPROJ_OFFLOAD_FLAGS: frozenset = frozenset({"--mmproj-offload", "--no-mmproj-offload"})


def _extra_args_set_mmproj_offload(extra_args: Optional[Sequence[str]]) -> bool:
    """True when the pass-through extras name either projector-placement spelling.

    Matched through _flag_name rather than by string equality: arg.cpp folds
    underscores to dashes before matching, so --mmproj_offload is the same flag.
    """
    return _extra_args_set_any_flag(extra_args, _MMPROJ_OFFLOAD_FLAGS)


def _extra_args_mmproj_offload_value(extra_args: Optional[Sequence[str]]) -> Optional[bool]:
    """The offload the extras actually resolve to, or None when they name neither.

    Detecting ownership is not enough to budget for: --no-mmproj-offload means the
    child keeps the projector in host RAM, so charging its bytes against VRAM
    shrinks the context for memory nothing on the GPU takes. Last occurrence wins,
    as llama.cpp pairs the two spellings into one option.
    """
    if not extra_args:
        return None
    value: Optional[bool] = None
    for raw in extra_args:
        flag = _flag_name(str(raw))
        if flag == "--mmproj-offload":
            value = True
        elif flag == "--no-mmproj-offload":
            value = False
    return value


# arg.cpp applies set_env options BEFORE argv, so an inherited placement is a choice
# Unsloth can reverse with nothing but a llama.cpp warning to show for it, and the child
# inherits this process's environment. Both spellings: get_value_from_env checks the
# LLAMA_ARG_NO_ form first and forces falsey on PRESENCE, empty value included.
_MMPROJ_OFFLOAD_ENV_VAR = "LLAMA_ARG_MMPROJ_OFFLOAD"
_MMPROJ_OFFLOAD_NEG_ENV_VAR = "LLAMA_ARG_NO_MMPROJ_OFFLOAD"


def _env_sets_mmproj_offload(env: Optional[Mapping[str, str]] = None) -> bool:
    """True when the child's environment names the projector placement at all.

    Ownership, not value: a value arg.cpp parses as neither truthy nor falsey throws
    out of common_params_parse, and a caller whose load is about to fail on their own
    variable is still the one who set it. Presence is the test for the same reason
    llama.cpp uses getenv, so ``LLAMA_ARG_NO_MMPROJ_OFFLOAD=`` counts.
    """
    source = os.environ if env is None else env
    return any(
        source.get(name) is not None
        for name in (_MMPROJ_OFFLOAD_ENV_VAR, _MMPROJ_OFFLOAD_NEG_ENV_VAR)
    )


def _env_mmproj_offload_value(env: Optional[Mapping[str, str]] = None) -> Optional[bool]:
    """The offload the child's environment resolves to, or None for silence.

    get_value_from_env's own order: the negative spelling short-circuits to falsey on
    presence, then the positive one goes through is_truthy / is_falsey. Anything else
    is left as None, since arg.cpp raises rather than picking a side and there is no
    placement to budget for.
    """
    source = os.environ if env is None else env
    if source.get(_MMPROJ_OFFLOAD_NEG_ENV_VAR) is not None:
        return False
    raw = source.get(_MMPROJ_OFFLOAD_ENV_VAR)
    if raw is None:
        return None
    value = str(raw).strip().lower()
    if value in _LLAMA_ARG_TRUE_VALUES:
        return True
    if value in _LLAMA_ARG_FALSE_VALUES:
        return False
    return None


def _resolved_mmproj_offload(
    extra_args: Optional[Sequence[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[bool]:
    """Where the projector actually ends up, over extras and environment together.

    Same precedence the child applies: environment first, then argv on top, so a
    pass-through flag wins over an inherited variable and only silence in both falls
    through to None.
    """
    from_args = _extra_args_mmproj_offload_value(extra_args)
    return from_args if from_args is not None else _env_mmproj_offload_value(env)


_OVERRIDE_TENSOR_FLAGS: frozenset = frozenset(
    {
        "-ot",
        "--override-tensor",
        "-otd",
        "--override-tensor-draft",
        "--spec-draft-override-tensor",
    }
)


def _paravirtual_strip_gpu_overrides(
    extra_args: Optional[Iterable[str]], *, log_dropped: bool = True
) -> Optional[List[str]]:
    """Drop --override-tensor entries that place weights back on the corrupt device.

    ``-ot`` is the one placement flag ``--gpu-layers 0`` cannot answer: llama.cpp applies
    the override while selecting each weight's buffer type, before any layer is assigned
    to a device, so ``-ot ".*=Metal"`` puts weights on the virtualised GPU whatever the
    layer count says. It also accumulates rather than replaces, so a later flag cannot
    neutralise it; the entry has to go. ``-otd`` does the same for the drafter and would
    defeat the draft-layer pin.

    Only non-CPU targets are dropped: ``-ot exps=CPU`` moves weights the same way this
    fallback does, so stripping it would slow the very load it rescues.

    ``log_dropped=False`` for the duplicate-load comparators, which only inspect a
    request and must not narrate a drop no launch is performing, on every /load.
    """
    if not extra_args:
        return extra_args if extra_args is None else list(extra_args)
    args = [str(a) for a in extra_args]
    out: List[str] = []
    i = 0
    while i < len(args):
        tok = args[i]
        # _flag_name mirrors llama.cpp's underscore folding (arg.cpp does
        # std::replace(_ -> -) before matching), so --override_tensor is the same flag.
        base, _, inline = tok.partition("=")
        if _flag_name(base) in _OVERRIDE_TENSOR_FLAGS:
            value = inline if inline else (args[i + 1] if i + 1 < len(args) else "")
            targets = [
                part.rsplit("=", 1)[-1].strip().lower() for part in value.split(",") if "=" in part
            ]
            if targets and all(t == "cpu" for t in targets):
                out.append(tok)
                if not inline and i + 1 < len(args):
                    out.append(args[i + 1])
            elif log_dropped:
                logger.warning(
                    "Dropping %s %s: this Mac's Metal device is virtualised, so an "
                    "override that keeps weights on it would return corrupt output.",
                    base,
                    value,
                )
            i += 1 if inline else 2
            continue
        out.append(tok)
        i += 1
    return out


class ParavirtualPlacement(NamedTuple):
    """A load request's GPU placement after the virtualised-Metal CPU pin."""

    gpu_memory_mode: Literal["auto", "manual"]
    gpu_layers: int
    tensor_parallel: bool
    tensor_split: Optional[List[float]]
    n_cpu_moe: int
    extra_args: Optional[List[str]]


def paravirtual_normalized_request(
    *,
    gpu_memory_mode: Literal["auto", "manual"] = "auto",
    gpu_layers: int = -1,
    tensor_parallel: bool = False,
    tensor_split: Optional[List[float]] = None,
    n_cpu_moe: int = 0,
    extra_args: Optional[Iterable[str]] = None,
    log_dropped: bool = True,
) -> ParavirtualPlacement:
    """Map a requested placement to the one a virtualised Metal device launches.

    Single source of truth for the CPU pin, shared by the launch (load_model) and by
    BOTH duplicate-load comparators (``_already_in_target_state`` and the route's
    ``_request_matches_loaded_settings``). The launch records what it normalized, so a
    comparator judging the RAW request would mismatch its own state and tear down a
    healthy CPU server on every repeat Apply -- and, with an unbounded reload loop, 409
    or cancel a live generation.

    Pure, unconditional (callers gate on ``_metal_device_is_paravirtual()``) and
    idempotent, so re-applying it to a normalized request is a no-op.

    Deliberately NOT keyed on the request already being manual/0: that places the main
    model on CPU, but the extras are the caller's, and ``-ot ".*=Metal"`` is applied
    while each weight's buffer type is chosen, before any layer is assigned, so it puts
    weights back on the corrupt device -- and the route strips only the ``-ngl`` family.

    ``log_dropped=False`` for the comparators, which only inspect a request and must not
    narrate a rewrite no launch is performing.
    """
    normalized = extra_args if extra_args is None else list(extra_args)
    if normalized:
        # Extras are appended AFTER the managed --gpu-layers 0 and llama.cpp is
        # last-wins, so an `-ngl 99` would re-enable the corrupt offload. The route
        # strips these only in manual mode, so an Auto request still carries them.
        normalized = strip_shadowing_flags(
            normalized,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            strip_offload = True,
        )
        # strip_offload covers only the layer-count family; an --override-tensor aimed
        # at Metal survives it and places weights before any layer assignment.
        normalized = _paravirtual_strip_gpu_overrides(normalized, log_dropped = log_dropped)
    return ParavirtualPlacement(
        gpu_memory_mode = "manual",
        gpu_layers = 0,
        # Nothing is left on the GPU to split, and the launch drops these anyway;
        # normalize here too so the recorded state and the next request agree.
        tensor_parallel = False,
        tensor_split = None,
        n_cpu_moe = 0,
        extra_args = normalized,
    )


def _paravirtual_split_mode_pin(extra_args: Optional[Iterable[str]]) -> List[str]:
    """Flags that neutralise a pass-through ``--split-mode`` on a virtualised Mac.

    A user ``--split-mode`` is deliberately allowed (the Tensor Parallelism toggle
    cannot express row/none), but the paravirtual fallback has already pinned this load
    to CPU, and the flag is NOT inert at ``--gpu-layers 0``: llama.cpp builds a
    buffer-type list for every device in ``model->devices`` before any layer is
    assigned, and n_gpu_layers never reaches that step. So ``-sm row`` throws "device
    <X> does not support split buffers" on every backend except SYCL
    (``make_gpu_buft_list``, llama-model.cpp, since ggml-org/llama.cpp#24216 removed
    CUDA's split buffers), and ``-sm tensor`` throws "LLAMA_SPLIT_MODE_TENSOR not
    implemented for architecture" for every arch ``llm_arch_supports_sm_tensor``
    excludes. Either turns the CPU rescue into a server that refuses to start, and the
    zero-offload mask cannot save it: it writes only CUDA/HIP visibility vars, so the
    Metal device stays in the list on the one platform this fallback fires on.

    Overridden rather than stripped: llama.cpp is last-wins, so ``layer`` (the default,
    and a provable no-op at ``--gpu-layers 0`` -- llama-model.cpp computes the split
    points but never indexes them once ``act_gpu_layers`` is 0) neutralises the mode
    without rewriting ``extra_args``. The route's duplicate-load comparator compares
    stored extras verbatim and the UI does not round-trip the extras box, so stripping
    would leave the two permanently unequal and turn every later Apply into a real model
    swap. ``--tensor-split`` needs neither treatment for the same never-indexed reason.

    Returns [] when extras set no mode or already set ``layer``.
    """
    mode = (parse_split_mode_override(extra_args) or "").strip().lower()
    if not mode or mode == "layer":
        return []
    logger.warning(
        "Overriding --split-mode %s with the default layer split: this Mac's "
        "Metal device is virtualised, so the model runs on CPU and a GPU split "
        "mode would only fail the load.",
        mode,
    )
    return ["--split-mode", "layer"]


def _extra_args_requests_separate_draft(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True if a non-MTP model draft mode (draft-simple/draft-eagle3) is selected, which
    loads a separate draft model the budget must reserve (draft-mtp ->
    _extra_args_requests_mtp; ngram-* load no model). Accumulating for the same reason as
    _extra_args_requests_mtp: a later --spec-default or --spec-type cannot clear an
    inherited draft-simple, so reading only the last under-reserves the model it loads."""
    return bool(
        _accumulated_spec_types(extra_args, env)
        & {"draft-simple", "draft-eagle3", "draft-dspark", "draft-dflash"}
    )


def _extra_args_spec_draft_n_max(extra_args: Optional[Iterable[str]]) -> Optional[int]:
    """Draft depth from extras (``--spec-draft-n-max`` or legacy ``--draft-max``), else None."""
    if not extra_args:
        return None
    args = [str(a) for a in extra_args]
    found: Optional[int] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag not in ("--spec-draft-n-max", "--draft-max"):
            continue
        value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        try:
            found = int(value)
        except (TypeError, ValueError):
            continue
    return found


def _extra_args_mtp_draft_path(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    """Separate drafter path from extras (local --model-draft/-md or HF
    --spec-draft-hf/-hfd/...), else the LLAMA_ARG_SPEC_DRAFT_MODEL/_HF_REPO env,
    else None. An HF repo isn't a local file, so the budget can't size it (falls
    back to the flat reserve), but recognizing it avoids sizing the wrong one."""
    return _extra_args_mtp_draft_source(extra_args, env)[0]


_HF_DRAFT_FLAGS = frozenset({"--spec-draft-hf", "-hfd", "-hfrd", "--hf-repo-draft"})
_LOCAL_DRAFT_FLAGS = frozenset({"--model-draft", "--spec-draft-model", "-md"})


def _extra_args_mtp_draft_source(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> tuple[Optional[str], bool]:
    """The drafter the launch resolves to, and whether it is a repo id.

    The two travel together on purpose. Draft flags are last-wins, so a remote flag
    followed by a local one leaves a local path as the winner; a caller that asks
    only "does any remote flag appear" would then price a filesystem path as a
    Hugging Face repository and charge a reserve for something llama-server will
    not load. Only the winning flag decides which of the two the value is.
    """
    args = [str(a) for a in extra_args] if extra_args else []
    found: Optional[str] = None
    found_remote = False
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag not in _HF_DRAFT_FLAGS and flag not in _LOCAL_DRAFT_FLAGS:
            continue
        value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        if value and not value.startswith("-"):
            found = value
            found_remote = flag in _HF_DRAFT_FLAGS
    if found is not None:
        return found, found_remote
    e = os.environ if env is None else env
    # The value lookup's own precedence; with no flag to read, the env spelling says
    # local or remote. The last two are pre-b8955 (2025-08-30 to 2026-04-28).
    for var, remote in (
        ("LLAMA_ARG_SPEC_DRAFT_MODEL", False),
        ("LLAMA_ARG_SPEC_DRAFT_HF_REPO", True),
        ("LLAMA_ARG_MODEL_DRAFT", False),
        ("LLAMA_ARG_HFD_REPO", True),
    ):
        value = e.get(var)
        if value:
            return value, remote
    return None, False


def _normalized_load_mode(value: Optional[str]) -> Optional[str]:
    """Canonical --load-mode, with llama.cpp's own default reading as unset.

    "auto" IS the default, so a load asking for it and a load asking for nothing
    launch the same command; the dedupe has to see them as equal or picking Auto
    would reload a server already running it.
    """
    if value is None:
        return None
    mode = str(value).strip().lower()
    return None if mode in {"", "auto"} else mode


# The KV cache dtypes llama.cpp can map, shared by the emission guard and the
# budget. Module level because both the draft-cache block and the MTP reserve
# need it, and the main cache path's copy is a local inside load_model.
_VALID_KV_CACHE_TYPES: frozenset[str] = frozenset(
    {"f16", "bf16", "q8_0", "q4_0", "q4_1", "q5_0", "q5_1", "iq4_nl", "f32"}
)


def _extra_args_draft_cache_types(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> tuple[Optional[str], Optional[str]]:
    """Draft KV cache types (k_type, v_type), each from extras else the
    LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_K/_V env, else None (f16). K and V are
    independent: a one-sided override must not apply to both."""
    args = [str(a) for a in extra_args] if extra_args else []
    k_flags = {"--cache-type-k-draft", "--spec-draft-type-k", "-ctkd"}
    v_flags = {"--cache-type-v-draft", "--spec-draft-type-v", "-ctvd"}
    k_type: Optional[str] = None
    v_type: Optional[str] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag not in k_flags and flag not in v_flags:
            continue
        value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        if not value or value.startswith("-"):
            continue
        if flag in k_flags:
            k_type = value
        else:
            v_type = value
    e = os.environ if env is None else env
    if k_type is None:
        k_type = e.get("LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_K") or None
    if v_type is None:
        v_type = e.get("LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_V") or None
    return k_type, v_type


_DRAFT_GPU_LAYER_FLAGS = frozenset(
    {"--spec-draft-ngl", "-ngld", "--gpu-layers-draft", "--n-gpu-layers-draft"}
)


def _extra_args_draft_gpu_layers(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    """The effective draft layer count for the SEPARATE drafter, as written.

    Last-wins over argv, falling back to the ``LLAMA_ARG_N_GPU_LAYERS_DRAFT`` twin
    the child reads before argv. None when neither is set."""
    args = [str(a) for a in extra_args] if extra_args else []
    last_ngl: Optional[str] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        if flag in _DRAFT_GPU_LAYER_FLAGS:
            last_ngl = value
    if last_ngl is None:
        last_ngl = (os.environ if env is None else env).get("LLAMA_ARG_N_GPU_LAYERS_DRAFT")
    return last_ngl


def _draft_is_split_across_host(
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
    *,
    n_draft_layers: Optional[int] = None,
) -> bool:
    """True when a fixed POSITIVE draft layer count splits the drafter between the
    GPU and host RAM.

    ``_extra_args_draft_offloaded_to_cpu`` is the whole-drafter question and only
    answers ``-ngld 0``. Anything between that and the drafter's own block count
    leaves the layers past the count on the host -- llama.cpp derives
    ``i_gpu_start`` from the count and hands every layer below it the CPU buffer
    list (llama-model.cpp), and each layer's KV follows its device
    (llama-kv-cache.cpp). llama.cpp's default is -1, "all", so only a non-negative
    count is a placement at all, and only a count ABOVE ``n_draft_layers`` places
    the drafter whole: ``i_gpu_start = max(n_layer_all + 1 - n_gpu_layers, 0)``
    (llama-model.cpp), so the count has to clear the block count by one to reach
    zero, and ``-ngld`` equal to the block count still leaves one block -- and its
    KV -- on the host. That is the same threshold the main model already uses
    (``requested <= n_layers`` in ``_partially_offloads_layers``, and
    ``0 <= gpu_layers <= n_layers`` in the pipelining check). An unreadable block
    count (None) says nothing either way, so a positive count stands as a split
    rather than being waved through.
    """
    raw = _extra_args_draft_gpu_layers(extra_args, env)
    if raw is None:
        return False
    try:
        count = int(str(raw).strip())
    except (TypeError, ValueError):
        # std::stoi would throw and the child never starts: nothing to misprice.
        return False
    if count <= 0:
        return False
    return not (n_draft_layers and count > n_draft_layers)


_SIDECAR_ADAPTER_FLAGS = (
    "--lora",
    "--lora-scaled",
    "--control-vector",
    "--control-vector-scaled",
)


def _sidecar_adapter_paths(extra_args: Optional[Iterable[str]]) -> list[str]:
    """Every adapter file the child loads and holds RESIDENT, in argv order.

    None of these have an env twin -- common/arg.cpp declares all four without
    ``set_env`` -- so the tokens are the whole surface. Each operand is a
    comma-separated row (``parse_csv_row``), and the ``-scaled`` spellings split
    every entry on ':' into exactly FNAME and SCALE and throw otherwise, so a
    malformed entry is a child that never starts and has no placement to misprice;
    it is skipped rather than priced. ACCUMULATED, not last-wins: every handler
    ``push_back``s onto ``lora_adapters`` / ``control_vectors``, so a second
    ``--lora`` adds to the first rather than replacing it.

    The ``-scaled`` pair also has a LEGACY spelling: builds up to the turn of the
    year declared it ``{"--lora-scaled"}, "FNAME", "SCALE"`` and took the scale as a
    SECOND token, and Unsloth runs whatever llama-server it is pointed at
    (``LLAMA_SERVER_PATH``, or one found on PATH), which is why the pass-through
    validator still admits that shape (``_OPTIONAL_SECOND_VALUE_FLAGS``). Read
    colon-first, since that is today's syntax; only when the colon parse priced
    NOTHING and the token after the operand is a bare number is this the two-token
    form, and then the operand is the whole filename -- which is also the one
    reading that survives a Windows drive letter. On a build that wants the colon
    the same tokens are upstream's own throw, so pricing the file there costs at
    most a fit that never launched.
    """
    args = [str(a) for a in extra_args] if extra_args else []
    paths: list[str] = []
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        if flag not in _SIDECAR_ADAPTER_FLAGS:
            continue
        _, eq, inline = raw.partition("=")
        operand = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        priced = 0
        for entry in (piece for piece in operand.split(",") if piece):
            if not flag.endswith("-scaled"):
                paths.append(entry)
                priced += 1
                continue
            # Upstream demands exactly 2 parts, so a bare or drive-lettered path throws.
            head, colon, tail = entry.partition(":")
            if not (colon and head) or ":" in tail:
                continue
            try:
                float(tail)
            except ValueError:
                continue
            paths.append(head)
            priced += 1
        if priced or not operand or eq or not flag.endswith("-scaled"):
            continue
        # Legacy "FNAME SCALE": the scale is the token AFTER the operand.
        scale = args[i + 2] if i + 2 < len(args) else ""
        try:
            float(scale.strip())
        except ValueError:
            continue
        paths.append(operand)
    return paths


def _sidecar_adapter_bytes(extra_args: Optional[Iterable[str]]) -> Optional[int]:
    """Resident bytes the pass-through adapters add, or None when one cannot be sized.

    LoRA tensors are allocated on the BASE tensor's buffer type
    (``ggml_backend_buffer_get_type(model_tensor->buffer)``, llama-adapter.cpp) and
    a control vector on ``model.select_buft(il)``, so they follow the layer
    placement this fit just priced rather than living anywhere it can ignore.
    Neither path mmaps -- the file is read into a staging buffer and pushed with
    ``ggml_backend_tensor_set`` -- so these bytes are resident whatever
    ``--load-mode`` says, and they sit ON TOP of a placement llama.cpp's own fitter
    never accounted for (common/fit.cpp knows nothing about adapters).

    File size is the ceiling on the allocation (the loader skips ``_norm.weight``
    pairs and keeps every other tensor at its stored type), and overstating a term
    only ever costs a fit, so the stat is charged whole. An unreadable file is the
    "engaged but unsized" case the fit abstains on.
    """
    total = 0
    for path in _sidecar_adapter_paths(extra_args):
        try:
            total += max(0, os.stat(path).st_size)
        except OSError:
            return None
    return total


def _extra_args_draft_offloaded_to_cpu(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True if the SEPARATE draft model is on CPU (so the budget must not charge
    its weights+KV): --spec-draft-ngl 0, or --spec-draft-device naming only
    cpu/none, else the LLAMA_ARG_N_GPU_LAYERS_DRAFT env the child honors (the
    device flag has no env). An embedded MTP head follows the main -ngl, so these
    draft-only flags don't move it. Last-wins, so only each flag's final value counts.

    A count BETWEEN 0 and the drafter's block count is a split, not an offload; see
    ``_draft_is_split_across_host``."""
    last_ngl = _extra_args_draft_gpu_layers(extra_args, env)
    if last_ngl is not None:
        try:
            if int(last_ngl) == 0:
                return True
        except (TypeError, ValueError):
            pass
    last_dev = _extra_args_draft_device(extra_args)
    if last_dev is not None:
        devs = [d.strip().lower() for d in last_dev.split(",") if d.strip()]
        if devs and all(d in ("cpu", "none") for d in devs):
            return True
    return False


def _extra_args_device(
    extra_args: Optional[Iterable[str]], flags: Collection[str]
) -> Optional[str]:
    """Return the last value for any device flag in ``flags``."""
    args = [str(a) for a in extra_args] if extra_args else []
    value: Optional[str] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag in flags:
            value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
    return value


def _extra_args_main_device(extra_args: Optional[Iterable[str]]) -> Optional[str]:
    """Return the last explicit main-device value, if any."""
    return _extra_args_device(extra_args, {"--device", "-dev"})


def _without_subsequence(tokens: List[str], run: List[str]) -> List[str]:
    """``tokens`` with the first contiguous occurrence of ``run`` removed.

    Only the exact flags Unsloth appended go, so a user's own identical flag
    elsewhere in the command survives. Unchanged when ``run`` is not present.
    """
    if not run:
        return list(tokens)
    for i in range(len(tokens) - len(run) + 1):
        if tokens[i : i + len(run)] == run:
            return [*tokens[:i], *tokens[i + len(run) :]]
    return list(tokens)


def _subsequence_index(tokens: List[str], run: List[str], hint: int) -> int:
    """Where ``run`` sits in ``tokens``, given it was appended at ``hint``.

    A stored index goes stale the moment anything narrows the argv ahead of it,
    and the arch gate does exactly that (dropping ``--split-mode`` /
    ``--tensor-split``), so the block can only ever move LEFT. Search back from
    the hint, then forward, so a future narrowing site cannot silently shift the
    slice and take neighbouring tokens with it.
    """
    span = len(tokens) - len(run)
    if not run or span < 0:
        return max(0, min(hint, len(tokens)))
    for i in range(min(hint, span), -1, -1):
        if tokens[i : i + len(run)] == run:
            return i
    for i in range(min(hint, span) + 1, span + 1):
        if tokens[i : i + len(run)] == run:
            return i
    return max(0, min(hint, len(tokens)))


_CPU_DEVICE_VALUES = frozenset({"cpu", "none"})


def _device_selection_is_cpu(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """True when the effective ``--device`` selection names no GPU.

    llama.cpp then runs the model on the CPU whatever the layer count says, so
    the weights are in pageable host RAM. argv wins over the env twin, and an
    unreadable value answers True like every other unknown in the gate.
    """
    value = _extra_args_main_device(extra_args)
    if value is None and env:
        value = env.get("LLAMA_ARG_DEVICE")
    if value is None:
        return False
    devices = [d.strip().lower() for d in str(value).split(",") if d.strip()]
    return not devices or all(d in _CPU_DEVICE_VALUES for d in devices)


def _split_mode_confines_to_one_device(
    args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """Whether the effective split mode confines all weights to one device."""
    try:
        mode = parse_split_mode_override(args)
    except ValueError:
        return False
    if mode is None and env:
        mode = env.get("LLAMA_ARG_SPLIT_MODE")
    return str(mode or "").strip().lower() == "none"


def _extra_args_draft_device(extra_args: Optional[Iterable[str]]) -> Optional[str]:
    """Return the last explicit draft-device value, if any."""
    return _extra_args_device(extra_args, {"--spec-draft-device", "-devd", "--device-draft"})


def _extra_args_draft_device_pin(extra_args: Optional[Iterable[str]]) -> Optional[str]:
    """Return a GPU draft-device override; cpu/none do not conflict with a pin."""
    last_dev = _extra_args_draft_device(extra_args)
    if last_dev is None:
        return None
    devs = [d.strip() for d in last_dev.split(",") if d.strip()]
    if not devs or all(d.lower() in ("cpu", "none") for d in devs):
        return None
    return last_dev


def _emitted_n_batch(n_batch: Optional[int], n_parallel: int) -> Optional[int]:
    """--batch-size the launch actually emits for a requested ``n_batch``.

    llama-server aborts below 2 and below the slot count, so the loader raises the
    flag to ``max(slots, 2)``. llama.cpp then derives the micro-batch from the
    raised value (``cparams.n_ubatch = min(cparams.n_batch, n_ubatch or n_batch)``),
    so every VRAM budget must be sized from it, not from the requested number, or a
    small batch with many slots is budgeted at a micro-batch the launch never uses.
    None (llama.cpp defaults) stays None: nothing is emitted, so nothing is raised.
    """
    if n_batch is None:
        return None
    return max(int(n_batch), max(2, int(n_parallel or 1)))


def _extra_args_split_mode(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    """Last-wins ``-sm`` / ``--split-mode`` value, lowercased, or None."""
    source_env = os.environ if env is None else env
    found: Optional[str] = None
    raw = source_env.get("LLAMA_ARG_SPLIT_MODE")
    if raw and str(raw).strip():
        found = str(raw).strip().lower()
    args = [str(a) for a in extra_args] if extra_args else []
    for i, arg in enumerate(args):
        name, _, inline = arg.partition("=")
        if name not in _SPLIT_MODE_FLAGS:
            continue
        value = inline if inline else (args[i + 1] if i + 1 < len(args) else "")
        if value.strip():
            found = value.strip().lower()
    return found


def _extra_args_tensor_split(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[list[float]]:
    """Last-wins ``-ts`` / ``--tensor-split`` proportions, or None.

    llama.cpp copies these into ``splits`` verbatim and prefix-sums them
    (llama-model.cpp:1436-1447), so they ARE the row-ownership weights that
    ``split_weights_per_device`` carries. Malformed parses to None rather than
    raising, which puts the load back on the decline path.

    The delimiter set is llama.cpp's own ``[,/]+`` (common/arg.cpp:2791-2804) and
    nothing else: ``-ts 3/1`` is exactly ``-ts 3,1`` to the child, while inventing
    extra delimiters is the same bug pointing the other way -- ``std::stof`` stops
    at the first non-numeric character, so ``-ts 3;1`` is ``[3, 0]``, not
    ``[3, 1]``.
    """
    source_env = os.environ if env is None else env
    raw: Optional[str] = None
    env_value = source_env.get("LLAMA_ARG_TENSOR_SPLIT")
    if env_value and str(env_value).strip():
        raw = str(env_value).strip()
    args = [str(a) for a in extra_args] if extra_args else []
    for i, arg in enumerate(args):
        name, _, inline = arg.partition("=")
        if name not in _TENSOR_SPLIT_FLAGS:
            continue
        value = inline if inline else (args[i + 1] if i + 1 < len(args) else "")
        if value.strip():
            raw = value.strip()
    if raw is None:
        return None
    try:
        parts = [float(p) for p in re.split(r"[,/]+", raw) if p.strip()]
    except ValueError:
        return None
    # isfinite, not just >= 0: float() takes "nan"/"inf", and NaN passes BOTH the
    # other tests (every comparison against NaN is false, sum() of a NaN list is
    # NaN). The caller's int(round(p * scale)) would then raise ValueError /
    # OverflowError with nothing catching it, aborting a load llama.cpp itself
    # merely degenerates on. Rejecting here routes it to the unparseable decline.
    if not parts or any(not math.isfinite(p) or p < 0 for p in parts) or sum(parts) <= 0:
        return None
    return parts


def _extra_args_n_parallel(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[int]:
    """Serving slots a pass-through overrides to, or None when nothing does.

    Same precedence as the launched command line: extras are appended last
    (llama_cpp.py emits Unsloth's --parallel first), and llama.cpp is last-wins,
    so an extras value beats both the emitted flag and the env. 0 is rejected at
    parse time on the server path, so it is not a value anyone gets.
    """
    source_env = os.environ if env is None else env
    found: Optional[int] = None
    raw = source_env.get("LLAMA_ARG_N_PARALLEL")
    if raw:
        try:
            found = int(str(raw).strip())
        except (TypeError, ValueError):
            pass
    args = [str(a) for a in extra_args] if extra_args else []
    for i, arg in enumerate(args):
        name, _, inline = arg.partition("=")
        if name not in ("-np", "--parallel"):
            continue
        value = inline if inline else (args[i + 1] if i + 1 < len(args) else "")
        try:
            found = int(value.strip())
        except (TypeError, ValueError):
            continue
    return found


def _extra_args_n_ubatch(
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
    n_ctx: Optional[int] = None,
    *,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
) -> Optional[int]:
    """Effective ubatch after llama.cpp normalizes it, or None at defaults.

    Precedence mirrors the launched command line: env, then the first-class
    n_batch / n_ubatch fields (emitted as flags, so they beat env), then user
    extra_args (appended last, so they last-wins-override the emitted flags).
    """
    values = {
        "batch": _DEFAULT_LLAMA_N_BATCH,
        "ubatch": _DEFAULT_LLAMA_N_UBATCH,
    }
    source_env = os.environ if env is None else env
    overridden = False
    for key, env_name in (
        ("batch", "LLAMA_ARG_BATCH"),
        ("ubatch", "LLAMA_ARG_UBATCH"),
    ):
        raw = source_env.get(env_name)
        if raw:
            try:
                values[key] = int(raw)
                overridden = True
            except (TypeError, ValueError):
                pass

    if n_batch is not None:
        values["batch"] = int(n_batch)
        overridden = True
    if n_ubatch is not None:
        values["ubatch"] = int(n_ubatch)
        overridden = True

    args = [str(a) for a in extra_args] if extra_args else []
    flags = {
        "-b": "batch",
        "--batch-size": "batch",
        "-ub": "ubatch",
        "--ubatch-size": "ubatch",
    }
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        key = flags.get(flag)
        if key is None:
            continue
        value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
        try:
            values[key] = int(value)
            overridden = True
        except (TypeError, ValueError):
            continue
    if not overridden:
        return None

    # common_params stores signed values, then llama_context_params converts
    # them to uint32_t. A zero ubatch means "use batch"; the context then caps
    # ubatch at batch size.
    batch = values["batch"] & 0xFFFFFFFF
    raw_ubatch = values["ubatch"]
    ubatch = batch if raw_ubatch == 0 else raw_ubatch & 0xFFFFFFFF
    effective = min(batch, ubatch)
    if n_ctx is not None and n_ctx > 0:
        effective = min(effective, n_ctx)
    return effective


def _build_ngram_mod_flags(
    caps: Optional[dict],
    n_match: int = 24,
    n_min: int = 48,
    n_max: int = 64,
) -> list[str]:
    """Emit the right ngram-mod knob flags for the running llama-server.

    Post-rename builds expose ``--spec-ngram-mod-n-{match,min,max}``;
    pre-rename builds expose legacy ``--spec-ngram-size-n`` /
    ``--draft-min`` / ``--draft-max``. ``caps`` comes from
    ``probe_server_capabilities``; ``ngram_mod_flavor`` says which set is
    real (vs a removal-stub). Returns ``[]`` when neither is available so
    the caller can drop ngram-mod entirely.
    """
    flavor = caps.get("ngram_mod_flavor") if caps else None
    if flavor == "new":
        return [
            "--spec-ngram-mod-n-match",
            str(n_match),
            "--spec-ngram-mod-n-min",
            str(n_min),
            "--spec-ngram-mod-n-max",
            str(n_max),
        ]
    if flavor == "legacy":
        # Pre-rename llama.cpp: same knobs lived under --spec-ngram-size-n
        # (lookup length) and generic --draft-min / --draft-max (N range).
        return [
            "--spec-ngram-size-n",
            str(n_match),
            "--draft-min",
            str(n_min),
            "--draft-max",
            str(n_max),
        ]
    return []


# Canonical Speculative Decoding modes exposed by the Unsloth chat UI.
# Dropdown renders seven (auto, mtp, dspark, dflash, ngram, mtp+ngram, off); the
# load API also accepts legacy values the original Switch and external callers
# emit (default, draft-mtp, ngram-mod, ngram-simple).
_CANONICAL_SPEC_MODES = {
    "auto",
    "mtp",
    "dspark",
    "dflash",
    "ngram",
    "mtp+ngram",
    "off",
    "ngram-simple",
}
_LEGACY_SPEC_MODE_MAP = {
    "default": "auto",
    "draft-mtp": "mtp",
    "draft-dspark": "dspark",
    "draft-dflash": "dflash",
    "ngram-mod": "ngram",
}


def _canonicalize_spec_mode(value):
    """Map any accepted ``speculative_type`` input onto a canonical mode.

    Returns ``auto``, ``mtp``, ``dspark``, ``dflash``, ``ngram``, ``mtp+ngram``,
    ``off``, ``ngram-simple``, or ``None`` (callers treat ``None`` as ``auto``).
    Unknown strings collapse to ``auto`` so a stale UI value or typo falls
    back to the safe platform-aware path.
    """
    if value is None:
        return None
    if not isinstance(value, str):
        return None
    stripped = value.strip().lower()
    if not stripped:
        return None
    if stripped in _CANONICAL_SPEC_MODES:
        return stripped
    if stripped in _LEGACY_SPEC_MODE_MAP:
        return _LEGACY_SPEC_MODE_MAP[stripped]
    # Old persisted state emits llama.cpp comma-chains e.g.
    # "ngram-mod,draft-mtp"; collapse the most common one explicitly.
    pieces = [p.strip() for p in stripped.split(",") if p.strip()]
    has_mtp = any(p in ("mtp", "draft-mtp") for p in pieces)
    has_ngram = any(p in ("ngram", "ngram-mod") for p in pieces)
    if has_mtp and has_ngram:
        return "mtp+ngram"
    if has_mtp:
        return "mtp"
    if has_ngram:
        return "ngram"
    return "auto"


def _backfill_usage_from_timings(usage, timings):
    """Synthesize ``usage`` from llama-server's ``timings`` when the
    OpenAI-style usage block is missing or reports zero tokens.

    The Unsloth chat UI computes generation t/s from
    ``meta.usage.completion_tokens / totalStreamTime``. llama-server always
    populates ``timings.predicted_n`` (true decoded count) and
    ``timings.prompt_n``, but the final SSE chunk's ``usage`` can be absent
    or zero on some server builds / streaming configs, making the UI fall
    back to wall-clock t/s and dilute speculative-decoding speedups.
    """
    if not timings:
        return usage
    if usage and usage.get("completion_tokens"):
        return usage
    predicted_n = timings.get("predicted_n")
    prompt_n = timings.get("prompt_n")
    if predicted_n is None and prompt_n is None:
        return usage
    out = dict(usage or {})
    if not out.get("completion_tokens") and predicted_n is not None:
        out["completion_tokens"] = predicted_n
    if not out.get("prompt_tokens") and prompt_n is not None:
        out["prompt_tokens"] = prompt_n
    out["total_tokens"] = int(out.get("prompt_tokens") or 0) + int(
        out.get("completion_tokens") or 0
    )
    return out


def _report_live_llama_timings(callback, chunk) -> None:
    """Report request-scoped llama.cpp progress without altering the public stream."""
    if callback is None or not isinstance(chunk, dict):
        return
    timings = chunk.get("timings")
    sample = dict(timings) if isinstance(timings, dict) else {}
    # Live samples are not TTFT; terminal metadata retains prompt_ms for the fallback.
    sample.pop("prompt_ms", None)
    progress = chunk.get("prompt_progress")
    if isinstance(progress, dict):
        try:
            processed = max(0.0, float(progress.get("processed", 0)))
            cached = max(0.0, float(progress.get("cache", 0)))
            elapsed_ms = float(progress.get("time_ms", 0))
            prompt_n = max(0.0, processed - cached)
            if math.isfinite(elapsed_ms) and elapsed_ms > 0 and math.isfinite(prompt_n):
                sample.update(
                    prompt_n = prompt_n,
                    prompt_per_second = prompt_n / (elapsed_ms / 1000.0),
                )
        except (TypeError, ValueError, OverflowError):
            pass
    if not sample:
        return
    try:
        callback(sample)
    except Exception:
        logger.debug("Ignoring API monitor throughput callback failure", exc_info = True)


# Host RAM to leave free on an integrated GPU, matching llama.cpp's own --fit
# margin (default 1024 MiB per device). ggml reports an iGPU's "VRAM" as shared
# system RAM, so hold back the same margin rather than inventing a larger one.
_IGPU_HOST_RESERVE_MIB = 1024
_HOST_RAM_HEADROOM_MIB = 2048
# Appended to whichever shortfall warning an oversized non-pageable launch produced,
# after _page_an_oversized_unmapped_load rewrote the mode. One string, so the three
# call sites cannot describe the same override differently.
_PAGEABLE_OVERRIDE_NOTE = (
    " This model was set to load without memory mapping, which reads every byte into "
    "RAM up front and cannot complete at this size, so Unsloth loaded it with memory "
    "mapping instead."
)
# What memory_warning says when the text-only fallback removed the CPU-pinned projector
# whose bytes were what made the load oversized, on a launch that had already had its
# unmapped load mode overridden for that shortfall. The override is REPORTED and not
# taken back: the argv was rewritten and spawned, and force_pageable_load rewrote the
# shared child env in place, so the running server is memory-mapped whatever this says.
_PAGEABLE_OVERRIDE_TEXT_ONLY_NOTICE = (
    "This model was set to load without memory mapping, and with its vision projector "
    "in system RAM it was too large to load that way, so Unsloth loaded it with memory "
    "mapping instead. The projector then failed to start and this session is text-only, "
    "which the weights alone would have fit. The running server keeps the memory "
    "mapping it started with; load the model again to run it as you asked."
)
_CGROUP_ROOT = "/sys/fs/cgroup"
_PROC_SELF_CGROUP = "/proc/self/cgroup"


def _apply_igpu_host_reserve_mib(free_mib: int, is_igpu: bool) -> int:
    """Reserve host headroom on an integrated (shared-memory) Vulkan GPU.

    An iGPU's reported free "VRAM" is really free system RAM, so sizing
    context/offload against all of it would push the host into swap or the OOM
    killer. Leave the same margin llama.cpp's --fit uses. ``is_igpu`` comes from
    ggml's device type, so a discrete card is never touched; only ever reduces.
    """
    if not is_igpu:
        return free_mib
    return max(0, free_mib - _IGPU_HOST_RESERVE_MIB)


def _resolve_llama_binary(binary: str, *, template_only: bool = False) -> Path:
    """Resolve a managed symlink or shell entrypoint to the real server.

    Follows a chain rather than one hop. A wrapper whose target is another
    wrapper used to resolve to the intermediate script, which on macOS is the
    same defect this is here to avoid (SIP drops DYLD_* through the shell) and
    also gives _llama_lib_dir the wrong directory, so the loader path would
    point at the wrapper's folder instead of the one holding the dylibs.
    Bounded, and stops on a repeat, so a wrapper pair pointing at each other
    cannot spin.

    ``template_only`` stops at the first link that is not the installer's own
    template. Two callers, two different questions. Finding the dylibs wants
    the end of the chain whatever it is made of, because that is where they
    sit. Choosing what to LAUNCH must not step over somebody's own script:
    checking only the outer entrypoint meant an installer-shaped symlink whose
    target was a hand-written wrapper had that wrapper's exports skipped, even
    though running the symlink directly would have executed them.
    """
    resolved = Path(binary).resolve()
    seen = {resolved}
    for _ in range(8):
        try:
            with open(resolved, "rb") as _f:
                _head = _f.read(256)
        except OSError:
            break
        if not _head.startswith(b"#!"):
            break
        _m = re.search(r'exec "\$\(dirname "\$0"\)/([^"]+)"', _head.decode("utf-8", "ignore"))
        if not _m:
            break
        if template_only and not _is_installer_entrypoint(str(resolved)):
            break
        nxt = (resolved.parent / _m.group(1)).resolve()
        if nxt in seen:
            break
        seen.add(nxt)
        resolved = nxt
    return resolved


def _llama_lib_dir(binary: str) -> Path:
    return _resolve_llama_binary(binary).parent


# install_llama_prebuilt.write_exec_wrapper emits exactly this and nothing else:
# a shebang, one exec line, a trailing newline. Anything more is somebody's own
# script, whose extra lines are the whole reason not to skip past it.
_INSTALLER_WRAPPER_RE = re.compile(
    r"\A#!/bin/sh\n" r'exec "\$\(dirname "\$0"\)/[^"\n]+" "\$@"\n?\Z'
)


def _is_installer_entrypoint(binary: str) -> bool:
    """Is ``binary`` an entrypoint the installer itself wrote?

    Symlinks and real executables qualify: neither carries setup that could be
    lost by launching the target instead. A shell script only qualifies when it
    matches the installer's template exactly, so a user's wrapper that exports
    variables before its exec line is launched as written.

    Kept separate from _resolve_llama_binary, which must keep resolving ANY
    wrapper: _llama_lib_dir needs the directory holding the dylibs, and that is
    the target's directory whoever wrote the wrapper.
    """
    try:
        path = Path(binary)
        if path.is_symlink():
            return True
        with open(path, "rb") as fh:
            head = fh.read(4096)
    except OSError:
        return True
    if not head.startswith(b"#!"):
        return True
    return bool(_INSTALLER_WRAPPER_RE.match(head.decode("utf-8", "ignore")))


def _loader_path_var() -> str:
    """The platform's shared-library search env var.

    dyld ignores LD_LIBRARY_PATH entirely, so a macOS child launched with only
    that variable set has no search path at all. Same mapping as the sibling
    engines (sd_cpp_engine._lib_path_var, stt_ggml_sidecar) and as the
    installer's own staged-binary validation.
    """
    if sys.platform == "darwin":
        return "DYLD_LIBRARY_PATH"
    if sys.platform == "win32":
        return "PATH"
    return "LD_LIBRARY_PATH"


def _prepend_loader_dir(existing: str, lib_dir: str) -> str:
    """``lib_dir`` first in a loader search path, with no repeats.

    Deduplicates on the normalised spelling, so an inherited "/x/bin/" or
    "/x/./bin" does not survive alongside the "/x/bin" being prepended and the
    result is stable however many times it is fed back in. Purely textual:
    realpath would touch the filesystem, and a dead network mount on an
    inherited entry must not stall a model load. Entries keep the spelling they
    arrived with, since that is what the loader is given.
    """
    out: list[str] = []
    seen: set[str] = set()
    for entry in (lib_dir, *existing.split(os.pathsep)):
        if not entry:
            continue
        key = os.path.normcase(os.path.normpath(entry))
        if key in seen:
            continue
        seen.add(key)
        out.append(entry)
    return os.pathsep.join(out)


_CPU_RUNTIME_OWNER_FILE = "UNSLOTH_OWNER_PID"

# GPU backends the staged CPU-only runtime must not carry over. Module level: compiled once.
_GGML_GPU_BACKEND_RE = re.compile(
    r"^(?:lib)?ggml-(?:cuda|hip|vulkan|metal|sycl|opencl|musa|cann|virtgpu)"
)


def _cpu_runtime_owner_alive(staged_dir: Path) -> bool:
    """Whether a live process still owns this staged CPU-fallback runtime."""
    try:
        pid = int((staged_dir / _CPU_RUNTIME_OWNER_FILE).read_text(encoding = "utf-8").strip())
    except (OSError, ValueError):
        # No owner stamp: written by an older Unsloth, so leave it alone.
        return True
    if pid == os.getpid():
        return True
    # 0 and negatives address process groups, never an owner.
    if pid <= 0:
        return False
    if sys.platform == "win32":
        import ctypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error = True)
        ctypes.set_last_error(0)
        handle = kernel32.OpenProcess(0x00100000, False, pid)
        if not handle:
            return ctypes.get_last_error() != 87  # ERROR_INVALID_PARAMETER
        kernel32.CloseHandle(handle)
        return True
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except OSError:
        return True
    return True


def _sweep_abandoned_cpu_runtimes(runtime_root: Path) -> None:
    """Delete staged runtimes whose owning Unsloth is gone (kill -9, host crash)."""
    try:
        candidates = list(runtime_root.glob("llama-cpu-*"))
    except OSError:
        return
    for staged_dir in candidates:
        if not staged_dir.is_dir() or _cpu_runtime_owner_alive(staged_dir):
            continue
        with contextlib.suppress(OSError):
            shutil.rmtree(staged_dir, ignore_errors = True)


def _lib_dir_has_ggml_backend(lib_dir: Path, backend: str) -> bool:
    """Match an exact or versioned ggml backend library soname."""
    stem = f"ggml-{backend}.dll" if sys.platform == "win32" else f"libggml-{backend}.so"
    try:
        return any(
            f.name == stem or f.name.startswith(stem + ".")
            for f in lib_dir.iterdir()
            if f.is_file()
        )
    except OSError:
        return False


def _is_external_link(path: Path) -> bool:
    """True when ``path`` is a --with-llama-cpp-dir local link: a POSIX symlink
    or a Windows directory junction / reparse point. Such a link resolves into
    the user's own llama.cpp checkout, which Unsloth does not own."""
    try:
        if os.path.islink(path):
            return True
    except OSError:
        return False
    if os.name == "nt":
        try:
            import stat
            attrs = os.lstat(path).st_file_attributes  # type: ignore[attr-defined]
            return bool(attrs & stat.FILE_ATTRIBUTE_REPARSE_POINT)
        except (OSError, AttributeError):
            return False
    return False


# Inkling's template takes a numeric thinking-effort dial (0..0.99) and its
# float() coercion turns unrecognized named levels into 0, i.e. no thinking.
# Map OpenAI-style names to the values the model was trained on. Module-level
# so duck-typed engine stand-ins in tests do not need the attribute.
_INKLING_REASONING_EFFORT = {
    "none": 0.0,
    "minimal": 0.1,
    "low": 0.2,
    "medium": 0.7,
    "high": 0.9,
    "xhigh": 0.99,
    "max": 0.99,
}


def _coerce_reasoning_effort(architecture, kwargs: dict) -> dict:
    if architecture == "inkling":
        effort = kwargs.get("reasoning_effort")
        if isinstance(effort, str):
            mapped = _INKLING_REASONING_EFFORT.get(effort.strip().lower())
            if mapped is not None:
                kwargs["reasoning_effort"] = mapped
    return kwargs


class CountAborted(Exception):
    """A token count stood down mid-flight because its answer stopped mattering."""

    __slots__ = ()


# Module level so tests can point the orphan sweep at a fixture tree.
_PROC_ROOT = "/proc"


class LlamaCppBackend:
    """Manages a llama-server subprocess for GGUF model inference.

    Lifecycle:
        1. load_model(): start llama-server with the GGUF file
        2. generate_chat_completion(): proxy to /v1/chat/completions, stream back
        3. unload_model(): terminate the subprocess
    """

    def __init__(self, *, manages_processes: bool = True):
        """``manages_processes = False`` builds an INERT probe.

        The constructor is not free: it reaps orphaned llama-servers, walking /proc,
        resolving each candidate's exe and signalling the ones it recognises, then
        registers an atexit handler holding this instance for the life of the process.
        Both are right for the backend that owns a child, neither for a probe that only
        reads a header -- and since the memory-estimate route those helpers run on every
        settings change. Measured on one estimate: five constructions, five /proc scans,
        five atexit handlers, never released, so fifty estimates left 250 of them
        holding 250 backends.

        Default True, so every existing caller keeps today's behaviour.
        """
        self._process: Optional[subprocess.Popen] = None
        self._port: Optional[int] = None
        # Advisory memory notice from the load in flight, handed back on LoadResponse.
        # Reset by _begin_load_warnings so one load's notice is never reported against
        # the next.
        self._last_load_warning: Optional[str] = None
        self._model_identifier: Optional[str] = None
        self._gguf_path: Optional[str] = None
        # Snapshot of the exact file(s) handed to the resident process. A local
        # link can be atomically retargeted while `_gguf_path` stays unchanged.
        self._gguf_load_identity: Optional[tuple] = None
        self._hf_repo: Optional[str] = None
        # Separate MTP drafter launched with the current model; reload-dedup
        # key so a drafter that appears next to the weights forces a reload.
        self._mtp_draft_path: Optional[str] = None
        # Drafter this load resolved then deliberately suppressed (virtualised Metal
        # with no draft-layer flag). The dedup keys on the drafter the caller asked
        # for, still on disk, so without this the detected path never matches the
        # launched None and every repeat Apply tears down a healthy server.
        self._mtp_draft_suppressed_path: Optional[str] = None
        # Why MTP was disabled on the last load that asked for it (auto on an
        # MTP model, or forced mtp / mtp+ngram), else None. Drives the "update
        # llama.cpp" hint in the UI. "binary_no_mtp" / "binary_outdated" ->
        # a newer prebuilt would help; "runtime_error" -> it may not.
        self._spec_fallback_reason: Optional[str] = None

        # How a requested multimodal projector recovered at startup. `cpu_offload`
        # keeps vision; the other values accompany a deliberate text-only retry.
        self._mmproj_fallback_reason: Optional[str] = None
        # Whether THIS load ran against a probe that did not answer, rather than one
        # that answered "no". An inconclusive probe reports every capability absent, so it
        # silently degrades speculative decoding, the DSpark sidecar and the --kv-unified
        # slot clamp alike. Separate from _spec_fallback_reason, whose UI banner stays
        # suppressed for an unresolved probe, so a reload can still be judged worth
        # retrying (#8317).
        self._capability_probe_inconclusive: bool = False
        self._spec_drafter_kind: Optional[str] = None
        self._dspark_sidecar_absent: bool = False
        self._dflash_sidecar_absent: bool = False
        # Sidecar fetch lost to a blip, not to the repo lacking one
        # (_dflash_sidecar_absent). Worth one more Apply: under Auto nothing else
        # records that the load ended up with no drafter.
        self._dflash_retry_needed: bool = False
        # Which llama-server file this load ran. `unsloth studio update` replaces it
        # in place, so a stand-down blamed on the binary can spot a real update.
        self._launch_binary_revision: tuple = ()
        # Binary a load has selected but not necessarily spawned yet. None means
        # no load is pending; the settings route compares a populated revision
        # before is_active becomes true so a concurrent path save cannot hide a
        # required reload.
        self._binary_revision_pending: Optional[tuple] = None
        # Set after an auto-Vulkan crash recovers with all devices disabled.
        self._cpu_fallback_reason: Optional[str] = None
        self._cpu_fallback_runtime: Optional[_CpuFallbackRuntime] = None
        self._pending_cpu_fallback_cleanups: list = []
        self._hf_variant: Optional[str] = None
        self._is_vision: bool = False
        # Vision deliberately left unloaded by the caller. Tracked so a reload that
        # flips the toggle cannot be satisfied by the live server, which opened a
        # different set of files, and echoed to the client so the switch can reseed
        # from the load it actually ran.
        self._disable_vision: bool = False
        # Narrower than the raw request: image input is off because the user asked,
        # not because the model has no usable projector. Only a model that HAS one
        # can have had it switched off, and the client needs the distinction to point
        # at the switch rather than at a missing file.
        self._vision_disabled_by_user: bool = False
        # Block-diffusion model (e.g. DiffusionGemma): served by the diffusion
        # runner, not llama-server. Set from the GGUF architecture at load.
        self._architecture: Optional[str] = None
        self._is_diffusion: bool = False
        # Whole header walked? Separates "declares no architecture" from "unreadable".
        self._gguf_header_parsed: bool = False
        self._gguf_split_index: Optional[int] = None
        self._diffusion_visual_bin: Optional[str] = None
        self._healthy = False
        self._load_rss_hwm = (None, 0)  # (pid, peak VmRSS) for load_progress
        self._stats_logger = None  # vLLM-style engine-stats poller, set on load
        # Set by _classify_gpu_offload after _wait_for_health.
        self._gpu_offload_active: Optional[bool] = None
        # Diffusion only: the split the running child was asked for.
        self._diffusion_requested_ngl: Optional[int] = None
        self._context_length: Optional[int] = None
        self._effective_context_length: Optional[int] = None
        self._max_context_length: Optional[int] = None
        self._effective_parallel_slots: int = 1
        # --parallel the last load asked for, before any fit-time reduction.
        self._requested_n_parallel: int = 1
        # Budget the running child was sized against; None before any load, so the
        # settings route reports a stale budget instead of nagging on every save.
        self._vram_fraction_launched: Optional[float] = None
        # Budget a load has committed to but not published, covering planning ->
        # Popen as _memory_launch_pending does for Model Memory placement.
        self._vram_fraction_pending: Optional[float] = None
        # --batch-size / --ubatch-size the last load asked for; none = defaults or extras / env
        self._requested_n_batch: Optional[int] = None
        self._requested_n_ubatch: Optional[int] = None
        # The tuning group the last load asked for; none = defaults, or left to
        # extras / env. What was REQUESTED, not what ran: Model Memory can replace
        # the load mode, and Windows full-offload tuning owns the two cache knobs.
        self._requested_load_mode: Optional[str] = None
        self._requested_spec_draft_cache_type: Optional[str] = None
        self._requested_ctx_checkpoints: Optional[int] = None
        self._requested_cache_ram: Optional[int] = None
        self._chat_template: Optional[str] = None
        self._markup_tokens: list = []
        self._markup_profile = None
        self._chat_template_override: Optional[str] = None
        self._supports_reasoning: bool = False
        self._reasoning_always_on: bool = False
        self._reasoning_style: str = "enable_thinking"
        self._reasoning_effort_levels: list = []
        self._supports_preserve_thinking: bool = False
        self._preserve_thinking_default: bool = False
        self._supports_tools: bool = False
        self._cache_type_kv: Optional[str] = None
        # Whether --split-mode tensor was applied on the active load.
        self._tensor_parallel: bool = False
        # GPU memory strategy applied on the active load ("auto"/"manual").
        self._gpu_memory_mode: str = "auto"
        # Manual-mode load options (echoed back so the UI round-trips them).
        self._gpu_layers: int = -1
        # MoE expert layers to keep on CPU (--n-cpu-moe); 0 = none.
        self._n_cpu_moe: int = 0
        # Relative model share per GPU (--tensor-split), in GPU order; None =
        # default (llama.cpp splits by free VRAM).
        self._tensor_split: Optional[List[float]] = None
        # Tokens the tensor-spill plan added to this argv, so a retry that re-places
        # the model can strip them with _without_subsequence. Empty when it abstained.
        self._spill_plan_flags: List[str] = []
        # Ratio the arch gate dropped from this argv, so the duplicate-load check
        # knows the live server already IS this request normalized (#7624).
        self._arch_gate_dropped_tensor_split: Optional[tuple[float, ...]] = None
        # Same for the split MODE: the gate drops --split-mode tensor when it forces
        # CPU or leaves one survivor, and the request still asks for it.
        self._arch_gate_dropped_tensor_parallel: bool = False
        # Gate masked every device away, so an AUTOMATIC request became a zero-VRAM
        # launch (#7624), which is why holds_no_vram cannot demand manual mode.
        self._arch_gate_forced_cpu: bool = False
        # User-picked physical GPU indices (None = automatic selection).
        self._gpu_ids: Optional[List[int]] = None
        # RAW requested GPU pin, before the fit narrowed it. self._gpu_ids records the
        # EFFECTIVE (fit-narrowed) pin for /status; dedupe compares this raw value so a
        # [0, 1] narrowed to [0] and re-sent as [0, 1] still matches (#7239).
        self._requested_gpu_ids: Optional[List[int]] = None
        # Layer load kept multi-GPU only to honor a downgraded tensor request, so a
        # later explicit tensor-off reloads instead of deduping to it (#6659).
        self._layer_preserves_tensor_intent: bool = False
        self._reasoning_default: bool = True
        self._speculative_type: Optional[str] = None
        # Canonical UI-facing mode the user requested
        # (auto/mtp/ngram/mtp+ngram/off/ngram-simple). Round-tripped through the
        # status API so the dropdown reflects the picked mode, not the resolved
        # flag set (auto on a 27B MTP GGUF resolves to draft-mtp but reads "Auto").
        self._requested_spec_mode: Optional[str] = None
        # User --spec-draft-n-max override (None = platform default).
        self._spec_draft_n_max: Optional[int] = None
        # KV-cache estimation fields (populated by _read_gguf_metadata)
        self._n_layers: Optional[int] = None
        # MoE metadata (populated by _read_gguf_metadata): expert count (>0 =
        # MoE) and leading dense-layer count (offsets --n-cpu-moe, which counts
        # from layer 0). See the n_moe_layers property.
        self._n_experts: Optional[int] = None
        self._leading_dense_block_count: Optional[int] = None
        self._n_kv_heads: Optional[int] = None
        self._n_kv_heads_by_layer: Optional[list[int]] = None
        self._n_heads: Optional[int] = None
        self._embedding_length: Optional[int] = None
        # llama_pooling_type from the GGUF; present and non-zero marks an embedding model.
        self._pooling_type: Optional[int] = None
        # For the compute-graph buffer estimate; vocab from the tokens array len.
        self._feed_forward_length: Optional[int] = None
        self._vocab_size: Optional[int] = None
        # Architecture-aware KV fields for 5-path estimation
        self._kv_key_length: Optional[int] = None
        self._kv_value_length: Optional[int] = None
        self._sliding_window: Optional[int] = None
        self._sliding_window_pattern: Optional[list[bool]] = None
        self._full_attention_interval: Optional[int] = None
        self._kv_lora_rank: Optional[int] = None
        self._key_length_mla: Optional[int] = None
        self._kv_key_length_swa: Optional[int] = None
        self._kv_value_length_swa: Optional[int] = None
        self._ssm_inner_size: Optional[int] = None
        self._ssm_state_size: Optional[int] = None
        self._ssm_group_count: Optional[int] = None
        self._ssm_conv_kernel: Optional[int] = None
        self._kda_head_dim: Optional[int] = None
        # Last N layers reuse earlier layers' KV and don't allocate their own
        # cache (Gemma 3n / Gemma 4: <arch>.attention.shared_kv_layers).
        self._shared_kv_layers: Optional[int] = None
        # MTP head count (llama.cpp #22673); >0 enables --spec-type draft-mtp.
        self._nextn_predict_layers: Optional[int] = None
        self._lock = threading.Lock()
        # Wraps load_model() end-to-end so concurrent loads serialise and never
        # coexist as two llama-server processes (#5401). RLock so MTP-crash
        # recovery can re-acquire it for its nested load_model.
        self._serial_load_lock = threading.RLock()
        # Serialises mid-session respawns so many generations hitting a killed
        # server trigger at most one reload (see _respawn_if_dead).
        self._respawn_lock = threading.Lock()
        # Bumped by every unload. load_model clears _cancel_event, so a respawn that
        # raced an unload needs a signal that survives the clear (see _respawn_if_dead).
        self._unload_epoch = 0
        # Set by the in-app updater while it swaps prebuilt binaries; load_model()
        # rejects fast so no server starts from a half-swapped binary.
        self._llama_update_in_progress = False
        # Last extra_args / requested n_ctx, preserved across unload so the chat
        # UI's /unload+/load Apply path can inherit them (#5401).
        # ``_extra_args_source`` records the (model_identifier, hf_variant) the
        # stored args came from so the route can refuse cross-model inheritance.
        self._extra_args: Optional[List[str]] = None
        # Extras as REQUESTED, before a launch-time rewrite (the virtualised-Metal
        # drafter drop strips the spec group), so the duplicate-load comparators can
        # compare requested-vs-requested like _requested_n_ctx does.
        self._requested_extra_args: Optional[List[str]] = None
        self._extra_args_source: Optional[tuple[str, Optional[str]]] = None
        self._requested_n_ctx: int = 0
        # Last healthy caller intent for crash recovery. Memory-only and never logged.
        self._last_load_intent: Optional[GgufLoadIntent] = None
        self._mtp_runtime_fallback_lock = threading.Lock()
        self._mtp_runtime_fallback_in_progress = False
        # Background watchdog so an MTP+tensor crash recovers even when no request
        # observes it (direct proxy endpoints, or nothing in flight).
        self._mtp_watchdog_thread: Optional[threading.Thread] = None
        self._mtp_watchdog_stop = threading.Event()
        # True when the launch actually runs MTP+tensor (Unsloth- or user/env-driven);
        # gates the probe, watchdog, and recovery so pass-through MTP is covered.
        self._mtp_runtime_fallback_active = False
        self._stdout_lines: list[str] = []
        self._stdout_thread: Optional[threading.Thread] = None
        # Wakes the health probe on subprocess readiness/exit, so a ready or crashed
        # server is not hidden behind the 500 ms fallback poll.
        self._health_probe_event = threading.Event()
        # llama-server tee log (see _drain_stdout / _kill_process).
        self._llama_log_fh = None
        self._llama_log_path: Optional[Path] = None
        self._cancel_event = threading.Event()
        self._api_key: Optional[str] = None
        self._slot_save_dir: Optional[str] = None
        self._slot_save_binary: Optional[tuple[str, int]] = None
        # (gguf_identity, launch_fingerprint) snapshotted at load, so a later slot
        # save can tell whether the model files were swapped on disk since load.
        self._slot_loaded_identity: Optional[tuple] = None
        self._prompt_cache_disabled: bool = False
        self._swa_full: bool = False
        self._kv_cache_unified: bool = False
        # (mlock, reserves_ram) the running process was launched with, or None
        # when this policy does not govern it (the diffusion runner has no
        # load-mode). _memory_policy_active records that the launch differed
        # from an unmanaged one, so disabling the toggles can undo it.
        self._memory_state: Optional[tuple[bool, bool]] = None
        self._memory_policy_active: bool = False
        # False when a launch is fully offloaded to a discrete GPU, where
        # page-locking host RAM is skipped on purpose.
        self._memory_mlock_applicable: bool = True
        # The "--load-mode none" tokens the FIT emitted, so paths that replace the
        # placement can take them back out. Empty for a mode the user asked for.
        self._fit_load_mode_flags: list[str] = []
        # True between recording a launch's placement and the child being
        # spawned, so a save landing in that window still has a launch to
        # compare against.
        self._memory_launch_pending: bool = False
        # True when the resident model came from an explicit UI load rather than
        # the OpenAI API, so the idle unload can be scoped to API-loaded models.
        # Not on GgufLoadIntent: that is compared for equality to detect
        # duplicate loads, and a provenance field there would force a reload.
        self._loaded_by_user_action: bool = False
        self._n_ubatch: int = self._DEFAULT_N_UBATCH
        self._flash_attn_enabled: bool = True
        self._effective_cache_types: tuple[str, str] = ("f16", "f16")
        # The pair this load ASKED for, before any launch-time rewrite.
        self._requested_cache_types: tuple[str, str] = ("f16", "f16")
        # Total KV allocation context across all slots. _effective_context_length
        # becomes the per-slot request limit after /props reconciliation.
        self._kv_cache_context_total: Optional[int] = None
        # True once a probe has completed; cleared on transient failure.
        self._is_audio: bool = False
        self._audio_type: Optional[str] = None
        self._audio_probed: bool = False
        # Audio INPUT capability (distinct from _is_audio, which is TTS output).
        self._has_audio_input: bool = False
        # Video INPUT capability, from llama-server's /props modalities. True
        # only when the mmproj, the build and ffmpeg all line up, none of which
        # the GGUF alone can tell us.
        self._has_video_input: bool = False
        self._mmproj_has_audio: bool = False  # clip.has_audio_encoder, set at load
        # clip.has_vision_encoder, set at load; True keeps an undeclared projector capable.
        self._mmproj_accepts_image: bool = True
        # Monotonic timestamp set in _kill_process; read by load_model
        # to decide whether to wait for the VRAM reclaim to finish.
        self._last_kill_monotonic: float = 0.0

        if manages_processes:
            _reaped = self._kill_orphaned_servers()
            if _reaped:
                # Reaped VRAM frees lazily; arm the settle wait so the first load
                # waits before ranking GPUs by free memory.
                self._last_kill_monotonic = time.monotonic()
            atexit.register(self._cleanup)

    # ── Properties ────────────────────────────────────────────────

    @property
    def is_loaded(self) -> bool:
        return self._process is not None and self._healthy

    @property
    def is_active(self) -> bool:
        """True if a llama-server process exists (loading or loaded)."""
        return self._process is not None

    @property
    def base_url(self) -> str:
        return f"http://127.0.0.1:{self._port}"

    @property
    def _auth_headers(self) -> "Optional[dict[str, str]]":
        """Bearer header matching the --api-key direct-stream mode uses, else
        None (so unauthenticated llama-server calls don't get a spurious 401)."""
        return {"Authorization": f"Bearer {self._api_key}"} if self._api_key else None

    @property
    def model_identifier(self) -> Optional[str]:
        return self._model_identifier

    @property
    def is_vision(self) -> bool:
        """Whether this model takes image input; ``_is_vision`` only records that a
        projector was attached, which happens for audio input too."""
        return self._is_vision and self._mmproj_accepts_image

    @property
    def is_diffusion(self) -> bool:
        """True when the loaded GGUF is a block-diffusion model (DiffusionGemma)."""
        return self._is_diffusion

    @property
    def swa_full(self) -> bool:
        """Whether the active llama-server received full-size SWA mode."""
        return self._swa_full

    @property
    def hf_variant(self) -> Optional[str]:
        return self._hf_variant

    @property
    def gguf_path(self) -> Optional[str]:
        return self._gguf_path

    @property
    def hf_repo(self) -> Optional[str]:
        """HF repo of the loaded model, or None for local/native file loads."""
        return self._hf_repo

    @property
    def mtp_draft_path(self) -> Optional[str]:
        return self._mtp_draft_path

    @property
    def mtp_draft_suppressed_path(self) -> Optional[str]:
        """Drafter the last load resolved and then dropped on purpose, else None.
        Duplicate-load checks accept it alongside mtp_draft_path so a drafter still on
        disk does not read as a settings change."""
        return self._mtp_draft_suppressed_path

    @property
    def spec_fallback_reason(self) -> Optional[str]:
        """Why MTP was disabled on the last MTP-requesting load, else None."""
        return self._spec_fallback_reason

    @property
    def mmproj_fallback_reason(self) -> Optional[str]:
        """How the active model recovered from an mmproj startup failure, else None."""
        return self._mmproj_fallback_reason

    def _binary_changed_since_launch(self) -> bool:
        """Whether a different llama-server is installed than the live one was launched
        from. False when either side is unreadable, so an install still in flight is not
        read as a finished one; the next Apply asks again."""
        # Same path space as the launch recorded: _binary_revision keys on the
        # path string, and on macOS the launch resolves a managed entrypoint to
        # its target, so comparing an unresolved discovery path against it would
        # differ for the same unchanged file and reload the model on every Apply.
        return self._binary_changed_since_revision(self._launch_binary_revision)

    def _binary_changed_since_revision(self, revision: tuple) -> bool:
        """Whether the current selection differs from a captured binary."""
        # No captured revision is no baseline, and discovery cannot recover one.
        if not revision:
            return False
        current = self._binary_revision(
            self._exec_path_for_launch(self._find_llama_server_binary())
        )
        if not current:
            return False
        return current != revision

    def spec_binary_fallback_can_retry(self) -> bool:
        """Whether the binary has since gained what the last load stood down for.

        The UI tells the user to run `unsloth studio update`, which leaves the request
        identical, so the duplicate-load comparators would otherwise dedup the very
        reload that update was meant to enable.

        Ask about the capability the drafter kind needs, not the reason: every kind
        records "binary_no_mtp", so asking about MTP after a DSpark stand-down says yes
        on a build that never gained draft-dspark. "binary_outdated" is an unknown
        architecture, which no flag advertises, so that one compares the file.
        """
        if self._spec_fallback_reason == "binary_outdated":
            return self._binary_changed_since_launch()
        if self._spec_fallback_reason != "binary_no_mtp":
            return False
        if self._launch_binary_revision and not self._binary_changed_since_launch():
            # An untouched file advertises nothing new, and this runs on every
            # duplicate-load check where the probe below is a subprocess.
            return False
        capability = _SPEC_KIND_CAPABILITY.get(self._spec_drafter_kind or "")
        if capability is None:
            return False
        try:
            return bool(self.probe_server_capabilities().get(capability))
        except Exception as exc:
            logger.debug("Could not recheck the speculative capability: %s", exc)
            return False

    @property
    def extra_args(self) -> Optional[List[str]]:
        """Extra llama-server flags from the last load (a copy). None =
        never set, [] = explicitly cleared. Used by the route for
        inheritance."""
        return list(self._extra_args) if self._extra_args is not None else None

    @property
    def requested_extra_args(self) -> Optional[List[str]]:
        """Extras the last load was INVOKED with (a copy), before any launch-time
        rewrite; falls back to the launched list when nothing was rewritten. Keeps a
        rewrite the caller cannot see (the virtualised-Metal drafter drop) from reading
        as a settings change in the duplicate-load comparators."""
        stored = (
            self._requested_extra_args
            if self._requested_extra_args is not None
            else self._extra_args
        )
        return list(stored) if stored is not None else None

    @property
    def requested_n_ctx(self) -> int:
        """n_ctx the last load was invoked with (not the effective cap).
        0 means Auto. Used by the route to detect Auto-vs-explicit flips."""
        return self._requested_n_ctx

    @property
    def extra_args_source(self) -> Optional[tuple[str, Optional[str]]]:
        """(model_identifier, hf_variant) the stored extra_args came from.
        ``None`` if no extras have ever been recorded. Used by the route
        to refuse cross-model inheritance (#5401)."""
        return self._extra_args_source

    @property
    def context_length(self) -> Optional[int]:
        """Return the effective context length the server is running at."""
        return self._effective_context_length or self._context_length

    @property
    def effective_parallel_slots(self) -> int:
        """Return the serving-slot count the active llama-server actually uses."""
        try:
            slots = int(getattr(self, "_effective_parallel_slots", 1))
        except (TypeError, ValueError):
            slots = 1
        return max(1, slots)

    @property
    def requested_parallel_slots(self) -> int:
        """--parallel the last load asked for, before any fit-time reduction.
        The reload dedupe compares requested-vs-requested (like requested_n_ctx);
        the effective count would reload forever after a fitter reduction."""
        try:
            slots = int(getattr(self, "_requested_n_parallel", 1))
        except (TypeError, ValueError):
            slots = 1
        return max(1, slots)

    @property
    def requested_n_batch(self) -> Optional[int]:
        """--batch-size the last load asked for; None means llama.cpp default."""
        return self._requested_n_batch

    @property
    def requested_n_ubatch(self) -> Optional[int]:
        """--ubatch-size the last load asked for; None means llama.cpp default."""
        return self._requested_n_ubatch

    @property
    def requested_load_mode(self) -> Optional[str]:
        """--load-mode the last load asked for; None means llama.cpp's own auto.
        The Model Memory settings may have replaced it, which the settings route
        reports; this stays the caller's intent so the dedupe compares like with
        like."""
        return self._requested_load_mode

    @property
    def requested_spec_draft_cache_type(self) -> Optional[str]:
        """Draft KV cache dtype the last load asked for; None means f16."""
        return self._requested_spec_draft_cache_type

    @property
    def requested_ctx_checkpoints(self) -> Optional[int]:
        """--ctx-checkpoints the last load asked for; None means the default 32."""
        return self._requested_ctx_checkpoints

    @property
    def requested_cache_ram(self) -> Optional[int]:
        """--cache-ram (MiB) the last load asked for; None means the default 8192."""
        return self._requested_cache_ram

    @property
    def max_context_length(self) -> Optional[int]:
        """Return the largest context that fits on this hardware at load time.

        The UI's "safe zone" warning threshold: the ``_fit_context_to_vram``
        binary-search cap for the best GPU subset, or the 4096 fallback if the
        weights exceed 90% of every subset. The slider ceiling is
        ``native_context_length``; dragging above this triggers the warning.
        """
        return self._max_context_length or self._context_length

    @property
    def native_context_length(self) -> Optional[int]:
        """Return the model's native context length from GGUF metadata."""
        return self._context_length

    def _commit_effective_parallel_slots(self, n_parallel: int) -> None:
        try:
            slots = int(n_parallel)
        except (TypeError, ValueError):
            slots = 1
        self._effective_parallel_slots = max(1, slots)

    def _reset_effective_parallel_slots(self) -> None:
        self._effective_parallel_slots = 1
        # Cleared with the effective count so a stale value can't skew the dedupe.
        self._requested_n_parallel = 1
        self._requested_n_batch = None
        self._requested_n_ubatch = None
        self._requested_load_mode = None
        self._requested_spec_draft_cache_type = None
        self._requested_ctx_checkpoints = None
        self._requested_cache_ram = None

    @staticmethod
    def _read_rss_bytes(pid: int) -> Optional[int]:
        """Resident set size of ``pid`` in bytes, from /proc/<pid>/status (Linux).
        0 when the status has no VmRSS line (zombie / kernel thread); None where
        /proc is unavailable (macOS/Windows) or the value is unreadable."""
        try:
            with open(f"/proc/{pid}/status", "r", encoding = "utf-8") as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        # IndexError guards a "VmRSS:" line with no value column.
                        return int(line.split()[1]) * 1024  # kB -> bytes
        except (FileNotFoundError, PermissionError, ValueError, IndexError, OSError):
            return None
        return 0  # readable but no VmRSS line

    def load_progress(self) -> Optional[dict]:
        """Return live model-load progress, or None if not loading.

        During warm-up llama-server mmaps weight shards into page cache before
        pushing layers to VRAM, a window where status only reports ``loading``
        and the UI spinner looks stuck for minutes on large MoEs. Samples
        ``/proc/<pid>/status VmRSS`` against the sum of GGUF shard sizes for a
        real progress bar. Returns ``None`` when no load is in flight.

        Shape::

            {
                "phase": "mmap" | "ready",
                "bytes_loaded": int,   # VmRSS of the llama-server
                "bytes_total":  int,   # sum of shard file sizes
                "fraction": float,     # bytes_loaded / bytes_total, 0..1
            }

        Linux-only; returns ``None`` where ``/proc/<pid>/status`` is unavailable.
        """
        proc = self._process
        if proc is None:
            return None
        pid = proc.pid
        if pid is None:
            return None

        # Sum shard sizes (primary + any extras alongside).
        bytes_total = 0
        gguf_path = self._gguf_path
        if gguf_path:
            primary = Path(gguf_path)
            try:
                if primary.is_file():
                    bytes_total += primary.stat().st_size
            except OSError:
                pass
            # Extra shards share the primary's prefix before the shard index.
            try:
                parent = primary.parent
                stem = primary.name
                m = _SHARD_RE.match(stem)
                prefix = m.group(1) if m else None
                if prefix and parent.is_dir():
                    prefix_lower = prefix.lower()
                    for sibling in parent.iterdir():
                        if (
                            sibling.is_file()
                            and sibling.name.lower().startswith(prefix_lower)
                            and sibling.name != stem
                            and sibling.suffix.lower() == ".gguf"
                        ):
                            try:
                                bytes_total += sibling.stat().st_size
                            except OSError:
                                pass
            except OSError:
                pass

        # VmRSS of the llama-server; None where /proc is unavailable.
        bytes_loaded = LlamaCppBackend._read_rss_bytes(pid)
        if bytes_loaded is None:
            return None

        # RSS climbs as weights page in, then drops once -ngl offloads them to
        # VRAM and the mmap pages are freed. Hold a per-process high-water mark
        # so the bar never regresses to ~8% mid-load (#5740).
        hwm_pid, hwm = getattr(self, "_load_rss_hwm", (None, 0))
        hwm = bytes_loaded if hwm_pid != pid else max(hwm, bytes_loaded)
        self._load_rss_hwm = (pid, hwm)
        bytes_loaded = hwm

        phase = "ready" if self._healthy else "mmap"
        fraction = 0.0
        if bytes_total > 0:
            fraction = min(1.0, bytes_loaded / bytes_total)
        # Once llama-server is healthy the load is complete by definition. With
        # layers offloaded to VRAM (-ngl) the process releases the mmap'd weight
        # pages, so VmRSS sinks back well below the shard total; the raw RSS
        # fraction would then report a partial (~8%) load indefinitely and freeze
        # a fraction-driven progress bar even though the model is ready (#5740).
        if self._healthy:
            if bytes_total > 0:
                bytes_loaded = bytes_total
            fraction = 1.0
        return {
            "phase": phase,
            "bytes_loaded": bytes_loaded,
            "bytes_total": bytes_total,
            "fraction": round(fraction, 4),
        }

    @property
    def chat_template(self) -> Optional[str]:
        return self._chat_template

    @property
    def markup_profile(self):
        """This model's own structural markers, from its GGUF template and vocabulary.

        None when neither could be read, which falls back to the curated patterns: a model
        we cannot profile stays fully swept rather than unprotected (#7066)."""
        # getattr, not attribute access: a lightweight backend double in a test never runs
        # __init__, and an unprofiled model must fall back rather than raise.
        cached = getattr(self, "_markup_profile", None)
        if cached is None:
            from core.inference.chat_template_helpers import model_markup
            cached = (
                model_markup(
                    getattr(self, "_chat_template_override", None)
                    or getattr(self, "_chat_template", None),
                    getattr(self, "_markup_tokens", None),
                ),
            )
            try:
                self._markup_profile = cached
            except AttributeError:
                pass
        return cached[0]

    @property
    def chat_template_override(self) -> Optional[str]:
        return self._chat_template_override

    @property
    def supports_reasoning(self) -> bool:
        return self._supports_reasoning

    @property
    def reasoning_always_on(self) -> bool:
        return self._reasoning_always_on

    @property
    def reasoning_style(self) -> str:
        return self._reasoning_style

    @property
    def reasoning_effort_levels(self) -> list:
        """Discrete reasoning_effort levels the template offers (e.g. GLM-5.2's
        ['high', 'max']). Empty unless reasoning_style == 'enable_thinking_effort'."""
        return self._reasoning_effort_levels

    @property
    def supports_preserve_thinking(self) -> bool:
        return self._supports_preserve_thinking

    @property
    def preserve_thinking_default(self) -> bool:
        return self._preserve_thinking_default

    @property
    def reasoning_default(self) -> bool:
        return self._reasoning_default

    def _reasoning_kwargs(self, enable_thinking: bool) -> dict:
        if self._reasoning_style == "enable_thinking_effort":
            # GLM-5.2-style: enable_thinking is the on/off gate; when on, leave
            # the template's default effort (max) in place.
            return {"enable_thinking": enable_thinking}
        if self._reasoning_style == "reasoning_effort":
            return _coerce_reasoning_effort(
                getattr(self, "_architecture", None),
                {"reasoning_effort": "high" if enable_thinking else "low"},
            )
        return {"enable_thinking": enable_thinking}

    def _request_reasoning_kwargs(
        self,
        enable_thinking: Optional[bool],
        reasoning_effort: Optional[str] = None,
        preserve_thinking: Optional[bool] = None,
    ) -> Optional[dict]:
        """Build chat_template_kwargs from per-request reasoning fields.

        Merges the active model's reasoning style (``enable_thinking`` or
        ``reasoning_effort``) plus the independent ``preserve_thinking``
        kwarg when the template supports it.
        """
        kwargs: dict = {}
        # Always-on reasoning models hardcode <think> tags and don't consume
        # enable_thinking / reasoning_effort -- skip.
        if self._supports_reasoning and not self._reasoning_always_on:
            if self._reasoning_style == "enable_thinking_effort":
                # GLM-5.2-style: enable_thinking gates thinking on/off, and the
                # reasoning_effort level (e.g. 'high' | 'max') is only meaningful
                # while thinking is on. Disabling is enable_thinking=false; a raw
                # API caller can also disable via the OpenAI-style
                # reasoning_effort="none" sentinel. We never coerce off into a
                # 'low' effort the way gpt-oss does (those models genuinely
                # cannot disable).
                thinking_off = enable_thinking is False or reasoning_effort == "none"
                # A named effort level implies thinking on, so emit enable_thinking
                # even if the caller sent only reasoning_effort (else the template
                # defaults it off and the requested level never renders).
                effort_on = reasoning_effort in self._reasoning_effort_levels
                if enable_thinking is not None or reasoning_effort == "none" or effort_on:
                    kwargs["enable_thinking"] = not thinking_off
                if not thinking_off and effort_on:
                    kwargs["reasoning_effort"] = reasoning_effort
            elif self._reasoning_style == "reasoning_effort":
                if reasoning_effort in ("none", "low", "medium", "high"):
                    kwargs["reasoning_effort"] = reasoning_effort
                elif reasoning_effort == "minimal":
                    kwargs["reasoning_effort"] = "low"
                elif enable_thinking is not None:
                    kwargs["reasoning_effort"] = "high" if enable_thinking else "low"
            else:
                if enable_thinking is not None:
                    kwargs["enable_thinking"] = enable_thinking
        if self._supports_preserve_thinking and preserve_thinking is not None:
            kwargs["preserve_thinking"] = preserve_thinking
        _coerce_reasoning_effort(getattr(self, "_architecture", None), kwargs)
        return kwargs or None

    @property
    def supports_tools(self) -> bool:
        # DiffusionGemma serves via the visual runner, whose live per-step canvas
        # frames are dropped by the agentic tool loop; never route it through tools.
        if self._is_diffusion:
            return False
        return self._supports_tools

    @property
    def supports_tool_passthrough(self) -> bool:
        # supports_tools is forced off for DiffusionGemma (its agentic loop drops the
        # per-step canvas frames), but client passthrough skips that loop, so it uses
        # the real _supports_tools.
        return self._supports_tools

    @property
    def cache_type_kv(self) -> Optional[str]:
        return self._cache_type_kv

    @property
    def tensor_parallel(self) -> bool:
        """Whether --split-mode tensor is active on the loaded server."""
        return self._tensor_parallel

    @property
    def gpu_memory_mode(self) -> str:
        """Active GPU memory strategy: 'auto' or 'manual' (gpu_layers < 0 = Auto/--fit, >= 0 = pinned)."""
        return self._gpu_memory_mode

    @property
    def gpu_layers(self) -> int:
        """Requested --gpu-layers for manual mode (-1 when not manual)."""
        return self._gpu_layers

    @property
    def holds_no_vram(self) -> bool:
        """Whether the resident server is a confirmed zero-VRAM launch, so the GPU
        arbiter can leave an image/video pipeline alone when re-asserting ownership.

        True for a manual zero-offload load whose argv carried no GPU companion, pin
        or tensor mode (``_gpu_offload_active`` None or True keeps the normal path),
        and for an arch-gated launch masked onto the CPU by the "-1" sentinel
        (#7624). The latter arrives through an AUTOMATIC request, so demanding manual
        mode would answer False for the case routes/inference.py:8206 documents and
        leave a VRAM-less server holding the CHAT claim, unloadable by an owner it
        never competed with."""
        if self._arch_gate_forced_cpu:
            return True
        return (
            self._gpu_memory_mode == "manual"
            and self._gpu_layers == 0
            and self._gpu_offload_active is False
        )

    @property
    def diffusion_requested_ngl(self) -> Optional[int]:
        """The diffusion split the live runner was ASKED for, or None for the default.

        Differs from ``gpu_layers`` only when the shim could not take the split: that
        reports what is running, this keeps the ask so a repeat still dedupes."""
        return getattr(self, "_diffusion_requested_ngl", None)

    @property
    def n_cpu_moe(self) -> int:
        """MoE expert layers manual mode kept on CPU (--n-cpu-moe); 0 = none."""
        return self._n_cpu_moe

    @property
    def tensor_split(self) -> Optional[List[float]]:
        """Manual-mode relative model share per GPU (--tensor-split); None =
        default (split by free VRAM)."""
        return self._tensor_split

    @property
    def gpu_ids(self) -> Optional[List[int]]:
        """User-picked physical GPU indices, or None for automatic selection."""
        return self._gpu_ids

    @property
    def requested_gpu_ids(self) -> Optional[List[int]]:
        """RAW requested GPU pin (before the fit narrowed it), or None for auto.
        gpu_ids echoes the EFFECTIVE pin for /status."""
        return self._requested_gpu_ids

    def matches_gpu_ids(self, gpu_ids: Optional[List[int]]) -> bool:
        """Whether a requested pin is already satisfied by the active runner.

        A regular GGUF load may narrow the requested placement pool to the
        smallest fitting subset. Accept both the original request and the
        effective status-echoed subset so either can round-trip without a
        needless reload. Diffusion drives one device and keeps its existing
        lowest-device normalization.
        """
        if self._is_diffusion:
            requested = [sorted(int(x) for x in gpu_ids)[0]] if gpu_ids else None
            # Raw pick accepted too: a forced-CPU runner records no effective pin, so
            # without it re-sending the same selection would reload every time.
            return requested in ((self._gpu_ids or None), (self._requested_gpu_ids or None))

        requested = sorted(int(x) for x in gpu_ids) if gpu_ids else None
        raw = self._requested_gpu_ids or None
        effective = self._gpu_ids or None
        return requested == raw or requested == effective

    def _record_matching_gpu_request(self, gpu_ids: Optional[List[int]]) -> None:
        """Adopt the caller's explicit pool after a full already-loaded match.

        Matching an effective subset avoids a reload, but the incoming request
        is still the user's latest placement intent. Record it so status and a
        later reload do not restore GPUs the user just removed.
        """
        if self._is_diffusion:
            self._requested_gpu_ids = [sorted(int(x) for x in gpu_ids)[0]] if gpu_ids else None
        else:
            self._requested_gpu_ids = sorted(int(x) for x in gpu_ids) if gpu_ids else None
        if self._last_load_intent is not None:
            self._last_load_intent = replace(
                self._last_load_intent,
                gpu_ids = tuple(self._requested_gpu_ids) if self._requested_gpu_ids else None,
            )

    @property
    def last_load_intent(self) -> Optional[GgufLoadIntent]:
        return self._last_load_intent

    def _runtime_matches_intent(
        self, intent: GgufLoadIntent, effective_extra_args: Optional[list[str]]
    ) -> bool:
        """Whether active runtime settings satisfy one resolved caller intent."""

        if intent.force_reload:
            return False
        if self._requested_n_ctx != int(intent.n_ctx):
            return False
        if not self._is_diffusion and self._requested_n_parallel != max(1, int(intent.n_parallel)):
            return False
        if not self._is_diffusion and (
            self._requested_n_batch != intent.n_batch or self._requested_n_ubatch != intent.n_ubatch
        ):
            return False
        # Same rule for the tuning group: requested against requested, so a server
        # launched with a different value is a reload. Compared even when the
        # intent is blank, unlike spec_draft_n_max above: blank is the llama.cpp
        # default and both sides hold what was requested, so two loads that asked
        # for nothing still match, while clearing a knob relaunches.
        if not self._is_diffusion and (
            _normalized_load_mode(self._requested_load_mode)
            != _normalized_load_mode(intent.load_mode)
            or self._requested_spec_draft_cache_type != intent.spec_draft_cache_type
            or self._requested_ctx_checkpoints != intent.ctx_checkpoints
            or self._requested_cache_ram != intent.cache_ram
        ):
            return False

        # The KV cache comparison waits for _invoked_extras below: the scalar
        # self._cache_type_kv alone cannot describe this launch.

        # Toggling vision changes which files the child opens, so it cannot be
        # satisfied by a live server that was launched the other way. Not on the
        # diffusion path: _start_diffusion_server ignores the switch and records it
        # False, so comparing it there makes every identical repeat request a
        # mismatch and tears down a runtime that was already the one asked for.
        if not self._is_diffusion and bool(self._disable_vision) != bool(intent.disable_vision):
            return False

        extra_args = list(effective_extra_args) if effective_extra_args is not None else None
        # A request omitting the extras field inherits the LAUNCHED list; anything else is
        # the caller's own. A launch-time rewrite (drafter drop, MTP crash replay) makes
        # the two differ, and the equality below wants what the load was INVOKED with.
        # Judged on the flag, not on value equality: a caller that deliberately sends the
        # stripped list is clearing the failed drafter and must not read as inheriting it.
        _invoked_extras = self.requested_extra_args if intent.extra_args_inherited else extra_args
        # Requested against requested, per axis, the same rule the tuning group above
        # uses. The scalar self._cache_type_kv holds only what Unsloth emitted as a
        # managed flag, so a cache set through extras or the env records None on one
        # side and a type on the other, and an identical repeat /load tears down a
        # healthy server. _requested_cache_types is what the live server was ASKED for,
        # so two equal requests match even when the launch rewrote the cache underneath
        # them. Before ggml-org/llama.cpp#23792 the tensor gate hid this by rewriting
        # the cache away; a layer load has always had it.
        if self._requested_cache_types != _planned_main_cache_types(
            intent.cache_type_kv, _invoked_extras
        ):
            return False
        # A virtualised Metal device never launches a tensor split (CPU-pinned, and
        # --split-mode is overridden with the default layer split), so judge the
        # normalized request there: an extras `-sm tensor`, which the pin deliberately
        # leaves in place, would otherwise never match.
        if _metal_device_is_paravirtual():
            if self._tensor_parallel:
                return False
        elif not _tensor_parallel_matches_loaded(
            extra_args, intent.tensor_parallel, self._tensor_parallel
        ):
            # A mode the gate normalised away is this request normalized, not a
            # different one. Guarded on a RECORDED drop, so a launch that dropped
            # nothing cannot excuse a live tensor server against a layer request.
            if not (self._arch_gate_dropped_tensor_parallel and not self._tensor_parallel):
                return False
        if (
            self._layer_preserves_tensor_intent
            and not _effective_tensor_parallel(extra_args, intent.tensor_parallel)
            and not intent.preserve_multi_gpu_on_layer
        ):
            return False

        if self._is_diffusion:
            requested_ngl = _diffusion_manual_ngl(intent.gpu_memory_mode, intent.gpu_layers)
            if requested_ngl != self.diffusion_requested_ngl:
                return False
            # A split dropped by an older shim still matches until the shim gains
            # --ngl support, at which point the same request should apply it.
            if (
                requested_ngl is not None
                and self._gpu_layers != requested_ngl
                and self.diffusion_split_supported()
            ):
                return False
        else:
            if self._swa_full != _swa_full_from_args_or_env(extra_args):
                return False
            if self._gpu_memory_mode != intent.gpu_memory_mode:
                return False
            if intent.gpu_memory_mode == "manual" and (
                self._gpu_layers != intent.gpu_layers
                or (
                    intent.gpu_layers >= 0
                    and (
                        self._n_cpu_moe != intent.n_cpu_moe
                        or (
                            (tuple(self._tensor_split) if self._tensor_split else None)
                            != (intent.tensor_split or None)
                            # Same rule as the mode above: a dropped ratio is this
                            # request normalized. Guarded on a RECORDED drop, never
                            # None == None. Any other ratio reloads.
                            and not (
                                self._arch_gate_dropped_tensor_split is not None
                                and self._arch_gate_dropped_tensor_split
                                == (intent.tensor_split or None)
                            )
                        )
                    )
                )
            ):
                return False

        if not self.matches_gpu_ids(list(intent.gpu_ids) if intent.gpu_ids else None):
            return False

        spec_owned_by_extra_args = _extra_args_set_spec_type(extra_args)
        speculative_type = (
            None
            if spec_owned_by_extra_args
            else _canonicalize_spec_mode(intent.speculative_type) or "auto"
        )
        backend_spec = self._requested_spec_mode
        if spec_owned_by_extra_args:
            if backend_spec is not None:
                return False
        elif speculative_type != (backend_spec or "auto"):
            return False
        # Reload so the next Apply retries the drafter fetch. Worth it when the
        # repo publishes a drafter and the fetch failed; not when it publishes
        # none, which for DSpark is the permanent state of every repo but one and
        # would relaunch an identical server forever.
        if (
            intent.gguf_path is None
            and self._spec_fallback_reason == "drafter_not_found"
            and speculative_type in ("auto", "mtp", "mtp+ngram", "dspark", "dflash")
            and not (self._spec_drafter_kind == "dspark" and self._dspark_sidecar_absent)
            # DFlash asks through _dflash_retry_needed below, which is set only for
            # retryable failures. A permanent listing error records no answer, so
            # _dflash_sidecar_absent stays False and this arm relaunched forever.
            and self._spec_drafter_kind != "dflash"
            and not spec_owned_by_extra_args
        ):
            return False
        # The stand-down the UI asks the user to fix by updating llama.cpp. That leaves
        # the request identical, so without this the repaired load never happens.
        if (
            speculative_type in ("auto", "mtp", "mtp+ngram", "dspark", "dflash")
            and self.spec_binary_fallback_can_retry()
        ):
            return False
        # Under Auto a failed fetch records no fallback reason, so the branch above
        # cannot see it. A repo with no sidecar is _dflash_sidecar_absent's business.
        if self._dflash_retry_needed and speculative_type in ("auto", "dflash"):
            return False
        # Retry a runtime the probe degraded, once the probe starts answering (#8317).
        # The retry window is worth nothing if Apply keeps deduping against the degraded
        # runtime, since nothing would re-probe. The slot clamp is the trap:
        # _requested_n_parallel stores the ASK, so a clamped runtime compares equal and
        # would never be revisited. One reload, not a loop -- it records the conclusive
        # probe and clears this flag, so a build that really lacks the capability
        # re-derives the same runtime and dedupes after. The probe is cached, so it is
        # free on the only path that reaches it.
        if (
            self._capability_probe_inconclusive
            and not self._is_diffusion
            and not self.probe_server_capabilities().get("mtp_probe_inconclusive")
        ):
            return False

        compared_draft_n_max = self._spec_draft_n_max
        if self._spec_fallback_reason == "runtime_error" and self._last_load_intent is not None:
            # The MTP-free recovery clears the runtime value but retains the
            # user's prior value in its intent. Only a changed value should retry MTP.
            compared_draft_n_max = self._last_load_intent.spec_draft_n_max
        if (
            (
                self._speculative_type in ("draft-mtp", "draft-dspark", "draft-dflash")
                # Auto's Hybrid Mamba partial-offload stand-down engaged nothing, so the
                # types above cannot see it -- yet the depth is what priced the rollback
                # copies that made the placement partial, so a change can re-enable MTP.
                or self._spec_fallback_reason in ("runtime_error", "mtp_partial_offload")
            )
            and intent.spec_draft_n_max is not None
            and intent.spec_draft_n_max != (compared_draft_n_max or 0)
        ):
            return False
        if (self._chat_template_override or None) != (intent.chat_template_override or None):
            return False

        if tuple(_invoked_extras or ()) != tuple(self.requested_extra_args or ()):
            return False
        if (intent.gguf_path is not None or intent.compare_mtp_draft) and speculative_type in (
            "auto",
            "mtp",
            "mtp+ngram",
            "dspark",
            "dflash",
        ):
            try:
                # Auto counts as dspark/dflash once it resolved that way: the launch
                # stored that sidecar, so comparing the MTP field (None for these
                # repos) against it would reload a healthy server on every Apply.
                # _speculative_type is reset to "default" when a drafter fails to
                # start and the drafterless retry succeeds, but the launch still
                # recorded the sidecar it resolved. Keying the comparison off it
                # would then compare the intent's (empty) MTP path against that
                # recorded sidecar and reload a healthy server on every Apply.
                # _spec_drafter_kind survives the fallback, so it decides here.
                _compare_dspark = speculative_type == "dspark" or (
                    speculative_type == "auto"
                    and (
                        self._speculative_type == "draft-dspark"
                        or self._spec_drafter_kind == "dspark"
                    )
                )
                _compare_dflash = speculative_type == "dflash" or (
                    speculative_type == "auto"
                    and (
                        self._speculative_type == "draft-dflash"
                        or self._spec_drafter_kind == "dflash"
                    )
                )
                if _compare_dspark:
                    intent_draft = intent.dspark_draft_path
                elif _compare_dflash:
                    intent_draft = intent.dflash_draft_path
                else:
                    intent_draft = intent.mtp_draft_path
                requested_draft = Path(intent_draft).resolve() if intent_draft else None
                # A drafter the last load dropped on purpose counts as launched here:
                # the file is still there, so comparing it against the stored None
                # would reload the same drafter-free server forever.
                _loaded = self._mtp_draft_path or self._mtp_draft_suppressed_path
                loaded_draft = Path(_loaded).resolve() if _loaded else None
            except OSError:
                return False
            if requested_draft != loaded_draft:
                return False
        return True

    @property
    def n_layers(self) -> Optional[int]:
        """Model layer count (GGUF block_count), or None if unknown."""
        return self._n_layers

    @property
    def n_moe_layers(self) -> int:
        """Number of MoE expert layers (the --n-cpu-moe ceiling), 0 if not MoE.

        block_count minus the leading dense layers (which carry no experts):
        --n-cpu-moe counts from layer 0, so those dense layers are no-ops.
        """
        if not self._n_experts or not self._n_layers:
            return 0
        return max(0, self._n_layers - (self._leading_dense_block_count or 0))

    _EMBEDDING_POOLING_TYPES = frozenset({1, 2, 3})  # llama_pooling_type MEAN, CLS, LAST

    @property
    def is_embedding_gguf(self) -> bool:
        """Whether the loaded GGUF is an embedding model, from its pooling type.

        Only MEAN, CLS and LAST pool into the one vector per sequence that
        `/v1/embeddings` returns. NONE (0) pools nothing, and RANK (4) is a reranker
        head: llama_context sizes its pooled buffer to n_cls_out while llama-server's
        send_embedding reads n_embd_out floats out of it.

        When the header omits pooling_type (common on dedicated encoder arches such as
        nomic-bert), fall back to architecture and model-name hints so llama-server still
        launches with --embedding (#9128).
        """
        pooling = getattr(self, "_pooling_type", None)
        if pooling is not None:
            return pooling in self._EMBEDDING_POOLING_TYPES
        path = getattr(self, "_gguf_path", None)
        if not path:
            return False
        from utils.models.gguf_metadata import is_gguf_embedding_model

        return is_gguf_embedding_model(
            path,
            model_identifier = self._model_identifier,
            architecture = self._architecture,
        )

    @staticmethod
    def _resolve_cpu_moe_flag(
        n_cpu_moe: int, n_moe_layers: int, leading_dense: int
    ) -> Optional[int]:
        """The --n-cpu-moe value (absolute first-N layers), or None to omit it.

        Clamps the requested count to the model's MoE layers, then offsets past
        the leading dense layers (--n-cpu-moe counts from layer 0). Returns None
        for nothing-to-offload (0 requested) or a non-MoE model.
        """
        if n_cpu_moe <= 0 or n_moe_layers <= 0:
            return None
        return leading_dense + min(n_cpu_moe, n_moe_layers)

    @staticmethod
    def _sanitize_tensor_split(tensor_split: Optional[List[float]]) -> List[float]:
        """Per-GPU shares with negative and non-finite entries clamped to 0.

        A direct caller's negative entry would launch a placement different
        from the ratio the UI showed, and inf would pass a plain ``> 0`` total
        gate and emit ``--tensor-split inf,...``. Returns [] for input that
        can't be read as floats (the length gate at the call site then drops
        the split).
        """
        try:
            return [
                x if math.isfinite(x) and x > 0.0 else 0.0 for x in (float(v) for v in tensor_split)
            ]
        except (TypeError, ValueError, OverflowError):
            return []

    @property
    def layer_preserves_tensor_intent(self) -> bool:
        """True when a downgraded tensor request kept this layer load multi-GPU."""
        return self._layer_preserves_tensor_intent

    @property
    def speculative_type(self) -> Optional[str]:
        return self._speculative_type

    @property
    def spec_drafter_kind(self) -> Optional[str]:
        """Which drafter the resolution was about: ``mtp``, ``dspark`` or ``dflash``.

        Distinct from ``requested_spec_mode``, which stays ``auto`` when Auto
        resolves the kind itself, and from ``speculative_type``, which reads
        ``default`` once a fallback fires. The UI needs the kind to name the
        right recovery in a fallback notice.
        """
        return self._spec_drafter_kind

    @property
    def requested_spec_mode(self) -> Optional[str]:
        """Canonical UI-facing mode the user requested (see field doc)."""
        return self._requested_spec_mode

    @property
    def spec_draft_n_max(self) -> Optional[int]:
        """User --spec-draft-n-max override active on the load, or None when
        the platform default (6 GPU / 3 CPU) is in effect."""
        return self._spec_draft_n_max

    # ── Binary discovery ──────────────────────────────────────────

    @staticmethod
    def _resolved_studio_root_and_is_legacy() -> "tuple[Optional[Path], bool]":
        """Resolve the Unsloth install root and classify it as the legacy
        ~/.unsloth/studio root vs. a custom (env/venv-inferred) root.

        Returns (resolved_root, is_legacy). On any import/resolution failure the
        root is treated as legacy and resolved_root is None -- callers must read
        resolved_root only when is_legacy is False. Shared by
        _find_llama_server_binary (discovery) and _kill_orphaned_servers
        (cleanup) so the two never disagree on which root is legacy.
        """
        try:
            from utils.paths.storage_roots import studio_root as _sr  # noqa: WPS433

            resolved = _sr()
            legacy_studio = Path.home() / ".unsloth" / "studio"
            try:
                is_legacy = resolved.resolve() == legacy_studio.resolve()
            except (OSError, ValueError):
                is_legacy = resolved == legacy_studio
            return (None if is_legacy else resolved), is_legacy
        except (ImportError, OSError, ValueError):
            return None, True

    @staticmethod
    def _find_llama_server_binary(*, include_denied: bool = False) -> Optional[str]:
        """
        Locate the llama-server binary.

        Search order:
        1.  LLAMA_SERVER_PATH environment variable (direct path to binary)
        1b. UNSLOTH_LLAMA_CPP_PATH env var (custom llama.cpp install dir)
        2.  Unsloth's custom llama.cpp folder setting
        3.  ~/.unsloth/llama.cpp/llama-server        (make build, root dir)
        4.  ~/.unsloth/llama.cpp/build/bin/llama-server  (cmake build, Linux)
        5.  ~/.unsloth/llama.cpp/build/bin/Release/llama-server.exe  (cmake build, Windows)
        6.  ./llama.cpp/llama-server                 (legacy: make build, root dir)
        7.  ./llama.cpp/build/bin/llama-server        (legacy: cmake in-tree build)
        8.  llama-server on PATH                     (system install)
        9.  ./bin/llama-server                       (legacy: extracted binary)
        """
        binary_name = "llama-server.exe" if sys.platform == "win32" else "llama-server"

        def _file_status(p: Path) -> str:
            # "file", "absent", "non_executable", or "denied". A denied
            # file stays access-denied across a short retry (Windows AV/ACL or
            # an install replace in flight). is_file() raises PermissionError
            # (WinError 5) instead of returning False for the locked case, so
            # never treat it as missing.
            for _ in range(5):
                try:
                    if not p.is_file():
                        return "absent"
                    if sys.platform != "win32" and not os.access(p, os.X_OK):
                        return "non_executable"
                    return "file"
                except PermissionError:
                    time.sleep(0.2)
                except OSError:
                    return "absent"
            return "denied"

        def _is_file(p: Path) -> bool:
            return _file_status(p) == "file"

        def _layout_candidates(d: Path) -> list:
            # Keep Settings validation and runtime discovery on one layout
            # contract so a folder accepted by the UI is always launchable.
            from utils.llama_cpp_path_settings import llama_server_candidates
            return list(llama_server_candidates(d))

        def _unavailable(p: object) -> None:
            # a pinned or managed binary that exists but is access-denied: report
            # it instead of silently downgrading to a lower-priority llama-server
            logger.warning(
                f"llama-server at {p} is not executable or is access-denied "
                "(permissions, antivirus, or an in-flight install); not falling "
                "back to another binary, retry once it is available"
            )
            return None

        def _scan_pinned(paths: list):
            # First executable candidate wins. A genuinely access-denied one
            # stops immediately; a known non-executable candidate is remembered
            # while sibling build layouts are checked. include_denied returns an
            # unavailable path instead: diffusion asset lookup only needs its dir.
            non_executable = None
            for p in paths:
                st = _file_status(p)
                if st == "file":
                    return str(p), None
                if st == "denied":
                    return (str(p), None) if include_denied else (None, p)
                if st == "non_executable" and non_executable is None:
                    # A source checkout may leave a stale root entrypoint beside a
                    # valid CMake build. Keep looking within this pinned layout,
                    # but do not fall through to a different runtime if none works.
                    non_executable = p
            if non_executable is not None:
                # include_denied is used only to preserve genuinely transient
                # access-denied paths. A missing execute bit needs repair, not a
                # retry, and must not pass the download preflight as available.
                return (None, None) if include_denied else (None, non_executable)
            return None, None

        # 1. Env var: direct path to binary
        env_path = os.environ.get("LLAMA_SERVER_PATH")
        if env_path:
            hit, locked = _scan_pinned([Path(env_path)])
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 1b. UNSLOTH_LLAMA_CPP_PATH: custom llama.cpp install dir
        custom_llama_cpp = os.environ.get("UNSLOTH_LLAMA_CPP_PATH")
        managed_path_marker = os.environ.get("UNSLOTH_STUDIO_MANAGED_LLAMA_CPP_PATH") == "1"
        if custom_llama_cpp and not managed_path_marker:
            hit, locked = _scan_pinned(_layout_candidates(Path(custom_llama_cpp)))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 2. Unsloth setting: a deliberate pin, so a missing or inaccessible
        # selected build must not silently fall through to the bundled runtime.
        # The user would otherwise see their custom path selected while another
        # llama-server actually ran.
        try:
            from utils.llama_cpp_path_settings import get_stored_custom_llama_cpp_path
            studio_custom_llama_cpp = get_stored_custom_llama_cpp_path()
        except Exception:
            studio_custom_llama_cpp = None
        if studio_custom_llama_cpp is not None:
            hit, locked = _scan_pinned(_layout_candidates(studio_custom_llama_cpp))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit
            logger.warning(
                "The custom llama.cpp folder selected in Unsloth no longer contains "
                "%s; not falling back to another runtime",
                binary_name,
            )
            return None

        # 3-5. Match installer layout: env-mode -> $STUDIO_HOME/llama.cpp;
        # default/HOME-redirect -> ~/.unsloth/llama.cpp (sibling of studio).
        legacy_llama = Path.home() / ".unsloth" / "llama.cpp"
        _resolved_sr, _is_legacy = LlamaCppBackend._resolved_studio_root_and_is_legacy()
        if _is_legacy:
            search_roots = [legacy_llama]
        else:
            # _kill_orphaned_servers excludes the legacy root in custom mode;
            # discovery must match so we never spawn a server we then refuse to
            # clean up. UNSLOTH_LLAMA_CPP_PATH (handled earlier) is the explicit
            # way to share a build across roots.
            search_roots = [_resolved_sr / "llama.cpp"]
        for unsloth_home in search_roots:
            hit, locked = _scan_pinned(_layout_candidates(unsloth_home))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 5-6. Legacy: in-tree build (older setup.sh / setup.ps1). A fallback,
        # so a denied candidate here just continues (no no-fallback halt).
        project_root = Path(__file__).resolve().parents[4]
        for p in _layout_candidates(project_root / "llama.cpp"):
            if _is_file(p):
                return str(p)

        # 7. System PATH
        system_path = shutil.which("llama-server")
        if system_path:
            return system_path

        # 8. Legacy: extracted to bin/
        bin_path = project_root / "bin" / binary_name
        if _is_file(bin_path):
            return str(bin_path)

        return None

    # ── llama-server capability probe ─────────────────────────────

    # Prebuilts based on llama.cpp b10259..b10268 advertise draft-dspark but land between
    # the reshape regression (ggml-org/llama.cpp#26531) and its fix (#26577), so a DSpark
    # launch aborts on load. Matched on the base build number, not one exact tag: every
    # release in that window is affected. Source builds carry no install marker, so only
    # managed prebuilts are gated.
    _BROKEN_DSPARK_BUILDS = range(10259, 10269)

    @classmethod
    def _dspark_release_is_broken(cls, release_tag: Optional[str]) -> bool:
        match = re.match(r"b(\d+)", str(release_tag or ""))
        return bool(match) and int(match.group(1)) in cls._BROKEN_DSPARK_BUILDS

    # Keyed on the file's revision, since `unsloth studio update` replaces it in place.
    # Nanoseconds and size, not int(st_mtime): an update landing in the same second as
    # the probe kept the key identical and got the old build's capabilities.
    _CAPABILITY_PROBE_RETRY_SECONDS = 30.0
    _capability_cache: dict[tuple[str, int, int], dict[str, object]] = {}
    _capability_retry_after: dict[tuple[str, int, int], float] = {}
    _capability_cache_lock = threading.Lock()

    # The value form of the flash-attention flag. Newer llama.cpp declares it
    # with an enum, "-fa, --flash-attn [on|off|auto]"; older builds take a bare
    # boolean and reject a following "on" as a stray positional, which is an
    # immediate "invalid argument" exit rather than a degraded launch.
    _FLASH_ATTN_ENUM_RE = re.compile(
        r"(?im)^[^\n]*--flash-attn[^\n]*\bon\b[ \t]*\|[ \t]*\boff\b[^\n]*$"
    )

    @classmethod
    def _flash_attn_takes_value(cls, help_text: str) -> bool:
        """Whether this build's --flash-attn accepts on/off/auto.

        Fails open: a build whose help never mentions the flag at all keeps
        today's behaviour, because the pinned prebuilt is the value form and a
        wrong answer there would break the supported path for a hypothetical
        one.
        """
        if not help_text or "--flash-attn" not in help_text:
            return True
        return bool(cls._FLASH_ATTN_ENUM_RE.search(help_text))

    @classmethod
    def probe_server_capabilities(cls, binary: Optional[str] = None) -> dict[str, object]:
        """Parse `llama-server --help` for feature flags. Returns
        {found, mtp_token, supports_mtp, supports_dspark, supports_dflash,
        ngram_mod_flavor, supports_ngram_mod, spec_draft_n_max_flag, cache flag
        support}.

        ``ngram_mod_flavor``: ``"new"`` when the post-rename
        ``--spec-ngram-mod-n-match / -n-min / -n-max`` are real args;
        ``"legacy"`` when only the pre-rename
        ``--spec-ngram-size-n / --draft-min / --draft-max`` are real (the
        rename ships stub removal entries for legacy names, told apart by
        the "argument has been removed" description); ``None`` if neither
        set is usable.

        ``spec_draft_n_max_flag``: the flag the binary accepts --
        ``--spec-draft-n-max`` post-rename, ``--draft-max`` on legacy.
        ``None`` means n_max cannot be set.
        """
        # Not only in load_model: startup, status and preflight probe directly,
        # and a wrapper loses DYLD_* to SIP before reaching the real server. The
        # inconclusive capabilities that follow clamp slots and disable
        # DSpark/DFlash sizing on a server that supports both (#8566).
        bin_path = cls._exec_path_for_launch(binary or cls._find_llama_server_binary())
        if not bin_path or not Path(bin_path).is_file():
            return {
                "found": False,
                "mtp_token": None,
                "supports_mtp": False,
                "supports_dspark": False,
                "supports_dflash": False,
                "mtp_probe_inconclusive": True,
                "ngram_mod_flavor": None,
                "supports_ngram_mod": False,
                "spec_draft_n_max_flag": None,
                "spec_draft_n_max_default": None,
                "supports_kv_unified": False,
                # Fail OPEN, unlike every key above. These three are emitted on
                # every launch today, so a failed probe must keep emitting them;
                # only a build whose --help positively lacks one drops it.
                "supports_no_context_shift": True,
                "supports_jinja": True,
                "supports_flash_attn": True,
                "flash_attn_takes_value": True,
                "supports_fit_ctx": False,
                "supports_fit_target": False,
                "supports_cache_ram": False,
                "supports_ctx_checkpoints": False,
                "ctx_checkpoints_flag": None,
                "supports_no_cache_prompt": False,
                "supports_metrics": False,
                "supports_slot_save": False,
                "supports_no_mmproj_offload": False,
                "supports_load_mode": False,
                "spec_draft_ngl_flag": None,
                "spec_draft_cache_k_flag": None,
                "spec_draft_cache_v_flag": None,
                "flags": {},
                "help_probe_ok": False,
            }
        try:
            binary_stat = Path(bin_path).stat()
            mtime_ns = binary_stat.st_mtime_ns
            size = binary_stat.st_size
        except OSError:
            mtime_ns = 0
            size = 0
        cache_key = (bin_path, mtime_ns, size)
        with cls._capability_cache_lock:
            cached = cls._capability_cache.get(cache_key)
            if cached is not None:
                if not cached.get("mtp_probe_inconclusive"):
                    return cached
                retry_after = cls._capability_retry_after.get(cache_key)
                if retry_after is not None and time.monotonic() < retry_after:
                    return cached
                cls._capability_cache.pop(cache_key, None)
                cls._capability_retry_after.pop(cache_key, None)

        mtp_token: Optional[str] = None
        supports_dspark = False
        supports_dflash = False
        ngram_mod_flavor: Optional[str] = None
        spec_draft_n_max_flag: Optional[str] = None
        spec_draft_n_max_default: Optional[int] = None
        supports_kv_unified = False
        # See the fallback dict: these fail open.
        supports_no_context_shift = True
        supports_jinja = True
        supports_flash_attn = True
        flash_attn_takes_value = True
        supports_fit_ctx = False
        supports_fit_target = False
        supports_cache_ram = False
        supports_ctx_checkpoints = False
        ctx_checkpoints_flag = None
        supports_no_cache_prompt = False
        supports_metrics = False
        supports_slot_save = False
        supports_no_mmproj_offload = False
        supports_load_mode = False
        spec_draft_ngl_flag = None
        spec_draft_cache_k_flag = None
        spec_draft_cache_v_flag = None
        saw_spec_type = False
        probe_ok = False
        help_text = ""
        # Every flag this build documents, with its help text. Pre-initialised for
        # the same reason as the booleans above: a failed probe must fall back to
        # "nothing known", not raise.
        blocks: dict[str, str] = {}
        # Same reason, and the reason it lives out here rather than beside the parse
        # loop: a probe that times out leaves the loop unrun, and the catalogue below
        # is still built. Reading an unset local there turned a slow binary into an
        # UnboundLocalError instead of "nothing known about this build".
        takes_value: dict[str, bool] = {}

        def _is_real(flag: str) -> bool:
            """True if the flag exists AND is not a removal stub."""
            desc = blocks.get(flag)
            if desc is None:
                return False
            return "argument has been removed" not in desc

        try:
            probe_env = cls._llama_server_env_for_binary(bin_path)
            # Capability detection describes the binary, independently of the
            # user's launch defaults. In particular, a device selected through
            # LLAMA_ARG_* becomes invalid when the macOS probe disables Metal.
            for name in tuple(probe_env):
                if name.startswith("LLAMA_ARG_"):
                    probe_env.pop(name, None)
            if sys.platform == "darwin":
                # Building --help asks llama_supports_rpc(), which otherwise
                # initializes Metal and compiles its embedded shaders. A cold
                # compile exceeds this probe's timeout; no device is needed to
                # enumerate the command-line flags.
                probe_env["GGML_METAL_DEVICES"] = "0"
            result = subprocess.run(
                [bin_path, "--help"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                check = False,
                env = probe_env,
            )
            probe_ok = result.returncode == 0
            help_text = (result.stdout or "") + "\n" + (result.stderr or "")
            # Split into per-flag blocks (each --flag line + its indented
            # continuation), so the "argument has been removed" description
            # sits with its flag.
            current_flags: list[str] = []
            current_desc: list[str] = []
            # Flag -> whether its declaration shows a value placeholder.
            current_takes_value = False
            for line in help_text.splitlines():
                stripped = line.strip()
                if stripped.startswith("-") and not line.startswith(" "):
                    # New flag line; flush previous.
                    if current_flags:
                        desc = " ".join(current_desc)
                        for f in current_flags:
                            blocks[f] = desc
                            takes_value[f] = current_takes_value
                    current_flags = []
                    current_desc = [stripped]
                    # Whether the flag takes a value at all, which is what tells
                    # "--verbose foo" (a typo llama-server refuses) from "--numa
                    # distribute". A placeholder follows its flag by a SINGLE space
                    # ("--threads N"); the description sits in an aligned column two
                    # or more spaces away. Only the yes/no is taken from this: how
                    # many values, and of what shape, is not worth guessing at from
                    # help text that wraps.
                    current_takes_value = False
                    _previous_end = None
                    for _match in re.finditer(r"\S+", stripped):
                        _token = _match.group()
                        _flag_shaped = _token.startswith("-") and re.match(
                            r"-{1,2}[A-Za-z][A-Za-z0-9_-]*,?$", _token
                        )
                        if _flag_shaped:
                            _previous_end = _match.end()
                            continue
                        # The first token that is not an alias: a placeholder when it
                        # is one space away, the description when it is further.
                        current_takes_value = (
                            _previous_end is not None and _match.start() - _previous_end == 1
                        )
                        break
                    # Extract long-form flag tokens from the DECLARATION
                    # prefix only (comma-separated aliases). Stop at the
                    # first non-flag token so flag references inside
                    # descriptions are ignored.
                    for tok in re.split(r"[,\s]+", stripped):
                        if tok.startswith("--") and re.match(r"--[A-Za-z][A-Za-z0-9_-]*$", tok):
                            current_flags.append(tok)
                        elif tok.startswith("-") and re.match(r"-[A-Za-z][A-Za-z0-9_-]*$", tok):
                            # A short alias (-fa, -t, -ngl). Kept, not just skipped:
                            # the catalogue is what the editor checks a typed flag
                            # against, and -t is as valid as --threads, so dropping
                            # it warned that a correct flag was unknown.
                            current_flags.append(tok)
                        elif tok.startswith("-") and len(tok) > 1:
                            # A value placeholder like -1; keep scanning aliases.
                            continue
                        else:
                            # First non-flag token marks end of decl.
                            break
                else:
                    current_desc.append(stripped)
            if current_flags:
                desc = " ".join(current_desc)
                for f in current_flags:
                    blocks[f] = desc
                    takes_value[f] = current_takes_value

            # MTP token from the full --spec-type help block (decl + indented
            # continuation). First-line-only probing missed builds putting the
            # enum on the next line (#7302). Prefer draft-mtp (PR #22673) over mtp.
            spec_help = blocks.get("--spec-type") or ""
            if not spec_help:
                # Fallback: join --spec-type lines, avoiding incidental "mtp" in --help.
                spec_help = "\n".join(
                    line for line in help_text.splitlines() if "--spec-type" in line
                )
            mtp_token = cls._mtp_token_from_spec_help(spec_help)
            supports_dspark = bool(
                re.search(
                    r"(?<![a-z0-9_-])draft-dspark(?![a-z0-9_-])",
                    spec_help.lower(),
                )
            )
            # Same word-boundary match as DSpark: draft-dflash only exists on
            # builds that carry the arch, and emitting a --spec-type the binary
            # does not know aborts the launch instead of falling back.
            supports_dflash = bool(
                re.search(
                    r"(?<![a-z0-9_-])draft-dflash(?![a-z0-9_-])",
                    spec_help.lower(),
                )
            )
            # Only a resolved --spec-type block confirms missing MTP; empty/crash
            # leaves saw_spec_type False so supports_mtp fails open.
            saw_spec_type = bool(spec_help.strip()) and "--spec-type" in spec_help

            # ngram-mod flag flavor. Post-rename builds advertise both new
            # args (real) and legacy ones (stubs); pre-rename builds only
            # have legacy ones as real.
            new_ngram_real = (
                _is_real("--spec-ngram-mod-n-match")
                and _is_real("--spec-ngram-mod-n-min")
                and _is_real("--spec-ngram-mod-n-max")
            )
            legacy_ngram_real = (
                _is_real("--spec-ngram-size-n")
                and _is_real("--draft-max")
                and _is_real("--draft-min")
            )
            if new_ngram_real:
                ngram_mod_flavor = "new"
            elif legacy_ngram_real:
                ngram_mod_flavor = "legacy"

            # n_max flag: prefer post-rename, fall back to legacy.
            if _is_real("--spec-draft-n-max"):
                spec_draft_n_max_flag = "--spec-draft-n-max"
            elif _is_real("--draft-max"):
                spec_draft_n_max_flag = "--draft-max"
            # And the build's OWN default for it, off the same help line. Needed
            # where the extras own --spec-type: Unsloth emits no depth then, so the
            # child runs on this number and the Hybrid Mamba rollback reserve
            # scales by it. None when the line carries no default.
            if spec_draft_n_max_flag:
                _n_max_default = re.search(
                    r"default:\s*(\d+)", blocks.get(spec_draft_n_max_flag) or ""
                )
                if _n_max_default:
                    spec_draft_n_max_default = int(_n_max_default.group(1))

            supports_kv_unified = _is_real("--kv-unified")
            # Only once the help actually parsed AND `--help` succeeded. Empty
            # `blocks` means the probe told us nothing, and a nonzero exit means
            # the listing may be a fragment; neither may read as "absent" for a
            # flag we would otherwise always send. A real llama-server prints
            # usage and exits 0, so this costs no supported build anything.
            if probe_ok and blocks:
                supports_no_context_shift = _is_real("--no-context-shift")
                supports_jinja = _is_real("--jinja")
                # Two answers, not one: whether the flag exists, and whether its
                # declaration takes a value. A build predating flash attention
                # has neither, and emitting the flag there is an immediate exit.
                supports_flash_attn = _is_real("--flash-attn")
                flash_attn_takes_value = cls._flash_attn_takes_value(help_text)
            supports_fit_ctx = _is_real("--fit-ctx")
            supports_fit_target = _is_real("--fit-target")
            supports_cache_ram = _is_real("--cache-ram")
            # --swa-checkpoints is the older spelling, kept as an alias on newer
            # builds. Probing the modern name alone drops the Checkpoints control on
            # a build carrying only the old one, so record WHICH name this build has,
            # like the draft-cache pair below.
            for _alias in ("--ctx-checkpoints", "--swa-checkpoints"):
                if _is_real(_alias):
                    ctx_checkpoints_flag = _alias
                    break
            supports_ctx_checkpoints = ctx_checkpoints_flag is not None
            supports_no_cache_prompt = _is_real("--no-cache-prompt")
            supports_metrics = _is_real("--metrics")
            supports_slot_save = _is_real("--slot-save-path")
            supports_no_mmproj_offload = _is_real("--no-mmproj-offload")
            # --load-mode supersedes --mlock / --no-mmap, which are deprecated.
            # Pre-initialised above: a failed probe must fall back, not raise.
            supports_load_mode = _is_real("--load-mode")
            # Record WHICH alias this build has: --spec-draft-ngl only landed in
            # b8955, and a build exposing only --gpu-layers-draft would refuse to
            # start on the newer name. Long forms only, since the block parser above
            # skips short aliases, so "-ngld" could never have matched.
            for _alias in ("--spec-draft-ngl", "--gpu-layers-draft", "--n-gpu-layers-draft"):
                if _is_real(_alias):
                    spec_draft_ngl_flag = _alias
                    break
            # Same alias dance for the draft KV cache pair: --spec-draft-type-* is
            # the modern spelling, --cache-type-*-draft the older, and a build with
            # only one exits on the other. K and V probed independently (upstream
            # renamed them together; a fork need not have). Long forms only.
            for _alias in ("--spec-draft-type-k", "--cache-type-k-draft"):
                if _is_real(_alias):
                    spec_draft_cache_k_flag = _alias
                    break
            for _alias in ("--spec-draft-type-v", "--cache-type-v-draft"):
                if _is_real(_alias):
                    spec_draft_cache_v_flag = _alias
                    break
        except (OSError, subprocess.SubprocessError) as exc:
            logger.debug(f"llama-server --help probe failed: {exc}")
            saw_spec_type = False
            probe_ok = False
            help_text = ""

        help_nonempty = bool(help_text.strip())
        # Confirmed only when a successful --help lists a --spec-type block with
        # mtp/draft-mtp; nonempty --help without it is a definitive pre-spec
        # binary; failed/empty probes stay inconclusive (#7302).
        if saw_spec_type and probe_ok:
            supports_mtp = mtp_token is not None
            mtp_probe_inconclusive = False
        elif help_nonempty and probe_ok:
            supports_mtp = False
            mtp_probe_inconclusive = False
        else:
            supports_mtp = False
            mtp_probe_inconclusive = True

        if supports_dspark:
            try:
                from utils.llama_cpp_freshness import read_install_marker

                marker = read_install_marker(bin_path) or {}
                release_tag = marker.get("release_tag") or marker.get("tag")
                if cls._dspark_release_is_broken(release_tag):
                    supports_dspark = False
                    logger.info(
                        "Disabling DSpark for known-broken llama.cpp prebuilt %s",
                        release_tag,
                    )
            except Exception as exc:
                logger.debug("Could not inspect llama.cpp prebuilt identity: %s", exc)

        info = {
            "found": True,
            "mtp_token": mtp_token,
            "supports_mtp": supports_mtp,
            "supports_dspark": bool(supports_dspark and saw_spec_type and probe_ok),
            "supports_dflash": bool(supports_dflash and saw_spec_type and probe_ok),
            "mtp_probe_inconclusive": mtp_probe_inconclusive,
            "ngram_mod_flavor": ngram_mod_flavor,
            "supports_ngram_mod": ngram_mod_flavor is not None,
            "spec_draft_n_max_flag": spec_draft_n_max_flag,
            "spec_draft_n_max_default": spec_draft_n_max_default,
            "supports_kv_unified": supports_kv_unified,
            "supports_no_context_shift": supports_no_context_shift,
            "supports_jinja": supports_jinja,
            "supports_flash_attn": supports_flash_attn,
            "flash_attn_takes_value": flash_attn_takes_value,
            "supports_fit_ctx": supports_fit_ctx,
            "supports_fit_target": supports_fit_target,
            "supports_cache_ram": supports_cache_ram,
            "supports_ctx_checkpoints": supports_ctx_checkpoints,
            "ctx_checkpoints_flag": ctx_checkpoints_flag,
            "supports_no_cache_prompt": supports_no_cache_prompt,
            "supports_metrics": supports_metrics,
            "supports_slot_save": supports_slot_save,
            "supports_no_mmproj_offload": supports_no_mmproj_offload,
            "supports_load_mode": supports_load_mode,
            "spec_draft_ngl_flag": spec_draft_ngl_flag,
            "spec_draft_cache_k_flag": spec_draft_cache_k_flag,
            "spec_draft_cache_v_flag": spec_draft_cache_v_flag,
            # The whole parsed catalogue, not just the booleans above. The UI
            # validates pass-through args against THIS build rather than a list
            # bundled with Unsloth, since a custom or newer llama.cpp is exactly
            # the case where a bundled list would be wrong. Removal stubs are
            # excluded: a build that still lists --draft-max only to say the
            # argument has been removed would otherwise read as supporting it,
            # and the editor would stay quiet about a flag the load then refuses.
            "flags": {flag: desc for flag, desc in blocks.items() if _is_real(flag)},
            # The flags that take no value, so the editor can tell "--verbose foo"
            # (a typo llama-server refuses) from "--numa distribute".
            "switch_flags": sorted(
                flag for flag, takes in takes_value.items() if not takes and _is_real(flag)
            ),
            # Whether --help actually succeeded. A run that exits nonzero after
            # printing part of its help still leaves a non-empty catalogue, and a
            # caller that equated "parsed something" with "read the whole thing"
            # would call every flag past the failure point unknown.
            "help_probe_ok": bool(probe_ok),
        }
        with cls._capability_cache_lock:
            published = cls._capability_cache.get(cache_key)
            if published is not None and (
                not published.get("mtp_probe_inconclusive") or mtp_probe_inconclusive
            ):
                # Concurrent callers may finish out of order. Never replace a
                # conclusive result with a timeout, or a newer retry result with
                # another result of the same confidence.
                return published
            cls._capability_cache[cache_key] = info
            if mtp_probe_inconclusive:
                # Bound both failure modes: do not pin a transient failure for
                # the process lifetime, and do not make every caller repeat a
                # 10-second timeout while a persistent failure remains (#8317).
                cls._capability_retry_after[cache_key] = (
                    time.monotonic() + cls._CAPABILITY_PROBE_RETRY_SECONDS
                )
            else:
                cls._capability_retry_after.pop(cache_key, None)
            return info

    @staticmethod
    def _mtp_token_from_spec_help(spec_help: str) -> Optional[str]:
        """Extract ``draft-mtp`` / ``mtp`` from a ``--spec-type`` help snippet.

        Prefers ``draft-mtp`` (llama.cpp PR #22673) over the later bare ``mtp``
        rename. Returns ``None`` when neither token appears as an enum value.
        """
        text = spec_help or ""
        if "draft-mtp" in text:
            return "draft-mtp"
        # Bare `mtp` enum token (`|mtp|`, `,mtp,`, ...), not a substring.
        if re.search(r"(?<![A-Za-z0-9_-])mtp(?![A-Za-z0-9_-])", text):
            return "mtp"
        return None

    # ── GPU allocation ────────────────────────────────────────────

    @staticmethod
    def _get_gguf_size_bytes(model_path: str) -> int:
        """Total GGUF size in bytes, including split shards."""
        main = Path(model_path)
        total = main.stat().st_size

        # Check for split shards (e.g. model-00001-of-00003.gguf)
        m = _SHARD_FULL_RE.match(main.name)
        if m:
            prefix, _, num_total = m.group(1), m.group(2), m.group(3)
            sibling_pat = re.compile(
                r"^" + re.escape(prefix) + r"-\d{5}-of-" + re.escape(num_total) + r"\.gguf$",
                re.IGNORECASE,
            )
            for sibling in main.parent.iterdir():
                if sibling != main and sibling_pat.match(sibling.name):
                    total += sibling.stat().st_size

        return total

    @staticmethod
    def _installed_ggml_backends(binary: Optional[str] = None) -> frozenset[str]:
        """Backend libraries shipped beside llama-server."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return frozenset()
        try:
            files = tuple(path.name for path in _llama_lib_dir(binary).iterdir() if path.is_file())
        except OSError:
            return frozenset()
        backends = set()
        for backend in ("base", "cpu", "cuda", "hip", "vulkan"):
            stem = f"ggml-{backend}.dll" if sys.platform == "win32" else f"libggml-{backend}.so"
            if any(name == stem or name.startswith(stem + ".") for name in files):
                backends.add(backend)
        return frozenset(backends)

    @staticmethod
    def _is_vulkan_backend(binary: Optional[str] = None) -> bool:
        """True if the installed llama.cpp build is Vulkan-only.

        The official prebuilts are single-backend, so the Vulkan ggml lib next
        to llama-server identifies a Vulkan build. Keeps the free-memory probe
        and GPU pin in ggml's Vulkan device-index space. For a custom
        multi-backend build with a CUDA or HIP ggml lib alongside Vulkan, defer
        to that backend (torch-usable, better-understood probe/pin).
        """
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        return "vulkan" in backends and not backends.intersection({"cuda", "hip"})

    @staticmethod
    def _active_gpu_visibility_mask() -> Optional[str]:
        """The raw visibility mask in force (HIP, then ROCR, then CUDA on ROCm; CUDA
        otherwise), or None when unset. Split out so a caller can tell "no mask" from
        "a mask I cannot map to physical ids"."""
        try:
            import torch

            # Same ROCm detection as _emit_child_gpu_visibility (AMD SDK wheels leave
            # version.hip unset but encode "rocm" in __version__). If the two
            # disagree an inherited ROCR mask reads back as "no mask" and the child's
            # new pin re-exposes the GPU it was hiding.
            is_rocm = LlamaCppBackend._torch_is_rocm(torch)
        except Exception:
            is_rocm = False
        if is_rocm:
            hip_v = os.environ.get("HIP_VISIBLE_DEVICES")
            # ROCR_VISIBLE_DEVICES is Linux-only: Windows HIP has no ROCr layer, so a
            # stray ROCR var there masks nothing and must not be read as the
            # ordinal->physical mapping (mirrors _emit_child_gpu_visibility).
            rocr_v = None if sys.platform == "win32" else os.environ.get("ROCR_VISIBLE_DEVICES")
            cvd = (
                hip_v
                if hip_v is not None
                else rocr_v
                if rocr_v is not None
                else os.environ.get("CUDA_VISIBLE_DEVICES")
            )
        else:
            cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
        return cvd

    @staticmethod
    def _resolve_visible_physical_ids() -> Optional[list[int]]:
        """Physical GPU ids behind the active visibility mask (HIP/ROCR/CUDA on
        ROCm, CUDA otherwise). None when unset, [] for an empty mask. Shared by the
        APU / datacenter / free-memory probes so they agree on the mapping."""
        cvd = LlamaCppBackend._active_gpu_visibility_mask()
        if cvd is None:
            return None
        try:
            return [int(x.strip()) for x in cvd.split(",") if x.strip()]
        except ValueError:
            return None

    @staticmethod
    def _visibility_mask_is_unmappable() -> bool:
        """True when a mask IS set but does not resolve to physical ids: ROCr and CUDA
        accept UUID tokens (ROCR_VISIBLE_DEVICES="0,GPU-DEADBEEF..."), CUDA also MIG
        ids. Torch ordinals cannot be mapped back, so re-emitting them numerically
        would REPLACE the mask with ids the runtime resolves against the whole host,
        handing the child cards the parent hid, including one a gate just dropped.
        Callers that would pin fail open. False when unset and for an empty mask."""
        return (
            LlamaCppBackend._active_gpu_visibility_mask() is not None
            and LlamaCppBackend._resolve_visible_physical_ids() is None
        )

    @staticmethod
    def _emit_child_gpu_visibility(
        env: dict,
        pinned: str,
        *,
        prefer_rocr: bool = False,
    ) -> None:
        """Write the child's GPU visibility mask: CUDA, plus a ROCm mirror on AMD
        (masking only CUDA_VISIBLE_DEVICES leaves an AMD child seeing every GPU).

        Default: HIP_VISIBLE_DEVICES, clearing any inherited ROCR mask so the two
        cannot stack (ROCR re-indexes from 0, a non-zero HIP pin then points out of
        range, HIP sees 0 devices, and llama.cpp falls back to CPU).

        prefer_rocr masks at the ROCr/HSA layer instead (clearing HIP): a HIP mask
        filters only AFTER the HSA runtime enumerates every agent, and that
        enumeration segfaults on a GPU the build has no kernels for (gfx1036 iGPU
        under a gfx103X prebuilt) before llama-server logs a line.

        The CPU sentinel ("-1") keeps the HIP mask and leaves an inherited ROCR mask
        alone: HIP sees zero devices either way, so the anti-stacking clear buys
        nothing while dropping the mask re-exposes hidden agents to that same
        enumeration. Windows keeps the HIP mask too, ROCR being Linux-only."""
        env["CUDA_VISIBLE_DEVICES"] = pinned
        if pinned == "-1":
            # An inherited LLAMA_ARG_DEVICE / LLAMA_ARG_MAIN_GPU naming a device that
            # no longer enumerates makes llama.cpp exit rather than use our CPU.
            LlamaCppBackend._clear_device_placement_env(env)
        try:
            import torch as _torch

            # torch.version.hip is set on ROCm, None on CUDA; AMD SDK wheels may
            # leave it unset but encode "rocm" in __version__ (mirrors detect_hardware).
            if (
                getattr(_torch.version, "hip", None) is not None
                or "rocm" in getattr(_torch, "__version__", "").lower()
            ):
                if prefer_rocr and pinned != "-1" and sys.platform != "win32":
                    env["ROCR_VISIBLE_DEVICES"] = pinned
                    env.pop("HIP_VISIBLE_DEVICES", None)
                    # ROCR re-indexes the visible agents from 0, and with HIP
                    # cleared HIP honours CUDA_VISIBLE_DEVICES -- so it must carry
                    # the post-ROCR ordinals (0..N-1), not the physical ids, else a
                    # non-zero pick points out of range and HIP sees 0 devices (the
                    # same stacking the default path avoids by clearing ROCR).
                    env["CUDA_VISIBLE_DEVICES"] = ",".join(
                        str(i) for i in range(len(pinned.split(",")))
                    )
                else:
                    env["HIP_VISIBLE_DEVICES"] = pinned
                    if pinned != "-1":
                        env.pop("ROCR_VISIBLE_DEVICES", None)
        except Exception as e:
            logger.debug("Failed to set ROCm visibility env vars for child: %s", e)

    @staticmethod
    def _pin_visible_gpu_order_for_split(env: dict) -> None:
        """Pin the child's GPU enumeration to the picker's order for a manual
        ``--tensor-split`` across the whole visible set. CUDA's default
        FASTEST_FIRST enumeration applies the shares to the wrong cards on
        heterogeneous hosts (#5025), and CUDA_DEVICE_ORDER only fixes the
        numbering base: an inherited numeric visibility mask ALSO defines
        enumeration order, so a reordered parent mask (CUDA_VISIBLE_DEVICES=3,1)
        would still hand the shares to the wrong cards. The UI built the split
        positionally over get_backend_visible_gpu_info's device list (ascending
        physical via nvidia-smi, inherited mask order on the torch fallback), so
        re-emit the same set in that report order -- not an assumed ascending
        sort. The visible set itself never changes. No mask, an empty mask, or a
        UUID/MIG mask (which resolves to None) is left alone -- the multi-GPU
        controls are hidden for the latter."""
        env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
        inherited = LlamaCppBackend._resolve_visible_physical_ids()
        if not inherited:
            return
        order = None
        try:
            from utils.hardware import get_backend_visible_gpu_info
            info = get_backend_visible_gpu_info()
            if info.get("available") and info.get("index_kind") == "physical":
                reported = [d["index"] for d in info.get("devices", [])]
                if sorted(reported) == sorted(inherited):
                    order = reported
        except Exception as e:
            logger.debug("Could not read reported GPU order for split pin: %s", e)
        if order is None:
            order = sorted(inherited)
        # Re-emit at the layer that produced the mapping. A parent masked only
        # via ROCR_VISIBLE_DEVICES hides agents at the driver layer, and the
        # default HIP re-emission clears that mask -- HSA then enumerates every
        # agent again and can segfault at startup on an unsupported GPU the
        # parent was hiding (the crash prefer_rocr exists to avoid). Linux-only,
        # mirroring _resolve_visible_physical_ids: on Windows a stray ROCR var
        # is dead and was not the mapping's source.
        prefer_rocr = (
            sys.platform != "win32"
            and env.get("HIP_VISIBLE_DEVICES") is None
            and env.get("ROCR_VISIBLE_DEVICES") is not None
        )
        LlamaCppBackend._emit_child_gpu_visibility(
            env, ",".join(str(i) for i in order), prefer_rocr = prefer_rocr
        )

    @staticmethod
    def _vulkan_targets_are_igpus(binary: Optional[str], gpu_indices = None) -> bool:
        """True when any Vulkan device in play is integrated.

        An iGPU's reported "VRAM" is shared system RAM (see
        ``_apply_igpu_host_reserve_mib``), so a model "fully offloaded" onto one
        is still backed by pageable host memory and is worth page-locking. Any,
        not every: a mixed selection splits weights onto the iGPU too, and those
        pages are as evictable as if it were the only device. An unreadable probe
        answers False.
        """
        try:
            rows = LlamaCppBackend._run_vulkan_probe(binary)
        except Exception:
            return False
        if not rows:
            return False
        wanted = set(gpu_indices) if gpu_indices else None
        selected = [r for r in rows if wanted is None or r["index"] in wanted]
        return any(r["is_igpu"] for r in selected)

    def _weights_in_host_memory(
        self,
        *,
        fully_gpu_offloaded: bool,
        gpu_memory_mode: Optional[str],
        gpu_layers: Optional[int],
        extra_args: Optional[Iterable[str]],
        gpu_indices = None,
        is_vulkan_backend: bool = False,
        binary: Optional[str] = None,
        env: Optional[Mapping[str, str]] = None,
        probe_vulkan: bool = True,
        fit_active: bool = False,
    ) -> bool:
        """True when the weights will sit in pageable host RAM, so mlock helps.

        Only the Model Memory gate uses this, and only to SKIP page-locking, so
        it errs towards True: that is the pre-existing behaviour.

        ``probe_vulkan`` False skips the Vulkan probe, the one subprocess in
        here, for a bookkeeping-only call; that keeps the conservative True.
        """
        from utils.hardware import is_apple_silicon

        # A CPU placement extra keeps weights in RAM whatever the layer count,
        # so it applies to the auto path too and cannot be short-circuited past.
        # Inherited env does the same and outlives any token stripping.
        if _args_place_tensors_on_cpu(extra_args):
            return True
        if _env_places_tensors_on_cpu(env):
            return True
        # A --device that names no GPU beats any layer count: llama.cpp has
        # nowhere to offload to, so the whole model stays in host RAM.
        if _device_selection_is_cpu(extra_args, env):
            return True
        # fully_gpu_offloaded predicts OUR "-ngl -1 --fit off", but auto keeps the
        # user's extras and appends them after, and llama.cpp is last-wins, so an
        # -ngl 0 lands the model in RAM. Only a fit that is switched ON voids the
        # prediction: "--fit off" is what we already pass, and a disabled fitter
        # cannot move anything to the CPU.
        if _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS) or fit_is_enabled_in(extra_args):
            fully_gpu_offloaded = False
        all_on_gpu = fully_gpu_offloaded or self._offloads_every_layer(
            gpu_memory_mode = gpu_memory_mode,
            gpu_layers = gpu_layers,
            extra_args = extra_args,
            fit_active = fit_active,
        )
        if not all_on_gpu:
            return True
        # Unified memory: the "VRAM" is host RAM, so the weights stay pageable
        # however fully they are offloaded.
        if is_apple_silicon():
            return True
        if is_vulkan_backend:
            # gpu_indices are Vulkan ordinals here, which the ROCm APU helper
            # would read as physical ids and answer for the wrong device. The
            # Vulkan probe owns device type; unprobed keeps the True answer.
            return not probe_vulkan or self._vulkan_targets_are_igpus(binary, gpu_indices)
        return self._amd_apu_wants_unified_memory(gpu_indices)

    def _offloads_every_layer(
        self,
        *,
        gpu_memory_mode: Optional[str],
        gpu_layers: Optional[int],
        extra_args: Optional[Iterable[str]],
        fit_active: bool = False,
    ) -> bool:
        """True when every layer lands on the GPU by a route ``fully_gpu_offloaded``
        does not cover: manual mode at its full-offload maximum, or a user -ngl.

        Only the Model Memory gate uses this, and only to SKIP page-locking, so
        every unknown answers False and keeps the pre-existing behaviour: an
        unreadable block count, CPU-side experts, a tensor override that places
        weights by name, or an unparseable -ngl.
        """
        n_layers = self.n_layers
        if not n_layers:
            return False
        if self._n_cpu_moe:
            return False
        # The parsed predicate, not flag presence: --n-cpu-moe 0 places nothing,
        # and answering False here would pin host RAM for an all-GPU launch.
        if _args_place_tensors_on_cpu(extra_args):
            return False
        requested: Optional[int] = None
        if gpu_memory_mode == "manual" and gpu_layers is not None and gpu_layers >= 0:
            # Manual owns offload and strips -ngl from the extras, so the field
            # is what the child gets. The picker's maximum is n_layers + 1.
            requested = gpu_layers
        else:
            try:
                requested = parse_gpu_layers_override(extra_args)
            except ValueError:
                return False
        if requested is None:
            return False
        # -1 is "all layers"; llama.cpp needs a count ABOVE the block count to
        # cover the output layer too, which is what the picker's maximum sends.
        # -1 is also llama.cpp's DEFAULT, so an active fitter is free to lower it
        # (common/fit.cpp aborts only on a count the user really set); a concrete
        # count stands, which is why only this arm is gated.
        if requested == -1:
            return not fit_active
        return requested > n_layers

    def _partially_offloads_layers(
        self,
        args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        fit_implies_partial: bool = True,
    ) -> bool:
        """Whether the effective main-model layer policy is partial GPU offload.

        A concrete layer count owns placement even when ``--fit on`` is present.
        Otherwise ``-1`` (or an omitted count) is partial only while the fitter may
        lower it. Zero is CPU-only rather than partial offload, and keeps CPU MTP,
        and so is a ``--device`` selection naming no GPU: llama.cpp then runs the
        model on the CPU whatever the layer count and the fitter say.

        ``fit_implies_partial`` is what an active fitter is allowed to mean. In Auto
        it is evidence: the planner ran and could not prove the model fits, which is
        why the fitter is on. In Manual mode the planner is skipped by design, so
        ``--fit on`` is a default rather than a verdict and says nothing about
        placement -- pass False there and let a concrete count answer instead.
        """
        n_layers = self.n_layers
        if not n_layers:
            return False
        try:
            requested = parse_gpu_layers_override(args)
        except ValueError:
            return False
        source_env = os.environ if env is None else env
        if _device_selection_is_cpu(args, source_env):
            return False
        if requested is None:
            raw = source_env.get("LLAMA_ARG_N_GPU_LAYERS")
            if raw is not None and raw.strip():
                try:
                    requested = int(raw)
                except ValueError:
                    requested = None
        if requested == 0:
            return False
        if requested is not None and requested > 0:
            # llama.cpp needs a count above block_count to include the output
            # layer, matching _offloads_every_layer.
            return requested <= n_layers
        return fit_implies_partial and fit_is_effectively_on(args, source_env)

    @staticmethod
    def _torch_is_rocm(torch) -> bool:
        """Whether this torch is a ROCm build. AMD SDK wheels leave
        ``version.hip`` unset and only encode "rocm" in ``__version__``."""
        return (
            getattr(torch.version, "hip", None) is not None
            or "rocm" in getattr(torch, "__version__", "").lower()
        )

    @staticmethod
    def _host_torch_is_rocm() -> bool:
        """Whether torch here is a ROCm build, without the caller importing torch.
        False when torch is missing or unreadable. Cheap guard so a CUDA or
        CPU-only host does not pay for ROCm-only work (#7624)."""
        try:
            import torch
            return LlamaCppBackend._torch_is_rocm(torch)
        except Exception:
            return False

    @staticmethod
    def _rocm_unified_memory_gpu_ids() -> set[int]:
        """PHYSICAL ids of visible ROCm GPUs whose "VRAM" is shared system RAM.

        Delegates to the training worker's classifier so both paths agree on what
        an APU is: it reads the driver's own ``is_integrated`` first, then the
        arch-name spellings, then the Radeon name table, because AMD SDK wheels
        may populate none of the arch attributes. Empty off ROCm and on error, so
        every caller keeps its discrete-GPU default.
        """
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return set()
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return set()
            from core.training.worker import _rocm_classify_unified_memory

            # Map visible ordinal -> physical id via the active ROCm mask (HIP,
            # then ROCR, then CUDA), mirroring _get_gpu_memory's ROCm branch.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            unified: set[int] = set()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    _arch, is_unified = _rocm_classify_unified_memory(
                        torch.cuda.get_device_properties(ordinal)
                    )
                except Exception:
                    continue
                if not is_unified:
                    continue
                unified.add(
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
            return unified
        except Exception:
            return set()

    @staticmethod
    def _rocm_arch_by_physical_id() -> dict[int, str]:
        """Base gfx arch (lowercased, ``:xnack`` stripped) per PHYSICAL device id,
        honoring the active ROCm visibility mask (HIP, then ROCR, then CUDA).

        Read through the training worker's classifier so the alternate spellings
        AMD SDK / Radeon wheels use (``gcn_arch_name``, ``arch_name``,
        ``gfx_arch_name``) are covered as well as canonical ``gcnArchName``;
        reading only the canonical name would leave the map empty on those wheels
        and silently fail the gate open. Devices torch cannot describe are omitted;
        empty off ROCm and on any error."""
        arch_by_id: dict[int, str] = {}
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return arch_by_id
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return arch_by_id
            from core.training.worker import _rocm_classify_unified_memory

            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    _arch, _is_unified = _rocm_classify_unified_memory(
                        torch.cuda.get_device_properties(ordinal)
                    )
                except Exception:
                    continue
                _base = (_arch or "").split(":")[0].strip().lower()
                if not _base:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                arch_by_id[pid] = _base
        except Exception:
            return arch_by_id
        return arch_by_id

    @staticmethod
    def _amd_apu_wants_unified_memory(gpu_indices = None) -> bool:
        """True only for AMD unified-memory APUs, where GGML_CUDA_ENABLE_UNIFIED_MEMORY
        lets llama.cpp use shared system RAM (it hurts discrete GPUs). gpu_indices
        (PHYSICAL ids) scopes the check, so a dGPU on a mixed host is not treated as
        unified-memory; None means every visible GPU."""
        # Guarded like the rest of this family: a bad gpu_indices (not iterable,
        # unhashable members) answers False rather than failing the load.
        try:
            unified = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            if gpu_indices is None:
                return bool(unified)
            return any(_i in unified for _i in gpu_indices)
        except Exception:
            return False

    @staticmethod
    def _integrated_cuda_gpu_ids() -> set[int]:
        """PHYSICAL ids of visible CUDA GPUs whose "VRAM" is shared system RAM.

        Jetson and DGX Spark class parts set cudaDeviceProp::integrated, which torch
        surfaces as ``is_integrated``; the diffusion memory policy reads the same flag
        (diffusion_memory.py:292-294). ROCm is excluded because it reuses
        ``torch.cuda.*`` and ``_rocm_unified_memory_gpu_ids`` already answers for it.
        Empty off CUDA and on error, so every caller keeps its discrete-GPU default.
        """
        try:
            import torch

            if LlamaCppBackend._torch_is_rocm(torch):
                return set()
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return set()
            # Same ordinal -> physical mapping the ROCm twin uses, so a masked host
            # (CUDA_VISIBLE_DEVICES=2) does not answer for the wrong card.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            integrated: set[int] = set()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    props = torch.cuda.get_device_properties(ordinal)
                except Exception:
                    continue
                # Both spellings: the attribute was `integrated` before torch renamed
                # it, and an old wheel exposing neither reads discrete.
                if not (
                    getattr(props, "is_integrated", False) or getattr(props, "integrated", False)
                ):
                    continue
                integrated.add(
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
            return integrated
        except Exception:
            return set()

    @staticmethod
    def _integrated_cuda_unified_memory(gpu_indices = None) -> bool:
        """True when a credited CUDA device is an integrated (unified-memory) SoC.

        Scoped by gpu_indices (PHYSICAL ids) like its ROCm twin, so a dGPU on a
        mixed host is not treated as unified; None means every visible GPU. Any
        integrated device is enough: one shared pool in the credited set is already
        the double count.
        """
        try:
            integrated = LlamaCppBackend._integrated_cuda_gpu_ids()
            if gpu_indices is None:
                return bool(integrated)
            return any(_i in integrated for _i in gpu_indices)
        except Exception:
            return False

    # "Off" spellings ggml itself ignores (it tests presence); we honour them.
    _UNIFIED_MEMORY_OFF = frozenset({"", "0", "false", "no", "off"})

    @staticmethod
    def _unified_memory_opted_out(env = None) -> bool:
        """True when GGML_CUDA_ENABLE_UNIFIED_MEMORY must be ABSENT from this launch.

        ggml tests presence, not value, so `=0` is not an off switch (#8651). Both
        opt-outs (UNSLOTH_DISABLE_UNIFIED_MEMORY=1, mirroring UNSLOTH_DISABLE_DC_TUNING,
        or a falsy GGML_CUDA_ENABLE_UNIFIED_MEMORY) must end in the name unset.
        Fails open (False) so a bad env never blocks a load.
        """
        try:
            source = os.environ if env is None else env
            if str(source.get("UNSLOTH_DISABLE_UNIFIED_MEMORY", "")).strip() == "1":
                return True
            value = source.get("GGML_CUDA_ENABLE_UNIFIED_MEMORY")
            if value is None:
                return False
            return str(value).strip().lower() in LlamaCppBackend._UNIFIED_MEMORY_OFF
        except Exception:
            return False

    # Datacenter / professional NVIDIA parts that benefit from the llama.cpp
    # FP32-accum / P2P tunings. Whole-word (\b) so short markers don't match
    # workstation parts as substrings: "a100" must not fire on "RTX A1000".
    _DATACENTER_GPU_RE = re.compile(
        r"\b(?:a100|a30|h100|h200|h800|gh200|b200|b100|b300|gb200|gb300|"
        r"l40s?|l4|rtx pro 6000|rtx 6000 ada)\b"
    )

    @staticmethod
    def _is_datacenter_gpu(gpu_indices = None) -> bool:
        """True iff every selected NVIDIA GPU is a datacenter/professional part.
        NVIDIA-only, fails open to False (consumer GeForce, ROCm, CPU and errors
        are left untouched); a mixed DC+consumer selection counts as non-DC.

        gpu_indices are PHYSICAL ids (see _get_gpu_free_memory), but
        get_device_properties wants mask-relative ordinals, so we rebuild the
        ordinal->physical map from CUDA_VISIBLE_DEVICES and key names by physical
        id. Otherwise a masked host (CUDA_VISIBLE_DEVICES=4,5,6,7, selection [4,5])
        would drop the tuning or probe the wrong GPU."""
        try:
            import torch

            if getattr(torch.version, "hip", None) is not None:
                return False  # ROCm reuses torch.cuda.*; not a CUDA part
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return False
            count = torch.cuda.device_count()

            # Mirror _get_gpu_free_memory: map visible ordinal -> physical id via
            # CUDA_VISIBLE_DEVICES; unset/unparsable leaves physical id == ordinal.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()

            pattern = LlamaCppBackend._DATACENTER_GPU_RE
            names_by_id: dict[int, str] = {}
            for ordinal in range(count):
                try:
                    name = (torch.cuda.get_device_properties(ordinal).name or "").lower()
                except Exception:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                names_by_id[pid] = name

            indices = list(gpu_indices) if gpu_indices else list(names_by_id)
            saw = False
            for _i in indices:
                name = names_by_id.get(_i)
                if name is None:
                    continue  # not visible -> skip (fail conservative)
                saw = True
                if not pattern.search(name):
                    return False
            return saw
        except Exception:
            return False

    @staticmethod
    def _effective_gpu_count(gpu_indices = None) -> int:
        """GPUs llama-server will use: len(selection), else the visible CUDA
        device count (None = every visible GPU). 0 on error so multi-GPU tuning
        stays off when the count is unknown."""
        if gpu_indices is not None:
            return len(gpu_indices)
        try:
            import torch
            if hasattr(torch, "cuda") and torch.cuda.is_available():
                return torch.cuda.device_count()
        except Exception:
            return 0
        return 0

    @staticmethod
    def _apply_datacenter_env(env: dict, gpu_indices = None) -> bool:
        """Inject DC llama.cpp tuning into env in place via setdefault (user
        values win); return whether the box qualified. Opt out with
        UNSLOTH_DISABLE_DC_TUNING=1; only datacenter NVIDIA parts qualify
        (consumer/ROCm/CPU/error are a no-op). Sets GGML_CUDA_FORCE_CUBLAS_COMPUTE_32F
        for any qualifying GPU (FP32 accum: ~0% cost on B200, real cost on GeForce),
        plus GGML_CUDA_P2P + CUDA_SCALE_LAUNCH_QUEUES=4x for multi-GPU (+33-51% pp
        tensor-split, +8-16% pipeline split on B200)."""
        if os.environ.get("UNSLOTH_DISABLE_DC_TUNING") == "1":
            return False
        if not LlamaCppBackend._is_datacenter_gpu(gpu_indices):
            return False
        env.setdefault("GGML_CUDA_FORCE_CUBLAS_COMPUTE_32F", "1")
        if LlamaCppBackend._effective_gpu_count(gpu_indices) > 1:
            env.setdefault("GGML_CUDA_P2P", "1")
            env.setdefault("CUDA_SCALE_LAUNCH_QUEUES", "4x")
        return True

    @staticmethod
    def _visible_devices_mask(env_name: str) -> Optional[set[int]]:
        """Physical indices a ``*_VISIBLE_DEVICES`` mask permits, or None if unset.

        ``if x.strip()`` filters trailing-comma masks ("0,1,"); an empty mask
        ("") yields an empty set (all devices hidden), distinct from an unset
        var (None, no mask). Used by the nvidia-smi probe.
        """
        raw = os.environ.get(env_name)
        if raw is None:
            return None
        try:
            return set(int(x.strip()) for x in raw.split(",") if x.strip())
        except ValueError:
            return None

    @staticmethod
    def _vulkan_pin_args(gpu_indices: Optional[Iterable[int]]) -> list[str]:
        """``--device Vulkan<i>,...`` to pin a Vulkan launch to selected GPUs.

        The indices are ggml's compact Vulkan ordinals (as _get_gpu_free_memory
        reports and the registry names ``Vulkan<i>``). Pin by that name, NOT via
        GGML_VK_VISIBLE_DEVICES: ggml parses that env var in the raw
        vkEnumeratePhysicalDevices space (before dropping CPU/llvmpipe devices
        and deduplicating ICDs), so a compact ordinal there could select a
        different physical device or the CPU rasterizer.
        """
        if not gpu_indices:
            return []
        return ["--device", ",".join(f"Vulkan{i}" for i in gpu_indices)]

    @staticmethod
    def _backend_lacks_gpu_lib(binary: Optional[str] = None) -> bool:
        """Detect a split-library build proven to be CPU-only.

        Unknown and static layouts return False to avoid rejecting custom GPU builds.
        """
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return False
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        return bool(backends.intersection({"cpu", "base"})) and not backends.intersection(
            {"cuda", "hip", "vulkan"}
        )

    def is_vulkan_build(self) -> bool:
        """Whether the resolved llama-server uses Vulkan ordinals."""
        try:
            return self._is_vulkan_backend(self._find_llama_server_binary())
        except Exception:
            return False

    @staticmethod
    def _strip_device_extra_args(extra_args):
        """Drop device and main-GPU flags so gpu_ids remains authoritative."""
        return strip_shadowing_flags(
            extra_args,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            strip_device = True,
        )

    # A concrete per-device gfx arch: "gfx" plus digits, with the trailing hex letter
    # real parts carry (gfx90a, gfx90c), which a digits-only pattern would reject.
    # Deliberately does NOT match generic code objects (gfx11-generic) or family
    # labels (gfx110X); no device reports either, and the gate fails open on them.
    _CONCRETE_GFX_ARCH = re.compile(r"^gfx[0-9][0-9a-f]{2,4}$")

    @staticmethod
    def _installed_llama_gfx_archs(binary: Optional[str] = None) -> Optional[frozenset]:
        """Concrete gfx archs the installed ROCm prebuilt was built for
        (``mapped_targets`` in UNSLOTH_PREBUILT_INFO.json). None when unknown (no
        marker, non-ROCm bundle), so callers fail open and keep every device
        (#7624). Never raises."""
        try:
            from utils.llama_cpp_freshness import read_install_marker

            marker = read_install_marker(binary or LlamaCppBackend._find_llama_server_binary())
            if not marker:
                return None
            targets = marker.get("mapped_targets")
            if not isinstance(targets, list):
                return None
            archs = frozenset(
                str(t).split(":")[0].strip().lower() for t in targets if str(t).strip()
            )
            if not archs:
                return None
            # Exact-set membership against what the device reports, so it only means
            # anything while every token is concrete. One token no device can report
            # (generic code object, family label, malformed marker) matches nothing,
            # dropping EVERY GPU and silently forcing CPU, worse than not gating.
            # mapped_targets is remote data versioned independently of this code, so
            # an unrecognised list is "unknown" and fails open, all or nothing:
            # dropping just the odd token would under-report the build's coverage.
            unknown = sorted(a for a in archs if not LlamaCppBackend._CONCRETE_GFX_ARCH.match(a))
            if unknown:
                logger.warning(
                    f"install marker mapped_targets has non-concrete arch tokens "
                    f"{unknown}; skipping the GPU arch gate"
                )
                return None
            return archs
        except Exception as e:
            logger.debug(f"install marker arch read failed: {e}")
            return None

    @staticmethod
    def _installed_llama_cuda_sms(binary: Optional[str] = None) -> Optional[frozenset]:
        """SM targets the installed CUDA prebuilt was built for (``supported_sms``
        in UNSLOTH_PREBUILT_INFO.json). None when unknown (no marker, older
        install, non-CUDA bundle), so callers fail open. Never raises."""
        try:
            from utils.llama_cpp_freshness import read_install_marker

            marker = read_install_marker(binary or LlamaCppBackend._find_llama_server_binary())
            if not marker:
                return None
            sms = marker.get("supported_sms")
            if not isinstance(sms, list) or not sms:
                return None
            if not all(str(s).strip().isdigit() for s in sms):
                return None
            return frozenset(int(s) for s in sms)
        except Exception as e:
            logger.debug(f"install marker supported_sms read failed: {e}")
            return None

    @staticmethod
    def _cuda_compute_caps() -> dict:
        """Physical id -> SM (90 for sm_90) via nvidia-smi, honoring
        CUDA_VISIBLE_DEVICES; {} when unknown. Never raises."""
        try:
            result = subprocess.run(
                ["nvidia-smi", "--query-gpu=index,compute_cap", "--format=csv,noheader"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = child_env_without_native_path_secret(),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode != 0:
                return {}
            allowed = LlamaCppBackend._visible_devices_mask("CUDA_VISIBLE_DEVICES")
            if allowed is not None and os.environ.get("CUDA_DEVICE_ORDER") != "PCI_BUS_ID":
                # Numeric mask entries are CUDA ordinals; nvidia-smi reports PCI
                # physical indices. Without a shared order, fail open.
                return {}
            caps = {}
            for line in result.stdout.strip().splitlines():
                parts = [p.strip() for p in line.split(",")]
                if len(parts) < 2:
                    continue
                try:
                    idx = int(parts[0])
                    major, minor = parts[1].split(".")
                    sm = int(major) * 10 + int(minor)
                except ValueError:
                    continue
                if allowed is not None and idx not in allowed:
                    continue
                caps[idx] = sm
            return caps
        except Exception as e:
            logger.debug(f"compute_cap probe failed: {e}")
            return {}

    @classmethod
    def _cuda_sm_gate_error(cls, binary: Optional[str] = None) -> Optional[str]:
        """Error message when every visible GPU is OLDER than the oldest arch the
        installed CUDA bundle was built for, or None to proceed. Fails open on
        unknown coverage or caps.

        Only the too-old direction is broken. The bundles compile plain arch
        numbers, so each fatbin carries PTX beside its cubins, and the driver JITs
        that PTX forward onto a newer card; ggml_cuda_highest_compiled_arch picks
        the highest compiled arch <= the device and only aborts ("not compiled with
        any CUDA arch <= N") when the device is below every one of them. So an
        exact-SM test would refuse working installs: the legacy PTX-only bundle
        (sm_50-61) drives an sm_86/sm_89 host at full speed. Missing native cubins
        cost a one-time JIT, not a launch. The installer's exact-membership check
        is a different question -- which bundle is BEST to install -- not whether
        the installed one can run."""
        # Resolved once so the marker read and the remedy name the same binary.
        binary = binary or cls._find_llama_server_binary()
        supported = cls._installed_llama_cuda_sms(binary)
        if supported is None:
            return None
        caps = cls._cuda_compute_caps()
        oldest = min(supported)
        if not caps or any(sm >= oldest for sm in caps.values()):
            return None
        present = ", ".join(f"GPU {idx} is sm_{sm}" for idx, sm in sorted(caps.items()))
        # The updater cannot replace a pinned LLAMA_SERVER_PATH or a llama-server
        # found on PATH, so the remedy follows the binary's provenance.
        return (
            f"The installed llama.cpp build only has GPU code for sm_{oldest} and "
            f"newer, but {present} -- it was likely installed on a machine with a "
            f"newer GPU, so {cls._runtime_remedy(binary)}."
        )

    @classmethod
    def _arch_gate_survivors(cls, binary: Optional[str] = None) -> list[int]:
        """Physical ids the ROCm arch gate leaves, or [] when there is nothing to
        mask: unknown coverage, a non-ROCm host, a build covering every card, or an
        inherited mask whose ids we cannot name back to the child.

        For callers that must PIN the answer, not just rank by it: the child
        enumerates every ROCm agent, and that HSA enumeration is what dies on an
        uncovered arch, so a mixed host (unsupported iGPU + supported dGPU) passes
        the gate and still crashes unless the survivors are masked in. Lazy, and
        never raises."""
        try:
            # Coverage first: a cached marker read, where _host_torch_is_rocm imports
            # torch (~1.3s cold). Non-ROCm bundles record no mapped_targets, so they
            # answer [] without that import.
            if cls._installed_llama_gfx_archs(binary) is None:
                return []  # unknown coverage: fail open, same as the probe
            if not cls._host_torch_is_rocm():
                return []
            if cls._visibility_mask_is_unmappable():
                # A UUID/MIG mask leaves ordinals unmapped, so pinning would swap it
                # for numbers the runtime resolves against the whole host, possibly
                # re-exposing the dropped card. Fail open (pre-#7624).
                logger.info(
                    "Not pinning the arch gate's survivors: the inherited GPU "
                    "visibility mask is not index based, so they cannot be named "
                    "to the child."
                )
                return []
            gated = [
                idx for idx, _free, _total in cls._get_gpu_memory(binary, for_llama_server = True)
            ]
            everything = [idx for idx, _free, _total in cls._get_gpu_memory(binary)]
            return gated if gated and len(gated) < len(everything) else []
        except Exception as e:
            logger.debug(f"arch gate survivor probe failed: {e}")
            return []

    @staticmethod
    def _get_gpu_free_memory(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int]]:
        """Free memory per GPU as ``(gpu_index, free_mib)`` sorted by index; empty
        if no supported GPU is reachable. Thin wrapper over ``_get_gpu_memory``,
        which also documents ``for_llama_server`` (forwarded verbatim)."""
        return [
            (idx, free)
            for idx, free, _total in LlamaCppBackend._get_gpu_memory(
                binary, for_llama_server = for_llama_server
            )
        ]

    @staticmethod
    def _metal_zero_ctx_floor(
        effective_ctx: int,
        auto_fit: bool,
        caller_owns_budget: bool,
        native_ctx: Optional[int],
        max_available_ctx: Optional[int] = None,
        *,
        fitter_runs: bool = True,
    ) -> int:
        """Context to start at when Metal would otherwise be sent "-c 0", else 0.

        llama.cpp reads "-c 0" as fit_params_min_ctx = UINT32_MAX, pinning the
        model's full native length and disabling --fit's reduction. Two paths
        reach the command builder with a zero context after the Apple cap has
        been skipped or thrown away:

          * the cap is guarded on ``effective_ctx > 0``, so a GGUF whose
            metadata carries no context length is never capped;
          * the ``except Exception`` around GPU selection restores the original
            request, 0 when context is on Auto, discarding a context the cap had
            already computed.

        Either way the child over-commits unified memory, surfacing as
        llama-server's "Compute error." at decode (#5118, #6529). Floor to the
        same ``_FIT_MIN_CTX`` the cap falls back to without a KV estimate.

        ``fitter_runs`` is whether the child's own --fit step will actually run, and
        both the exemption and the floor VALUE depend on it. _FIT_MIN_CTX sits above
        llama.cpp's own ``fit_params_min_ctx`` on purpose: 8192 is defensible on a Mac
        only because it is a request the fitter can still reduce, down to 4096. Turn
        the fitter off and that backstop is gone, and this arm would hand a machine
        with room for 4096 but not 8192 a context nothing can bring down -- a startup
        failure or a "Compute error." at decode, the very thing the floor exists to
        prevent. So a launch with no fitter is floored at ``_LLAMA_FIT_MIN_CTX``, the
        number the fitter would have reduced to, rather than at the ceiling that
        assumed one. Conservative on purpose: --fit off is a flag the user typed, and
        overriding it to keep our own invented floor would be Unsloth taking back a
        setting the user asked for, on the path where they most likely asked for it
        because the fitter misbehaves on their host.

        Exemptions: no Metal budget (0 off Apple Silicon, so this is inert
        there); ``auto_fit``, which omits -c so --fit sizes it, and which is
        therefore honoured only while ``fitter_runs`` -- the conjunction is taken
        here rather than trusted to the caller, since without it the exemption hands
        the child no -c and no fitter, which is llama.cpp's native length; and
        ``caller_owns_budget``, a manual mode with a fixed layer count where the
        user owns memory management. That last is read off the REQUEST, because
        the paravirtual CPU pin rewrites every placement to manual/0 first and
        would make a plain Auto request look caller-owned.
        """
        if effective_ctx > 0 or (auto_fit and fitter_runs) or caller_owns_budget:
            return 0
        if not LlamaCppBackend._apple_metal_memory_budget_bytes():
            return 0
        floor = _FIT_MIN_CTX if fitter_runs else _LLAMA_FIT_MIN_CTX
        # Never above a ceiling the cap already worked out: on the exception path
        # max_available_ctx survives the reset, and its KV-based answer can sit
        # below the floor. Floating back up would re-create the over-commit.
        return min(floor, native_ctx or floor, max_available_ctx or floor)

    @staticmethod
    def _metal_drops_zero_ctx_override(
        ctx_override: Optional[int], caller_owns_budget: bool
    ) -> bool:
        """Whether a pass-through "-c 0" must be dropped before it reaches Metal.

        User extras are appended after Unsloth's own -c and llama.cpp is
        last-wins, so a zero override outlives both the Apple cap and the floor
        above and re-pins the native length. Only a zero; a positive -c stays
        honored. Inert off Apple Silicon like the floor, but unlike the floor it
        also fires in Auto-layers, where the command omits -c precisely so --fit
        sizes the context. ``caller_owns_budget`` is exempt, read off the request
        for the reason the floor documents.
        """
        if ctx_override != 0 or caller_owns_budget:
            return False
        return bool(LlamaCppBackend._apple_metal_memory_budget_bytes())

    @staticmethod
    def _apple_metal_memory_budget_bytes() -> int:
        """Unified-memory budget for GGUF context fitting on Apple Silicon.

        No GPU is enumerated on Metal, so the context would default to native and
        over-commit unified memory ("Compute error." at decode, #5118/#6529). Use a
        fraction of MLX's Metal working-set, else total RAM; 0 off Apple Silicon or
        when unresolvable, so callers skip the cap.

        Both of those inputs describe the MACHINE, not the moment. MLX's
        max_recommended_working_set_size is a static device property, and
        virtual_memory().total obviously is, so on a 16 GB Mac the budget came
        out around 9 GB whether the machine was idle or already holding several
        gigabytes. Unsloth's own idle footprint alone is over a gigabyte once the
        warm thread has imported torch and, on Apple Silicon, MLX. The fit then
        sized a context against headroom that was not there, and llama-server
        died in KV or compute allocation.

        So take whichever is smaller: the device ceiling, or what is actually
        available right now. The ceiling still applies on a machine with plenty
        free, which is the case the working-set number was chosen for.

        _APPLE_UNIFIED_MEMORY_FRACTION then earns a second job it did not have
        over a static ceiling: available is a snapshot, and llama-server spends
        seconds loading weights, so another app can take memory inside that
        window. Budgeting all of it would re-create the failure this avoids.
        """
        from utils.hardware import is_apple_silicon

        if not is_apple_silicon():
            return 0
        rec_bytes = 0
        try:
            import mlx.core as mx
            if mx.metal.is_available():
                rec_bytes = int(mx.device_info().get("max_recommended_working_set_size") or 0)
        except Exception:
            rec_bytes = 0
        vm = None
        try:
            import psutil
            vm = psutil.virtual_memory()
        except Exception:
            vm = None
        if rec_bytes <= 0:
            if vm is None:
                return 0
            try:
                rec_bytes = int(vm.total)
            except Exception:
                return 0
        # available, not free: psutil's macOS free subtracts speculative pages and
        # leaves out the inactive queue, so it reads far below what a new allocation
        # can get. available is inactive + free (psutil arch/osx/mem.c), which adds
        # that reclaimable cache back. An estimate either way, since it counts dirty
        # inactive pages that cost a compression to reclaim and ignores the
        # compressor entirely. Only ever lowers the budget.
        try:
            available = int(getattr(vm, "available", 0) or 0) if vm is not None else 0
        except Exception:
            available = 0
        if available > 0:
            rec_bytes = min(rec_bytes, available)
        return int(rec_bytes * _APPLE_UNIFIED_MEMORY_FRACTION)

    @staticmethod
    def _rocm_arch_gate_keep(
        binary: Optional[str], torch_mod, for_llama_server: bool
    ) -> Callable[[int], bool]:
        """Predicate over PHYSICAL ids: False for a device the installed ROCm
        prebuilt has no kernels for.

        llama-server placement only, so the free-memory rank cannot pick a GPU that
        binary cannot run (#7624: an iGPU reporting shared RAM outranks the dGPU and
        the child dies with "device kernel image is invalid"). Keeps every device off
        that path, off ROCm, on unknown coverage, and for a device with no reported
        arch. Shared by both branches of ``_get_gpu_memory`` so the amd-smi and torch
        paths cannot gate differently.
        """
        if not for_llama_server or not LlamaCppBackend._torch_is_rocm(torch_mod):
            return lambda _idx: True
        supported_archs = LlamaCppBackend._installed_llama_gfx_archs(binary)
        if supported_archs is None:
            return lambda _idx: True
        arch_by_id = LlamaCppBackend._rocm_arch_by_physical_id()

        def _keep(idx: int) -> bool:
            _base = arch_by_id.get(idx, "")
            if _base and _base not in supported_archs:
                logger.warning(
                    f"Skipping GPU {idx} ({_base}): installed llama.cpp "
                    f"prebuilt only covers {sorted(supported_archs)}"
                )
                return False
            return True

        return _keep

    @staticmethod
    def _rocm_hip_is_reachable() -> bool:
        """Whether HIP can actually open a device on this ROCm host.

        amd-smi reads the driver over sysfs and libdrm, HIP needs ``/dev/kfd`` and a
        matching HSA runtime, so the two disagree on a container given only
        ``/dev/dri`` and on a torch built against another ROCm: amd-smi lists the
        card and ``hipGetDeviceCount`` returns 0. The llama-server child is a HIP
        process too, so answering there places a model on a device nothing can open.

        ``is_available()`` is that ``hipGetDeviceCount``, not ``_lazy_init``, so it
        creates no primary context; ``_rocm_unified_memory_gpu_ids`` already calls it
        further down the same probe. False when torch is missing or unreadable.
        """
        try:
            import torch
            return bool(hasattr(torch, "cuda") and torch.cuda.is_available())
        except Exception:
            return False

    @staticmethod
    def _rocm_hip_device_count() -> int:
        """How many devices HIP can open here, or 0 when torch cannot say.

        ``hipGetDeviceCount``, the same call ``_rocm_hip_is_reachable`` asks for a
        yes/no, so it costs no primary context either. This is the size of the
        inventory the llama-server child will see; amd-smi reads sysfs and answers
        for the whole host regardless, so the two disagree wherever something
        outside the visibility variables filters the device set (a device-cgroup
        container given one ``/dev/dri/renderD*`` node, ``GPU_DEVICE_ORDINAL``, a
        card amd-smi could not size).
        """
        try:
            import torch
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return 0
            return int(torch.cuda.device_count())
        except Exception:
            return 0

    @staticmethod
    def _gpu_device_ordinal_active() -> bool:
        """Whether ``GPU_DEVICE_ORDINAL`` is filtering this process's devices.

        ROCm's fourth visibility variable, and the one nothing here reads:
        ``_active_gpu_visibility_mask`` knows the HIP, ROCR and CUDA names only, so
        ``_resolve_visible_physical_ids`` answers None ("no mask") under it. AMD
        documents it at the ROCclr layer as "devices indices exposed to OpenCL and
        HIP applications", while clr itself reads it only on the non-HIP branch
        (``rocclr/device/rocm/rocdevice.cpp`` picks HIP_VISIBLE_DEVICES /
        CUDA_VISIBLE_DEVICES when ``amd::IS_HIP``), so the two disagree on whether
        HIP honours it. Treat it as a mask either way: being wrong here costs the
        host nothing but this branch's context saving, and being wrong the other way
        offers a hidden card for placement. ``utils/hardware/hardware.py::
        _rocm_visibility_mask_active`` gates the system-wide VRAM overlay on the same
        four names. Whitespace is not a filter, matching that helper."""
        return bool(os.environ.get("GPU_DEVICE_ORDINAL", "").strip())

    @staticmethod
    def _rocm_visibility_masks_are_stacked() -> bool:
        """Whether a ROCr mask AND a HIP-layer mask are both filtering this process.

        The two sit at different layers and therefore COMPOSE: ROCR_VISIBLE_DEVICES
        filters and renumbers the agent list inside the ROCr runtime
        (``ROCR-Runtime/core/inc/amd_filter_device.h::RvdFilter``), and clr's
        ``Device::init`` then indexes ``HIP_VISIBLE_DEVICES`` (or its
        ``CUDA_VISIBLE_DEVICES`` twin) into ``gpu_agents_``, the vector
        ``hsa_iterate_agents`` just returned -- so the HIP ordinals count positions in
        what ROCr left, not physical devices. ``ROCR_VISIBLE_DEVICES=1,2`` with
        ``HIP_VISIBLE_DEVICES=0`` opens physical GPU 1.

        ``_active_gpu_visibility_mask`` returns the single highest-precedence value,
        which is the right answer for one layer and cannot express two: it reads
        ``[0]`` for that example, and on a host whose cards have the same total the
        inventory and total-memory cross-checks agree with it. Callers that would map
        those ids onto amd-smi's host-wide device list must decline instead. Composing
        the masks here is not an option: the physical->ROCr mapping is exactly what
        ROCr renumbered away, and guessing it wrong offers a hidden card.

        HIP and CUDA together are ONE layer, not two -- clr reads whichever is set
        first and never both -- so they do not stack. Windows has no ROCr layer at
        all, so a stray ROCR variable filters nothing there, matching
        ``_active_gpu_visibility_mask`` and ``_emit_child_gpu_visibility``. Set is
        set: an empty ROCr mask hides every agent rather than nothing."""
        if sys.platform == "win32":
            return False
        if os.environ.get("ROCR_VISIBLE_DEVICES") is None:
            return False
        return (
            os.environ.get("HIP_VISIBLE_DEVICES") is not None
            or os.environ.get("CUDA_VISIBLE_DEVICES") is not None
        )

    @staticmethod
    def _rocm_total_memory_mib_by_physical_id() -> dict[int, int]:
        """Total memory HIP reports per PHYSICAL device id, honoring the active ROCm
        mask, for cross-checking amd-smi's totals.

        Read through ``get_device_properties`` like ``_rocm_arch_by_physical_id``, so
        it costs no primary context (``mem_get_info`` is the call that does).
        Devices torch cannot describe are omitted and callers fail open on them;
        empty off ROCm and on any error."""
        totals: dict[int, int] = {}
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return totals
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return totals
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    total_bytes = int(
                        getattr(torch.cuda.get_device_properties(ordinal), "total_memory", 0) or 0
                    )
                except Exception:
                    continue
                if total_bytes <= 0:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                totals[pid] = total_bytes // (1024 * 1024)
        except Exception:
            return totals
        return totals

    @staticmethod
    def _amd_smi_hip_id_map(
        enumerated: list[int], mask: Optional[list[int]]
    ) -> Optional[dict[int, int]]:
        """{amd-smi gpu id: HIP id} for every enumerated device, else None.

        amd-smi numbers its devices in discovery order and HIP numbers them by KFD
        node id, so the two agree on most hosts and not on all of them (MI350X in
        SPX/NPS1 among others). Every id this probe returns is fed back as a HIP
        ordinal -- matched against the visibility mask, then written into the child's
        HIP_VISIBLE_DEVICES -- so an untranslated amd-smi id pins the wrong card.

        None means "not provable", and the branch then defers to torch, which
        enumerates in HIP's space by construction.
        """
        if len(enumerated) == 1 and mask in (None, [0]):
            # One card on the host, so HIP can only be looking at that card and its
            # id can only be 0. Keeps the single-GPU ROCm desktop, which is most of
            # them, on amd-smi even where the CLI predates the mapping below.
            return {enumerated[0]: 0}
        from utils.hardware.amd import get_hip_id_by_gpu_index

        mapping = get_hip_id_by_gpu_index()
        if mapping is None or not all(_g in mapping for _g in enumerated):
            logger.debug(
                "amd-smi VRAM probe deferring to torch: no amd-smi to HIP id mapping "
                "for this host (amd-smi list -e needs ROCm 6.4.0+)"
            )
            return None
        return mapping

    @staticmethod
    def _get_gpu_memory_amd_smi(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int, int]]:
        """ROCm free/total VRAM per PHYSICAL (HIP) gpu id via amd-smi, else ``[]``.

        Same index space and arch gate as the torch branch of ``_get_gpu_memory``,
        read from a child process instead. Reading VRAM through
        ``torch.cuda.mem_get_info`` creates a HIP primary context that the backend
        never gives back (~700 MiB measured), and the GGUF models this sizes run in a
        llama-server CHILD, so that VRAM is lost for the life of the process to
        answer a question a subprocess can answer.

        ``[]`` off ROCm and whenever amd-smi cannot answer, so the caller falls
        through to torch exactly as before. A gate that drops every card answers
        ``[]`` too, and torch then gates identically to the same empty list, so the
        one context this still costs is on the arm already headed for the CPU.
        A visible unified-memory APU answers ``[]`` as well: amd-smi sees only its
        dedicated VRAM carve-out, not the GTT pool the torch branch measures. So does
        anything it can only half answer: a subset is a non-empty list the caller
        takes as the whole host, which would drop a device from the count tensor
        parallelism is decided on.

        The inventory has to be HIP's, since the child is a HIP process: the answer
        is declined when the device set is filtered by something the mask cannot see
        (``GPU_DEVICE_ORDINAL``, a device-cgroup container), when amd-smi and HIP
        count different numbers of devices, and when they report totals far enough
        apart to be describing different memory scopes.
        """
        try:
            import torch
            if not LlamaCppBackend._torch_is_rocm(torch):
                return []
        except Exception:
            return []
        if not LlamaCppBackend._rocm_hip_is_reachable():
            # amd-smi would still list the hardware, but HIP cannot open it and
            # neither can the llama-server child. Torch answers [] here, as it did
            # before this branch existed, and the load goes to CPU.
            logger.debug(
                "amd-smi VRAM probe deferring to torch: this ROCm torch cannot open "
                "a device, so amd-smi's inventory is not usable by llama-server"
            )
            return []
        try:
            from utils.hardware.amd import get_gpu_vram_report

            if LlamaCppBackend._visibility_mask_is_unmappable():
                # A mask IS set but names devices by UUID, so it cannot be applied
                # here. amd-smi ignores the mask itself (it reads KFD directly), so
                # answering would offer cards the parent deliberately hid. Torch sees
                # only the masked set, so let it answer.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: the GPU visibility mask "
                    "is not index based, so amd-smi's device list cannot be filtered"
                )
                return []
            if LlamaCppBackend._gpu_device_ordinal_active():
                # _resolve_visible_physical_ids does not read this one, so "no mask"
                # below would be a lie wherever it does filter, and every hidden card
                # would be offered for ranking.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: GPU_DEVICE_ORDINAL is "
                    "set, so amd-smi's device list cannot be filtered"
                )
                return []
            if LlamaCppBackend._rocm_visibility_masks_are_stacked():
                # A ROCr mask under a HIP mask re-indexes it, and the resolved value
                # is the HIP one alone -- ordinals into the set ROCr left, not the
                # physical ids amd-smi answers for. Every later check agrees with the
                # wrong ids on a host whose cards match, so this is the only place it
                # can be caught.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: ROCR_VISIBLE_DEVICES is "
                    "stacked under a HIP-layer mask, so the visible ids are positions "
                    "in the ROCr-filtered set rather than physical devices"
                )
                return []
            mask = LlamaCppBackend._resolve_visible_physical_ids()
            if mask is not None and not mask:
                return []  # every device hidden
            vram, enumerated = get_gpu_vram_report()
            if not enumerated:
                return []
            # amd-smi ids are not HIP ids; translate before anything compares them
            # against the mask or hands them to the child.
            hip_by_gpu = LlamaCppBackend._amd_smi_hip_id_map(enumerated, mask)
            if hip_by_gpu is None:
                return []
            vram = {hip_by_gpu[_g]: _v for _g, _v in vram.items()}
            # amd-smi enumerates every card regardless of the mask, so drop the ones
            # this process cannot see. No mask means all of them.
            visible = set(mask) if mask is not None else set(hip_by_gpu.values())
            if not visible.issubset(vram):
                # A device that is visible and unmeasured: all or nothing.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: no usable VRAM reading "
                    f"for visible GPU(s) {sorted(visible - set(vram))}"
                )
                return []
            hip_count = LlamaCppBackend._rocm_hip_device_count()
            if len(visible) != hip_count:
                # This inventory has to BE the child's. amd-smi answers for the whole
                # host off sysfs, so anything filtering devices outside the
                # visibility variables leaves it larger than HIP's: a device-cgroup
                # container given one /dev/dri/renderD* node and no env var (see
                # test_overlay_skips_device_cgroup_filtered_container) is the usual
                # one. Smaller means amd-smi omitted a card HIP can open, which the
                # single-GPU shortcut in _amd_smi_hip_id_map would otherwise read as
                # a one-card host. Either way the numbers are not comparable.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: amd-smi reports "
                    f"{len(visible)} visible GPU(s) and HIP opens {hip_count}"
                )
                return []
            hip_totals = LlamaCppBackend._rocm_total_memory_mib_by_physical_id()
            disagreeing = sorted(
                _idx
                for _idx in visible
                if _idx in hip_totals
                and abs(vram[_idx][1] - hip_totals[_idx])
                > _AMD_SMI_TOTAL_TOLERANCE * hip_totals[_idx]
            )
            if disagreeing:
                # Two memory scopes, not two readings of one pool. The case that
                # matters is an APU _rocm_classify_unified_memory does not name (a
                # gfx1103 Phoenix wheel with no is_integrated flag): amd-smi sees the
                # BIOS carve-out and HIP the GTT pool, so accepting amd-smi's figure
                # would cut context or push the model to CPU. A partitioned MI300
                # reads the other way round. hardware.py::
                # _rocm_system_wide_vram_by_index gates its own overlay on the same
                # comparison. Devices torch cannot describe are absent from
                # hip_totals and fail open, so an unreadable properties call cannot
                # disable this branch wholesale.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: amd-smi and HIP report "
                    f"different total memory for GPU(s) {disagreeing}"
                )
                return []
            unified_ids = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            if unified_ids:
                # amd-smi reports only the dedicated VRAM carve-out on a
                # unified-memory APU, while HIP reports the far larger GTT pool the
                # models actually run in: on a 128GiB Strix Halo with an 8GiB BIOS
                # carve-out amd-smi says 8GiB and torch says ~100GiB. Handing the
                # GGUF fitter the slice would cut context or push the model to CPU.
                # utils/hardware/hardware.py::_apply_unified_memory_correction
                # adopts torch's total over amd-smi's for the System tab for the
                # same reason. Defer the WHOLE host rather than mix two memory
                # scopes: dropping only the APU would remove it from placement, and
                # the two branches of _get_gpu_memory must not disagree.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: unified-memory APU(s) "
                    f"{sorted(unified_ids)} report only their dedicated VRAM slice"
                )
                return []
            arch_keeps = LlamaCppBackend._rocm_arch_gate_keep(binary, torch, for_llama_server)
            gpus: list[tuple[int, int, int]] = []
            for idx in sorted(visible):
                if not arch_keeps(idx):
                    continue
                free_mib, total_mib = vram[idx]
                gpus.append((idx, free_mib, total_mib))
            return gpus
        except Exception as e:
            logger.debug(f"amd-smi GPU probe failed: {e}")
            return []

    @staticmethod
    def _get_gpu_memory(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int, int]]:
        """Query free AND total memory per GPU.

        Order: ``nvidia-smi`` (NVIDIA, respects ``CUDA_VISIBLE_DEVICES``), then
        ``amd-smi`` (ROCm, the same answer without a HIP context), then
        ``torch.cuda.mem_get_info``, a universal fallback that works on ROCm too
        (HIP reuses the ``torch.cuda.*`` namespace). The fallback covers #5106
        (nvidia-smi returned [] on AMD) and hosts with no smi tool on PATH; it is
        last because it costs this process a permanent CUDA/HIP context, and kept
        because callers read ``[]`` as "no GPU" and would silently drop to CPU.

        On a Vulkan build the ggml Vulkan probe is authoritative, so the indices are
        ggml's compact Vulkan ordinals (what ``--device Vulkan<i>`` selects). It
        reports ``total`` for discrete cards and 0 for an iGPU (shared RAM) so the
        fit falls back to free*frac. The torch branch treats an AMD unified-memory
        APU the same way by arch name, ROCm having no iGPU flag of its own.

        ``for_llama_server`` opts into the ROCm arch gate: devices whose gfx arch is
        not in the prebuilt's built-arch list are dropped, so auto placement cannot
        pick a GPU that binary has no kernels for (#7624). Off by default because
        this probe also backs ``core/rag/embeddings.py::_resolve_auto``, where such a
        device is usually still fine under PyTorch and filtering it would push
        sentence-transformers onto the CPU for no reason. Pass it only where a
        llama-server process is about to be placed.

        Returns (gpu_index, free_mib, total_mib) sorted by index; empty if no
        supported GPU is reachable."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if LlamaCppBackend._is_vulkan_backend(binary):
            return LlamaCppBackend._get_gpu_free_memory_vulkan(binary)
        # ── NVIDIA via nvidia-smi ────────────────────────────────────
        try:
            result = subprocess.run(
                [
                    "nvidia-smi",
                    "--query-gpu=index,memory.free,memory.total",
                    "--format=csv,noheader,nounits",
                ],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = child_env_without_native_path_secret(),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode == 0:
                allowed = LlamaCppBackend._visible_devices_mask("CUDA_VISIBLE_DEVICES")
                gpus: list[tuple[int, int, int]] = []
                for line in result.stdout.strip().splitlines():
                    parts = [p.strip() for p in line.split(",")]
                    if len(parts) < 2:
                        continue
                    # Index and free required; skip a bad line rather than abandon
                    # the probe to the torch fallback.
                    try:
                        idx = int(parts[0])
                        free_mib = int(parts[1])
                    except ValueError:
                        continue
                    # Total parsed separately: a two-column line or a non-integer
                    # total ("N/A" on MIG/vGPU) keeps the GPU at total 0 (fit uses
                    # the free*frac fallback) instead of dropping it.
                    total_mib = 0
                    if len(parts) >= 3 and parts[2]:
                        try:
                            total_mib = int(parts[2])
                        except ValueError:
                            total_mib = 0
                    if allowed is not None and idx not in allowed:
                        continue
                    gpus.append((idx, free_mib, total_mib))
                # Match the docstring's sort-by-id guarantee (driver order isn't).
                gpus.sort(key = lambda g: g[0])
                if gpus:
                    return gpus
        except Exception as e:
            logger.debug(f"nvidia-smi probe failed: {e}")

        # ── AMD ROCm via amd-smi ─────────────────────────────────────
        rocm_gpus = LlamaCppBackend._get_gpu_memory_amd_smi(
            binary, for_llama_server = for_llama_server
        )
        if rocm_gpus:
            return rocm_gpus

        # ── Torch fallback (covers AMD ROCm and missing nvidia-smi) ──
        try:
            import torch

            if not hasattr(torch, "cuda") or not torch.cuda.is_available():
                return []
            if not hasattr(torch.cuda, "mem_get_info"):
                return []
            # torch.cuda enumerates GPUs RELATIVE to the visibility mask. We
            # feed these IDs back into the subprocess as CVD, so visible ordinals
            # must be translated to physical indices first; otherwise CVD=2,3
            # gets rewritten to 0,1 and targets the wrong GPUs.
            # Match utils/hardware/hardware.py::_get_parent_visible_gpu_spec:
            # treat an empty mask (HIP_VISIBLE_DEVICES="") as "no GPUs" rather
            # than falling through. ``or`` would coerce "" to the wrong source.
            # Empty mask (CVD="") yields an empty list -> no GPUs, consistent
            # with the nvidia-smi path.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            # Shared-pool APU: same as the Vulkan iGPU path. Hold back the host
            # margin, and report total 0 since that "total" is system RAM.
            unified_ids = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            # Same #7624 arch gate the amd-smi branch applies, from the one helper.
            arch_keeps = LlamaCppBackend._rocm_arch_gate_keep(binary, torch, for_llama_server)
            gpus = []
            # Windows ROCm's free reading is an over-report on discrete cards too,
            # not only on the shared pool handled below (#8403). It is capped
            # against this process's own allocator, so VRAM a resident torch model
            # holds in the backend process stops being offered to llama.cpp slots.
            from utils.hardware import trusted_mem_get_info

            for ordinal in range(torch.cuda.device_count()):
                free_bytes, total_bytes = trusted_mem_get_info(ordinal)
                idx = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                if not arch_keeps(idx):
                    continue
                shared = idx in unified_ids
                raw_mib = free_bytes // (1024 * 1024)
                if shared:
                    # ROCm's free is unreliable on a shared pool (Windows HIP
                    # reports free==total, #7072), and system RAM is the real
                    # ceiling there, so cap before taking the reserve.
                    avail = LlamaCppBackend._available_system_memory_mib()
                    if avail is not None:
                        raw_mib = min(raw_mib, avail)
                free_mib = _apply_igpu_host_reserve_mib(raw_mib, shared)
                if free_mib < raw_mib:
                    logger.info(
                        f"ROCm device {idx} is a unified-memory APU sharing system "
                        f"RAM; reserving {raw_mib - free_mib}MiB host headroom "
                        f"({raw_mib}->{free_mib}MiB usable)"
                    )
                gpus.append((idx, free_mib, 0 if shared else total_bytes // (1024 * 1024)))
            # Match the nvidia-smi path's docstring guarantee of sorted-by-id.
            return sorted(gpus, key = lambda g: g[0])
        except Exception as e:
            logger.debug(f"torch GPU probe failed: {e}")
            return []

    @staticmethod
    def _vulkan_auto_gpu_memory(gpus: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
        """Prefer discrete devices for automatic Vulkan placement."""
        discrete = [gpu for gpu in gpus if gpu[2] > 0]
        return discrete or gpus

    @staticmethod
    def _run_vulkan_probe(binary: Optional[str] = None) -> list[dict]:
        """Run ``_vulkan_probe.py`` and parse its per-device lines.

        Returns raw (uncapped) rows sorted by index:
        ``{"index", "free_mib", "total_mib", "is_igpu", "name"}``. The index is
        ggml's compact Vulkan ordinal -- the one the registry names
        ``Vulkan<index>`` and load_model pins with ``--device``, NOT the raw
        ``GGML_VK_VISIBLE_DEVICES`` space. A user-set ``GGML_VK_VISIBLE_DEVICES``
        is honored by ggml (passed through), so the list already reflects it.
        ``name`` is ggml's device description; "" from an older 4-column probe.
        [] when no Vulkan build or device is reachable.
        """
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return []
        binary_dir = _llama_lib_dir(binary)
        if not _lib_dir_has_ggml_backend(binary_dir, "vulkan"):
            return []

        env = child_env_without_native_path_secret()
        # Let ggml apply GGML_VK_VISIBLE_DEVICES; Python sees compact ordinals.
        if sys.platform != "win32":
            # Let the loader resolve sibling ggml libs next to the binary.
            # _loader_path_var keeps macOS off LD_LIBRARY_PATH, which dyld
            # ignores (#8566).
            _loader_var = _loader_path_var()
            existing_ld = env.get(_loader_var, "")
            env[_loader_var] = (
                f"{binary_dir}{os.pathsep}{existing_ld}" if existing_ld else str(binary_dir)
            )
        probe_script = Path(__file__).with_name("_vulkan_probe.py")
        try:
            # UTF-8 to match the probe's stdout reconfigure: device names can be
            # non-ASCII, and the platform-default decode (cp1252) could throw.
            result = subprocess.run(
                [sys.executable, str(probe_script), str(binary_dir)],
                capture_output = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 15,
                env = utf8_child_env(env),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode != 0:
                logger.debug(
                    f"vulkan GPU probe exited {result.returncode}: {result.stderr.strip()}"
                )
                return []
        except Exception as e:
            logger.debug(f"vulkan GPU probe failed: {e}")
            return []

        rows: list[dict] = []
        for line in result.stdout.strip().splitlines():
            parts = line.split("\t")
            # 4 columns from an older probe (no name); 5 with the name column.
            if len(parts) not in (4, 5):
                continue
            try:
                rows.append(
                    {
                        "index": int(parts[0]),
                        "free_mib": int(parts[1]) // (1024 * 1024),
                        "is_igpu": parts[2] == "1",
                        "total_mib": int(parts[3]) // (1024 * 1024),
                        "name": parts[4].strip() if len(parts) == 5 else "",
                    }
                )
            except ValueError:
                continue
        rows.sort(key = lambda r: r["index"])
        return rows

    @staticmethod
    def vulkan_device_inventory(binary: Optional[str] = None) -> list[dict]:
        """UI-facing Vulkan device list: the devices llama-server will actually
        use, with real totals (an iGPU keeps its shared-RAM total here -- the
        caller labels it, unlike the fit which zeroes it). Same rows as
        ``_run_vulkan_probe``; names fall back to ``Vulkan<i>``.
        """
        rows = LlamaCppBackend._run_vulkan_probe(binary)
        for row in rows:
            if not row["name"]:
                row["name"] = f"Vulkan{row['index']}"
        return rows

    @staticmethod
    def _get_gpu_free_memory_vulkan(binary: Optional[str] = None) -> list[tuple[int, int, int]]:
        """Query free (and total) VRAM per device via the bundled ggml Vulkan backend.

        Fit-oriented view of ``_run_vulkan_probe``: returns (device_index,
        free_mib, total_mib) sorted by index. iGPUs leave a host-RAM margin (see
        ``_apply_igpu_host_reserve_mib``) and report total 0; discrete cards pass
        their real total through. [] when no Vulkan build or device is reachable.
        """
        gpus: list[tuple[int, int, int]] = []
        for row in LlamaCppBackend._run_vulkan_probe(binary):
            idx, free_mib, is_igpu = row["index"], row["free_mib"], row["is_igpu"]
            # iGPU "total" is shared RAM, not a VRAM budget -> keep 0 so the
            # fit stays on free*frac (the host reserve below is its
            # headroom); a discrete card passes its real total through.
            total_mib = 0 if is_igpu else row["total_mib"]
            capped = _apply_igpu_host_reserve_mib(free_mib, is_igpu)
            if capped < free_mib:
                logger.info(
                    f"Vulkan device VK{idx} is an integrated GPU sharing system "
                    f"RAM; reserving {free_mib - capped}MiB host headroom "
                    f"({free_mib}->{capped}MiB usable)"
                )
            gpus.append((idx, capped, total_mib))
        if gpus:
            logger.info(
                "Vulkan GPU memory detected: "
                + ", ".join(f"VK{idx}={free}MiB" for idx, free, _total in gpus)
            )
        return gpus

    @staticmethod
    def _igpu_backed_free_mib(free_mib: int, headroom_mib: int = 0) -> int:
        """Bound a raw iGPU free reading by host RAM plus any firmware carve-out.

        Vulkan combines OS-visible RAM with carve-outs. Memory above ``MemTotal``
        is a conservative floor for the free carve-out; add ``MemAvailable`` for
        the host-backed share after its required headroom. WSL cannot use this
        inference because the VM and adapter report different memory scopes.
        """
        available = LlamaCppBackend._available_system_memory_mib()
        total_ram = LlamaCppBackend._total_system_memory_mib()
        if available is None or total_ram is None:
            return free_mib
        unseen = 0 if _is_wsl() else max(0, free_mib - total_ram)
        host_backed = max(0, available - max(0, headroom_mib))
        return min(free_mib, unseen + host_backed)

    @staticmethod
    def _igpu_backed_usable_mib(usable_mib: int) -> int:
        """Bound a post-reserve iGPU budget for shared-heap admission.

        Placement keeps the Vulkan reading so an existing full-offload plan is
        not demoted to the fitter. The host guard alone reconstructs the raw
        reading, bounds its host-backed share with the whole-system headroom,
        and caps that against the already-reserved placement budget. A zero
        budget stays zero because the raw value below the reserve is no longer
        recoverable and could not admit weights either way.
        """
        if usable_mib <= 0:
            return 0
        raw_free_mib = usable_mib + _IGPU_HOST_RESERVE_MIB
        backed_mib = LlamaCppBackend._igpu_backed_free_mib(
            raw_free_mib, headroom_mib = _HOST_RAM_HEADROOM_MIB
        )
        return min(usable_mib, backed_mib)

    @staticmethod
    def _cgroup_available_memory_mib() -> Optional[int]:
        """Memory this process can still charge to an enforcing cgroup.

        ``psutil`` and ``/proc/meminfo`` expose host-wide availability in many
        containers. Walk the process's cgroup plus its ancestors and pair each
        limit with that same directory's usage; an ancestor slice can be the
        binding limit and includes sibling usage that a leaf does not see.
        Supports cgroup v2 and the legacy v1 memory controller. ``None`` means
        no finite readable limit, so callers retain their host reading.
        """

        def _first_line(path: str) -> Optional[str]:
            try:
                with open(path, "r", encoding = "utf-8") as f:
                    return f.readline().strip()
            except OSError:
                return None

        def _integer(raw: Optional[str], *, limit: bool = False) -> Optional[int]:
            if not raw or raw == "max":
                return None
            try:
                value = int(raw)
            except ValueError:
                return None
            # cgroup v1 spells unlimited as a near-2^63 sentinel.
            if value < 0 or (limit and value >= 1 << 60):
                return None
            return value

        def _stat_integer(path: str, *keys: str) -> int:
            """Read the first requested byte counter present in memory.stat."""
            try:
                with open(path, "r", encoding = "utf-8") as f:
                    values = {}
                    for line in f:
                        parts = line.split()
                        if len(parts) == 2 and parts[0] in keys:
                            value = _integer(parts[1])
                            if value is not None:
                                values[parts[0]] = value
            except OSError:
                return 0
            return next((values[key] for key in keys if key in values), 0)

        def _directories(root: str, relative: Optional[str]) -> list[str]:
            root = os.path.abspath(root)
            current = os.path.normpath(os.path.join(root, (relative or "/").lstrip("/")))
            try:
                if os.path.commonpath((root, current)) != root:
                    return [root]
            except ValueError:
                return [root]
            out = []
            while True:
                out.append(current)
                if current == root:
                    return out
                current = os.path.dirname(current)

        try:
            with open(_PROC_SELF_CGROUP, "r", encoding = "utf-8") as f:
                lines = [line.strip() for line in f if line.strip()]
        except OSError:
            lines = []

        remaining: list[int] = []
        v2_relative = next((line[3:] for line in lines if line.startswith("0::")), None)
        for directory in _directories(_CGROUP_ROOT, v2_relative):
            limit = _integer(_first_line(os.path.join(directory, "memory.max")), limit = True)
            if limit is None:
                continue
            used = _integer(_first_line(os.path.join(directory, "memory.current")))
            if used is not None:
                # memory.current includes file-backed cache. Inactive file pages
                # are reclaimable under pressure, so price the launch against the
                # cgroup working set rather than charging cached GGUF pages twice.
                used = max(
                    0, used - _stat_integer(os.path.join(directory, "memory.stat"), "inactive_file")
                )
            remaining.append(limit if used is None else limit - used)

        v1_root = os.path.join(_CGROUP_ROOT, "memory")
        v1_relative = None
        for line in lines:
            parts = line.split(":", 2)
            if len(parts) == 3 and "memory" in parts[1].split(","):
                v1_relative = parts[2]
                break
        for directory in _directories(v1_root, v1_relative):
            limit = _integer(
                _first_line(os.path.join(directory, "memory.limit_in_bytes")), limit = True
            )
            if limit is None:
                continue
            used = _integer(_first_line(os.path.join(directory, "memory.usage_in_bytes")))
            if used is not None:
                # v1 usage is hierarchical when use_hierarchy is enabled, so its
                # matching counter is total_inactive_file. Fall back to the local
                # counter for non-hierarchical controllers.
                used = max(
                    0,
                    used
                    - _stat_integer(
                        os.path.join(directory, "memory.stat"),
                        "total_inactive_file",
                        "inactive_file",
                    ),
                )
            remaining.append(limit if used is None else limit - used)

        return max(min(remaining), 0) // (1024 * 1024) if remaining else None

    @staticmethod
    def _available_system_memory_mib() -> Optional[int]:
        """Available system RAM in MiB (psutil, then /proc/meminfo), or None if
        neither is readable, capped by this process's cgroup remainder. On a
        unified-memory APU this, not the ROCm-reported VRAM, is the real ceiling:
        the weights load into shared system RAM."""
        available = None
        try:
            import psutil
            available = int(psutil.virtual_memory().available // (1024 * 1024))
        except Exception:
            pass
        if available is None:
            try:
                with open("/proc/meminfo", encoding = "utf-8") as f:
                    for line in f:
                        if line.startswith("MemAvailable:"):
                            available = int(line.split()[1]) // 1024  # kB -> MiB
                            break
            except Exception:
                pass
        cgroup_available = LlamaCppBackend._cgroup_available_memory_mib()
        if available is None:
            return cgroup_available
        return min(available, cgroup_available) if cgroup_available is not None else available

    @staticmethod
    def _total_system_memory_mib() -> Optional[int]:
        """Total system RAM in MiB (psutil, then /proc/meminfo), or None if neither is
        readable. The ceiling on what ``MemAvailable`` can ever become, so a preflight that
        runs before the resident model and pipeline are torn down can price against it
        without charging for host memory that is about to come back."""
        try:
            import psutil
            return int(psutil.virtual_memory().total // (1024 * 1024))
        except Exception:
            pass
        try:
            with open("/proc/meminfo", encoding = "utf-8") as f:
                for line in f:
                    if line.startswith("MemTotal:"):
                        return int(line.split()[1]) // 1024  # kB -> MiB
        except Exception:
            pass
        return None

    _ARGV_MODEL = frozenset({"-m", "--model"})
    _ARGV_RPC = frozenset({"--rpc"})

    @staticmethod
    def _binary_ships_no_gpu_backend(
        binary: Optional[str] = None, env: Optional[Mapping[str, str]] = None
    ) -> bool:
        """Whether a split-library build beside ``binary`` carries no GPU backend at all.

        Stricter than ``_backend_lacks_gpu_lib``, which reads cuda, hip and vulkan only:
        a SYCL, MUSA, CANN or OpenCL build offloads too, and pricing its weights against
        host RAM would refuse a load the accelerator can hold. A static or unrecognised
        layout, a directory this cannot read, and a GGML_BACKEND_PATH pointing the child
        at plugins elsewhere all answer False so a GPU build keeps its VRAM credit.
        """
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return False
        source = os.environ if env is None else env
        if str(source.get("GGML_BACKEND_PATH", "") or "").strip():
            return False
        try:
            files = tuple(path.name for path in _llama_lib_dir(binary).iterdir() if path.is_file())
        except OSError:
            return False
        cpu_stem = "ggml-cpu" if sys.platform == "win32" else "libggml-cpu"
        base_stem = "ggml-base" if sys.platform == "win32" else "libggml-base"
        split_library = any(name.startswith((cpu_stem, base_stem)) for name in files)
        return split_library and not any(_GGML_GPU_BACKEND_RE.match(name) for name in files)

    def _argv_offloads_every_layer(
        self,
        argv: Iterable[str],
        env: Optional[Mapping[str, str]] = None,
    ) -> bool:
        """Whether the final command puts every model layer on a GPU.

        Unknown placement is treated as partial offload so unverified GPU memory
        is never credited.
        """
        args = [str(a) for a in argv or ()]
        if _device_selection_is_cpu(args, env):
            return False
        if _args_place_tensors_on_cpu(args) or _env_places_tensors_on_cpu(env):
            return False
        # The fitter owns placement unless it is explicitly disabled.
        if fit_is_effectively_on(args, env):
            return False
        try:
            requested = parse_gpu_layers_override(args)
        except ValueError:
            return False
        if requested is None:
            return False
        # -1 means every layer; otherwise the count must exceed the block count.
        n_layers = self.n_layers
        return requested == -1 or (bool(n_layers) and requested > n_layers)

    @staticmethod
    def _rows_the_child_can_reach(detected_gpus, pinned_ids) -> list:
        """``detected_gpus`` narrowed to the cards THIS launch pinned the child to.

        ``_launch_host_shortfall_message`` sums free VRAM over every row it is handed,
        which is right for an advisory about the host and wrong for a decision about
        one launch: a child pinned to a subset cannot spend the VRAM on the cards it
        cannot see, so crediting them prices the spill too low and can leave an
        unmapped oversized load unrewritten, which is an OOM rather than a slow load.

        ``pinned_ids`` is the narrowing this load performed, not the visibility mask
        in ``env``. An inherited CUDA_VISIBLE_DEVICES is already applied: the probe
        only ever reported the cards it left visible, so re-applying it here would
        subtract the same pin twice and price a single-card host as having none.
        None means nothing narrowed the launch, which is not the same as an empty
        pin, and physical ids match ``row[0]``.
        """
        rows = list(detected_gpus or ())
        if pinned_ids is None:
            return rows
        visible = set(pinned_ids)
        return [row for row in rows if row[0] in visible]

    def _shared_heap_budget(
        self,
        gpus: Iterable[tuple],
        shared_gpu_ids: Collection[int],
        model_bytes: int,
        argv: list[str],
        env: Optional[Mapping[str, str]] = None,
    ) -> tuple[int, int]:
        """Return reachable shared Vulkan memory and the bytes it must hold.

        Shared iGPU rows overlap, so only the largest pool is credited. The pool
        must be reachable by an unambiguous full offload -- a device pin that
        names it, or no pin on a host where llama.cpp finds no discrete card --
        and only selected discrete cards reduce the bytes assigned to it.
        """
        rows = [(row[0], max(0, row[1])) for row in gpus]
        pinned = _extra_args_main_device(argv)
        if pinned is None and env:
            pinned = env.get("LLAMA_ARG_DEVICE")
        if pinned is None:
            reachable = {idx for idx, _free in rows}
            # Unpinned, llama.cpp builds the device list itself and appends
            # integrated GPUs only when it found no discrete one, so a shared
            # heap beside a discrete card receives nothing.
            if any(idx not in shared_gpu_ids for idx in reachable):
                reachable -= set(shared_gpu_ids)
        else:
            # Match the ggml registry names emitted by _vulkan_pin_args.
            names = {device.strip().lower() for device in str(pinned).split(",")}
            reachable = {idx for idx, _free in rows if f"vulkan{idx}" in names}
        pool = 0
        if (
            shared_gpu_ids
            and self._argv_offloads_every_layer(argv, env)
            # Tensor-split positions cannot be mapped reliably to probe indices.
            and not _extra_args_set_any_flag(argv, _TENSOR_SPLIT_FLAGS)
            and not str((env or {}).get("LLAMA_ARG_TENSOR_SPLIT") or "").strip()
            # With multiple devices, split-mode none does not identify the recipient.
            and not (len(reachable) > 1 and _split_mode_confines_to_one_device(argv, env))
        ):
            budgets = []
            for idx, free in rows:
                if idx not in shared_gpu_ids or idx not in reachable:
                    continue
                backed = self._igpu_backed_usable_mib(free)
                if backed < free:
                    logger.info(
                        f"Vulkan device VK{idx} offers {free}MiB to placement; "
                        f"host admission credits {backed}MiB"
                    )
                budgets.append(backed)
            pool = max(budgets, default = 0)
        on_cards = sum(free for idx, free in rows if idx not in shared_gpu_ids and idx in reachable)
        return pool, model_bytes - on_cards * 1024 * 1024

    def _launch_host_shortfall_message(
        self,
        cmd: Iterable[str],
        detected_gpus: Iterable[tuple],
        env: Optional[Mapping[str, str]] = None,
        *,
        child_has_no_gpu: bool = False,
        avail_mib: Optional[int] = None,
        shared_gpu_ids: Iterable[int] = (),
        honor_opt_out: bool = True,
    ) -> Optional[str]:
        """Warning when the weights alone do not fit in free VRAM plus available RAM.

        Advisory only. Nothing here blocks a load: callers log this and launch anyway.

        Weights only, against the whole free pool, is a strict lower bound on what the
        launch must hold: the KV cache, projector, drafter and compute buffers all add
        to it, and a layer or device pin only narrows the VRAM actually reachable. So
        every term this leaves out moves the estimate down, never up, and no missing
        term can turn a quiet load into a warned one. That is what keeps the check
        a floor with no placement modelling to keep in step with llama.cpp.

        Read from the finished argv, so the model path is the one the child opens. An
        unsized model abstains rather than guessing, and so does an empty GPU pool,
        which means the probe threw. ``child_has_no_gpu`` is the launch reporting a
        placement it already knows reaches no card, rather than one it could not read:
        there the whole model is host-resident and takes no VRAM credit.

        UNSLOTH_ALLOW_HOST_OFFLOAD=1 abstains outright. DEPRECATED: it was the opt-out
        from the old refusal, so all it does now is silence the warning. Still honoured
        so existing scripts and docs keep working.

        ``honor_opt_out=False`` prices the shortfall with that variable ignored, for a
        caller that needs the FACT rather than the warning. Silencing the message must
        never disable the pageable-load override, which is what lets an oversized
        unmapped load finish at all: see ``_page_an_oversized_unmapped_load``.

        ``avail_mib`` overrides the host figure for a caller that runs before the resident
        owners are released; the launch reads what is available now. ``shared_gpu_ids``
        names Vulkan iGPUs whose reported free memory overlaps the host pool. Either
        reading can hold the remaining weights, but they must never be added together.
        """
        argv = [str(a) for a in cmd or ()]
        if not argv:
            return None
        model_path = _extra_args_device(argv, self._ARGV_MODEL)
        if not model_path:
            return None
        if honor_opt_out and self._host_offload_warning_opted_out():
            logger.info("UNSLOTH_ALLOW_HOST_OFFLOAD set: skipping the host-RAM preflight.")
            return None
        # rpc places layers on remote devices this cannot size, in either spelling
        _env = os.environ if env is None else env
        if (_extra_args_device(argv, self._ARGV_RPC) or "").strip() or str(
            _env.get("LLAMA_ARG_RPC", "") or ""
        ).strip():
            return None
        try:
            model_bytes = self._get_gguf_size_bytes(model_path)
        except Exception:
            return None
        gpus = [] if child_has_no_gpu else list(detected_gpus or ())
        # _get_gpu_memory swallows a failed probe as [], so an empty pool it did not
        # vouch for cannot be told from a host that has no gpu at all
        if not model_bytes or (not gpus and not child_has_no_gpu):
            return None
        shared = set(shared_gpu_ids or ())
        free_vram_mib = sum(max(0, row[1]) for row in gpus if row[0] not in shared)
        heap_free_mib, heap_bytes = self._shared_heap_budget(gpus, shared, model_bytes, argv, _env)
        offload_bytes = model_bytes - free_vram_mib * 1024 * 1024
        # A carve-out can satisfy the dedicated-VRAM shortfall. Skip card-resident
        # loads so a cgroup budget is never applied to a nonpositive need.
        if 0 < offload_bytes and heap_bytes <= heap_free_mib * 1024 * 1024:
            # A finite cgroup still limits host-backed GPU allocations.
            cgroup_mib = self._cgroup_available_memory_mib()
            if cgroup_mib is None:
                return None
            return self._apu_ram_shortfall_message(heap_bytes, cgroup_mib)
        return self._host_offload_shortfall_message(
            offload_bytes,
            self._available_system_memory_mib() if avail_mib is None else avail_mib,
        )

    @staticmethod
    def _apu_ram_shortfall_message(
        model_size_bytes: int,
        avail_mib: Optional[int],
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
    ) -> Optional[str]:
        """On a unified-memory APU, return a user-facing WARNING when the weights
        do not fit in available system RAM (else None). Weights only: KV/context
        auto-reduce, so counting them too would warn about loads that are fine.
        None avail (unknown RAM) never warns.

        Advisory, never a refusal: the load goes ahead and llama.cpp reports what
        actually happens rather than Studio pre-empting a failure it predicted.
        """
        if avail_mib is None:
            return None
        need_mib = model_size_bytes / (1024 * 1024)
        if need_mib <= avail_mib - headroom_mib:
            return None
        return (
            f"This model needs about {need_mib / 1024:.0f} GB but only about "
            f"{avail_mib / 1024:.0f} GB of memory is available. On a unified-memory "
            "APU the weights load into system RAM, so the OS may stop the load. "
            "Loading anyway. If it does not complete, use a smaller or more "
            "quantized GGUF, or free memory (on WSL, raise the memory limit in "
            ".wslconfig)."
        )

    @staticmethod
    def _host_offload_shortfall_message(
        offload_bytes: int,
        avail_mib: Optional[int],
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
    ) -> Optional[str]:
        """On a discrete GPU, return a user-facing WARNING when the part of a load
        that misses VRAM does not fit in available system RAM (else None). Priced
        against free VRAM with no margin subtracted, so it under-states the spill and
        only an unambiguous shortfall warns. None avail (unknown RAM), and anything
        VRAM-resident, never warn.

        Advisory, never a refusal. The spill is mmap'd, so the weights page in from disk
        rather than failing: off fast storage that is a deliberate way to run a quant
        larger than the machine's fast memory, and this check cannot tell how fast the
        backing store is. It reports the cost; the user decides.
        """
        if offload_bytes <= 0 or avail_mib is None:
            return None
        need_mib = offload_bytes / (1024 * 1024)
        if need_mib <= avail_mib - headroom_mib:
            return None
        # need up, usable down, so the printed pair cannot round into a tie
        need_gb = math.ceil(need_mib / 1024)
        usable_gb = math.floor(max(0, avail_mib - headroom_mib) / 1024)
        return (
            f"About {need_gb} GB of this model does not fit in GPU memory and would run "
            f"from system RAM. Only about {avail_mib / 1024:.0f} GB is available and "
            f"{headroom_mib / 1024:.0f} GB of that is kept free for the rest of the "
            f"system, leaving about {usable_gb} GB usable. The weights are memory-mapped, "
            "so the machine pages them in from disk as it runs. Loading anyway: expect "
            "slow generation, and slower still on a hard disk than on an SSD. A smaller "
            "or more quantized GGUF, or more free memory, would run faster."
        )

    @staticmethod
    def _host_offload_warning_opted_out() -> bool:
        """Whether UNSLOTH_ALLOW_HOST_OFFLOAD silences the host-RAM warning.

        The user's own opt-out, so it reads the REAL environment rather than the
        curated child env. DEPRECATED and warning-scoped: it was the escape from a
        refusal that no longer exists, so all it may do is suppress a message. It must
        never reach a decision that changes what the child runs.
        """
        return os.environ.get("UNSLOTH_ALLOW_HOST_OFFLOAD", "").strip().lower() in (
            "1",
            "true",
            "yes",
        )

    def _page_an_oversized_unmapped_load(
        self, cmd: Iterable[str], env: Optional[dict], oversized
    ) -> tuple[list, Optional[str]]:
        """Rewrite a launch that is BOTH oversized and non-pageable into a pageable one.

        Returns ``(cmd, note)``: the argv to launch, and the sentence to append to
        whatever warning is emitted, or None when nothing was overridden and ``cmd``
        comes back unchanged.

        The host-RAM shortfall is survivable only because the weights are mmap'd: the
        whole premise is that the spill pages in from disk as the model runs. Modes
        "none" and "mlock" have no such fallback -- upstream sets use_mmap for
        mmap/mmap+mlock/auto and nothing else (llama-model-loader.cpp), so those two
        read the weights into a buffer llama.cpp allocates. The same shortfall is then
        an allocation failure or an OOM kill during loading, not slow generation.
        Reached by ``--load-mode``, by the deprecated ``--no-mmap`` / ``--no-direct-io``
        spellings, and by the LLAMA_ARG_* twins llama.cpp reads before argv, so the
        EFFECTIVE state is what decides, not the tokens Unsloth happens to have emitted.

        This never blocks a load, so the unmapped request is OVERRIDDEN rather than
        refused: the pageable equivalent goes in (a lock is kept, as mmap+mlock) so the
        load the user asked for can actually finish. Only on a real shortfall -- an
        unmapped load that fits is exactly what was asked for and is left byte for byte
        as written. Said out loud, since a silent override is its own surprise: in the
        returned note when a warning is emitted, and in the log either way, so a load
        whose warning was silenced is still traceable.

        One helper for every launch that can discover a shortfall (the APU preflight,
        the discrete host guard, the arch-crash retry), because the decision belongs to
        the CONDITION and not to any one warning: a site that only recorded, or a
        warning the environment suppressed, would otherwise skip the remap and hand the
        child a load it cannot complete. ``oversized`` is the per-site shortfall
        predicate, called only once the cheap non-pageable test has passed, so a
        comfortable launch pays for no pricing.
        """
        # The caller's own list back on every no-op path, not a rebuilt copy: an
        # untouched launch must stay byte for byte, and the same token objects, as
        # whatever built it.
        original = cmd if isinstance(cmd, list) else list(cmd or ())
        _mlock_now, _reserves_ram_now = resolve_effective_memory_state(original, env)
        if not _reserves_ram_now:
            return original, None
        try:
            if not (oversized() if callable(oversized) else oversized):
                return original, None
        except Exception:
            # Advisory pricing: an unreadable host or GGUF leaves the launch alone.
            logger.debug("Could not price the load for a pageable override.", exc_info = True)
            return original, None
        paged, overridden = force_pageable_load(original, env)
        if not overridden:
            return original, None
        logger.warning(
            "Overriding the unmapped load mode (%s) for an oversized model: it would "
            "allocate the whole model in host RAM instead of paging it in.",
            ", ".join(overridden),
        )
        return paged, _PAGEABLE_OVERRIDE_NOTE

    @property
    def last_load_warning(self) -> Optional[str]:
        """Advisory notice from the most recent load, or None. Read by the route."""
        return self._last_load_warning

    def _begin_load_warnings(self) -> None:
        """Drop the previous load's advisory notice, at the point a load commits to
        replacing the resident server. Without it a warned load followed by a
        comfortable one would report the first load's notice against the second.

        Called from the Phase 1 teardown, not from the top of ``load_model``: an
        attempt rejected before that point leaves the old child serving, and its
        advisory has to survive with it (the route still answers ``already_loaded``
        from that child). The arch-crash retry calls it again for the same reason in
        reverse -- the placement everything was priced against is the one that just
        died."""
        self._last_load_warning = None

    def _record_load_warning(self, message: Optional[str]) -> None:
        """Log an advisory memory notice and keep it for the route to hand back.

        Never raises: these replace what used to be a refusal, and an oversized GGUF
        pages from disk instead of failing, so the load is the user's call. First notice
        wins, since the earliest priced the whole pool and later ones see a narrowed
        selection.
        """
        if not message:
            return
        logger.warning(message)
        if self._last_load_warning is None:
            self._last_load_warning = message

    def _amend_load_warning(self, note: Optional[str]) -> None:
        """Append to the notice already recorded for this load, if there is one.

        The pageable-load override can be settled after an earlier guard has already
        recorded its warning: the APU preflight runs long before ``cmd`` and ``env``
        exist, which is where the override has to be applied. First notice wins, so
        that earlier text is what the route hands back, and appending is what keeps the
        override named in the message the user actually sees. A load whose warning was
        suppressed has nothing to amend and keeps the log line as its only record.
        """
        if note and self._last_load_warning:
            self._last_load_warning += note

    def _reprice_after_dropping_pinned_projector(
        self,
        *,
        apu_msg: Optional[str],
        host_msg: Optional[str],
        model_size: Optional[int],
        pinned_bytes: int,
        avail_mib: Optional[int],
    ) -> None:
        """Re-price the APU RAM advisory once a text-only retry drops a CPU-pinned
        vision projector.

        The APU preflight charges ``model_size + _mmproj_pinned_bytes``, because a
        projector pinned to the CPU loads into the same system RAM as the weights. When
        that projector then fails to start and the retry strips ``--mmproj``, the child
        that came up healthy never read those bytes: the recorded shortfall describes a
        load nothing is running. Priced again without them, so the notice matches what
        the serving process actually holds -- rewritten to the smaller need if the
        weights alone still do not fit, handed to the discrete guard's notice if that
        one also found a shortfall, and otherwise dropped.

        What is NOT undone is the pageable-load override. It rewrote the argv and, in
        ``force_pageable_load``, the shared child env in place, and the child was
        spawned from both long before this runs, so the server IS memory-mapped and
        nothing here can change that; reverting it would need yet another respawn of a
        process that just came up healthy, on the recovery rung that exists because this
        model has already failed to start once. So an override that the reprice shows
        was not needed is reported rather than reverted: whatever note the message
        carried is kept, and a load whose only remaining news is the override says that
        and nothing else.

        A no-op unless the projector was actually charged and the APU advisory is
        actually what the route would hand back -- an opt-out that silenced it, or any
        other notice that first-notice-wins kept, is left exactly as it is.
        """
        if not apu_msg or pinned_bytes <= 0 or model_size is None or avail_mib is None:
            return
        current = self._last_load_warning
        if not current or not current.startswith(apu_msg):
            return
        # Whatever _amend_load_warning appended (the pageable-override note), carried
        # over rather than rebuilt, so a reprice cannot describe the override in
        # different words than the launch site did.
        suffix = current[len(apu_msg) :]
        # ``avail_mib`` is the figure the PREFLIGHT read, carried down rather than taken
        # again here. By this point the text-only child is healthy and holding the
        # weights, so a fresh reading is the pool minus the very model being priced:
        # it would charge ``model_size`` against ``avail - model_size`` and report a
        # shortfall for a load that demonstrably just started. Same pool, one term
        # removed, is the only comparison that answers the question being asked.
        repriced = self._apu_ram_shortfall_message(model_size, avail_mib)
        if repriced:
            self._last_load_warning = repriced + suffix
        elif host_msg:
            # The discrete guard priced the same launch and lost first-notice-wins.
            # It reads the model path off the argv and never charged the projector,
            # so dropping the projector leaves its verdict standing.
            self._last_load_warning = host_msg + suffix
        elif suffix.strip():
            self._last_load_warning = _PAGEABLE_OVERRIDE_TEXT_ONLY_NOTICE
        else:
            self._last_load_warning = None
        logger.info(
            "Text-only fallback dropped the CPU-pinned vision projector (%.0f MiB); "
            "re-priced the host memory advisory against the weights alone.",
            pinned_bytes / (1024 * 1024),
        )

    def _reprice_after_cpu_only_fallback(
        self,
        *,
        host_msg: Optional[str],
        cpu_cmd: Iterable[str],
        env: Optional[Mapping[str, str]],
        avail_mib: Optional[int],
        pageable_note: Optional[str] = None,
    ) -> None:
        """Re-price the host memory advisory once a Vulkan crash is replayed on CPU.

        The replay launches with ``--gpu-layers 0 --device none``, so no VRAM is
        credited to it at all: the child that serves the session holds the WHOLE model
        in system RAM and pages it from disk. Two things follow, and the preflight
        notice gets neither right.

        A load that was warned about its spill was warned about the spill of the GPU
        placement that just died. The replay's spill is the whole model, which is
        strictly larger, so the recorded figure understates what the running child
        actually pages. And a load that FIT in VRAM was never warned at all, yet it is
        the one the user most needs told: it now runs entirely from host RAM on a host
        that may not hold it, and ``memory_warning`` was null for it.

        Priced against ``avail_mib``, the figure the PREFLIGHT read, for the same reason
        the projector reprice carries its own snapshot down: this runs after
        ``_spawn_and_wait`` reports the CPU child healthy, so a fresh reading is the
        pool minus the model being priced and would report a shortfall for a load that
        demonstrably just started.

        Called only where the replay is known healthy, never where it is chosen. A
        failed replay is not terminal on every rung -- the drafter replay reports "not
        recovered" and the caller tries the drafterless argv next -- so pricing at the
        decision would describe a placement about to be abandoned.

        The pageable-load override is NOT re-decided here, and nothing claims it was
        reverted. ``force_pageable_load`` rewrote the argv and the shared child env in
        place before the first spawn, and ``_cpu_isolated_replay`` strips placement
        alone, so the replay inherits both and the CPU child really is memory-mapped.
        Whatever note the preflight message carried is carried over verbatim onto the
        re-priced text rather than rebuilt, so a reprice cannot describe the override in
        different words than the launch site did.

        ``pageable_note`` is the override ``_prepare_cpu_fallback_launch`` decided on
        the REPLAY, which the preflight message cannot have carried: a launch that fit
        in VRAM was priced as pageable-enough and left the user's unmapped mode alone,
        and only the replay's own footprint (no VRAM credited) turns it into a full
        host allocation. Both notes cannot be set at once -- if the preflight had
        already overridden, the replay it built from is mapped and the second pricing
        finds nothing to rewrite -- so this appends rather than replaces. Priced against
        the same ``avail_mib`` the rewrite used, so the advisory cannot describe an
        unmapped load the same pool reading has just made mapped.

        A no-op unless the notice the route would hand back is the one this path can
        speak for: an opt-out that silenced it (the re-pricing call honours it too), or
        any other notice first-notice-wins kept, is left exactly as it is. The note
        follows the message: an override on a silenced load stays in the log alone,
        exactly as it does on the main launch path.
        """
        repriced = self._launch_host_shortfall_message(
            cpu_cmd,
            (),
            env,
            child_has_no_gpu = True,
            avail_mib = avail_mib,
        )
        note = pageable_note or ""
        current = self._last_load_warning
        if current is None:
            # The model fit in VRAM, so nothing warned; on CPU it fits nowhere but disk.
            self._record_load_warning((repriced + note) if repriced else None)
            return
        if not host_msg or not current.startswith(host_msg) or not repriced:
            # Nothing here can be re-priced, but an override still changed the child:
            # say so on whatever notice first-notice-wins kept.
            self._amend_load_warning(pageable_note)
            return
        self._last_load_warning = repriced + current[len(host_msg) :] + note
        logger.info(
            "Re-priced the host memory advisory for the CPU replay: it runs with no "
            "GPU, so the whole model is charged to system RAM."
        )

    def _fits_without_paging(
        self,
        footprint_bytes: Optional[int],
        detected_gpus: Iterable[tuple],
        *,
        gpu_indices: Optional[Iterable[int]] = None,
        shared_gpu_ids: Iterable[int] = (),
        host_only_bytes: int = 0,
        vram_margin_mib: float = 0.0,
        avail_mib: Optional[int] = None,
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
    ) -> Optional[bool]:
        """Whether the whole load fits in VRAM, or in VRAM plus host RAM (else False;
        None when it cannot be told). This is the ``--load-mode`` question: mmap earns
        its keep by demand-paging a footprint the machine cannot hold, so a load that
        fits never needs it.

        ``footprint_bytes`` is weights + KV + scratch, not weights alone. The refusal
        guards next door deliberately price weights only, because understating there
        can only fail to refuse a load that would have worked. Here the bias runs the
        other way: understating would claim a fit that isn't one and hand the load a
        loader that cannot page, so every term the launch knows about is charged.

        Shared iGPU memory is not added on top of host RAM (it IS host RAM), so those
        devices are dropped from the VRAM term and their weights are carried by the RAM
        term, the same split ``_launch_host_shortfall_message`` uses. ``gpu_indices``
        narrows the VRAM term to the devices this launch actually pins; unpinned cards
        hold nothing for it. Unreadable RAM answers None rather than guessing, which
        keeps the caller on llama.cpp's own default.

        ``host_only_bytes`` is the part of ``footprint_bytes`` that CANNOT be satisfied
        out of VRAM however much is free -- a drafter the launch pinned to the CPU is
        the case -- so it is subtracted from what VRAM may cover and added to the RAM
        requirement instead. Pooling it would let free VRAM pay for bytes that can only
        ever be allocated in host RAM.

        ``vram_margin_mib`` is the free VRAM llama.cpp's own fitter keeps PER DEVICE
        and will not allocate into (``--fit-target``, default 1024 MiB, "target margin
        per device for --fit"; common/arg.cpp, common/common.h). Under ``--fit on``
        the child spills weights to host RAM rather than dip into it, so those bytes
        are not credit this launch may spend. Zero on the proved path, which emits
        ``-ngl -1 --fit off`` and runs no fitter at all.
        """
        if not footprint_bytes or footprint_bytes <= 0:
            return None
        host_only = max(0, int(host_only_bytes or 0))
        shared = set(shared_gpu_ids or ())
        pinned = None if gpu_indices is None else {int(idx) for idx in gpu_indices}
        margin_mib = max(0.0, float(vram_margin_mib or 0.0))
        free_vram_mib = sum(
            max(0, row[1] - margin_mib)
            for row in (detected_gpus or ())
            if row[0] not in shared and (pinned is None or row[0] in pinned)
        )
        free_vram_bytes = int(free_vram_mib * 1024 * 1024)
        # VRAM covers the GPU-eligible part; its spill plus the host-only bytes hit RAM.
        spill = max(0, max(0, footprint_bytes - host_only) - free_vram_bytes) + host_only
        if spill <= 0:
            return True
        avail = self._available_system_memory_mib() if avail_mib is None else avail_mib
        if avail is None:
            return None
        # Same headroom the host-offload refusal keeps free: a RAM filled to the last
        # byte is the paging case this is trying to avoid.
        return spill <= max(0, avail - headroom_mib) * 1024 * 1024

    def _fit_derived_load_mode(
        self,
        *,
        model_size: Optional[int],
        mmproj_pinned_bytes: int = 0,
        kv_cache_bytes: int = 0,
        kv_sized: bool = True,
        mtp_bytes: int = 0,
        mtp_unsized: bool = False,
        host_only_bytes: int = 0,
        compute_buffer_flat: int = 0,
        compute_buffer_ctx: int = 0,
        pipeline_overhead_bytes: int = 0,
        soft_overhead: int = 0,
        gpus: Optional[Iterable[tuple]] = None,
        gpu_indices: Optional[Iterable[int]] = None,
        shared_gpu_ids: Iterable[int] = (),
        fit_margin_mib: float = 0.0,
        is_vulkan_backend: bool = False,
        avail_mib: Optional[int] = None,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[str]:
        """``"none"`` when the fit proves the load needs no demand paging, else None.

        mmap exists to demand-page a footprint the machine cannot hold, and llama.cpp
        builds its async pinned-buffer upload path ONLY when mmap is off
        (llama-model-loader.cpp, ``upload_backend``), so a load that fits wants
        ``none``: same residency, faster load, no model-sized mapping left behind.
        Anything that does not fit, or that cannot be priced, keeps llama.cpp's own
        ``auto``, where the mapping is what stops an over-committed load from being
        killed outright.

        The footprint is charged WHOLE, weights and KV and scratch, because
        understating it would claim a fit that is not there and hand the load a loader
        that cannot page. Every term that cannot be read abstains for the same reason:
        unreadable weights, an unsized KV (the estimator returns 0 without the dims,
        and a 0 KV term on a long-context load is exactly the missing term) and a
        drafter engaged but unsized, which the placement itself covers with a flat
        cushion rather than a number.

        ``host_only_bytes`` is the slice of that footprint no amount of free VRAM can
        hold (a drafter pinned to the CPU with ``-ngld 0``): counted in the total, but
        charged to host RAM alone, because free VRAM cannot pay for an allocation the
        child only ever makes on the host. ``kv_cache_bytes`` joins it under an
        effective ``--no-kv-offload``, which puts the WHOLE cache on the host
        whatever the layer placement says (llama-kv-cache.cpp defaults each layer's
        buffer type to the CPU one and upgrades it only inside ``if (offload)``).

        Apple Silicon abstains outright. Metal is the one backend where
        ``buffer_from_host_ptr`` IS supported, so mmap wraps the weights in a Metal
        buffer in place, zero copy and file backed; ``none`` would allocate the same
        bytes anonymously, and an evictable 30 GB mapping on a 32 GB machine is the
        difference between working and being jetsammed. The host figure is the wrong
        ceiling there anyway (see ``_apple_metal_memory_budget_bytes``), so a fit read
        off ``MemAvailable`` would not be one worth acting on.

        ``extra_args`` is the pass-through block as the child will really get it (the
        caller strips what a ``gpu_ids`` pin owns first), and it voids the VRAM term.
        Those tokens are appended AFTER this launch's own placement flags and
        llama.cpp is last-wins (common/arg.cpp assigns ``n_gpu_layers`` / ``devices``
        on every occurrence), so a hand-typed ``-ngl``, a ``--device`` naming no GPU
        or a CPU tensor override runs weights out of host RAM that the planner just
        credited to a card. The placement this priced is then not the one that
        launches, and ``none`` on a footprint host RAM cannot hold is an OOM where
        ``auto`` would have demand-paged. Dropping the VRAM credit rather than
        abstaining keeps the answer for the case that is still provable: a load host
        RAM holds WHOLE is safe wherever those flags end up putting it. The same
        predicates the Model Memory host-residency gate uses, so the two cannot drift.

        ``env`` is the environment the child will really get (``os.environ`` when the
        caller passes none). Every one of those pass-through overrides has an env twin
        llama.cpp reads BEFORE argv, so classifying on the tokens alone would miss an
        inherited ``LLAMA_ARG_DEVICE=none``, which no automatic launch clears (only an
        explicit ``gpu_ids`` pin does). A ``--device`` naming FEWER devices than this
        fit credits voids the VRAM term for the same reason a CPU-valued one does: the
        cards it leaves out hold nothing for this launch. ``LLAMA_ARG_N_GPU_LAYERS``
        is the sharpest of them: the fitting path emits no ``-ngl`` for it to lose
        to, so an inherited count is the whole layer policy (see
        ``_env_fixes_gpu_layers``).

        ``fit_margin_mib`` is what llama.cpp's fitter keeps free per device when the
        fitter really runs, i.e. VRAM this load may not spend; see
        ``_fits_without_paging``. The caller answers that from the EFFECTIVE flags
        rather than from its own plan: the extras land after this launch's ``--fit``
        and llama.cpp is last-wins, ``-ngl -1`` is llama.cpp's own default so an
        enabled fitter is free to lower it (common/fit.cpp aborts only on a count the
        user really set), and a pass-through ``--fit-target`` raises the margin above
        anything ``_ctx_integrity_flags`` emitted.
        """
        from utils.hardware import is_apple_silicon

        if not model_size or not kv_sized or mtp_unsized or is_apple_silicon():
            return None
        # Pass-through adapters are resident weights model_size (the base GGUF alone)
        # never carried. A TERM, not a placement override, so an unreadable one abstains.
        sidecar_bytes = _sidecar_adapter_bytes(extra_args)
        if sidecar_bytes is None:
            return None
        rows = list(gpus or ())
        source_env = os.environ if env is None else env
        # A --device naming FEWER devices than this fit charges leaves the credit
        # paying for cards the child never opens. llama.cpp REPLACES the list on every
        # occurrence (parse_device_list) and reads LLAMA_ARG_DEVICE before argv, so the
        # last of the two wins. Counted, not name-matched: CUDA/ROCm ordinals are
        # assigned after a visibility mask this launch has not written yet.
        _dev_value = _extra_args_main_device(extra_args)
        if _dev_value is None:
            _dev_value = source_env.get("LLAMA_ARG_DEVICE")
        _dev_names = [d.strip() for d in str(_dev_value or "").split(",") if d.strip()]
        _credited = len(list(gpu_indices)) if gpu_indices is not None else len(rows)
        # DISTINCT names: llama.cpp appends every entry without deduplicating and
        # keeps the list verbatim, so "CUDA0,CUDA0" is ONE physical pool listed twice,
        # and counting it as two leaves the credit paying for a card that is not there.
        _device_narrows = bool(_dev_names) and len(set(_dev_names)) < _credited
        # Vulkan is the one backend where names ARE comparable (_vulkan_device_pin ->
        # "Vulkan<i>"), so hold a surviving --device to an exact match. That catches
        # what a count cannot: a same-sized list naming DIFFERENT cards, and a longer
        # one adding devices this footprint never charged for.
        _vulkan_pin_replaced = bool(
            is_vulkan_backend
            and gpu_indices is not None
            and _dev_names
            and {name.strip().lower() for name in _dev_names}
            != {f"vulkan{idx}" for idx in gpu_indices}
        )
        if (
            _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
            # And its env twin, the ONLY layer count the fitting path leaves: it
            # emits no -ngl, only Manual mode clears LLAMA_ARG_N_GPU_LAYERS, and the
            # fitter will not lower a count it did not set, so an inherited one stands
            # and loads a prefix out of host RAM.
            or _env_fixes_gpu_layers(source_env)
            # With the env twin: only an explicit gpu_ids pin clears LLAMA_ARG_DEVICE,
            # so an inherited "none" puts the whole load in host RAM.
            or _device_selection_is_cpu(extra_args, source_env)
            or _device_narrows
            or _vulkan_pin_replaced
            # Pass-through and last-wins: --split-mode none, or a --tensor-split that
            # zeroes a device, leaves the pooled credit paying for cards held empty.
            or split_policy_starves_devices(extra_args, _credited, source_env)
            or _args_place_tensors_on_cpu(extra_args)
            or _env_places_tensors_on_cpu(source_env)
        ):
            logger.info(
                "Load mode: pass-through arguments override the placement this fit "
                "priced; charging the whole load to host RAM."
            )
            rows, gpu_indices = [], None
        footprint = (
            model_size
            # Pass-through LoRA / control vectors, allocated alongside the base tensors.
            + max(0, sidecar_bytes)
            # A CPU-pinned projector left model_size but is still resident, and this
            # is a footprint rather than a VRAM budget.
            + max(0, mmproj_pinned_bytes)
            + max(0, kv_cache_bytes)
            # Carries the drafter's own weights and KV.
            + max(0, mtp_bytes)
            # Resident, but only ever in host RAM; charged to the RAM term alone below.
            + max(0, host_only_bytes)
            + max(0, compute_buffer_flat)
            + max(0, compute_buffer_ctx)
            # A layer split puts a fixed CUDA context and scratch on EVERY device, and
            # the lumps above cover one, so the rest is a term of its own (the same one
            # _subset_model_size reserves). 0 on a single GPU.
            + max(0, pipeline_overhead_bytes)
            + max(0, soft_overhead)
        )
        # Unified memory is ONE pool: an APU's free VRAM IS the host RAM the spill
        # comes out of, so adding both fits a model twice into memory that holds it
        # once. shared_gpu_ids already names Vulkan iGPUs; the ROCm APUs it cannot see
        # are added here. Both end up priced against host RAM alone.
        shared = set(shared_gpu_ids or ())
        pinned = list(gpu_indices) if gpu_indices is not None else [idx for idx, _free in rows]
        if rows and not is_vulkan_backend and self._amd_apu_wants_unified_memory(pinned):
            # Per device, not blanket: the gate above is the cheap "is ANY of them
            # unified" question, and a discrete card next to an APU still has a pool of
            # its own, so re-ask per row rather than forfeit a fit that is really there.
            shared |= {idx for idx, _free in rows if self._amd_apu_wants_unified_memory([idx])}
        # --no-kv-offload puts the WHOLE cache in host RAM whatever the layer placement
        # says (llama-kv-cache.cpp upgrades a layer's buffer type only inside
        # `if (offload)`), so free VRAM may not pay for it. Resolved off the same
        # effective views the placement overrides above use.
        _kv_on_host = not _kv_offload_from_args(extra_args, env = source_env)
        if self._fits_without_paging(
            footprint,
            rows,
            gpu_indices = gpu_indices,
            shared_gpu_ids = shared,
            # A CPU-pinned projector is host-resident: counted once in the footprint
            # above, and charged here to the term free VRAM may NOT pay for, so surplus
            # VRAM cannot cover it and answer True without consulting RAM.
            host_only_bytes = (
                max(0, host_only_bytes)
                + max(0, mmproj_pinned_bytes)
                # Same split as the pinned projector: counted once above, charged to RAM.
                + (max(0, kv_cache_bytes) if _kv_on_host else 0)
            ),
            vram_margin_mib = fit_margin_mib,
            avail_mib = avail_mib,
        ):
            logger.info(
                "Load mode: the whole load (%.1f GB) fits without paging, using --load-mode %s.",
                footprint / (1024**3),
                self._FIT_LOAD_MODE,
            )
            return self._FIT_LOAD_MODE
        return None

    # What a proven fit picks. One name, because the choice is a measurement.
    # Load-to-ready on a B200 over local NVMe, median of 3, full offload, b10360:
    #
    #   Qwen3-4B Q4_K_M (2.5 GB)          cold   warm
    #     mmap (no flag)                  1.81   1.42
    #     none                            2.04   1.49
    #     dio                             2.05   1.69
    #   Qwen3-30B-A3B UD-Q4_K_XL (17 GB)  cold   warm
    #     mmap (no flag)                  5.43   2.81
    #     none                            5.49   3.21
    #     dio                             2.26   2.30
    #
    # So "none" is NOT the fast one here: it drops mmap and unlocks llama.cpp's async
    # pinned-buffer uploader, but still pays the page-cache copy, which on this storage
    # costs more than the uploader wins. "dio" takes that uploader AND skips the cache,
    # and is 2.4x faster cold on the model big enough for loading to matter, which is
    # upstream's guidance too. Kept at "none" because that is what was asked for; this
    # constant is the whole switch. dio has no pre-enum spelling, so a build without
    # --load-mode would emit nothing rather than a legacy flag.
    _FIT_LOAD_MODE = "none"

    METAL_CTX_OVERCOMMIT_ENV = "UNSLOTH_ALLOW_METAL_CTX_OVERCOMMIT"

    @staticmethod
    def _metal_context_overcommit_message(
        requested_ctx: int,
        max_available_ctx: int,
        cache_type_kv: Optional[str] = None,
        *,
        nothing_fits: bool = False,
    ) -> Optional[str]:
        """Refusal when a hand-set context exceeds what unified memory holds (else None).

        The Metal placement branch already works out the largest context that fits, but
        only Auto was moved to it: an explicit request was passed through verbatim, on
        the theory that "--fit on" is a backstop. It is one, just not a trustworthy one
        here. llama.cpp will reduce an explicit context (common.h: fit_params_min_ctx
        defaults to 4096, and only "-c 0" disables the reduction outright), but it
        decides from the free memory ggml-metal reports, off the device's
        recommendedMaxWorkingSetSize. That is a property of the machine, not the moment:
        it knows nothing of Unsloth's own resident gigabyte or two, of whatever else the
        user has open, or of the iogpu wired limit that is the figure actually being
        blown. _apple_metal_memory_budget_bytes exists for exactly that gap, and takes
        min(device ceiling, psutil available) instead.

        So an optimistic estimate leaves the request alone and the launch over-commits
        wired memory. Wired pages are not reclaimable, so Jetsam cannot step in: the
        driver faults and the machine panics rather than the load failing the way it
        would on a discrete GPU (r/unsloth, M1 Max 32 GB, Qwen3.8-27B-UD-Q4_K_XL,
        panicked twice on a hand-set context, and never on Auto).

        Refusing rather than silently clamping is deliberate: a context that quietly
        became a quarter of what was asked for is its own support thread.

        Unlike ``_apu_ram_shortfall_message`` this prices the context, not just the
        weights. That helper leaves KV out because context auto-reduces on its path; here
        the explicit request is exactly what does not auto-reduce, so the KV and compute
        buffers it implies are the bytes that do the damage.

        Callers pass a ceiling measured with a real KV estimate. The 4096 floor the
        branch falls back to when KV cannot be sized is a guess, and refusing against it
        would block contexts that load fine today.

        UNSLOTH_ALLOW_METAL_CTX_OVERCOMMIT=1 abstains, matching the host-offload opt-out,
        though the failure mode it re-enables is the whole machine rather than one app.
        """
        if requested_ctx <= 0:
            return None
        # nothing_fits carries its own verdict, and is the one case with no positive
        # ceiling: the fit priced its smallest context and even that did not fit.
        if not nothing_fits:
            if max_available_ctx <= 0:
                return None
            if requested_ctx <= max_available_ctx:
                return None
        # the user's own opt-out, so read the real environment, not the curated child env
        if os.environ.get(LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV, "").strip().lower() in (
            "1",
            "true",
            "yes",
        ):
            logger.info(
                "%s set: launching at a context unified memory is not sized for.",
                LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV,
            )
            return None
        kv_hint = (
            " Setting the KV cache to q8_0 roughly halves what the context costs."
            if (cache_type_kv or "f16").strip().lower() in ("f16", "fp16", "")
            else ""
        )
        if nothing_fits:
            return (
                "No context fits in this Mac's unified memory with this model. The weights "
                "fit, but they leave too little for even the smallest context, so a load at "
                f"any length would over-commit. The GPU and the rest of the system share one "
                f"pool here, so there is nothing to offload to, and the load would bring the "
                f"machine down instead of reporting an error. Use a smaller or more quantized "
                f"GGUF, or free memory."
                f"{kv_hint} Set "
                f"{LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV}=1 to load it anyway."
            )
        return (
            f"A context of {requested_ctx:,} tokens does not fit in this Mac's unified "
            f"memory with this model. The largest that fits is {max_available_ctx:,} "
            "tokens. The GPU and the rest of the system share one pool here, so there is "
            "nothing to offload to, and the load would bring the machine down instead of "
            f"reporting an error. Lower the context to {max_available_ctx:,} or less, "
            "leave it on Auto, or use a more quantized GGUF."
            f"{kv_hint} Set "
            f"{LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV}=1 to load it anyway."
        )

    # Skip the wait when the last kill is older than this; the driver has
    # already reclaimed the prior process's allocations.
    _VRAM_SETTLE_WINDOW_S: float = 15.0

    @staticmethod
    def _wait_for_vram_settle(
        max_wait: float = 2.0,
        interval: float = 0.25,
        tolerance_mib: int = 256,
        since_kill: float = 0.0,
    ) -> None:
        """Poll ``_get_gpu_free_memory`` until free VRAM stabilises.

        The driver reclaims a dead process's allocations asynchronously, so
        sampling free memory in the kill-to-spawn window reads artificially low
        and pushes GPU selection toward needless CPU offload (the Apply-reload
        OOM bare-shell launches never see).

        Short-circuits on cold start, stale kill (older than
        ``_VRAM_SETTLE_WINDOW_S``), CPU-only hosts, probe exceptions, and GPU-set
        changes. ``max_wait`` bounds wall-clock time so a wedged ``nvidia-smi``
        can't extend the reload.
        """
        now = time.monotonic()
        if since_kill <= 0.0:
            return
        if now - since_kill > LlamaCppBackend._VRAM_SETTLE_WINDOW_S:
            return
        deadline = now + max_wait

        def _probe_or_none():
            if time.monotonic() >= deadline:
                return None
            try:
                return LlamaCppBackend._get_gpu_free_memory()
            except Exception:
                return None

        prev = _probe_or_none()
        if prev is None or not prev:
            return
        while time.monotonic() < deadline:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return
            # Clip the nap so a near-zero ``max_wait`` is respected.
            time.sleep(min(interval, remaining))
            curr = _probe_or_none()
            if curr is None or not curr or len(curr) != len(prev):
                return
            prev_map = dict(prev)
            stable = True
            for idx, free in curr:
                if idx not in prev_map:
                    stable = False
                    break
                prev_free = prev_map[idx]
                # Adaptive: 2% of the larger sample dominates the 256 MiB floor.
                per_gpu_tol = max(tolerance_mib, int(max(free, prev_free) * 0.02))
                if abs(free - prev_free) >= per_gpu_tol:
                    stable = False
                    break
            if stable:
                return
            prev = curr

    # Free-VRAM fraction at which Unsloth pins the GPU directly instead of
    # deferring to ``--fit on``. 3% headroom: the compute buffer is now modelled in
    # the fit, so this only guards fragmentation + multi-GPU per-device CUDA context
    # (~2-3%); kept >= 3% as a floor (0.90 dropped 91-94% fits to CPU offload, #5106).
    _GPU_PIN_VRAM_FRACTION = 0.97

    # Fallback per-device tensor-mode compute buffer (MiB), used only when GGUF
    # dims are unavailable so _estimate_compute_buffer_bytes (the primary, derived
    # path) returns 0.
    _TENSOR_PARALLEL_BUFFER_RESERVE_MIB = 5120

    # Fixed per-device overhead on every GPU of a LAYER split (CUDA context +
    # scratch), beyond the conserved slot-scaling buffer. ~0.9 GB/device measured
    # (Qwen3.6-27B, b9625), independent of --parallel; reserved per extra GPU so a
    # tight layer split can't advertise a context that OOMs at load.
    _PIPELINE_PER_DEVICE_OVERHEAD_MIB = 1024

    # V cache types that llama.cpp can run WITHOUT flash attention. Only the V
    # axis has the dependency: a quantized V cache (q8_0/q4_0/q4_1/q5_0/q5_1/
    # iq4_nl) aborts init with "V cache quantization requires flash_attn", while
    # a quantized K cache runs fine without FA. So the flash-attn-off crash-
    # recovery fallback must reset a quantized V cache to f16 before it can
    # launch (and leaves K alone). These three are the only non-quantized types.
    _NON_QUANTIZED_KV_TYPES = frozenset({"f16", "bf16", "f32"})

    # Main-model placement settings that Manual mode owns. They must not leak
    # from Unsloth's parent environment into llama-server and silently override
    # the command assembled from the current request. Draft-model placement is
    # intentionally separate and remains available to speculative decoding.
    _MANUAL_PLACEMENT_ENV_VARS = (
        "LLAMA_ARG_CPU_MOE",
        "LLAMA_ARG_N_CPU_MOE",
        "LLAMA_ARG_N_GPU_LAYERS",
        "LLAMA_ARG_TENSOR_SPLIT",
        "LLAMA_ARG_FIT",
        "LLAMA_ARG_FIT_TARGET",
        "LLAMA_ARG_FIT_CTX",
    )

    # Eligibility must reject every inherited placement value replay removes.
    _CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS = (
        *_MANUAL_PLACEMENT_ENV_VARS,
        "LLAMA_ARG_DEVICE",
        "LLAMA_ARG_MAIN_GPU",
        "LLAMA_ARG_SPLIT_MODE",
        "LLAMA_ARG_OVERRIDE_TENSOR",
    )

    # (binary, mtime, model, kv types) that aborted on --split-mode tensor this
    # process (#6415 geometry limit, e.g. MQA n_head_kv=1). Model-keyed so one
    # model's abort doesn't skip tensor for others; tensor is tried by default,
    # recorded only on a real abort.
    # KV-type-keyed too: since ggml-org/llama.cpp#23792 the type reaches the tensor
    # child rather than being rewritten to f16, so an abort can be specific to one
    # type. iq4_nl asserts on b10441 where q4_0 runs on the same binary and model
    # (ggml-org/llama.cpp#27116); keyed only by (binary, model) that would disable
    # tensor mode for the types that work.
    _tensor_split_abort_keys: set[tuple[str, int, str, tuple[str, str]]] = set()

    # (binary, mtime) that refused a quantized KV cache under --split-mode tensor.
    # Coarser than _tensor_split_abort_keys on purpose: the pre-b9455 rejection is a
    # missing capability of the BINARY, not of one model or type, so keying it per
    # model+pair would pay another doomed full load for each new model and each
    # q8_0 -> q4_0 switch. f16 still splits on such a binary, so this is consulted
    # only when an axis is actually quantized.
    _tensor_quant_kv_unsupported_binaries: set[tuple[str, int]] = set()

    @classmethod
    def _binary_key(cls, binary: Optional[str]) -> Optional[tuple[str, int]]:
        """(path, mtime_ns); ns mtime re-probes a same-second binary swap."""
        if not binary:
            return None
        try:
            mtime = Path(binary).stat().st_mtime_ns
        except OSError:
            mtime = 0
        return (binary, mtime)

    @classmethod
    def _record_tensor_quant_kv_unsupported(cls, binary: Optional[str]) -> None:
        """Remember a binary that cannot run a quantized KV cache in tensor mode."""
        key = cls._binary_key(binary)
        if key is not None:
            cls._tensor_quant_kv_unsupported_binaries.add(key)

    @classmethod
    def _tensor_quant_kv_unsupported_binary(
        cls,
        binary: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> bool:
        """True if this binary already refused a quantized KV cache in tensor mode
        AND this launch asks for one. A non-quantized pair is unaffected."""
        if not any(_kv_bytes_per_elem(t) < _kv_bytes_per_elem("f16") for t in cache_types):
            return False
        key = cls._binary_key(binary)
        return key is not None and key in cls._tensor_quant_kv_unsupported_binaries

    @classmethod
    def _tensor_split_cache_key(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> Optional[tuple[str, int, str, tuple[str, str]]]:
        """(path, mtime_ns, model, (type_k, type_v)) key; ns mtime re-probes a
        same-second binary swap. ``cache_types`` defaults to llama.cpp's own
        default pair, which is what a caller that sets no type gets."""
        if not binary or not model:
            return None
        try:
            mtime = Path(binary).stat().st_mtime_ns
        except OSError:
            mtime = 0
        k, v = cache_types
        return (binary, mtime, model, (k.strip().lower(), v.strip().lower()))

    @classmethod
    def _tensor_split_aborts(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> bool:
        """True if this (binary, model, KV types) aborted on --split-mode tensor
        this session. A different cache type is a different question, so it is
        tried rather than assumed broken."""
        key = cls._tensor_split_cache_key(binary, model, cache_types)
        return key is not None and key in cls._tensor_split_abort_keys

    @classmethod
    def _record_tensor_split_abort(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> None:
        """Remember a (binary, model, KV types) that aborts on --split-mode tensor."""
        key = cls._tensor_split_cache_key(binary, model, cache_types)
        if key is not None:
            cls._tensor_split_abort_keys.add(key)

    @staticmethod
    def _windows_pip_nvidia_dll_dirs(prefix: str) -> list[str]:
        """Return DLL dirs from pip-installed CUDA wheels under
        ``<prefix>/Lib/site-packages/`` so llama-server.exe can load
        ``cudart64_X.dll`` / ``cublas64_X.dll`` without a system CUDA toolkit.
        Mirrors the Linux ``nvidia/cu*/lib`` LD_LIBRARY_PATH block, covering the
        Windows wheel layouts seen in the wild:
          * ``nvidia/<pkg>/bin`` -- legacy modular wheels.
          * ``nvidia/<pkg>/bin/x86_64`` and ``.../bin/x64`` -- CUDA 13 layout
            for unsuffixed packages (#5106).
          * ``nvidia/<pkg>/Library/bin`` (and arch subdirs) -- conda repacks.
          * ``torch/lib`` -- PyTorch's CUDA-bundled wheel can ship
            ``cudart64_*.dll`` here; mirrors install_llama_prebuilt.py.

        Walks with ``Path.iterdir`` not ``glob.glob`` so it's safe against
        Windows paths containing ``[`` or ``]`` (valid in usernames)."""
        site_packages = Path(prefix) / "Lib" / "site-packages"
        out: list[str] = []
        seen: set[str] = set()

        def _add(path: Path) -> None:
            if not path.is_dir():
                return
            key = os.path.normcase(os.path.abspath(str(path)))
            if key in seen:
                return
            seen.add(key)
            out.append(str(path))

        nvidia_root = site_packages / "nvidia"
        if nvidia_root.is_dir():
            for pkg_dir in nvidia_root.iterdir():
                if not pkg_dir.is_dir():
                    continue
                # Arch-specific subdirs first so the explicit cudart64_X.dll
                # location wins over an empty sibling ``bin``.
                for sub in (
                    pkg_dir / "bin" / "x86_64",
                    pkg_dir / "bin" / "x64",
                    pkg_dir / "bin",
                    pkg_dir / "Library" / "bin" / "x86_64",
                    pkg_dir / "Library" / "bin" / "x64",
                    pkg_dir / "Library" / "bin",
                ):
                    _add(sub)
        _add(site_packages / "torch" / "lib")
        return out

    @staticmethod
    def _build_windows_path_dirs(binary_dir: str, prefix: str, cuda_path: str) -> list[str]:
        """Ordered PATH entries prepended so llama-server.exe resolves cudart /
        cublas DLLs: binary_dir, pip nvidia wheels, CUDA_PATH/bin, .../bin/x64.
        Extracted so test_windows_gpu_detection_mock tests the real logic. #5106."""
        path_dirs = [binary_dir]
        path_dirs.extend(LlamaCppBackend._windows_pip_nvidia_dll_dirs(prefix))
        if cuda_path:
            cuda_bin = os.path.join(cuda_path, "bin")
            if os.path.isdir(cuda_bin):
                path_dirs.append(cuda_bin)
            cuda_bin_x64 = os.path.join(cuda_path, "bin", "x64")
            if os.path.isdir(cuda_bin_x64):
                path_dirs.append(cuda_bin_x64)
        return path_dirs

    @staticmethod
    def _llama_server_env_for_binary(
        binary: str, *, use_system_rocm: bool = True
    ) -> dict[str, str]:
        """Build a subprocess env that lets llama-server resolve native libs.

        ``use_system_rocm=False`` skips the native-Linux system ROCm prepend.
        WSL's librocdxg prepend is independent and is not gated by this flag.
        """
        env = child_env_without_native_path_secret()
        # _llama_lib_dir resolves the llama-server symlink to the real build/bin.
        binary_dir = str(_llama_lib_dir(binary))

        if sys.platform == "win32":
            # Ordering: see _build_windows_path_dirs. #5106.
            path_dirs = LlamaCppBackend._build_windows_path_dirs(
                binary_dir,
                sys.prefix,
                os.environ.get("CUDA_PATH", ""),
            )
            existing_path = env.get("PATH", "")
            env["PATH"] = ";".join(path_dirs) + ";" + existing_path

            # ROCm: the prebuilt bundles rocblas.dll but NOT the Tensile
            # kernel files (rocblas/library/*.dat + *.hsaco); the DLL searches
            # <binary_dir>/rocblas/library/ which doesn't exist.
            _hip_path = os.environ.get("HIP_PATH", os.environ.get("ROCM_PATH", ""))
            if _hip_path:
                _rocblas_lib = os.path.join(_hip_path, "bin", "rocblas", "library")
                if os.path.isdir(_rocblas_lib):
                    env.setdefault("ROCBLAS_TENSILE_LIBPATH", _rocblas_lib)
        elif sys.platform == "darwin":
            # dyld ignores LD_LIBRARY_PATH, so the Linux branch below left the
            # child with no search path at all, while the installer's own
            # validation sets DYLD_LIBRARY_PATH and so never saw it (#8566).
            # A healthy prebuilt resolves via @loader_path and does not need
            # this; one with wrong install names dies in dyld without it.
            _dyld = _loader_path_var()
            env[_dyld] = _prepend_loader_dir(env.get(_dyld, ""), binary_dir)
        else:
            # Linux: LD_LIBRARY_PATH for shared libs next to the binary plus
            # CUDA runtime libs (libcudart, libcublas, etc.)
            import platform

            lib_dirs = []
            # WSL: system HIP before the bundle's (which segfaults on /dev/dxg).
            lib_dirs.extend(_wsl_system_rocm_lib_dirs())
            if lib_dirs:
                env.setdefault("HSA_ENABLE_DXG_DETECTION", "1")
            # Native Linux AMD: system ROCm libs before the bundle's HIP runtime,
            # which can be incompatible with the host amdkfd driver (#7233).
            if use_system_rocm and not LlamaCppBackend._prefers_bundle_only_rocm(binary):
                lib_dirs.extend(_native_linux_system_rocm_lib_dirs(binary_dir))
            lib_dirs.append(binary_dir)
            _arch = platform.machine()  # x86_64, aarch64, etc.

            # Pip-installed nvidia CUDA runtime libs. The prebuilt binary links
            # libcudart.so.13 / libcublas.so.13 which live here, not in
            # /usr/local/cuda.
            import glob as _glob

            for _nv_pattern in [
                os.path.join(sys.prefix, "lib", "python*", "site-packages", "nvidia", _sub, "lib")
                for _sub in ("cu*", "cudnn", "nvjitlink")
            ]:
                for _nv_dir in _glob.glob(_nv_pattern):
                    if os.path.isdir(_nv_dir):
                        lib_dirs.append(_nv_dir)

            for cuda_lib in [
                "/usr/local/cuda/lib64",
                f"/usr/local/cuda/targets/{_arch}-linux/lib",
                # Fallback CUDA compat paths (e.g. binary built with CUDA 12
                # where default /usr/local/cuda is CUDA 13+).
                "/usr/local/cuda-12/lib64",
                "/usr/local/cuda-12.8/lib64",
                f"/usr/local/cuda-12/targets/{_arch}-linux/lib",
                f"/usr/local/cuda-12.8/targets/{_arch}-linux/lib",
            ]:
                if os.path.isdir(cuda_lib):
                    lib_dirs.append(cuda_lib)
            existing_ld = env.get("LD_LIBRARY_PATH", "")
            new_ld = ":".join(lib_dirs)
            env["LD_LIBRARY_PATH"] = f"{new_ld}:{existing_ld}" if existing_ld else new_ld

        return env

    @classmethod
    def _clear_manual_placement_env(cls, env: dict[str, str]) -> None:
        """Remove inherited main-model placement owned by Manual mode."""
        for name in cls._MANUAL_PLACEMENT_ENV_VARS:
            env.pop(name, None)

    @classmethod
    def _clear_device_placement_env(cls, env: dict[str, str]) -> None:
        """Remove inherited device placement owned by an explicit ``gpu_ids``."""
        for name in ("LLAMA_ARG_DEVICE", "LLAMA_ARG_MAIN_GPU"):
            env.pop(name, None)

    @classmethod
    def _clear_split_placement_env(cls, env: dict[str, str]) -> None:
        """Remove an inherited split mode / ratio when the arch gate drops ours.

        These are the env spelling of --split-mode / --tensor-split, so stripping the
        tokens alone leaves the inherited value in force. It matters more here: a
        tensor split aborts a child with no visible device, and a narrowed set
        re-indexes the survivors so an inherited positional ratio lands on the wrong
        card."""
        for name in ("LLAMA_ARG_SPLIT_MODE", "LLAMA_ARG_TENSOR_SPLIT"):
            env.pop(name, None)

    @staticmethod
    def _select_gpus(
        model_size_bytes: int,
        gpus: list[tuple[int, int]],
        usable_fraction: Optional[float] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        per_device_overhead_bytes: int = 0,
        min_gpus: int = 1,
    ) -> tuple[Optional[list[int]], bool]:
        """Pick GPU(s) for a model from estimated VRAM and free memory.

        ``min_gpus`` (default 1, capped at ``len(gpus)``) keeps a downgraded
        tensor/multi-GPU request spread instead of collapsing to one card.

        ``model_size_bytes`` should include weights and estimated KV cache.
        ``usable_fraction`` (default ``_GPU_PIN_VRAM_FRACTION``) provides
        headroom for compute buffers, CUDA context, and other runtime
        overhead; callers lower it when MTP reserves VRAM for a draft model.
        ``total_by_idx`` (index -> total MiB) makes the headroom an ABSOLUTE
        ``(1 - fraction) * total`` per GPU instead of a fraction of free.
        ``per_device_overhead_bytes`` is the fixed layer-split cost per GPU beyond
        the first; a k-GPU pin must hold ``model + (k-1) * overhead`` or it can OOM
        a device after -ngl -1 (no --fit fallback). Single-GPU adds none.

        Returns (gpu_indices, use_fit):
          - ([1], False)       fits on 1 GPU at the headroom threshold
          - ([1, 2], False)    needs 2 GPUs
          - (None, True)       too large, let --fit handle it
        """
        if not gpus:
            return None, True

        min_gpus = max(1, min(min_gpus, len(gpus)))
        model_size_mib = model_size_bytes / (1024 * 1024)
        if usable_fraction is None:
            usable_fraction = _active_vram_fraction()
        overhead_mib = per_device_overhead_bytes / (1024 * 1024)

        # Per-GPU usable budget: free minus the reserve when total is known, else
        # the legacy free*frac (also covers a total-0 two-column probe).
        def _usable(idx: int, free_mib: int) -> float:
            t = total_by_idx.get(idx, 0) if total_by_idx else 0
            usable = _vram_usable_mib(free_mib, t, usable_fraction)
            return max(0.0, usable) if t > 0 else usable

        # Rank by usable budget (free - reserve), not raw free: a more-used large
        # card can have less usable room than a less-used small one.
        ranked = sorted(gpus, key = lambda g: _usable(g[0], g[1]), reverse = True)

        # Cap a downgraded multi-GPU request to the usable count so it doesn't pull
        # in a near-full card to hit min_gpus. No-op for the default min_gpus == 1.
        usable_count = sum(1 for idx, free_mib in ranked if _usable(idx, free_mib) > overhead_mib)
        min_gpus = max(1, min(min_gpus, usable_count or 1))

        # Try 1 GPU at the usable-VRAM threshold (only when one device is allowed).
        if min_gpus <= 1 and _usable(ranked[0][0], ranked[0][1]) >= model_size_mib:
            return [ranked[0][0]], False

        # Try N GPUs (most-free first); each past the first adds per-device overhead.
        # Require at least min_gpus devices before accepting a fit.
        cumulative = 0.0
        selected = []
        for idx, free_mib in ranked:
            selected.append(idx)
            cumulative += _usable(idx, free_mib)
            if (
                len(selected) >= min_gpus
                and cumulative >= model_size_mib + (len(selected) - 1) * overhead_mib
            ):
                return sorted(selected), False

        # Too large even for all GPUs; let --fit handle it
        logger.debug(
            "Model does not fit in available GPU memory, falling back to --fit",
            model_size_mib = round(model_size_mib, 2),
            ranked_gpus = ranked,
        )
        return None, True

    @staticmethod
    def _select_gpus_split_aware(
        model_size_bytes: int,
        gpus: list[tuple[int, int]],
        usable_fraction: Optional[float] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        per_device_overhead_bytes: int = 0,
        min_gpus: int = 1,
        split_extra_bytes: int = 0,
    ) -> tuple[Optional[list[int]], bool]:
        """``_select_gpus``, re-checked at the multi-device context-compute rate.

        The device count comes out of the footprint, so the first pass must price the
        compute buffer at the single-device rate -- but a layer split replicates a BIGGER
        one per card (see ``_CTX_COMPUTE_SPLIT_MULT``). ``split_extra_bytes`` is that
        per-device step (0 when llama.cpp declines pipeline parallelism): charge it and
        re-select once the count is known to be > 1, exact in one retry since the step is
        count-independent. The bigger overhead can cut ``_select_gpus``'s usable-card
        count to one, and a lone card is not a split, so a retry landing below two
        devices is re-priced without the delta. Still no fit returns (None, True) ->
        --fit on, i.e. CPU offload rather than a pin that OOMs at launch."""
        gpu_indices, use_fit = LlamaCppBackend._select_gpus(
            model_size_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes,
            min_gpus = min_gpus,
        )
        if use_fit or split_extra_bytes <= 0 or not gpu_indices or len(gpu_indices) < 2:
            return gpu_indices, use_fit
        retry_indices, retry_fit = LlamaCppBackend._select_gpus(
            model_size_bytes + split_extra_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes + split_extra_bytes,
            min_gpus = min_gpus,
        )
        if not retry_fit and retry_indices and len(retry_indices) >= 2:
            return retry_indices, retry_fit
        single, single_fit = LlamaCppBackend._select_gpus(
            model_size_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes,
            min_gpus = 1,
        )
        if not single_fit and single is not None and len(single) == 1:
            return single, False
        return retry_indices, retry_fit

    @staticmethod
    def _every_gpu_holds_reserve(usable_mib: Iterable[float], reserve_bytes: int) -> bool:
        """Whether every card in a layer-split subset can hold the reserve it replicates
        (flat per-device overhead + its own context-compute copy). A pooled budget cannot
        see this: in the sum a roomy card's spare VRAM covers a nearly full card's copy,
        and the small card OOMs at launch. Bites when the subset loop cannot start at
        one GPU (``_auto_min_gpus`` >= 2, set by every tensor -> layer downgrade);
        starting at one, the failed n-1 subset already bounds the smallest card from
        below by the reserve."""
        reserve_mib = reserve_bytes / (1024 * 1024)
        values = list(usable_mib)
        return bool(values) and all(usable >= reserve_mib for usable in values)

    @staticmethod
    def _cap_ctx_to_per_device_reserve(
        ctx: int,
        usable_mib: Iterable[float],
        reserve_bytes_fn: Callable[[int], int],
        min_ctx: int = 8192,
    ) -> int:
        """Largest context in [``min_ctx``, ``ctx``] whose replicated per-device reserve
        still fits the SMALLEST card of a layer-split subset; 0 when even ``min_ctx``
        does not. The reserve shrinks with the context, so a subset
        ``_every_gpu_holds_reserve`` turns down at the pooled context usually serves a
        lower one: 40000 + 2500 MiB free holds 31488, not the 4096 a drop would leave.
        Bisects the reserve, which is monotone in context on every branch but
        proportional on only some: deepseek4's flat indexer term makes a closed form
        answer 43341 on a 4000 MiB card, whose reserve there is 6048 MiB. The MiB
        comparison mirrors ``_every_gpu_holds_reserve``, so that gate accepts what this
        returns."""
        values = list(usable_mib)
        if not values or ctx < min_ctx:
            return 0
        smallest = min(values)
        lo, hi, best = min_ctx, ctx, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if reserve_bytes_fn(mid) / (1024 * 1024) <= smallest:
                best, lo = mid, mid + 1
            else:
                hi = mid - 1
        best = (best // 256) * 256  # same alignment _fit_context_to_vram uses
        return best if best >= min_ctx else 0

    # ── KV cache VRAM estimation ─────────────────────────────────────

    def _can_estimate_kv(self) -> bool:
        """True if we have enough GGUF metadata to estimate KV cache size."""
        if self._n_layers is None:
            return False
        # MLA: kv_lora_rank suffices (K-only cache).
        if self._kv_lora_rank is not None:
            return True
        # New-style: need explicit key AND value dimensions.
        if self._kv_key_length is not None and self._kv_value_length is not None:
            return True
        # Legacy: need embedding_length + a head count (scalar or per-layer).
        return self._embedding_length is not None and (
            self._n_kv_heads is not None
            or self._n_heads is not None
            or self._n_kv_heads_by_layer is not None
        )

    def _kv_layer_weights(
        self,
        n_ctx: int,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
        cache_type_kv: Optional[str] = None,
    ) -> "list[int]":
        """Relative KV size per layer, or [] when the shape is uniform/unknown.

        Only the RATIOS matter: the planner scales this to the byte-accurate total
        it already has, so it never becomes a second, competing estimate of the
        cache size. It exists because the total says nothing about WHERE the big
        caches land, which on a multi-device split is the whole question -- a
        sliding-window layer holds a window's worth of cells while a
        full-attention layer holds the entire context, ~100x more at 128K against
        a 1K window (llama-kv-cache-iswa.cpp:69-104).

        The cell geometry MUST be the one the total was priced at, so the launch
        knobs that change it travel too: ``--swa-full`` collapses the two cache
        sizes into one, and the compact SWA allowance is per-slot plus a
        micro-batch and padded (_estimate_kv_cache_bytes path 3), not a bare
        ``min(window, n_ctx)``. Pricing a ratio the total does not have moves cache
        bytes onto the wrong card, a per-device shortfall under the ``--fit off``
        the plan pins.

        Trailing layers that reuse an earlier layer's cache get weight 0: Gemma 3n
        / Gemma 4 set ``n_layer_kv_from_start = n_layer_all - shared_kv_layers``
        and ``llama_hparams::has_kv`` is false past it (llama-hparams.cpp:275-279),
        so they allocate nothing. Giving them weight would spread the same total
        over layers that hold no cache.

        Only ever describes _estimate_kv_cache_bytes PATH 3, which picks its path
        before it looks at the window. The earlier paths price a different
        quantity: path 1 (MLA) caches one compressed K latent per layer with NO V
        and no window/full distinction, path 2 (hybrid recurrent) caches only 1 in
        full_attention_interval layers. A window-shaped vector against either is a
        different model of the cache, not an approximation, so answer [] and let
        the planner abstain. Reachable, not hypothetical: dots3note reads
        KV_LORA_RANK and ATTENTION_SLIDING_WINDOW(_PATTERN) in the same loader.

        Omits the per-slot context-checkpoint extra deliberately: llama.cpp's
        checkpoints are HOST buffers (common/common.cpp:2282-2297), so no VRAM
        total this is scaled against contains them either.
        """
        pattern = self._sliding_window_pattern
        n_layers = self._n_layers or 0
        if not pattern or n_layers <= 0:
            return []
        # Mirror _estimate_kv_cache_bytes' branch order: anything it returns before
        # path 3 is a shape this vector cannot describe.
        if self._kv_lora_rank is not None:
            return []
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            return []
        swa = self._sliding_window or 0
        if swa <= 0:
            return []
        n_kv = self._n_kv_heads or self._n_heads or 1
        key_len = self._kv_key_length or 0
        val_len = self._kv_value_length or 0
        if not key_len or not val_len:
            return []
        key_len_swa = self._kv_key_length_swa or key_len
        val_len_swa = self._kv_value_length_swa or val_len
        # Same floor as _estimate_kv_cache_bytes: a bad GGUF cannot zero the vector.
        n_layers_kv = max(1, n_layers - (self._shared_kv_layers or 0))
        # Same cell layout the byte total was computed with.
        slots, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        full_cells = max(1, cells_per_stream * streams)
        if swa_full:
            swa_cells = full_cells
        else:
            ubatch = max(0, int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch))
            swa_limit = int(swa) * (slots if kv_unified else 1) + ubatch
            swa_cells = max(1, _pad_kv_cells(min(cells_per_stream, swa_limit)) * streams)
        # With flash attention OFF llama.cpp cannot use a ragged V cache: every
        # layer's V is padded to hparams.n_embd_v_gqa_max() over the WHOLE model,
        # which is what _estimate_kv_cache_bytes charges (_max_kv_value_width). The
        # V half goes constant while K stays per-layer, so an unpadded vector
        # prices a ratio the total does not have. Not an edge case: load_model pins
        # planned_flash_attn = False unconditionally (llama_cpp.py:16690), so the
        # padded branch is the only one the total ever takes. bpe_v is floored at
        # f16 for a quantised cache, and with V constant that asymmetry moves the
        # ratio too, so carry both rather than cancelling one.
        bpe_k = _kv_bytes_per_elem(cache_type_kv)
        bpe_v = bpe_k if flash_attn else max(bpe_k, _kv_bytes_per_elem("f16"))
        padded_v_width = None if flash_attn else self._max_kv_value_width(val_len, val_len_swa)
        weights: list[int] = []
        for layer_idx in range(n_layers):
            if layer_idx >= n_layers_kv:
                weights.append(0)
                continue
            layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
            is_swa = layer_idx < len(pattern) and bool(pattern[layer_idx])
            key_bytes = layer_n_kv * (key_len_swa if is_swa else key_len) * bpe_k
            value_bytes = (
                layer_n_kv * (val_len_swa if is_swa else val_len)
                if padded_v_width is None
                else padded_v_width
            ) * bpe_v
            width = key_bytes + value_bytes
            weights.append(int(width * (swa_cells if is_swa else full_cells)))
        return weights if any(weights) else []

    def _kv_heads_for_layer(self, layer_idx: int, fallback: int) -> int:
        if self._n_kv_heads_by_layer is not None and layer_idx < len(self._n_kv_heads_by_layer):
            return self._n_kv_heads_by_layer[layer_idx]
        return fallback

    def _recurrent_state_bytes(self, n_parallel: int = 1) -> int:
        """VRAM for the conv + recurrent state of linear-attention layers.

        Hybrids pair an MLA/attention cache with llama_memory_recurrent, which
        allocates per recurrent layer and per sequence, always f32, offloaded
        beside the KV cache. Unlike KV this does not scale with context, so it
        is the whole reservation at short contexts and the bisection in
        _fit_context_to_vram cannot shrink it away.

        Sizes follow llama_hparams::n_embd_r/n_embd_s. This helper covers the
        per-layer KDA layout; Hybrid Mamba uses its architecture-level interval
        and group count in _mamba_recurrent_state_bytes.
        """
        if not self._n_kv_heads_by_layer or not self._n_layers or not self._kda_head_dim:
            return 0
        n_recurrent = sum(1 for i in range(self._n_layers) if self._kv_heads_for_layer(i, 1) == 0)
        if n_recurrent == 0:
            return 0
        head_dim, n_head = self._kda_head_dim, self._n_heads or 1
        d_conv = self._ssm_conv_kernel or 4
        n_embd_r = 3 * max(0, d_conv - 1) * n_head * head_dim
        n_embd_s = head_dim * head_dim * n_head
        return int(n_recurrent * (n_embd_r + n_embd_s) * 4 * max(1, n_parallel))

    def _target_kv_excludes_nextn(self) -> bool:
        """Whether this model's TARGET KV cache skips the embedded MTP blocks.

        See _TARGET_KV_EXCLUDES_NEXTN_ARCHS for why this is per-architecture
        rather than a property of the nextn key.

        A hybrid recurrent header answers yes without consulting that list. Every
        hybrid Mamba architecture llama.cpp accepts a nextn key from -- Qwen3-Next,
        Qwen3.5, Qwen3.5-MoE, Nemotron-H -- is filtered at llama-model.cpp:2289,
        and the recurrent half is sized on n_layer() regardless
        (llama-memory-recurrent.cpp:29), so the ssm dims are sufficient evidence
        and a GGUF whose header names an arch this build has never heard of still
        gets the right answer. Everything else must be named, so an unreadable or
        unknown architecture keeps every block.
        """
        if not self._nextn_predict_layers:
            return False
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            return True
        arch = getattr(self, "_architecture", None)
        return bool(arch) and str(arch).strip().lower() in _TARGET_KV_EXCLUDES_NEXTN_ARCHS

    def _mamba_recurrent_state_bytes(
        self,
        n_parallel: int = 1,
        n_rs_seq: int = 0,
    ) -> int:
        """VRAM for Hybrid Mamba conv/SSM state, including rollback copies.

        llama.cpp allocates one f32 recurrent state per parallel sequence. MTP
        additionally keeps ``--spec-draft-n-max`` rollback states per sequence
        while verifying draft tokens, so its allocation is ``1 + n_rs_seq``
        times the base state.
        """
        n_layers_raw = getattr(self, "_n_layers", None)
        d_inner_raw = getattr(self, "_ssm_inner_size", None)
        d_state_raw = getattr(self, "_ssm_state_size", None)
        n_group_raw = getattr(self, "_ssm_group_count", None)
        d_conv_raw = getattr(self, "_ssm_conv_kernel", None)
        fai_raw = getattr(self, "_full_attention_interval", None)
        if not all(
            value is not None
            for value in (
                n_layers_raw,
                d_inner_raw,
                d_state_raw,
                n_group_raw,
                d_conv_raw,
                fai_raw,
            )
        ):
            return 0
        # Excludes the embedded MTP blocks, as _estimate_kv_cache_bytes does and
        # for the same reason: llama.cpp keeps them out of the target's n_layer.
        n_layers = max(
            0,
            int(n_layers_raw or 0) - int(getattr(self, "_nextn_predict_layers", None) or 0),
        )
        fai = int(fai_raw or 0)
        n_attn = -(-n_layers // fai) if fai > 0 else n_layers
        n_recurrent = max(0, n_layers - n_attn)
        if n_recurrent == 0:
            return 0
        d_inner = int(d_inner_raw or 0)
        d_state = int(d_state_raw or 0)
        n_group = int(n_group_raw or 0)
        d_conv = int(d_conv_raw or 0)
        n_embd_r = max(0, d_conv - 1) * (d_inner + 2 * n_group * d_state)
        n_embd_s = d_state * d_inner
        return int(
            n_recurrent * (n_embd_r + n_embd_s) * 4 * max(1, n_parallel) * max(1, 1 + n_rs_seq)
        )

    def _legacy_head_dim(self) -> int:
        """Head-dim fallback for GGUFs without explicit key/value dims. Reached
        only via the legacy branch of _can_estimate_kv(), so _embedding_length
        is non-None here."""
        return self._embedding_length // self._n_heads if self._n_heads else 128  # type: ignore[operator]

    def _max_kv_value_width(
        self,
        default_len: int,
        swa_len: Optional[int] = None,
    ) -> int:
        """llama.cpp's hparams.n_embd_v_gqa_max() over every model layer."""
        n_layers = self._n_layers or 1
        n_kv = self._n_kv_heads or self._n_heads or 1
        if self._sliding_window_pattern is None:
            max_len = max(default_len, swa_len or default_len)
            return max(
                self._kv_heads_for_layer(layer_idx, n_kv) * max_len for layer_idx in range(n_layers)
            )
        return max(
            self._kv_heads_for_layer(layer_idx, n_kv)
            * (
                (swa_len or default_len)
                if (
                    layer_idx < len(self._sliding_window_pattern)
                    and self._sliding_window_pattern[layer_idx]
                )
                else default_len
            )
            for layer_idx in range(n_layers)
        )

    def _estimate_kv_cache_bytes(
        self,
        n_ctx: int,
        cache_type_kv: Optional[str] = None,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        ctx_checkpoints: int = 0,
        flash_attn: bool = True,
    ) -> int:
        """Estimate KV cache VRAM for a given context length.

        5-path architecture-aware estimation:
          1. MLA      -- compressed KV latent + RoPE, K-only (no separate V)
          2. Hybrid   -- only attention layers need KV (Mamba layers don't)
          3. SWA      -- sliding-window layers use compact or full cache cells
          4. GQA      -- standard full KV with explicit key/value dimensions
          5. Legacy   -- fallback using embed // n_heads

        Server-flag knobs (mirror llama-server's CLI):
          swa_full        -- --swa-full: SWA layers cache full n_ctx (path 3->4).
          n_parallel      -- --parallel slots: controls per-slot stream padding.
          kv_unified      -- --kv-unified: one shared stream vs one per slot.
          n_ubatch        -- --ubatch-size: SWA cache's processing headroom.
          ctx_checkpoints -- --ctx-checkpoints: N SWA snapshots per slot.
          flash_attn      -- False pads variable-width V tensors to the model max.

        Returns 0 if metadata is insufficient.
        """
        if not self._can_estimate_kv() or n_ctx <= 0:
            return 0

        # GGUF block_count includes embedded MTP blocks, and llama.cpp keeps
        # those out of the target context for SOME architectures only -- see
        # _TARGET_KV_EXCLUDES_NEXTN_ARCHS. Where it does, their KV lives in the
        # draft context and _mtp_draft_kv_bytes prices it separately; where it
        # does not, the target cache still allocates them and subtracting here
        # would under-reserve.
        n_layers = self._n_layers  # type: ignore[assignment]
        if self._target_kv_excludes_nextn():
            n_layers = max(1, n_layers - (self._nextn_predict_layers or 0))
        # Gemma 3n / Gemma 4 reuse earlier KV in the last ``shared_kv_layers``
        # blocks (no cache). Floor at 1 so a bad GGUF can't zero out KV.
        shared = self._shared_kv_layers or 0
        n_layers_kv = max(1, n_layers - shared)
        n_kv = self._n_kv_heads or self._n_heads or 1  # type: ignore[assignment]

        # Bytes per element depends on KV cache quantization
        bpe_k = _kv_bytes_per_elem(cache_type_kv)
        # The automatic FA-off retry rewrites an invalid quantized V cache to
        # f16. Pricing that viable retry here avoids under-reserving it.
        bpe_v = bpe_k if flash_attn else max(bpe_k, _kv_bytes_per_elem("f16"))

        slots, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        total_cells = cells_per_stream * streams
        ubatch = max(
            0,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )

        # Path 1: MLA (DeepSeek-V2/V3, GLM-4.7, GLM-5, Kimi-K2.5)
        # One compressed KV latent per token/layer (shared across heads); V is
        # reconstructed from it, no separate V cache. key_length = kv_lora_rank
        # + rope_dim. MLA GGUFs set head_count_kv=1; default to 1 if absent to
        # avoid falling back to n_heads (e.g. 128 for DeepSeek-V3) which 128x's.
        if self._kv_lora_rank is not None:
            n_kv_mla = self._n_kv_heads or 1
            rope_dim = self._key_length_mla or 64
            key_len = self._kv_key_length or (self._kv_lora_rank + rope_dim)
            # Hybrid MLA (Kimi-K3): head_count_kv is a per-layer array whose KDA
            # linear-attention layers are 0 and hold a constant-size state instead
            # of a growing cache. Only the non-zero layers allocate KV, so counting
            # every block overstates it by the hybrid ratio (93 blocks vs 24 real
            # ones is 3.9x, or 78 GiB of phantom cache at 1M context) and shrinks
            # the auto-fit context for no reason. Uniform MLA keeps n_layers_kv.
            n_mla_layers = n_layers_kv
            if self._n_kv_heads_by_layer:
                attn = sum(
                    1 for i in range(n_layers_kv) if self._kv_heads_for_layer(i, n_kv_mla) > 0
                )
                n_mla_layers = max(1, attn)
            return int(
                n_mla_layers * total_cells * n_kv_mla * key_len * bpe_k
            ) + self._recurrent_state_bytes(n_parallel)

        key_len = self._kv_key_length
        val_len = self._kv_value_length

        # Path 2: Hybrid Mamba/Attention (Qwen3.5-27B, Qwen3.5-35B-A3B)
        # Only 1 in N layers is attention; the rest are Mamba (no KV cache).
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            fai = self._full_attention_interval
            n_attn = -(-n_layers // fai) if fai > 0 else n_layers  # ceiling division
            recurrent = self._mamba_recurrent_state_bytes(n_parallel)
            if key_len is not None and val_len is not None:
                v_width = n_kv * val_len if flash_attn else self._max_kv_value_width(val_len)
                return (
                    int(n_attn * total_cells * (n_kv * key_len * bpe_k + v_width * bpe_v))
                    + recurrent
                )
            head_dim = self._legacy_head_dim()
            return int(n_attn * total_cells * n_kv * 2 * head_dim * bpe_k) + recurrent

        # Path 3: Sliding window (Gemma 2/3/3n/4, gpt-oss, Cohere2 ...). Pattern
        # from the resolver; if absent, falls through to the legacy 1/4-global
        # heuristic. --parallel N accounting (verified against llama-server):
        # non-SWA cells total n_ctx across streams. Compact SWA adds one processing
        # micro-batch to the window allowance and pads to 256 cells; unified mode
        # holds all slots in one stream, while non-unified mode has one stream per
        # slot. --swa-full expands SWA to each stream's full context.
        if (
            self._sliding_window is not None
            and self._sliding_window > 0
            and key_len is not None
            and val_len is not None
        ):
            swa = self._sliding_window
            if swa_full:
                swa_cells_total = total_cells
            else:
                swa_limit = swa * (slots if kv_unified else 1) + ubatch
                swa_cells_per_stream = min(cells_per_stream, swa_limit)
                swa_cells_per_stream = _pad_kv_cells(swa_cells_per_stream)
                swa_cells_total = swa_cells_per_stream * streams
            key_len_swa = self._kv_key_length_swa or key_len
            val_len_swa = self._kv_value_length_swa or val_len
            padded_v_width = None if flash_attn else self._max_kv_value_width(val_len, val_len_swa)
            if self._sliding_window_pattern is not None:
                global_bytes = 0.0
                swa_bytes = 0.0
                checkpoint_extra_per_slot = 0.0
                # Only layers that allocate their own KV; trailing shared layers
                # reuse earlier caches.
                for layer_idx in range(n_layers_kv):
                    layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
                    is_swa = (
                        layer_idx < len(self._sliding_window_pattern)
                        and self._sliding_window_pattern[layer_idx]
                    )
                    layer_key_bytes = layer_n_kv * (key_len_swa if is_swa else key_len) * bpe_k
                    layer_value_bytes = (
                        layer_n_kv * (val_len_swa if is_swa else val_len)
                        if padded_v_width is None
                        else padded_v_width
                    ) * bpe_v
                    layer_kv_bytes = layer_key_bytes + layer_value_bytes
                    if is_swa:
                        swa_bytes += swa_cells_total * layer_kv_bytes
                        if ctx_checkpoints > 0 and not swa_full:
                            checkpoint_extra_per_slot += ctx_checkpoints * swa * layer_kv_bytes
                    else:
                        global_bytes += total_cells * layer_kv_bytes
                return int(global_bytes + swa_bytes + slots * checkpoint_extra_per_slot)
            n_global = max(1, n_layers_kv // 4)
            n_swa = n_layers_kv - n_global
            global_v_width = n_kv * val_len if padded_v_width is None else padded_v_width
            swa_v_width = n_kv * val_len_swa if padded_v_width is None else padded_v_width
            kv_per_token = n_kv * key_len * bpe_k + global_v_width * bpe_v
            kv_per_token_swa = n_kv * key_len_swa * bpe_k + swa_v_width * bpe_v
            global_bytes = n_global * total_cells * kv_per_token
            swa_bytes = n_swa * swa_cells_total * kv_per_token_swa
            checkpoint_extra_per_slot = (
                ctx_checkpoints * n_swa * swa * kv_per_token_swa
                if ctx_checkpoints > 0 and not swa_full
                else 0.0
            )
            return int(global_bytes + swa_bytes + slots * checkpoint_extra_per_slot)

        # Path 4: Standard GQA with explicit key/value dimensions
        if key_len is not None and val_len is not None:
            padded_v_width = None if flash_attn else self._max_kv_value_width(val_len)
            bytes_per_cell = 0.0
            for layer_idx in range(n_layers_kv):
                layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
                v_width = layer_n_kv * val_len if padded_v_width is None else padded_v_width
                bytes_per_cell += layer_n_kv * key_len * bpe_k + v_width * bpe_v
            return int(total_cells * bytes_per_cell)

        # Path 5: Legacy fallback (old GGUFs without explicit dimensions)
        head_dim = self._legacy_head_dim()
        return int(2 * n_kv * head_dim * n_layers_kv * total_cells * bpe_k)

    def _draft_backend_for(self, drafter_path: str) -> Optional["LlamaCppBackend"]:
        """Lightweight backend with a drafter GGUF's metadata, to size its own KV
        via _estimate_kv_cache_bytes. Cached per path; None if unreadable."""
        cache = getattr(self, "_draft_backend_cache", None)
        if cache is not None and cache[0] == drafter_path:
            return cache[1]
        db: Optional[LlamaCppBackend] = None
        try:
            db = LlamaCppBackend.__new__(LlamaCppBackend)
            for attr in (
                "_context_length",
                "_n_layers",
                "_n_kv_heads",
                "_n_heads",
                "_embedding_length",
                "_kv_key_length",
                "_kv_value_length",
                "_kv_lora_rank",
                "_sliding_window",
                "_sliding_window_pattern",
                "_ssm_inner_size",
                "_ssm_state_size",
                "_ssm_group_count",
                "_ssm_conv_kernel",
                "_full_attention_interval",
                "_key_length_mla",
                "_n_kv_heads_by_layer",
                "_kv_key_length_swa",
                "_kv_value_length_swa",
                "_shared_kv_layers",
                "_nextn_predict_layers",
            ):
                setattr(db, attr, None)
            db._model_identifier = "mtp-draft"
            db._read_gguf_metadata(drafter_path)
        except Exception as e:  # unreadable drafter -> caller falls back
            logger.debug(f"Could not read drafter GGUF for MTP budget: {e}")
            db = None
        self._draft_backend_cache = (drafter_path, db)
        return db

    def _mtp_draft_kv_bytes(
        self,
        n_ctx: int,
        *,
        drafter_path: Optional[str] = None,
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        n_parallel: int = 1,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """Draft KV cache bytes at n_ctx, sized from GGUF dims (K and V types are
        independent). Separate drafter (Gemma): its own KV via _estimate_kv_cache_bytes
        at the heavier type. Embedded head (Qwen): nextn_predict_layers attention
        layers from the main dims. None when dims are missing (flat fallback)."""
        if n_ctx <= 0:
            return None
        bpe_k = _kv_bytes_per_elem(draft_cache_type_k)
        bpe_v = _kv_bytes_per_elem(draft_cache_type_v)
        if drafter_path:
            db = self._draft_backend_for(drafter_path)
            if db is None or not db._can_estimate_kv():
                return None
            # Gemma 4 assistant layers share the target context's final global
            # and SWA KV tensors, so only the drafter weights add memory.
            if getattr(db, "_architecture", None) == "gemma4-assistant":
                return 0
            heavier = draft_cache_type_k if bpe_k >= bpe_v else draft_cache_type_v
            # The drafter uses the main model's slot and stream layout, so its
            # compact SWA and per-stream padding must follow the same settings.
            kv = db._estimate_kv_cache_bytes(
                n_ctx,
                heavier,
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )
            return kv if kv > 0 else None
        nextn = self._nextn_predict_layers or 0
        n_kv = self._n_kv_heads or self._n_heads
        k_len = self._kv_key_length
        v_len = self._kv_value_length
        if not (nextn and n_kv and k_len and v_len):
            return None
        # The embedded MTP head is one draft layer, so a quantized draft KV can't
        # amortize its overhead and fits *less* context than f16 (llama.cpp#24102).
        # Floor it at f16: a quantized override is priced as f16, f32 keeps its 4
        # bytes. The separate-drafter branch is multi-layer, so it keeps its type.
        f16_bpe = _kv_bytes_per_elem("f16")
        bpe_k = max(bpe_k, f16_bpe)
        bpe_v = max(bpe_v, f16_bpe)
        _, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        v_width = n_kv * v_len
        if not flash_attn:
            v_width = self._max_kv_value_width(
                v_len,
                self._kv_value_length_swa,
            )
        return int(nextn * (n_kv * k_len * bpe_k + v_width * bpe_v) * cells_per_stream * streams)

    def _cpu_resident_draft_bytes(
        self,
        n_ctx: int,
        *,
        drafter_path: Optional[str],
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        n_parallel: int = 1,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """Host-RAM footprint of a SEPARATE drafter pinned to the CPU (``-ngld 0``).

        The VRAM budget drops such a drafter, and rightly: none of it is on the
        GPU. The load-mode fit asks the other question -- is the whole load
        resident without demand paging -- and there the bytes have not gone
        anywhere, they have moved to host RAM. llama.cpp carries the process-wide
        load mode into the draft model: ``common_base_params_to_speculative``
        starts from ``result = params`` and overrides only devices/model/
        n_gpu_layers, and ``--load-mode none`` clears ``use_mmap``
        (llama-model-loader.cpp), so the draft GGUF becomes a real anonymous
        allocation rather than an evictable file mapping. Charging it is the same
        reasoning that keeps a CPU-pinned projector in the footprint.

        0 when no separate drafter is CPU-pinned. ``None`` when the drafter is
        there but cannot be priced, so the caller abstains instead of claiming a
        fit that is short a whole draft GGUF.
        """
        if not drafter_path:
            return 0
        try:
            weights = self._get_gguf_size_bytes(drafter_path)
        except Exception:
            weights = 0
        if weights <= 0:
            return None
        kv = self._mtp_draft_kv_bytes(
            n_ctx,
            drafter_path = drafter_path,
            draft_cache_type_k = draft_cache_type_k,
            draft_cache_type_v = draft_cache_type_v,
            n_parallel = n_parallel,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            flash_attn = flash_attn,
        )
        if kv is None:
            return None
        # The drafter has a llama_context of its own, so its decode graph is allocated
        # wherever it runs -- here, the host. _soft_overhead charges that constant only
        # while _mtp_reserves_gpu, which is False for exactly this placement.
        return int(weights) + max(0, int(kv)) + self._MTP_DRAFT_COMPUTE_BYTES

    def _estimate_mtp_overhead_bytes(
        self,
        n_ctx: int,
        *,
        spec_draft_n_max: int = 0,
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        drafter_path: Optional[str] = None,
        draft_weights_bytes: int = 0,
        n_parallel: int = 1,
        mtp_keeps_target_ctx: bool = True,
        target_rollback: bool = True,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """MTP draft reserve at ``n_ctx`` = draft KV (grows with ctx) + separate-
        drafter weights + target verification state. MLA duplicates the target
        KV context, while Hybrid Mamba adds recurrent rollback copies. The other
        verify buffers ride in the ctx-fit headroom (no tuned constant). None when
        the draft KV can't be sized (caller keeps the flat fallback).
        ``draft_weights_bytes`` is the drafter file size (0 for embedded).
        ``mtp_keeps_target_ctx`` is True for MTP draft modes (which keep the
        duplicated target context) and False for separate-drafter spec modes
        (draft-simple/draft-eagle3), which do not. ``target_rollback`` is the
        wider set: every draft-model type llama.cpp gives the target n_rs_seq for
        (draft-mtp/eagle3/dflash/dspark), which is all of them but draft-simple.
        Both default to charging, so an unsure caller over-reserves."""
        draft_kv = self._mtp_draft_kv_bytes(
            n_ctx,
            drafter_path = drafter_path,
            draft_cache_type_k = draft_cache_type_k,
            draft_cache_type_v = draft_cache_type_v,
            n_parallel = n_parallel,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            flash_attn = flash_attn,
        )
        weights = max(0, draft_weights_bytes)
        # MLA models (GLM-5.x, DeepSeek, Kimi-K2) under MTP keep a *second* full copy
        # of the target model's KV context for draft verification -- llama.cpp's
        # `ctx_tgt=yes` -- allocated at f16 regardless of the main cache type. It is
        # ~the main KV again and dwarfs the embedded draft head (GLM-5.2 @ 1M ctx:
        # a ~2 GiB head next to a ~89 GiB target copy), so omitting it lets auto-fit
        # pick a context that fits on paper but OOMs cublasCreate at the first
        # decode. Gated on both MLA (kv_lora_rank present) and the engaged mode
        # actually being MTP: non-MLA MTP (Qwen/Gemma) keeps no such copy, and the
        # separate-drafter spec modes (draft-simple/draft-eagle3) load a small
        # distinct drafter with its own KV -- already counted in draft_kv/weights --
        # rather than duplicating the target, so they must not be charged for it.
        target_ctx_copy = 0
        if mtp_keeps_target_ctx and self._kv_lora_rank is not None:
            target_ctx_copy = self._estimate_kv_cache_bytes(
                n_ctx,
                "f16",
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )
        # Hybrid Mamba targets keep one recurrent state in the normal target
        # context, counted by _estimate_kv_cache_bytes. Verification adds one
        # rollback copy per drafted token, in the TARGET context, so a separate
        # drafter file pays it exactly like the embedded head: ``target_rollback``
        # decides, not ``drafter_path`` (see _TARGET_ROLLBACK_SPEC_TYPES). The
        # dominant hidden cost on Qwen3.5/3.8 at multiple parallel slots.
        target_recurrent_copies = 0
        if target_rollback and spec_draft_n_max > 0:
            base_recurrent = self._mamba_recurrent_state_bytes(n_parallel)
            target_recurrent_copies = base_recurrent * spec_draft_n_max
        if draft_kv is None:
            # KV unsized (exotic/remote drafter): still reserve known weights + any
            # MLA target copy so a large config can't launch over budget (the small
            # unsized draft KV rides in the cushion). Nothing known -> None, so the
            # caller keeps the flat fallback.
            total = weights + target_ctx_copy + target_recurrent_copies
            return total if total > 0 else None
        return draft_kv + weights + target_ctx_copy + target_recurrent_copies

    _DEFAULT_N_UBATCH = _DEFAULT_LLAMA_N_UBATCH
    _COMPUTE_BUFFER_SAFETY = 1.15  # upper-bound margin on the compute-buffer estimate
    # Soft VRAM the modeled terms omit; charged to the fit budget on tight tiers (#6682).
    _CUDA_CONTEXT_RESERVE_BYTES = 320 * 1024 * 1024  # CUDA ctx + cuBLAS workspace (~330 MiB)
    _MMPROJ_VRAM_SAFETY = 1.4  # mmproj worst-case buffer vs file size (runtime ~1.3x)
    # Context the projector's residency is priced at. The placement loop shrinks the
    # context to this floor long before it would spill a layer, so this is the length
    # at which "does it fit" means "does every layer stay on the GPU".
    _MMPROJ_FIT_FLOOR_CTX = 8192
    _MTP_DRAFT_COMPUTE_BYTES = 224 * 1024 * 1024  # MTP draft decode graph beyond its KV
    # Draft depth to budget when the extras own the spec block and the probe cannot
    # read the build's own default off its --help. Shipped values are 3
    # (common_params_speculative_draft::n_max) and 16; take the deeper, since the
    # Hybrid Mamba rollback copies scale by this and under-reserving them OOMs the
    # load while over-reserving only costs context. Zero cost on any other model,
    # where the recurrent state is nil.
    _UNKNOWN_SPEC_DRAFT_N_MAX = 16
    # The flash-attn KQ mask + attention scratch grow ~linearly with context; the flat
    # _estimate_compute_buffer_bytes term only covers ctx -> 0. The per-token rate
    # depends on the KV cache type: a QUANTIZED cache (q8_0/q5/q4/iq4) needs a
    # context-sized dequant scratch that scales with n_embd, measured at 0.74-2.02 x
    # n_embd across Qwen3.5/3.6 (2B/4B/9B/27B) and Gemma-4 (12B/31B) at q8_0; an
    # f16/bf16/f32 cache skips the dequant and pays only the KQ mask, a flat n_ubatch*2
    # bytes per context token regardless of n_embd (measured 1024 B/tok on Qwen-9B and
    # Gemma-31B alike). So Qwen3.5-4B at 256k is 1.30 GiB at q8_0 vs 0.31 GiB at f16.
    # 2.25 covers the worst quantized case (Qwen3.5-4B, ~2.0x) plus the under-modeled
    # flat base; the mask safety covers the f16 base gap. Without this term, tight tiers
    # at extreme context over-pin and spill to CPU (the 3% cushion is only ~0.25 GiB on
    # an 8 GB card, far below the ~1-2.4 GiB quantized buffer at 256k): e.g. Qwen3.5-4B
    # Q4 at 256k needs ~8.5 GiB on a real 8 GB card (weights 2.4 + KV 4.3 + compute 1.3
    # + CUDA ctx) -> CPU spill; with this reserve the auto context caps to ~210k, fits.
    _CTX_COMPUTE_BYTES_PER_EMBD = 2.25  # quantized KV, regular attention (dequant scratch)
    _CTX_COMPUTE_BYTES_PER_EMBD_MLA = 1.25  # quantized KV, MLA (compressed attn: measured 0.94x)
    _CTX_COMPUTE_F16_MASK_SAFETY = 1.5  # f16/bf16/f32 KV: KQ mask only (n_ubatch*2 B/tok)
    # Per-device f16 ctx-linear rate steps 4x once the model spans >1 device under
    # `-sm layer`: pipeline parallelism sets the ggml scheduler's n_copies to
    # GGML_SCHED_MAX_COPIES == 4, and the [n_kv, n_ubatch] f16 KQ mask is a
    # GGML_TENSOR_FLAG_INPUT, so 1 live copy becomes 4. Hence a step on "is split", not
    # a ramp in device count: measured 2.00 B/tok/ubatch on 1 GPU and 8.00 on 2-8 GPUs,
    # architecture- and --parallel-independent. Charging 1x on a split under-reserves
    # 2.67x (= 8/(2*1.5)). llama.cpp declines it in _pipeline_parallel_disabled_by_args.
    _CTX_COMPUTE_SPLIT_MULT = 4
    # DeepSeek-V4 (deepseek4): its lightning indexer + sparse attention reserve a large
    # context-scaling compute buffer the rates above miss (present even with an f16
    # cache). Measured on UD-Q4_K_XL (ub=512): ~2 GiB at 16k -> ~65.5 GiB at 1M. Without
    # it auto-fit commits the full 1M train context, OOMs the reserve, and spills to CPU.
    _DSV4_CTX_COMPUTE_FLAT_BYTES = 2 * 1024**3  # ctx-independent indexer scratch
    _DSV4_CTX_COMPUTE_BYTES_PER_TOK = 72000  # per token at ub=512 (~72 GiB at 1M)

    # Inkling (inkling): with the reserve fix in the bundled llama.cpp (full-cache
    # reserve context reports the whole cache as position-contiguous, so the
    # worst-case graph is the banded flash path instead of the dense-bias
    # fallback), the ctx-linear compute term is just the banded KQ-mask cont:
    # measured on UD-IQ1_S (ub=512) 64K -> 1M total-VRAM slope of 50.6 KiB/tok,
    # of which 45,056 B/tok is KV -> ~5.6 KiB/tok compute. 8192 adds ~1.5x
    # headroom. (Pre-fix builds reserved the dense fallback at ~402 KiB/tok and
    # could not load large contexts at all.)
    _INKLING_CTX_COMPUTE_BYTES_PER_TOK = 8192  # per token at ub=512
    # Dense relative-bias fallback rate (quantized KV cache disables the banded
    # path): measured 402.5 GiB reserve at 1M ctx pre-fix, ~402 KiB per token.
    _INKLING_CTX_COMPUTE_DENSE_BYTES_PER_TOK = 402470  # per token at ub=512

    def _estimate_compute_buffer_bytes(
        self,
        *,
        n_ubatch: Optional[int] = None,
        n_parallel: int = 1,
        per_device_tensor: bool = False,
    ) -> int:
        """Per-device compute-graph buffer (bytes) from GGUF dims: a vocab-width
        output buffer + activation scratch. Context-independent; scales with
        ``--parallel`` (serving slots). Tensor mode materializes it on every device.
        A slight upper bound over measured allocations; 0 when dims are missing."""
        n_vocab = self._vocab_size or 0
        n_embd = self._embedding_length or 0
        if n_vocab <= 0 or n_embd <= 0:
            return 0
        ub = max(
            1,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )
        par = max(1, int(n_parallel))
        out_buffer = n_vocab * ub * 4  # f32 output/logits buffer
        act_scratch = 4 * n_embd * ub * 4  # a few resident hidden-width buffers
        if per_device_tensor:
            # Output + comm/staging materialized on every device, every slot.
            compute = 2 * act_scratch + out_buffer * par
        else:
            # Each extra concurrent slot adds one output buffer (chat decode sizes
            # ~one logit row per slot). Embedding mode outputs the whole first
            # micro-batch too, so it pays for every slot rather than slots past one.
            # Matches measured chat {1:36,2:492,4:1388,8:3220} MiB.
            output_slots = par if self.is_embedding_gguf else max(0, par - 1)
            compute = act_scratch + out_buffer * output_slots
        return int(compute * self._COMPUTE_BUFFER_SAFETY)

    def _compute_buffer_ctx_bytes(
        self,
        n_ctx: int,
        n_ubatch: Optional[int] = None,
        cache_type_kv: Optional[str] = None,
        *,
        layer_split: bool = False,
    ) -> int:
        """Context-linear growth of the per-device compute buffer (bytes), charged
        on top of the flat ``_estimate_compute_buffer_bytes``. The flash-attn KQ
        mask + attention scratch scale ~linearly with context and with the micro-
        batch; the flat term only covers ctx -> 0. A quantized KV cache adds a
        context-sized dequant scratch that scales with n_embd; f16/bf16/f32 pays only
        the KQ mask, a flat n_ubatch*2 bytes per context token. ``cache_type_kv`` None
        -> f16 (llama.cpp's default; env-set types are adopted by the caller via
        ``_env_main_cache_type_for_budget``). Returns 0 when dims are missing or
        ``n_ctx`` <= 0.

        ``layer_split`` adds the extra KQ-mask copies a multi-device split pays (see
        ``_CTX_COMPUTE_SPLIT_MULT``) on every architecture except deepseek4, whose own
        rate already subsumes them. Tensor mode passes False, having been measured
        separately at the single-device rate (see ``_plan_tensor_parallel``)."""
        n_embd = self._embedding_length or 0
        if n_embd <= 0 or n_ctx <= 0:
            return 0
        ub = max(
            1,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )
        # One KQ mask copy ([n_kv, n_ubatch] f16), n_embd-independent. Every rate below
        # is a single-GPU total containing exactly one, so a split adds the extra copies.
        mask_rate = ub * 2 * self._CTX_COMPUTE_F16_MASK_SAFETY
        split_extra = (self._CTX_COMPUTE_SPLIT_MULT - 1) * mask_rate if layer_split else 0.0
        if getattr(self, "_architecture", None) == "deepseek4":
            # DSV4 indexer/CSA buffer (see constants): flat + linear, ub-scaled. Fires
            # for any KV type -- the indexer scratch is present even with an f16 cache.
            # No split_extra, unlike every other arch: 72000 already clears the measured
            # 65.5 KiB/tok by 4928 B/tok, more than the 4608 the mask copies cost.
            ub_scale = ub / self._DEFAULT_N_UBATCH
            return int(
                self._DSV4_CTX_COMPUTE_FLAT_BYTES
                + self._DSV4_CTX_COMPUTE_BYTES_PER_TOK * n_ctx * ub_scale
            )
        if getattr(self, "_architecture", None) == "inkling":
            ub_scale = ub / self._DEFAULT_N_UBATCH
            # The fused banded path requires an f32/f16/bf16 KV cache. A quantized
            # cache forces the dense relative-bias fallback, whose compute buffer is
            # [n_kv, ub, n_head] f32 (~402 KiB per context token at ub=512); size the
            # fit for that so a q8_0 cache gets a small honest context instead of an
            # unloadable one that crash-loops the server.
            if cache_type_kv and _kv_bytes_per_elem(cache_type_kv) < 2.0:
                rate = self._INKLING_CTX_COMPUTE_DENSE_BYTES_PER_TOK
            else:
                # Banded flash path (see constants): linear, ub-scaled.
                rate = self._INKLING_CTX_COMPUTE_BYTES_PER_TOK
            # Both paths allocate the mask, and 8192 has only ~1.5x headroom over the
            # 5.6 KiB/tok banded measurement -- a split alone would overrun it.
            return int(rate * n_ctx * ub_scale + split_extra * n_ctx)
        if _kv_bytes_per_elem(cache_type_kv) < 2.0:
            # Quantized cache: the dequant scratch dominates and scales with n_embd.
            # MLA (compressed KV) needs far less of it: measured 0.94 x n_embd on
            # GLM-5.2 and Kimi-K2.7 vs up to 2.02x on regular attention.
            ub_scale = ub / self._DEFAULT_N_UBATCH
            rate = (
                self._CTX_COMPUTE_BYTES_PER_EMBD_MLA
                if self._key_length_mla
                else self._CTX_COMPUTE_BYTES_PER_EMBD
            )
            per_tok = rate * n_embd * ub_scale
        else:
            # f16/bf16/f32: only the KQ mask.
            per_tok = mask_rate
        # Only the mask goes 1x -> 4x, not the dequant scratch, so ADD the extra copies:
        # max() would under-reserve the quantized path by the whole dequant scratch.
        return int((per_tok + split_extra) * n_ctx)

    def _slots_that_fit_on_gpu(
        self,
        n_parallel: int,
        effective_ctx: int,
        gpus: list[tuple[int, int]],
        total_by_idx: Optional[dict[int, int]],
        base_footprint_bytes: int,
        cache_type_kv: Optional[str],
        pin_fraction: float,
        per_device_overhead_bytes: int,
        min_gpus: int,
        n_ubatch: Optional[int] = None,
        swa_full: bool = False,
        kv_unified: bool = True,
        flash_attn: bool = True,
        split_extra_bytes: int = 0,
        ubatch_for_slots: Optional[Callable[[int], Optional[int]]] = None,
        mtp_bytes_for_slots: Optional[Callable[[int, Optional[int]], int]] = None,
        ctx_checkpoints: int = 0,
        include_requested: bool = False,
        exact: bool = False,
    ) -> tuple[Optional[list[int]], bool, int]:
        """Largest serving-slot count that fits fully on GPU, so Unsloth keeps the model on
        GPU (-ngl -1) instead of --fit on, which offloads layers to host and collapses decode
        ~3x (oobabooga #6718). The search runs over [1, n_parallel) by default, or over
        [1, n_parallel] when ``include_requested`` is set. ``base_footprint_bytes`` is the
        slot-independent footprint (weights + soft overhead + context-linear compute,
        minus the folded compute buffer); each candidate re-adds the slot-sized compute buffer
        and KV, then re-selects GPUs like the explicit-context path -- ``split_extra_bytes``
        included, so a multi-GPU candidate is re-checked at the split rate. Returns
        (gpu_indices, use_fit=False, slots) for the largest fitting count, else (None, True,
        n_parallel). Unit-testable with synthetic VRAM maps.
        ``exact`` stops after the first candidate, for a caller that accepts only
        ``n_parallel`` itself and would re-price every lower count just to discard it.
        ``ctx_checkpoints`` mirrors --ctx-checkpoints, which allocates N SWA/recurrent
        snapshots PER SLOT; omitting it under-prices every candidate, so the caller that
        re-fits context off this predicate would spend bytes already promised to them.
        ``ubatch_for_slots`` re-derives the micro-batch per candidate: the emitted
        --batch-size is raised to max(slots, 2), and llama.cpp caps the micro-batch
        against it, so a batch below the requested slot count shrinks as the candidates
        do. Holding it at the requested count made a fitting candidate look too big and
        dropped the load to --fit offload.
        ``mtp_bytes_for_slots(slots, ubatch)`` does the same for the MTP reserve, which is
        NOT slot-independent: compact SWA scales its window allowance by the slot count
        under kv_unified and adds one micro-batch, and an MLA target with recurrent (KDA)
        layers charges per slot. It takes the candidate micro-batch as well as the slot
        count, since a reduced candidate lowers the batch floor and so the ubatch too;
        pricing the reserve at the requested pair over-charged every candidate, so one that
        fits could be rejected and the load kept --fit."""
        for slots in range(n_parallel if include_requested else n_parallel - 1, 0, -1):
            _ub = ubatch_for_slots(slots) if ubatch_for_slots else n_ubatch
            cb = self._estimate_compute_buffer_bytes(
                n_ubatch = _ub, n_parallel = slots, per_device_tensor = False
            )
            if cb <= 0:
                cb = self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
            total = (
                base_footprint_bytes
                + cb
                + (mtp_bytes_for_slots(slots, _ub) if mtp_bytes_for_slots else 0)
                + self._estimate_kv_cache_bytes(
                    effective_ctx,
                    cache_type_kv,
                    n_parallel = slots,
                    swa_full = swa_full,
                    kv_unified = kv_unified,
                    n_ubatch = _ub,
                    ctx_checkpoints = ctx_checkpoints,
                    flash_attn = flash_attn,
                )
            )
            gpu_indices, use_fit = self._select_gpus_split_aware(
                total,
                gpus,
                usable_fraction = pin_fraction,
                total_by_idx = total_by_idx,
                per_device_overhead_bytes = per_device_overhead_bytes,
                min_gpus = min_gpus,
                split_extra_bytes = split_extra_bytes,
            )
            if not use_fit:
                return gpu_indices, False, slots
            if exact:
                break
        return None, True, n_parallel

    def _fit_context_to_vram(
        self,
        requested_ctx: int,
        available_mib: int,
        model_size_bytes: int,
        cache_type_kv: Optional[str] = None,
        min_ctx: int = 8192,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        ctx_checkpoints: int = 0,
        flash_attn: bool = True,
        kv_on_gpu: bool = True,
        mtp_engaged: bool = False,
        # True only for an absolute budget already summed across cards.
        pooled: bool = False,
        mtp_overhead_fn: Optional[Callable[[int], int]] = None,
        compute_ctx_bytes_fn: Optional[Callable[[int], int]] = None,
        budget_frac: Optional[float] = None,
        total_mib: Optional[int] = None,
    ) -> int:
        """Return the largest context length that fits in GPU VRAM.

        Budget caps occupancy at ``_CTX_FIT_VRAM_FRACTION`` of the card: an
        absolute ``free - (1 - frac) * total`` when ``total_mib`` is given, else
        ``free * frac``. Weights alone over budget returns ``requested_ctx``.

        ``kv_on_gpu`` mirrors ``--kv-offload`` (default on); when False the KV
        cache lives in CPU RAM and the requested context is honored verbatim.
        Other keyword args mirror ``_estimate_kv_cache_bytes``.

        ``mtp_engaged`` reserves extra VRAM for the MTP draft model's KV cache +
        compute buffers, else tight tiers (e.g. 32 GB) spill to a slower path.
        """
        if not self._can_estimate_kv():
            logger.debug(
                "Skipping context fit because KV cache metadata is unavailable",
                requested_ctx = requested_ctx,
                available_mib = available_mib,
            )
            return requested_ctx

        # KV lives off-GPU: no VRAM accounting needed for the cache itself.
        if not kv_on_gpu:
            return requested_ctx

        kv_kwargs = dict(
            swa_full = swa_full,
            n_parallel = n_parallel,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            ctx_checkpoints = ctx_checkpoints,
            flash_attn = flash_attn,
        )

        # byte-accurate mtp_overhead_fn supersedes the flat fraction (the fallback
        # when dims can't size the draft KV); callers may override budget_frac.
        if budget_frac is None:
            flat_mtp = mtp_engaged and mtp_overhead_fn is None
            budget_frac = _active_vram_fraction() - (_MTP_VRAM_RESERVE_FRAC if flat_mtp else 0.0)
        # Absolute reserve off total when known, else fraction-of-free; clamp >=0.
        budget_mib = _vram_usable_mib(available_mib, total_mib or 0, budget_frac, pooled = pooled)
        if total_mib is not None and total_mib > 0:
            budget_mib = max(0.0, budget_mib)
        budget_bytes = budget_mib * 1024 * 1024
        model_footprint = model_size_bytes

        def _mtp_at(ctx: int) -> int:
            return mtp_overhead_fn(ctx) if mtp_overhead_fn is not None else 0

        def _cc_at(ctx: int) -> int:
            # Context-linear compute-buffer growth (flash-attn KQ mask + scratch);
            # the flat term in model_footprint only covers ctx -> 0.
            return compute_ctx_bytes_fn(ctx) if compute_ctx_bytes_fn is not None else 0

        # Already fits?
        kv = self._estimate_kv_cache_bytes(requested_ctx, cache_type_kv, **kv_kwargs)
        if model_footprint + kv + _mtp_at(requested_ctx) + _cc_at(requested_ctx) <= budget_bytes:
            return requested_ctx

        # Weights + compute buffer alone exceed budget -- reducing ctx can't help.
        if model_footprint >= budget_bytes:
            logger.debug(
                "Model footprint exceeds GPU budget before KV cache",
                requested_ctx = requested_ctx,
                available_mib = available_mib,
                model_size_gb = round(model_footprint / (1024**3), 2),
            )
            return requested_ctx

        # Binary search for max context that fits (KV + MTP draft reserve at that ctx)
        remaining = budget_bytes - model_footprint
        effective_min = min(min_ctx, requested_ctx)
        lo, hi = effective_min, requested_ctx
        best = effective_min
        while lo <= hi:
            mid = (lo + hi) // 2
            kv = self._estimate_kv_cache_bytes(mid, cache_type_kv, **kv_kwargs)
            if kv + _mtp_at(mid) + _cc_at(mid) <= remaining:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1

        # Round down to nearest 256 for alignment, never above requested_ctx
        best = (best // 256) * 256
        best = max(effective_min, best)
        best = min(best, requested_ctx)
        return best

    # ── Variant fallback ────────────────────────────────────────────

    @staticmethod
    def _find_smallest_fitting_variant(
        hf_repo: str,
        free_bytes: int,
        hf_token: Optional[str] = None,
    ) -> Optional[tuple[str, int, list[str]]]:
        """Find the smallest GGUF variant (including all shards) that fits.

        Groups split shards by variant prefix and sums their sizes (e.g.
        UD-Q4_K_XL with 9 shards of 50 GB each = 450 GB total).

        Returns (first_shard_filename, total_size_bytes, extra_shards) or None.
        """
        try:
            from huggingface_hub import get_paths_info, list_repo_files

            files = list_repo_files(hf_repo, token = hf_token)
            from hub.utils.gguf import drop_shadowed_appledouble_names

            gguf_files = [
                f
                for f in drop_shadowed_appledouble_names(list(files))
                if f.lower().endswith(".gguf")
                and not _is_companion_gguf_path(f)
                and not _is_big_endian_gguf_path(f)
            ]
            if not gguf_files:
                return None

            # Sizes for all GGUF files
            path_infos = list(get_paths_info(hf_repo, gguf_files, token = hf_token))
            size_map = {p.path: (p.size or 0) for p in path_infos}

            # Group by variant: shards share a prefix before -NNNNN-of-NNNNN
            variants: dict[str, list[str]] = {}
            for f in gguf_files:
                m = _SHARD_RE.match(f)
                key = m.group(1) if m else f
                variants.setdefault(key, []).append(f)

            # Sum shard sizes per variant, track the first shard (for download)
            variant_sizes: list[tuple[str, int, list[str]]] = []
            for key, shard_files in variants.items():
                total = sum(size_map.get(f, 0) for f in shard_files)
                first = sorted(shard_files)[0]
                variant_sizes.append((first, total, shard_files))

            # Smallest that fits
            variant_sizes.sort(key = lambda x: x[1])
            for first_file, total_size, shard_files in variant_sizes:
                if total_size > 0 and total_size <= free_bytes:
                    return (
                        first_file,
                        total_size,
                        [path for path in sorted(shard_files) if path != first_file],
                    )

            return None
        except Exception:
            return None

    # ── Port allocation ───────────────────────────────────────────

    @staticmethod
    def _find_free_port() -> int:
        """Find an available TCP port."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.bind(("127.0.0.1", 0))
            return s.getsockname()[1]

    # ── Stdout drain (prevents pipe deadlock on Windows) ─────────

    def _drain_stdout(self):
        """Read subprocess stdout lines in a background thread.

        Prevents a pipe-buffer deadlock on Windows (~4 KB buffer): without
        draining, llama-server blocks on writes and never becomes healthy.
        Each line is also teed to ``self._llama_log_fh`` when set, so a
        post-mortem has the full output even if the crash predates the
        drain-thread join in ``_wait_for_health``.
        """
        try:
            for line in self._process.stdout:
                line = line.rstrip()
                if line:
                    self._stdout_lines.append(line)
                    # Two forms across llama.cpp builds. Only readiness lines wake the
                    # probe: waking on every tensor-load log spins startup.
                    line_lower = line.lower()
                    if "server is listening" in line_lower or "model loaded" in line_lower:
                        health_probe_event = getattr(self, "_health_probe_event", None)
                        if health_probe_event is not None:
                            health_probe_event.set()
                    logger.debug(f"[llama-server] {line}")
                    fh = getattr(self, "_llama_log_fh", None)
                    if fh is not None:
                        try:
                            fh.write(line + "\n")
                            fh.flush()
                        except (ValueError, OSError):
                            # Log file closed under us; tee silently.
                            pass
        except Exception:
            # Never let the drain thread die: a full stdout pipe can deadlock
            # llama-server (Windows). Pipe-closed on exit is the common case.
            logger.debug("llama-server stdout drain stopped", exc_info = True)
        finally:
            # EOF means the process exited; wake the health loop immediately.
            health_probe_event = getattr(self, "_health_probe_event", None)
            if health_probe_event is not None:
                health_probe_event.set()

    # GGUF KV type sizes for fast skipping
    _GGUF_TYPE_SIZE = {
        0: 1,
        1: 1,
        2: 2,
        3: 2,
        4: 4,
        5: 4,
        6: 4,
        7: 1,
        10: 8,
        11: 8,
        12: 8,
    }

    @staticmethod
    def _gguf_skip_value(f, vtype: int) -> None:
        """Skip a GGUF KV value without reading it."""
        sz = LlamaCppBackend._GGUF_TYPE_SIZE.get(vtype)
        if sz is not None:
            f.seek(sz, 1)
        elif vtype == 8:  # STRING
            slen = struct.unpack("<Q", f.read(8))[0]
            f.seek(slen, 1)
        elif vtype == 9:  # ARRAY
            atype = struct.unpack("<I", f.read(4))[0]
            alen = struct.unpack("<Q", f.read(8))[0]
            elem_sz = LlamaCppBackend._GGUF_TYPE_SIZE.get(atype)
            if elem_sz is not None:
                f.seek(elem_sz * alen, 1)
            elif atype == 8:
                for _ in range(alen):
                    slen = struct.unpack("<Q", f.read(8))[0]
                    f.seek(slen, 1)
            else:
                for _ in range(alen):
                    LlamaCppBackend._gguf_skip_value(f, atype)

    @staticmethod
    def _gguf_read_array_value(f, atype: int, alen: int) -> Optional[list]:
        if atype == 4:  # UINT32
            return [struct.unpack("<I", f.read(4))[0] for _ in range(alen)]
        if atype == 5:  # INT32
            return [struct.unpack("<i", f.read(4))[0] for _ in range(alen)]
        if atype == 7:  # BOOL
            return [struct.unpack("<?", f.read(1))[0] for _ in range(alen)]

        if atype == 8:  # STRING: kept only for the delimiter-shaped entries (#7066).
            from core.inference.chat_template_helpers import delimiter_shaped_tokens

            kept: list = []
            for _ in range(alen):
                n = struct.unpack("<Q", f.read(8))[0]
                raw = f.read(n)
                # Only "<...>" / "[...]" entries survive delimiter_shaped_tokens, so skip
                # the decode for the rest. UTF-8 is self-synchronising, so no multi-byte
                # character starts with either byte and the first one settles it. The
                # bytes are still read rather than seeked past: seeking would move the
                # cursor differently on a short read, raise a different error on a bad
                # length, and fail outright on a non-seekable stream. Decoding a
                # six-figure vocabulary is the cost here, not reading it.
                if raw[:1] != b"<" and raw[:1] != b"[":
                    continue
                # A vocabulary holds arbitrary bytes; a marker is text, so undecodable
                # entries are simply not markers.
                try:
                    kept.append(raw.decode("utf-8"))
                except UnicodeDecodeError:
                    continue
            return delimiter_shaped_tokens(kept)

        for _ in range(alen):
            LlamaCppBackend._gguf_skip_value(f, atype)
        return None

    @classmethod
    def _gguf_path_is_diffusion(cls, gguf_path: str, model_identifier: str) -> bool:
        """Classify a downloaded GGUF without mutating the active backend."""
        probe = object.__new__(cls)
        probe._model_identifier = model_identifier
        probe._read_gguf_metadata(gguf_path)
        return probe._is_diffusion

    def _reject_vulkan_diffusion_gpu_ids_before_teardown(
        self, gguf_path: str, model_identifier: str
    ) -> None:
        """Reject Vulkan + gpu_ids for diffusion GGUFs before Phase 1 teardown."""
        if self._gguf_path_is_diffusion(gguf_path, model_identifier):
            raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)

    @classmethod
    def _non_chat_gguf_refusal_for_path(
        cls, gguf_path: str, model_identifier: Optional[str]
    ) -> Optional[str]:
        """``_non_chat_gguf_refusal`` for a file on disk, so it can be raised before Phase 1
        tears the running model down -- refusing after costs the user their resident chat
        model to answer a question the header already answers. Same probe-instance trick as
        ``_gguf_path_is_diffusion``: reading into ``self`` would overwrite the live model's
        metadata with a file we are about to reject."""
        probe = object.__new__(cls)
        probe._model_identifier = model_identifier
        probe._read_gguf_metadata(gguf_path)
        return probe._non_chat_gguf_refusal(gguf_path)

    @classmethod
    def _verified_cached_gguf(cls, intent, hf_repo, hf_variant) -> Optional[str]:
        """Return a carried file only if it still matches the load and active cache."""
        verified = getattr(intent, "verified_gguf", None)
        if not verified:
            return None
        try:
            repo, variant, path, sizes = verified
        except (TypeError, ValueError):
            return None
        if (repo or "").lower() != (hf_repo or "").lower():
            return None
        if (variant or "").lower() != (hf_variant or "").lower():
            return None
        if not path:
            return None
        try:
            if not Path(path).is_file():
                return None
            from utils.hf_cache_settings import get_hf_cache_paths
            hub_cache = Path(os.path.abspath(get_hf_cache_paths().hub_cache))
        except Exception:  # noqa: BLE001 -- an unreadable cache setting is not a reusable path
            return None
        # Cache settings can change while a load is in flight.
        try:
            if not Path(os.path.abspath(path)).is_relative_to(hub_cache):
                return None
        except (OSError, ValueError):
            return None
        # Recheck the recorded byte count of every shard against the set this
        # snapshot still holds. Both are local, so reuse still avoids Hub calls.
        try:
            if _cached_variant_sizes(_resolve_repo_id_casing(repo), variant, path) != sizes:
                return None
        except OSError:
            return None
        return path

    @classmethod
    def non_chat_gguf_refusal_for_intent(cls, intent) -> Optional[str]:
        """The header verdict for a resolved load intent, or None.

        ``load_model``'s copy runs before its own teardown, but by then the ROUTE has already
        evicted a resident Images/Video pipeline via ``acquire_for(CHAT)`` and cancelled the
        running generations. Asking here first spares both; the in-load checks stay as the
        backstop for paths that skip the route. Fails open exactly as they do."""
        try:
            gguf_path = getattr(intent, "gguf_path", None)
            hf_repo = getattr(intent, "hf_repo", None)
            identifier = getattr(intent, "model_identifier", None)
            if gguf_path and not hf_repo and Path(gguf_path).is_file():
                return cls._non_chat_gguf_refusal_for_path(gguf_path, identifier)
            if hf_repo:
                hf_variant = getattr(intent, "hf_variant", None)
                verified = cls._verified_cached_gguf(intent, hf_repo, hf_variant)
                if verified:
                    verdict = cls._non_chat_gguf_refusal_for_path(verified, identifier)
                    cls._hand_over_route_verdict(hf_repo, hf_variant, verdict)
                    return verdict
                # Same offline window as the download: the probe asks the Hub before reading
                # any local header, and those calls would otherwise wait out their retry
                # backoff on an unreachable Hub.
                with _hf_offline_if_unreachable():
                    verdict = cls._remote_non_chat_gguf_verdict(
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        hf_token = getattr(intent, "hf_token", None),
                        model_identifier = identifier,
                    )
                cls._hand_over_route_verdict(hf_repo, hf_variant, verdict)
                return verdict
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Non-chat GGUF preflight failed for the route: %s", e)
        return None

    def host_offload_warning_for_intent(self, intent) -> Optional[str]:
        """The host-RAM advisory for a resolved load intent, or None.

        Advisory, never a refusal: the route LOGS this and loads anyway. It does not
        reach the load response -- it records nothing, and ``load_model`` clears the
        previous notice at its teardown anyway; the response carries the launch-time
        notice instead. What this buys is a line in the log before ``acquire_for(CHAT)``
        evicts a resident Images/Video pipeline, rather than only from deep inside
        ``load_model`` once that teardown has happened.

        Both capacities are read as PHYSICAL TOTALS, not as what is free right now. The
        resident llama-server, Unsloth model and Images/Video pipeline hold VRAM and, through
        a host KV cache, CPU-offloaded weights and locked mappings, host RAM as well, and the
        route and ``load_model`` reclaim all of it after this runs. Pricing against the free
        readings would warn about a switch to a model the reclaimed machine holds easily. Each
        total is the ceiling on what the launch can ever see, and every narrowing the launch
        applies to the pool (the ROCm arch gate, the Vulkan discrete preference, a ``gpu_ids``
        pin) only shrinks it further, so this charges no more than the launch copy and can
        warn about nothing the launch would call comfortable.

        Only a local path is priced. An HF repo may not be downloaded yet, and resolving one
        here would start a download the route has not committed to.
        """
        try:
            gguf_path = getattr(intent, "gguf_path", None)
            if not gguf_path or getattr(intent, "hf_repo", None):
                return None
            if not Path(gguf_path).is_file():
                return None
            binary = self._find_llama_server_binary()
            if not binary:
                return None
            # extras are appended after -m at launch and llama.cpp is last-wins, so read them
            argv = [
                binary,
                "-m",
                str(gguf_path),
                *(str(arg) for arg in getattr(intent, "extra_args", None) or ()),
            ]
            total_ram_mib = self._total_system_memory_mib()
            if total_ram_mib is None:
                return None
            probed = self._get_gpu_memory(binary)
            # an igpu and a MIG/vGPU line report total 0, leaving the ceiling unknown
            if any(total <= 0 for _idx, _free, total in probed):
                return None
            return self._launch_host_shortfall_message(
                argv,
                [(idx, total) for idx, _free, total in probed],
                avail_mib = total_ram_mib,
            )
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Host-RAM preflight failed for the route: %s", e)
        return None

    # Each ask is a repo listing, a cache verification and a range request, every one bounded
    # at 15s, so the route HANDS OVER what it learned rather than making a slow Hub pay twice.
    # Written only by the route entry point and taken once by the load it belongs to, so a
    # verdict can never outlive its load; the age bound only covers a route ask no load
    # ever came for.
    _HANDOFF_TTL_S = 120.0
    _route_verdict_handoff: Optional[
        tuple[tuple[Optional[str], Optional[str]], Optional[str], float]
    ] = None

    @classmethod
    def _take_route_verdict(cls, hf_repo, hf_variant):
        """The verdict the route just took for this key, or ``_MISS``. Consumed on read."""
        handoff = cls._route_verdict_handoff
        if handoff is None:
            return _MISS
        key, verdict, at = handoff
        if key != (hf_repo, hf_variant) or (time.monotonic() - at) >= cls._HANDOFF_TTL_S:
            return _MISS
        cls._route_verdict_handoff = None
        return verdict

    @classmethod
    def _hand_over_route_verdict(cls, hf_repo, hf_variant, verdict) -> None:
        cls._route_verdict_handoff = ((hf_repo, hf_variant), verdict, time.monotonic())

    @classmethod
    def _remote_non_chat_gguf_refusal(
        cls,
        *,
        hf_repo: str,
        hf_variant: Optional[str],
        hf_token: Optional[str],
        model_identifier: Optional[str],
    ) -> Optional[str]:
        """``_non_chat_gguf_refusal_for_path`` for a repo load, decided from a header-sized
        BYTE RANGE instead of the checkpoint, so the verdict lands before Phase 1 tears the
        resident model down. The Model Hub sends a repo id for every Hub model, so leaving
        this to the post-download check meant a media GGUF opened into a chat killed the
        live model to answer a question its own header answers; downloading first would
        trade the teardown for tens of GB.

        A 256 KiB prefix is decisive for exactly the files this refuses: measured over the
        Hub, flux / flux2 / cosmos / wan / sd3 finish the KV walk in 144-145 bytes and
        LTX-2, the largest seen, in 3,987, while a chat model's ``tokenizer.ggml.tokens``
        pushes its KV block into the megabytes (Qwen3-0.6B 5.93 MB, Llama-3.2-1B 7.82 MB) --
        so a chat prefix cuts mid-KV, ``_gguf_header_parsed`` stays False and there is no
        verdict.

        Fails open at every step (no filename, unreachable Hub, a 200 instead of a 206, too
        short a prefix) since the post-download check is the backstop. It can only make a
        refusal cheaper, never refuse a load the full-file check would have allowed.

        Takes the route's verdict for this intent when there is one, rather than repeating
        the listing, cache verification and range request it just paid for."""
        handed_over = cls._take_route_verdict(hf_repo, hf_variant)
        if handed_over is not _MISS:
            logger.debug("Reusing the header verdict the route already took for %s", hf_repo)
            return handed_over
        return cls._remote_non_chat_gguf_verdict(
            hf_repo = hf_repo,
            hf_variant = hf_variant,
            hf_token = hf_token,
            model_identifier = model_identifier,
        )

    @classmethod
    def _remote_non_chat_gguf_verdict(
        cls,
        *,
        hf_repo: str,
        hf_variant: Optional[str],
        hf_token: Optional[str],
        model_identifier: Optional[str],
    ) -> Optional[str]:
        """The uncached probe: one listing, one cache resolution, one range read."""
        try:
            from core.inference.diffusion_compat import (
                _read_gguf_header,
                _read_local_header,
            )
        except Exception as e:  # noqa: BLE001 -- an unavailable probe is not a verdict
            logger.debug("GGUF header probe unavailable: %s", e)
            return None
        try:
            gguf_filename, shards = _resolve_variant_gguf_files(hf_repo, hf_variant, hf_token)
            if not gguf_filename:
                return None
            # A cached copy answers this with no request, and is the only thing that can
            # answer it with the Hub down. Resolved with the SAME precedence AND the same
            # verification _download_gguf uses -- cached_gguf_for_load at
            # verify_sizes = True, then the listing's filename -- because that is the file
            # the load will open. Anything else (a truncated snapshot judged here but
            # skipped there, a repo that renamed the file for a quant) lets the probe judge
            # one GGUF and the load open another. verify_sizes fails open on unreachable
            # metadata, so the probe still answers offline.
            local = cached_gguf_for_load(hf_repo, hf_variant, verify_sizes = True, hf_token = hf_token)
            if local is None and not hf_variant:
                # No variant means cached_gguf_for_load declines outright, so mirror the other
                # half of _download_gguf: the complete candidate for this filename, size-checked
                # against its own revision. Never the bare local path -- a candidate the verified
                # lookup just REJECTED would come straight back through it, and the probe would
                # judge a truncated snapshot the load is about to redownload.
                candidate = _cached_complete_candidate(hf_repo, gguf_filename, list(shards))
                if candidate is not None and _cached_candidate_matches_revision_size(
                    hf_repo, candidate, hf_token
                ):
                    local = candidate[0]
            prefix = (
                _read_local_header(local)
                if local
                else _read_gguf_header(hf_repo, gguf_filename, hf_token)
            )
            # Magic, version and the two counts: anything shorter is not a GGUF at all.
            if len(prefix) < 24:
                return None
            with tempfile.TemporaryDirectory(prefix = "unsloth-gguf-probe-") as probe_dir:
                # Named after the real file: a GGUF declaring no architecture is judged by
                # its name, and a temp name would lose the page pointer.
                probe_path = os.path.join(probe_dir, os.path.basename(gguf_filename))
                with open(probe_path, "wb") as handle:
                    handle.write(prefix)
                return cls._non_chat_gguf_refusal_for_path(probe_path, model_identifier)
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Non-chat GGUF header probe failed for %s: %s", hf_repo, e)
            return None

    def _read_gguf_metadata(self, gguf_path: str) -> None:
        """Read context_length, architecture params, and chat_template from a GGUF header.

        Parses only the KV pairs we need (~30ms even for multi-GB files).
        For split GGUFs, metadata is always in shard 1.
        """
        # Reset metadata so stale flags (e.g. _supports_reasoning) don't
        # carry over when switching models.
        self._context_length = None
        self._chat_template = None
        self._markup_tokens = []
        self._markup_profile = None
        self._supports_reasoning = False
        self._reasoning_always_on = False
        self._reasoning_style = "enable_thinking"
        self._reasoning_effort_levels = []
        self._reasoning_default = True
        self._supports_preserve_thinking = False
        self._preserve_thinking_default = False
        self._supports_tools = False
        self._n_layers = None
        self._n_experts = None
        self._leading_dense_block_count = None
        self._n_kv_heads = None
        self._n_kv_heads_by_layer = None
        self._n_heads = None
        self._embedding_length = None
        self._pooling_type = None
        self._gguf_path = gguf_path
        self._feed_forward_length = None
        self._vocab_size = None
        self._kv_key_length = None
        self._kv_value_length = None
        self._sliding_window = None
        self._sliding_window_pattern = None
        self._full_attention_interval = None
        self._kv_lora_rank = None
        self._key_length_mla = None
        self._kv_key_length_swa = None
        self._kv_value_length_swa = None
        self._ssm_inner_size = None
        self._ssm_state_size = None
        self._ssm_group_count = None
        self._ssm_conv_kernel = None
        self._kda_head_dim = None
        self._shared_kv_layers = None
        self._nextn_predict_layers = None
        self._architecture = None
        self._is_diffusion = False
        self._gguf_header_parsed = False
        self._gguf_split_index = None

        try:
            canvas_seen = False
            WANTED = {
                "general.architecture",
                "tokenizer.chat_template",
                # Vocab size = tokens array length (no vocab_size key in many GGUFs).
                "tokenizer.ggml.tokens",
                # Block-diffusion marker (DiffusionGemma); routes to the diffusion runner.
                "diffusion.canvas_length",
                # Source-repo hints for the SWA resolver's HF fallback.
                "general.source.huggingface.repository",
                "general.source.url",
                "general.source.repo_url",
                "general.base_model.0.repo_url",
                "general.base_model.0.organization",
                "general.base_model.0.name",
                "general.basename",
                "general.organization",
                "general.size_label",
                "general.finetune",
            }
            # Arch-specific keys added dynamically once we know the arch.
            arch_keys: dict[str, str] = {}  # gguf_key -> attribute name
            arch = None
            pooling_by_arch: dict[str, int] = {}
            sliding_window_pattern_period: Optional[int] = None
            general: dict[str, str] = {}

            with open(gguf_path, "rb") as f:
                magic = struct.unpack("<I", f.read(4))[0]
                if magic != 0x46554747:  # b"GGUF" as little-endian u32
                    return
                _version = struct.unpack("<I", f.read(4))[0]
                _tensor_count, kv_count = struct.unpack("<QQ", f.read(16))

                # Set by the loop's `else` below: True only if no truncation `break` fired.
                kv_complete = False
                for _ in range(kv_count):
                    # Tolerate truncated input (e.g. a partial header from an
                    # HTTP byte-range fetch): bail out so the resolver
                    # fallback runs on whatever we parsed.
                    try:
                        key_len_bytes = f.read(8)
                        if len(key_len_bytes) < 8:
                            break
                        key_len = struct.unpack("<Q", key_len_bytes)[0]
                        key_bytes = f.read(key_len)
                        if len(key_bytes) < key_len:
                            break
                        key = key_bytes.decode("utf-8")
                        vtype_bytes = f.read(4)
                        if len(vtype_bytes) < 4:
                            break
                        vtype = struct.unpack("<I", vtype_bytes)[0]
                        # gguf-split puts the whole metadata block in shard 1 and gives every
                        # later shard only split.no / split.count / split.tensors.count
                        # (measured on unsloth/DeepSeek-R1-GGUF: shard 1 has 48 KV pairs from
                        # general.architecture = "deepseek2", shard 2 has those 3). Read the
                        # INDEX, not the presence: shard 1 carries these keys too, so presence
                        # alone would cover a whole set rather than its tail.
                        if key == "split.no":
                            width = _GGUF_UINT_WIDTHS.get(vtype)
                            if width is not None:
                                raw = f.read(width)
                                if len(raw) < width:
                                    break
                                self._gguf_split_index = int.from_bytes(raw, "little")
                                continue
                    except (struct.error, UnicodeDecodeError):
                        break

                    try:
                        if key in WANTED or key in arch_keys or key.endswith(".pooling_type"):
                            if vtype == 8:  # STRING
                                slen = struct.unpack("<Q", f.read(8))[0]
                                val_s = f.read(slen).decode("utf-8")
                                if key.startswith("general.") and key != "general.architecture":
                                    general[key] = val_s
                                if key == "general.architecture":
                                    arch = val_s
                                    self._architecture = val_s
                                    arch_keys = {
                                        f"{arch}.context_length": "context_length",
                                        f"{arch}.block_count": "n_layers",
                                        f"{arch}.expert_count": "n_experts",
                                        f"{arch}.leading_dense_block_count": "leading_dense_block_count",
                                        f"{arch}.attention.head_count_kv": "n_kv_heads",
                                        f"{arch}.attention.head_count": "n_heads",
                                        f"{arch}.embedding_length": "embedding_length",
                                        f"{arch}.pooling_type": "pooling_type",
                                        f"{arch}.feed_forward_length": "feed_forward_length",
                                        f"{arch}.attention.key_length": "kv_key_length",
                                        f"{arch}.attention.value_length": "kv_value_length",
                                        f"{arch}.attention.sliding_window": "sliding_window",
                                        f"{arch}.attention.sliding_window_pattern": "sliding_window_pattern",
                                        f"{arch}.full_attention_interval": "full_attention_interval",
                                        f"{arch}.attention.kv_lora_rank": "kv_lora_rank",
                                        f"{arch}.attention.key_length_mla": "key_length_mla",
                                        f"{arch}.attention.key_length_swa": "kv_key_length_swa",
                                        f"{arch}.attention.value_length_swa": "kv_value_length_swa",
                                        f"{arch}.attention.shared_kv_layers": "shared_kv_layers",
                                        f"{arch}.ssm.inner_size": "ssm_inner_size",
                                        f"{arch}.ssm.state_size": "ssm_state_size",
                                        f"{arch}.ssm.group_count": "ssm_group_count",
                                        f"{arch}.ssm.conv_kernel": "ssm_conv_kernel",
                                        f"{arch}.kda.head_dim": "kda_head_dim",
                                        f"{arch}.nextn_predict_layers": "nextn_predict_layers",
                                    }
                                elif key == "tokenizer.chat_template":
                                    self._chat_template = val_s
                            elif vtype in (4, 10):  # UINT32 or UINT64
                                val_i = (
                                    struct.unpack("<I", f.read(4))[0]
                                    if vtype == 4
                                    else struct.unpack("<Q", f.read(8))[0]
                                )
                                if key == "diffusion.canvas_length":
                                    canvas_seen = True
                                if key.endswith(".pooling_type"):
                                    pooling_by_arch[key] = val_i
                                attr = arch_keys.get(key)
                                if attr:
                                    if attr == "sliding_window_pattern":
                                        sliding_window_pattern_period = val_i
                                    else:
                                        setattr(self, f"_{attr}", val_i)
                            elif vtype == 9:  # ARRAY
                                atype = struct.unpack("<I", f.read(4))[0]
                                alen = struct.unpack("<Q", f.read(8))[0]
                                # Vocab size = token count; keep the length, not the strings.
                                if key == "tokenizer.ggml.tokens":
                                    self._vocab_size = int(alen)
                                val_a = self._gguf_read_array_value(f, atype, alen)
                                if key == "tokenizer.ggml.tokens" and val_a is not None:
                                    # Only the delimiter-shaped entries are kept, a few
                                    # hundred out of a six-figure vocab, so the sweep can
                                    # tell this model's own sentinels from another family's
                                    # without holding the whole vocabulary (#7066).
                                    from core.inference.chat_template_helpers import (
                                        delimiter_shaped_tokens,
                                    )
                                    self._markup_tokens = delimiter_shaped_tokens(val_a)
                                attr = arch_keys.get(key)
                                if attr == "n_kv_heads" and val_a is not None:
                                    self._n_kv_heads_by_layer = [int(x) for x in val_a]
                                    if self._n_kv_heads is None and self._n_kv_heads_by_layer:
                                        self._n_kv_heads = max(self._n_kv_heads_by_layer)
                                elif attr == "sliding_window_pattern" and val_a is not None:
                                    self._sliding_window_pattern = [bool(x) for x in val_a]
                                    sliding_window_pattern_period = None
                            else:
                                self._gguf_skip_value(f, vtype)
                        else:
                            self._gguf_skip_value(f, vtype)
                    except (struct.error, UnicodeDecodeError):
                        # Truncated input (e.g. HTTP byte-range header
                        # fetch); break so the resolver fallback runs on
                        # what we have.
                        break
                else:
                    kv_complete = True

            # GGUF metadata has no key-order contract. Pooling can precede
            # general.architecture, so bind the buffered value after the sweep.
            if arch is not None:
                self._pooling_type = pooling_by_arch.get(f"{arch}.pooling_type", self._pooling_type)

            # Decide diffusion routing before the SWA resolver below: it can raise on an arch transformers
            # does not know, which would otherwise drop a DiffusionGemma model to plain llama-server.
            self._is_diffusion = bool(
                (arch and arch.lower().startswith("diffusion")) or canvas_seen
            )
            if self._is_diffusion:
                logger.info(
                    f"GGUF metadata: diffusion model detected (architecture={arch}); "
                    "will serve via the diffusion runner"
                )

            # Expand a scalar period straight from the GGUF first.
            if (
                self._sliding_window_pattern is None
                and sliding_window_pattern_period
                and self._n_layers
            ):
                self._sliding_window_pattern = [
                    (i + 1) % sliding_window_pattern_period != 0 for i in range(self._n_layers)
                ]

            # Otherwise hand off to the resolver (cache / bootstrap / transformers / HF). Diffusion models
            # skip it: they do not use Unsloth's SWA pattern and the resolver can raise for them.
            if (
                self._sliding_window_pattern is None
                and self._sliding_window
                and self._n_layers
                and not self._is_diffusion
            ):
                hf_repo_candidates = (
                    general.get("general.source.huggingface.repository"),
                    _hf_repo_from_url(general.get("general.source.url")),
                    _hf_repo_from_url(general.get("general.source.repo_url")),
                    _hf_repo_from_url(general.get("general.base_model.0.repo_url")),
                    (
                        f"{general['general.base_model.0.organization']}/"
                        f"{general['general.base_model.0.name']}".replace(" ", "-")
                        if general.get("general.base_model.0.organization")
                        and general.get("general.base_model.0.name")
                        else None
                    ),
                    (
                        f"{general['general.organization']}/{general['general.basename']}".replace(
                            " ", "-"
                        )
                        if general.get("general.organization") and general.get("general.basename")
                        else None
                    ),
                )
                self._sliding_window_pattern = _resolve_swa_pattern(
                    arch,
                    self._n_layers,
                    hf_repo_candidates,
                )

            # Only with the whole walk done does ``_architecture is None`` mean "declares no
            # architecture" rather than "the read stopped early" -- what the preflight needs.
            self._gguf_header_parsed = kv_complete

            if self._context_length:
                logger.info(f"GGUF metadata: context_length={self._context_length}")
            if self._chat_template:
                logger.info(f"GGUF metadata: chat_template={len(self._chat_template)} chars")
                # Detect thinking/reasoning support from chat template.
                flags = detect_reasoning_flags(
                    self._chat_template,
                    self._model_identifier,
                    log_source = "GGUF metadata",
                )
                self._supports_reasoning = flags["supports_reasoning"]
                self._reasoning_style = flags["reasoning_style"]
                self._reasoning_effort_levels = flags.get("reasoning_effort_levels", [])
                self._reasoning_always_on = flags["reasoning_always_on"]
                self._supports_preserve_thinking = flags["supports_preserve_thinking"]
                self._preserve_thinking_default = flags["preserve_thinking_default"]
                self._supports_tools = flags["supports_tools"]
        except Exception as e:
            logger.warning(f"Failed to read GGUF metadata: {e}")

    # ── Diffusion runner (DiffusionGemma) ──

    def _find_diffusion_assets(self) -> Optional[tuple[list, str, Optional[str]]]:
        """Resolve how to launch the DiffusionGemma runner: (shim argv prefix,
        visual-server binary, optional extra PYTHONPATH dir for the file override).

        Shim: UNSLOTH_DG_SHIM (a .py file) first, else the installed
        unsloth_zoo.diffusion_studio.shim. Binary: DG_VISUAL_BIN first, else
        alongside llama-server. Returns None if neither can be found.
        """
        import importlib.util

        # Visual-server binary: env override, else next to llama-server or in the
        # install's build/bin (where the prebuilt/installer puts it). .exe on Windows.
        visual_bin = os.environ.get("DG_VISUAL_BIN")
        if not visual_bin:
            name = "llama-diffusion-gemma-visual-server" + (".exe" if os.name == "nt" else "")
            # include_denied: a transiently locked llama-server still pins the
            # install dir so the adjacent visual-server can be found
            base = self._find_llama_server_binary(include_denied = True)
            if base:
                base_dir = Path(base).parent
                for cand in (
                    base_dir / name,
                    base_dir / "build" / "bin" / name,
                    base_dir / "build" / "bin" / "Release" / name,
                ):
                    if cand.is_file():
                        visual_bin = str(cand)
                        break
        if not (visual_bin and Path(visual_bin).is_file()):
            return None

        # Shim: a file override (its dir goes on PYTHONPATH), else the zoo package via -m.
        shim_file = os.environ.get("UNSLOTH_DG_SHIM")
        if shim_file and Path(shim_file).is_file():
            return ([sys.executable, shim_file], visual_bin, str(Path(shim_file).parent))

        # Find the installed shim without importing the heavy unsloth_zoo package
        # (find_spec on the top-level package does not run its __init__).
        try:
            spec = importlib.util.find_spec("unsloth_zoo")
        except Exception:
            spec = None
        if spec is not None and spec.submodule_search_locations:
            pkg_dir = Path(list(spec.submodule_search_locations)[0])
            if (pkg_dir / "diffusion_studio" / "shim.py").is_file():
                return (
                    [sys.executable, "-m", "unsloth_zoo.diffusion_studio.shim"],
                    visual_bin,
                    None,
                )

        return None

    def diffusion_split_supported(self) -> bool:
        """Whether a diffusion launch right now would honour --ngl.

        Mirrors the launch gate for the training guard: a split the launcher will drop
        must be guarded as GPU-resident. False when no shim resolves or the probe fails,
        matching the launcher's own fallback."""
        try:
            assets = self._find_diffusion_assets()
        except Exception:
            return False
        if assets is None:
            return False
        shim_cmd, _visual_bin, _extra_pythonpath = assets
        return _shim_supports_ngl(shim_cmd)

    @staticmethod
    def _diffusion_gpu_arg(
        gpu_ids: Optional[List[int]],
        *,
        cpu_only: bool = False,
        force_cpu: bool = False,
    ) -> str:
        """Device token passed to the diffusion visual-server child.

        The visual engine replaces its child's CUDA visibility mask with this
        token, so an unpinned load must carry forward the first token from the
        parent's mask rather than turning a parent-relative ordinal into a new
        physical selection.
        """
        # force_cpu alone outranks the picker: zero GPU layers place nothing, and a real
        # device would let the child hold a context while _gpu_offload_active reports
        # False, making the training VRAM coordinator skip the unload. cpu_only stays
        # *below* the picker: an explicit pick wins on a host whose GPU torch cannot see.
        if force_cpu:
            return ""
        if gpu_ids:
            return str(sorted(gpu_ids)[0])
        if cpu_only:
            return ""
        if "DG_GPU" in os.environ:
            return os.environ["DG_GPU"]
        parent_mask = os.environ.get("CUDA_VISIBLE_DEVICES")
        if parent_mask:
            first = next((token.strip() for token in parent_mask.split(",") if token.strip()), "")
            if first and first != "-1":
                return first
        return "0"

    def _start_diffusion_server(
        self,
        *,
        model_path: str,
        gguf_path: Optional[str],
        hf_repo: Optional[str],
        hf_variant: Optional[str],
        model_identifier: str,
        n_ctx: int,
        extra_args: Optional[List[str]],
        gpu_ids: Optional[List[int]] = None,
        gpu_memory_mode: Literal["auto", "manual"] = "auto",
        gpu_layers: int = -1,
    ) -> bool:
        """Launch the OpenAI-compat diffusion shim (which drives the on-device
        visual decoder) and wait for health. Presents the same /v1 + /health
        interface as llama-server, so the rest of Unsloth is unchanged.

        Manual mode forwards gpu_layers as --ngl so a GGUF larger than VRAM can be
        split across GPU and RAM; auto leaves the runner's all-layers default."""
        assets = self._find_diffusion_assets()
        if assets is None:
            raise RuntimeError(
                "DiffusionGemma runner not found. Install unsloth_zoo (which ships "
                "unsloth_zoo.diffusion_studio.shim) or set UNSLOTH_DG_SHIM to a shim "
                "file, and provide the visual-server binary via DG_VISUAL_BIN or next "
                "to llama-server in the install tree."
            )
        shim_cmd, visual_bin, extra_pythonpath = assets
        self._diffusion_visual_bin = visual_bin

        self._kill_process()
        self._port = self._find_free_port()
        # Auto-size (0): the visual server probes the largest context that fits this GPU's VRAM
        # (capped at the training context). An explicit in-range n_ctx overrides it.
        maxtok = n_ctx if (n_ctx and 0 < n_ctx <= 65536) else 0
        # Manual mode: honour the picked split. Without it the runner pins every layer
        # to GPU and a GGUF larger than VRAM dies in cudaMalloc even at 0 layers
        # (#7574). An older shim has no --ngl, so drop it rather than die in argparse.
        manual_ngl = _diffusion_manual_ngl(gpu_memory_mode, gpu_layers)
        if manual_ngl is not None and not _shim_supports_ngl(shim_cmd):
            # Dropping a zero-layer split on virtualised Metal undoes the CPU pin:
            # cpu_only below is torch.cuda only, so it reads 0 on a Mac and the empty
            # --gpu token still lets the runner use Metal. Only the split keeps weights
            # off it, so refuse rather than serve possibly corrupt output.
            if manual_ngl == 0 and _metal_device_is_paravirtual():
                raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)
            logger.warning(
                "DiffusionGemma: ignoring the %d GPU-layer split; the installed "
                "unsloth_zoo shim has no --ngl. Upgrade unsloth_zoo to set the split.",
                manual_ngl,
            )
            manual_ngl = None
        # No visible CUDA GPU: a genuine CPU host, or a GPU host masked with
        # CUDA_VISIBLE_DEVICES="" to force CPU serving. Keep the visual-server child
        # CPU-masked (empty --gpu) so the shim does not re-expose GPU 0 via its default.
        cpu_only = self._effective_gpu_count() == 0
        # Stronger than cpu_only and deliberately not derived from it: _effective_gpu_count
        # is torch.cuda only, so it reads 0 on Metal, Vulkan, Windows-HIP or Intel XPU hosts
        # the visual server will happily use. Only an explicit zero-layer split keeps the
        # weights off every backend, and a real --gpu token there would let the child hold a
        # CUDA context while _gpu_offload_active reports False, which the coordinator trusts.
        holds_no_gpu = manual_ngl == 0
        # Honor the GPU picker first: the diffusion runner takes a single device,
        # so use the lowest selected GPU (matches the sorted set recorded below, so
        # the device used == the echoed gpu_ids[0]). With no pick, fall back to the
        # CPU-only mask, else DG_GPU / 0.
        gpu = self._diffusion_gpu_arg(gpu_ids, cpu_only = cpu_only, force_cpu = holds_no_gpu)

        cmd = list(shim_cmd) + [
            "--gguf",
            model_path,
            "--host",
            "127.0.0.1",
            "--port",
            str(self._port),
            "--gpu",
            gpu,
            "--maxtok",
            str(maxtok),
        ]
        if manual_ngl is not None:
            cmd += ["--ngl", str(manual_ngl)]
            # Block diffusion is compute-bound, so CPU-side layers cost far more than on an
            # autoregressive model (~6 tok/s vs ~31 for non-diffusion Gemma). Make the
            # tradeoff visible instead of swapping an OOM for a slow model.
            logger.warning(
                "DiffusionGemma: %d GPU layers requested. Layers left on CPU are much "
                "slower for block diffusion than for a regular model; prefer a smaller "
                "quant over a large CPU split if throughput matters.",
                manual_ngl,
            )

        env = child_env_without_native_path_secret()
        # `python -m unsloth_zoo.diffusion_studio.shim` imports unsloth_zoo, which
        # refuses to load unless UNSLOTH_IS_PRESENT is set (normally by `import
        # unsloth`). The shim never imports unsloth, so set it here as unsloth does.
        env["UNSLOTH_IS_PRESENT"] = "1"
        # The shim's `import unsloth_zoo` aborts in get_device_type() ("needs a GPU")
        # when no accelerator is visible, even though it only drives the CPU
        # visual-server binary and does no torch GPU work. Allow the CPU device so the
        # runner starts; the visual server still runs on the CPU llama.cpp build.
        if cpu_only:
            env.setdefault("UNSLOTH_ALLOW_CPU", "1")
        env["DG_VISUAL_BIN"] = visual_bin
        env["DG_GPU"] = gpu
        if gpu_ids:
            # The visual server remasks via CUDA_VISIBLE_DEVICES=<gpu>; pin PCI
            # order (as the llama-server path does) so the picked physical id maps
            # to the GPU the picker showed, not CUDA's default fastest-first order.
            env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
        # The file-override shim imports its sibling visual_engine; put its dir on PYTHONPATH.
        # (The zoo-package shim is an installed module and needs no PYTHONPATH change.)
        if extra_pythonpath:
            existing = env.get("PYTHONPATH")
            env["PYTHONPATH"] = (
                (extra_pythonpath + os.pathsep + existing) if existing else extra_pythonpath
            )

        logger.info(f"Starting DiffusionGemma runner: {' '.join(cmd)}")
        self._stdout_lines = []
        self._llama_log_fh = None
        self._llama_log_path = None
        try:
            log_dir = _swa_cache_path().parent / "logs" / "diffusion-server"
            log_dir.mkdir(parents = True, exist_ok = True)
            self._llama_log_path = log_dir / f"diffusion-{int(time.time())}-port-{self._port}.log"
            self._llama_log_fh = open(self._llama_log_path, "w", encoding = "utf-8", buffering = 1)
            # After the open, so the cap counts this file and can never delete it.
            prune_log_dir(log_dir, "diffusion-*.log", protect = self._llama_log_path)
            logger.info(f"diffusion runner stdout/stderr -> {self._llama_log_path}")
        except (OSError, UnicodeDecodeError) as e:
            logger.debug(f"Could not open diffusion runner log file: {e}")

        # The shim (and its visual server) die with this backend process, so a
        # Unsloth crash/restart never orphans a GPU process.
        self._process = subprocess.Popen(
            cmd,
            stdout = subprocess.PIPE,
            stderr = subprocess.STDOUT,
            text = True,
            encoding = "utf-8",
            errors = "replace",
            env = utf8_child_env(env),
            # Deliberately NOT start_new_session, as with the component
            # installer: the desktop stops this backend by signalling its
            # process group and force-kills it after five seconds, so a session
            # of its own would leave the shim and the visual server holding the
            # GPU until the next launch sweeps them.
            **_windows_hidden_subprocess_kwargs(),
            **_child_popen_kwargs(),
        )
        # macOS has no parent-death signal, so the kwargs above are empty there and
        # only this record lets the next startup reap a runner holding the GPU.
        try:
            from utils.process_lifetime import adopt_pid
            adopt_pid(self._process.pid)
        except Exception as e:
            logger.debug(f"Could not track diffusion runner for lifetime sweep: {e}")
        self._stdout_thread = threading.Thread(
            target = self._drain_stdout, daemon = True, name = "diffusion-stdout"
        )
        self._stdout_thread.start()

        # Publish state before the health wait (mirrors the llama-server path).
        self._gguf_path = model_path
        self._gguf_load_identity = self._gguf_load_source_identity(model_path)
        self._hf_repo = hf_repo
        self._is_vision = False
        # Clear the prior GGUF's toggle too: a diffusion model must not report the
        # last model's vision state.
        self._disable_vision = False
        self._vision_disabled_by_user = False
        self._is_audio = False  # clear any prior TTS/audio model's routing flag
        self._model_identifier = model_identifier
        self._cache_type_kv = None
        self._swa_full = False
        self._kv_cache_unified = False
        self._memory_state = None
        self._memory_policy_active = False
        self._memory_mlock_applicable = True
        self._fit_load_mode_flags = []
        self._memory_launch_pending = False
        self._n_ubatch = self._DEFAULT_N_UBATCH
        self._requested_n_batch = None
        self._requested_n_ubatch = None
        # The diffusion runner builds its own command and passes none of these,
        # so a previous GGUF's values must not be reported against it.
        self._requested_load_mode = None
        self._requested_spec_draft_cache_type = None
        self._requested_ctx_checkpoints = None
        self._requested_cache_ram = None
        self._flash_attn_enabled = True
        self._effective_cache_types = ("f16", "f16")
        self._requested_cache_types = ("f16", "f16")
        self._kv_cache_context_total = None
        # False means "confirmed to hold no VRAM" and makes the training coordinator skip
        # the unload, so it is claimed only for a zero-layer split.
        self._gpu_offload_active = not holds_no_gpu
        # Diffusion uses only the layer split of the llama.cpp GPU-memory knobs: record what
        # was applied (so /load, /status and reload dedup agree with the child) and reset the
        # rest so a previous GGUF's manual settings are not reported.
        self._gpu_memory_mode = gpu_memory_mode if manual_ngl is not None else "auto"
        self._gpu_layers = manual_ngl if manual_ngl is not None else -1
        # What was ASKED for, not always what was applied (no --ngl downgrades it above).
        # /status reports reality via _gpu_layers, but the dedup guards must compare like
        # with like or the same request reloads on every /load.
        self._diffusion_requested_ngl = _diffusion_manual_ngl(gpu_memory_mode, gpu_layers)
        self._n_cpu_moe = 0
        self._tensor_split = None
        self._spill_plan_flags = []
        # Diffusion is never tensor-parallel; clear any state left by a prior TP
        # chat load (load_model phase 1 only kills the process, it doesn't run
        # the unload reset) so /status doesn't misreport TP and an identical
        # re-Apply doesn't reload against stale tensor-parallel state.
        self._tensor_parallel = False
        # Same reason, sharper consequence: a diffusion runner DOES hold VRAM, so a
        # leftover arch-gate flag would answer holds_no_vram True and let the arbiter
        # run a competing workload into its memory (#7624).
        self._arch_gate_forced_cpu = False
        # The single-device runner records only the lowest selected GPU (chosen
        # above), not the whole pick, and clears any explicit pin from a prior
        # chat load; a multi-GPU list would misreport placement and mis-dedup.
        # A zero-layer split on virtualised Metal masks the child's devices outright, so
        # it pins nothing: record no effective pin, or /status names a device the runner
        # never used and clearing that pick reloads the same CPU runner.
        _pv_diffusion_cpu = manual_ngl == 0 and _metal_device_is_paravirtual()
        self._gpu_ids = [sorted(gpu_ids)[0]] if gpu_ids and not _pv_diffusion_cpu else None
        # The frontend prefers requested_gpu_ids when hydrating the picker.
        # Diffusion uses only one device, so echo the collapsed effective pin,
        # not unused members of the original request.
        self._requested_gpu_ids = [sorted(gpu_ids)[0]] if gpu_ids else None
        if hf_variant:
            self._hf_variant = hf_variant
        elif gguf_path:
            try:
                from utils.models.model_config import _extract_quant_label
                self._hf_variant = _extract_quant_label(gguf_path)
            except Exception:
                self._hf_variant = None
        else:
            self._hf_variant = None
        # Provisional until the server reports the budget it resolved (auto-size picks it from VRAM).
        self._effective_context_length = maxtok or self._context_length
        self._max_context_length = self._context_length or maxtok or None

        healthy = self._wait_for_health(timeout = 600.0)
        if healthy:
            self._healthy = True
            self._gpu_offload_active = not holds_no_gpu
            if extra_args is not None:
                self._extra_args = list(extra_args)
                # No spec block to drop here, so launched IS requested; rebind so a
                # prior GGUF load's record cannot outlive it.
                self._requested_extra_args = list(extra_args)
                self._extra_args_source = (model_identifier, hf_variant)
            # The visual server logs "MAXTOK=<N>" with the context budget it actually resolved
            # (auto-sized to VRAM). Read it back so the UI context bar shows the real budget.
            chosen = maxtok
            try:
                for _ln in reversed(self._stdout_lines):
                    _m = re.search(r"MAXTOK=(\d+)", _ln)
                    if _m:
                        chosen = int(_m.group(1))
                        break
            except Exception:
                pass
            if chosen and chosen > 0:
                self._effective_context_length = chosen
                self._max_context_length = chosen
            self._requested_n_ctx = int(n_ctx)
        else:
            self._healthy = False
            logger.error("DiffusionGemma runner failed to become healthy")
        return healthy

    # ── HF download (no lock held) ───────────────────────────────

    def _download_gguf(
        self,
        *,
        hf_repo: str,
        hf_variant: Optional[str] = None,
        hf_token: Optional[str] = None,
        force: bool = False,
        allow_smaller_fallback: bool = True,
        cancel_event: Optional[threading.Event] = None,
    ) -> str:
        """Download GGUF file(s) from HuggingFace. Returns local path.

        Runs WITHOUT self._lock so unload_model() can set _cancel_event at
        any time; checks it between each shard download.

        ``force`` re-fetches even when a (possibly stale) blob is cached.
        ``allow_smaller_fallback=False`` raises on low disk instead of silently
        switching to a smaller quant. ``cancel_event`` overrides
        ``self._cancel_event`` so an update can use a private event without
        touching the shared one; defaults to the shared event.
        """
        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        from utils.hf_cache_settings import get_hf_cache_paths

        download_cache_dir = str(get_hf_cache_paths().hub_cache)
        try:
            import huggingface_hub  # noqa: F401 -- presence check only
        except ImportError:
            raise RuntimeError(
                "huggingface_hub is required for HF model loading. "
                "Install it with: pip install huggingface_hub"
            )

        resolved_hf_repo = _resolve_repo_id_casing(hf_repo)
        if resolved_hf_repo != hf_repo:
            logger.info(
                "Using cached repo_id casing '%s' for requested '%s'",
                resolved_hf_repo,
                hf_repo,
            )
            hf_repo = resolved_hf_repo

        # Resolve the filename from the variant (shared with the pre-teardown header probe)
        gguf_filename, gguf_extra_shards = _resolve_variant_gguf_files(
            hf_repo, hf_variant, hf_token
        )

        # Prefer the existing model. Updates use force=True to fetch a new revision.
        if not force:
            if hf_variant:
                # Resolve by variant so a newer revision's filename does not hide
                # the complete older copy. Size-check against that older snapshot's
                # own revision when its metadata remains available.
                cached_main = cached_gguf_for_load(
                    hf_repo,
                    hf_variant,
                    verify_sizes = True,
                    hf_token = hf_token,
                )
            else:
                candidate = _cached_complete_candidate(hf_repo, gguf_filename, gguf_extra_shards)
                cached_main = (
                    candidate[0]
                    if candidate is not None
                    and _cached_candidate_matches_revision_size(hf_repo, candidate, hf_token)
                    else None
                )
            if cached_main is not None:
                logger.info(f"Reusing cached GGUF: {cached_main}")
                return cached_main

        # Check disk space; fall back to a smaller variant if needed
        all_gguf_files = [gguf_filename] + gguf_extra_shards
        try:
            from huggingface_hub import get_paths_info, try_to_load_from_cache

            path_infos = list(get_paths_info(hf_repo, all_gguf_files, token = hf_token))
            total_bytes = sum((p.size or 0) for p in path_infos)

            # Subtract bytes already in the HF cache so we only preflight
            # against what we must download. Without this, re-loading a
            # cached large model (e.g. MiniMax-M2.7-GGUF at 131 GB) fails
            # cold whenever free disk is below the full weight footprint,
            # even though nothing needs downloading.
            already_cached_bytes = 0
            # Count only files that can resume this download.
            offline = _hf_env_offline()
            # Offline split sets are reusable only when every shard shares a snapshot.
            split_needs_refetch = bool(offline and not force and gguf_extra_shards)
            if not force and not split_needs_refetch:
                for p in path_infos:
                    if not p.size:
                        continue
                    try:
                        cached_path = try_to_load_from_cache(
                            hf_repo,
                            p.path,
                            cache_dir = download_cache_dir,
                        )
                    except Exception:
                        cached_path = None
                    if (
                        not (isinstance(cached_path, str) and os.path.exists(cached_path))
                        and offline
                    ):
                        cached_path = _cached_hf_snapshot_file(
                            hf_repo,
                            p.path,
                            expected_size = p.size,
                            cache_dir = download_cache_dir,
                        )
                    if isinstance(cached_path, str) and os.path.exists(cached_path):
                        try:
                            on_disk = os.path.getsize(cached_path)
                        except OSError:
                            on_disk = 0
                        # Satisfied only when the full blob is present.
                        if on_disk >= p.size:
                            already_cached_bytes += p.size

            total_download_bytes = max(0, total_bytes - already_cached_bytes)

            if total_download_bytes > 0:
                Path(download_cache_dir).mkdir(parents = True, exist_ok = True)
                free_bytes = shutil.disk_usage(download_cache_dir).free

                total_gb = total_download_bytes / (1024**3)
                free_gb = free_bytes / (1024**3)
                cached_gb = already_cached_bytes / (1024**3)

                logger.info(
                    f"GGUF download: {total_gb:.1f} GB needed "
                    f"({cached_gb:.1f} GB already cached), "
                    f"{free_gb:.1f} GB free on disk"
                )

                if total_download_bytes > free_bytes:
                    if not allow_smaller_fallback:
                        # Update path: never silently switch to a smaller quant;
                        # surface the disk shortfall for the requested variant.
                        raise RuntimeError(
                            f"Not enough disk space to download {gguf_filename}. "
                            f"Only {free_gb:.1f} GB free in {download_cache_dir}"
                        )
                    smaller = self._find_smallest_fitting_variant(
                        hf_repo,
                        free_bytes,
                        hf_token,
                    )
                    if smaller:
                        fallback_file, fallback_size, fallback_shards = smaller
                        logger.info(
                            f"Selected variant too large ({total_gb:.1f} GB), "
                            f"falling back to {fallback_file} ({fallback_size / (1024**3):.1f} GB)"
                        )
                        gguf_filename = fallback_file
                        gguf_extra_shards = fallback_shards

                        # The selected fallback is a new load target. Apply the
                        # same any-revision reuse policy before starting a fetch.
                        fallback_candidate = _cached_complete_candidate(
                            hf_repo, gguf_filename, gguf_extra_shards
                        )
                        if fallback_candidate is not None and (
                            _cached_candidate_matches_revision_size(
                                hf_repo, fallback_candidate, hf_token
                            )
                        ):
                            logger.info(f"Reusing cached fallback GGUF: {fallback_candidate[0]}")
                            return fallback_candidate[0]
                    else:
                        raise RuntimeError(
                            f"Not enough disk space to download any variant. "
                            f"Only {free_gb:.1f} GB free in {download_cache_dir}"
                        )
        except RuntimeError:
            raise
        except Exception as e:
            logger.warning(f"Could not check disk space: {e}")

        gguf_label = f"{hf_repo}/{gguf_filename}" + (
            f" (+{len(gguf_extra_shards)} shards)" if gguf_extra_shards else ""
        )
        logger.info(f"Resolving GGUF: {gguf_label}")
        try:
            if cancel_event.is_set():
                raise RuntimeError("Cancelled")
            dl_start = time.monotonic()
            # Xet primary, HTTP fallback on stall; per-file so finished shards stay cached.
            local_path = hf_hub_download_with_xet_fallback(
                hf_repo,
                gguf_filename,
                hf_token,
                cancel_event = cancel_event,
                on_status = lambda m: logger.info(m),
                force_download = force,
                cache_dir = download_cache_dir,
            )
            for shard in gguf_extra_shards:
                if cancel_event.is_set():
                    raise RuntimeError("Cancelled")
                logger.info(f"Resolving GGUF shard: {shard}")
                hf_hub_download_with_xet_fallback(
                    hf_repo,
                    shard,
                    hf_token,
                    cancel_event = cancel_event,
                    force_download = force,
                    cache_dir = download_cache_dir,
                )
        except Exception as e:
            if isinstance(e, RuntimeError) and "Cancelled" in str(e):
                raise
            raise RuntimeError(
                f"Failed to download GGUF file '{gguf_filename}' from {hf_repo}: {e}"
            )

        dl_elapsed = time.monotonic() - dl_start
        if dl_elapsed < 2.0:
            logger.info(f"GGUF resolved from cache: {local_path}")
        else:
            logger.info(f"GGUF downloaded in {dl_elapsed:.1f}s: {local_path}")
        return local_path

    def _download_companion_gguf(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str],
        pick: Callable[[list[str]], Optional[str]],
        label: str,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
        outcome: Optional[dict] = None,
        on_transient_failure: Optional[Callable[[], None]] = None,
    ) -> Optional[str]:
        """Resolve and fetch a companion GGUF (mmproj / MTP drafter) by name.

        Prefers a companion co-located with ``near_path``'s cache snapshot,
        then tries the live repo file list, then the local HF cache snapshots
        (offline, same fallback as _download_gguf), then hf_hub_download.
        Runs WITHOUT self._lock (like _download_gguf); honors _cancel_event so
        an /unload between the main download and here skips the fetch.
        ``cancel_event`` overrides ``self._cancel_event`` (defaults to it).

        Split-aware, like the main-model download: a companion published as a
        split GGUF is only usable as a complete set, since llama-server resolves
        the sibling shards from the first one's directory. Fetching just the
        picked shard left a drafter whose header reads fine and which the server
        then cannot open, so the load fell back to no speculation with nothing to
        show for the download -- and it disagreed with the local scan, which
        accepts a split drafter only when every shard is present.

        ``on_transient_failure`` fires when the companion was lost to a listing that
        never completed or a download that dropped, the one None worth another attempt.
        A callback rather than an ``outcome`` key because the DFlash caller loops and
        needs the answer per attempt. Permanent errors, offline and cancellation do not
        fire it.
        """
        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            return None

        # The listing that produced the pick, kept so the shard siblings can be
        # resolved from the same names the pick chose among.
        available: list[str] = []

        def _pick_from(names: list[str]) -> Optional[str]:
            nonlocal available
            available = list(names)
            return pick(available)

        # Keep companion files in the main GGUF's snapshot.
        if near_path:
            cached = _companion_snapshot_sibling(near_path, pick)
            if cached:
                logger.info("Reusing cached %s: %s", label, cached)
                return cached

        from utils.hf_cache_settings import get_hf_cache_paths

        companion_cache_dir = _hub_cache_dir_for_snapshot_path(near_path) or str(
            get_hf_cache_paths().hub_cache
        )

        if _hub_download_in_flight(hf_repo):
            logger.info("Skipping %s download while a hub download is active", label)
            return None

        target: Optional[str] = None
        # Whether the question was actually answered. A listing that never
        # completed (offline, transient Hub failure) leaves target None for a
        # reason that says nothing about the repo's contents.
        listing_answered = False
        # Whether the listing died of something retryable. Distinct from
        # listing_answered: a permanent error also leaves the listing unanswered.
        listing_failed = False
        from huggingface_hub import list_repo_files

        # Retry a transient listing blip; permanent repo/auth errors and offline
        # mode are not retried (offline raises at once -> fall through to cache).
        for attempt in range(3):
            if cancel_event.is_set():
                return None
            try:
                target = _pick_from(list_repo_files(hf_repo, token = hf_token))
                listing_answered = True
                listing_failed = False
                break
            except Exception as e:
                if type(e).__name__ in _PERMANENT_HUB_ERRORS:
                    logger.debug(f"Could not list repo files for {label}: {e}")
                    break
                listing_failed = True
                logger.debug(
                    f"Could not list repo files for {label} (attempt {attempt + 1}/3): {e}"
                )
                if attempt < 2:
                    cancel_event.wait(2**attempt)

        if target is None:
            try:
                from utils.models.model_config import _iter_hf_cache_snapshots
                for snap in _iter_hf_cache_snapshots(hf_repo, companion_cache_dir):
                    rel_files = _gguf_snapshot_files(snap)
                    target = _pick_from(rel_files)
                    if target is not None:
                        logger.info("Resolved %s %s from local HF cache", label, target)
                        break
            except Exception as e:
                logger.debug(f"Offline cache lookup for {label} failed: {e}")

        # "The repo publishes none" and "the fetch failed" both return None, but
        # only the second is worth retrying on the next Apply. Left unset unless
        # the question was really answered -- by a listing that completed, or by
        # a cache hit that produced a target regardless -- so an unreachable Hub
        # is not recorded as a permanent absence.
        if (
            outcome is not None
            and not cancel_event.is_set()
            and (listing_answered or target is not None)
        ):
            outcome["listed"] = target is not None
        if target is None or cancel_event.is_set():
            # The listing is the only step that can fail this far in.
            if target is None and listing_failed and not cancel_event.is_set():
                self._report_transient_companion_failure(on_transient_failure, label)
            return None

        # Offline, resolve the companion straight from the cache snapshot that
        # holds it. resolve_cached_repo_id_case can return a partial lower-case
        # spelling when any dir exists under the requested casing, so calling
        # hf_hub_download with hf_repo would miss the canonical file and silently
        # drop the companion. _cached_hf_snapshot_file scans every case variant.
        if _hf_env_offline():
            cached = _cached_hf_snapshot_file(
                hf_repo,
                target,
                cache_dir = companion_cache_dir,
            )
            if cached:
                from utils.models.model_config import _drafter_split_is_complete

                # Same whole-set rule as the snapshot reuse above: half a split
                # companion is not a companion, and offline there is no fetch to
                # complete it, so answering None leaves the load without a
                # drafter instead of with one llama-server cannot open.
                if _drafter_split_is_complete(Path(cached)):
                    logger.info("Resolved %s from local HF cache: %s", label, cached)
                    return cached

        # A split companion is one file to pick and N files to fetch. Same helper
        # the main-model download resolves its shards with, so the two cannot
        # disagree about what belongs to a set; empty for the single-file case,
        # which is every mmproj and every published sidecar so far.
        extra_shards = _gguf_extra_shards(available, target)
        # The filename carries the set size, so a short listing is answerable before
        # the download: half a split companion is not one, as the reuse paths above say.
        _shard_total = _SHARD_FULL_RE.match(target)
        if _shard_total and len(extra_shards) + 1 != int(_shard_total.group(3)):
            logger.info(
                "Skipping %s: %s lists %d of %s shards.",
                label,
                hf_repo,
                len(extra_shards) + 1,
                _shard_total.group(3),
            )
            # Settled, not retryable: the listing answered, so the caller records
            # absence rather than reloading on every Apply.
            if outcome is not None:
                outcome["listed"] = False
            return None
        try:
            logger.info(f"Downloading {label}: {hf_repo}/{target}")
            # Same policy; companions are best-effort (caller below swallows failures to None).
            local_path = hf_hub_download_with_xet_fallback(
                hf_repo,
                target,
                hf_token,
                cancel_event = cancel_event,
                cache_dir = companion_cache_dir,
            )
            for shard in extra_shards:
                if cancel_event.is_set():
                    return None
                logger.info(f"Downloading {label} shard: {hf_repo}/{shard}")
                hf_hub_download_with_xet_fallback(
                    hf_repo,
                    shard,
                    hf_token,
                    cancel_event = cancel_event,
                    cache_dir = companion_cache_dir,
                )
            return local_path
        except Exception as e:
            logger.warning(f"Could not download {label}: {e}")
            # The listing named the file, so this is the fetch dropping: retryable
            # unless the Hub or this machine answered for good, or we were cancelled.
            if (
                not cancel_event.is_set()
                and type(e).__name__ not in _PERMANENT_HUB_ERRORS
                and getattr(e, "errno", None) not in _UNRECOVERABLE_LOCAL_ERRNOS
                and not _hf_env_offline()
            ):
                self._report_transient_companion_failure(on_transient_failure, label)
            return None

    @staticmethod
    def _report_transient_companion_failure(
        on_transient_failure: Optional[Callable[[], None]], label: str
    ) -> None:
        """Tell the caller its companion was lost to something retryable.

        Best-effort both ways: the callback is optional, and one that raises must not
        lose the load over bookkeeping for an already best-effort companion.
        """
        if on_transient_failure is None:
            return
        try:
            on_transient_failure()
        except Exception as exc:
            logger.debug("Could not record the transient %s failure: %s", label, exc)

    def _download_mmproj(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
    ) -> Optional[str]:
        """Download the mmproj (vision projection) file from a GGUF repo.

        Prefers mmproj-F16.gguf, else any mmproj*.gguf. Returns the local
        path, or None if none exists. ``cancel_event`` overrides
        ``self._cancel_event`` (defaults to it). ``near_path`` prefers a
        copy co-located with the main GGUF's cache snapshot.
        """

        return self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = _pick_mmproj,
            label = "mmproj",
            cancel_event = cancel_event,
            near_path = near_path,
        )

    def _cached_repo_mtp_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
    ) -> Optional[str]:
        """A drafter already in this repo's local HF cache, reused offline when a
        fresh copy can't be fetched. Prefers a repo-root ``mtp-*.gguf`` across all
        cached snapshots; else an existing ``MTP/`` copy (any precision -- the
        target verifies every drafted token). None if none is cached."""
        try:
            from utils.models.model_config import _iter_hf_cache_snapshots

            roots: list[Path] = []
            subdirs: list[Path] = []
            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            for snap in snapshots:  # newest first
                for f in sorted(_gguf_snapshot_files(snap)):
                    # MTP only: a DSpark drafter needs --spec-type draft-dspark,
                    # so it must never be launched as an MTP one.
                    if _is_mtp_only_drafter_path(f):
                        (roots if "/" not in f else subdirs).append(snap / f)
            # Keep snapshot order (newest first), root before any MTP/ copy, so a
            # newer main GGUF pairs with the newest cached drafter, not a stale one.
            for cand in roots + subdirs:
                if cand.is_file():
                    return str(cand)
        except Exception as e:
            logger.debug("Cached MTP drafter lookup failed for %s: %s", hf_repo, e)
        return None

    def _download_mtp(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        near_path: Optional[str] = None,
    ) -> Optional[str]:
        """Download the separate MTP drafter (speculative head) from a GGUF repo.

        Targets the repo-root ``mtp-*.gguf`` companion -- the Q8_0 drafter
        unsloth mirrors there for llama.cpp ``-hf`` auto-discovery (smallest,
        recommended for speculation). Repos that bake the MTP head into the
        main GGUF (e.g. Qwen) ship no such sibling and this returns None. The
        higher-precision copies under ``MTP/`` are for explicit selection and
        are intentionally skipped. Returns the local path, or None.
        """

        if near_path:
            cached = _companion_snapshot_sibling(near_path, _pick_mtp)
            if cached:
                logger.info("Reusing cached MTP drafter: %s", cached)
                return cached

        # Offline, reuse any drafter already on disk (a fresh copy can't be
        # fetched). Online, _download_companion_gguf/hf_hub_download reuse the
        # current cached file and refetch a changed one, so skip the probe here
        # rather than pair new weights with a stale draft.
        if _hf_env_offline():
            cached = self._cached_repo_mtp_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
            )
            if cached:
                logger.info(f"Reusing cached MTP drafter (offline): {cached}")
                return cached

        return self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = _pick_mtp,
            label = "MTP drafter",
            near_path = near_path,
        )

    def _cached_repo_dspark_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
    ) -> Optional[str]:
        """The preferred already-cached DSpark sidecar for a repo, Q8_0 first
        (dspark_preference_key), so an offline reuse picks the same file the
        online download would have fetched."""
        try:
            from utils.models.model_config import (
                _iter_hf_cache_snapshots,
                dspark_preference_key,
            )

            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            candidates: list[Path] = []
            for snap in snapshots:
                candidates.extend(
                    snap / name
                    for name in _gguf_snapshot_files(snap)
                    if _is_dspark_drafter_path(name)
                )
            for candidate in sorted(candidates, key = lambda p: dspark_preference_key(p.name)):
                if candidate.is_file():
                    return str(candidate)
        except Exception as exc:
            logger.debug("Cached DSpark drafter lookup failed for %s: %s", hf_repo, exc)
        return None

    def _download_dspark(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        near_path: Optional[str] = None,
        binary: Optional[str] = None,
        caps_probe: Optional[Callable[[Optional[str]], dict]] = None,
    ) -> Optional[str]:
        """Download the published DSpark sidecar, preferring its Q8_0 copy.

        The ~11 GB fetch is gated on ``supports_dspark``: a binary that cannot run
        ``draft-dspark`` (every prebuilt in the known-broken window included) falls
        back, so the download would never be opened. A raised probe still fetches,
        since launch re-probes and may yet engage.

        ``caps_probe`` is the caller's accumulator: this gate shapes the launch, and a
        guess here has to latch like any other, or a load that skipped the sidecar on an
        inconclusive probe looks conclusive once the retry window lapses mid-download.
        """
        if caps_probe is None:
            caps_probe = self.probe_server_capabilities

        cached = _companion_snapshot_sibling(near_path, _pick_dspark) if near_path else None
        if not cached and _hf_env_offline():
            cached = self._cached_repo_dspark_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
            )
        try:
            if not caps_probe(binary).get("supports_dspark"):
                logger.warning(
                    "Skipping the DSpark sidecar download: llama-server has no usable "
                    "--spec-type draft-dspark, so this load falls back to no speculative "
                    "decoding. Run `unsloth studio update`, then reload."
                )
                # A sidecar already on disk is still reported: the route rediscovers it
                # on every Apply, so answering None would make the reuse check compare
                # it against a launched None and reload the same server each time.
                # _build_speculative_flags re-checks the capability and still falls back.
                return cached
        except Exception as exc:
            logger.debug("DSpark capability probe failed before the sidecar fetch: %s", exc)

        if cached:
            logger.info("Reusing cached DSpark drafter: %s", cached)
            return cached
        outcome: dict = {}
        found = self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = _pick_dspark,
            label = "DSpark drafter",
            near_path = near_path,
            outcome = outcome,
        )
        # Distinguishes a repo that ships no sidecar (the permanent state for
        # every repo but one) from a fetch that failed and could yet succeed.
        self._dspark_sidecar_absent = outcome.get("listed") is False
        return found

    def _cached_repo_dflash_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
        near_path: Optional[str] = None,
    ) -> Optional[str]:
        """The preferred already-cached DFlash sidecar for a repo, Q8_0 first
        (dflash_repo_preference_key), so an offline reuse picks the same file
        the online download would have fetched.

        ``near_path`` is the weight this sidecar would draft for. A repo hosting
        more than one family ships more than one sidecar, and precision alone
        would hand model B the sidecar named after model A, so the candidates
        are ranked against the weight actually being loaded (same rule as
        detect_dflash_file). Without it the ordering is precision only, as
        before.
        """
        try:
            from utils.models.drafters import (
                _drafter_split_is_complete,
                dflash_repo_preference_key,
                is_dflash_architecture,
            )
            from utils.models.model_config import _iter_hf_cache_snapshots

            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            weight_name = Path(near_path).name if near_path else None
            ranked: list[tuple[tuple[int, int, int, str], Path]] = []
            for snap in snapshots:
                names = _gguf_snapshot_files(snap)
                # Every non-sidecar GGUF in the snapshot is a weight some sidecar
                # could be naming; that is what tells a neighbour's sidecar apart
                # from one naming no family at all. A nested dflash-*.gguf counts
                # as one of those weights, since only a root-level file is a
                # sidecar here.
                others = [
                    Path(name).name for name in names if not _is_root_dflash_drafter_path(name)
                ]
                ranked.extend(
                    (dflash_repo_preference_key(name, weight_name, others), snap / name)
                    for name in names
                    if _is_root_dflash_drafter_path(name)
                )
            for _, candidate in sorted(ranked, key = lambda entry: entry[0]):
                if not candidate.is_file():
                    continue
                # The ranking above works off names, and dflash- is only a naming
                # convention: a cached weight whose basename happens to start with
                # it would be launched as --model-draft and refused at startup.
                # Same header rule, same helper, as the local scan, so an offline
                # reuse and a local scan cannot disagree about what a sidecar is.
                # Skipped rather than fatal, since the snapshot may hold a real one.
                if not is_dflash_architecture(str(candidate)):
                    logger.info(
                        "Ignoring cached DFlash candidate %s: general.architecture is not dflash",
                        candidate,
                    )
                    continue
                # Same whole-set rule _companion_snapshot_sibling applies, for the
                # same reason: llama-server resolves the sibling shards from this
                # one's directory, and what this lookup returns is handed straight
                # back as the drafter with no fetch left to complete it. Half a
                # set reads as a valid header and then cannot be opened, so the
                # load quietly drops speculation. Skipped rather than fatal, since
                # another snapshot may hold the complete copy.
                if not _drafter_split_is_complete(candidate):
                    logger.info(
                        "Ignoring cached DFlash candidate %s: split shard set is incomplete",
                        candidate,
                    )
                    continue
                return str(candidate)
        except Exception as exc:
            logger.debug("Cached DFlash drafter lookup failed for %s: %s", hf_repo, exc)
        return None

    def _download_dflash(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        near_path: Optional[str] = None,
        binary: Optional[str] = None,
    ) -> Optional[str]:
        """Download the published DFlash sidecar, preferring its Q8_0 copy.

        Unlike the ~11 GB DSpark sidecar, which is why that one is opt-in, the
        published DFlash sidecar is ~1.5 GiB and already ships in the model's own
        GGUF repo, so Auto fetches it the same way it fetches the MTP drafter.
        Still gated on ``supports_dflash``: a binary with no usable
        ``--spec-type draft-dflash`` falls back, so the download would never be
        opened. A raised probe still fetches, since launch re-probes and may yet
        engage.
        """

        weight_name = Path(near_path).name if near_path else None
        # Whatever a previous load concluded, this one is asking again.
        self._dflash_retry_needed = False

        def _mark_retry_needed() -> None:
            self._dflash_retry_needed = True

        # Basenames whose header turned out not to say dflash. A name lands here
        # only once the file is readable on disk, and _pick_dflash then skips it,
        # so a repo whose best-ranked candidate is an impostor still reaches the
        # real sidecar behind it instead of the search giving up on the repo.
        rejected: set[str] = set()

        def _pick_dflash(candidates: list[str]) -> Optional[str]:
            # Ranked against the weight being loaded, not by precision alone: a
            # repo hosting two families ships a sidecar per family, and
            # dflash-model-A-Q8_0.gguf beats the generic dflash-kquant.gguf on
            # precision, so model B would download and launch model A's drafter.
            # The rest of the listing supplies the neighbouring weights that make
            # a foreign sidecar recognisable (a sidecar naming no family at all
            # stays eligible, which is what the published one does).
            from utils.models.drafters import (
                dflash_repo_preference_key,
                split_listing_is_complete,
            )

            # Root level only, as the local scan is: a nested dflash-*.gguf is an
            # ordinary weight, and offering it here spends its entire download
            # before the header check can turn it away.
            others = [
                Path(name).name
                for name in candidates
                if name.lower().endswith(".gguf") and not _is_root_dflash_drafter_path(name)
            ]
            # Same bound as dflash_plan_files: dflash- is a prefix real weights carry,
            # the header only reads once the bytes are here, and a drafter is a few
            # layers of its target. An unlisted size leaves the candidate in, as before.
            sizes = self._remote_root_gguf_sizes(hf_repo, hf_token)
            try:
                target_bytes = (self._get_gguf_size_bytes(near_path) or 0) if near_path else 0
            except OSError:
                target_bytes = 0
            files = sorted(
                (
                    name
                    for name in candidates
                    if _is_root_dflash_drafter_path(name)
                    and Path(name).name not in rejected
                    # Before the ranking, as dflash_plan_files is: the fetch refuses a
                    # half-listed set, and returning it ends the loop.
                    and split_listing_is_complete(candidates, name)
                    # Whole set, not the picked shard: each half of a split weight can
                    # sit under the target while the set does not.
                    and not (
                        target_bytes and _drafter_set_bytes(sizes, Path(name).name) >= target_bytes
                    )
                ),
                key = lambda name: dflash_repo_preference_key(name, weight_name, others),
            )
            return files[0] if files else None

        def _validated(path: Optional[str]) -> Optional[str]:
            """``path`` back iff its header really says ``dflash``.

            _is_dflash_drafter_path is a FILENAME test, deliberately (the prefix
            form is the only one accepted, so a sidecar cannot double as a
            selectable main model in the quant picker), which means a remote repo
            holding an ordinary weight called dflash-*.gguf passes it. The local
            scan settles that with the architecture in the header; the remote
            paths have to as well, or the load spends gigabytes of download on a
            file llama-server then refuses as --model-draft. Same helper as
            detect_dflash_file so the two rules cannot drift.
            """
            from utils.models.drafters import is_dflash_architecture

            if not path:
                return None
            if is_dflash_architecture(path):
                return path
            rejected.add(Path(path).name)
            logger.warning("Ignoring DFlash candidate %s: general.architecture is not dflash", path)
            return None

        # Retried rather than abandoned: every rejection removes one name from the
        # pool, so the next pick returns a different file and the scan ends at the
        # last candidate (or at the first real sidecar). Answers already seen end
        # it too, so a scan that ignores the pool cannot spin here.
        cached: Optional[str] = None
        seen_siblings: set[str] = set()
        while near_path:
            sibling = _companion_snapshot_sibling(near_path, _pick_dflash)
            if sibling is None or sibling in seen_siblings:
                break
            seen_siblings.add(sibling)
            cached = _validated(sibling)
            if cached:
                break
        # _cached_repo_dflash_drafter applies the same header check to its own
        # candidates, so anything it hands back is already validated.
        if not cached and _hf_env_offline():
            cached = self._cached_repo_dflash_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
                near_path = near_path,
            )
        try:
            if not self.probe_server_capabilities(binary).get("supports_dflash"):
                logger.warning(
                    "Skipping the DFlash sidecar download: llama-server has no usable "
                    "--spec-type draft-dflash, so this load falls back to no speculative "
                    "decoding. Run `unsloth studio update`, then reload."
                )
                # A sidecar already on disk is still reported, for the same reason as
                # the DSpark path: the route rediscovers it on every Apply, so
                # answering None would make the reuse check compare it against a
                # launched None and reload the same server each time.
                # _build_speculative_flags re-checks the capability and still falls back.
                return cached
        except Exception as exc:
            logger.debug("DFlash capability probe failed before the sidecar fetch: %s", exc)

        if cached:
            logger.info("Reusing cached DFlash drafter: %s", cached)
            return cached
        outcome: dict = {}
        found: Optional[str] = None
        # The header can only be read once the bytes are here, so validation is a
        # post-fetch step and a rejection has to be able to fall through to the
        # next candidate rather than end the search. Bounded the same way as the
        # reuse scan above: a fetch that answers with a file already rejected has
        # nothing further to offer.
        fetched: set[str] = set()
        while True:
            candidate = self._download_companion_gguf(
                hf_repo = hf_repo,
                hf_token = hf_token,
                pick = _pick_dflash,
                label = "DFlash drafter",
                near_path = near_path,
                outcome = outcome,
                # Not a header rejection: that candidate is settled and the loop moves
                # on. Only the Hub dropping out leaves a real sidecar unfetched.
                on_transient_failure = _mark_retry_needed,
            )
            if candidate is None or candidate in fetched:
                break
            fetched.add(candidate)
            found = _validated(candidate)
            if found:
                break
        # Distinguishes a repo that ships no sidecar from a fetch that failed and
        # could yet succeed. A repo whose only dflash-*.gguf is an ordinary weight
        # exits the loop through a listing that picked nothing, which records the
        # same permanent absence: there is nothing usable here to fetch next time.
        self._dflash_sidecar_absent = outcome.get("listed") is False
        return found

    @staticmethod
    def _remote_root_gguf_sizes(hf_repo: str, hf_token: Optional[str] = None) -> dict[str, int]:
        """Root-level GGUF basenames to their listed byte size, {} when unavailable.

        list_repo_files answers names only, so the size bound needs the metadata
        listing. Best effort: an empty map leaves every candidate eligible, which is
        the behaviour before the bound existed.
        """
        try:
            from huggingface_hub import model_info
            info = model_info(hf_repo, token = hf_token, files_metadata = True)
            return {
                name: int(getattr(sibling, "size", 0) or 0)
                for sibling in (getattr(info, "siblings", None) or [])
                if isinstance(name := getattr(sibling, "rfilename", None), str) and "/" not in name
            }
        except Exception as exc:
            logger.debug("Could not size the DFlash candidates for %s: %s", hf_repo, exc)
            return {}

    def _dspark_wins_auto(
        self,
        *,
        binary: Optional[str],
        dspark_draft_path: Optional[str],
        spec_canon: str,
        extra_args: Optional[list[str]],
        caps: Optional[Callable[[Optional[str]], dict]] = None,
    ) -> bool:
        """Whether Auto will actually resolve this load to DSpark.

        A DSpark path on its own does not answer that. _download_dspark reports
        an already-cached sidecar even when the binary has no usable
        ``--spec-type draft-dspark`` (deliberately: the route rediscovers it on
        every Apply, and answering None there would reload the same server each
        time), so the capability has to be applied by everything that reads the
        path as "DSpark is what Auto picks". Without it a binary that supports
        DFlash but not DSpark stands down on the DFlash fetch for a sidecar it
        can never launch and the load ends up with no drafter at all.

        A raised probe answers False, which keeps Auto on its other options
        exactly as the promotion does. probe_server_capabilities caches on the
        binary's revision, so asking here and at the promotion is one probe.
        """
        if spec_canon != "auto" or not dspark_draft_path:
            return False
        if _extra_args_set_spec_type(extra_args):
            return False
        try:
            # Through the caller's getter when it has one, so an inconclusive probe
            # still latches for this launch (#8317) even though the promotion moved
            # in here.
            probe = caps or self.probe_server_capabilities
            return bool(probe(binary).get("supports_dspark"))
        except Exception as exc:
            logger.debug("DSpark capability probe failed during Auto: %s", exc)
            return False

    def _resolve_launch_mmproj_path(
        self, *, model_path: str, mmproj_path: Optional[str]
    ) -> Optional[str]:
        """Return mmproj_path iff it exists on disk AND matches the model family.

        None if mmproj_path is None, missing, or family-mismatched.
        """
        if not mmproj_path:
            return None

        mmproj = Path(mmproj_path)
        if not mmproj.is_file():
            logger.warning(f"mmproj file not found: {mmproj_path}")
            return None

        from utils.models.model_config import mmproj_matches_model_family

        if not mmproj_matches_model_family(model_path, str(mmproj)):
            logger.warning(
                f"mmproj does not match model family: model={Path(model_path).name} "
                f"mmproj={mmproj.name}"
            )
            return None

        return str(mmproj)

    def _mmproj_vram_bytes(self, launch_mmproj_path: Optional[str]) -> int:
        """Return resolved mmproj VRAM bytes, or 0 when absent/unreadable."""
        if not launch_mmproj_path:
            return 0
        try:
            return self._get_gguf_size_bytes(launch_mmproj_path)
        except OSError as e:
            logger.debug(f"Could not size mmproj {launch_mmproj_path}: {e}")
            return 0

    def _inherited_mmproj_soft_overhead(self, mmproj_bytes: int, *, on_host: bool) -> int:
        """Runtime buffer allowance for a projector that arrived only through the env.

        The resolved projector gets this term in the fit's ``soft_overhead``, but that
        one is gated on ``effective_is_vision``, itself gated on ``launch_mmproj_path``,
        so a ``LLAMA_ARG_MMPROJ`` projector is charged its file size and nothing for the
        ~1.3x the encoder really allocates. Understating the footprint is the direction
        that claims a fit which is not there.

        VRAM arm only: on the host arm the resolved projector is priced raw too.
        """
        if mmproj_bytes <= 0 or on_host:
            return 0
        return int(mmproj_bytes * (self._MMPROJ_VRAM_SAFETY - 1.0))

    def _resolve_launch_mtp_path(
        self,
        *,
        mtp_draft_path: Optional[str],
        drafter_label: str = "MTP",
    ) -> Optional[str]:
        """Return mtp_draft_path iff it exists on disk, else None.

        No family check needed: the drafter is only ever auto-resolved from
        the same repo as the main GGUF (see _download_mtp).
        """
        if not mtp_draft_path:
            return None
        if not Path(mtp_draft_path).is_file():
            logger.warning(f"{drafter_label} drafter file not found: {mtp_draft_path}")
            return None
        return str(mtp_draft_path)

    # ── Lifecycle ─────────────────────────────────────────────────

    # GGUF ``general.architecture`` values for diffusion / image models.
    # llama.cpp has no such architectures, so loading one as a chat model dies
    # with "unknown model architecture: '<arch>'". These match the patched
    # stable-diffusion.cpp / ComfyUI-GGUF enums. Unsloth publishes FLUX and
    # Qwen-Image GGUFs under
    # https://huggingface.co/collections/unsloth/unsloth-diffusion-ggufs.
    # Matched exactly (not a substring) so a chat arch containing "wan"/"sd1"
    # (e.g. "taiwan") isn't misrouted to Images.
    _IMAGE_ARCHES = frozenset(
        (
            "qwen_image",
            "flux",
        )
    )
    # Archs shared by more than one family, so the header alone does NOT say whether the
    # Images page can run the file: Z-Image's DiT is a Lumina2 derivative, so its GGUFs
    # declare "lumina2" too (measured on unsloth/Z-Image-Turbo-GGUF/z-image-turbo-Q2_K.gguf
    # and on calcuis/lumina-gguf). ``routes.models._arch_to_task`` resolves these from the
    # repo id and the filename and tags the rest ``image-diffusion-unsupported``, hiding
    # them from the Images picker, so the refusal must run the SAME resolution before it
    # names that page -- e.g. ``neta-art/neta-lumina-gguf/checkpoint-e3_s9658-*.gguf``
    # declares "lumina2" and resolves to no family ("lumina-2" is not aliased to bare
    # "lumina"). Mirrors ``routes.models._AMBIGUOUS_DIFFUSION_GGUF_ARCHS``.
    _AMBIGUOUS_IMAGE_ARCHES = frozenset(("lumina2",))
    # Text-to-video archs the Video page can offer. Split from the image set so the refusal
    # names Video: sending a Wan / LTX-2 GGUF to Images is a second dead end.
    _VIDEO_ARCHES = frozenset(
        (
            "ltxv",
            "wan",
        )
    )
    # Media archs Unsloth recognises but NO page can run, so the refusal must not promise
    # one. Mirrors ``routes.models._UNSUPPORTED_DIFFUSION_GGUF_ARCHS``, which tags these
    # ``image-diffusion-unsupported`` and so hides them from the Images AND Video pickers.
    #   * "cosmos": no VideoFamily exists at all (``detect_video_family`` returns None for
    #     every cosmos repo id and for override="cosmos"), and the published cosmos GGUFs
    #     are Cosmos-Predict2-14B-Text2Image, which Images cannot assemble either.
    #   * "hyvid": HunyuanVideo 1.0 has no VideoFamily, and the 1.5 GGUFs that do map to
    #     one are still tagged unsupported (that family ships no ``gguf_repo``).
    #   * "sd1" / "sd3" / "sdxl" / "aura" / "hidream": unsupported on the image side for
    #     the same reason, so "use the Images page" was always an empty promise.
    # Kept inside _DIFFUSION_ARCHES so the pre-launch refusal still fires, it just names no
    # destination. Mirrors the whole set: a partial mirror leaves the same dead end.
    _UNRUNNABLE_MEDIA_ARCHES = frozenset(
        (
            "cosmos",
            "hyvid",
            "sd1",
            "sd3",
            "sdxl",
            "aura",
            "hidream",
        )
    )
    _DIFFUSION_ARCHES = (
        _IMAGE_ARCHES | _AMBIGUOUS_IMAGE_ARCHES | _VIDEO_ARCHES | _UNRUNNABLE_MEDIA_ARCHES
    )
    # TTS archs llama.cpp cannot load (CSM support is only on an unmerged upstream branch). One
    # shared definition, so this gate and the listing classifier cannot drift.
    _SPEECH_ARCHES = _SPEECH_GGUF_ARCHS

    # Not architectures: the literal placeholders gguf-connector writes into
    # general.architecture for its diffusion GGUFs (gguf-org/flux2-dev-gguf and
    # calcuis/cosmos-predict2-gguf both declare "pig"); ComfyUI-GGUF special cases the same
    # two. llama.cpp knows neither, so without this they slip past the arch sets and die in
    # llama-server as the opaque failure this preflight exists to prevent.
    _PLACEHOLDER_ARCHES = frozenset(("pig", "cow"))

    @staticmethod
    def _video_arch_is_pickable(
        arch: Optional[str], gguf_path: Optional[str], model_identifier: Optional[str]
    ) -> bool:
        """Whether the Video page would actually OFFER this GGUF.

        Same fixed order ``_arch_to_task`` asks in: the ARCHITECTURE first, since some map
        straight to a family (``detect_video_family("", override = "ltxv")`` resolves LTX-2
        with no name to go on), then the repo id, then the filename. Whatever resolves must
        not be an MoE (the GGUF loader cannot assemble those) and must be buildable by the
        video engine -- bare "wan" resolves nothing and QuantStack/Wan2.2-T2V-A14B-GGUF
        resolves an MoE, so neither is promised the page."""
        try:
            from core.inference.video_families import detect_video_family

            from routes.models import _video_family_buildable

            fam = detect_video_family("", override = (arch or "").strip().lower() or None)
            if fam is None:
                for needle in (model_identifier, os.path.basename(gguf_path or "")):
                    if not needle:
                        continue
                    fam = detect_video_family(needle)
                    if fam is not None:
                        break
            if fam is None:
                return False
            return not getattr(fam, "is_moe", False) and _video_family_buildable(fam)
        except Exception as e:  # noqa: BLE001 -- never lose the page over a probe failure
            logger.debug("Family probe failed for video arch: %s", e)
            return True

    @staticmethod
    def _ambiguous_image_arch_is_pickable(
        gguf_path: Optional[str], model_identifier: Optional[str]
    ) -> bool:
        """Whether the Images page would actually OFFER this shared-arch GGUF.

        The same three questions ``routes.models._arch_to_task`` asks in its
        ``_AMBIGUOUS_DIFFUSION_GGUF_ARCHS`` branch, over the same evidence (repo id, then
        filename): does a family resolve, can a GGUF transformer be assembled for it, can an
        engine on THIS host build it. Both sides must answer alike -- the picker's answer is
        what decides whether the row the refusal points at exists.

        Imported lazily inside the function since ``routes`` imports this module, so the
        canonical classifier cannot be imported from here.

        Fails OPEN on a probe error, like every family probe on the listing side: naming the
        page is a nicety, not worth losing over a broken import."""
        try:
            from core.inference.diffusion_engine_router import family_buildable_here
            from core.inference.diffusion_families import (
                detect_family_for_pick,
                family_gguf_loadable,
            )

            for needle in (model_identifier, os.path.basename(gguf_path or "")):
                if not needle:
                    continue
                fam = detect_family_for_pick(needle)
                if fam is not None:
                    return family_gguf_loadable(fam) and family_buildable_here(
                        fam, model_kind = "gguf"
                    )
            return False
        except Exception as e:  # noqa: BLE001 -- never lose the page over a probe failure
            logger.debug("Family probe failed for ambiguous image arch: %s", e)
            return True

    def _non_chat_gguf_refusal(self, gguf_path: str) -> Optional[str]:
        """Why this GGUF cannot be a chat model, decided from its own header BEFORE
        llama-server is launched; None when there is no such verdict.

        Otherwise a media GGUF opened in a chat runs the whole download-and-launch path only
        to die in llama-server as "llama-server failed to start", with no hint that the file
        was never a chat model (the reported Video-model case).

        The header alone is enough to be certain, in two ways:

        * A declared architecture in the image / video sets. llama.cpp has no such
          architectures, so this is exactly the failure it would hit, one launch earlier.
        * NO ``general.architecture`` at all -- a mandatory key for anything llama.cpp can
          load, and Unsloth's video GGUFs (MiniMax-H3) carry a bare tensor header with zero
          KV pairs, so they never reach the arch test. Gated on ``_gguf_header_parsed`` so a
          read that FAILED still gets its chance in llama-server.

        Naming the destination page is the point, so when the architecture does not say
        which it is, the family detectors are asked about the repo id and the filename."""
        arch = (self._architecture or "").strip().lower()
        # A declared media arch is the whole answer, and it is KV #0 in every GGUF measured,
        # so the remote probe's prefix can carry it even where bulkier later metadata leaves
        # the walk unfinished. The walk still gates the no-architecture fallback below, the
        # one case where an incomplete read is indistinguishable from declaring nothing.
        if (
            arch not in self._DIFFUSION_ARCHES
            and not is_speech_gguf_architecture(arch)
            and not getattr(self, "_gguf_header_parsed", False)
        ):
            return None
        if arch in self._PLACEHOLDER_ARCHES:
            # Names no architecture, so treat it like a GGUF that declares none and let the
            # name-based branch below name a page.
            arch = ""
        if arch:
            if is_speech_gguf_architecture(arch):
                # Points at the Transformers build, not this file on the Audio page: that page
                # cannot list a speech GGUF either, so it would promise a row that is not there.
                return (
                    "This is a text-to-speech GGUF, which llama.cpp cannot load: it has no "
                    "CSM decoder. Run the model's Transformers build (for example "
                    "unsloth/csm-1b) from the Audio page instead."
                )
            if arch in self._UNRUNNABLE_MEDIA_ARCHES:
                return (
                    f"This is an image / video generation GGUF (architecture '{arch}'), "
                    "which cannot run as a chat model. Unsloth Studio cannot run this "
                    "architecture at all: neither the Images page nor the Video page "
                    "accepts it."
                )
            if arch in self._VIDEO_ARCHES:
                # Shared like the image archs: the canonical classifier resolves a
                # VideoFamily by name and rejects an MoE the GGUF loader cannot assemble,
                # so "wan" alone does not mean the Video page will list it.
                if self._video_arch_is_pickable(arch, gguf_path, self._model_identifier):
                    return (
                        f"This is a text-to-video GGUF (architecture '{arch}'), which "
                        "cannot run as a chat model. Open it from the Video page instead."
                    )
                return (
                    f"This is a text-to-video GGUF (architecture '{arch}'), which cannot "
                    "run as a chat model. Unsloth cannot assemble this particular model "
                    "from a GGUF, so the Video page does not list it either."
                )
            if arch in self._IMAGE_ARCHES:
                return (
                    f"This is an image-generation GGUF (architecture '{arch}'), which "
                    "cannot run as a chat model. Open it from the Images page instead."
                )
            if arch in self._AMBIGUOUS_IMAGE_ARCHES:
                if self._ambiguous_image_arch_is_pickable(gguf_path, self._model_identifier):
                    return (
                        f"This is an image-generation GGUF (architecture '{arch}'), which "
                        "cannot run as a chat model. Open it from the Images page instead."
                    )
                return (
                    f"This is an image-generation GGUF (architecture '{arch}'), which "
                    "cannot run as a chat model. Unsloth could not tell which model family "
                    f"this file belongs to -- '{arch}' is shared by several -- so the "
                    "Images page cannot assemble it either."
                )
            return None

        # A shard past the first of a gguf-split set declares no architecture (shard 1 holds
        # it) but is no media GGUF, and llama.cpp's own "model must be loaded with the first
        # split" is more use than "carries no metadata". Needs split.no > 0 AND nothing
        # declared: shard 1 carries the split keys too, and a placeholder arch is blanked
        # above, so a looser test would wave through the very files the placeholder handling
        # exists to catch. Only reachable with a hand-written variant anyway: every producer
        # here strips the shard suffix and sorts, landing on shard 1.
        if self._architecture is None and (self._gguf_split_index or 0) > 0:
            return None

        # No architecture declared: not loadable by llama-server whatever it is. Say which
        # page runs it when the identifiers make that clear.
        needles = [n for n in (self._model_identifier, os.path.basename(gguf_path or "")) if n]
        # Naming a page answers to the same predicates as the arch branches above: a family
        # that resolves is not enough, the picker also drops an MoE it cannot assemble and a
        # family no installed engine can build. So detect first, then ask whether the page
        # would list it, rather than pointing at a page the model is missing from.
        try:
            from core.inference.video_families import detect_video_family
            if any(detect_video_family(n) is not None for n in needles):
                if self._video_arch_is_pickable(None, gguf_path, self._model_identifier):
                    return (
                        "This is a text-to-video model, not a chat model: its GGUF carries "
                        "no llama.cpp model metadata, so llama-server cannot load it. Open "
                        "it from the Video page instead."
                    )
                return (
                    "This is a text-to-video model, not a chat model, and its GGUF carries "
                    "no llama.cpp model metadata. Unsloth cannot assemble this particular "
                    "model from a GGUF either, so the Video page does not list it."
                )
        except Exception as e:  # noqa: BLE001 -- naming the page is a nicety, never a gate
            logger.debug("Video family probe failed during non-chat GGUF preflight: %s", e)
        try:
            from core.inference.diffusion_families import detect_family
            if any(detect_family(n) is not None for n in needles):
                if self._ambiguous_image_arch_is_pickable(gguf_path, self._model_identifier):
                    return (
                        "This is an image-generation model, not a chat model: its GGUF "
                        "carries no llama.cpp model metadata, so llama-server cannot load "
                        "it. Open it from the Images page instead."
                    )
                return (
                    "This is an image-generation model, not a chat model, and its GGUF "
                    "carries no llama.cpp model metadata. Unsloth cannot assemble this "
                    "particular model from a GGUF either, so the Images page does not list "
                    "it."
                )
        except Exception as e:  # noqa: BLE001
            logger.debug("Image family probe failed during non-chat GGUF preflight: %s", e)
        return (
            "This GGUF carries no llama.cpp model metadata (no general.architecture), so "
            "llama-server cannot load it as a chat model. Image and video GGUFs are "
            "packaged this way -- try the Images or Video page, or pick a chat GGUF."
        )

    # Distro package names for the shared libraries the Linux prebuilt links,
    # so the loader failure below can say what to install.
    _SHARED_LIB_PACKAGES = {
        "libgomp.so.1": " (Debian/Ubuntu: libgomp1, Fedora/RHEL: libgomp)",
    }

    # Shared objects Unsloth ships itself, next to llama-server in build/bin
    # (see runtime_payload_health_groups in install_llama_prebuilt.py, and
    # _llama_server_env_for_binary which puts that dir on the platform's
    # loader search path -- DYLD_LIBRARY_PATH on macOS). No
    # distro packages these, so a loader failure naming one means the managed
    # runtime is incomplete or mismatched, not that something must be installed.
    _BUNDLED_LIB_PREFIXES = ("libllama", "libggml", "libmtmd")

    @staticmethod
    def _is_bundled_llama_library(lib: str) -> bool:
        # The loader prints a bare soname when the file is absent but a full
        # path when it found and rejected it, so compare on the basename.
        return os.path.basename((lib or "").strip()).startswith(
            LlamaCppBackend._BUNDLED_LIB_PREFIXES
        )

    @staticmethod
    def _is_unsloth_managed_binary(binary: Optional[str]) -> bool:
        """Would `unsloth studio update` actually replace ``binary``?

        A pinned LLAMA_SERVER_PATH, or a llama-server found on PATH, is
        explicitly unmanaged (update_flow.managed_install_root returns None),
        so telling the user to update Unsloth's runtime cannot repair it.
        Unknown binary (callers that pass nothing) keeps the managed default.
        """
        if not binary:
            return True
        try:
            from utils.llama_cpp_path_settings import custom_llama_cpp_path_source
            from utils.llama_cpp_update import (
                _active_install_is_local_link,
                _llama_install_root,
            )

            # A Settings-selected checkout is user-owned even when its ordinary
            # `llama.cpp` directory name or prebuilt marker resembles our tree.
            if custom_llama_cpp_path_source() == "studio":
                return False
            # A --with-llama-cpp-dir tree is the user's own checkout reached
            # through a symlinked llama.cpp dir. The updater refuses to write
            # through that link, so it cannot repair the binary either, and its
            # entrypoint is theirs to keep.
            if _active_install_is_local_link(binary):
                return False
            return _llama_install_root(binary) is not None
        except Exception:
            return True

    @staticmethod
    def _is_llama_install_tree(binary: Optional[str]) -> bool:
        """Does ``binary`` sit in a llama.cpp tree Unsloth resolved for itself?

        The pre-existing half of the question above, kept separate because the
        two are not the same: a --with-llama-cpp-dir checkout IS the active
        install (so anything that only needs to read or copy from it still
        applies) while not being something the updater can replace.
        """
        if not binary:
            return True
        try:
            from utils.llama_cpp_update import _llama_install_root
            return _llama_install_root(binary) is not None
        except Exception:
            return True

    @staticmethod
    def _is_library_path(lib: str) -> bool:
        # glibc's own discriminator is `strchr (name, '/') == NULL`
        # (elf/dl-load.c): a slash anywhere means the name is a pathname and no
        # search happens, so a relative DT_NEEDED is as exact as an absolute
        # one. os.sep would be platform-bound and this string comes from
        # whatever host ran llama-server, so match both separators.
        lib = (lib or "").strip()
        return "/" in lib or "\\" in lib

    @staticmethod
    def _missing_library_message(lib: str, binary: Optional[str] = None) -> str:
        """The loader could not FIND ``lib`` ("cannot open shared object file")."""
        if LlamaCppBackend._is_bundled_llama_library(lib):
            if LlamaCppBackend._is_unsloth_managed_binary(binary):
                return (
                    f"llama-server could not start: {lib} is part of Unsloth's own "
                    "llama.cpp runtime and is missing from the install. Run "
                    "`unsloth studio update` to reinstall it, then load the model "
                    "again."
                )
            return (
                f"llama-server could not start: {lib} is part of the llama.cpp "
                "runtime that the llama-server binary in use was built with. That "
                "binary is a custom install Unsloth does not manage, so reinstall "
                "or rebuild that llama.cpp, then load the model again."
            )
        # A bare soname means the loader searched the standard directories,
        # which is what a package populates. Any name carrying a separator is a
        # pathname the loader opened directly (e.g. a vendor .so under /opt), so
        # one exact file is absent and no package will put it there.
        if LlamaCppBackend._is_library_path(lib):
            _remedy = (
                "run `unsloth studio update`"
                if LlamaCppBackend._is_unsloth_managed_binary(binary)
                else "reinstall or rebuild that custom llama.cpp"
            )
            return (
                f"llama-server could not start: {lib} is missing from that exact "
                f"location. Restore it, or {_remedy}, then load the model again."
            )
        return (
            f"llama-server could not start: the system library "
            f"{lib or 'it needs'} is missing. Install it with your package "
            f"manager{LlamaCppBackend._SHARED_LIB_PACKAGES.get(lib, '')}, "
            "then load the model again."
        )

    @staticmethod
    def _unloadable_library_message(
        lib: str,
        reason: str,
        binary: Optional[str] = None,
    ) -> str:
        """The loader FOUND ``lib`` and refused it: the same "error while
        loading shared libraries" line also carries "file too short", "invalid
        ELF header", "wrong ELF class", "cannot open shared object file:
        Permission denied", ... Installing a package is the wrong advice there
        -- the file is already present."""
        detail = f" ({reason})" if reason else ""
        if LlamaCppBackend._is_bundled_llama_library(lib):
            if LlamaCppBackend._is_unsloth_managed_binary(binary):
                return (
                    f"llama-server could not start: {lib}, part of Unsloth's own "
                    f"llama.cpp runtime, could not be loaded{detail}. The install "
                    "is incomplete or mismatched. Run `unsloth studio update` to "
                    "reinstall it, then load the model again."
                )
            return (
                f"llama-server could not start: {lib}, part of the llama.cpp "
                "runtime that the llama-server binary in use was built with, "
                f"could not be loaded{detail}. That binary is a custom install "
                "Unsloth does not manage, so reinstall or rebuild that "
                "llama.cpp, then load the model again."
            )
        return (
            f"llama-server could not start: the library {lib or 'it needs'} "
            f"could not be loaded{detail}. Reinstall or update whatever "
            "provides it, then load the model again."
        )

    @staticmethod
    def _exec_path_for_launch(binary: Optional[str]) -> Optional[str]:
        """The path to actually execute, resolving a managed macOS entrypoint.

        SIP purges DYLD_* while starting the protected /bin/sh a shell
        entrypoint runs under, so the loader path we build for the child would
        not survive the wrapper's own exec (#8566). Only OUR entrypoint is
        resolved: someone's own wrapper may export backend variables or do
        other setup before its exec line, and skipping past it would silently
        drop that.

        The test is the wrapper's shape, not where it came from. Provenance is
        not enough (_llama_install_root treats the directory named by
        UNSLOTH_LLAMA_CPP_PATH as the active install with no marker file
        needed, so somebody's own checkout reads as managed), and neither is an
        explicit LLAMA_SERVER_PATH pin: pointing that at the installer's own
        entrypoint is a supported configuration, and refusing to resolve it
        just because it was named put the launch back through /bin/sh and
        reproduced the very bug this fixes. An installer-template wrapper does
        nothing but exec its target, so resolving past one is never a loss,
        however it was reached.
        """
        if not binary or sys.platform != "darwin":
            return binary
        if not LlamaCppBackend._is_unsloth_managed_binary(binary):
            try:
                from utils.llama_cpp_path_settings import custom_llama_cpp_path_source
                if custom_llama_cpp_path_source() != "studio":
                    return binary
            except Exception:
                return binary
        if not _is_installer_entrypoint(binary):
            return binary
        # template_only: the outer entrypoint being ours says nothing about
        # what it points at. Resolve only through links that are also ours.
        return str(_resolve_llama_binary(binary, template_only = True))

    @staticmethod
    def _runtime_remedy(binary: Optional[str]) -> str:
        """The repair advice for ``binary``, by provenance.

        `unsloth studio update` cannot touch a pinned LLAMA_SERVER_PATH or a
        llama-server found on PATH, so those owners get told to rebuild theirs.
        """
        return (
            "run `unsloth studio update` to reinstall the llama.cpp runtime"
            if LlamaCppBackend._is_unsloth_managed_binary(binary)
            else "reinstall or rebuild that custom llama.cpp"
        )

    # A "tried:" list names every searched path, so the reason can run to
    # kilobytes. The glibc branch is capped to one line; cap this one too.
    _MACOS_REASON_CHARS = 300

    # A dyld install name is a path, and macOS PATH_MAX is 1024. Double it and
    # anything longer is not something the loader produced.
    _DYLD_LIB_NAME_MAX_CHARS = 2048

    @staticmethod
    def _plain_dyld_lib_name(lib: str) -> str:
        """Drop dyld's search directives from an install name.

        ``@rpath/libllama.dylib`` is a lookup token, not a location, so passing
        it through as a path makes _missing_library_message tell the user to
        restore a file at a directory that does not exist. The soname is what
        they can act on, and _is_bundled_llama_library already matches on it.
        """
        # Basename, not just the directive: "@loader_path/../Frameworks/x.dylib"
        # still reads as an exact location to _is_library_path.
        if lib.startswith(("@rpath/", "@loader_path/", "@executable_path/")):
            lib = os.path.basename(lib)
        # The name is quoted from untrusted output and lands in an HTTP error.
        # A real install name is well under this; without the cap, a wrapper
        # printing a 100000-character one turned a 200-character diagnosis into
        # a 100000-character API response. PATH_MAX on macOS is 1024, so this
        # only ever truncates something dyld could not have produced.
        if len(lib) > LlamaCppBackend._DYLD_LIB_NAME_MAX_CHARS:
            lib = lib[: LlamaCppBackend._DYLD_LIB_NAME_MAX_CHARS] + "..."
        return lib

    # Ten search paths at a long path each, with room to spare. Only ever cuts
    # text a real dyld reason does not produce.
    _DYLD_REASON_MAX_CHARS = 4000
    # How far past "Library not loaded:" to look for its Reason at all. Four
    # times the cap above, so a real reason preceded by a little noise is still
    # found whole.
    _DYLD_REASON_SCAN_CHARS = 16000
    # Candidates read out of one "tried:" list. dyld searches a bounded set of
    # paths; a list longer than this is not one it produced.
    _DYLD_MAX_CANDIDATES = 128

    # dyld announces itself at the start of a line: "dyld[1234]: ", the older
    # "dyld: ", or a crash report's "Termination Reason: ... DYLD". Structural
    # on purpose: "Referenced from:" and friends are words a wrapper or a GGUF
    # metadata string can carry, and were accepted as framing before.
    _DYLD_FRAMING_RE = re.compile(
        r"(?im)^[ \t]*(?:dyld(?:\[\d+\])?:|termination reason:.*\bdyld\b)"
    )

    @staticmethod
    def _dyld_reason_after(output: str, start: int) -> str:
        """The ``Reason:`` belonging to a dyld error, flattened to one line.

        Bounded to that line plus its indented continuations, and searched only
        after the "Library not loaded:" it explains: an unrelated earlier
        "Reason:" in llama.cpp's own output would otherwise be read as dyld's,
        and an unbounded read would swallow everything printed afterwards.

        Length-capped as well. dyld lists one candidate per search path, so a
        real reason is a couple of KB at most, but the text is whatever the
        child printed: a pathological one drives the candidate scan below into
        quadratic backtracking (100KB of "'a' (" measured at 6.3s, against
        0.0s before this change), and that scan runs on the event loop.
        """
        # Windowed, not just capped afterwards: dyld prints the reason directly
        # under the "Library not loaded:" line, so nothing useful lives further
        # out, and matching against the whole remaining output would materialise
        # a group as large as whatever the child printed (a 25MB reason was
        # measured at ~366MB peak RSS through the flatten below).
        window = output[start : start + LlamaCppBackend._DYLD_REASON_SCAN_CHARS]
        match = re.compile(
            r"reason:[ \t]*([^\r\n]*(?:\r?\n[ \t]+[^\r\n]*)*)",
            re.IGNORECASE,
        ).search(window)
        if not match:
            return ""
        return " ".join(match.group(1)[: LlamaCppBackend._DYLD_REASON_MAX_CHARS].split())

    @staticmethod
    def _dyld_tried_verdict(reason: str, binary: Optional[str]) -> str:
        """The verdict for the candidate that is ours, out of a "tried:" list.

        dyld reports ``tried: '<path>' (<verdict>), '<path>' (<verdict>), ...``
        over every search path, so the list routinely mixes "no such file" for
        our own bundle with "incompatible architecture" for a leftover Intel
        Homebrew copy. Prefer the candidate in the runtime's own lib dir, else
        the first one; with no list at all the reason stands as its own verdict.
        """
        lib_dir = ""
        if binary:
            try:
                lib_dir = str(_llama_lib_dir(binary))
            except (OSError, ValueError):
                lib_dir = ""
        # finditer with a count, not findall: the reason is already capped, but
        # a list built before the first useful match is work done for nothing.
        first: Optional[str] = None
        for index, match in enumerate(re.finditer(r"'([^']+)'\s*\(([^)]*)\)", reason)):
            if index >= LlamaCppBackend._DYLD_MAX_CANDIDATES:
                break
            path, verdict = match.group(1), match.group(2)
            if first is None:
                first = verdict
            if lib_dir and os.path.dirname(path) == lib_dir:
                return verdict
        return first if first is not None else reason

    @staticmethod
    def _classify_macos_loader_failure(output: str, binary: Optional[str]) -> Optional[str]:
        """dyld / Mach-O startup failures, or None when the output has none.

        Pure text matching on captured llama-server output, so this runs (and
        is tested) on any host, not only Darwin. Kept ahead of the returncode
        heuristics in the caller: a dyld diagnostic is a fact, while signal 9
        is a guess that would otherwise blame memory (#8566).

        Nothing here fires without dyld's own framing. llama.cpp echoes GGUF
        metadata to stderr while loading, so "Library not loaded:" or "Symbol
        not found" can be a model's own general.name; a bare match outranked
        the status-127 and signal-15 branches and answered a diffusion-GGUF
        load with library advice. Every branch is now gated on the same guard
        rather than each carrying its own.
        """
        if not output:
            return None
        if not LlamaCppBackend._DYLD_FRAMING_RE.search(output):
            return None
        lowered = output.lower()

        # Built for a newer macOS than the host. Same two markers as
        # install_llama_prebuilt.looks_like_macos_incompatibility, so the
        # installer and the runtime agree on the wording.
        if ("built for macos" in lowered and "newer than running os" in lowered) or (
            "symbol not found" in lowered and "mtlresidency" in lowered
        ):
            return (
                "llama-server could not start: the installed llama.cpp runtime "
                "was built for a newer version of macOS than this Mac is "
                f"running. Update macOS, or {LlamaCppBackend._runtime_remedy(binary)} "
                "to get a build that matches this OS."
            )

        # "Library not loaded: <path>", then the "Reason:" that belongs to it.
        not_loaded = re.search(
            r"library not loaded:[ \t]*([^\r\n]+)",
            output,
            re.IGNORECASE,
        )
        if not_loaded:
            lib = LlamaCppBackend._plain_dyld_lib_name(not_loaded.group(1).strip())
            reason = LlamaCppBackend._dyld_reason_after(output, not_loaded.end())
            # dyld4 gives a per-path verdict for every path it searched, so
            # judge ours. Scanning the flattened list would let a stale Intel
            # /usr/local copy decide the diagnosis for a dylib simply absent.
            verdict = LlamaCppBackend._dyld_tried_verdict(reason, binary)
            verdict_l = verdict.lower()
            # macOS refused the Mach-O itself. Unsigned or altered code is a
            # hard SIGKILL on Apple Silicon, so never send the user hunting for
            # a corrupt GGUF or for free memory.
            if "code signature" in verdict_l or "not valid for use in process" in verdict_l:
                return (
                    f"llama-server could not start: macOS rejected the code "
                    f"signature of {lib}. The file was modified or is "
                    f"incompletely signed, so {LlamaCppBackend._runtime_remedy(binary)}."
                )
            # dyld4 says "mach-o file, but is an incompatible architecture";
            # the older wording is "mach-o, but wrong architecture".
            if "incompatible architecture" in verdict_l or "wrong architecture" in verdict_l:
                return (
                    f"llama-server could not start: {lib} was built for a "
                    "different CPU architecture than this Mac. Its install is "
                    f"for the wrong platform, so {LlamaCppBackend._runtime_remedy(binary)}."
                )
            # "no such file" (the modern per-path "tried:" list) and the older
            # bare "image not found" both mean absent; anything else means dyld
            # found it and refused it, where reinstalling a package is wrong.
            if not verdict_l or "no such file" in verdict_l or "image not found" in verdict_l:
                return LlamaCppBackend._missing_library_message(lib, binary)
            return LlamaCppBackend._unloadable_library_message(
                lib, verdict[: LlamaCppBackend._MACOS_REASON_CHARS], binary
            )

        # A symbol mismatch with no missing file. Where it was expected decides
        # the remedy: a system framework means the build wants a newer macOS
        # (reinstalling cannot make the OS export it); one of ours means our
        # own files are from different builds.
        # Only with dyld's own framing: "Symbol not found" is ordinary English
        # any wrapper on any platform can print, and claiming it would also
        # suppress the output tail the fallback carries.
        if "symbol not found" in lowered and any(
            marker in lowered for marker in ("dyld[", "dyld:", "referenced from:", "expected in:")
        ):
            expected = re.search(r"expected in:\s*(?:<[^>]*>\s*)?([^\r\n]+)", output, re.IGNORECASE)
            # Newer dyld quotes the path. Unstripped, "'/System/..." fails the
            # prefix test below and a too-new build is blamed on a mismatched
            # install instead of on the OS.
            expected_path = expected.group(1).strip().strip("'\"") if expected else ""
            if expected_path.startswith(("/System/", "/usr/lib/")):
                return (
                    "llama-server could not start: it needs a symbol this "
                    "version of macOS does not provide, so the installed "
                    "llama.cpp runtime was built for a newer macOS. Update "
                    f"macOS, or {LlamaCppBackend._runtime_remedy(binary)} to get "
                    "a build that matches this OS."
                )
            return (
                "llama-server could not start: its llama.cpp libraries are from "
                "a different build than the llama-server binary (a symbol it "
                "needs is missing). The install is mismatched, so "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )
        return None

    # The macOS shell's message for EBADARCH, printed with the offending path
    # and typically exit 126. Never reaches dyld, so it carries no dyld framing
    # and has to be matched on its own; the wording is macOS-specific enough
    # (Linux says "cannot execute binary file") to be safe anywhere.
    _BAD_CPU_TYPE_RE = re.compile(r"(?im)^.*:[ \t]*bad cpu type in executable[ \t]*$")

    @staticmethod
    def _classify_llama_start_failure(
        output: str,
        gguf_path: Optional[str],
        model_identifier: Optional[str],
        returncode: Optional[int] = None,
        binary: Optional[str] = None,
        log_path: "Optional[Path | str]" = None,
        secrets: Sequence[Optional[str]] = (),
        extra_args: Optional[Sequence[str]] = None,
    ) -> str:
        """Classify, then redact, whatever the classification quoted.

        Redaction used to live only in the startup-diagnostics tail, so it
        covered the fallback and nothing else. Every other branch also quotes
        untrusted text -- a dyld message names the library it could not load,
        and that name comes from the child -- so a credential appearing there
        went out in the API error while the same credential in the tail was
        starred out. One boundary for every branch, rather than one per
        interpolation, which is the arrangement that let this through.

        Scrubbing twice is harmless: a redacted value no longer matches, so
        running the pass over an already-decorated message is a no-op.
        """
        return LlamaCppBackend._scrub_secret_values(
            LlamaCppBackend._classify_start_failure_text(
                output,
                gguf_path,
                model_identifier,
                returncode,
                binary,
                log_path,
                secrets,
                extra_args,
            ),
            secrets,
        )

    @staticmethod
    def _classify_start_failure_text(
        output: str,
        gguf_path: Optional[str],
        model_identifier: Optional[str],
        returncode: Optional[int] = None,
        binary: Optional[str] = None,
        log_path: "Optional[Path | str]" = None,
        secrets: Sequence[Optional[str]] = (),
        extra_args: Optional[Sequence[str]] = None,
    ) -> str:
        """Explain *why* llama-server failed to start, from its output.

        Several distinct failures otherwise collapse into the same opaque
        "invalid GGUF or out of memory" message. Worst case: a diffusion GGUF
        loaded as a chat model -- valid file, plenty of memory, but llama.cpp
        has no such architecture, so the user is told to free memory that was
        never the problem (#5842). Pick the most specific message we can.

        ``output`` is the child's stdout and is never trusted, not even when it
        looks like something this module wrote: the only guard on our own
        framing is the one in _with_startup_diagnostics, which reads the
        ``message`` we built ourselves. An earlier revision short-circuited here
        when the *output* carried that framing, so a wrapper printing
        "llama-server output:" as its first line had its stdout returned
        verbatim: no redaction, no 2000-character cap, no log path (50067
        characters with an environment dump's credentials intact, against 2136
        scrubbed for the same bytes without the heading).
        """
        lowered = (output or "").lower()

        # The dynamic loader kills llama-server before main(), so nothing below
        # matches and the fallback blames the file or memory instead. The Linux
        # prebuilt links libgomp.so.1, which a stock container does not ship.
        # glibc prints "<prog>: error while loading shared libraries: <object>:
        # <diagnostic>[: <strerror>]" (elf/dl-catch.c fatal_error). <object> is
        # echoed verbatim, so an absolute dependency under a directory with
        # spaces keeps them ("/opt/My Runtime/libfoo.so: file too short"):
        # split on the ": " that introduces the diagnostic, not on whitespace.
        missing_lib = re.search(
            r"error while loading shared libraries:[ \t]*([^\r\n]+?)"
            r"(?::[ \t]+([^\r\n]*))?[ \t]*\r?$",
            output or "",
            re.MULTILINE,
        )
        if missing_lib:
            _lib = missing_lib.group(1).strip()
            _reason = (missing_lib.group(2) or "").strip()
            # glibc omits the object name entirely on its own allocation
            # failures ("...shared libraries: cannot create search path array"),
            # so the first word is prose, not a library. Report it unnamed.
            if not (
                "/" in _lib or "\\" in _lib or any(_e in _lib for _e in (".so", ".dylib", ".dll"))
            ):
                return LlamaCppBackend._unloadable_library_message(
                    "", f"{_lib} {_reason}".strip(), binary
                )
            # Only "cannot open shared object file" means absent; the same line
            # reports corrupt/incompatible libraries too, which are present.
            # glibc appends strerror(errno) to that diagnostic, and only ENOENT
            # ("No such file or directory") means the file is not there: EACCES
            # ("Permission denied", seen with an absolute DT_NEEDED path, an
            # unreadable parent directory, SELinux mislabels or container
            # sandboxing) means it exists and cannot be opened, where installing
            # a package is the wrong advice. A truncated tail keeps the
            # missing-library reading.
            _reason_l = _reason.lower()
            _errno_text = ""
            if "cannot open shared object file:" in _reason_l:
                _errno_text = _reason_l.split("cannot open shared object file:", 1)[1].strip()
            if not _reason_l or (
                "cannot open" in _reason_l and (not _errno_text or "no such file" in _errno_text)
            ):
                return LlamaCppBackend._missing_library_message(_lib, binary)
            return LlamaCppBackend._unloadable_library_message(_lib, _reason, binary)

        # macOS. dyld shares no wording with glibc, so every loader failure on
        # Apple Silicon fell past the branch above into the generic GGUF/memory
        # message, and none of them is about either (#8566).
        macos_detail = LlamaCppBackend._classify_macos_loader_failure(output or "", binary)
        if macos_detail:
            return macos_detail

        # The executable itself is for the wrong architecture, so the shell
        # rejects it before dyld runs and there is no loader diagnostic at all.
        if LlamaCppBackend._BAD_CPU_TYPE_RE.search(output or ""):
            return (
                "llama-server could not start: the executable was built for a "
                "different CPU architecture than this Mac, so "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )

        # Argument parsing runs before the model is touched, so a rejected flag is
        # never about the GGUF or memory. llama.cpp prints two shapes, and the
        # difference matters to the reader: an unknown flag is a typo or a flag
        # this build does not have, while a rejected VALUE is the right flag used
        # wrongly. Both are otherwise diagnosed as an invalid GGUF or an OOM.
        # Bounded, unlike the branches above, which have to see a dyld line whose
        # library name can itself be the pathological part. llama.cpp prints an
        # argument error and exits, so it is always at the end of the capture.
        scan_tail = (output or "")[-_FAILURE_SCAN_TAIL_CHARS:]

        def _short(value: str) -> str:
            """A quoted fragment of the child's output, kept to a readable length.

            The capture is a run of non-whitespace, and nothing stops a wrapper on
            LLAMA_SERVER_PATH from printing 64 KiB of it, so this is the bound that
            keeps an API error the size of an error rather than the size of the
            capture. _STARTUP_TAIL_CHARS bounds the surrounding diagnostics; this
            bounds the one piece interpolated straight from the child.
            """
            value = value.strip()
            return (
                value
                if len(value) <= _FAILURE_QUOTE_CHARS
                else (value[:_FAILURE_QUOTE_CHARS] + "...")
            )

        unknown_arg = re.search(r"error:\s*invalid argument:\s*(\S+)", scan_tail, re.IGNORECASE)
        if unknown_arg:
            # Both owners in one sentence, because nothing reaching here says which
            # one it was: Unsloth emits its own flags conditionally on the capability
            # probe, and a binary swapped underneath a cached probe rejects one of
            # those just as readily as it rejects a typo from the box. Sending every
            # reader to the extra arguments would point most of them at a box they
            # never opened.
            return (
                f"llama-server does not recognise the argument "
                f"'{_short(unknown_arg.group(1))}'. Check it in this model's extra "
                f"arguments, or reinstall llama.cpp if you did not set it."
            )

        bad_arg_value = re.search(
            r'error while handling argument "([^"]+)":\s*([^\r\n]*)',
            scan_tail,
            re.IGNORECASE,
        )
        if bad_arg_value:
            _arg = _short(bad_arg_value.group(1))
            _why = _short(bad_arg_value.group(2) or "")
            # "stoi" is what llama.cpp surfaces when std::stoi throws on a value
            # that is not a number; nobody outside the C++ standard library reads
            # that as an error message.
            if _why.lower() in {"stoi", "stof", "stod", "stoul", "stoll"}:
                _why = "the value is not a number"
            _tail = f": {_why}" if _why else ""
            # Whose flag it is decides the advice. Unsloth emits its own options
            # conditionally on the capability probe, so a build that reads
            # "--flash-attn on" differently rejects a value the box never held, and
            # sending that reader to edit their extra arguments points them at a
            # setting they cannot use to fix it. Named here only when the extras
            # really do carry the flag; an alias spelling falls back to the neutral
            # wording rather than guessing.
            _owned_by_user = False
            if extra_args:
                from core.inference.llama_server_args import _flag_name
                _failed_flag = _flag_name(_arg)
                _owned_by_user = _failed_flag is not None and any(
                    _flag_name(str(token)) == _failed_flag for token in extra_args
                )
            if _owned_by_user:
                return (
                    f"llama-server rejected the value for '{_arg}'{_tail}. Fix it in "
                    f"the extra arguments for this model."
                )
            return (
                f"llama-server rejected the value for '{_arg}'{_tail}. Check it in "
                f"this model's extra arguments, or reinstall llama.cpp if you did "
                f"not set it."
            )

        # Tensor parallelism (--split-mode tensor) is arch-gated in llama.cpp;
        # unsupported architectures abort the load with this marker. Point the
        # user at the toggle instead of a generic invalid-GGUF/OOM message.
        if "split_mode_tensor not implemented" in lowered:
            return (
                "Tensor parallelism is not supported for this model's "
                "architecture. Turn off Tensor Parallelism in the model "
                "settings and reload."
            )

        # An older llama.cpp refusing a quantized KV cache under --split-mode tensor.
        # Naming the build is the point: the remedy is an update, where the generic
        # invalid-GGUF/OOM fallback sends the user to check their file or buy VRAM.
        # After the arch gate above, a different marker for a permanent per-model limit.
        if LlamaCppBackend._is_tensor_quant_kv_unsupported(lowered):
            return (
                "This llama.cpp build cannot use a quantized KV cache together "
                "with Tensor Parallelism (support landed in b9455). Update "
                "llama.cpp, or set the KV cache type to f16, or turn off Tensor "
                "Parallelism in the model settings."
            )

        # llama.cpp prints the four bytes it found with %c, so a binary header arrives as
        # unprintable characters; the generic fallback then blamed the user's memory (#8566).
        if "invalid magic characters" in lowered:
            # Not necessarily the main model: the projector and drafter report this too.
            base = os.path.basename(gguf_path) if gguf_path else ""
            named = f", loading {base}" if base else ""
            # A "._" model path proves the volume keeps xattrs in companions, whichever file
            # llama-server actually opened, and dot_clean is the remedy for the volume.
            remedy = (
                'This volume has no native extended attributes, so macOS keeps them in "._" '
                'companions: run "dot_clean -m" on the folder to remove them, or keep models '
                "on an APFS disk."
                if base.startswith("._")
                else "Re-download the model, or pick a different file."
            )
            return LlamaCppBackend._with_startup_diagnostics(
                f"llama-server opened a file that is not a GGUF{named}: it does not start with "
                "the GGUF magic. It may be that file or a companion loaded with it, such as a "
                f"vision projector or a drafter, which llama-server does not always name. {remedy}",
                output,
                log_path,
                secrets,
            )

        # Detect Ollama source up front so the arch branch can keep the
        # Ollama hint instead of the generic "unsupported arch" message.
        gguf = gguf_path or ""
        is_ollama = (
            ".studio_links" in gguf
            or os.sep + "ollama_links" + os.sep in gguf
            or os.sep + ".cache" + os.sep + "ollama" + os.sep in gguf
            or (model_identifier or "").startswith("ollama/")
        )

        # "unknown model architecture: '<arch>'": diffusion -> Images page,
        # Ollama -> Ollama hint, else a precise "unsupported" message. Exact
        # match so chat archs aren't misrouted.
        arch_match = re.search(r"unknown model architecture:\s*'([^']+)'", lowered)
        if arch_match:
            arch = arch_match.group(1)
            if is_speech_gguf_architecture(arch):
                # Same wording rule as the pre-launch refusal above: name the build that runs,
                # not a page this file will not appear on.
                return (
                    f"'{arch}' is a text-to-speech GGUF, which llama-server cannot run as a "
                    "chat/completion model. Run the model's Transformers build (for example "
                    "unsloth/csm-1b) from Unsloth's Audio page instead."
                )
            if arch in LlamaCppBackend._UNRUNNABLE_MEDIA_ARCHES:
                return (
                    f"'{arch}' is an image / video generation GGUF, which llama-server "
                    "cannot run as a chat/completion model. Unsloth Studio cannot run "
                    "this architecture at all: neither the Images page nor the Video "
                    "page accepts it."
                )
            if arch in LlamaCppBackend._VIDEO_ARCHES:
                if LlamaCppBackend._video_arch_is_pickable(arch, gguf_path, model_identifier):
                    return (
                        f"'{arch}' is a text-to-video GGUF, which llama-server "
                        "cannot run as a chat/completion model. Open it from "
                        "Unsloth's Video page instead of a chat."
                    )
                return (
                    f"'{arch}' is a text-to-video GGUF, which llama-server cannot run as "
                    "a chat/completion model. Unsloth cannot assemble this particular "
                    "model from a GGUF, so the Video page does not list it either."
                )
            if arch in LlamaCppBackend._IMAGE_ARCHES or (
                arch in LlamaCppBackend._AMBIGUOUS_IMAGE_ARCHES
                and LlamaCppBackend._ambiguous_image_arch_is_pickable(gguf_path, model_identifier)
            ):
                return (
                    f"'{arch}' is a diffusion (image-generation) GGUF, which "
                    "llama-server cannot run as a chat/completion model. Use "
                    "Unsloth's Images page to generate with local diffusion "
                    "GGUFs such as FLUX and Qwen-Image."
                )
            if arch in LlamaCppBackend._AMBIGUOUS_IMAGE_ARCHES:
                # Same shared-arch resolution as the pre-launch refusal: unresolved means
                # the Images picker tags it image-diffusion-unsupported and hides the row.
                return (
                    f"'{arch}' is a diffusion (image-generation) GGUF, which "
                    "llama-server cannot run as a chat/completion model. Unsloth Studio "
                    f"could not tell which model family this file is -- '{arch}' is "
                    "shared by several -- so the Images page cannot assemble it either."
                )
            if is_ollama:
                return (
                    "Some Ollama models do not work with llama.cpp. Try a "
                    "different model, or use this model directly through "
                    "Ollama instead."
                )
            return (
                f"llama.cpp does not support this GGUF's model architecture "
                f"('{arch}'). The file is valid, but this model type cannot "
                "be run with llama-server."
            )

        # Other Ollama compat failures that don't name an arch. Only when
        # the output shows a GGUF compat issue, not OOM / missing binaries.
        if is_ollama:
            gguf_compat_hints = (
                "key not found",
                "unknown model architecture",
                "failed to load model",
            )
            if any(h in lowered for h in gguf_compat_hints):
                return (
                    "Some Ollama models do not work with llama.cpp. Try a "
                    "different model, or use this model directly through "
                    "Ollama instead."
                )

        # 127 without any loader line above is not specific to a library: it is
        # also what a shell wrapper entrypoint reports when its exec target is
        # gone (_llama_lib_dir supports those, as does a custom
        # LLAMA_SERVER_PATH), and what a "symbol lookup error" from a mismatched
        # runtime exits with. Name both causes instead of blaming a distro
        # package -- but still keep it off the GGUF and off memory.
        # A ROCm symbol lookup is also 127, but the generic text below would send
        # the user to reinstall a binary Vulkan and a shell launch both run fine.
        _rocm_miss = LlamaCppBackend._bundled_hip_symbol_miss(output or "")
        if _rocm_miss:
            _miss_obj, _miss_sym = _rocm_miss
            return (
                f"llama-server could not start: bundled {_short(os.path.basename(_miss_obj))} "
                f"looked up {_short(_miss_sym)} in a different ROCm than it was built "
                "against. That is a HIP/ROCR version mix, not a missing "
                "binary and not out of VRAM. Try the Vulkan backend, or "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )
        if returncode == 127:
            # Same provenance split as the library branches: the updater cannot
            # touch a pinned binary, so do not send its owner there.
            _remedy = (
                "run `unsloth studio update` to reinstall the llama.cpp runtime"
                if LlamaCppBackend._is_unsloth_managed_binary(binary)
                else "reinstall or rebuild that custom llama.cpp"
            )
            return (
                "llama-server exited immediately (status 127): either the "
                "llama-server executable could not be found or run, or one of "
                f"the shared libraries it needs could not be loaded. Check the "
                f"llama-server log, and {_remedy}."
            )

        # SIGKILL with no diagnostic output is the OOM killer (e.g. a model too
        # large for the WSL VM's RAM cap); name it actionably.
        if returncode == -9:
            # macOS also SIGKILLs an invalid code signature before the process
            # can print, so memory is not the only reading there (#8566).
            if sys.platform == "darwin":
                # The log is often empty here, so name the likeliest cause and
                # the macOS-specific one without claiming the two are the only
                # ones: signal 9 is also a supervisor, or a plain `kill -9`.
                return LlamaCppBackend._with_startup_diagnostics(
                    "llama-server was stopped by macOS (signal 9) before it "
                    "started. This is most often out of memory, so try a "
                    "smaller or more quantized GGUF, or lower the context "
                    "length. macOS also sends signal 9 when it refuses a "
                    "binary's code signature, so if memory is not the problem, "
                    f"{LlamaCppBackend._runtime_remedy(binary)}.",
                    output,
                    log_path,
                    secrets,
                )
            return (
                "llama-server was stopped by the operating system (signal 9), "
                "most likely out of memory. Try a smaller or more quantized "
                "GGUF, lower the context length, or free memory (on WSL, raise "
                "the memory limit in .wslconfig)."
            )
        # SIGTERM is also how an unload/cancel or a supervisor stops the server,
        # so report it neutrally rather than blaming memory.
        if returncode == -15:
            return (
                "llama-server was terminated (signal 15) before it became "
                "healthy. If you cancelled or unloaded the model this is "
                "expected; otherwise check the llama-server log for the cause."
            )

        # A live server that never answered 200 on /health is not a bad GGUF:
        # the load is too large for VRAM/context, or a local proxy/VPN grabbed
        # the loopback probe (#5740).
        if "health check timed out" in lowered:
            return (
                "llama-server started but never became healthy on its local "
                "/health endpoint. Try a smaller context length or a more "
                "quantized GGUF, and if you use a VPN or HTTP proxy make sure "
                "localhost bypasses it (NO_PROXY=127.0.0.1,localhost)."
            )

        # Fallback: genuinely unknown failure (OOM, missing binary ...).
        # Nothing above recognised the output, so carry the evidence rather
        # than drop it; without the tail and the log path a report of this
        # message is unactionable and costs a round trip (#8566).
        return LlamaCppBackend._with_startup_diagnostics(
            "llama-server failed to start. "
            "Check that the GGUF file is valid and you have enough memory.",
            output,
            log_path,
            secrets,
        )

    # Enough of the tail to carry a stack trace or a ggml assert, bounded so a
    # chatty server cannot push an unreadable wall of text into an API error.
    _STARTUP_TAIL_CHARS = 2000

    # The labels _with_startup_diagnostics writes, so it can recognise its own
    # output and stay idempotent. Kept next to the writer: a label edited on one
    # side only would silently re-enable double appending.
    _DIAGNOSTICS_MARKERS = ("llama-server output:", "Full log: ")

    # Token shapes worth redacting on sight: a name-based list cannot cover a
    # credential the child obtained elsewhere, or one held in a variable whose
    # name says nothing (GITHUB_PAT, MY_THING).
    _SECRET_VALUE_RES = (
        re.compile(r"hf_[A-Za-z0-9]{20,}"),
        re.compile(r"github_pat_[A-Za-z0-9_]{20,}"),
        re.compile(r"gh[pousr]_[A-Za-z0-9]{20,}"),
        re.compile(r"sk-[A-Za-z0-9_\-]{20,}"),
        # HTTP credentials, if a wrapper or a proxy echoes a request header.
        # token68 is [A-Za-z0-9._~+/-]* with optional "=" padding (RFC 9110
        # 11.2), so a narrower class leaves the tail of a base64 credential
        # readable; Basic (RFC 7617) is a base64 user:password pair and belongs
        # here for the same reason.
        re.compile(r"(?i)(?:bearer|basic)\s+[A-Za-z0-9._~+/\-]+=*"),
        # Our own --api-key, if a wrapper dumps its argv. token_urlsafe(32)
        # matches no shape and is in no env var, so catch it by its flag, as
        # _redacted_cmd_for_log already does for the log.
        re.compile(r"(?<=--api-key )\S+"),
        re.compile(r"(?<=--api-key=)\S+"),
        # scheme://user:secret@host, which is what DATABASE_URL / REDIS_URL and
        # a proxy variable carry. Keep the scheme, drop the userinfo.
        re.compile(r"(?<=://)[^/@\s]+(?=@)"),
    )

    # NAME = value / "NAME": "value", in the three shapes an environment dump
    # takes: shell-ish, JSON, and bare. The quoted arm ends on the delimiter it
    # opened with, not on either quote character: a JSON value may legitimately
    # contain an apostrophe, and rejecting both meant "DB_PASSWORD": "a' b"
    # fell through to the bare arm, which stops at whitespace and left " b"
    # standing in the API error. Escapes are consumed so a backslash-escaped
    # delimiter does not end the value early. Both arms are unambiguous
    # alternations of single characters, so matching stays linear; there is no
    # nested quantifier for a crafted line to exploit.
    # The name accepts the separators a config key uses, not only the ones a
    # shell variable may: a child dumping its own configuration writes
    # "db-password" or client.secret, and an identifier-only pattern never
    # reached is_secret_env_name for either. The predicate still decides.
    #
    # Third value arm: a truncated line ends the output mid-value, so
    # DB_PASSWORD="prefix supersecret has no closing delimiter. It cannot match
    # the terminated arm, and the bare arm stops at whitespace, which left the
    # rest of the credential in the API error. An opened-but-unclosed quote
    # runs to the end of the line. Ordered after the terminated arm so a
    # properly closed value still matches that one.
    _SECRET_ASSIGNMENT_RE = re.compile(
        r"""(?P<q>["']?)(?P<name>[A-Za-z_][A-Za-z0-9_.\-]{0,63})(?P=q)
            (?P<sep>[ \t]*[=:][ \t]*)
            (?:(?P<vq>["'])(?P<qval>(?:\\.|(?!(?P=vq))[^\\])*)(?P=vq)
             |  (?P<uq>["'])(?P<uval>[^\r\n]*)
             |  (?P<val>[^\s,;]+))""",
        re.VERBOSE,
    )

    @staticmethod
    def _redact_secret_assignments(text: str) -> str:
        """Redact the value beside any secret-looking NAME, however encoded.

        Positional, not literal: whatever follows the name is replaced, so
        JSON escaping, shell quoting or URL encoding cannot smuggle a value
        past the check the way a value-literal comparison allows.
        """
        try:
            from utils.prebuilt.child_env import is_secret_env_name
        except Exception:  # noqa: BLE001 - redaction must never break a load error
            return text

        def sub(m: "re.Match[str]") -> str:
            # A config key spells the same thing with a hyphen or a dot, and
            # the predicate's markers are underscored (API_KEY, PRIVATE_KEY),
            # so "api-key" missed while "api_key" matched. Normalise the
            # separator before asking; the predicate stays the one place that
            # decides what counts as a secret.
            name = m.group("name")
            if not is_secret_env_name(name.replace("-", "_").replace(".", "_")):
                return m.group(0)
            q, vq, uq = m.group("q"), m.group("vq"), m.group("uq")
            if vq:
                body = f"{vq}***{vq}"
            elif uq:
                # Unterminated: keep the opening delimiter, drop the rest of
                # the line. Inventing a closing quote would misreport what the
                # child printed.
                body = f"{uq}***"
            else:
                body = "***"
            return f"{q}{m.group('name')}{q}{m.group('sep')}{body}"

        try:
            return LlamaCppBackend._SECRET_ASSIGNMENT_RE.sub(sub, text)
        except Exception:  # noqa: BLE001
            return text

    @staticmethod
    def _scrub_secret_values(text: str, extra: Sequence[Optional[str]] = ()) -> str:
        """Redact credential-looking environment values out of ``text``.

        llama-server inherits nearly all of Unsloth's environment, so a wrapper
        script, a diagnostic build or a crash handler that echoes its env would
        otherwise put an API key straight into the load error.

        Two passes, because either alone has a hole. Matching the VALUE catches
        a credential under a name we never heard of, but only if the child
        printed it verbatim: a wrapper dumping its environment as JSON prints
        pa"ss\\word as pa\\"ss\\\\word, which is a different string and was
        reaching the API error fully reconstructible. Matching the NAME and
        redacting whatever follows it is immune to how the value was encoded,
        but only works for names that look like secrets. Doing both leaves a
        gap only for an unrecognised name AND an escaped value.
        """
        if not text:
            return text
        cleaned = LlamaCppBackend._redact_secret_assignments(text)
        # Secrets we minted and therefore know exactly: no pattern recognises
        # a token_urlsafe blob. Gathered together with the environment's own
        # values and replaced LONGEST FIRST, because two credentials can
        # overlap: with TOKEN_A=abcdefgh and TOKEN_B="abcdefgh VERYSECRET",
        # replacing the short one first rewrote the long one's only occurrence
        # to "*** VERYSECRET", after which the long one no longer matched
        # itself and its tail went out in the API error.
        literals = {literal for literal in extra if literal and len(literal) >= 8}
        # By name, reusing what decides which vars a managed server is denied,
        # so the two cannot drift: what we withhold must not come back out of
        # the child either. URL userinfo counts whatever it is named.
        try:
            from utils.prebuilt.child_env import URL_USERINFO_RE, is_secret_env_name
            for name, value in os.environ.items():
                if not value:
                    continue
                secret_name = is_secret_env_name(name)
                if len(value) < 8:
                    # Too short to replace globally ("1", "true", a port number
                    # would match everywhere), but a short password is still a
                    # password: redact it where it appears next to its name.
                    # The name and the value may each be quoted, because an env
                    # dump can be shell-ish (DB_PASSWORD='x'), JSON
                    # ({"DB_PASSWORD": "x"}), or bare, and only the bare form
                    # matched before.
                    if secret_name:
                        cleaned = re.sub(
                            rf"([\"']?{re.escape(name)}[\"']?\s*[=:]\s*)"
                            rf"([\"']?){re.escape(value)}\2",
                            r"\1\2***\2",
                            cleaned,
                        )
                    continue
                if secret_name or URL_USERINFO_RE.search(value):
                    literals.add(value)
        except Exception:  # noqa: BLE001 - redaction must never break a load error
            pass
        for literal in sorted(literals, key = len, reverse = True):
            cleaned = cleaned.replace(literal, "***")
        # By shape, for credentials that are not in our environment to match on
        # (a token the child read from its own config, a proxy's header echo).
        for pattern in LlamaCppBackend._SECRET_VALUE_RES:
            cleaned = pattern.sub("***", cleaned)
        return cleaned

    @staticmethod
    def _has_startup_diagnostics(text: str) -> bool:
        """Is ``text`` something _with_startup_diagnostics already produced?

        Matches our own framing, not the bare words: a server that printed
        "llama-server output:" itself must still get its tail attached.
        """
        return text.startswith(LlamaCppBackend._DIAGNOSTICS_MARKERS) or any(
            f"\n\n{marker}" in text for marker in LlamaCppBackend._DIAGNOSTICS_MARKERS
        )

    # Ceiling on how far the tail window is widened for redaction. A real
    # credential is far below this; the cap stops a pathological environment
    # value from turning a bounded slice into a scan of everything the child
    # ever printed.
    _MAX_SECRET_SCAN_CHARS = 262144

    @staticmethod
    def _max_secret_len(extra: Sequence[Optional[str]] = ()) -> int:
        """Longest value _scrub_secret_values could be asked to match, capped."""
        longest = 0
        for literal in extra:
            if literal:
                longest = max(longest, len(literal))
        try:
            from utils.prebuilt.child_env import URL_USERINFO_RE, is_secret_env_name
            for name, value in os.environ.items():
                if not value or len(value) <= longest:
                    continue
                if is_secret_env_name(name) or URL_USERINFO_RE.search(value):
                    longest = len(value)
        except Exception:  # noqa: BLE001 - a narrower window still redacts most
            pass
        return min(longest, LlamaCppBackend._MAX_SECRET_SCAN_CHARS)

    @staticmethod
    def _with_startup_diagnostics(
        message: str,
        output: Optional[str],
        log_path: "Optional[Path | str]",
        extra_secrets: Sequence[Optional[str]] = (),
    ) -> str:
        """Append llama-server's output tail and log path to ``message``.

        Returns ``message`` unchanged when there is neither, so the classified
        messages and the no-output case keep their exact existing text.

        Idempotent: a message that already carries a diagnostics block is
        returned as is. Only one call site exists today, so this cannot fire
        yet; it is here so a second caller (a retry that re-classifies an
        already-decorated message, say) cannot silently double the tail.
        """
        if LlamaCppBackend._has_startup_diagnostics(message):
            return message
        parts = [message]
        # Slice before filtering: _drain_stdout keeps an unterminated line
        # whole, so a runaway progress line would otherwise be walked
        # character by character just to throw all but the last 2000 away.
        #
        # Widened by the longest secret we could be asked to redact. The
        # scrubber matches a whole value, so a credential longer than this
        # window (a PEM key or a service-account blob dumped by a wrapper) was
        # cut by the slice, and the surviving suffix matched neither the
        # literal nor any token shape -- so it reached the API error. A shorter
        # secret cannot straddle the boundary: if its end is inside a window
        # wider than the secret, so is its start.
        _window = LlamaCppBackend._STARTUP_TAIL_CHARS * 4 + LlamaCppBackend._max_secret_len(
            extra_secrets
        )
        raw = (output or "")[-_window:]
        # Control characters (progress bars, colour codes) would corrupt the
        # API error; keep newlines and tabs, which carry the structure.
        tail = "".join(ch for ch in raw if ch in "\n\t" or ch.isprintable()).strip()
        if tail:
            tail = LlamaCppBackend._scrub_secret_values(tail, extra_secrets)
            tail = tail[-LlamaCppBackend._STARTUP_TAIL_CHARS :].lstrip()
            parts.append(f"llama-server output:\n{tail}")
        if log_path:
            parts.append(f"Full log: {log_path}")
        return "\n\n".join(parts)

    def _plan_tensor_parallel(
        self,
        gpus: list[tuple[int, int]],
        model_size: int,
        target_ctx: int,
        cache_type_kv: Optional[str] = None,
        n_parallel: int = 1,
        mtp_engaged: bool = False,
        mtp_overhead_fn: Optional[Callable[[int], int]] = None,
        mtp_flat_reserve_bytes: int = 0,
        max_target_ctx: Optional[int] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        n_ubatch: Optional[int] = None,
        soft_overhead_bytes: int = 0,
        swa_full: bool = False,
        kv_unified: bool = True,
        flash_attn: bool = True,
        vram_fraction: Optional[float] = None,
        scratch_cache_type_kv: Optional[str] = None,
    ) -> tuple[int, int, list[int], Optional[list[int]]]:
        """Plan a ``--split-mode tensor`` load. Pure: no model or GPU needed.

        ``gpus`` is a list of ``(gpu_index, free_mib)``; ``model_size`` is the
        weight size in bytes; ``target_ctx`` is the context to fit (the explicit
        request, or the model's native length for auto). ``max_target_ctx`` is
        the native/hardware ceiling used only for the UI bound (defaults to
        ``target_ctx``). Returns
        ``(effective_ctx, max_available_ctx, gpu_indices, tensor_split)``.

        Policy (assumes >= 2 GPUs; the caller drops the toggle below that):
        - Cap context to the KV that fits the pooled VRAM after the weights, one
          per-device flat compute-graph buffer (``_estimate_compute_buffer_bytes``,
          deterministic from dims; flat fallback when dims are unavailable), and the
          per-device context-linear compute growth (``_compute_buffer_ctx_bytes``,
          replicated on every device in tensor mode, so summed over the split).
          llama.cpp's ``--fit`` is a no-op in tensor mode, so this is the only
          cap, honored even for an explicit ``-c``. It is more accurate than the
          0.80 whole-pool heuristic, which over-reserves and leaves VRAM unused.
        - ``tensor_split`` is None (llama.cpp's even default, safe for every arch
          incl. Gemma 3n which GGML_ASSERTs on a weighted split) when an even
          share fits the smallest GPU; otherwise it is weighted by usable budget
          so the roomier GPU absorbs more weight and the smallest keeps room for KV.
        ``total_by_idx`` enables the total-based occupancy cap; ``n_ubatch`` sizes
        the compute buffer. ``soft_overhead_bytes`` is the CUDA-context / mmproj /
        MTP-draft-graph reserve the layer path folds into ``model_size_fit``;
        charged against the pooled budget so tensor mode reserves the same overhead.
        ``cache_type_kv`` is the HEAVIER planned axis (KV bytes);
        ``scratch_cache_type_kv`` is the LIGHTER one and prices the dequant scratch,
        so an asymmetric pair keeps both terms conservative. Defaults to
        ``cache_type_kv`` when unset, which is the symmetric case.
        """

        # Per-GPU usable budget: free - (1-frac)*total, else (unknown total, e.g. a
        # two-column probe) the legacy free*frac. Mirrors _select_gpus and
        # _gpu_usable so the 5% cushion is kept on every path, not dropped here.
        # Prefer the caller's resolved budget, so placement and ranking price the
        # SAME fraction even if a save lands mid-load; resolved here only for the
        # direct callers (tests) with no load to inherit from, and once, not per GPU.
        _tp_frac = vram_fraction if vram_fraction is not None else _active_vram_fraction()

        def _usable(idx: int, free_mib: int) -> float:
            # Through the shared helper, so the floor reserve the ranking and the
            # layer path apply is charged here too. Tensor mode has no --fit valve,
            # so a budget spent above the floor fails at startup rather than
            # offloading. Clamped on both branches, unlike _select_gpus: this pool
            # is summed, and one negative card must not fund another.
            t = total_by_idx.get(idx, 0) if total_by_idx else 0
            return max(0.0, _vram_usable_mib(free_mib, t, _tp_frac))

        # Drop GPUs whose usable budget can't hold the per-device compute-graph
        # buffer; they'd OOM in tensor mode. Admitting on raw free would let a
        # partly-used big card in with no budget left. Defense-in-depth (load_model
        # gates too). Derived per-device reserve; flat fallback.
        _reserve_bytes = self._estimate_compute_buffer_bytes(
            n_ubatch = n_ubatch, n_parallel = n_parallel, per_device_tensor = True
        )
        reserve_mib = (
            _reserve_bytes // (1024 * 1024)
            if _reserve_bytes > 0
            else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB
        )
        usable_gpus = [g for g in gpus if _usable(g[0], g[1]) >= reserve_mib]
        gpu_indices = sorted(idx for idx, _ in usable_gpus)
        if len(gpu_indices) < 2:
            # Tensor parallelism is meaningless on <2 GPUs (the caller drops the
            # toggle before this); be defensive and never emit a split here.
            return (
                target_ctx if target_ctx > 0 else 4096,
                target_ctx if target_ctx > 0 else 4096,
                gpu_indices,
                None,
            )
        free_by_idx = {idx: free for idx, free in usable_gpus}
        usable_by_idx = {idx: _usable(idx, free_by_idx[idx]) for idx in gpu_indices}
        pool_mib = sum(usable_by_idx.values())
        # MTP reserve: byte-accurate per-ctx inside _fit_ctx (mtp_overhead_fn) plus
        # a flat cushion that the byte fn can't size -- 2 GiB when dims are wholly
        # unavailable (no fn), or mtp_flat_reserve_bytes when the fn is weights-only
        # because the draft KV couldn't be sized (_mtp_kv_unsized). Without this the
        # binary search spends the unsized-KV cushion on main context and OOMs.
        flat_mtp_bytes = max(0, mtp_flat_reserve_bytes)
        if mtp_engaged and mtp_overhead_fn is None:
            flat_mtp_bytes = max(flat_mtp_bytes, 2 * 1024**3)
        # soft_overhead_bytes is the CUDA-context / mmproj / MTP-draft-graph reserve
        # the layer path folds into model_size_fit. Tensor mode has no --fit valve, so
        # an unreserved overshoot OOMs at startup rather than offloading; charge it here
        # too. Once (pooled), mirroring the layer path -- the per-device CUDA context is
        # a known slight under-charge, left for real multi-GPU data.
        kv_budget_b = (
            (pool_mib - len(gpu_indices) * reserve_mib) * 1024 * 1024
            - model_size
            - flat_mtp_bytes
            - max(0, soft_overhead_bytes)
        )

        def _mtp_at(ctx: int) -> int:
            return mtp_overhead_fn(ctx) if mtp_overhead_fn is not None else 0

        def _kv_at(ctx: int) -> int:
            return self._estimate_kv_cache_bytes(
                ctx,
                cache_type_kv,
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )

        # Context-linear compute buffer, summed over the split. Tensor mode
        # replicates the compute graph on EVERY device (measured: the per-device
        # buffer grows a flat n_ubatch*2 bytes/token, ~1024 B/tok on Qwen3.5-9B at
        # f16, independent of n_embd), so the growth is n_dev x the per-device
        # term. The flat reserve_mib above only covers ctx->0; without this the fit
        # over-pins and OOMs at high context on a tight pool (0.5-4 GiB unreserved
        # at 262k-1M across 2-4 GPUs), the tensor-mode analog of the layer-split
        # compute bug.
        #
        # Priced from the LIGHTER axis, not the heavier budget type: since
        # ggml-org/llama.cpp#23792 an asymmetric -ctk q4_0 -ctv f16 reaches the child,
        # and the heavier scalar (f16) would drop the dequant scratch the q4 axis
        # allocates. No --fit valve here, so that under-reservation OOMs at startup.
        n_dev = len(gpu_indices)
        cc_cache_type = (
            scratch_cache_type_kv if scratch_cache_type_kv is not None else cache_type_kv
        )

        def _cc_ctx(ctx: int) -> int:
            return n_dev * self._compute_buffer_ctx_bytes(ctx, n_ubatch, cc_cache_type)

        def _fit_ctx(ctx: int) -> int:
            # Largest context whose KV (+ MTP draft reserve + context-linear
            # compute) fits the pooled budget. Floors small, but never raises an
            # explicit ctx above asked.
            if self._can_estimate_kv() and ctx > 0:
                ctx_floor = min(2048, ctx)
                if kv_budget_b <= 0:
                    # Weights + buffers exceed the pool -> floor; the load then
                    # falls back to layer split.
                    return ctx_floor

                def _consumer(c: int) -> int:
                    return _kv_at(c) + _mtp_at(c) + _cc_ctx(c)

                if _consumer(ctx) <= kv_budget_b:
                    return ctx
                lo, hi, best = ctx_floor, ctx, ctx_floor
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if _consumer(mid) <= kv_budget_b:
                        best = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1
                return best
            # KV size unknown -> can't prove a safe cap; floor.
            return min(4096, ctx) if ctx > 0 else 4096

        # max_available_ctx is the hardware ceiling for the UI bound, sized from
        # the native context independent of an explicit small -c (which only
        # caps effective_ctx).
        max_ctx_target = max_target_ctx if (max_target_ctx and max_target_ctx > 0) else target_ctx
        max_available_ctx = _fit_ctx(max_ctx_target)
        effective_ctx = min(_fit_ctx(target_ctx), max_available_ctx)

        min_usable_mib = min(usable_by_idx.values())
        kv_bytes = _kv_at(effective_ctx) if (self._can_estimate_kv() and effective_ctx > 0) else 0
        # The MTP reserve also has to fit the even split (mirror the pooled budget):
        # byte-accurate per-ctx (0 when no fn) plus the same flat cushion as above.
        mtp_bytes = (_mtp_at(effective_ctx) if effective_ctx > 0 else 0) + flat_mtp_bytes
        # Context-linear compute is replicated per device; charge the whole split so
        # the weighted ratio reflects it (mirrors kv_budget_b's per-device reserve).
        cc_bytes = _cc_ctx(effective_ctx) if effective_ctx > 0 else 0
        even_share_mib = (
            (model_size + kv_bytes + mtp_bytes + cc_bytes) / len(gpu_indices) / (1024 * 1024)
        )
        tensor_split: Optional[list[int]] = None
        if even_share_mib > (min_usable_mib - reserve_mib):
            # Each device also holds its replicated share of the context-linear
            # compute (cc_bytes/n_dev) on top of the flat reserve. The even-share
            # gate above charges cc_bytes; the split weights must subtract it too, or
            # the smaller card is weighted above its real usable budget and OOMs (the
            # per-device analog of the layer path's per-GPU overhead in _select_gpus).
            cc_per_dev_mib = (cc_bytes // len(gpu_indices)) // (1024 * 1024) if cc_bytes else 0
            adj = [
                max(0, int(usable_by_idx[i] - reserve_mib - cc_per_dev_mib)) for i in gpu_indices
            ]
            if sum(adj) > 0:
                tensor_split = adj
        return effective_ctx, max_available_ctx, gpu_indices, tensor_split

    @staticmethod
    def _with_mmproj_offload_disabled(
        cmd: Sequence[str], env: Optional[Mapping[str, str]] = None
    ) -> Optional[List[str]]:
        """Return a vision-preserving retry with the projector pinned to CPU.

        llama.cpp's boolean placement flags are last-wins, so the recovery pin
        must follow pass-through arguments that may have enabled GPU offload.
        None means no projector is present or it already runs on CPU.
        """
        args = [str(arg) for arg in cmd]

        def _flag(token: str) -> str:
            return token.split("=", 1)[0].replace("_", "-").lower()

        if not any(_flag(arg) in ("--mmproj", "-mm") for arg in args):
            return None
        # Argv and environment at arg.cpp's own precedence. Two placements the
        # spelling list below cannot see: LLAMA_ARG_NO_MMPROJ_OFFLOAD (falsey on
        # presence alone) and the `disabled` token. Either already has the projector in
        # host RAM, so respawning cannot clear the allocation failure and costs the
        # caller the real error, which only surfaces when this returns None.
        #
        # Only a resolved False means "already on CPU". An explicit --mmproj-offload is
        # overridden deliberately: this is crash recovery, and the alternative is
        # losing vision altogether.
        if _resolved_mmproj_offload(args, env or {}) is False:
            return None
        placements = [
            _flag(arg) for arg in args if _flag(arg) in ("--mmproj-offload", "--no-mmproj-offload")
        ]
        if not placements:
            # Colloquial spellings arg.cpp itself rejects: `no` parses as neither truthy
            # nor falsey, so common_params_parse throws and the child never starts, which
            # no retry can fix. Kept as a deliberate superset of the resolution above
            # rather than tightened, so a value that used to skip the futile retry still
            # does.
            env_value = str((env or {}).get(_MMPROJ_OFFLOAD_ENV_VAR) or "").strip().lower()
            if env_value in ("0", "false", "off", "no"):
                return None
        return args + ["--no-mmproj-offload"]

    @staticmethod
    def _is_gpu_memory_start_failure(output: str) -> bool:
        """Whether startup output ties allocation pressure to a GPU backend."""
        lines = (output or "").lower().splitlines()
        allocation_markers = (
            "out of memory",
            "failed to allocate",
            "cudamalloc failed",
            "hiperroroutofmemory",
            "vk_error_out_of_device_memory",
        )
        gpu_markers = (
            "cuda",
            "hiperror",
            "hipmalloc",
            "ggml_backend_hip",
            "rocm",
            "vulkan",
            "vk_",
            "metal",
            "sycl",
            "oneapi",
            "musa",
            "gpu",
            "device memory",
        )
        return any(
            any(marker in line for marker in allocation_markers)
            and any(marker in line for marker in gpu_markers)
            for line in lines
        )

    @staticmethod
    def _is_projector_incompatibility(output: str) -> bool:
        """True when llama-server aborted because it cannot load the model's
        vision/audio projector (mmproj), typically an installed llama.cpp
        that predates the projector format. Conservative: only matches
        projector-format errors so unrelated failures (OOM, bad GGUF, port
        bind, ...) keep their own handling, and a bare 'clip'/'mmproj'
        mention in a normal startup log does not match.
        """
        text = (output or "").lower()
        if any(
            m in text
            for m in (
                "unknown projector type",
                "unsupported projector",
                "unsupported mmproj",
            )
        ):
            return True
        # Builds that phrase it via clip.cpp without the exact words above.
        return (
            "clip" in text
            and "projector" in text
            and ("unknown" in text or "unsupported" in text or "not supported" in text)
        )

    @staticmethod
    def _mmproj_retry_failure_message(*, projector_confirmed: bool, detail: str) -> str:
        """User-facing error when the text-only --mmproj strip retry also fails.

        Confirmed projector-format mismatches keep the historical wording.
        Bare signal crashes (common on some ROCm/driver paths) must not be
        reported as "Vision projector incompatible" — that misled #7302.
        """
        if projector_confirmed:
            return (
                "Vision projector incompatible with this llama.cpp "
                "build, and the text-only retry also failed: " + detail
            )
        return (
            "Vision model failed to start (llama-server crashed with "
            "--mmproj), and the text-only retry also failed: " + detail
        )

    @staticmethod
    def _output_has_nonprojector_diagnostic(output: str) -> bool:
        """True when the output already names a concrete non-projector cause (out
        of memory, an unsupported architecture, a tensor-parallel limit). A hard
        crash carrying such a marker must surface that error, not be silently
        retried text-only as if the vision projector were at fault; a bare crash
        with no marker still gets the text-only retry.
        """
        text = (output or "").lower()
        return any(
            m in text
            for m in (
                "out of memory",
                "failed to allocate",
                "unknown model architecture",
                "split_mode_tensor not implemented",
                LlamaCppBackend._TENSOR_QUANT_KV_UNSUPPORTED_MARKER,
            )
        )

    # llama.cpp before ggml-org/llama.cpp#23792 (build b9455) refused a quantized KV
    # cache under --split-mode tensor outright, in llama_init_from_model:
    #   "simultaneous use of SPLIT_MODE_TENSOR and KV cache quantization not implemented"
    # Unlike the #6415 split-axis abort this is a clean LLAMA_LOG_ERROR + return
    # nullptr (exit 1, no signal), so _should_record_tensor_split_abort cannot see it.
    # Matched on the middle of the string, so the surrounding log format is irrelevant.
    # Unsloth dropped its own pre-emptive gate once #23792 shipped, so this marker is
    # what keeps an older binary cheap: without it every load burns two doomed model
    # loads (tensor attempt plus --fit retry) before the route's layer fallback.
    _TENSOR_QUANT_KV_UNSUPPORTED_MARKER = (
        "split_mode_tensor and kv cache quantization not implemented"
    )

    @classmethod
    def _is_tensor_quant_kv_unsupported(cls, output: str) -> bool:
        """True for the pre-b9455 refusal of a quantized KV cache in tensor mode.

        Deterministic and binary-wide: only a different llama.cpp helps, so the
        caller latches it and downgrades instead of retrying --fit or flash-attn.
        """
        return cls._TENSOR_QUANT_KV_UNSUPPORTED_MARKER in (output or "").lower()

    @staticmethod
    def _is_tensor_split_assert(output: str) -> bool:
        """True only for the #6415 split-axis warmup assert (GGML_BACKEND_SPLIT_AXIS_*),
        not any ggml assert/abort, so an unrelated invariant isn't cached. stderr is
        merged into output."""
        text = (output or "").lower()
        if "ggml_assert" not in text and "ggml_abort" not in text:
            return False
        # the split-axis enum token, unique to this assert (not the source file).
        return "split_axis" in text

    # The prepend covers the whole system ROCm dir, so any lib in it can be the
    # one that fails to resolve, not just HIP. Matched on the basename so a path
    # component (/opt/librocm-custom/...) cannot stand in for the object.
    _ROCM_OBJECT_HINTS = ("libamdhip", "libamd_comgr", "libhsa-runtime", "libhip", "libroc")

    # Build dirs where a bundle-only launch has come up healthy after the mix
    # crashed, paired with the binary revision that proved it. The installer
    # swaps a new runtime into the same path, so the revision prevents an old
    # proof from suppressing the system ROCm prepend for the new build.
    _bundle_only_rocm_dirs: dict[str, tuple] = {}
    _bundle_only_rocm_lock = threading.Lock()

    @staticmethod
    def _remember_bundle_only_rocm(binary: str) -> None:
        resolved = _resolve_llama_binary(binary)
        revision = LlamaCppBackend._binary_stamp(resolved)
        with LlamaCppBackend._bundle_only_rocm_lock:
            LlamaCppBackend._bundle_only_rocm_dirs[str(resolved.parent)] = revision

    @staticmethod
    def _prefers_bundle_only_rocm(binary: str) -> bool:
        resolved = _resolve_llama_binary(binary)
        revision = LlamaCppBackend._binary_stamp(resolved)
        with LlamaCppBackend._bundle_only_rocm_lock:
            return LlamaCppBackend._bundle_only_rocm_dirs.get(str(resolved.parent)) == revision

    @staticmethod
    def _bundled_hip_symbol_miss(output: str) -> "Optional[tuple[str, str]]":
        """(object, symbol) when a bundled ROCm lib failed a symbol lookup (#8998).

        glibc prints ``symbol lookup error: <object>: undefined symbol: <sym>[,
        version <v>]``. A ggml symbol, or an absent .so (``error while loading
        shared libraries``), is a different failure. The object is echoed
        verbatim, so split on the ": undefined symbol:" that follows it rather
        than on whitespace, the same way the missing-library branch above keeps
        "/opt/My Runtime/libfoo.so" whole.
        """
        match = re.search(
            r"symbol lookup error:[ \t]*([^\r\n]{1,4096}?):"
            r"[ \t]*undefined symbol:[ \t]*([^\s,]+)",
            output or "",
        )
        if not match:
            return None
        obj = os.path.basename(match.group(1)).lower()
        if not obj.startswith(LlamaCppBackend._ROCM_OBJECT_HINTS):
            return None
        return match.group(1), match.group(2)

    @staticmethod
    def _is_bundled_hip_rocr_mismatch(output: str) -> bool:
        return LlamaCppBackend._bundled_hip_symbol_miss(output) is not None

    @staticmethod
    def _is_signal_crash(returncode: Optional[int]) -> bool:
        """True only on a hard fault (SIGSEGV/SIGABRT/SIGILL/SIGFPE/SIGBUS or a
        Windows 0xC0000000+ status), not SIGKILL/SIGTERM/SIGINT (OOM killer /
        unload) nor a clean exit or still-running (None) process.
        """
        if returncode is None:
            return False
        if returncode >= 0xC0000000:  # Windows access violation / illegal instruction
            return True
        return -returncode in (4, 6, 7, 8, 11)  # SIGILL SIGABRT SIGBUS SIGFPE SIGSEGV

    @staticmethod
    def _is_abort_exit(returncode: Optional[int]) -> bool:
        """Windows CRT abort() exit code (3) from GGML_ASSERT on MSVC -- not a POSIX
        signal or 0xC0000000+ NTSTATUS."""
        return returncode == 3

    @classmethod
    def _should_record_tensor_split_abort(cls, returncode: Optional[int], output: str) -> bool:
        """The #6415 split-axis abort: the marker plus a hard crash (POSIX signal or
        Windows abort exit). Marker required so a generic crash isn't cached."""
        return cls._is_tensor_split_assert(output) and (
            cls._is_signal_crash(returncode) or cls._is_abort_exit(returncode)
        )

    # ROCm's arch-mismatch crash: no compiled kernels for the device it launched on
    # (#7624). Deterministic, so only a different device helps, not a fit / flash-attn
    # retry. Four spellings because clr returns four codes for "no code object for
    # THIS device": hip_fatbin.cpp raises them, hip_platform.cpp propagates them out
    # of the launch path, and ggml reprints hipGetErrorString verbatim. Matching only
    # hipErrorInvalidImage (what both field logs show) would leave a build raising
    # hipErrorNoBinaryForGpu on the misleading GGUF/memory error.
    _KERNEL_IMAGE_INVALID_MARKERS = (
        "device kernel image is invalid",  # hipErrorInvalidImage
        "no kernel image is available for execution",  # hipErrorNoBinaryForGpu
        "invalid kernel file",  # hipErrorInvalidKernelFile
        "invalid device function",  # hipErrorInvalidDeviceFunction
    )

    @classmethod
    def _kernel_image_invalid(cls, output: str) -> bool:
        # Case-folded: hipGetErrorString is lowercase, but the layers that
        # reprint it are not consistent about that.
        text = (output or "").lower()
        return any(marker in text for marker in cls._KERNEL_IMAGE_INVALID_MARKERS)

    @classmethod
    def _arch_crash_retry_gpu_ids(cls, selected, enumerated) -> list[int]:
        """Devices to retry on after a "device kernel image is invalid" crash.

        Prefer the enumerated GPUs the failed launch never touched. When it used every
        one the crash does not name the offending card, so narrow instead: drop the
        unified-memory devices, where this mismatch keeps landing (#7624, the
        shared-pool APU's system-RAM "free memory" outranked the dGPU). Empty when
        nothing would change, when narrowing leaves no device, or on a single-GPU
        host."""
        _selected = set(selected or ())
        if not _selected:
            return []
        remaining = sorted(i for i in set(enumerated or ()) if i not in _selected)
        if remaining or len(_selected) < 2:
            return remaining
        try:
            discrete = sorted(_selected - cls._rocm_unified_memory_gpu_ids())
        except Exception:
            return []
        return discrete if 0 < len(discrete) < len(_selected) else []

    @staticmethod
    def _without_tensor_split(cmd: list[str]) -> Optional[list[str]]:
        """Return cmd with ``--tensor-split``/``-ts`` removed (both spellings and the
        ``--tensor-split=1,2`` form), or None when it carries none.

        The shares are positional over the child's VISIBLE device list, so a respawn
        that masks a device out re-indexes the survivors while keeping the old
        weights, handing card N the share sized for card N-1. Dropping the flag falls
        back to llama.cpp's free-VRAM split, correct for any device set."""
        return LlamaCppBackend._without_flags(cmd, ("--tensor-split", "-ts"))

    @staticmethod
    def _without_flags(cmd: list[str], names: Collection[str]) -> Optional[list[str]]:
        """Return cmd with every ``names`` flag (and its value) dropped, or None when
        it carries none. ``_flag_name`` peels ``--key=value`` and underscore
        spellings; only the two-token form swallows the next entry. Pass VALUE-TAKING
        flags only: valueless ones (``--mlock``, ``--no-mmap``, bare ``-fa``) would
        drop whatever argv entry follows."""
        out: list[str] = []
        found = False
        skip = False
        for tok in cmd:
            if skip:
                skip = False
                continue
            token = str(tok)
            if _flag_name(token) in names:
                found = True
                skip = "=" not in token
                continue
            out.append(token)
        return out if found else None

    @staticmethod
    def _requires_symmetric_kv(kv_lora_rank, architecture) -> bool:
        """Whether llama.cpp rejects K != V for a model with this metadata.

        Mirrors ``is_mla() || arch == LLM_ARCH_DEEPSEEK4``: kv_lora_rank stands in
        for is_mla() (the MLA archs' converter writes it alongside the MLA head
        dims), and deepseek4 is checked by name because it sets neither.
        """
        if kv_lora_rank is not None:
            return True
        return (architecture or "").strip().lower() == "deepseek4"

    def _target_kv_symmetry(self) -> bool:
        """Whether the TARGET model requires K == V."""
        return self._requires_symmetric_kv(self._kv_lora_rank, getattr(self, "_architecture", None))

    def _draft_kv_symmetry(
        self,
        cmd: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[bool]:
        """Whether the DRAFTER requires K == V; None when it cannot be determined.

        Derived from the drafter the launch actually resolves to, which is the one
        named on the command being launched. The stored ``_mtp_draft_path`` is the
        wrong source twice over: it only ever holds the managed sidecar, so an
        ``extra_args`` ``--model-draft``/``--hf-repo-draft`` (the drafter llama.cpp
        would really load) is invisible to it, and it is not assigned until after
        the launch-site reset has already run, so it is stale there anyway. The
        managed path emits ``--model-draft <sidecar>`` into the same command, so
        reading the command covers both.

        None only when no drafter is named at all, in which case there are no draft
        flags to reset and the value cannot matter. A drafter that IS named but
        whose metadata cannot be read (a Hugging Face repo id rather than a local
        file, or an unreadable GGUF) resolves to True rather than to the target's
        answer: the two mistakes are not symmetric. Resetting a non-MLA drafter's K
        needlessly costs memory, whereas failing to reset an MLA drafter's K leaves
        it quantized against an f16 draft V and aborts the draft context outright,
        which is the failure this whole path exists to avoid.
        """
        path, is_remote = _extra_args_mtp_draft_source(list(cmd or []), env)
        if not path:
            return None
        if is_remote:  # a repo id is not a local file whose metadata can be read
            return True
        try:
            db = self._draft_backend_for(path)
        except Exception:
            db = None
        if db is None:  # named but unreadable -> conservative, not the target
            return True
        return self._requires_symmetric_kv(
            getattr(db, "_kv_lora_rank", None), getattr(db, "_architecture", None)
        )

    @staticmethod
    def _reset_quantized_v_cache(
        cmd: list[str],
        reason: str,
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> list[str]:
        """Return cmd with any quantized V cache reset to f16, for a launch that
        runs without flash attention.

        A quantized V cache requires flash attention in llama.cpp: the init aborts
        with "V cache quantization requires flash_attn". A quantized K cache has no
        such requirement and runs fine without FA, so it is left untouched --
        resetting it would needlessly enlarge the K cache and can OOM a
        memory-constrained config.

        ``mla`` overrides that on the models where leaving K alone is now itself
        fatal. llama-context.cpp gained this in #25871, and it sits ABOVE the
        V-quantization check, so it decides first:

            if ((model->hparams.is_mla() || model->arch == LLM_ARCH_DEEPSEEK4)
                    && params.type_k != params.type_v) {
                LLAMA_LOG_ERROR("model does not support different K (%s) and V
                                 (%s) cache types");
                return nullptr;
            }

        is_mla() is n_embd_head_k_mla_impl and n_embd_head_v_mla_impl both being
        set, which covers DeepSeek V2/V3/R1, Kimi K2 and GLM-4.7/5.x. DeepSeek4 is
        the separate arch term in that condition rather than a second is_mla()
        model: it has its own KV cache (llama-kv-cache-dsv4.cpp), never sets the
        MLA head dims, and its converter writes q_lora_rank but no kv_lora_rank, so
        a kv_lora_rank probe alone does not see it. Resetting V
        alone on one of those turns a quantized KV into K=q8_0 V=f16, which is a
        hard abort for a DIFFERENT reason than the one being avoided: the retry
        that exists to recover from a flash-attention crash fails on the K/V
        mismatch instead. Both axes go to f16 together there, since equal is what
        the rule asks for and f16 is the only value guaranteed to satisfy the V
        rule as well. Main and draft V are both reset (the draft context shares the
        global --flash-attn flag, so its V cache aborts too) to f16 (the llama.cpp
        default); K follows per model, ``mla`` for the target flags and
        ``draft_mla`` for the draft pair. Non-quantized types -- f16/bf16/f32 --
        run fine without FA and are left untouched. The value is rewritten in place
        so the list length is preserved for downstream slices.
        """
        out = list(cmd)
        _v_cache_flags = (
            "--cache-type-v",
            "-ctv",
            "--cache-type-v-draft",
            "--spec-draft-type-v",
            "-ctvd",
        )
        _cache_reset = False
        for i, tok in enumerate(out):
            # llama.cpp rewrites '_' to '-' for any argv token starting with
            # '--' before matching, so a legal pass-through spelling such as
            # --cache_type_v parses as --cache-type-v and still enables a
            # quantized V cache. Canonicalize the flag name the same way so the
            # reset recognizes the underscore aliases too; short flags (-ctv)
            # and the type value are left untouched.
            name = _flag_name(tok)
            if name not in _v_cache_flags:
                continue
            if "=" in tok:
                flag, _, value = tok.partition("=")
                if value.strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i] = f"{flag}=f16"
                    _cache_reset = True
            elif i + 1 < len(out):
                if out[i + 1].strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i + 1] = "f16"
                    _cache_reset = True
        # Symmetry, not size: an MLA model rejects K != V outright, so the K cache
        # has to follow V down rather than stay quantized. This is not conditional
        # on having just reset V here: on this flash-attn-off path V always ends up
        # f16 anyway (reset above when it was quantized on argv, dropped by
        # _drop_env_quantized_v_cache when it was quantized in the environment,
        # otherwise already f16/bf16/f32), so a quantized K left on argv is a
        # guaranteed K != V abort. The asymmetric case that motivates this is
        # -ctk q8_0 on argv with LLAMA_ARG_CACHE_TYPE_V in the environment: nothing
        # quantized appears on argv for V, so a V-triggered reset would never fire.
        #
        # The target and the drafter are separate models with separate contexts, and
        # llama.cpp applies the restriction per context, so each side is gated on its
        # OWN model. Mixing them is wrong in both directions: an MLA target with a
        # non-MLA drafter would needlessly double the drafter's K cache (the very OOM
        # the size argument above warns about), and a non-MLA target with an MLA
        # drafter would leave the draft K quantized against an f16 draft V and abort
        # the draft context. ``draft_mla`` defaults to ``mla`` when the caller cannot
        # read the drafter's metadata, which is the safe direction: an unnecessary
        # reset only costs memory, a missing one aborts.
        _main_k_flags = ("--cache-type-k", "-ctk")
        _draft_k_flags = ("--cache-type-k-draft", "--spec-draft-type-k", "-ctkd")
        if draft_mla is None:
            draft_mla = mla
        _k_cache_flags = (_main_k_flags if mla else ()) + (_draft_k_flags if draft_mla else ())
        _k_reset = False
        for i, tok in enumerate(out):
            if _flag_name(tok) not in _k_cache_flags:
                continue
            if "=" in tok:
                flag, _, value = tok.partition("=")
                if value.strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i] = f"{flag}=f16"
                    _k_reset = True
            elif i + 1 < len(out):
                if out[i + 1].strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i + 1] = "f16"
                    _k_reset = True
        if _cache_reset or _k_reset:
            logger.info(
                "KV cache dtype reset to f16 because flash attention is off (%s): a "
                "quantized V cache requires flash attention in llama.cpp. %s",
                reason,
                (
                    "The K cache went down with it: this model uses MLA, which "
                    "rejects different K and V cache types."
                    if _k_reset
                    else "The K cache is left untouched."
                ),
            )
        return out

    @staticmethod
    def _with_flash_attn_off(
        cmd: list[str],
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> Optional[list[str]]:
        """Return cmd with flash attention forced off, or None when its effective
        (last-wins) value is already off/absent so there is nothing to retry. FA
        kernels hard-crash at startup on some ROCm builds; disabling FA keeps
        vision and MTP, the least destructive rung. A bare --flash-attn/-fa reads
        as on, so it counts toward the effective value and is neutralised too --
        by dropping it, since only the older boolean builds accept the bare form
        and they take no value. Valued forms are flipped in place."""
        out = list(cmd)

        def explicit(i):
            nxt = out[i + 1] if i + 1 < len(out) else None
            return nxt if nxt in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES else None

        effective = None
        for i, tok in enumerate(out):
            name = _flag_name(tok)
            if name in ("--flash-attn", "-fa") and "=" in tok:
                effective = tok.partition("=")[2]
            elif name in ("--flash-attn", "-fa"):
                effective = explicit(i) or "on"
        if effective not in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
            return None
        # A bare flag cannot be turned off in place: llama.cpp looks each argv
        # token up verbatim (only '_' -> '-'), so --flash-attn=off is "invalid
        # argument" everywhere, and the boolean builds that are the only ones
        # accepting the bare form take no value at all. Dropping the token is
        # what disables FA there. Collected first, removed back to front, so the
        # indices stay valid.
        bare_at: list[int] = []
        for i, tok in enumerate(out):
            name = _flag_name(tok)
            if name in ("--flash-attn", "-fa") and "=" in tok:
                flag, _, value = tok.partition("=")
                if value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
                    out[i] = f"{flag}=off"
            elif name in ("--flash-attn", "-fa"):
                if explicit(i) in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
                    out[i + 1] = "off"
                elif explicit(i) is None:  # bare flag (reads as on) -> drop it
                    bare_at.append(i)
        for i in reversed(bare_at):
            del out[i]

        # Unsloth launches with FA on, so a quantized --cache-type-v is legal at
        # launch but would make THIS FA-off retry crash on init instead of
        # recovering.
        return LlamaCppBackend._reset_quantized_v_cache(
            out,
            "disabled by the crash-recovery fallback",
            mla = mla,
            draft_mla = draft_mla,
        )

    @staticmethod
    def _drop_env_quantized_v_cache(
        env: MutableMapping[str, str],
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> bool:
        """Drop an inherited quantized V-cache env var (main or draft) in place
        before a flash-attn-off retry, returning True if anything was removed.

        The argv rewrite in ``_with_flash_attn_off`` only reaches flags on the
        command line. Unsloth deliberately lets an env-only cache type reach the
        child untouched (an asymmetric K/V env must survive), so a quantized V
        cache set purely through ``LLAMA_ARG_CACHE_TYPE_V`` (or the draft
        ``LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_V``) would still abort the FA-off retry
        with "V cache quantization requires flash_attn". Dropping it lets
        llama.cpp fall back to the f16 default.

        On a non-MLA model only V is dropped: a quantized K cache runs fine
        without flash attention, so its env var is preserved. On an MLA model
        (DeepSeek V2/V3/R1, Kimi K2, GLM-4.7/5.x) llama.cpp rejects K != V
        outright, and it checks that *before* the V/flash-attn rule, so the
        quantized K env vars have to go too, each gated on its own model
        (``mla`` for the target var, ``draft_mla`` for the draft one, since the
        drafter is a separate model with its own context). Every caller runs this after the
        argv reset has already forced V to f16, so a surviving quantized K env
        is a guaranteed "model does not support different K and V cache types"
        abort rather than the recovery the retry is trying to perform.
        """
        dropped = False
        variables = ["LLAMA_ARG_CACHE_TYPE_V", "LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_V"]
        if draft_mla is None:
            draft_mla = mla
        if mla:
            variables.append("LLAMA_ARG_CACHE_TYPE_K")
        if draft_mla:
            variables.append("LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_K")
        for var in variables:
            value = (env.get(var) or "").strip().lower()
            if value and value not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                env.pop(var, None)
                dropped = True
        return dropped

    @staticmethod
    def _drop_env_flash_attn(env: MutableMapping[str, str]) -> bool:
        """Drop an inherited LLAMA_ARG_FLASH_ATTN in place before a flash-attn-off
        retry, returning True if anything was removed.

        On the older builds whose --flash-attn takes no value the argv rewrite can
        only drop the flag, never negate it, and llama.cpp reads the env var before
        parsing argv, so LLAMA_ARG_FLASH_ATTN=1 would turn the kernel that just
        crashed straight back on. Newer builds get an explicit --flash-attn off,
        which already beats the env, so dropping it changes nothing there.
        """
        return env.pop("LLAMA_ARG_FLASH_ATTN", None) is not None

    @staticmethod
    def _strip_mmproj_args(cmd: list[str]) -> list[str]:
        """Return cmd without the '--mmproj <path>' pair (text-only retry).
        Every other flag is preserved; a no-op when --mmproj is absent.
        """
        out: list[str] = []
        skip_value = False
        for tok in cmd:
            if skip_value:
                skip_value = False
                continue
            if tok == "--mmproj":
                skip_value = True
                continue
            out.append(tok)
        return out

    @staticmethod
    def _vulkan_prebuilt_was_auto_selected(binary: Optional[str]) -> bool:
        """Whether this managed Vulkan bundle was detected rather than chosen.

        Only an automatic Vulkan install may be quietly replaced with CPU placement
        on a crash: someone who picked Vulkan in Settings > System (or exported
        the variable) picked it over a GPU backend that presumably crashed too, and
        silently undoing that would be the same bug in the other direction. The
        managed marker also excludes custom and PATH binaries.
        """
        if not binary:
            return False
        from utils.llama_cpp_update import _llama_install_root
        from utils.prebuilt.llama_backend import (
            environment_backend_override,
            marker_backend_was_chosen,
        )

        # The same precedence the installer applied when it chose this bundle, so
        # a stale UNSLOTH_FORCE_VULKAN cannot mark an install explicit that
        # UNSLOTH_LLAMA_CPP_BACKEND=auto had setup detect. Only a concrete
        # override is a choice; "auto" still has to pass the marker check below.
        override = environment_backend_override(
            os.environ.get("UNSLOTH_LLAMA_CPP_BACKEND"),
            os.environ.get("UNSLOTH_FORCE_VULKAN"),
        )
        if override is not None and override != "auto":
            return False
        try:
            install_root = _llama_install_root(binary)
            if install_root is None:
                return False
            marker = json.loads(
                (install_root / "UNSLOTH_PREBUILT_INFO.json").read_text(encoding = "utf-8")
            )
        except (OSError, ValueError, TypeError):
            return False
        # Reads new and pre-#7188 markers alike, including the force_cpu-only ones.
        return isinstance(marker, dict) and not marker_backend_was_chosen(marker)

    @staticmethod
    def _strip_cpu_fallback_main_placement(args: Iterable[str]) -> list[str]:
        """Remove every raw main-model placement choice the CPU replay replaces."""
        stripped = strip_shadowing_flags(
            args,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = True,
            strip_offload = True,
            strip_device = True,
        )
        return _paravirtual_strip_gpu_overrides(stripped, log_dropped = False) or []

    @classmethod
    def _cpu_fallback_request_eligible(
        cls,
        intent: GgufLoadIntent,
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        *,
        allow_manual_cpu: bool = False,
    ) -> bool:
        """Whether CPU recovery may replace the requested placement."""
        args = [str(arg) for arg in (extra_args or ())]
        companion_placement_flags = {
            *_OVERRIDE_TENSOR_FLAGS,
            "--spec-draft-device",
            "-devd",
            "--device-draft",
            "--spec-draft-ngl",
            "-ngld",
            "--gpu-layers-draft",
            "--n-gpu-layers-draft",
            "--mmproj-offload",
            "--no-mmproj-offload",
        }
        child_env = os.environ if env is None else env
        placement_eligible = intent.gpu_memory_mode == "auto" or (
            allow_manual_cpu and intent.gpu_memory_mode == "manual" and intent.gpu_layers == 0
        )
        return bool(
            placement_eligible
            and not intent.gpu_ids
            and not intent.tensor_parallel
            and not intent.tensor_split
            and intent.n_cpu_moe == 0
            and cls._strip_cpu_fallback_main_placement(args) == args
            and not _extra_args_set_any_flag(args, companion_placement_flags)
            and not any(
                str(child_env.get(name) or "").strip()
                for name in (
                    *cls._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS,
                    "LLAMA_ARG_N_GPU_LAYERS_DRAFT",
                    "LLAMA_ARG_MMPROJ_OFFLOAD",
                    "GGML_BACKEND_PATH",
                )
            )
        )

    @classmethod
    def _auto_vulkan_cpu_fallback_eligible(
        cls,
        binary: Optional[str],
        intent: GgufLoadIntent,
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        *,
        allow_manual_cpu: bool = False,
    ) -> bool:
        """Whether a signal may replace automatic Vulkan placement with CPU."""
        return bool(
            cls._cpu_fallback_request_eligible(
                intent, extra_args, env, allow_manual_cpu = allow_manual_cpu
            )
            and cls._is_vulkan_backend(binary)
            and cls._vulkan_prebuilt_was_auto_selected(binary)
        )

    @staticmethod
    def _as_cpu_fallback_intent(intent: GgufLoadIntent) -> GgufLoadIntent:
        return replace(
            intent,
            gpu_memory_mode = "manual",
            gpu_layers = 0,
            n_cpu_moe = 0,
            tensor_parallel = False,
            tensor_split = None,
            gpu_ids = None,
            cpu_fallback = True,
        )

    def _preserve_cpu_fallback_intent(
        self,
        intent: GgufLoadIntent,
        *,
        source_matches: bool = False,
    ) -> GgufLoadIntent:
        if not self._cpu_fallback_reason:
            return intent
        if not source_matches and not self.matches_load_source(intent):
            return intent
        extras = list(intent.extra_args) if intent.extra_args is not None else None
        # Judge the env the replay runs with, not this process's: _cpu_isolated_replay
        # pops every main-model placement var first. Using os.environ would drop the
        # recovery over a value no child saw, re-running the crash on every reload.
        replay_env = {
            name: value
            for name, value in os.environ.items()
            if name not in self._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS
            and name != "GGML_BACKEND_PATH"
        }
        if not self._cpu_fallback_request_eligible(
            intent,
            extras,
            replay_env,
            allow_manual_cpu = True,
        ):
            return intent
        return self._as_cpu_fallback_intent(intent)

    def _apply_cpu_fallback_state(
        self,
        intent: GgufLoadIntent,
        *,
        is_vision: bool,
        mmproj_has_audio: bool,
        disable_vision: bool,
        vision_disabled_by_user: bool,
    ) -> GgufLoadIntent:
        intent = self._as_cpu_fallback_intent(intent)
        self._gpu_memory_mode = intent.gpu_memory_mode
        self._gpu_layers = intent.gpu_layers
        self._n_cpu_moe = intent.n_cpu_moe
        self._tensor_split = intent.tensor_split
        self._tensor_parallel = intent.tensor_parallel
        self._gpu_ids = intent.gpu_ids
        self._requested_gpu_ids = None
        self._layer_preserves_tensor_intent = False
        self._is_vision = is_vision
        self._mmproj_has_audio = mmproj_has_audio
        # The caller returns straight after this, before the load's own assignment of
        # these two, so a recovery that skipped them left the response describing the
        # PREVIOUS load's Vision state: the control flips back on, and an unchanged
        # disable_vision request then fails runtime matching and reloads the model.
        self._disable_vision = bool(disable_vision)
        self._vision_disabled_by_user = bool(vision_disabled_by_user)
        self._cpu_fallback_reason = "vulkan_startup_crash"
        return intent

    @staticmethod
    def _launch_has_mmproj(cmd: Iterable[str], env: Mapping[str, str]) -> bool:
        """Whether this launch receives a projector from argv or the environment."""
        return _extra_args_set_any_flag(cmd, {"--mmproj", "-mm"}) or any(
            str(env.get(name) or "").strip()
            for name in ("LLAMA_ARG_MMPROJ", "LLAMA_ARG_MMPROJ_URL")
        )

    @classmethod
    def _cpu_isolated_replay(
        cls,
        cmd: Iterable[str],
        env: dict[str, str],
        server_caps: Mapping[str, object],
        *,
        drop_full_offload_threads: bool = False,
    ) -> Optional[list[str]]:
        """Build a replay that cannot initialize or schedule on a GPU.

        Unlike ``-ngl 0``, ``--device none`` removes GPU devices. Refuse companions
        that this binary cannot pin to CPU.
        """
        original = [str(arg) for arg in cmd]
        has_mmproj = cls._launch_has_mmproj(original, env)
        if has_mmproj and not _paravirtual_mmproj_pinnable(server_caps):
            return None
        has_draft = _extra_args_mtp_draft_path(original, env = env) is not None
        draft_ngl_flag = _paravirtual_draft_ngl_flag(server_caps) if has_draft else None
        if has_draft and draft_ngl_flag is None:
            return None

        replay = cls._strip_cpu_fallback_main_placement(original)
        if drop_full_offload_threads:
            # Windows full-offload tuning pins 2 threads and PASSIVE OpenMP because
            # the GPU was doing the work, so a CPU replay would decode on 2 cores.
            # Only Unsloth's own values: a user --threads override is reported by
            # the caller, and the env vars were setdefault'd.
            replay = _strip_flag_pairs(replay, _THREAD_OVERRIDE_FLAGS)
            for name in ("OMP_NUM_THREADS", "OMP_WAIT_POLICY"):
                env.pop(name, None)
        replay.extend(["--gpu-layers", "0", "--fit", "off", "--device", "none"])
        if has_mmproj:
            replay.append("--no-mmproj-offload")
        if has_draft:
            replay.extend([str(draft_ngl_flag), "0", "--device-draft", "none"])

        for name in (*cls._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS, "GGML_BACKEND_PATH"):
            env.pop(name, None)
        return replay

    def _prepare_cpu_fallback_launch(
        self,
        binary: Optional[str],
        cmd: Iterable[str],
        env: dict[str, str],
        server_caps: Mapping[str, object],
        *,
        drop_full_offload_threads: bool = False,
        avail_mib: Optional[int] = None,
    ) -> Optional[tuple[list[str], Optional[str], Optional[str]]]:
        """Build the CPU replay, or None when this install cannot host one.

        Returns ``(argv, cwd, pageable_note)``. The note is the sentence
        ``_page_an_oversized_unmapped_load`` produces when it had to override an
        unmapped load mode, for the caller to put in front of the user; None when
        nothing was rewritten.

        ``avail_mib`` is the host pool the preflight read, carried down so the rewrite
        below and ``_reprice_after_cpu_only_fallback`` price the replay against the same
        number and cannot reach opposite conclusions about the same child.
        """
        # Staging only removes GPU backends; a non-Vulkan install would report a
        # Vulkan crash that never happened.
        if not self._is_vulkan_backend(binary):
            return None
        replay = self._cpu_isolated_replay(
            cmd, env, server_caps, drop_full_offload_threads = drop_full_offload_threads
        )
        if replay is None:
            return None
        # The replay runs on no GPU, so the VRAM half of the fit that chose "none" is
        # void and mmap is what keeps the host-RAM load survivable: hand the CPU attempt
        # llama.cpp's auto back. Only Unsloth's own tokens; a user's is theirs.
        if self._fit_load_mode_flags:
            replay = _without_subsequence(replay, self._fit_load_mode_flags)
            logger.info(
                "Load mode: dropping the fit's --load-mode none for the CPU "
                "fallback; it runs entirely from host RAM."
            )
        # A user's own "--load-mode none" / "--no-mmap" survives that strip, by design,
        # and on this rung it is no longer the mode they were priced for: the replay
        # appends "--gpu-layers 0 --fit off --device none", so nothing credits VRAM and
        # the child holds the WHOLE model in host RAM. Unmapped that is one allocation
        # of the whole file rather than a mapping the kernel pages, i.e. an OOM kill on
        # a host that cannot hold it -- which the main launch path would have rewritten
        # before spawning. So price the replay on its OWN footprint (never the preflight
        # verdict, which credited a GPU placement this argv has just deleted) and apply
        # the same override.
        _priced_replay = replay
        replay, pageable_note = self._page_an_oversized_unmapped_load(
            replay,
            env,
            # honor_opt_out=False for the same reason _launch_is_oversized reads it that
            # way: UNSLOTH_ALLOW_HOST_OFFLOAD silences a message and must never withdraw
            # the rewrite that makes the load possible.
            lambda: bool(
                self._launch_host_shortfall_message(
                    _priced_replay,
                    (),
                    env,
                    child_has_no_gpu = True,
                    avail_mib = avail_mib,
                    honor_opt_out = False,
                )
            ),
        )
        cpu_binary = self._cpu_isolated_binary(binary)
        if cpu_binary is None:
            return None
        loader_env = self._llama_server_env_for_binary(cpu_binary)
        loader_path = _loader_path_var()
        env[loader_path] = loader_env[loader_path]
        replay[0] = cpu_binary
        # Staging covers only the executable and libraries, so keep Unsloth's working
        # directory: relative paths in user extra args resolve against it.
        return replay, None, pageable_note

    def _cpu_isolated_binary(self, binary: Optional[str]) -> Optional[str]:
        """Stage managed llama.cpp without GPU backend libraries.

        Backend loading precedes ``--device none``, so isolation prevents the
        Vulkan plugin from loading first.

        Gated on the install tree, not on _is_unsloth_managed_binary: that one
        answers "would `unsloth studio update` replace this file", which is a
        question about repair advice, and it now answers no for a
        --with-llama-cpp-dir tree. Staging a CPU copy needs neither the updater
        nor write access to the source, so those installs keep the fallback
        they had on every platform.
        """
        if not binary or not self._is_llama_install_tree(binary):
            return None
        source_binary = _resolve_llama_binary(binary)
        source_stamp = self._binary_stamp(source_binary)
        runtime = self._cpu_fallback_runtime
        if (
            runtime is not None
            and runtime.source_binary == source_binary
            and runtime.source_stamp == source_stamp
        ):
            if runtime.staged_binary.is_file():
                return str(runtime.staged_binary)
        self._cleanup_cpu_fallback_runtime()
        staged_runtime = None
        try:
            runtime_root = _swa_cache_path().parent / "runtime"
            runtime_root.mkdir(parents = True, exist_ok = True)
            _sweep_abandoned_cpu_runtimes(runtime_root)
            staged_runtime = tempfile.TemporaryDirectory(
                prefix = "llama-cpu-",
                dir = runtime_root,
            )
            staged_dir = Path(staged_runtime.name)
            # A kill -9 skips TemporaryDirectory's atexit hook, so stamp the owner
            # and let the next stage collect what no live Unsloth holds.
            (staged_dir / _CPU_RUNTIME_OWNER_FILE).write_text(str(os.getpid()), encoding = "utf-8")
            lib_dir = _llama_lib_dir(str(source_binary))
            gpu_backend = _GGML_GPU_BACKEND_RE
            cpu_library_present = False
            for source in lib_dir.iterdir():
                try:
                    resolved = source.resolve(strict = True)
                except OSError:
                    continue
                name = source.name
                is_shared = name.endswith((".dll", ".dylib")) or ".so" in name
                if resolved != source_binary and not is_shared:
                    continue
                if gpu_backend.match(name.lower()):
                    continue
                destination = staged_dir / name
                if destination.exists():
                    continue
                try:
                    os.link(resolved, destination)
                except OSError:
                    shutil.copy2(resolved, destination)
                if name.lower().startswith(("libggml-cpu", "ggml-cpu")):
                    cpu_library_present = True
            staged_binary = staged_dir / source_binary.name
            if not staged_binary.is_file() or not cpu_library_present:
                staged_runtime.cleanup()
                return None
        except (OSError, ValueError):
            if staged_runtime is not None:
                with contextlib.suppress(Exception):
                    staged_runtime.cleanup()
            return None
        self._cpu_fallback_runtime = _CpuFallbackRuntime(
            tempdir = staged_runtime,
            source_binary = source_binary,
            staged_binary = staged_binary,
            source_stamp = source_stamp,
        )
        return str(staged_binary)

    @staticmethod
    def _binary_stamp(path: Path) -> tuple:
        try:
            stat = path.stat()
        except OSError:
            return ()
        return (stat.st_ino, stat.st_size, stat.st_mtime_ns)

    @staticmethod
    def _binary_revision(binary: Optional[str]) -> tuple:
        """Which build of llama-server a path currently holds, () when unreadable.

        The path alone cannot say, since an update swaps the file in place. Empty on an
        unreadable file so callers read "cannot tell" as "unchanged": the install window
        is itself unreadable, and treating it as a finished update would tear a healthy
        server down for a binary that is not there yet.
        """
        if not binary:
            return ()
        stamp = LlamaCppBackend._binary_stamp(Path(binary))
        return (str(binary),) + stamp if stamp else ()

    def _cleanup_cpu_fallback_runtime(self) -> None:
        runtime = getattr(self, "_cpu_fallback_runtime", None)
        self._cpu_fallback_runtime = None
        # cleanup() detaches its finalizer before removing the tree, so dropping a
        # failed one (locked DLL on Windows) orphans it. Retry it on the next call.
        pending = getattr(self, "_pending_cpu_fallback_cleanups", [])
        if runtime is not None:
            pending.append(runtime.tempdir)
        retry = []
        for tempdir in pending:
            try:
                tempdir.cleanup()
            except Exception:
                retry.append(tempdir)
        self._pending_cpu_fallback_cleanups = retry

    def _cleanup_failed_cpu_fallback(self) -> None:
        """Remove every process and staged artifact from a terminal CPU replay."""
        self._kill_process()
        self._cpu_fallback_reason = None
        self._cleanup_cpu_fallback_runtime()

    @staticmethod
    def _gpu_init_crash_message(binary: Optional[str] = None) -> str:
        """Return backend-specific advice for a GPU initialization crash."""
        base = (
            "llama-server crashed at startup on both the vision and text-only "
            "attempts -- a GPU driver/runtime initialization crash, not a model "
            "or vision-projector problem. "
        )
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        backend = next((name for name in ("cuda", "hip", "vulkan") if name in backends), None)
        if backend == "vulkan":
            return base + (
                "This build uses Vulkan, which Unsloth selects when it detects an "
                "Intel or AMD GPU. Older integrated GPUs and their drivers can fault "
                "inside Vulkan device initialization. Update your Vulkan driver (Mesa "
                "on Linux), or reinstall llama.cpp on CPU with "
                "UNSLOTH_LLAMA_CPP_BACKEND=cpu unsloth studio update."
            )
        if backend == "hip":
            return base + (
                "This often means an unsupported secondary GPU; on AMD/ROCm, hide it "
                "with ROCR_VISIBLE_DEVICES (e.g. ROCR_VISIBLE_DEVICES=0 exposes only "
                "the first GPU) before launching Unsloth Studio."
            )
        if backend == "cuda":
            return base + (
                "This often means an unsupported secondary GPU or a driver/CUDA "
                "runtime mismatch; hide the extra GPU with CUDA_VISIBLE_DEVICES (e.g. "
                "CUDA_VISIBLE_DEVICES=0 exposes only the first GPU) before launching "
                "Unsloth Studio, or update the NVIDIA driver."
            )
        return base + (
            "Check the llama-server log and your GPU driver, and make sure the "
            "installed llama.cpp build matches this machine's GPU."
        )

    @staticmethod
    def _redacted_cmd_for_log(cmd: "list[str]") -> "list[str]":
        """Copy of cmd with the value after --api-key replaced by <redacted>."""
        out = list(cmd)
        if "--api-key" in out:
            ki = out.index("--api-key") + 1
            if ki < len(out):
                out[ki] = "<redacted>"
        return out

    def _start_llama_process(self, cmd: list[str], env: dict) -> None:
        """Spawn llama-server from cmd and start draining its output.

        Caller holds self._lock. Resets the stdout buffer, opens a fresh
        per-attempt tee log, launches the process, and starts the drain
        thread. Used for the initial start and the text-only mmproj retry.
        """
        # Defensive kill: if a concurrent load slipped past Phase 1
        # (because its `self._process` was None at the time) and already
        # stored a Popen handle here, drop that orphan before we overwrite
        # the reference. See issue #5161.
        self._kill_process()

        self._stdout_lines = []
        # Tee llama-server output to a dedicated log file so a post-mortem
        # in CI (or after a remote-debug session) has the full subprocess
        # trail even when the parent only stored the last 50 lines.
        self._llama_log_fh = None
        try:
            log_dir = _swa_cache_path().parent / "logs" / "llama-server"
            log_dir.mkdir(parents = True, exist_ok = True)
            self._llama_log_path = log_dir / f"llama-{int(time.time())}-port-{self._port}.log"
            self._llama_log_fh = open(
                self._llama_log_path,
                "w",
                encoding = "utf-8",
                buffering = 1,
            )
            # After the open, so the cap counts this file and can never delete it.
            prune_log_dir(log_dir, "llama-*.log", protect = self._llama_log_path)
            logger.info(f"llama-server stdout/stderr -> {self._llama_log_path}")
        except (OSError, UnicodeDecodeError) as e:
            # Best-effort; never block the load on logging.
            logger.debug(f"Could not open llama-server log file: {e}")
            self._llama_log_path = None

        # Log the argv per attempt (the text-only mmproj retry re-enters here
        # with --mmproj stripped), redacting the API key.
        logger.info(f"Starting llama-server: {' '.join(self._redacted_cmd_for_log(cmd))}")

        self._process = subprocess.Popen(
            cmd,
            stdout = subprocess.PIPE,
            stderr = subprocess.STDOUT,
            text = True,
            encoding = "utf-8",
            errors = "replace",
            env = env,
            **_windows_hidden_subprocess_kwargs(),
            **_child_popen_kwargs(),
        )
        # Cross-session backstop: record the PID so a later startup can reap this
        # server if parent-death cleanup did not run (macOS / best-effort failure).
        self._record_server_pid(self._process.pid)

        # Start background thread to drain stdout and prevent pipe deadlock
        self._stdout_thread = threading.Thread(
            target = self._drain_stdout, daemon = True, name = "llama-stdout"
        )
        self._stdout_thread.start()

    @contextlib.contextmanager
    def _serial_load_scope(self):
        """Hold the serial load lock and release pending launch state with it.

        The pending fraction is armed before the download, so every exit ahead of
        the spawn has to give it back or the settings route, which reads it before
        is_active, answers from a load that is over. Clearing it on the way out of
        the lock rather than on the way out of the call is what makes that safe:
        a queued load arms its own value the instant it takes the lock, and a
        clear running after that point would discard the marker of a load that is
        still going.
        """
        with self._serial_load_lock:
            try:
                yield
            finally:
                self._vram_fraction_pending = None
                self._binary_revision_pending = None

    @_with_gguf_load_marker
    def load_model(
        self,
        intent: GgufLoadIntent,
        load_cancel_event: Optional[threading.Event] = None,
    ) -> bool:
        """Start llama-server from one immutable load intent."""

        def _load_cancelled() -> bool:
            return self._cancel_event.is_set() or bool(
                load_cancel_event is not None and load_cancel_event.is_set()
            )

        gguf_path = intent.gguf_path
        mmproj_path = intent.mmproj_path
        mtp_draft_path = intent.mtp_draft_path
        dspark_draft_path = intent.dspark_draft_path
        dflash_draft_path = intent.dflash_draft_path
        hf_repo = intent.hf_repo
        hf_variant = intent.hf_variant
        hf_token = intent.hf_token
        model_identifier = intent.model_identifier
        is_vision = intent.is_vision
        disable_vision = intent.disable_vision
        n_ctx = intent.n_ctx
        chat_template_override = intent.chat_template_override
        cache_type_kv = intent.cache_type_kv
        speculative_type = intent.speculative_type
        spec_draft_n_max = intent.spec_draft_n_max
        tensor_parallel = intent.tensor_parallel
        gpu_memory_mode = intent.gpu_memory_mode
        gpu_layers = intent.gpu_layers
        n_cpu_moe = intent.n_cpu_moe
        tensor_split = list(intent.tensor_split) if intent.tensor_split is not None else None
        gpu_ids = list(intent.gpu_ids) if intent.gpu_ids is not None else None
        gpu_ids_are_vulkan_ordinals = intent.gpu_ids_are_vulkan_ordinals
        n_threads = intent.n_threads
        n_parallel = intent.n_parallel
        n_batch = intent.n_batch
        n_ubatch = intent.n_ubatch
        load_mode = intent.load_mode
        spec_draft_cache_type = intent.spec_draft_cache_type
        ctx_checkpoints = intent.ctx_checkpoints
        cache_ram = intent.cache_ram
        extra_args = list(intent.extra_args) if intent.extra_args is not None else None
        preserve_multi_gpu_on_layer = intent.preserve_multi_gpu_on_layer
        # Serialise the whole load so concurrent /load calls never leave two
        # llama-server processes alive (#5401 / #5161). Doesn't block /unload.
        with self._serial_load_scope():
            # In-app update swapping binaries: refuse fast (set under this lock,
            # so any in-flight load has drained) instead of using a half-swapped one.
            if getattr(self, "_llama_update_in_progress", False):
                raise RuntimeError("llama.cpp is updating; try again in a moment.")

            intent = self._preserve_cpu_fallback_intent(intent)
            tensor_parallel = intent.tensor_parallel
            gpu_memory_mode = intent.gpu_memory_mode
            gpu_layers = intent.gpu_layers
            n_cpu_moe = intent.n_cpu_moe
            tensor_split = list(intent.tensor_split) if intent.tensor_split is not None else None
            gpu_ids = list(intent.gpu_ids) if intent.gpu_ids is not None else None

            # Read before the pin below rewrites every placement, Auto included, to
            # manual/0. Owning the memory budget is a property of what was asked for,
            # and the three Metal context guards further down skip themselves on it.
            _caller_owns_budget = gpu_memory_mode == "manual" and gpu_layers >= 0

            # A virtualised Apple GPU corrupts every offloaded layer, so pin GGUF
            # inference to CPU there; physical Apple Silicon is untouched. Settled
            # ABOVE the duplicate-load check (and the KV estimates) so the compared
            # placement is the one that launches: the launch records the normalized
            # values, so comparing the raw request would miss the fast path and tear
            # down a healthy CPU server on every repeat Auto /load.
            # Keyed on the hardware, not the request, and applied whole rather than
            # only when the request asks for offload: Manual + 0 layers already places
            # the main model on CPU, but the companions below (mmproj, a separate
            # drafter) do not read --gpu-layers, and an `-ot ".*=Metal"` the route never
            # strips would put weights straight back on the corrupt device.
            # paravirtual_normalized_request is the one definition of that rewrite,
            # shared with both duplicate-load comparators.
            _paravirtual_cpu_forced = _metal_device_is_paravirtual()
            if _paravirtual_cpu_forced:
                _pv_placement = paravirtual_normalized_request(
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    tensor_parallel = tensor_parallel,
                    tensor_split = tensor_split,
                    n_cpu_moe = n_cpu_moe,
                    extra_args = extra_args,
                )
                if (gpu_memory_mode, gpu_layers) != (
                    _pv_placement.gpu_memory_mode,
                    _pv_placement.gpu_layers,
                ):
                    logger.warning(
                        "Forcing gpu_layers=0 for %s: this Mac's Metal device is "
                        "virtualised and offloaded layers produce corrupt output.",
                        model_identifier or gguf_path,
                    )
                if extra_args and _pv_placement.extra_args != list(extra_args):
                    logger.warning(
                        "Dropping offload flags from extra args on a "
                        "virtualised Metal device: %s -> %s",
                        list(extra_args),
                        _pv_placement.extra_args,
                    )
                if tensor_parallel or tensor_split:
                    logger.info(
                        "Virtualised Metal device: dropping tensor split/parallel "
                        "flags (nothing to split on the GPU)"
                    )
                gpu_memory_mode = _pv_placement.gpu_memory_mode
                gpu_layers = _pv_placement.gpu_layers
                n_cpu_moe = _pv_placement.n_cpu_moe
                extra_args = _pv_placement.extra_args
                # Spelled out (not read off _pv_placement, which returns exactly these)
                # so tests/test_tp_vision_regression.py's TP-drop allowlist sees this site.
                tensor_parallel = False
                tensor_split = None
                # The intent is what the duplicate-load check compares and what a retry
                # replays, so carry the rewrite into it rather than the raw request.
                intent = replace(
                    intent,
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    n_cpu_moe = n_cpu_moe,
                    extra_args = tuple(extra_args) if extra_args is not None else None,
                    tensor_parallel = False,
                    tensor_split = None,
                )

            # Fraction of each card this load may claim, resolved ONCE so ranking
            # and fitting price the same number (mixed totals mis-order otherwise);
            # unset means _CTX_FIT_VRAM_FRACTION, the historical behaviour. Under
            # the lock and ahead of the duplicate check, or a queued load would plan
            # with a stale fraction while the check reads the live one, and could
            # evict the resident child for a budget it then fails to apply.
            _vram_frac = _active_vram_fraction()
            # How far this budget moves llama.cpp's own fitter margin, set once the
            # devices are known. Signed: lowering holds more back, raising packs
            # closer to the card. Zero at the default.
            _fit_target_delta_mib = 0.0
            # Set only if that margin actually reached the command line, which is
            # what makes the child budget-priced in a mode the planner skipped.
            _fit_target_priced = False

            def _budget_priced_placement() -> Optional[float]:
                """The fraction this child was sized against, or None if it wasn't.

                Read at call time, because both names it closes over are rebound
                during the load. Every consumer of the fraction is gated on a
                non-empty ``gpus``, so manual mode and a host with no discrete GPU
                plan without it; and an auto Vulkan crash that recovers on CPU
                rewrites the intent to CPU placement while leaving ``gpus``
                populated from the attempt that failed. Recording a budget for
                either would make a later change to the setting evict a healthy
                child for a reload that cannot move anything.
                """
                if intent.cpu_fallback:
                    return None
                if gpus:
                    return _vram_frac
                # Manual + Auto empties gpus to bypass the planner, but --fit-target
                # still carries the budget to llama.cpp's fitter, so that child IS
                # priced. Without this a later change reports no reload needed and
                # the duplicate check adopts a child on the old margin.
                return _vram_frac if _fit_target_priced else None

            # Armed before the duplicate check, not merely cleared: on an inactive
            # backend a save landing in that gap saw no pending value and no live
            # process, so it was told no reload was needed while this load went on to
            # launch against the captured fraction. The load scope hands it back on
            # every exit, the fast path below included.
            self._vram_fraction_pending = _vram_frac
            # _vram_fraction_launched is committed at the launch site instead: the
            # duplicate-load fast path, a cancellation and every failed preflight
            # return with the previous child still serving, so setting it here would
            # claim that stale child carries the new budget and hide its reload.

            # Duplicate /load that raced past the route check: do nothing if the
            # live server already satisfies this request.
            if self.adopt_load_intent_if_matched(intent):
                logger.info(
                    f"load_model: backend already in target state for "
                    f"'{model_identifier}', skipping reload"
                )
                # Retry probe only if a prior attempt didn't finish.
                if not self._audio_probed:
                    try:
                        detected = self._detect_audio_type_strict()
                        self._audio_probed = True
                    except Exception as exc:
                        logger.debug("Fast-path audio probe failed: %s", exc)
                        detected = None
                    if not self._apply_detected_audio(detected):
                        return False
                if not self._healthy:
                    return False
                return True

            # Stays armed through the download and planning, which can take minutes.
            # Placement is undecided until the spawn site narrows it: a needless
            # reload prompt beats sizing a child against a replaced budget.
            self._cancel_event.clear()
            if _load_cancelled():
                logger.info("Load cancelled before GGUF resolution")
                return False

            # Resolve llama-server now but defer a not-found error: a block-diffusion
            # GGUF uses the diffusion runner, and its arch is only known after the header.
            # Serialize this snapshot with settings writes. If a save wins the
            # guard, this load sees the new folder; if the load wins, the save
            # response compares against this pending old revision and asks for a
            # reload even before Popen makes is_active true.
            from utils.llama_cpp_path_settings import llama_cpp_path_selection_guard

            with llama_cpp_path_selection_guard():
                binary = self._find_llama_server_binary()
                # macOS: launch the resolved server, never a shell entrypoint. SIP
                # purges DYLD_* while starting the protected /bin/sh a wrapper
                # entrypoint runs under, so the loader path built for the child
                # would not survive the wrapper's own exec (#8566). The installer
                # writes a wrapper only when it cannot symlink, and that wrapper
                # does nothing but exec the target with "$@", so this is the same
                # launch minus the shell hop. The resolved path stays inside the
                # managed install, so provenance-aware advice is unaffected.
                # Resolved here rather than at the later reset so every consumer of
                # `binary` below (capability probe, revision stamp) shares one path
                # space; `_binary_changed_since_launch` compares against this one.
                binary = self._exec_path_for_launch(binary)
                self._binary_revision_pending = self._binary_revision(binary)

            # Every capability answer shaping this launch, latching whether any was a
            # guess. Accumulated, not sampled: the decisions straddle the whole load (slot
            # clamp before an HF download, command build after), and with a 30s window a
            # later success would otherwise erase an earlier one that already degraded it.
            _launch_probe_inconclusive = False
            # Set where flash attention ends up off with the argv unable to say
            # so: a build that has no --flash-attn at all, and the crash-recovery
            # retry on a build whose flag takes no value, which disables FA by
            # dropping it. Either way the default below has to carry the answer.
            _flash_attn_known_off = False

            def _launch_caps(bin_path):
                nonlocal _launch_probe_inconclusive
                caps = self.probe_server_capabilities(bin_path)
                if caps.get("mtp_probe_inconclusive"):
                    _launch_probe_inconclusive = True
                return caps

            is_vulkan_backend = self._is_vulkan_backend(binary)
            _vulkan_ordinal_pin = (
                is_vulkan_backend and bool(gpu_ids) and gpu_ids_are_vulkan_ordinals is not False
            )
            _cpu_only_pin = (
                bool(gpu_ids) and not is_vulkan_backend and self._backend_lacks_gpu_lib(binary)
            )

            # Without --kv-unified an explicit --parallel N splits -c into windows of -c/N, so on a
            # build lacking the flag the default of 4 would quarter every context window for a
            # feature it cannot serve: fall back to one slot. Ahead of the KV estimates so the
            # fit matches what launches.
            if n_parallel > 1 and binary and not _launch_caps(binary).get("supports_kv_unified"):
                logger.warning(
                    "llama-server at %s has no --kv-unified, so %d parallel slots would "
                    "split the context window %d ways. Using 1 slot instead; update "
                    "llama.cpp to run chats in parallel.",
                    binary,
                    n_parallel,
                    n_parallel,
                )
                n_parallel = 1  # allow-slot-clamp: the build cannot serve more

            # MTP does not clamp the slots. #7717 did, for a draft-acceptance collapse, but on
            # b10310 four MTP slots hit 1.97x the batch throughput of one, beating four without.
            # llama.cpp#26031 reports concurrent MTP garbling on hybrid archs; it did not
            # reproduce here (qwen35 and qwen35moe on CUDA, 24 staggered uneven requests).

            # ── Vulkan-ordinal preflight (BEFORE the Phase 1 kill) ────────
            # An explicit Vulkan pin the ggml probe never enumerated cannot be honored.
            # Validate it ABOVE the kill so an invalid selection leaves the live model
            # untouched: CUDA ids are range-checked at the route, but Vulkan ordinals are
            # not, so a stale gpu_ids=[99] used to kill the server then 400, leaving
            # nothing running (#7239). _get_gpu_memory needs only the binary (safe pre-
            # download) and reuses the later fit's issubset logic. Guarded on a found
            # Vulkan build + a pin so a deferred not-found stays deferred for diffusion,
            # and on the ordinals being unconfirmed: a caller-confirmed physical CUDA pin
            # is not in this namespace and must not be range-checked against it.
            if _vulkan_ordinal_pin and binary:
                _pf_wanted = {int(x) for x in gpu_ids}
                _pf_probed = {g[0] for g in self._get_gpu_memory(binary)}
                if not _pf_wanted.issubset(_pf_probed):
                    raise ValueError(
                        f"Requested Vulkan GPU ordinal(s) {sorted(_pf_wanted)} not "
                        f"present. Available Vulkan devices: {sorted(_pf_probed)}."
                    )

            # Classify before killing the healthy server (#7205); Phase 2 reuses this
            # path. Diffusion changes the meaning or validity of requested placement,
            # so both the remote and the local branch settle it above the teardown.
            # A zero-layer diffusion pin this shim cannot apply is refused; probe
            # once here so the HF case can be settled above the teardown as well.
            _pv_diffusion_unpinnable = bool(
                _paravirtual_cpu_forced and not self.diffusion_split_supported()
            )
            _preflight_model_path = None
            if hf_repo and (_vulkan_ordinal_pin or _cpu_only_pin or _pv_diffusion_unpinnable):
                _resolved_repo = _resolve_repo_id_casing(hf_repo)
                if _resolved_repo != hf_repo:
                    logger.info(
                        "Using cached repo_id casing '%s' for requested '%s'",
                        _resolved_repo,
                        hf_repo,
                    )
                    hf_repo = _resolved_repo
                with _hf_offline_if_unreachable():
                    _preflight_model_path = self._download_gguf(
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        hf_token = hf_token,
                    )
                _preflight_is_diffusion = self._gguf_path_is_diffusion(
                    _preflight_model_path, model_identifier
                )
                if _preflight_is_diffusion:
                    if _vulkan_ordinal_pin:
                        raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)
                    if _pv_diffusion_unpinnable:
                        raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)
                elif _cpu_only_pin:
                    raise ValueError(
                        f"Requested gpu_ids {list(gpu_ids)} but the llama.cpp build has "
                        "no GPU backend (CPU-only build); it would ignore the pin and run "
                        "on CPU. Omit gpu_ids to run on CPU."
                    )
            elif is_vulkan_backend and gpu_ids and gguf_path and not hf_repo:
                if not Path(gguf_path).is_file():
                    raise FileNotFoundError(f"GGUF file not found: {gguf_path}")

            # Only an ordinal pin is ambiguous for the diffusion runner; a
            # caller-confirmed physical pin keeps its CUDA placement path.
            if _vulkan_ordinal_pin and gguf_path and not hf_repo:
                self._reject_vulkan_diffusion_gpu_ids_before_teardown(
                    gguf_path,
                    model_identifier,
                )
            # Same for the unpinnable diffusion split: _start_diffusion_server enforces
            # it everywhere, but only after the teardown, so settle the local case here
            # and leave the running server alone.
            if (
                _pv_diffusion_unpinnable
                and gguf_path
                and not hf_repo
                and self._gguf_path_is_diffusion(gguf_path, model_identifier)
            ):
                raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)

            # An image / video GGUF already on disk is refused HERE, before the teardown:
            # the header answers this without llama-server, so there is no reason to make
            # the user pay their resident chat model for it.
            if gguf_path and not hf_repo and Path(gguf_path).is_file():
                _early_non_chat = self._non_chat_gguf_refusal_for_path(gguf_path, model_identifier)
                if _early_non_chat:
                    logger.error(
                        "Refusing non-chat GGUF before teardown: %s (%s)",
                        _early_non_chat,
                        gguf_path,
                    )
                    raise ValueError(_early_non_chat)

            # The same refusal for a REPO load, which is what the Model Hub actually sends:
            # the route resolves every Hub model to hf_repo, so leaving this to the
            # post-download check killed the live model first in the reported case. The file
            # does not exist yet, but a header-sized byte range decides it (see
            # _remote_non_chat_gguf_refusal). When a preflight above already fetched the
            # file, judge that instead -- same verdict, no request. Fails open into the
            # post-download check below, which stays as the backstop.
            if hf_repo:
                # Same offline guard the download below uses: the probe asks the Hub twice
                # before reading any local header (the file listing, then the cached
                # candidate's revision sizes), and each would wait out its retry backoff,
                # putting two timeouts in front of a cached load that needs no network. The
                # guard is memoised and only bites when the Hub really is unreachable.
                with _hf_offline_if_unreachable():
                    _early_non_chat = (
                        self._non_chat_gguf_refusal_for_path(
                            _preflight_model_path, model_identifier
                        )
                        if _preflight_model_path
                        else self._remote_non_chat_gguf_refusal(
                            hf_repo = hf_repo,
                            hf_variant = hf_variant,
                            hf_token = hf_token,
                            model_identifier = model_identifier,
                        )
                    )
                if _early_non_chat:
                    logger.error(
                        "Refusing non-chat GGUF before teardown: %s (%s)",
                        _early_non_chat,
                        hf_repo,
                    )
                    raise ValueError(_early_non_chat)

            # The probe can take a moment on a slow Hub, so re-read the cancel flag rather
            # than tearing down a healthy server for a load that was called off.
            if _load_cancelled():
                logger.info("Load cancelled before teardown")
                return False

            # ── Phase 1: kill old process (under lock, fast) ──────────
            # The previous load's advisory is dropped HERE, at the one point this call
            # commits to replacing the resident server, rather than on the first line of
            # load_model. Everything above can stand down with that server still serving
            # (the update-in-progress refusal, the duplicate-load fast path, an
            # unenumerated Vulkan pin, a diffusion or non-chat refusal, a cancel), and
            # clearing on the way past retired the advisory of a child that keeps
            # running -- so the next `already_loaded` answered memory_warning: null for
            # an oversized model that is still paging from disk. Placing the reset at
            # the teardown rather than restoring it on each rejected path is what keeps
            # that true for early returns added later: this is the line that separates
            # "the old child survives" from "the old child is gone", so a new stand-down
            # above it is covered by construction and needs no bookkeeping of its own.
            # Nothing between the top of load_model and this point records a warning.
            _replaying_cpu_fallback = intent.cpu_fallback
            with self._lock:
                self._begin_load_warnings()
                self._kill_process()
                if not _replaying_cpu_fallback:
                    self._cpu_fallback_reason = None
                    self._cleanup_cpu_fallback_runtime()

                self._mmproj_fallback_reason = None
            # Both describe the process just killed, so they are reset HERE rather than
            # where the binary is resolved: everything above can bail with the old server
            # still running (a stand-down, a non-chat refusal, a cancel), and resetting on
            # the way past would tell the next Apply that the resident process launched from
            # the binary installed now and is owed no DFlash retry -- so an Apply after
            # `unsloth studio update` or a retryable sidecar failure would dedupe against it
            # instead of relaunching. Nothing between the two points reads either field.
            #
            # Kept so a stand-down blamed on the binary can later tell a real update
            # from the same file still being installed.
            self._launch_binary_revision = self._binary_revision(binary)
            # Cleared per load, not only where the fetch runs: a local-file load never
            # reaches the DFlash fetch, and a verdict left over from the previous model
            # would make every Apply for this one reload.
            self._dflash_retry_needed = False

            # ── Phase 2: download (NO lock held, so cancel can proceed) ──
            # mtp_draft_path arrives set for local Gemma loads (detected
            # sibling); for -hf loads it's None here and resolved just below.
            # The canonical mode drives which drafter is downloaded, sized and
            # launched, so resolve it once before either branch can use it.
            _spec_canon = _canonicalize_spec_mode(speculative_type) or "auto"
            # Scope HF_HUB_OFFLINE to the download block only when DNS is
            # dead; cleanup runs even on exception so a transient hiccup
            # can't quarantine future loads.
            if hf_repo:
                # Resolve the requested repo id to its cached canonical casing once,
                # up front, so the main GGUF and its companions (mmproj / MTP drafter)
                # all resolve from the same cache entry. Otherwise a case-variant
                # request resolves the main file from the canonical cache dir while the
                # companions keep the requested casing and miss the cached files.
                _resolved_repo = _resolve_repo_id_casing(hf_repo)
                if _resolved_repo != hf_repo:
                    logger.info(
                        "Using cached repo_id casing '%s' for requested '%s'",
                        _resolved_repo,
                        hf_repo,
                    )
                    hf_repo = _resolved_repo
                with _hf_offline_if_unreachable():
                    model_path = _preflight_model_path
                    if model_path is None:
                        # Revalidate the carried file before skipping download resolution.
                        model_path = self._verified_cached_gguf(intent, hf_repo, hf_variant)
                        if model_path:
                            logger.info("Reusing verified cached GGUF: %s", model_path)
                    if model_path is None:
                        model_path = self._download_gguf(
                            hf_repo = hf_repo,
                            hf_variant = hf_variant,
                            hf_token = hf_token,
                        )
                    # Auto-download mmproj for vision models unless opted out. Vision
                    # switched off does NOT opt out: remote discovery calls any mmproj
                    # filename vision, and only the file's metadata separates an image
                    # tower from an audio encoder (ultravox, Voxtral, Qwen3-ASR).
                    # Skipping the fetch would take audio away from an audio-only model
                    # to save one small companion file. Suppression happens at the
                    # resolve, where the metadata is readable.
                    if is_vision and not mmproj_path and not extra_args_disable_mmproj(extra_args):
                        mmproj_path = self._download_mmproj(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            near_path = model_path,
                        )
                    # Auto-download the separate MTP drafter (e.g. Gemma) when
                    # the requested spec mode can use it. Repos with the head
                    # baked into the main GGUF (Qwen) have no mtp- sibling and
                    # this no-ops, so the size gate stays out of it: a separate
                    # drafter speeds up even sub-3B (Gemma E2B), and the resolver
                    # below decides the final emission. Skipped only when the
                    # user disabled MTP or drives --spec-type manually.
                    if (
                        not mtp_draft_path
                        and _spec_canon in ("auto", "mtp", "mtp+ngram")
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        mtp_draft_path = self._download_mtp(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            near_path = model_path,
                        )
                    # "auto" is included: DSpark is the default whenever the repo
                    # ships a sidecar. Repos without one no-op, exactly like the
                    # MTP fetch above, so this costs one listing and no download.
                    if (
                        not dspark_draft_path
                        and _spec_canon in ("auto", "dspark")
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        dspark_draft_path = self._download_dspark(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            near_path = model_path,
                            binary = binary,
                            caps_probe = _launch_caps,
                        )
                    # DFlash: same shape, and Auto is included for the same
                    # reason, but it is not gated behind an opt-in the way the
                    # ~11 GB DSpark sidecar is. The published sidecar is ~1.5 GiB
                    # and ships in the model's own GGUF repo, so under Auto it
                    # costs about what the MTP drafter costs. Repos without one
                    # no-op after a single listing.
                    # Under Auto, DSpark takes first refusal in the promotion
                    # below, so a repo that ships both kinds would never launch
                    # the DFlash sidecar. Fetching it anyway costs ~1.5 GiB of
                    # bandwidth and cache for a file that cannot be used, so the
                    # Auto fetch stands down once DSpark has resolved. It has to
                    # be the same "resolved" the promotion means, capability and
                    # all: a DSpark path this binary cannot launch loses the
                    # promotion, so standing down on it would leave a
                    # DFlash-capable binary with no drafter at all. An explicit
                    # "dflash" request still fetches.
                    if (
                        not dflash_draft_path
                        and _spec_canon in ("auto", "dflash")
                        and not self._dspark_wins_auto(
                            binary = binary,
                            dspark_draft_path = dspark_draft_path,
                            spec_canon = _spec_canon,
                            extra_args = extra_args,
                        )
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        dflash_draft_path = self._download_dflash(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            near_path = model_path,
                            binary = binary,
                        )
            elif gguf_path:
                if not Path(gguf_path).is_file():
                    raise FileNotFoundError(f"GGUF file not found: {gguf_path}")
                model_path = gguf_path
            else:
                raise ValueError("Either gguf_path or hf_repo must be provided")

            # Set identifier early so _read_gguf_metadata can use it (DeepSeek).
            self._model_identifier = model_identifier

            # Auto resolves to DSpark whenever a sidecar is available and this
            # binary can run it: 1.84x decode on 4x B200 and 1.91x on one, against
            # the ngram-mod fallback this architecture would otherwise get. The
            # capability gate lives in _dspark_wins_auto, shared with the DFlash
            # fetch above so the fetch and the promotion cannot disagree about
            # whether Auto is going to end up on DSpark.
            if self._dspark_wins_auto(
                binary = binary,
                dspark_draft_path = dspark_draft_path,
                spec_canon = _spec_canon,
                extra_args = extra_args,
                caps = _launch_caps,
            ):
                _spec_canon = "dspark"
                logger.info("Auto: DSpark sidecar available, using draft-dspark.")

            # DFlash is the other Auto promotion, on the same capability gate.
            # DSpark keeps first refusal (llama.cpp's own downloader ranks it
            # ahead too), so a repo shipping both is unchanged; in practice a
            # repo ships one kind or neither.
            if (
                _spec_canon == "auto"
                and dflash_draft_path
                and not _extra_args_set_spec_type(extra_args)
            ):
                try:
                    if _launch_caps(binary).get("supports_dflash"):
                        _spec_canon = "dflash"
                        logger.info("Auto: DFlash sidecar available, using draft-dflash.")
                except Exception as exc:
                    logger.debug("DFlash capability probe failed during Auto: %s", exc)

            # MTP and DSpark are mutually exclusive, and the drafter sizing and
            # lifecycle path below is architecture agnostic, so it carries the
            # one drafter the mode selected. From here mtp_draft_path means
            # "the drafter this load will launch", whichever kind that is;
            # _spec_canon is the only thing that says which.
            if _spec_canon == "dspark":
                mtp_draft_path = dspark_draft_path
            elif _spec_canon == "dflash":
                mtp_draft_path = dflash_draft_path

            # Read GGUF metadata (context_length, chat_template); header-only.
            self._read_gguf_metadata(model_path)

            if _load_cancelled():
                logger.info("Load cancelled after download phase")
                return False

            # Backstop for everything the pre-teardown probes fail open on: refuse from the
            # header rather than watching llama-server die as "failed to start".
            non_chat = self._non_chat_gguf_refusal(model_path)
            if non_chat:
                logger.error("Refusing non-chat GGUF: %s (%s)", non_chat, model_path)
                raise ValueError(non_chat)

            # Block-diffusion GGUFs (DiffusionGemma) cannot run on llama-server;
            # serve them with the diffusion runner (same OpenAI-compat interface).
            if self._is_diffusion:
                # Final defense: route and pre-teardown preflights reject before Phase 1.
                # The diffusion runner cannot translate Vulkan ordinals to CUDA IDs, so
                # this fires unless the caller confirmed the pin is physical CUDA IDs.
                if is_vulkan_backend and gpu_ids and gpu_ids_are_vulkan_ordinals is not False:
                    raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)
                # Not a tensor/layer GGUF: clear any preserved-fallback flag from a
                # prior load (this path skips the command builder that clears it).
                self._layer_preserves_tensor_intent = False
                # Same reason: a diffusion server never carries a drafter, only unload
                # clears these, and the dedupe compares the pair, so a stale one
                # reloads a healthy diffusion server on every Apply.
                self._mtp_draft_path = None
                self._mtp_draft_suppressed_path = None
                # And the verdict on why the last load had no drafter, for the same
                # reason once more: _build_speculative_flags clears it at the top of
                # every load that reaches it, and this path never does. Both retry
                # rules in the dedupe read it -- the drafter one and the binary one --
                # and a stale answer would relaunch this server on every Apply for a
                # drafter it was never going to carry.
                self._spec_fallback_reason = None
                self._spec_drafter_kind = None
                # Discovery runs before the metadata read that says diffusion, so a
                # transient sidecar failure can set this for a drafterless server.
                self._dflash_retry_needed = False
                # Same reason: this path returns before the launch block, and the
                # diffusion runner ignores the budget, so a previous llama-server's
                # fraction would relaunch a healthy diffusion server on every Apply.
                self._vram_fraction_launched = None
                with self._lock:
                    if _load_cancelled():
                        logger.info("Load cancelled before diffusion server start")
                        return False
                    return self._start_diffusion_server(
                        model_path = model_path,
                        gguf_path = gguf_path,
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        model_identifier = model_identifier,
                        n_ctx = n_ctx,
                        extra_args = extra_args,
                        gpu_ids = gpu_ids,
                        gpu_memory_mode = gpu_memory_mode,
                        gpu_layers = gpu_layers,
                    )

            if not binary:
                # distinguish a transiently locked binary (antivirus / in-flight
                # install) from a missing one so the user retries, not reinstalls
                locked = self._find_llama_server_binary(include_denied = True)
                if locked:
                    raise RuntimeError(
                        f"llama-server at {locked} is temporarily unavailable "
                        "(access-denied; antivirus or an in-flight install). "
                        "Retry the load once it is released."
                    )
                # Reached only after the diffusion early-return above, so this is a
                # genuine llama-server-backed GGUF with no runtime. Raise the typed
                # error so /load returns the actionable 400 (not a generic 500), the
                # same message remote validation already shows.
                raise LlamaServerNotFoundError(LLAMA_SERVER_NOT_FOUND_DETAIL)

            server_caps = _launch_caps(binary)

            # Outside ``self._lock`` so /unload, /cancel, /status aren't
            # blocked. ``unload_model`` also records the kill, so the
            # frontend /unload+/load Apply path engages the wait here even
            # without an in-process kill.
            self._wait_for_vram_settle(since_kill = self._last_kill_monotonic)

            # ── Phase 3: start llama-server (under lock) ──────────────
            with self._lock:
                # Re-check cancel inside lock
                if _load_cancelled():
                    logger.info("Load cancelled before server start")
                    return False

                self._port = self._find_free_port()

                # Select GPU(s) from model size + estimated KV cache. Seed
                # safe defaults before probing so the except path has valid
                # state to publish.
                ctx_override = parse_ctx_override(extra_args)
                requested_ctx = resolve_requested_ctx(extra_args, n_ctx)
                swa_full = _swa_full_from_args_or_env(extra_args)

                # The emitted batch, not the requested one: the floor raise below is what
                # llama.cpp caps the micro-batch against, so the fit, the slot search and
                # every compute-buffer reserve must be sized from the value that launches.
                # Slot-dependent, since the floor is max(slots, 2): the slot search below
                # reduces the count, and each candidate launches at its own batch.
                def _ubatch_for_slots(slots: int) -> Optional[int]:
                    return _extra_args_n_ubatch(
                        extra_args,
                        n_ctx = (requested_ctx if requested_ctx > 0 else self._context_length),
                        n_batch = _emitted_n_batch(n_batch, slots),
                        n_ubatch = n_ubatch,
                    )

                _effective_ubatch = _ubatch_for_slots(n_parallel)
                # What the SWA checkpoint reserve is priced against. Extras beat the
                # field, as at launch: the control emits its flag before them, so a
                # typed --ctx-checkpoints is what the child allocates. Only an
                # explicit request counts at all: the estimator has always charged 0,
                # and adopting llama.cpp's default of 32 would move the fit for every
                # model. Gated on the capability the argv builder emits the flag on:
                # a build with neither alias allocates nothing, so pricing it costs
                # slots and context for bytes no child holds.
                _effective_ctx_checkpoints = (
                    resolve_ctx_checkpoints(extra_args, ctx_checkpoints)
                    if server_caps.get("ctx_checkpoints_flag")
                    else 0
                )
                # --embedding forces n_batch = n_ubatch, which aborts a load below the slots.
                if (
                    self.is_embedding_gguf
                    and _effective_ubatch is not None
                    and _effective_ubatch < n_parallel
                ):
                    # max(): a degenerate "-b 0" extra resolves to 0, and --parallel 0 is
                    # rejected at arg parse.
                    _embedding_slots = max(1, _effective_ubatch)
                    logger.warning(
                        "Reducing serving slots from %d to %d: llama-server caps the batch "
                        "at the %d-token micro-batch under --embedding and aborts when that "
                        "is below the slot count.",
                        n_parallel,
                        _embedding_slots,
                        _effective_ubatch,
                    )
                    n_parallel = _embedding_slots  # allow-slot-clamp: llama-server would abort
                    _effective_ubatch = _ubatch_for_slots(n_parallel)
                planned_kv_unified = _kv_unified_from_args(
                    extra_args,
                    default = n_parallel > 1 and server_caps.get("supports_kv_unified", False),
                )
                _pipeline_parallel_off = _pipeline_parallel_disabled_by_args(
                    extra_args, n_layers = self._n_layers
                )
                # A hard-crash recovery may relaunch this same plan with FA off.
                # Size that larger cache up front so the recovery cannot OOM.
                planned_flash_attn = False
                cache_override = parse_cache_override(extra_args)
                # Budget the heavier of asymmetric --cache-type-k/-v extras (they
                # win per axis at launch, appended last); resolve_cache_type_kv only
                # returns the last-wins type, which under-reserves the heavier axis.
                # The user's extras still set the real (possibly asymmetric) child
                # cache, so this only affects the reserve, not the emitted command.
                _extras_cache = _extra_args_main_cache_type_for_budget(extra_args)
                cache_type_kv = _extras_cache if _extras_cache is not None else cache_type_kv
                _cache_type_from_env = False
                # An unknown type is never emitted (see _VALID_CACHE_TYPES below), so the
                # child falls through to whatever LLAMA_ARG_CACHE_TYPE_K/_V it inherits.
                # Budgeting the unemittable string would price it at _kv_bytes_per_elem's
                # 2.0 unknown default while the child allocates the inherited type: a 2x
                # under-reservation against an inherited f32, in the mode with no --fit
                # valve. Treat it as unset so the env adoption below sees it.
                if cache_type_kv is not None and (
                    cache_type_kv.strip().lower() not in _VALID_CACHE_TYPES
                ):
                    cache_type_kv = None
                if cache_type_kv is None:
                    # Param/extras set nothing, so the child inherits
                    # LLAMA_ARG_CACHE_TYPE_K/_V. Adopt an env type that budgets
                    # differently from f16 (f32, quantized) for the reserve only;
                    # the launch does NOT re-emit it (that would rewrite an
                    # asymmetric K=f32,V=f16 env into symmetric flags), so
                    # _cache_type_from_env keeps it out of the emitted flags.
                    cache_type_kv = _env_main_cache_type_for_budget()
                    _cache_type_from_env = cache_type_kv is not None
                # The heavier axis above budgets KV BYTES; the dequant scratch keys off
                # the LIGHTER axis instead. Since ggml-org/llama.cpp#23792 an asymmetric
                # -ctk q4_0 -ctv f16 reaches the child, where the heavier scalar (f16)
                # would price the scratch as if nothing were quantized. Same precedence.
                _scratch_cache_type_kv = _planned_scratch_cache_type(
                    None if _cache_type_from_env else cache_type_kv,
                    extra_args,
                )
                # The (K, V) pair this launch will run, for the tensor-abort latch:
                # since #23792 the type reaches the child, so an abort can be specific
                # to it and the latch must not generalise across types.
                _planned_cache_pair = _planned_main_cache_types(
                    None if _cache_type_from_env else cache_type_kv,
                    extra_args,
                )
                # A user --split-mode in extras last-wins-overrides the toggle, and
                # an inherited tensor LLAMA_ARG_SPLIT_MODE flips it on (the child
                # would run tensor unbudgeted otherwise). The duplicate-load matchers
                # use the same helper so a healthy env-driven tensor server matches.
                split_mode_override = parse_split_mode_override(extra_args)
                tensor_parallel = _effective_tensor_parallel(extra_args, tensor_parallel)
                # gpu_layers=0 leaves nothing to split, yet --split-mode tensor or
                # a per-GPU ratio still launches tensor mode -- and under the
                # CPU-only mask below (no visible devices) that aborts the server
                # instead of loading on CPU. Drop both here (nothing to split).
                if gpu_memory_mode == "manual" and gpu_layers == 0:
                    if tensor_parallel or tensor_split:
                        logger.info(
                            "Manual gpu_layers=0: dropping tensor split/parallel "
                            "flags (nothing to split on the GPU)"
                        )
                    tensor_parallel = False
                    tensor_split = None
                # Record the requested strategy for /status and the load
                # response. 'manual' has no fallback, so the request value is the
                # value actually applied.
                self._gpu_memory_mode = gpu_memory_mode
                # The layer/MoE/split knobs apply only with an explicit offload
                # (manual + gpu_layers >= 0); else record defaults so /status and
                # /load don't report knobs the server never applied. Reset before the
                # branch so an earlier launch's recorded drop cannot excuse this one.
                self._arch_gate_dropped_tensor_split = None
                self._arch_gate_dropped_tensor_parallel = False
                if gpu_memory_mode == "manual" and gpu_layers >= 0:
                    self._gpu_layers = gpu_layers
                    self._n_cpu_moe = n_cpu_moe
                    self._tensor_split = tensor_split
                else:
                    self._gpu_layers = -1
                    self._n_cpu_moe = 0
                    self._tensor_split = None
                self._requested_gpu_ids = sorted(gpu_ids) if gpu_ids else None
                self._gpu_ids = list(self._requested_gpu_ids) if self._requested_gpu_ids else None
                # Manual offload skips the TP planner but still emits --split-mode
                # tensor at launch; drop it when fewer than 2 GPUs are in use --
                # tensor split is a no-op there and aborts on some architectures.
                if (
                    tensor_parallel
                    and gpu_memory_mode == "manual"
                    and gpu_layers >= 0
                    and self._effective_gpu_count(sorted(gpu_ids) if gpu_ids else None) < 2
                ):
                    logger.info(
                        "Tensor parallelism requested in manual mode but fewer "
                        "than 2 GPUs are in use; ignoring (needs >= 2)."
                    )
                    tensor_parallel = False
                if tensor_parallel and gpu_memory_mode == "manual" and gpu_layers < 0:
                    logger.info(
                        "Manual mode with Auto layers hands memory management to "
                        "llama.cpp --fit, which is incompatible with tensor "
                        "parallelism; ignoring the tensor split."
                    )
                    tensor_parallel = False
                if ctx_override is not None and ctx_override > 0:
                    logger.info(f"User --ctx-size {ctx_override} honored; skipping auto-reduce")
                if cache_override is not None:
                    _ck, _cv = parse_cache_override_per_axis(extra_args)
                    logger.info(
                        f"User --cache-type-k/-v (k={_ck}, v={_cv}) honored; "
                        "KV estimate budgets the heavier axis"
                    )
                if split_mode_override is not None:
                    logger.info(
                        f"User --split-mode {split_mode_override} honored; "
                        "reconciled into tensor_parallel state"
                    )
                effective_ctx = requested_ctx if requested_ctx > 0 else (self._context_length or 0)
                max_available_ctx = self._context_length or effective_ctx
                gpus: list[tuple[int, int]] = []
                # Keep fit-budget and launch-flag mmproj resolution in sync.
                launch_mmproj_path = None
                # Set only where the SWITCH is what dropped a usable image projector.
                # A None launch path does not mean that on its own: the resolve also
                # returns None for a missing file or a family mismatch, and reporting
                # the switch there tells the user to turn Vision back on when the same
                # projector will just be rejected again.
                _dv_dropped_image_projector = False
                if not extra_args_disable_mmproj(extra_args):
                    launch_mmproj_path = self._resolve_launch_mmproj_path(
                        model_path = model_path,
                        mmproj_path = mmproj_path,
                    )
                    # The switch turns VISION off, and a projector is not always a
                    # vision tower: ultravox, Voxtral and Qwen3-ASR declare an audio
                    # encoder and no vision at all, so suppressing one takes the
                    # model's audio input away and gives no image VRAM back. Nothing
                    # there for the switch to turn off, so keep it. Resolution is a
                    # disk and family check with no download, so asking first is free.
                    if disable_vision and launch_mmproj_path:
                        _dv_has_audio, _dv_accepts_image = False, True
                        try:
                            from utils.models.gguf_metadata import mmproj_capabilities
                            _dv_has_audio, _dv_accepts_image = mmproj_capabilities(
                                launch_mmproj_path
                            )
                        except Exception as e:
                            # Unknown reads image-capable upstream, so honor the switch
                            # rather than quietly keep a projector the user turned off.
                            logger.debug(f"mmproj capability read failed: {e}")
                        if _dv_accepts_image:
                            if _dv_has_audio:
                                # One projector serves both modalities (Qwen2.5-Omni)
                                # and llama.cpp cannot load half of it, so audio input
                                # goes with vision. Say so: the switch only named images.
                                logger.warning(
                                    "Vision is off for this load, so this model's audio "
                                    "input goes too: its projector serves both and "
                                    "llama.cpp cannot load one modality without the "
                                    "other. Turn Vision back on to send audio."
                                )
                            launch_mmproj_path = None
                            _dv_dropped_image_projector = True
                        else:
                            logger.info(
                                "Vision is off for this load, but this model's projector "
                                "is audio-only (no vision tower), so it stays loaded: "
                                "dropping it would remove audio input and free no image "
                                "VRAM."
                            )
                # A virtualised Metal device corrupts the vision encoder too, and
                # --no-mmproj-offload is the only way to keep it off there (clip.cpp
                # never reads --gpu-layers). Without that flag the choice is a projector
                # on the corrupt device or no projector, so drop it: silently encoding
                # every image from garbage is the failure this fallback exists to stop.
                # Only when the probe answered: --no-mmproj-offload is from b5178 and
                # the base argv already needs b6325, so a build that can start here
                # always has it, and a false capability means the --help probe failed
                # (see _paravirtual_probe_answered). Dropping vision on that would be a
                # self-inflicted outage; the pin below covers the unanswered case.
                _pv_mmproj_unpinnable = bool(
                    launch_mmproj_path
                    and _paravirtual_cpu_forced
                    and _paravirtual_probe_answered(server_caps)
                    and not server_caps.get("supports_no_mmproj_offload")
                )
                if _pv_mmproj_unpinnable:
                    logger.warning(
                        "Disabling image/audio input for this session: this Mac's "
                        "Metal device is virtualised and this llama-server build has "
                        "no --no-mmproj-offload, so the vision projector would keep "
                        "running on the device whose output is corrupt. Run 'unsloth "
                        "studio update' to install a build that supports it."
                    )
                    launch_mmproj_path = None
                # Need both a resolved mmproj AND the config vision flag; a stray
                # mmproj passing the family-name heuristic must not flip a non-VLM
                # GGUF into vision mode.
                effective_is_vision = bool(launch_mmproj_path) and bool(is_vision)
                if is_vision and not effective_is_vision and not _pv_mmproj_unpinnable:
                    logger.warning(
                        "Vision-capable GGUF loaded without a usable mmproj; "
                        "image input will be disabled for this session"
                    )
                # Seed before the try: the except (GPU-selection failure ->
                # --fit on) falls through to the launch which reads this, and the
                # probe that assigns it may throw first. Captured before manual
                # empty `gpus` so the speculative defaults stay GPU-aware and the
                # CPU-fallback check still knows GPUs were present.
                _detected_gpus: list[tuple[int, int]] = []
                _shared_gpu_ids: set[int] = set()
                # Set when the arch gate emptied a non-empty GPU pool, so the env
                # block below masks the child onto the CPU. Bound before the try for
                # the same reason as _detected_gpus: the except path (--fit on) falls
                # through to the launch, which reads it.
                _arch_gate_forced_cpu = False
                # The GPUs THIS launch pinned the child to, or None when it pinned
                # nothing. Set where the pin is emitted, and read by the pageable
                # override so it prices against VRAM the child can actually spend.
                # Not derived from env: an inherited mask is already applied by the
                # probe, so re-reading it there would subtract the same pin twice.
                _launch_pinned_ids: Optional[list] = None
                # The pageable rewrite a CPU replay applied, kept across attempts: the
                # env is shared, so only the first replay to need it produces a note.
                _replay_pageable_override: Optional[str] = None
                # Set by the restored cpu_fallback path, consumed once the launch is
                # healthy: str carries that replay's override note, True means none.
                _restored_cpu_reprice: Union[str, bool, None] = None
                # Whether Unsloth's placement planner actually RAN and came back
                # unable to fit the model. `use_fit` alone cannot answer that: it
                # starts True at its declaration below and is also what the except
                # path restores, so an unfitted `--fit on` is indistinguishable
                # from the default unless the verdict is recorded on its own.
                # Bound before the try for the same reason as _detected_gpus.
                _placement_verdict_partial = False
                # Sized inputs for the tensor-spill planner, None when the fit never
                # priced them. Bound before the try like _placement_verdict_partial:
                # the except arm restores use_fit=True without rebinding
                # kv_cache_bytes, so reading it from the spill arm would be an
                # UnboundLocalError on the path that reaches it most often.
                _spill_inputs: Optional[dict] = None
                total_by_idx: dict[int, int] = {}
                model_size = None  # set in the fit try; used by the APU RAM guard
                # "none" once the fit proves the load needs no demand paging, else None
                # for llama.cpp's own default. Bound before the try like the verdict
                # flags above: the except path falls through to the launch, which reads it.
                _fit_load_mode: Optional[str] = None
                # Layer-fallback min GPUs; raised below on a tensor downgrade. Bound
                # before the try so the --fit-on except path still has it (no UnboundLocal).
                _layer_min_gpus = 1
                # An explicit Vulkan ordinal absent from the ggml probe cannot be
                # honored; flag it in the fit and reject after the try (raising inside
                # would be swallowed into the --fit-on fallback). Bound before the try.
                _vulkan_explicit_unmatched = False
                _vulkan_requested_ids: list[int] = []
                _vulkan_available_ordinals: list[int] = []
                # Auto dropped the drafter because only the target fit. Bound before the
                # try: the launch below reads it either way.
                _spec_dropped_no_vram = False
                # The projector runs on the CPU and so allocates no VRAM:
                # --no-mmproj-offload clears mmproj_use_gpu and clip.cpp gates its whole
                # GPU backend on that, leaving no partial offload. Only the paravirtual
                # reason is known this early; the fit below may add the automatic one.
                # Bound before the try, like _spec_dropped_no_vram.
                _mmproj_cpu_pinned = bool(
                    launch_mmproj_path
                    and _paravirtual_cpu_forced
                    and _paravirtual_mmproj_pinnable(server_caps)
                )
                # What the pin took out of model_size, for the one consumer that must
                # have it back: _apu_ram_shortfall_message prices SYSTEM RAM, and a
                # CPU-pinned projector is still in system RAM.
                _mmproj_pinned_bytes = 0
                # Metal unified-memory refusal for a hand-set context, raised AFTER this
                # block: the `except Exception` below would swallow the raise into the
                # placement fallback and restore the original request, which is the very
                # over-commit being refused. Carrying the message out survives that arm,
                # and the ceiling it names was measured before the throw. (Worded around
                # the handler's own log line on purpose: test_tp_vision_regression
                # string-searches this function's source for it to check ordering.)
                _metal_ctx_refusal: Optional[str] = None
                try:
                    gguf_size = self._get_gguf_size_bytes(model_path)
                    # Include GPU-loaded mmproj in the fit budget (#5825). GPU-loaded is
                    # the operative word: --no-mmproj-offload already put the projector in
                    # host RAM, so its bytes are not on the card. Charging them anyway
                    # shrinks the context (measured 9984 -> 4096) or spills layers to make
                    # room for VRAM nothing occupies. The RESOLVED value decides, not just
                    # ownership: arg.cpp reads the env before argv, so the environment
                    # places the projector just as surely as the flag.
                    _user_mmproj_offload = _resolved_mmproj_offload(extra_args)
                    mmproj_size = (
                        self._mmproj_vram_bytes(launch_mmproj_path)
                        if (effective_is_vision and _user_mmproj_offload is not False)
                        else 0
                    )
                    if _user_mmproj_offload is False and launch_mmproj_path:
                        # Still in system RAM, which the APU shortfall guard prices.
                        _mmproj_pinned_bytes = self._mmproj_vram_bytes(launch_mmproj_path)
                    model_size = gguf_size + mmproj_size
                    # 2-tuple gpus for existing logic + a total map for the absolute
                    # per-GPU headroom (correct when the GPU is already partly used).
                    # Pass binary so a Vulkan build probes ggml's Vulkan ordinals.
                    # AUTOMATIC placement only. Gating an explicit pin would leave
                    # `gpus` empty, skipping the fit and layer plan and forcing
                    # `--fit on`, yet `gpu_indices` is restored from `gpu_ids` below
                    # so the pin happens anyway. A pinned uncovered GPU is the user's
                    # call and already reports "device kernel image is invalid".
                    _gpu_mem = self._get_gpu_memory(binary, for_llama_server = not gpu_ids)
                    # Every present device gated out (#7624). Left alone the launch
                    # takes the `--fit on` arm with `gpu_indices` still None, so no
                    # mask is written, the child enumerates every unsupported card and
                    # dies, and the reactive retry cannot help (its guard needs a
                    # truthy `gpu_indices`). CPU is the only placement that runs here.
                    # ROCm auto only; the guard spares CUDA and CPU-only hosts, where
                    # an empty probe just means "no GPU".
                    if (
                        not gpu_ids
                        and not _gpu_mem
                        and not is_vulkan_backend
                        and self._host_torch_is_rocm()
                    ):
                        _ungated = self._get_gpu_memory(binary)
                        # Re-derive the verdict rather than infer it from the empty
                        # result: _get_gpu_memory turns any probe error into [], so
                        # "gated empty, ungated not" also describes a one-shot failure
                        # of the FIRST probe on a host the gate never filters, and
                        # masking that onto CPU is a silent, permanent cliff. Unknown
                        # coverage or an unreadable arch keeps every device.
                        _coverage = self._installed_llama_gfx_archs(binary)
                        _arch_by_id = self._rocm_arch_by_physical_id() if _ungated else {}
                        _all_uncovered = (
                            bool(_ungated)
                            and _coverage is not None
                            and all(
                                (_arch_by_id.get(idx) or "") not in ("", *_coverage)
                                for idx, _free, _total in _ungated
                            )
                        )
                        if _all_uncovered:
                            _arch_gate_forced_cpu = True
                            _present = ", ".join(
                                f"{idx} ({_arch_by_id.get(idx) or 'unknown arch'})"
                                for idx, _free, _total in _ungated
                            )
                            logger.warning(
                                "The installed llama.cpp build has no kernels for "
                                "any GPU on this host (%s), so inference falls back "
                                "to CPU. Reinstall llama.cpp for these devices to "
                                "get GPU inference back.",
                                _present,
                            )
                    if is_vulkan_backend and not gpu_ids and gpu_memory_mode != "manual":
                        _gpu_mem = self._vulkan_auto_gpu_memory(_gpu_mem)
                    gpus = [(idx, free) for idx, free, _t in _gpu_mem]
                    # Restrict the fit (and thus the layer plan + pin env) to the
                    # selected GPUs; fail-open if none match so a stale UI choice
                    # can't strand the load on CPU (issue #7164).
                    if gpu_ids:
                        # A Vulkan build indexes by ggml ordinal. An explicit ordinal
                        # absent from the probe can't be pinned, so reject after the try
                        # rather than fail-open onto a device the user didn't pick.
                        _wanted_ids = {int(x) for x in gpu_ids}
                        # Reject if ANY requested ordinal is absent, not only when none
                        # match: [0, 99] against {0, 1} silently drops 99. Comparing the
                        # full requested set (before filter narrows) still lets the fitter
                        # pick a valid subset later -- that is narrowing, not absence.
                        _probed_ordinals = {g[0] for g in gpus}
                        if is_vulkan_backend and not _wanted_ids.issubset(_probed_ordinals):
                            _vulkan_explicit_unmatched = True
                            _vulkan_requested_ids = sorted(_wanted_ids)
                            _vulkan_available_ordinals = sorted(_probed_ordinals)
                        # Restrict the probed pool to the selection; fail-open (keep the
                        # full pool) if none match so a stale UI choice can't strand the
                        # load on CPU (issue #7164).
                        _sel_gpus = [g for g in gpus if g[0] in _wanted_ids]
                        gpus = _sel_gpus if _sel_gpus else gpus
                    total_by_idx = {idx: total for idx, _f, total in _gpu_mem}
                    # GPU picker: restrict every mode to the chosen devices, so
                    # auto selection only considers them and manual mask to
                    # them (the env block below pins CUDA/HIP_VISIBLE_DEVICES).
                    if gpu_ids:
                        _picked = set(gpu_ids)
                        gpus = [g for g in gpus if g[0] in _picked]

                    # GPUs the model will run on -- captured before manual
                    # empty `gpus` to bypass the planner. bool() drives the
                    # GPU-aware speculative defaults; the list feeds the
                    # CPU-fallback check.
                    _detected_gpus = list(gpus)
                    # Vulkan reports total 0 only for integrated GPUs. Their
                    # free "VRAM" is the same host pool the RAM guard prices.
                    _shared_gpu_ids = (
                        {idx for idx, _free in _detected_gpus if total_by_idx.get(idx, 1) <= 0}
                        if is_vulkan_backend
                        else set()
                    )
                    # The --fit fallback is llama.cpp's own fitter, which knows nothing
                    # about this budget: it keeps its own margin and packs the rest on,
                    # so the slider never reached the path that runs when the fit is
                    # tightest. Hand it the difference, both directions, measured from
                    # the default so an untouched slider leaves the command alone.
                    # One broadcast value: --fit-target does take a per-device list, but
                    # in llama.cpp's enumeration order, which the visible-device pin and
                    # the ROCr/Vulkan ordinal quirks make not ours to assume, and a
                    # misaligned list hands a card the wrong margin. So the direction
                    # picks the card: lowering scales by the largest, so no device ends
                    # up under the margin it asked for, raising by the smallest, so none
                    # is taken below its own. Mixed cards gain a little less, and hold
                    # back a little more, than a per-device list would.
                    if _vram_frac != _CTX_FIT_VRAM_FRACTION and gpus:
                        # Free stands in for an unreported total, the same scale
                        # _vram_usable_mib falls back to: MIG/vGPU and the two-column
                        # probe report no total, and deriving the whole adjustment
                        # from a zero would silently drop the budget on exactly the
                        # devices whose headroom is hardest to see.
                        _scales = [total_by_idx.get(_idx) or _free for _idx, _free in gpus]
                        _scale = (
                            max(_scales) if _vram_frac < _CTX_FIT_VRAM_FRACTION else min(_scales)
                        )
                        _fit_target_delta_mib = (_CTX_FIT_VRAM_FRACTION - _vram_frac) * _scale

                    def _gpu_usable(g, frac = _vram_frac):
                        # Callers pass the ACTIVE fraction so the ranking matches the
                        # budget the fit then tests, else mixed totals mis-order.
                        idx, free = g
                        return _vram_usable_mib(free, total_by_idx.get(idx, 0), frac)

                    def _pool_budget_mib(subset, frac):
                        # Sum each GPU's own usable budget. Pooling free and total
                        # separately would let an unknown-total GPU (MIG/vGPU/N/A)
                        # add full free with no cushion among known-total GPUs.
                        return sum(max(0.0, _gpu_usable(g, frac)) for g in subset)

                    # Resolve effective context: 0 means let llama-server use
                    # the model's native length. Only expand to a known native
                    # length if metadata exists; else keep 0 as a sentinel.
                    if requested_ctx > 0:
                        effective_ctx = requested_ctx
                    elif self._context_length is not None:
                        effective_ctx = self._context_length
                    else:
                        effective_ctx = 0
                    original_ctx = effective_ctx
                    # Default UI ceiling to the native context length;
                    # GPU/VRAM-fit logic below may shrink it on limited HW.
                    max_available_ctx = self._context_length or effective_ctx

                    # Manual + Auto layers (the Manual default): hand memory
                    # management to llama.cpp's --fit. Emptying the probed GPU set
                    # no-ops the selection/TP planning below, leaving gpu_indices
                    # None (an explicit gpu_ids pick still pins below) and use_fit
                    # True. An explicit context is honored (--fit optimizes around
                    # it); 0 lets --fit size it.
                    if gpu_memory_mode == "manual" and gpu_layers < 0:
                        gpus = []
                        effective_ctx = requested_ctx if requested_ctx > 0 else 0
                        original_ctx = effective_ctx
                        # --fit aborts under --split-mode tensor; a raw extras
                        # --split-mode/--tensor-split (appended last) would
                        # otherwise reach llama-server. Strip it like the TP
                        # downgrade does.
                        extra_args = strip_split_mode_only(extra_args)
                    elif gpu_memory_mode == "manual":
                        # Manual offload (--gpu-layers + --fit off): no automatic
                        # device masking (a gpu_ids pick still pins below) or
                        # context cap -- the user owns both. tensor_parallel is
                        # honored but skips the memory-based planner (gpus = []);
                        # the toggle just emits --split-mode tensor (split by free
                        # VRAM, or by the Split ratio if set).
                        gpus = []
                        effective_ctx = (
                            requested_ctx if requested_ctx > 0 else (self._context_length or 0)
                        )
                        original_ctx = effective_ctx
                        # Strip the user --split-mode when the toggle owns the split
                        # (TP engaged -> Unsloth emits --split-mode tensor) or when the
                        # user asked for tensor (which aborts on a single GPU even if
                        # the manual <2-GPU guard downgraded TP). Otherwise keep their
                        # non-tensor mode (row/none/layer) -- the toggle can't express
                        # those.
                        if tensor_parallel or split_mode_override == "tensor":
                            extra_args = strip_split_mode_only(extra_args)

                    # Will MTP engage? If so, auto-fit reserves draft-model VRAM.
                    # Mirrors _build_speculative_flags: forced mtp/mtp+ngram always
                    # engage; auto only on an MTP model >= 3B; ngram/off never. A
                    # separate drafter (Gemma) counts as an MTP model.
                    # _spec_canon, not the raw request: Auto has already resolved to
                    # dspark or dflash above when a sidecar is available, and the
                    # reserve below differs by kind (no duplicated target-KV copy,
                    # and DSpark uses depth 3).
                    _mtp_effective = _spec_canon
                    _mtp_size_for_fit = _extract_model_size_b(model_identifier)
                    # Sub-3B drops MTP only for an embedded head; a separate
                    # drafter (Gemma) engages and needs its VRAM reserved.
                    _mtp_sub_3b_for_fit = (
                        _mtp_size_for_fit is not None
                        and _mtp_size_for_fit < _MTP_MIN_SIZE_B
                        and not bool(mtp_draft_path)
                    )
                    # The inherited spec env reaches the child only when the extras own
                    # --spec-type; the launch scrubs it otherwise. Reserve against the
                    # env in that case only, where flags and env accumulate and launch.
                    _spec_env: Mapping[str, str] = _child_spec_env(extra_args)
                    # Extras can run MTP even when Unsloth suppresses its own emission.
                    _user_mtp_via_extras = _extra_args_requests_mtp(extra_args, env = _spec_env)
                    # A non-MTP model-based draft mode (draft-simple/draft-eagle3) in
                    # extras also loads a separate draft model that needs reserving;
                    # engage only when extras actually name a drafter for it.
                    _user_draft_via_extras = _extra_args_requests_separate_draft(
                        extra_args, env = _spec_env
                    ) and bool(_extra_args_mtp_draft_path(extra_args))
                    # Mirror _build_speculative_flags: reserve only for MTP the launch
                    # resolver will actually emit (needs a head/drafter and a binary
                    # that supports --spec-type mtp).
                    _mtp_model_for_fit = bool(
                        self._nextn_predict_layers
                        or _is_mtp_model_name(model_identifier, model_path)
                        or bool(mtp_draft_path)
                    ) and not (
                        # Drafterless Gemma falls back to ngram-mod; reserve no
                        # drafter VRAM for it (mirrors the launch resolver).
                        _is_gemma_mtp_name(model_identifier, model_path)
                        and not mtp_draft_path
                        and not self._nextn_predict_layers
                    )
                    _mtp_binary_ok = True
                    _mtp_probe_raised = False
                    if not _user_mtp_via_extras:
                        try:
                            _fit_caps = _launch_caps(binary) or {}
                            _sidecar_cap = {
                                "dspark": "supports_dspark",
                                "dflash": "supports_dflash",
                            }.get(_mtp_effective)
                            _mtp_binary_ok = bool(
                                _fit_caps.get(_sidecar_cap)
                                if _sidecar_cap
                                else _fit_caps.get("mtp_token")
                            )
                        except Exception:
                            _mtp_binary_ok = False
                            _mtp_probe_raised = True
                    _auto_studio_mtp = (
                        not _extra_args_set_spec_type(extra_args)
                        and _mtp_model_for_fit
                        and (
                            _mtp_effective in ("mtp", "mtp+ngram", "dspark", "dflash")
                            or (_mtp_effective == "auto" and not _mtp_sub_3b_for_fit)
                        )
                        and (
                            _mtp_binary_ok
                            # Reserve on a raised (uncached) probe too: it re-probes in
                            # _build_speculative_flags and may still engage MTP (embedded
                            # head or separate drafter -- _mtp_model_for_fit covers both).
                            or _mtp_probe_raised
                        )
                    )
                    _mtp_will_engage = bool(
                        _user_mtp_via_extras or _user_draft_via_extras or _auto_studio_mtp
                    )
                    # The duplicated full target-KV copy (ctx_tgt) is an MTP-only
                    # cost: the MTP head runs a second context over the target
                    # model's own KV geometry. Every separate-drafter mode loads a
                    # distinct drafter with its own KV and keeps no such copy, so
                    # only charge it when the engaged mode is truly MTP. Those modes
                    # arrive by two routes, hence the two conditions: draft-simple
                    # and draft-eagle3 via _user_draft_via_extras (already excluded,
                    # they never set _user_mtp_via_extras), and DSpark/DFlash via
                    # Unsloth's own resolution, which does set _auto_studio_mtp.
                    _engaged_is_mtp = bool(
                        _user_mtp_via_extras
                        or (_auto_studio_mtp and _mtp_effective not in ("dspark", "dflash"))
                    )
                    # The recurrent rollback copies are a WIDER set than that copy
                    # (_TARGET_ROLLBACK_SPEC_TYPES): DSpark and DFlash pay them too,
                    # and draft-simple is the one engaged draft mode that does not,
                    # which is why the pass-through arm reads the types rather than
                    # assuming every extras-owned drafter qualifies.
                    _target_rollback = bool(
                        _auto_studio_mtp
                        or _user_mtp_via_extras
                        or (
                            _user_draft_via_extras
                            and _accumulated_spec_types(extra_args, env = _spec_env)
                            & _TARGET_ROLLBACK_SPEC_TYPES
                        )
                    )

                    # Effective draft depth, by what the CHILD will run on rather than
                    # what was asked for: an extras depth wins (last-wins at launch),
                    # else the field, else the platform default (2 GPU / 3 CPU).
                    _extra_n_max = _extra_args_spec_draft_n_max(extra_args)
                    _mtp_eff_n_max = _extra_n_max
                    if _mtp_eff_n_max is None and _extra_args_set_spec_type(extra_args):
                        # The extras own the spec block, so _build_speculative_flags
                        # returns without emitting a depth at all: neither the request
                        # field nor the platform default below reaches the child. What
                        # does: the inherited env, which survives exactly this case,
                        # then the build's own default. The rollback reserve scales by
                        # this number, so carrying a request field of 2 into a build
                        # that drafts 16 under-reserves by a factor of eight.
                        try:
                            _depth_caps = _launch_caps(binary) or {}
                        except Exception:
                            _depth_caps = {}
                        # The env twin of whichever depth flag this build carries, and
                        # only that one: a legacy build spells the pair --draft-max /
                        # LLAMA_ARG_DRAFT_MAX, and a post-rename build ignores the
                        # legacy name, so a stale value there must not price its
                        # rollback. Both names only where the probe named no flag.
                        _depth_flag = _depth_caps.get("spec_draft_n_max_flag")
                        if _depth_flag == "--draft-max":
                            _env_names = ("LLAMA_ARG_DRAFT_MAX",)
                        elif _depth_flag:
                            _env_names = ("LLAMA_ARG_SPEC_DRAFT_N_MAX",)
                        else:
                            _env_names = ("LLAMA_ARG_SPEC_DRAFT_N_MAX", "LLAMA_ARG_DRAFT_MAX")
                        _env_n_max = next(
                            (v for v in map(_spec_env.get, _env_names) if _is_positive_int(v)),
                            None,
                        )
                        if _env_n_max is not None:
                            _mtp_eff_n_max = int(str(_env_n_max).strip())
                        else:
                            # Never fall through to Unsloth's platform default here:
                            # the child is drafting at the build's number, and a
                            # probe that timed out or printed no default still leaves
                            # it drafting. Assume the deepest llama.cpp has shipped.
                            _mtp_eff_n_max = (
                                _depth_caps.get("spec_draft_n_max_default")
                                or self._UNKNOWN_SPEC_DRAFT_N_MAX
                            )
                    elif _mtp_eff_n_max is None:
                        _mtp_eff_n_max = spec_draft_n_max
                    if _mtp_eff_n_max is None:
                        # _detected_gpus (not gpus) so manual -- which empty
                        # gpus to bypass the planner -- keep the GPU draft depth the
                        # launch flags also use, instead of the CPU default.
                        _mtp_eff_n_max = (
                            3 if _mtp_effective == "dspark" else (2 if _detected_gpus else 3)
                        )
                    # Separate-drafter weights live on GPU (an embedded head is
                    # already in model_size). Size the drafter the launch loads, by
                    # precedence: extras --model-draft (last-wins), else Unsloth's
                    # emitted mtp_draft_path, else the env drafter. Sizing the wrong
                    # one would under-reserve and OOM.
                    _cli_draft_for_budget = _extra_args_mtp_draft_path(extra_args, env = {})
                    _studio_draft_for_budget = (
                        mtp_draft_path
                        if (
                            _mtp_will_engage
                            and mtp_draft_path
                            and not _extra_args_set_spec_type(extra_args)
                        )
                        else None
                    )
                    # Same scrubbed view: reserving for an inherited drafter the child
                    # never loads shrinks the context or rejects a placement that fits.
                    _env_draft_for_budget = _extra_args_mtp_draft_path([], env = _spec_env)
                    _mtp_draft_for_budget = (
                        _cli_draft_for_budget or _studio_draft_for_budget or _env_draft_for_budget
                    )
                    # Will a SEPARATE drafter be emitted at all, taken before the CPU
                    # nulling below. Not mtp_draft_path: extras owning --spec-type return
                    # before Unsloth's sidecar becomes --model-draft, which
                    # _studio_draft_for_budget already encodes.
                    _separate_draft_launches = bool(_mtp_draft_for_budget)
                    # Drafter offloaded to CPU keeps its weights+KV off the GPU, so
                    # drop it from the budget (an embedded head stays in the model).
                    # Consult the env too: the child honors LLAMA_ARG_N_GPU_LAYERS_DRAFT.
                    _draft_on_cpu = _extra_args_draft_offloaded_to_cpu(extra_args, env = os.environ)
                    # Kept for the load-mode fit, which the nulling below would leave
                    # short a whole draft GGUF: dropping the drafter from the VRAM budget
                    # moves those bytes to host RAM rather than deleting them. See
                    # _cpu_resident_draft_bytes.
                    _cpu_draft_path = _mtp_draft_for_budget if _draft_on_cpu else None
                    if _draft_on_cpu:
                        _mtp_draft_for_budget = None
                    _mtp_draft_weights = 0
                    if _mtp_draft_for_budget:
                        try:
                            _mtp_draft_weights = self._get_gguf_size_bytes(_mtp_draft_for_budget)
                        except Exception:
                            _mtp_draft_weights = 0
                    # Draft K/V types (f16 by default; independent extras overrides).
                    _mtp_draft_ck, _mtp_draft_cv = _extra_args_draft_cache_types(extra_args)
                    # The control underneath them: emitted before the extras, so an
                    # extra still last-wins and the reserve prices what will run.
                    _budget_draft_cache = (
                        spec_draft_cache_type.strip().lower() if spec_draft_cache_type else None
                    )
                    if _budget_draft_cache in _VALID_KV_CACHE_TYPES:
                        _mtp_draft_ck = _mtp_draft_ck or _budget_draft_cache
                        _mtp_draft_cv = _mtp_draft_cv or _budget_draft_cache

                    # Byte-accurate reserve when dims allow, else None -> flat fallback.
                    mtp_overhead_fn: Optional[Callable[[int], int]] = None
                    # True when the byte reserve is the drafter weights ONLY because
                    # its KV couldn't be sized; the flat fraction must then stay on
                    # as the cushion for that unsized draft KV (it is not covered by
                    # the weights-only mtp_overhead_fn).
                    _mtp_kv_unsized = False
                    if _mtp_will_engage:
                        _probe_ctx = self._context_length or (
                            effective_ctx if effective_ctx > 0 else 4096
                        )
                        _draft_kv_probe = self._mtp_draft_kv_bytes(
                            _probe_ctx,
                            drafter_path = _mtp_draft_for_budget,
                            draft_cache_type_k = _mtp_draft_ck,
                            draft_cache_type_v = _mtp_draft_cv,
                            n_parallel = n_parallel,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            flash_attn = planned_flash_attn,
                        )
                        if (
                            self._estimate_mtp_overhead_bytes(
                                _probe_ctx,
                                spec_draft_n_max = _mtp_eff_n_max,
                                draft_cache_type_k = _mtp_draft_ck,
                                draft_cache_type_v = _mtp_draft_cv,
                                drafter_path = _mtp_draft_for_budget,
                                draft_weights_bytes = _mtp_draft_weights,
                                n_parallel = n_parallel,
                                mtp_keeps_target_ctx = _engaged_is_mtp,
                                target_rollback = _target_rollback,
                                swa_full = swa_full,
                                kv_unified = planned_kv_unified,
                                n_ubatch = _effective_ubatch,
                                flash_attn = planned_flash_attn,
                            )
                            is not None
                        ):
                            # Reserve is weights-only when the draft KV is unsizable.
                            _mtp_kv_unsized = _draft_kv_probe is None

                            # Closure binding this load's draft params; ctx varies.
                            def mtp_overhead_fn(
                                ctx: int,
                                _n: int = _mtp_eff_n_max,
                                _ck: Optional[str] = _mtp_draft_ck,
                                _cv: Optional[str] = _mtp_draft_cv,
                                _dp: Optional[str] = _mtp_draft_for_budget,
                                _w: int = _mtp_draft_weights,
                                _np: int = n_parallel,
                                _mtp: bool = _engaged_is_mtp,
                                _rollback: bool = _target_rollback,
                                _swa_full: bool = swa_full,
                                _kv_unified: bool = planned_kv_unified,
                                _n_ubatch: Optional[int] = _effective_ubatch,
                                _flash_attn: bool = planned_flash_attn,
                            ) -> int:
                                v = self._estimate_mtp_overhead_bytes(
                                    ctx,
                                    spec_draft_n_max = _n,
                                    draft_cache_type_k = _ck,
                                    draft_cache_type_v = _cv,
                                    drafter_path = _dp,
                                    draft_weights_bytes = _w,
                                    n_parallel = _np,
                                    mtp_keeps_target_ctx = _mtp,
                                    target_rollback = _rollback,
                                    swa_full = _swa_full,
                                    kv_unified = _kv_unified,
                                    n_ubatch = _n_ubatch,
                                    flash_attn = _flash_attn,
                                )
                                return v if v is not None else 0

                    def _mtp_bytes(
                        ctx: int,
                        slots: Optional[int] = None,
                        ubatch: Optional[int] = None,
                    ) -> int:
                        # slots/ubatch override the closure's requested pair: the reserve
                        # scales with both for compact SWA and MLA+recurrent, so the slot
                        # fit re-prices it per candidate.
                        if mtp_overhead_fn is None:
                            return 0
                        if slots is None:
                            return mtp_overhead_fn(ctx)
                        return mtp_overhead_fn(
                            ctx, _np = slots, _n_ubatch = ubatch if ubatch else _effective_ubatch
                        )

                    def _kv_bytes(ctx: int, ctx_checkpoints: int = 0) -> int:
                        # Checkpoints default OFF: the placement paths price the SWA
                        # snapshots themselves, so charging them again here would shrink
                        # the context they just chose. The load-mode fit, which has no
                        # such term, passes the effective count in.
                        return self._estimate_kv_cache_bytes(
                            ctx,
                            cache_type_kv,
                            n_parallel = n_parallel,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            ctx_checkpoints = ctx_checkpoints,
                            flash_attn = planned_flash_attn,
                        )

                    def _cc_bytes(ctx: int, n_gpus: int = 1) -> int:
                        # Context-linear compute-buffer growth (flash-attn KQ mask +
                        # attention scratch); the flat _compute_buffer_pipeline folded
                        # into model_size_fit only covers ctx -> 0. Charged per
                        # candidate context so the fit can't over-pin and spill. The
                        # rate depends on the KV cache type (quantized adds a dequant
                        # scratch), so pass it through -- the LIGHTER axis, since any
                        # quantized axis allocates it and the heavier scalar hides a
                        # paired one. In a layer split this buffer is
                        # replicated on EVERY device (measured ~equal per GPU), so scale
                        # by the device count; a large model at high context otherwise
                        # under-reserves ~(n-1)x it (e.g. Qwen3.5-397B on 3 GPUs). The
                        # per-device rate also steps up once split, unless llama.cpp
                        # declines the pipeline parallelism that causes the step.
                        return max(1, n_gpus) * self._compute_buffer_ctx_bytes(
                            ctx,
                            _effective_ubatch,
                            _scratch_cache_type_kv,
                            layer_split = n_gpus > 1 and not _pipeline_parallel_off,
                        )

                    def _cc_split_extra(ctx: int) -> int:
                        # Per-device step from the single-device rate to the split one,
                        # for the paths that must select GPUs before they know the
                        # count. 0 when llama.cpp declines pipeline parallelism.
                        return max(0, _cc_bytes(ctx, 2) // 2 - _cc_bytes(ctx))

                    # Layer-split compute buffer (one lump; tensor mode reserves it
                    # per device in _plan_tensor_parallel). Context-independent, so
                    # fold it into the model footprint for the branches below. Falls
                    # back to the flat reserve when dims are missing (returns 0), a
                    # safe upper bound since the tensor buffer >= the layer one.
                    _compute_buffer_pipeline = self._estimate_compute_buffer_bytes(
                        n_ubatch = _effective_ubatch,
                        n_parallel = n_parallel,
                        per_device_tensor = False,
                    )
                    if _compute_buffer_pipeline <= 0:
                        _compute_buffer_pipeline = (
                            self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
                        )

                    # ...and the tensor-mode rate, reserved on EVERY selected device:
                    # the f32 output buffer and the comm staging are replicated rather
                    # than split, so the layer lump above is a fraction of what a tensor
                    # split allocates. Same flat fallback when the dims are missing.
                    _compute_buffer_tensor = self._estimate_compute_buffer_bytes(
                        n_ubatch = _effective_ubatch,
                        n_parallel = n_parallel,
                        per_device_tensor = True,
                    )
                    if _compute_buffer_tensor <= 0:
                        _compute_buffer_tensor = (
                            self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
                        )

                    # Layer split adds a fixed per-device overhead on every GPU. The
                    # folded buffer covers one device; reserve the extra devices'
                    # share so a k-GPU split can't pin a context that OOMs a device
                    # (k=1 adds nothing).
                    _pipeline_overhead_bytes = self._PIPELINE_PER_DEVICE_OVERHEAD_MIB * 1024 * 1024

                    # Auto-cap context to fit VRAM and select GPUs. Explicit n_ctx:
                    # honor it, cap only if it fits no combination. Auto (native):
                    # prefer fewer GPUs with reduced context (multi-GPU is slower).
                    gpu_indices, use_fit = None, True
                    # Per-GPU weight proportions for tensor mode (None lets
                    # llama.cpp split by free VRAM).
                    tp_tensor_split: Optional[list[int]] = None
                    # Whether the tensor-parallel branch below really planned this load.
                    # Not readable from tp_tensor_split, which stays None on a tensor
                    # split llama.cpp is left to size itself.
                    _tp_planned = False
                    explicit_ctx = requested_ctx > 0
                    # Nothing speculative on the GPU: the drafter that launches is the
                    # separate CPU-offloaded one, and a sidecar wins over an embedded head
                    # (llama.cpp loads the draft model on has_dft()). A head with no
                    # sidecar is still GPU-resident and still reserved.
                    _draft_cpu_no_embedded = _draft_on_cpu and (
                        _separate_draft_launches or not self._nextn_predict_layers
                    )

                    # The two tensor -> layer downgrades that need nothing the probe
                    # decides run BEFORE it: the probe is gated on `not tensor_parallel`
                    # and must answer for any load that ends up layer-split.

                    # The route fallback retry is tensor-off; keep it multi-GPU.
                    if preserve_multi_gpu_on_layer:
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))

                    if tensor_parallel and self._tensor_quant_kv_unsupported_binary(
                        binary, _planned_cache_pair
                    ):
                        # This build already refused a quantized KV cache under a tensor
                        # split; go straight to layer rather than reload the model to be
                        # told again. Keeps the quantized cache, which layer supports.
                        logger.info(
                            "Tensor parallelism skipped: this llama.cpp build cannot "
                            "use a quantized KV cache with --split-mode tensor "
                            "(needs b9455+); loading with a layer split."
                        )
                        tensor_parallel = False
                        # Like the split-axis skip below: a missing capability says
                        # nothing about capacity, so keep the multi-GPU request rather
                        # than let the layer planner settle on the first card it fits.
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        extra_args = strip_split_mode_only(extra_args)
                    if tensor_parallel and self._tensor_split_aborts(
                        binary, model_identifier, _planned_cache_pair
                    ):
                        # Aborted on tensor for this model this session (#6415); skip
                        # tensor upfront, layer split serves it.
                        logger.info(
                            "Tensor parallelism skipped: this llama.cpp build aborted "
                            "on --split-mode tensor for this model earlier this "
                            "session; using layer split across %d GPU(s).",
                            len(gpus),
                        )
                        tensor_parallel = False
                        # The abort says nothing about capacity, so keep multi-GPU.
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        # An extras --split-mode tensor would re-engage tensor mode.
                        extra_args = strip_split_mode_only(extra_args)

                    # Tensor mode replicates a compute buffer on every GPU, so drop
                    # GPUs below that reserve from the set up front (gpu_indices
                    # becomes the CUDA_VISIBLE_DEVICES mask, fully excluding them).
                    tp_gpus = gpus
                    # Manual mode owns the layer count and context, so it skips
                    # the memory-based planner; its toggle still emits
                    # --split-mode tensor below (split by free VRAM, or by the
                    # Split ratio if set). auto plans here.
                    plan_tp = tensor_parallel and gpu_memory_mode != "manual"
                    if plan_tp:
                        # Deterministic per-device compute buffer (replicated on
                        # every device in tensor mode); flat fallback when dims
                        # are unavailable. _plan_tensor_parallel uses the same.
                        _tp_reserve_bytes = self._estimate_compute_buffer_bytes(
                            n_ubatch = _effective_ubatch,
                            n_parallel = n_parallel,
                            per_device_tensor = True,
                        )
                        reserve_mib = (
                            _tp_reserve_bytes // (1024 * 1024)
                            if _tp_reserve_bytes > 0
                            else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB
                        )
                        # Admit by usable budget (free - (1-frac)*total), not raw
                        # free: a partly-used big card can clear the reserve on raw
                        # free yet have no budget left.
                        tp_gpus = [g for g in gpus if _gpu_usable(g) >= reserve_mib]

                    if plan_tp and len(tp_gpus) < 2:
                        # Tensor parallelism needs >= 2 usable GPUs. On a single
                        # GPU --split-mode tensor is a no-op; with 0 GPUs (CPU-only
                        # or probe failed) it must not reach llama-server; and a
                        # GPU below the buffer reserve can't participate. Drop the
                        # flag and fall through to normal layer/CPU allocation.
                        logger.info(
                            "Tensor parallelism requested but only %d of %d GPU(s) "
                            "have enough free VRAM for the compute buffer; "
                            "ignoring (needs >= 2).",
                            len(tp_gpus),
                            len(gpus),
                        )
                        tensor_parallel = False
                        # GPUs below tensor's compute-buffer reserve can still do layer
                        # split, so keep multi-GPU (mirrors the budget/geometry drops);
                        # _select_gpus caps unusable cards.
                        if len(gpus) >= 2:
                            _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        extra_args = strip_split_mode_only(extra_args)

                    # Normalize the speculative reserve BEFORE anything prices it.
                    # _mtp_bytes reads mtp_overhead_fn at call time, so leaving this
                    # until after the probes below charged the projector probe the full
                    # GPU-drafter footprint for a drafter pinned to the CPU (-ngld 0),
                    # which allocates none of it: the probe then answers "does not fit",
                    # pins the projector, and costs ~8.8x on every image encode for
                    # memory nothing was holding. _draft_cpu_no_embedded is settled well
                    # above, and every input this needs with it, so there is nothing to
                    # wait for.
                    if _draft_cpu_no_embedded and mtp_overhead_fn is not None:
                        # Nothing speculative is GPU-resident: the drafter that launches
                        # is the separate CPU-offloaded one, and any embedded head it
                        # displaced does not run. The flat fraction below is gated on
                        # this; the byte-accurate callback was not, so the fit went on
                        # charging VRAM no drafter allocates.
                        # One term survives: a Hybrid Mamba target's recurrent rollback
                        # snapshots sit in the TARGET context, so pinning the drafter to
                        # CPU does not move them. Charge those alone. Flat in ctx (the
                        # state is per-slot), hence the same _np/_n_ubatch keywords the
                        # replaced callback takes, so _mtp_bytes can still re-price slots.
                        def _cpu_draft_target_state(
                            _ctx: int,
                            _np: int = n_parallel,
                            _n_ubatch: Optional[int] = _effective_ubatch,
                            _n: int = _mtp_eff_n_max,
                            _rollback: bool = _target_rollback,
                        ) -> int:
                            if not _rollback or _n <= 0:
                                return 0
                            return self._mamba_recurrent_state_bytes(_np) * _n

                        mtp_overhead_fn = (
                            _cpu_draft_target_state
                            if _cpu_draft_target_state(effective_ctx) > 0
                            else None
                        )
                        _mtp_kv_unsized = False

                    # Projector placement, the FIRST thing given up when the load does
                    # not fit: the encoder runs once per image, layers once per token,
                    # so host RAM is its better home when it is what costs residency.
                    # Ahead of the drafter (a bounded per-image cost is cheaper to give
                    # up than a per-token speedup); never a reason to drop vision, which
                    # would answer a pasted screenshot text-only with no signal.
                    #
                    # Does the pin free anything? Only on a device with a budget of its
                    # own. Apple unified memory and AMD APUs / iGPUs report free SYSTEM
                    # RAM as free "VRAM", so the encoder just moves inside one pool.
                    # Their marker is a total of 0, which also covers a total the probe
                    # could not read (MIG/vGPU) -- same answer either way.
                    #
                    # Asked of the budgeted devices, not all of them: a laptop pairing a
                    # discrete card with an APU enumerates both, and demanding every one
                    # be discrete refused the pin there, keeping a projector the discrete
                    # card could have been rid of.
                    # Applied here, or after the pooled weight-budget check gives
                    # tensor mode up. One body, so the two sites cannot drift.
                    _mm_pin_deferred = False

                    def _apply_mmproj_cpu_pin(floor_ctx: int) -> None:
                        nonlocal _mmproj_cpu_pinned, _mmproj_pinned_bytes
                        nonlocal mmproj_size, model_size
                        _mmproj_cpu_pinned = True
                        _mmproj_pinned_bytes = mmproj_size
                        # Everything downstream prices the projector off these two,
                        # including the drop probe below: it sees the lighter footprint
                        # and gives the drafter up only if the pin was not enough.
                        mmproj_size = 0
                        model_size = gguf_size
                        # What the startup-recovery pin reports, so a CPU-resident
                        # projector is announced whether it was predicted or salvaged;
                        # otherwise image encoding just gets mysteriously slower. After
                        # the per-load reset, before the recovery paths, which override
                        # it with their more specific reason.
                        self._mmproj_fallback_reason = "cpu_offload"
                        logger.info(
                            "Auto: running the vision projector on the CPU "
                            "(--no-mmproj-offload); it does not fit in VRAM "
                            "alongside the model at %d context. Image encoding "
                            "gets slower, text generation is unaffected. Pass "
                            "--mmproj-offload in the advanced arguments to keep it "
                            "on the GPU.",
                            floor_ctx,
                        )

                    _mm_budgeted_gpus = [
                        (_idx, _free) for _idx, _free in gpus if total_by_idx.get(_idx, 0) > 0
                    ]
                    _discrete_vram = bool(_mm_budgeted_gpus)
                    if (
                        effective_is_vision
                        and mmproj_size > 0
                        and _discrete_vram
                        and not _mmproj_cpu_pinned
                        and gpu_memory_mode != "manual"
                        # Not gated on tensor_parallel: these are layer-split numbers,
                        # so the ANSWER is still never applied to a tensor load, but the
                        # pooled weight-budget check below can end one, and it prices
                        # weights + projector -- it downgrades exactly the loads moving
                        # the encoder would have rescued. Asking here and applying after
                        # that downgrade is the non-circular order; making the check
                        # pin-aware would decide TP from a pin decided from TP.
                        and _paravirtual_mmproj_pinnable(server_caps)
                        # Last-wins on the placement pair, so whoever named either
                        # spelling owns it. The environment counts: arg.cpp applies
                        # set_env before argv, so --no-mmproj-offload here would
                        # OVERWRITE LLAMA_ARG_MMPROJ_OFFLOAD=1, not lose to it.
                        and not _extra_args_set_mmproj_offload(extra_args)
                        and not _env_sets_mmproj_offload()
                    ):
                        # One question, asked once: at the context this load will
                        # actually run at, with speculative decoding STILL LIVE, does
                        # model + drafter + projector stay resident in VRAM? Which
                        # context that is, is the whole question.
                        #
                        # AUTO gets the FLOOR, which makes this a residency question and
                        # not a context one. Auto shrinks the CONTEXT before it spills
                        # layers, reaching `--fit on` only once even _FIT_MIN_CTX will
                        # not place -- and then RAISES the context to _AUTO_OFFLOAD_CTX,
                        # since offload is already unavoidable by that point. So this
                        # floor is deliberately the residency floor and not the context
                        # the load ends up running at; the projector's bytes are charged
                        # again at the real context through _subset_model_size below.
                        # Pricing at the native length would answer "does not fit" for a
                        # load merely heading for a smaller context and pin a projector
                        # that was resident all along -- 8.8x on image encode for nothing.
                        #
                        # An EXPLICIT context gets its requested length, because there
                        # the reasoning points the other way: the loop honors a pinned
                        # context verbatim, so the only give left is `--fit on`, which
                        # spills MODEL LAYERS and collapses decode ~3x. Asking at 4096
                        # would answer "fits", keep the projector, and pay in offloaded
                        # weights -- this probe's trade at its worst rate.
                        #
                        # The drafter IS charged: this runs before the drop probe, so
                        # speculative decoding is still in the footprint. Priced exactly
                        # where the fit prices it below, term for term.
                        _mm_mtp_on_gpu = _mtp_will_engage and not _draft_cpu_no_embedded
                        _mm_frac = _vram_frac - (
                            _MTP_VRAM_RESERVE_FRAC
                            if (_mm_mtp_on_gpu and (mtp_overhead_fn is None or _mtp_kv_unsized))
                            else 0.0
                        )
                        _mm_floor_ctx = (
                            effective_ctx
                            if explicit_ctx
                            else min(self._MMPROJ_FIT_FLOOR_CTX, effective_ctx)
                        )
                        _mm_need = (
                            gguf_size
                            + mmproj_size
                            + _compute_buffer_pipeline
                            + self._CUDA_CONTEXT_RESERVE_BYTES
                            + int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                            + (self._MTP_DRAFT_COMPUTE_BYTES if _mm_mtp_on_gpu else 0)
                        )
                        if _mm_floor_ctx > 0 and self._can_estimate_kv():
                            _mm_need += (
                                _kv_bytes(_mm_floor_ctx)
                                + _cc_bytes(_mm_floor_ctx)
                                + _mtp_bytes(_mm_floor_ctx)
                            )
                        else:
                            # No KV estimate: the fit builds one flat footprint against
                            # _mtp_bytes at the native length and no context it hands
                            # out lowers it, so charging the reserve at a floor the fit
                            # never applies would promise room the fit never sees.
                            # Rebound rather than used inline so the log below names the
                            # length this actually priced against.
                            _mm_floor_ctx = self._context_length or effective_ctx or 4096
                            _mm_need += _mtp_bytes(_mm_floor_ctx)
                        # Run through whichever selector the branch below will use, at
                        # the same fraction and per-device overhead, so "does not fit"
                        # here is a placement that branch could not have chosen either.
                        # A probe more optimistic than the placement it gates is the
                        # failure mode that matters: projector kept, layers spilled.
                        #
                        # Split-aware, because a layer split replicates a BIGGER
                        # context-compute buffer per device (_CTX_COMPUTE_SPLIT_MULT):
                        # at 65536 on two cards, 96 MiB charged against 768 MiB spent, a
                        # gap wider than the projector surcharge being decided. Mirrored
                        # term for term, including the single-to-split step.
                        #
                        # Plain only where the placement itself is plain: with no KV
                        # estimate it falls to the file-size-only path, which is
                        # _select_gpus at the flat overhead. Same condition that decided
                        # whether _mm_need carries a context-compute term, so the two
                        # cannot drift apart.
                        _mm_split_aware = self._can_estimate_kv()
                        _, _mm_needs_fit = (
                            self._select_gpus_split_aware(
                                _mm_need,
                                _mm_budgeted_gpus,
                                usable_fraction = _mm_frac,
                                total_by_idx = total_by_idx,
                                per_device_overhead_bytes = _pipeline_overhead_bytes
                                + _cc_bytes(_mm_floor_ctx),
                                min_gpus = _layer_min_gpus,
                                split_extra_bytes = _cc_split_extra(_mm_floor_ctx),
                            )
                            if _mm_split_aware
                            else self._select_gpus(
                                _mm_need,
                                _mm_budgeted_gpus,
                                usable_fraction = _mm_frac,
                                total_by_idx = total_by_idx,
                                per_device_overhead_bytes = _pipeline_overhead_bytes,
                                min_gpus = _layer_min_gpus,
                            )
                        )
                        if _mm_needs_fit:
                            if tensor_parallel:
                                # Held, not dropped. Applying it here would price a
                                # tensor load off layer-split numbers; discarding it
                                # would lose the verdict the downgrade below needs.
                                _mm_pin_deferred = True
                            else:
                                _apply_mmproj_cpu_pin(_mm_floor_ctx)

                    # Target pins but the drafter's reserve tips it over: Auto drops the
                    # drafter rather than pay for speed with context (or a --fit offload,
                    # where decode collapses ~3x). Priced over the SAME ranked subsets the
                    # placement loop walks, at the context the target alone would get, so
                    # it drops only when no placement could have held both. Carried to the
                    # launch as drafter_no_vram. Skipped under tensor parallelism, whose
                    # per-device buffer has its own geometry these numbers do not model;
                    # `tensor_parallel` already reflects the downgrades hoisted above, so
                    # a request that ends up layer-split IS probed. The pooled tensor
                    # weight-budget check below still escapes, since it prices the reserve
                    # this probe may clear and running it first would be circular. The
                    # gate reads the user's choice, not _mtp_effective, which by here is
                    # the kind Auto resolved and can no longer tell the two apart.
                    if (
                        _mtp_will_engage
                        and (_canonicalize_spec_mode(speculative_type) or "auto") == "auto"
                        and not _user_mtp_via_extras
                        and not _user_draft_via_extras
                        and not _extra_args_set_spec_type(extra_args)
                        # A bare --model-draft / --spec-draft-hf sets neither flag above
                        # (both key off --spec-type), yet llama.cpp loads whatever it
                        # names anyway: load_model gates the draft on has_dft(). Dropping
                        # here would free the reserve for a drafter that still loads.
                        and not _extra_args_mtp_draft_path(extra_args, env = _spec_env)
                        and not _draft_cpu_no_embedded
                        and not tensor_parallel
                        and gpus
                        and effective_ctx > 0
                        and self._can_estimate_kv()
                    ):

                        def _probe_frac(drafter: bool) -> float:
                            # The flat fraction is the reserve whenever _mtp_bytes is 0.
                            # Same budget the fit uses, else the probe answers for a
                            # card size the fit never tests.
                            return _vram_frac - (
                                _MTP_VRAM_RESERVE_FRAC
                                if (drafter and (mtp_overhead_fn is None or _mtp_kv_unsized))
                                else 0.0
                            )

                        def _probe_base(drafter: bool, n: int) -> int:
                            # model_size_fit's terms, before it is built below.
                            _soft = self._CUDA_CONTEXT_RESERVE_BYTES
                            if effective_is_vision and mmproj_size > 0:
                                _soft += int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                            if drafter:
                                _soft += self._MTP_DRAFT_COMPUTE_BYTES
                            return (
                                model_size
                                + _compute_buffer_pipeline
                                + _soft
                                + max(0, n - 1) * _pipeline_overhead_bytes
                            )

                        # Fewest GPUs first, ranked by usable VRAM: the same order and
                        # the same budget the auto placement loop uses, so the answer is
                        # about placements that loop could actually choose.
                        def _probe_rank(drafter: bool) -> list:
                            return sorted(
                                gpus,
                                key = lambda g: _gpu_usable(g, _probe_frac(drafter)),
                                reverse = True,
                            )

                        _probe_overhead_mib = _pipeline_overhead_bytes / (1024 * 1024)

                        def _probe_floor(ranked: list, drafter: bool) -> int:
                            # Same floor as the placement loop's _auto_min_gpus: a tensor
                            # downgrade raises _layer_min_gpus to keep the request
                            # multi-GPU, and a one-GPU placement the loop is forbidden to
                            # choose must not be the one that saves the drafter.
                            return max(
                                1,
                                min(
                                    _layer_min_gpus,
                                    sum(
                                        1
                                        for g in ranked
                                        if _gpu_usable(g, _probe_frac(drafter))
                                        > _probe_overhead_mib
                                    )
                                    or 1,
                                ),
                            )

                        # Both rankings: an unsized drafter costs five points of pin
                        # fraction, which can reorder heterogeneous cards (a busy 80 GB
                        # can lead at 0.97, an idle 24 GB at 0.92). The placement loop
                        # sorts under the fraction that load ends up with, so a prefix
                        # only the drafter's ranking produces is still one it can choose.
                        # Identical whenever the orders agree, i.e. every uniform machine.
                        _probe_orders = [_probe_rank(False)]
                        _ranked_w = _probe_rank(True)
                        if [id(g) for g in _ranked_w] != [id(g) for g in _probe_orders[0]]:
                            _probe_orders.append(_ranked_w)
                        _target_fits_somewhere = False
                        _both_fit_somewhere = False
                        _probe_ctx = 0
                        _probe_need = _probe_have = 0.0
                        for _probe_ranked in _probe_orders:
                            if _both_fit_somewhere:
                                break
                            _probe_min_gpus = _probe_floor(_probe_ranked, False)
                            for _n in range(_probe_min_gpus, len(_probe_ranked) + 1):
                                _subset = _probe_ranked[:_n]
                                _cc_n = lambda c, _k = _n: _cc_bytes(c, _k)
                                _base_wo = _probe_base(False, _n)
                                _budget_wo = _pool_budget_mib(_subset, _probe_frac(False))
                                # Explicit context is honored verbatim, so that is what the
                                # drafter has to fit alongside; Auto gets its own best cap.
                                _ctx_wo = (
                                    effective_ctx
                                    if explicit_ctx
                                    else self._fit_context_to_vram(
                                        effective_ctx,
                                        _budget_wo,
                                        _base_wo,
                                        cache_type_kv,
                                        swa_full = swa_full,
                                        n_parallel = n_parallel,
                                        kv_unified = planned_kv_unified,
                                        n_ubatch = _effective_ubatch,
                                        ctx_checkpoints = _effective_ctx_checkpoints,
                                        flash_attn = planned_flash_attn,
                                        mtp_engaged = False,
                                        mtp_overhead_fn = None,
                                        compute_ctx_bytes_fn = _cc_n,
                                        budget_frac = 1.0,
                                        pooled = True,
                                        total_mib = None,
                                    )
                                )
                                if _ctx_wo <= 0:
                                    continue
                                _shared = _kv_bytes(_ctx_wo) + _cc_n(_ctx_wo)
                                _foot_wo = (_base_wo + _shared) / (1024 * 1024)
                                if _foot_wo > _budget_wo:
                                    continue
                                # The pooled figure hides the compute buffer every device
                                # replicates, so the weakest card may not hold the context
                                # the pool priced and the placement loop caps to what it
                                # does. Charging the drafter at the uncapped context
                                # condemns it at a context this load never reaches. Same
                                # reserve and cap the auto-context loop below applies, so
                                # the two cannot disagree. Auto only: an explicit context
                                # is honored verbatim and overflows to --fit.
                                _usable_wo = [_gpu_usable(g, _probe_frac(False)) for g in _subset]
                                _probe_reserve_at = lambda c, _k = _n: (
                                    (_pipeline_overhead_bytes if _k > 1 else 0)
                                    + _cc_bytes(c, _k) // _k
                                )
                                if not self._every_gpu_holds_reserve(
                                    _usable_wo, _probe_reserve_at(_ctx_wo)
                                ):
                                    if explicit_ctx:
                                        # Nothing to cap: this subset cannot hold it, and
                                        # _select_gpus_split_aware will go to --fit too.
                                        # Calling it a fit would drop the drafter and then
                                        # report a pin that never happened.
                                        continue
                                    _ctx_wo = self._cap_ctx_to_per_device_reserve(
                                        _ctx_wo, _usable_wo, _probe_reserve_at
                                    )
                                    if _ctx_wo <= 0:
                                        continue
                                    # Every pooled term shrinks with the context, so this
                                    # cannot newly fail; re-price rather than lean on it.
                                    _shared = _kv_bytes(_ctx_wo) + _cc_n(_ctx_wo)
                                    _foot_wo = (_base_wo + _shared) / (1024 * 1024)
                                    if _foot_wo > _budget_wo:
                                        continue
                                _foot_w = (
                                    _probe_base(True, _n) + _shared + _mtp_bytes(_ctx_wo)
                                ) / (1024 * 1024)
                                _budget_w = _pool_budget_mib(_subset, _probe_frac(True))
                                if not _target_fits_somewhere:
                                    _target_fits_somewhere = True
                                    _probe_ctx, _probe_need, _probe_have = (
                                        _ctx_wo,
                                        _foot_w,
                                        _budget_w,
                                    )
                                if _foot_w <= _budget_w:
                                    _both_fit_somewhere = True
                                    break
                                # Both do not fit at the target's own context. The loop does
                                # not move on: it re-caps the context WITH the drafter and
                                # takes this subset at whatever that leaves. So a smaller
                                # context holding both here IS the placement the load takes,
                                # paying for the drafter in context, which is the trade being
                                # refused. Only if no context fits both does it widen.
                                _ctx_w = (
                                    0
                                    if explicit_ctx
                                    else self._fit_context_to_vram(
                                        _ctx_wo,
                                        _budget_w,
                                        _probe_base(True, _n),
                                        cache_type_kv,
                                        swa_full = swa_full,
                                        n_parallel = n_parallel,
                                        kv_unified = planned_kv_unified,
                                        n_ubatch = _effective_ubatch,
                                        ctx_checkpoints = _effective_ctx_checkpoints,
                                        flash_attn = planned_flash_attn,
                                        mtp_engaged = True,
                                        mtp_overhead_fn = mtp_overhead_fn,
                                        compute_ctx_bytes_fn = _cc_n,
                                        budget_frac = 1.0,
                                        pooled = True,
                                        total_mib = None,
                                    )
                                )
                                if (
                                    _ctx_w > 0
                                    and (
                                        _probe_base(True, _n)
                                        + _kv_bytes(_ctx_w)
                                        + _cc_n(_ctx_w)
                                        + _mtp_bytes(_ctx_w)
                                    )
                                    / (1024 * 1024)
                                    <= _budget_w
                                ):
                                    break
                        if _target_fits_somewhere and not _both_fit_somewhere:
                            _spec_dropped_no_vram = True
                            _mtp_will_engage = False
                            # Clearing the flag alone leaves the reserve: the _mtp_bytes
                            # sites are unconditional and _fit_context_to_vram invokes any
                            # non-None mtp_overhead_fn whatever mtp_engaged says, so the
                            # fit would still shrink the context for a drafter that no
                            # longer launches. _mtp_kv_unsized goes with it, or
                            # _flat_mtp_engages swaps the flat fraction in as replacement.
                            mtp_overhead_fn = None
                            _mtp_kv_unsized = False
                            logger.warning(
                                "Speculative decoding disabled for this load: the model "
                                "fits in VRAM at context %d but its drafter does not "
                                "(needs %.1f GB of a %.1f GB budget, on any GPU subset). "
                                "Auto keeps the context rather than shrink it for a speed "
                                "option. Select the drafter in Settings to force it.",
                                _probe_ctx,
                                _probe_need / 1024,
                                _probe_have / 1024,
                            )

                    # Flat MTP reserve fraction: used only as the fallback when the
                    # byte-accurate mtp_overhead_fn can't size the draft KV (dims
                    # unavailable, or _mtp_kv_unsized = weights-only). A separate
                    # drafter on CPU uses no GPU (no reserve); an embedded head is on
                    # GPU regardless of draft-offload flags (keep its reserve).
                    _flat_mtp_engages = _mtp_will_engage and (
                        mtp_overhead_fn is None or _mtp_kv_unsized
                    )
                    # MTP reserves GPU VRAM unless its only drafter is a separate
                    # CPU-offloaded one (an embedded head stays on GPU). The tensor
                    # path reserves like the layer path; gate both on this.
                    _mtp_reserves_gpu = _mtp_will_engage and not _draft_cpu_no_embedded
                    # Narrower than that: whether ANY byte reserve survives on the GPU.
                    # A CPU-pinned drafter leaves the target's own rollback state behind
                    # (the block above keeps it), and the tensor floor has to hold it,
                    # tensor mode having no --fit valve and no amount of context
                    # shrinking freeing a per-slot allocation. It stays out of
                    # _mtp_reserves_gpu because that also charges the draft decode
                    # graph, which follows the drafter onto the CPU.
                    _mtp_gpu_bytes_remain = _mtp_reserves_gpu or mtp_overhead_fn is not None
                    _flat_mtp_reserve = (
                        _MTP_VRAM_RESERVE_FRAC
                        if (_flat_mtp_engages and not _draft_cpu_no_embedded)
                        else 0.0
                    )
                    _pin_fraction = _vram_frac - _flat_mtp_reserve

                    # Charge the soft overhead _CTX_FIT_VRAM_FRACTION under-covers on tight
                    # tiers, gated so plain dense loads (#5106) only pay the CUDA-ctx base.
                    # CUDA/cuBLAS context is discrete-GPU only (not Metal); the mmproj and
                    # MTP draft-graph buffers exist on every backend.
                    _soft_overhead = self._CUDA_CONTEXT_RESERVE_BYTES if gpus else 0
                    if effective_is_vision and mmproj_size > 0:
                        _soft_overhead += int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                    if _mtp_reserves_gpu:
                        _soft_overhead += self._MTP_DRAFT_COMPUTE_BYTES
                    # A CPU-pinned projector left model_size, which is right only where
                    # the bytes it gave up landed somewhere else. Shared memory -- an APU /
                    # iGPU pool, Apple unified memory, or a total the probe could not read
                    # -- has nowhere else, so the encoder sits in the very memory this fit
                    # measures and the context can spend those bytes twice.
                    #
                    # Near _discrete_vram's question but not the same one: that drops
                    # shared devices to ask whether the pin frees anything ANYWHERE, and
                    # one discrete card settles that. The fit asks what a candidate subset
                    # draws on, and the selection walks prefixes of `gpus`, so a shared
                    # device ranked first is a candidate alone. Measured: 9000 MiB of
                    # shared pool beside a nearly full discrete card fitted a 6 GiB model
                    # to 32000 tokens with a 1 GiB projector pinned into that same pool.
                    # So the charge follows the PRESENCE of shared memory, not its absence.
                    # On a mixed host that ends up purely discrete this over-charges by the
                    # projector, costing context rather than correctness.
                    _shared_pool_mmproj = (
                        _mmproj_pinned_bytes
                        if (not gpus or len(_mm_budgeted_gpus) < len(gpus))
                        else 0
                    )
                    model_size_fit = (
                        model_size + _compute_buffer_pipeline + _soft_overhead + _shared_pool_mmproj
                    )

                    def _subset_model_size(n_gpus: int) -> int:
                        return model_size_fit + max(0, n_gpus - 1) * _pipeline_overhead_bytes

                    # Unified-memory budget (0 off Apple Silicon) for the no-GPU Metal cap below.
                    _apple_budget_mib = self._apple_metal_memory_budget_bytes() // (1024 * 1024)

                    if tensor_parallel and tp_gpus:
                        # Pooled usable budget (after each device's compute buffer)
                        # must hold the non-shrinkable footprint: weights + the MTP
                        # reserve. The planner can shrink ctx/KV, not these.
                        _tp_weight_budget_mib = (
                            sum(_gpu_usable(g) for g in tp_gpus) - len(tp_gpus) * reserve_mib
                        )
                        _tp_flat_mtp = 2 * 1024**3  # flat reserve when dims unavailable
                        if not _mtp_gpu_bytes_remain:
                            # No MTP, or its only drafter is CPU-offloaded and the
                            # target keeps no state of its own (no GPU bytes at all).
                            _tp_mtp_floor = 0
                        elif mtp_overhead_fn is not None and not _mtp_kv_unsized:
                            _tp_mtp_floor = _mtp_bytes(
                                min(2048, effective_ctx) if effective_ctx > 0 else 2048
                            )
                        else:
                            # Dims unavailable / weights-only: tensor mode has no
                            # --fit valve, so keep the flat reserve as the unsized-KV
                            # cushion, never below the known byte reserve.
                            _tp_mtp_floor = max(
                                _tp_flat_mtp,
                                _mtp_bytes(min(2048, effective_ctx) if effective_ctx > 0 else 2048),
                            )
                        _tp_required_mib = (model_size + _tp_mtp_floor + _soft_overhead) / (
                            1024 * 1024
                        )
                        if _tp_weight_budget_mib <= _tp_required_mib:
                            logger.info(
                                "Tensor parallelism requested but the pooled VRAM "
                                "budget cannot hold the weights, MTP reserve, and "
                                "per-device compute buffers; falling back to layer split."
                            )
                            tensor_parallel = False
                            # Weights needed >1 card, so keep multi-GPU across the
                            # usable tensor GPUs.
                            if len(tp_gpus) >= 2:
                                _layer_min_gpus = max(_layer_min_gpus, len(tp_gpus))
                            extra_args = strip_split_mode_only(extra_args)
                            # Layer split now, so the withheld verdict applies -- but not
                            # when a GPU drafter is still in play. The drafter-drop probe
                            # is gated off under tensor parallelism, so it has not run;
                            # the documented order is projector first and drafter second,
                            # and pinning here without being able to re-ask the second
                            # half pays the encoder cost AND still reaches --fit on.
                            # Re-running that probe after this downgrade is the complete
                            # fix.
                            if _mm_pin_deferred and not _mtp_reserves_gpu:
                                _apply_mmproj_cpu_pin(_mm_floor_ctx)
                                _mm_pin_deferred = False
                                # Rebuild what was derived from model_size before the
                                # pin. _subset_model_size closes over model_size_fit by
                                # name, so rebinding it carries to the fit below.
                                _soft_overhead = self._CUDA_CONTEXT_RESERVE_BYTES if gpus else 0
                                if _mtp_reserves_gpu:
                                    _soft_overhead += self._MTP_DRAFT_COMPUTE_BYTES
                                _shared_pool_mmproj = (
                                    _mmproj_pinned_bytes
                                    if (not gpus or len(_mm_budgeted_gpus) < len(gpus))
                                    else 0
                                )
                                model_size_fit = (
                                    model_size
                                    + _compute_buffer_pipeline
                                    + _soft_overhead
                                    + _shared_pool_mmproj
                                )

                    if tensor_parallel and tp_gpus:
                        # Tensor-parallel allocation; see _plan_tensor_parallel.
                        target_ctx = (
                            effective_ctx
                            if explicit_ctx
                            else (self._context_length or effective_ctx)
                        )
                        # When the draft KV couldn't be sized (weights-only reserve),
                        # the planner's mtp_overhead_fn is non-None but covers only
                        # weights, so pass the flat cushion for the unsized KV (else
                        # the binary search spends it on context).
                        _tp_unsized_mtp_reserve = (
                            2 * 1024**3 if (_mtp_reserves_gpu and _mtp_kv_unsized) else 0
                        )
                        (
                            effective_ctx,
                            max_available_ctx,
                            gpu_indices,
                            tp_tensor_split,
                        ) = self._plan_tensor_parallel(
                            tp_gpus,
                            model_size,
                            target_ctx,
                            cache_type_kv = cache_type_kv,
                            scratch_cache_type_kv = _scratch_cache_type_kv,
                            n_parallel = n_parallel,
                            mtp_engaged = _mtp_reserves_gpu,
                            mtp_overhead_fn = mtp_overhead_fn,
                            mtp_flat_reserve_bytes = _tp_unsized_mtp_reserve,
                            # Report the UI ceiling from native ctx, not the
                            # explicit small request.
                            max_target_ctx = self._context_length or target_ctx,
                            total_by_idx = total_by_idx,
                            n_ubatch = _effective_ubatch,
                            soft_overhead_bytes = _soft_overhead,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            flash_attn = planned_flash_attn,
                            # Already resolved, not a second read: a mid-load save
                            # would otherwise size placement against a fraction the
                            # ranking above never used.
                            vram_fraction = _vram_frac,
                        )
                        use_fit = False
                        _tp_planned = True
                    elif gpus and self._can_estimate_kv() and effective_ctx > 0:
                        # Compute the largest hardware-aware cap from the model's
                        # native context across all usable GPU subsets (for UI
                        # bounds), independent of the currently requested context.
                        native_ctx_for_cap = self._context_length or effective_ctx
                        if native_ctx_for_cap > 0:
                            ranked_for_cap = sorted(
                                gpus,
                                key = lambda g: _gpu_usable(g, _vram_frac - _flat_mtp_reserve),
                                reverse = True,
                            )
                            best_cap = 0
                            _cap_fraction = _vram_frac - _flat_mtp_reserve
                            for n_gpus in range(1, len(ranked_for_cap) + 1):
                                subset = ranked_for_cap[:n_gpus]
                                # Per-GPU-consistent pool budget (fixes mixed
                                # known/unknown totals); pass it as an absolute
                                # budget so the fit and the check below agree.
                                pool_budget = _pool_budget_mib(subset, _cap_fraction)
                                _ms = _subset_model_size(n_gpus)
                                # Compute buffer is replicated per device in a layer
                                # split, so scale the context term by the subset size.
                                _cc_sub = lambda c, n = n_gpus: _cc_bytes(c, n)
                                capped = self._fit_context_to_vram(
                                    native_ctx_for_cap,
                                    pool_budget,
                                    _ms,
                                    cache_type_kv,
                                    swa_full = swa_full,
                                    n_parallel = n_parallel,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = _effective_ubatch,
                                    ctx_checkpoints = _effective_ctx_checkpoints,
                                    flash_attn = planned_flash_attn,
                                    mtp_engaged = _mtp_reserves_gpu,
                                    mtp_overhead_fn = mtp_overhead_fn,
                                    compute_ctx_bytes_fn = _cc_sub,
                                    budget_frac = 1.0,
                                    pooled = True,
                                    total_mib = None,
                                )
                                kv = _kv_bytes(capped)
                                footprint_mib = (
                                    _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                ) / (1024 * 1024)
                                if footprint_mib <= pool_budget:
                                    best_cap = max(best_cap, capped)
                            if best_cap > 0:
                                max_available_ctx = best_cap
                            else:
                                # Weights exceed 90% of every GPU subset, so no
                                # context fits. Anchor the UI "safe zone" at the
                                # Auto offload fallback so the slider warns ABOVE
                                # what Auto itself selects: anchoring below it
                                # makes every Auto load in this branch exceed its
                                # own published ceiling, and the chat sheet reads
                                # that as "context exceeds the estimated VRAM
                                # capacity" while advising the user to leave it
                                # on Auto.
                                max_available_ctx = min(_AUTO_OFFLOAD_CTX, native_ctx_for_cap)

                        if explicit_ctx:
                            # Honor the requested context verbatim. If it fits,
                            # pin GPUs and skip --fit; else ship -c <ctx> --fit
                            # on and let llama-server flex -ngl (CPU offload).
                            requested_total = (
                                model_size_fit
                                + _kv_bytes(effective_ctx)
                                + _mtp_bytes(effective_ctx)
                                + _cc_bytes(effective_ctx)
                            )
                            # The compute buffer is replicated on every device in a
                            # layer split; fold it into the per-device reserve so a
                            # multi-GPU pin sizes each card for its own copy. Priced
                            # single-device (the count comes out of this figure), then
                            # re-checked at the split rate, falling back to --fit on.
                            gpu_indices, use_fit = self._select_gpus_split_aware(
                                requested_total,
                                gpus,
                                usable_fraction = _pin_fraction,
                                total_by_idx = total_by_idx,
                                per_device_overhead_bytes = _pipeline_overhead_bytes
                                + _cc_bytes(effective_ctx),
                                min_gpus = _layer_min_gpus,
                                split_extra_bytes = _cc_split_extra(effective_ctx),
                            )
                            # No silent shrink: effective_ctx stays == requested_ctx.
                        else:
                            # Auto context: prefer fewer GPUs, cap to fit. Same
                            # headroom threshold as _select_gpus (#5106). Rank by the
                            # active pin fraction so the order matches the fit budget.
                            pin_fraction = _pin_fraction
                            ranked = sorted(
                                gpus, key = lambda g: _gpu_usable(g, pin_fraction), reverse = True
                            )
                            # Skips _select_gpus, so apply its cap: count only cards
                            # whose usable VRAM clears the per-device layer overhead.
                            _pipeline_overhead_mib = _pipeline_overhead_bytes / (1024 * 1024)
                            _auto_min_gpus = max(
                                1,
                                min(
                                    _layer_min_gpus,
                                    sum(
                                        1
                                        for g in ranked
                                        if _gpu_usable(g, pin_fraction) > _pipeline_overhead_mib
                                    )
                                    or 1,
                                ),
                            )
                            for n_gpus in range(_auto_min_gpus, len(ranked) + 1):
                                subset = ranked[:n_gpus]
                                pool_budget = _pool_budget_mib(subset, pin_fraction)
                                _ms = _subset_model_size(n_gpus)
                                # Compute buffer is replicated per device in a layer
                                # split, so scale the context term by the subset size.
                                _cc_sub = lambda c, n = n_gpus: _cc_bytes(c, n)
                                capped = self._fit_context_to_vram(
                                    effective_ctx,
                                    pool_budget,
                                    _ms,
                                    cache_type_kv,
                                    swa_full = swa_full,
                                    n_parallel = n_parallel,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = _effective_ubatch,
                                    ctx_checkpoints = _effective_ctx_checkpoints,
                                    flash_attn = planned_flash_attn,
                                    mtp_engaged = _mtp_reserves_gpu,
                                    mtp_overhead_fn = mtp_overhead_fn,
                                    compute_ctx_bytes_fn = _cc_sub,
                                    budget_frac = 1.0,
                                    pooled = True,
                                    total_mib = None,
                                )
                                kv = _kv_bytes(capped)
                                footprint_mib = (
                                    _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                ) / (1024 * 1024)
                                if footprint_mib > pool_budget:
                                    continue
                                # Pooling admits a subset whose per-device reserve
                                # does not fit the smallest card, which then OOMs at
                                # launch; only knowable once `capped` is chosen.
                                _usable_mib = [_gpu_usable(g, pin_fraction) for g in subset]
                                _reserve_at = lambda c, n = n_gpus: (
                                    (_pipeline_overhead_bytes if n > 1 else 0)
                                    + _cc_bytes(c, n) // n
                                )
                                if not self._every_gpu_holds_reserve(
                                    _usable_mib, _reserve_at(capped)
                                ):
                                    # Keep the largest context the smallest card holds
                                    # rather than lose the subset to the 4096 drop below.
                                    # Costs no context: subsets are prefixes of a
                                    # usable-descending ranking and the reserve is the
                                    # same function of context for every n > 1, so any
                                    # later subset clears the gate no higher than this.
                                    capped = self._cap_ctx_to_per_device_reserve(
                                        capped, _usable_mib, _reserve_at
                                    )
                                    if capped <= 0:
                                        continue
                                    # Pooled terms only shrink with the context, so this
                                    # cannot newly fail; re-price rather than lean on that
                                    # across the KV and MTP branches.
                                    kv = _kv_bytes(capped)
                                    footprint_mib = (
                                        _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                    ) / (1024 * 1024)
                                    if footprint_mib > pool_budget:
                                        continue
                                effective_ctx = capped
                                gpu_indices = sorted(idx for idx, _ in subset)
                                use_fit = False
                                break
                            else:
                                # No discrete-GPU subset holds the model at a fitted
                                # context. Prefer a useful chat context before
                                # handing placement to --fit on and host offload.
                                effective_ctx = min(_AUTO_OFFLOAD_CTX, effective_ctx)
                                if effective_ctx > 0:
                                    for n_gpus in range(_auto_min_gpus, len(ranked) + 1):
                                        subset = ranked[:n_gpus]
                                        kv = _kv_bytes(effective_ctx)
                                        footprint_mib = (
                                            _subset_model_size(n_gpus)
                                            + kv
                                            + _mtp_bytes(effective_ctx)
                                            + _cc_bytes(effective_ctx, n_gpus)
                                        ) / (1024 * 1024)
                                        if footprint_mib > _pool_budget_mib(subset, pin_fraction):
                                            continue
                                        # Pooling hides the per-device reserve here too.
                                        if not self._every_gpu_holds_reserve(
                                            (_gpu_usable(g, pin_fraction) for g in subset),
                                            (_pipeline_overhead_bytes if n_gpus > 1 else 0)
                                            + _cc_bytes(effective_ctx, n_gpus) // n_gpus,
                                        ):
                                            continue
                                        gpu_indices = sorted(idx for idx, _ in subset)
                                        use_fit = False
                                        break

                    elif gpus:
                        # Can't estimate KV -- file-size-only check; keep the
                        # ceiling at native context (already the default).
                        logger.debug(
                            "Falling back to file-size-only GPU selection",
                            model_size_gb = round(model_size / (1024**3), 2),
                        )
                        # Add the byte-accurate MTP reserve here too when it is
                        # available; otherwise _pin_fraction carries the flat
                        # fallback (the two are mutually exclusive by design).
                        _fs_total = model_size_fit + _mtp_bytes(
                            self._context_length or effective_ctx or 4096
                        )
                        gpu_indices, use_fit = self._select_gpus(
                            _fs_total,
                            gpus,
                            usable_fraction = _pin_fraction,
                            total_by_idx = total_by_idx,
                            per_device_overhead_bytes = _pipeline_overhead_bytes,
                            min_gpus = _layer_min_gpus,
                        )
                        if use_fit and not explicit_ctx:
                            # Without KV metadata, llama.cpp owns the fit. Keep the
                            # same useful Auto default as the measured offload path.
                            effective_ctx = (
                                min(_AUTO_OFFLOAD_CTX, effective_ctx)
                                if effective_ctx > 0
                                else _AUTO_OFFLOAD_CTX
                            )

                    elif _apple_budget_mib > 0 and effective_ctx > 0:
                        # No GPU on Metal: the branches above are skipped and the context
                        # stays at native, over-committing unified memory (#5118, #6529).
                        # Cap with the same fit math; Auto shrinks to the cap, an explicit
                        # request above it is refused. "--fit on" stays a backstop but not
                        # one this can lean on: llama.cpp sizes its reduction from
                        # ggml-metal's free-memory report, blind to Unsloth's own footprint
                        # and the wired limit. See _metal_context_overcommit_message.
                        native_ctx_for_cap = self._context_length or effective_ctx
                        # This arm's floor, which is _FIT_MIN_CTX only while the child's
                        # fitter can come down from it. With --fit off (argv or
                        # LLAMA_ARG_FIT) nothing reduces what we emit, so hand over the
                        # number llama.cpp's own fitter would have reduced to instead.
                        # _metal_zero_ctx_floor draws the same distinction but never sees
                        # these paths: they assign a POSITIVE context, and its first
                        # condition returns 0 for any positive effective_ctx.
                        _metal_floor_ctx = (
                            _FIT_MIN_CTX
                            if fit_is_effectively_on(extra_args, os.environ)
                            else _LLAMA_FIT_MIN_CTX
                        )
                        # Only a ceiling backed by a real KV estimate may refuse; the 4096
                        # fallback below is a guess and would block working loads.
                        _apple_measured_ceiling: Optional[int] = None
                        # The other measured verdict: nothing fits, so there is no ceiling
                        # to name and every explicit request over-commits.
                        _apple_nothing_fits = False
                        # Reserve the flat MTP fraction up front like the discrete
                        # _pin_fraction, so an unsized MTP draft (e.g. Qwen3.6-MTP, #6529)
                        # can't over-commit. No-op when MTP is off; exclusive with the
                        # byte-accurate _mtp_bytes reserve.
                        _apple_fit_budget_mib = int(
                            _apple_budget_mib * max(0.0, 1.0 - _flat_mtp_reserve)
                        )
                        # A CPU-pinned projector is already carried by model_size_fit here:
                        # this arm is reached only with no GPU enumerated, so no device has
                        # a budget of its own and _shared_pool_mmproj charged those bytes.
                        # Adding them again would price the encoder twice.
                        _apple_model_size_fit = model_size_fit

                        def _apple_ctx_fit(target: int, min_ctx: int) -> int:
                            return self._fit_context_to_vram(
                                target,
                                _apple_fit_budget_mib,
                                _apple_model_size_fit,
                                cache_type_kv,
                                min_ctx = min_ctx,
                                swa_full = swa_full,
                                n_parallel = n_parallel,
                                kv_unified = planned_kv_unified,
                                n_ubatch = _effective_ubatch,
                                ctx_checkpoints = _effective_ctx_checkpoints,
                                flash_attn = planned_flash_attn,
                                mtp_engaged = _mtp_reserves_gpu,
                                mtp_overhead_fn = mtp_overhead_fn,
                                compute_ctx_bytes_fn = _cc_bytes,
                                budget_frac = 1.0,
                                pooled = True,
                                total_mib = None,
                            )

                        def _apple_footprint_mib(ctx: int) -> float:
                            return (
                                _apple_model_size_fit
                                + _kv_bytes(ctx)
                                + _mtp_bytes(ctx)
                                + _cc_bytes(ctx)
                            ) / (1024 * 1024)

                        if self._can_estimate_kv():
                            cap = _apple_ctx_fit(native_ctx_for_cap, _FIT_MIN_CTX)
                            _cap_footprint_mib = _apple_footprint_mib(cap)
                            # Fit returns the request unchanged when it fits OR weights
                            # exceed budget; only the latter over-commits, so floor to
                            # _FIT_MIN_CTX.
                            if _cap_footprint_mib <= _apple_fit_budget_mib:
                                max_available_ctx = cap
                                _apple_measured_ceiling = cap
                            else:
                                # Two states land here, only one unmeasurable. Weights
                                # alone over budget: the fit returned the request
                                # untouched, priced nothing, and no context rescues it.
                                # Or the weights fit and it is the helper's own
                                # _FIT_MIN_CTX floor that does not -- a floor, not a
                                # measurement, so re-price under it before concluding
                                # nothing was measured. Without that pass a Mac with room
                                # for no tested context skipped the refusal and reached
                                # llama-server, whose own --fit stops at LLAMA.CPP's
                                # fit_params_min_ctx (4096, a different number from ours
                                # since this arm's floor became _FIT_MIN_CTX) and so
                                # cannot rescue it either.
                                _floor_cap = _apple_ctx_fit(native_ctx_for_cap, _FIT_FLOOR_MIN_CTX)
                                # Ask the budget directly rather than inferring the
                                # weights-only state from the two fits disagreeing: both
                                # are bounded by the same target, so on a model whose
                                # native length is at or under the floor they tie for a
                                # reason unrelated to the weights, which read as "priced
                                # nothing" and refused nothing. Reachable at native == 256,
                                # and whenever the GGUF carries no context length and the
                                # request itself is that small.
                                _weights_over_budget = (
                                    model_size_fit / (1024 * 1024)
                                ) > _apple_fit_budget_mib
                                if _weights_over_budget:
                                    # The fit priced nothing: no context rescues a load
                                    # whose weights alone miss the budget, and that is the
                                    # host-RAM guard's failure. Floor for the UI, but do
                                    # not refuse against a number the fit never vouched for.
                                    max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                                elif _apple_footprint_mib(_floor_cap) <= _apple_fit_budget_mib:
                                    max_available_ctx = _floor_cap
                                    _apple_measured_ceiling = _floor_cap
                                else:
                                    # It shrank, so the weights fit and even the smallest
                                    # context the search prices does not. A measurement
                                    # too, and the strongest available: nothing fits, so
                                    # there is no number to lower to and every explicit
                                    # request over-commits. Auto is untouched as everywhere
                                    # else here -- it keeps this arm's floor, which is now
                                    # _FIT_MIN_CTX like every other arm, rather than the
                                    # separate 4096 Metal used to hold.
                                    max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                                    _apple_nothing_fits = True
                        else:
                            # No KV estimate: mirror the discrete file-size-only fallback
                            # and floor to _FIT_MIN_CTX rather than launch at native and
                            # over-commit.
                            max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                        if not explicit_ctx:
                            effective_ctx = max_available_ctx
                        elif (
                            (_apple_measured_ceiling is not None or _apple_nothing_fits)
                            and not _caller_owns_budget
                            and not _paravirtual_cpu_forced
                        ):
                            # Exempt for the reason the other two Metal guards are: a
                            # manual load with a fixed layer count is the user taking the
                            # memory budget over, read off the request so the paravirtual
                            # CPU pin (which rewrites Auto to manual/0) cannot make a plain
                            # Auto load look caller-owned.
                            #
                            # The virtualised device is exempt for the opposite reason:
                            # that pin puts the whole load on CPU behind --device none, so
                            # it allocates no Metal memory and this budget is the wrong
                            # yardstick. Refusing would break Mac VM loads that work today,
                            # and the message would describe a GPU the launch never
                            # touches. Its real risk is host RAM, which
                            # _host_offload_shortfall_message already prices.
                            #
                            # The fit above is sized through the model's native length, so
                            # on its own it caps the ceiling there and refuses every
                            # request past it -- including ones this Mac has the memory
                            # for. Nothing clamps a request to native on the way in (the
                            # Extra Arguments box takes a raw "--ctx-size" and even
                            # suggests "--rope-scaling yarn"), and llama.cpp builds the
                            # context at the full -c, capping only the per-slot value
                            # afterwards, so the request is what gets allocated. Re-price
                            # through it, adopting the answer only when the budget
                            # vouches for it.
                            if _apple_measured_ceiling is not None and (
                                effective_ctx > native_ctx_for_cap
                            ):
                                _extended_ceiling = _apple_ctx_fit(effective_ctx, _FIT_MIN_CTX)
                                if _apple_footprint_mib(_extended_ceiling) > _apple_fit_budget_mib:
                                    # _FIT_MIN_CTX is the helper's floor, not a
                                    # measurement, and the cap above re-prices under it
                                    # for the same reason.
                                    # It bites here whenever native is below the floor: the
                                    # request is above native and the floor above what
                                    # fits, so the probe hands back a non-fitting floor, the
                                    # check discards it, and the refusal keeps naming the
                                    # native-sized cap -- "the largest that fits is 2,048"
                                    # on a 2048-native model whose machine launches 3,072
                                    # when asked for it directly.
                                    _extended_ceiling = _apple_ctx_fit(
                                        effective_ctx, _FIT_FLOOR_MIN_CTX
                                    )
                                if (
                                    _extended_ceiling > _apple_measured_ceiling
                                    and _apple_footprint_mib(_extended_ceiling)
                                    <= _apple_fit_budget_mib
                                ):
                                    _apple_measured_ceiling = _extended_ceiling
                                    # Publish it too: max_available_ctx becomes
                                    # max_context_length, which the UI reads as the
                                    # largest context that fits and both amber warnings
                                    # compare against. Left at native, a load this branch
                                    # just measured and allowed would arrive with a
                                    # warning saying it does not fit. The fit is bounded
                                    # by the request, so the bound rises to the context
                                    # that loaded and no further.
                                    max_available_ctx = max(
                                        max_available_ctx, _apple_measured_ceiling
                                    )
                            _metal_ctx_refusal = self._metal_context_overcommit_message(
                                effective_ctx,
                                _apple_measured_ceiling or 0,
                                cache_type_kv,
                                nothing_fits = _apple_nothing_fits,
                            )

                    # Prefer fewer serving slots on GPU over --fit on offload: when the extra
                    # --parallel slots push the footprint past the pin budget, llama-server
                    # offloads layers to host and decode collapses ~3x (#6718). Retry the fit
                    # at fewer slots, keeping the largest count that stays fully on GPU and the
                    # chosen context. Skips tensor mode / Metal / KV-inestimable paths.
                    if (
                        use_fit
                        and n_parallel > 1
                        and gpus
                        and self._can_estimate_kv()
                        and effective_ctx > 0
                    ):
                        # The PROBE context for the search below, not the context the load
                        # runs at: the re-fit further down awards that, from the final slot
                        # count. So price the search at the fit search floor, never at
                        # _AUTO_OFFLOAD_CTX.
                        #
                        # _AUTO_OFFLOAD_CTX is what Auto settles for once offload really is
                        # unavoidable. Asking this search at that value asks the wrong
                        # question, because this block exists to OVERTURN "offload is
                        # unavoidable" by re-asking at fewer slots -- a higher probe can only
                        # make it fail, and its failure is all-or-nothing: no reduction and
                        # --fit on, so the load keeps the slot count it could not afford and
                        # offloads anyway. Measured on a 12 GiB card, probing at 8192 instead
                        # of the floor moves the hybrid 10,900-11,100 MiB and dense
                        # 9,800-10,500 MiB bands from fully GPU-resident to host offload, the
                        # ~3x decode collapse (#6718) this whole block was written to avoid.
                        #
                        # An explicit context is the exception: it launches verbatim, so the
                        # search has to be priced at the context that will actually run or the
                        # slot count it picks is one the card cannot hold.
                        #
                        # _FIT_MIN_CTX rather than a literal: _largest_ctx below starts its
                        # binary search at the same floor, and the two must agree or the
                        # search can pick a slot count the re-fit then refuses to confirm.
                        _reduce_ctx = (
                            effective_ctx if explicit_ctx else min(effective_ctx, _FIT_MIN_CTX)
                        )
                        # Slot-independent footprint (folded compute buffer and the MTP
                        # reserve swapped out so the helper re-prices both per candidate).
                        _base_footprint = (
                            model_size_fit - _compute_buffer_pipeline + _cc_bytes(_reduce_ctx)
                        )
                        _gi_slots, _uf_slots, _slots = self._slots_that_fit_on_gpu(
                            n_parallel,
                            _reduce_ctx,
                            gpus,
                            total_by_idx,
                            _base_footprint,
                            cache_type_kv,
                            _pin_fraction,
                            _pipeline_overhead_bytes + _cc_bytes(_reduce_ctx),
                            _layer_min_gpus,
                            _effective_ubatch,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            flash_attn = planned_flash_attn,
                            split_extra_bytes = _cc_split_extra(_reduce_ctx),
                            ubatch_for_slots = _ubatch_for_slots,
                            mtp_bytes_for_slots = lambda s, ub: _mtp_bytes(_reduce_ctx, s, ub),
                            ctx_checkpoints = _effective_ctx_checkpoints,
                        )
                        if not _uf_slots:
                            _slots_asked = n_parallel
                            gpu_indices, use_fit, n_parallel = _gi_slots, False, _slots
                            # Fewer slots means a lower batch floor, so the launch runs a
                            # smaller micro-batch than the one this was sized at. Re-derive
                            # it, or the recorded _n_ubatch describes a graph never built.
                            _effective_ubatch = _ubatch_for_slots(n_parallel)
                            # Re-fit at the final slot count; the KV and compute closures
                            # read the values just rebound above.

                            def _slots_hold(
                                ctx: int, devices: list[tuple[int, int]]
                            ) -> Optional[list[int]]:
                                """Return the GPU subset if the final slot count fits."""
                                _gi, _uf, _got = self._slots_that_fit_on_gpu(
                                    n_parallel,
                                    ctx,
                                    devices,
                                    total_by_idx,
                                    model_size_fit - _compute_buffer_pipeline + _cc_bytes(ctx),
                                    cache_type_kv,
                                    _pin_fraction,
                                    _pipeline_overhead_bytes + _cc_bytes(ctx),
                                    _layer_min_gpus,
                                    _effective_ubatch,
                                    swa_full = swa_full,
                                    kv_unified = planned_kv_unified,
                                    flash_attn = planned_flash_attn,
                                    split_extra_bytes = _cc_split_extra(ctx),
                                    ubatch_for_slots = _ubatch_for_slots,
                                    mtp_bytes_for_slots = (lambda s, ub, c = ctx: _mtp_bytes(c, s, ub)),
                                    ctx_checkpoints = _effective_ctx_checkpoints,
                                    include_requested = True,
                                    exact = True,  # only n_parallel is accepted below
                                )
                                return _gi if not _uf and _got == n_parallel else None

                            def _largest_ctx(
                                devices: list[tuple[int, int]],
                            ) -> Optional[tuple[int, list[int]]]:
                                """Largest 256-aligned context these cards hold; the
                                footprint grows monotonically with context.

                                Bound here, not by the arm above: the arm that reaches this
                                is not always the one that binds it, and a GGUF with no
                                native length would arrive with the 0 sentinel and search
                                nothing."""
                                _native = self._context_length or _reduce_ctx
                                _lo = max(1, min(_FIT_MIN_CTX, _native) // 256)
                                _hi = _native // 256
                                _best = None
                                while _lo <= _hi:
                                    _mid = (_lo + _hi) // 2
                                    _held = _slots_hold(_mid * 256, devices)
                                    if _held is None:
                                        _hi = _mid - 1
                                    else:
                                        _best = (_mid * 256, _held)
                                        _lo = _mid + 1
                                return _best

                            # Only the cards the reduction chose. Searching every GPU
                            # again buys context by pulling in another device -- the layer
                            # split this path avoids, and one a direct request never makes.
                            _kept = set(_gi_slots or ())
                            _plan_gpus = [g for g in gpus if g[0] in _kept]
                            _refit = _largest_ctx(_plan_gpus)
                            # Explicit contexts are never rewritten. Otherwise the re-fit is
                            # the answer, in both directions: it is the largest context the
                            # FINAL slot count holds on the cards the reduction chose, so
                            # taking anything else launches a context that was never priced.
                            # Not gated on it being an increase over effective_ctx -- that
                            # gate was safe only while the search and effective_ctx shared a
                            # value, and _AUTO_OFFLOAD_CTX above the probe floor is exactly
                            # the case where the re-fit legitimately comes back lower.
                            if _refit is not None and not explicit_ctx:
                                if _refit[0] != effective_ctx:
                                    logger.info(
                                        "Context re-fitted %d -> %d for %d serving slot(s).",
                                        effective_ctx,
                                        _refit[0],
                                        n_parallel,
                                    )
                                effective_ctx, gpu_indices = _refit
                            # After the re-fit, so it names the context that launches
                            # rather than one sized for slots this load dropped.
                            logger.info(
                                "Serving slots reduced %d -> %d to keep the model on GPU "
                                "(avoid --fit offload) at context %d.",
                                _slots_asked,
                                n_parallel,
                                effective_ctx,
                            )
                            # Across every card at the final slot count, matching the
                            # best_cap sweep above; an explicit request that large does
                            # re-select GPUs and load. Not a hardware maximum -- a larger
                            # request can reduce slots further and free KV for more.
                            _ceiling = (
                                _refit if len(_plan_gpus) == len(gpus) else _largest_ctx(gpus)
                            )
                            if _ceiling is not None:
                                # Replaces the anchor rather than raising it. Reaching here
                                # means the offload fallback set max_available_ctx for a plan
                                # this block just superseded, and max() would keep publishing
                                # that plan's number: with _AUTO_OFFLOAD_CTX above what the
                                # final slot count holds, the sheet would advertise a context
                                # the launched plan cannot serve, which is the same ceiling /
                                # selection inversion #9492 removed, pointing the other way.
                                max_available_ctx = _ceiling[0]

                    # Pass the final slot and micro-batch values instead of the defaults
                    # captured before slot reduction.
                    _mtp_reserve_bytes = (
                        _mtp_bytes(effective_ctx, n_parallel, _effective_ubatch)
                        if _mtp_will_engage
                        else 0
                    )
                    if _mtp_will_engage:
                        _mtp_note = (
                            f"MTP reserve: {_mtp_reserve_bytes / (1024**3):.2f} GB "
                            f"(draft KV @ {effective_ctx} + verify n_max={_mtp_eff_n_max}"
                            + (", flat-frac fallback" if mtp_overhead_fn is None else "")
                            + "), "
                        )
                    else:
                        _mtp_note = ""

                    if effective_ctx < original_ctx:
                        kv_est = _kv_bytes(effective_ctx)
                        logger.info(
                            f"Context auto-reduced: {original_ctx} -> {effective_ctx} "
                            f"(model: {model_size / (1024**3):.1f} GB, "
                            f"est. KV cache: {kv_est / (1024**3):.1f} GB, "
                            f"{_mtp_note}".rstrip(", ")
                            + ")"
                        )

                    kv_cache_bytes = _kv_bytes(effective_ctx)
                    # Everything the spill planner needs, snapshotted as plain ints
                    # where it is already evaluated.
                    _spill_inputs = {
                        "model_size": model_size,
                        "kv_cache_bytes": kv_cache_bytes,
                        "gpus": list(gpus or ()),
                        # The budget the fit above tested, per device: _gpu_usable
                        # applies the VRAM-budget fraction and the reserve floor.
                        # Raw free_mib is 3.5 GiB per card larger at 0.80 on a
                        # 24 GiB card, so planning on it under-spills and then pins
                        # the result with --fit off.
                        #
                        # _pin_fraction, not the bare _vram_frac: when the drafter
                        # engages but its KV cannot be sized, the placement paths
                        # spend _MTP_VRAM_RESERVE_FRAC less of every card and
                        # _mtp_reserve_bytes carries no replacement for the unsized
                        # part, so crediting the full fraction here would hand the
                        # planner 5% of VRAM the fit deliberately kept free. Equal to
                        # _vram_frac on every other load (_flat_mtp_reserve is 0).
                        "gpu_usable_mib": {
                            _idx: max(0.0, _gpu_usable((_idx, _free), _pin_fraction))
                            for _idx, _free in (gpus or ())
                        },
                        "gpu_indices": gpu_indices,
                        "soft_overhead": _soft_overhead,
                        # GPU-resident bytes in model_size_fit the planner cannot
                        # see: it rebuilds from the target GGUF's tensor table, so
                        # the projector and MTP reserve are absent from its deficit.
                        "extra_gpu_bytes": (mmproj_size + _shared_pool_mmproj + _mtp_reserve_bytes),
                        # The compute buffer, charged on the same terms as the fit
                        # that produced the use_fit verdict: model_size_fit carries
                        # the flat _compute_buffer_pipeline IN ADDITION to
                        # _soft_overhead, and the fit adds _cc_bytes(ctx) per device
                        # on top, so there is no double charge. Omitting them is not
                        # conservative -- _cc_bytes is context-linear (tens of GiB
                        # on deepseek4 at 1M, ~2.4 GiB on a quantised cache at 128K)
                        # and the plan is pinned with --fit off, so the shortfall is
                        # a graph_reserve OOM with nothing left to catch it.
                        "compute_buffer_flat": int(_compute_buffer_pipeline),
                        "ctx_compute_per_device": (
                            _cc_bytes(effective_ctx, max(1, len(gpus or ())))
                            // max(1, len(gpus or ()))
                        ),
                        # An engaging draft turns the trailing nextn/MTP blocks from
                        # skipped bytes into resident ones in the TARGET's load, so
                        # charge them back. Any engaged draft counts: load_mtp comes
                        # from the spec type (common/common.cpp:1713), and a
                        # separate drafter that is itself an MTP head selects that
                        # same type (common/speculative.cpp:2257-2261).
                        # Over-charging only spills more.
                        "mtp_will_engage": bool(_mtp_will_engage),
                        # A SEPARATE drafter that stays on the GPU: a second model,
                        # whose weights and KV llama.cpp distributes like any other.
                        # None once the drafter is CPU-offloaded (_mtp_draft_for_budget
                        # is nulled there), which is the case that really is off-GPU.
                        "separate_draft_on_gpu": bool(_mtp_will_engage and _mtp_draft_for_budget),
                        # The planner reads the real tensor table, not a bucket
                        # total, so it can spill the MINIMUM set of blocks.
                        "model_path": model_path,
                        "n_ctx": effective_ctx,
                        # The slot count the KV and recurrent state were PRICED at.
                        # A pass-through --parallel is appended after Unsloth's own
                        # and wins, and both caches scale with it.
                        "n_parallel": int(n_parallel or 1),
                        # Relative cache size per layer: only the ratios are used
                        # (the planner scales them to kv_cache_bytes), but they say
                        # WHERE the big caches land, which the total cannot. Same
                        # launch settings kv_cache_bytes was priced at, so the
                        # vector describes the same cache geometry.
                        "kv_layer_weights": self._kv_layer_weights(
                            effective_ctx,
                            swa_full = swa_full,
                            n_parallel = n_parallel,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            flash_attn = planned_flash_attn,
                            cache_type_kv = cache_type_kv,
                        ),
                        # An iGPU or APU reports host RAM as VRAM: crediting it and
                        # then "spilling" into that pool counts one memory twice.
                        "shared_gpu_ids": set(_shared_gpu_ids or ()),
                    }
                    mmproj_note = (
                        f"mmproj: {mmproj_size / (1024**3):.1f} GB, " if mmproj_size else ""
                    )
                    logger.info(
                        f"GGUF size: {gguf_size / (1024**3):.1f} GB, "
                        f"{mmproj_note}"
                        f"est. KV cache: {kv_cache_bytes / (1024**3):.1f} GB, "
                        f"{_mtp_note}"
                        f"context: {effective_ctx}, "
                        # --fit flag state, not "does it fit": off means this subset provably fits.
                        f"GPUs free: {gpus}, selected: {gpu_indices}, --fit: {'on' if use_fit else 'off'}"
                    )
                    # The planner ran to completion over a real device list and
                    # left --fit on, i.e. it could not prove the model fits. THAT
                    # is a partial-placement verdict. Set last, so any early
                    # return or raise above leaves it False.
                    _placement_verdict_partial = bool(_detected_gpus) and bool(use_fit)

                    # Load mode, from the same numbers the placement just used: mmap
                    # exists to demand-page a footprint the machine cannot hold, so a
                    # load that fits wants "none" and anything else keeps "auto". See
                    # _fit_derived_load_mode. `gpus`, not `_detected_gpus`: the arch gate
                    # empties that one on "--device none", and crediting VRAM the child
                    # never reaches would claim a fit that has to come from RAM.
                    _fit_devices = max(1, len(gpu_indices or ()) or len(gpus))
                    # A CPU-pinned drafter is out of the VRAM budget above but still
                    # resident in host RAM, so the footprint carries it. None means it
                    # cannot be priced -> abstain, like the other unreadable terms.
                    _cpu_draft_fit_bytes = self._cpu_resident_draft_bytes(
                        effective_ctx,
                        drafter_path = _cpu_draft_path,
                        draft_cache_type_k = _mtp_draft_ck,
                        draft_cache_type_v = _mtp_draft_cv,
                        n_parallel = n_parallel,
                        swa_full = swa_full,
                        kv_unified = planned_kv_unified,
                        n_ubatch = _effective_ubatch,
                        flash_attn = planned_flash_attn,
                    )
                    # The extras and env as the child really gets them: a gpu_ids pin
                    # drops the device flags AND their env twins, so classifying on
                    # either would void the VRAM term for a "--device none" the launch
                    # strips. Unpinned, the child inherits LLAMA_ARG_DEVICE verbatim.
                    _fit_extras = (
                        self._strip_device_extra_args(extra_args)
                        if gpu_ids is not None
                        else extra_args
                    )
                    _fit_env = dict(os.environ)
                    if gpu_memory_mode == "manual":
                        self._clear_manual_placement_env(_fit_env)
                    if gpu_ids is not None:
                        self._clear_device_placement_env(_fit_env)
                    # What the placement branch below will emit, so the effective
                    # (last-wins) fitter state is readable before the final argv exists.
                    # Every reachable branch is fixed by use_fit.
                    _fitter_runs = fit_is_effectively_on(
                        ["--fit", "on" if use_fit else "off", *(_fit_extras or [])],
                        _fit_env,
                    )
                    # _ctx_integrity_flags emits --fit-target only while use_fit, so a
                    # fitter the EXTRAS turned back on keeps llama.cpp's own 1024 MiB
                    # default; a pass-through --fit-target wins over either (below).
                    # A drafter the extras SPLIT between card and host with a fixed
                    # positive -ngld: _cpu_draft_path is None there (that predicate is
                    # the whole-drafter question), so mtp_bytes carries the drafter WHOLE
                    # while llama.cpp keeps the layers past the count, and their KV, in
                    # host RAM. Nothing here says which slice stays on the card, so this
                    # is the "engaged but unsized" case the fit abstains on.
                    _draft_split_across_host = bool(
                        _mtp_draft_for_budget
                        and _draft_is_split_across_host(
                            _fit_extras,
                            _fit_env,
                            n_draft_layers = getattr(
                                self._draft_backend_for(_mtp_draft_for_budget),
                                "_n_layers",
                                None,
                            ),
                        )
                    )
                    _fit_margin_mib = (
                        max(
                            self._fit_target_margin_mib(
                                auto_fit = (gpu_memory_mode == "manual" and gpu_layers < 0),
                                fit_target_delta_mib = _fit_target_delta_mib if use_fit else 0.0,
                                supports_fit_target = use_fit
                                and bool(server_caps.get("supports_fit_target")),
                            ),
                            fit_target_margin_in(_fit_extras, _fit_env) or 0.0,
                        )
                        if _fitter_runs
                        else 0.0
                    )
                    # A projector Unsloth never resolved but the child loads anyway:
                    # LLAMA_ARG_MMPROJ / _URL are read before argv and only the vision
                    # switch and the paravirtual pin clear them, while model_size carries
                    # none of those bytes. A URL names a download that has not happened
                    # (and outranks even the --mmproj this launch emits), and an
                    # unreadable path cannot be sized, so both abstain.
                    _fit_env_mmproj_scrubbed = bool(
                        _pv_mmproj_unpinnable or _paravirtual_cpu_forced
                    )
                    _fit_env_mmproj = (
                        ""
                        if (
                            launch_mmproj_path
                            or _fit_env_mmproj_scrubbed
                            or (
                                disable_vision
                                # The scrub's own audio-only reprieve: that projector
                                # survives the switch, so it is loaded.
                                and not _mmproj_env_is_audio_only(_fit_env.get("LLAMA_ARG_MMPROJ"))
                            )
                        )
                        else (_fit_env.get("LLAMA_ARG_MMPROJ") or "").strip()
                    )
                    _fit_env_mmproj_url = (
                        ""
                        if (_fit_env_mmproj_scrubbed or disable_vision)
                        else (_fit_env.get("LLAMA_ARG_MMPROJ_URL") or "").strip()
                    )
                    _fit_env_mmproj_bytes = self._mmproj_vram_bytes(_fit_env_mmproj or None)
                    _fit_env_mmproj_unsized = bool(_fit_env_mmproj_url) or (
                        bool(_fit_env_mmproj) and _fit_env_mmproj_bytes <= 0
                    )
                    # Host-resident when the resolved offload says CPU, the same split
                    # the resolved projector gets.
                    _fit_env_mmproj_on_host = (
                        _resolved_mmproj_offload(_fit_extras, _fit_env) is False
                    )
                    _fit_model_size = model_size
                    if _fit_env_mmproj_unsized:
                        # Same abstain the other unreadable terms take.
                        _fit_model_size = None
                    elif _fit_model_size and not _fit_env_mmproj_on_host:
                        _fit_model_size += _fit_env_mmproj_bytes
                    _fit_soft_overhead = _soft_overhead + self._inherited_mmproj_soft_overhead(
                        _fit_env_mmproj_bytes,
                        on_host = _fit_env_mmproj_on_host,
                    )
                    # The same projector, handed to the spill planner. Its
                    # extra_gpu_bytes carries the RESOLVED one only, so without this
                    # an inherited LLAMA_ARG_MMPROJ is VRAM no term in the plan has
                    # paid for -- and a plan is pinned with --fit off, so llama.cpp's
                    # fitter never gets to absorb it. Weights plus the runtime
                    # allowance, exactly what _fit_model_size and _fit_soft_overhead
                    # just charged, and the same abstain when it cannot be sized.
                    _spill_inputs["env_mmproj_unsized"] = _fit_env_mmproj_unsized
                    _spill_inputs["env_mmproj_bytes"] = (
                        0
                        if _fit_env_mmproj_on_host
                        else _fit_env_mmproj_bytes
                        + self._inherited_mmproj_soft_overhead(_fit_env_mmproj_bytes, on_host = False)
                    )
                    _fit_load_mode = self._fit_derived_load_mode(
                        model_size = _fit_model_size,
                        mmproj_pinned_bytes = _mmproj_pinned_bytes
                        + (_fit_env_mmproj_bytes if _fit_env_mmproj_on_host else 0),
                        # Re-read WITH the SWA snapshots --ctx-checkpoints allocates;
                        # the closure leaves them at 0 for the placement paths, which
                        # price them by their own route.
                        kv_cache_bytes = _kv_bytes(effective_ctx, _effective_ctx_checkpoints),
                        kv_sized = self._can_estimate_kv(),
                        mtp_bytes = _mtp_bytes(effective_ctx),
                        # _flat_mtp_engages whole: its other arm, _mtp_kv_unsized,
                        # prices weights but NO draft KV, and the placement covers that
                        # gap with a flat cushion this footprint has no term for --
                        # the "engaged but unsized" case the predicate abstains on.
                        mtp_unsized = bool(
                            _flat_mtp_engages
                            or _cpu_draft_fit_bytes is None
                            or _draft_split_across_host
                        ),
                        # Host-only, not pooled: -ngld 0 puts the drafter in RAM, which
                        # free VRAM cannot pay for.
                        host_only_bytes = _cpu_draft_fit_bytes or 0,
                        # One lump on the layer path, where the graph buffer is
                        # allocated once. A tensor split replicates it on every selected
                        # device, so pricing one LAYER-mode buffer there understates a
                        # multi-GPU load by GiBs. pipeline_overhead_bytes below is a flat
                        # per-device constant and cannot cover it.
                        compute_buffer_flat = (
                            _fit_devices * _compute_buffer_tensor
                            if _tp_planned
                            else _compute_buffer_pipeline
                        ),
                        compute_buffer_ctx = _cc_bytes(effective_ctx, _fit_devices),
                        # Ungated, like _subset_model_size: the per-device CUDA context
                        # and scratch are there whether or not llama.cpp keeps the
                        # pipeline (_cc_bytes is the term that gates on it).
                        pipeline_overhead_bytes = (
                            max(0, _fit_devices - 1) * _pipeline_overhead_bytes
                        ),
                        soft_overhead = _fit_soft_overhead,
                        gpus = gpus,
                        gpu_indices = gpu_indices,
                        shared_gpu_ids = _shared_gpu_ids,
                        # A running fitter keeps --fit-target free per device, so that
                        # margin is not VRAM this fit may spend. Zero only when the
                        # fitter is provably off; see _fitter_runs above.
                        fit_margin_mib = _fit_margin_mib,
                        is_vulkan_backend = is_vulkan_backend,
                        # Never stripped, and appended last, so they beat this
                        # launch's own -ngl.
                        extra_args = _fit_extras,
                        env = _fit_env,
                    )
                except Exception as e:
                    logger.warning(f"GPU selection failed ({e}), using --fit on")
                    gpu_indices, use_fit = None, True
                    # Not a verdict: this arm never priced anything. Explicit, so
                    # the flag cannot survive from a previous load.
                    _placement_verdict_partial = False
                    # Same reasoning: an unpriced load keeps llama.cpp's default.
                    _fit_load_mode = None
                    # And a half-built snapshot is not a price either: the throw can
                    # land after the dict exists but before the later terms are added
                    # to it, which would plan against a footprint missing them.
                    _spill_inputs = None
                    tp_tensor_split = None
                    effective_ctx = requested_ctx  # fall back to original

                # A hand-set context unified memory cannot hold. Raised here so the handler
                # above cannot turn it back into the launch it refuses, and ahead of the
                # Vulkan and APU checks, which describe hardware this branch has ruled out.
                if _metal_ctx_refusal:
                    raise RuntimeError(_metal_ctx_refusal)

                # An unenumerated explicit Vulkan ordinal can't be pinned; fail loudly
                # instead of fitting onto an unselected device. Clear the raw selection
                # the early state-publish recorded so it never leaks into gpu_ids (#7239).
                if _vulkan_explicit_unmatched:
                    self._gpu_ids = None
                    self._requested_gpu_ids = None
                    raise ValueError(
                        f"Requested Vulkan GPU ordinal(s) {_vulkan_requested_ids} not "
                        f"present. Available Vulkan devices: {_vulkan_available_ordinals}."
                    )

                # GPU picker: when no narrower subset was chosen (manual, or
                # a failed/file-size selection), pin the whole picked set so the
                # model can't spill onto an unpicked GPU.
                if gpu_ids and gpu_indices is None:
                    gpu_indices = sorted(gpu_ids)
                # Auto Vulkan fit prefers discrete GPUs and keeps that pool pinned.
                elif (
                    is_vulkan_backend
                    and gpu_memory_mode != "manual"
                    and use_fit
                    and gpu_indices is None
                    and _detected_gpus
                ):
                    gpu_indices = sorted(idx for idx, _free in _detected_gpus)

                # Status reports the explicit subset the launch actually uses,
                # while reload dedupe compares requested_gpu_ids so repeating a
                # wider request that fit narrowed does not restart the server.
                # A forced-CPU launch carries --device none, so it pins no GPU at all:
                # echoing the request as effective would report devices the runtime never
                # touched, and clearing an ineffective pick would then reload a CPU server
                # that is already in the target state. requested_gpu_ids still holds the
                # pick, so repeating it keeps matching.
                if gpu_ids and not _paravirtual_cpu_forced:
                    effective_pin = gpu_indices if gpu_indices is not None else gpu_ids
                    self._gpu_ids = sorted(int(idx) for idx in effective_pin)
                else:
                    self._gpu_ids = None

                # Did the APU preflight below find a shortfall. Carried to the launch
                # site, which is where `cmd` and `env` first exist and so the only place
                # the pageable-load override can be applied. Without it an oversized
                # unmapped load on an APU is never remapped: _shared_gpu_ids is
                # populated for Vulkan alone, so the discrete guard downstream credits
                # the APU's reported GPU pool against the weights, finds no spill and
                # abstains, while the RAM this launch actually loads into cannot hold
                # them. "none" and "mlock" do not mmap, so that is an OOM kill.
                _apu_ram_oversized = False
                # The two shortfall notices this load recorded, kept verbatim (and
                # un-amended) so the text-only fallback further down can re-price them
                # once it drops the CPU-pinned projector whose bytes they charged. Both
                # are re-stated by the arch-crash retry, which starts its own warning
                # scope, so what these hold is always the pair behind the notice the
                # route would hand back right now.
                _apu_ram_msg: Optional[str] = None
                _host_ram_msg: Optional[str] = None
                # The RAM figure those notices were priced against, kept with them.
                _apu_avail_mib: Optional[int] = None

                # Unified-memory APUs load weights into system RAM (under WSL the VM
                # cap, not the ROCm-reported VRAM, is the real ceiling); refuse an
                # oversize load the OS would otherwise kill mid-flight. Base model
                # only: an optional MTP drafter is dropped by the MTP-drop fallback.
                # CUDA/ROCm ids only; a Vulkan build's gpu_indices are ggml ordinals.
                if (
                    model_size is not None
                    and not is_vulkan_backend
                    and self._amd_apu_wants_unified_memory(gpu_indices)
                ):
                    # Read ONCE and kept, because the text-only fallback re-prices this
                    # same decision much later, with the weights already resident. A
                    # second live reading there would be the pool MINUS the model the
                    # reprice is asking about, which double-charges it.
                    _apu_avail_mib = self._available_system_memory_mib()
                    _ram_msg = self._apu_ram_shortfall_message(
                        # A pinned projector left model_size but not system RAM, and
                        # this guard exists to stop an oversize load being OOM-killed
                        # mid-read, so it has to weigh the projector either way.
                        model_size + _mmproj_pinned_bytes,
                        _apu_avail_mib,
                    )
                    # gpu_indices is None for a launch nothing pinned, so the guard
                    # priced every visible card, including an APU the gate is about to
                    # drop and whose shared pool the narrowed child never touches.
                    # Re-ask for the set the child will actually see. Warned branch
                    # only, so a passing launch pays for no probe; an empty answer
                    # keeps the warning.
                    if _ram_msg and gpu_indices is None and not gpu_ids:
                        _gated_pin = self._arch_gate_survivors(binary)
                        if _gated_pin and not self._amd_apu_wants_unified_memory(_gated_pin):
                            logger.info(
                                "Skipping the APU RAM warning: the arch gate pins "
                                "this launch to discrete GPU(s) %s.",
                                _gated_pin,
                            )
                            _ram_msg = None
                    # The condition, not the message: read after the arch-gate skip
                    # above, so a launch the gate moves onto discrete cards is not
                    # remapped for a shortfall it no longer has. Independent of
                    # UNSLOTH_ALLOW_HOST_OFFLOAD, which this preflight never consulted.
                    _apu_ram_oversized = bool(_ram_msg)
                    # ...and the MESSAGE is the one thing the deprecated opt-out may
                    # take away. _apu_ram_shortfall_message prices RAM and never reads
                    # it, so without this UNSLOTH_ALLOW_HOST_OFFLOAD silenced the
                    # discrete guard next door and left the APU advisory in
                    # memory_warning, against a contract that is only ever "silences
                    # the warning". Read AFTER the verdict above, so the rewrite the
                    # verdict drives is untouched.
                    if _ram_msg and self._host_offload_warning_opted_out():
                        logger.info(
                            "UNSLOTH_ALLOW_HOST_OFFLOAD set: not recording the APU RAM advisory."
                        )
                        _ram_msg = None
                    _apu_ram_msg = _ram_msg
                    self._record_load_warning(_ram_msg)

                # Audio input straight from the mmproj (clip.has_audio_encoder),
                # independent of token names. A projector passed only via
                # LLAMA_ARG_MMPROJ misses launch_mmproj_path, so probe that too,
                # but never one the unpinnable guard just dropped.
                self._mmproj_has_audio = False
                self._mmproj_accepts_image = True
                # ...and never one the vision switch is about to scrub out of the
                # child environment either. Reading it would record an audio encoder
                # the launched server does not have, and _apply_detected_audio turns
                # that into has_audio_input, so the composer would offer attachments
                # the server cannot process.
                #
                # Unless the switch is going to keep it: an inherited audio-only
                # encoder survives the scrub below, so the server really does have it
                # and the same reasoning says to record it. One predicate for both, off
                # the same inherited value, so the probe cannot describe a child the
                # scrub did not build.
                # ...and not on a virtualised Metal device, whose own scrub below
                # takes BOTH projector vars unconditionally. It runs after the switch's
                # block, so a file kept there is gone by launch, and a probe that still
                # described it would report an audio encoder the child does not have.
                _dv_env_mmproj_kept = (
                    disable_vision
                    and not _paravirtual_cpu_forced
                    and _mmproj_env_is_audio_only(os.environ.get("LLAMA_ARG_MMPROJ"))
                )
                _mmproj_probe = launch_mmproj_path or (
                    ""
                    if (_pv_mmproj_unpinnable or (disable_vision and not _dv_env_mmproj_kept))
                    else (os.environ.get("LLAMA_ARG_MMPROJ") or "")
                )
                if launch_mmproj_path or os.path.isfile(_mmproj_probe):
                    try:
                        from utils.models.gguf_metadata import mmproj_capabilities

                        has_audio, accepts_image = mmproj_capabilities(_mmproj_probe)
                        self._mmproj_has_audio = has_audio
                        self._mmproj_accepts_image = accepts_image
                    except Exception as e:
                        logger.debug(f"mmproj capability read failed: {e}")

                auto_fit = gpu_memory_mode == "manual" and gpu_layers < 0
                # What the user asked for, kept whole. The strip below is a launch
                # decision, but _requested_extra_args is the comparator a later Apply
                # is matched against: storing the stripped list there made an
                # unchanged request compare unequal and reload the model.
                _extra_args_as_requested = list(extra_args) if extra_args is not None else None
                if self._metal_drops_zero_ctx_override(ctx_override, _caller_owns_budget):
                    extra_args = strip_context_only(extra_args)
                    logger.warning(
                        "Dropping the pass-through zero context: on Metal it pins the "
                        "model's native length and disables --fit."
                    )
                _metal_floor = self._metal_zero_ctx_floor(
                    effective_ctx,
                    auto_fit,
                    _caller_owns_budget,
                    self._context_length,
                    max_available_ctx,
                    # Whether the child's own fitter runs at all, which decides both the
                    # Auto-layers exemption and how far the floor may reach. Every branch
                    # that can reach the floor emits "--fit on" or nothing (llama.cpp
                    # defaults it on); the one branch that emits "--fit off" is manual
                    # with a fixed layer count, which _caller_owns_budget exempts. So the
                    # only ways off here are the user's own, and both are read: extras
                    # land after Unsloth's flag and win, and LLAMA_ARG_FIT is applied
                    # before argv when argv sets nothing.
                    fitter_runs = fit_is_effectively_on(extra_args, os.environ),
                )
                if _metal_floor:
                    effective_ctx = _metal_floor
                    # Replace, do not max(). On the exception path max_available_ctx
                    # still holds the native length its initialiser put there, which
                    # no cap ever said fits. Keeping the larger publishes native as
                    # max_context_length, which the UI reads as the largest context
                    # that fits, advertising this very failure as safe. The floor is
                    # already bounded by any real ceiling the cap did compute.
                    max_available_ctx = _metal_floor
                    logger.warning(
                        "No GPU is enumerated on Metal and the context cap did not "
                        f"run, so starting at {effective_ctx} rather than the model's "
                        "native length."
                    )

                # Gated like every other optional flag, but failing OPEN: these
                # are emitted on every launch, so an unreadable --help keeps
                # today's command and only a build that positively lacks one
                # drops it. Harmless for the pinned prebuilt, which has all
                # three; the case this covers is a stale or user-supplied
                # LLAMA_SERVER_PATH, where an unknown argument is an immediate
                # exit rather than a degraded launch.
                _caps = _launch_caps(binary)
                cmd = [
                    binary,
                    "-m",
                    model_path,
                    "--port",
                    str(self._port),
                    "--parallel",
                    str(n_parallel),
                ]
                # Force flash attention for speed. Two separate answers: whether
                # the build has the flag at all (predates flash attention, or a
                # wrapper that never exposed it), and whether its declaration
                # takes a value -- older builds take -fa as a bare boolean and
                # read a following "on" as a stray positional.
                if _caps.get("supports_flash_attn", True):
                    cmd.append("--flash-attn")
                    if _caps.get("flash_attn_takes_value", True):
                        cmd.append("on")
                else:
                    # Only ever reached on an authoritative --help that has no
                    # flash attention to lose, so there is no speed to give up.
                    _flash_attn_known_off = True
                # Error out at n_ctx instead of silently rotating the KV cache; frontend catches it and points the user at "Context Length".
                if _caps.get("supports_no_context_shift", True):
                    cmd.append("--no-context-shift")
                # A positive context is always passed (in auto-fit, --fit then
                # optimizes the gpu-layer offload around it). When auto-fit has
                # no explicit context, omit -c so --fit sizes it to fit VRAM:
                # "-c 0" would instead pin the FULL native context (llama.cpp's
                # -c handler sets fit_params_min_ctx = UINT32_MAX on value 0,
                # disabling --fit's reduction). See gpu_memory_mode.
                if effective_ctx > 0:
                    cmd.extend(["-c", str(effective_ctx)])
                elif not auto_fit:
                    cmd.extend(["-c", "0"])

                # llama-server 501s on /v1/embeddings without this; pooling stays model-default.
                if self.is_embedding_gguf:
                    cmd.append("--embedding")

                # emitted before user extras so a pass-through -b / -ub still last-wins-overrides
                if n_batch is not None:
                    # Two separate aborts, both reachable from the picker since the input
                    # clamps into BATCH_MIN = 1 rather than rejecting:
                    #   -b < --parallel  -> GGML_ASSERT(n_outputs_max <= cparams.n_outputs_max)
                    #   -b 1 (any slots) -> GGML_ASSERT(n_tokens_all <= cparams.n_batch)
                    # Measured: b1/p1 and b1/p2 abort, b2/p1 and b2/p2 load, b4/p8 aborts,
                    # b8/p8 loads. So the floor is max(slots, 2), not slots alone. The
                    # bounds are per-field and cannot express it, so raise here instead of
                    # failing the load.
                    _emit_batch = _emitted_n_batch(n_batch, n_parallel)
                    if _emit_batch != n_batch:
                        logger.warning(
                            "Raising --batch-size from %s to %s: llama-server aborts below "
                            "2 and below the %s parallel slot(s) it serves.",
                            n_batch,
                            _emit_batch,
                            n_parallel,
                        )
                    cmd.extend(["--batch-size", str(_emit_batch)])
                if n_ubatch is not None:
                    cmd.extend(["--ubatch-size", str(n_ubatch)])

                server_caps = _launch_caps(binary)

                # Before the extras, like the batch pair: a hand-typed flag still
                # last-wins over the control. Each is gated on the capability
                # probe, because a build that predates the flag exits on it.
                if ctx_checkpoints is not None:
                    _ctxcp_flag = server_caps.get("ctx_checkpoints_flag")
                    if _ctxcp_flag:
                        cmd.extend([str(_ctxcp_flag), str(int(ctx_checkpoints))])
                    else:
                        logger.info(
                            "llama-server has no --ctx-checkpoints; skipping the requested %s.",
                            ctx_checkpoints,
                        )
                if cache_ram is not None:
                    if server_caps.get("supports_cache_ram"):
                        cmd.extend(["--cache-ram", str(int(cache_ram))])
                    else:
                        logger.info(
                            "llama-server has no --cache-ram; skipping the requested %s MiB.",
                            cache_ram,
                        )

                # Report a clean public model id (matching GET /v1/models) rather
                # than the raw -m path in llama-server's own /v1/models and the
                # "model" field of its chat/completions responses.
                from core.inference.model_ids import public_model_id

                _alias = public_model_id(self._model_identifier or model_path)
                if _alias:
                    cmd.extend(["--alias", _alias])

                fully_gpu_offloaded = False
                # Set when a positional --tensor-split is emitted, so the env block
                # can pin CUDA to PCI order even without a GPU subset (see below).
                manual_tensor_split_emitted = False
                if gpu_memory_mode == "manual" and gpu_layers >= 0:
                    # Pin the user's layer count and disable auto-fit. --fit off
                    # also means _ctx_integrity_flags must not add --fit-ctx.
                    use_fit = False
                    cmd.extend(["--gpu-layers", str(gpu_layers), "--fit", "off"])
                    # Keep the first n_cpu_moe MoE layers' experts on CPU.
                    moe_flag = self._resolve_cpu_moe_flag(
                        n_cpu_moe,
                        self.n_moe_layers,
                        self._leading_dense_block_count or 0,
                    )
                    if moe_flag is not None:
                        cmd.extend(["--n-cpu-moe", str(moe_flag)])
                    elif n_cpu_moe:
                        # Requested on a dense model: nothing was emitted, so
                        # don't report a count llama-server never received.
                        self._n_cpu_moe = 0
                    # Distribute the model across GPUs by the user's per-GPU shares
                    # (--tensor-split). Works with layer split and tensor
                    # parallelism; --fit off means no fit/tensor abort. Only emit
                    # when >1 GPU is in use AND the list length matches that count:
                    # the field is hidden (not cleared) when the picker narrows to
                    # one, and a direct caller can send a stale ratio for a different
                    # GPU set. Unsloth drops any mismatch to the free-VRAM default
                    # (llama.cpp would silently zero-pad a short list, or abort past
                    # its 16-device cap).
                    _split_gpus = self._effective_gpu_count(gpu_indices)
                    if tensor_split and _split_gpus > 1:
                        # An all-zero/non-positive sanitized split assigns nothing
                        # anywhere, so fall through to the free-VRAM default in
                        # that case.
                        _sanitized_split = self._sanitize_tensor_split(tensor_split)
                        _split_total = sum(_sanitized_split)
                        if len(_sanitized_split) == _split_gpus and _split_total > 0:
                            cmd.extend(
                                ["--tensor-split", ",".join(f"{x:g}" for x in _sanitized_split)]
                            )
                            self._tensor_split = _sanitized_split
                            manual_tensor_split_emitted = True
                        else:
                            logger.warning(
                                "Dropping manual --tensor-split (%d entries for "
                                "%d GPUs, sanitized total %s); llama.cpp's "
                                "free-VRAM split applies instead",
                                len(tensor_split),
                                _split_gpus,
                                _split_total,
                            )
                            self._tensor_split = None
                    elif tensor_split:
                        # Single effective GPU: the split is never emitted, so
                        # don't report it as active via /status and /load.
                        self._tensor_split = None
                elif use_fit:
                    # Unsloth could not prove a fit, so llama.cpp's fitter takes the
                    # placement. Its dense path fills "back to front with dense
                    # layers" (common/fit.cpp:402), i.e. WHOLE layers, and a layer
                    # takes its KV cache with it because the cache buffer comes
                    # from model.dev_layer(il) (llama-kv-cache.cpp:215). Spilling
                    # weight TENSORS instead leaves the cache resident: measured on
                    # a 27B at 128K, 13.63 t/s resident against 1.03 t/s evicted.
                    _spill = self._planned_tensor_spill(
                        _spill_inputs,
                        extra_args = extra_args,
                        env = os.environ,
                    )
                    # NOT `if _spill:` -- Plan is a dataclass, so every instance is
                    # truthy, including ones saying it could not place this at all.
                    _spill_flags = self._spill_plan_flags_for(_spill)
                    if _spill_flags:
                        self._spill_plan_flags = _spill_flags
                        cmd.extend(self._spill_plan_flags)
                        logger.info(
                            "Tensor spill: %s (resident %.1f GB, host %.1f GB)",
                            " ".join(_spill.ot_patterns),
                            _spill.vram_bytes / (1024**3),
                            _spill.host_bytes / (1024**3),
                        )
                    else:
                        cmd.extend(["--fit", "on"])
                elif gpu_indices is not None:
                    # Fits on selected GPU(s) -- force all layers on GPU. --fit off is
                    # required: without it llama.cpp's default --fit on second-guesses
                    # and offloads ~1 GB at --parallel 4 even though the model fits.
                    cmd.extend(["-ngl", "-1", "--fit", "off"])
                    fully_gpu_offloaded = True

                # Expose Prometheus /metrics for the engine-stats logger, only
                # when the binary advertises it (older/custom binaries may not).
                if server_caps.get("supports_metrics"):
                    cmd.append("--metrics")
                self._slot_save_dir = None
                self._slot_save_binary = None
                self._prompt_cache_disabled = False
                if server_caps.get("supports_slot_save"):
                    try:
                        from utils.paths.storage_roots import (  # noqa: WPS433
                            llama_slot_cache_root,
                        )

                        slot_dir = llama_slot_cache_root()
                        slot_dir.mkdir(parents = True, exist_ok = True)
                        # Saved KV encodes chat content; keep it from other local users.
                        with contextlib.suppress(OSError):
                            os.chmod(slot_dir, 0o700)
                        slot_path = str(slot_dir)
                        # llama.cpp's fs_is_directory() constructs a narrow
                        # std::filesystem::path on Windows, so an existing UTF-8
                        # path such as C:\Users\Егор is rejected as missing.
                        # Slot persistence is optional; keep model loading available
                        # until the managed runtime carries the upstream UTF-8 fix.
                        if sys.platform == "win32" and not slot_path.isascii():
                            logger.warning(
                                "Disabling llama.cpp slot persistence because its "
                                "Windows path contains non-ASCII characters: %s",
                                slot_path,
                            )
                        else:
                            cmd.extend(["--slot-save-path", slot_path])
                            self._slot_save_dir = slot_path
                            self._slot_save_binary = (binary, Path(binary).stat().st_mtime_ns)
                    except OSError:
                        self._slot_save_dir = None
                        self._slot_save_binary = None
                _integrity_flags = self._ctx_integrity_flags(
                    n_parallel,
                    use_fit,
                    auto_fit,
                    requested_ctx,
                    effective_ctx,
                    server_caps,
                    fit_target_delta_mib = _fit_target_delta_mib,
                )
                # From the flags, not the inputs: --fit off, an older server without
                # the capability and a budget at the default all leave the child
                # unpriced, and each is decided inside that call.
                _fit_target_priced = "--fit-target" in _integrity_flags
                cmd.extend(_integrity_flags)
                offload_overridden = _extra_args_set_any_flag(
                    extra_args, _GPU_OFFLOAD_OVERRIDE_FLAGS
                )
                threads_overridden = _extra_args_set_any_flag(extra_args, _THREAD_OVERRIDE_FLAGS)
                full_offload_tuning_active = fully_gpu_offloaded and not offload_overridden
                # The CPU replay must undo what this launch pins for an absent GPU;
                # a user's own --threads still wins.
                _drop_full_offload_threads = (
                    sys.platform == "win32"
                    and full_offload_tuning_active
                    and not threads_overridden
                )

                # Thread count: an unset --threads makes llama.cpp pick physical
                # cores (common_cpu_get_num_math), but an explicit --threads -1
                # resolves to hardware_concurrency() (every hyperthread), which
                # contends on the memory bus and slows CPU / hybrid decode. So
                # omit the flag when unset and only pin it for an explicit
                # override or the Windows full-offload OpenMP cap. Pass-through
                # thread flags in extra_args still win (appended last). #5692
                if (
                    sys.platform == "win32"
                    and full_offload_tuning_active
                    and not threads_overridden
                ):
                    cmd.extend(["--threads", "2"])
                elif n_threads is not None and n_threads > 0:
                    cmd.extend(["--threads", str(n_threads)])

                # Enable Jinja chat template rendering
                if _caps.get("supports_jinja", True):
                    cmd.extend(["--jinja"])

                # KV cache data type
                _valid_cache_types = _VALID_CACHE_TYPES
                # Normalize like the budget does (_planned_main_cache_types): a
                # case-sensitive match drops "Q8_0", emitting no flag, so llama.cpp
                # runs f16 while the estimate priced q8_0. Emit the normalized
                # spelling; kv_cache_type_from_str is case-sensitive.
                cache_type_kv = cache_type_kv.strip().lower() if cache_type_kv else cache_type_kv
                if (
                    cache_type_kv
                    and cache_type_kv in _valid_cache_types
                    and not _cache_type_from_env
                ):
                    cmd.extend(
                        [
                            "--cache-type-k",
                            cache_type_kv,
                            "--cache-type-v",
                            cache_type_kv,
                        ]
                    )
                    self._cache_type_kv = cache_type_kv
                    logger.info(f"KV cache type: {cache_type_kv}")
                else:
                    # An env-only type is left inherited (untouched) so an
                    # asymmetric K/V env reaches the child as set.
                    self._cache_type_kv = None

                # Tensor parallelism: split the model across GPUs by tensor
                # rather than by layer. The UI only offers it on multi-GPU; a
                # direct single-GPU caller is redundant (supported archs no-op,
                # unsupported ones abort and the /load path retries layer split).
                # Default (layer split) is left implicit by omitting the flag.
                # See llama.cpp --split-mode.
                if tensor_parallel:
                    cmd.extend(["--split-mode", "tensor"])
                    if tp_tensor_split and len(tp_tensor_split) > 1:
                        cmd.extend(
                            [
                                "--tensor-split",
                                ",".join(str(int(x)) for x in tp_tensor_split),
                            ]
                        )
                    self._tensor_parallel = True
                    self._layer_preserves_tensor_intent = False
                    logger.info(
                        "Tensor parallelism: --split-mode tensor, --tensor-split %s",
                        tp_tensor_split,
                    )
                else:
                    self._tensor_parallel = False
                    # > 1 only when a tensor request was downgraded but kept multi-GPU.
                    self._layer_preserves_tensor_intent = _layer_min_gpus > 1

                # Speculative decoding. See _build_speculative_flags for the
                # mode resolution, benchmarks, and llama.cpp references.
                _vulkan_pin_ids = gpu_indices if gpu_indices is not None else (gpu_ids or None)
                _draft_device = _extra_args_main_device(extra_args) if gpu_ids is None else None
                if _draft_device is None and is_vulkan_backend and _vulkan_pin_ids:
                    _draft_device = ",".join(f"Vulkan{i}" for i in _vulkan_pin_ids)
                launch_mtp_draft_path = self._resolve_launch_mtp_path(
                    mtp_draft_path = mtp_draft_path,
                    drafter_label = _DRAFTER_DISPLAY_LABELS.get(_spec_canon, "MTP"),
                )
                _pv_suppressed_draft_path: Optional[str] = None
                _pv_suppressed_spec_extra_args: Optional[List[str]] = None
                # Same shape as the projector drop above: the CPU pin below needs a
                # draft-layer flag from the probe, and without one the drafter keeps its
                # automatic placement on the virtualised device. Unlike the projector
                # this is throughput, not correctness -- a token is emitted only when the
                # CPU-side target samples it itself (common_sampler_sample_and_accept_n
                # pushes the target's own draw and stops at the first mismatch), so a
                # corrupt drafter can only get its proposals rejected, costing a forward
                # pass per step for nothing. So drop it, from both sources: Unsloth's
                # resolved drafter and a user/env one in the extras. The rest of the spec
                # group goes with it, since a --spec-type needing a draft model
                # (draft-simple, eagle3) aborts llama-server once the model is gone;
                # _build_speculative_flags re-derives the drafter-free modes below. A
                # user who already pinned the drafter (-ngld 0 / --spec-draft-device cpu)
                # keeps it; the probe only decides whether Unsloth can emit the flag.
                # And as with the projector, --gpu-layers-draft has existed since 2023,
                # so a missing flag means the probe failed: on an unanswered probe pin
                # with the legacy spelling rather than drop.
                # Keyed on the drafter the launch really loads, not one that merely
                # exists: a user-owned --spec-type returns early from
                # _build_speculative_flags, so Unsloth's resolved sibling never becomes
                # --model-draft and keying on it would strip a drafter-free mode
                # (--spec-type ngram-mod and its knobs) for a drafter that never
                # launches. The inherited env counts only where it survives to the child
                # (the launch scrubs LLAMA_ARG_SPEC_DRAFT_* unless the extras own
                # --spec-type), or os.environ would drop a drafter that never loads and
                # take the caller's spec tuning with it.
                _pv_draft_unpinnable = bool(
                    _paravirtual_cpu_forced
                    and not _paravirtual_draft_ngl_flag(server_caps)
                    and (
                        _extra_args_mtp_draft_path(extra_args, env = _child_spec_env(extra_args))
                        or (launch_mtp_draft_path and not _extra_args_set_spec_type(extra_args))
                    )
                    and not _extra_args_draft_offloaded_to_cpu(extra_args)
                )
                if _pv_draft_unpinnable:
                    logger.warning(
                        "Dropping the speculative drafter for this session: this "
                        "Mac's Metal device is virtualised and this llama-server "
                        "build advertises no draft-layer flag, so the drafter would "
                        "keep running on the device whose output is corrupt. Output "
                        "stays correct either way; this only costs speed. Run "
                        "'unsloth studio update' to install a build that supports it."
                    )
                    # Remember what was suppressed: the drafter stays on disk, so caller
                    # and route keep detecting it, and comparing that against the
                    # launched None would reload a healthy server on every repeat Apply.
                    _pv_suppressed_draft_path = launch_mtp_draft_path
                    launch_mtp_draft_path = None
                    if extra_args:
                        # Same reason: record the extras as REQUESTED next to the
                        # launched ones. Both comparators key on the caller's list,
                        # which keeps arriving unchanged, so comparing it against this
                        # rewrite would reload a healthy server on every repeat Apply.
                        _pv_suppressed_spec_extra_args = list(extra_args)
                        extra_args = strip_shadowing_flags(
                            extra_args,
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                # The same view of argv and env the child will get, built with the
                # helpers the launch itself uses so the two cannot drift: manual mode
                # drops the placement vars, and a gpu_ids pin drops the device flags
                # from both. Classifying on the raw extras would read a stale
                # --device none as CPU-only for a load that does offload.
                _spec_placement_env = dict(os.environ)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(_spec_placement_env)
                _spec_placement_extras = extra_args
                if gpu_ids is not None:
                    _spec_placement_extras = self._strip_device_extra_args(extra_args)
                    self._clear_device_placement_env(_spec_placement_env)
                # A device the launch really carries, and not the CPU spelling of it.
                # Only consulted where the probe found nothing: it is the one remaining
                # way the child can still be pointed at a GPU.
                _spec_device_pick = _extra_args_main_device(
                    [*cmd, *(_spec_placement_extras or [])]
                ) or _spec_placement_env.get("LLAMA_ARG_DEVICE")
                _spec_extras_pick_a_gpu = bool(_spec_device_pick) and not _device_selection_is_cpu(
                    [*cmd, *(_spec_placement_extras or [])], _spec_placement_env
                )
                spec_flags = self._build_speculative_flags(
                    speculative_type = speculative_type,
                    spec_draft_n_max = spec_draft_n_max,
                    extra_args = extra_args,
                    model_identifier = model_identifier,
                    model_path = model_path,
                    gpus = bool(_detected_gpus),
                    binary = binary,
                    mtp_draft_path = (
                        None if _spec_canon in ("dspark", "dflash") else launch_mtp_draft_path
                    ),
                    dspark_draft_path = (launch_mtp_draft_path if _spec_canon == "dspark" else None),
                    dspark_fit_sized = not use_fit,
                    dflash_draft_path = (launch_mtp_draft_path if _spec_canon == "dflash" else None),
                    dflash_fit_sized = not use_fit,
                    drafter_no_vram = _spec_dropped_no_vram,
                    embedded_mtp_partial_offload = bool(
                        _spec_canon == "auto"
                        and self._nextn_predict_layers
                        and self._ssm_inner_size is not None
                        and self._full_attention_interval is not None
                        and not launch_mtp_draft_path
                        and not _extra_args_set_spec_type(extra_args)
                        # No GPU, nothing to partially offload TO. `--fit on` is also
                        # what a CPU-only box and a Metal Mac emit (use_fit starts True
                        # and only the planner lowers it), and there the rollback copies
                        # cost no VRAM at all -- same reason the helper treats -ngl 0 as
                        # CPU-only rather than partial. Those keep the CPU MTP policy.
                        # gpu_indices counts too: an explicit pick the VRAM probe could
                        # not enumerate still pins the child to those devices, so the
                        # launch offloads to them whatever the probe returned. So does
                        # a device named in the extras, which is the same flag
                        # _device_selection_is_cpu reads for the CPU answer: a failed
                        # probe is not evidence of no GPU when the child is pointed at
                        # one by hand.
                        and (_detected_gpus or gpu_indices or _spec_extras_pick_a_gpu)
                        and self._partially_offloads_layers(
                            [*cmd, *(_spec_placement_extras or [])],
                            _spec_placement_env,
                            # Manual mode skips Unsloth's placement planner (gpus is
                            # emptied above), so its --fit on is the default this
                            # function starts at, not a finding that the model does
                            # not fit. Only Auto's fitter carries that evidence --
                            # and only when it actually ran and actually failed to
                            # fit, which is what _placement_verdict_partial records.
                            # Auto alone is not enough: an empty VRAM probe with a
                            # hand-pinned device (Metal0, Vulkan0) satisfies the GPU
                            # guard above while every planner branch stayed gated on
                            # the empty `gpus`, and the except path restores --fit on
                            # having priced nothing. A concrete --gpu-layers count is
                            # unaffected; it is independent evidence inside the helper.
                            fit_implies_partial = (
                                gpu_memory_mode != "manual" and _placement_verdict_partial
                            ),
                        )
                    ),
                    draft_device = _draft_device,
                )
                # _build_speculative_flags judged the stripped list, so a user
                # --spec-type the drop removed left the requested mode reading "auto"
                # while the caller's extras still mean "the user owns it" (None).
                # Restore the requested view, or the spec-mode compare never matches.
                if _extra_args_set_spec_type(_pv_suppressed_spec_extra_args):
                    self._requested_spec_mode = None
                # The draft KV cache dtype sizes the DRAFT context, so it means
                # nothing without --model-draft. Judged on the flags actually built,
                # not the requested mode: a mode that fell back to no drafter emits
                # nothing, and an MTP load that did attach one is covered.
                # Normalized and allow-listed like the main cache dtype above, and
                # for the same reason: llama-server exits during argument parsing on
                # a value it cannot map, and by then the resident model is gone. An
                # unknown value emits nothing instead, so the load still comes up.
                _draft_cache_type = (
                    spec_draft_cache_type.strip().lower() if spec_draft_cache_type else None
                )
                if _draft_cache_type and _draft_cache_type not in _VALID_KV_CACHE_TYPES:
                    logger.warning(
                        "Ignoring unsupported draft KV cache type %r", spec_draft_cache_type
                    )
                    _draft_cache_type = None
                if _draft_cache_type and any(
                    _flag_name(tok) in _LOCAL_DRAFT_FLAGS for tok in spec_flags
                ):
                    _draft_k_flag = server_caps.get("spec_draft_cache_k_flag")
                    _draft_v_flag = server_caps.get("spec_draft_cache_v_flag")
                    if _draft_k_flag and _draft_v_flag:
                        # Both axes together: llama.cpp refuses K != V on an MLA
                        # draft context, and the control is one dtype for the pair.
                        spec_flags.extend(
                            [
                                str(_draft_k_flag),
                                _draft_cache_type,
                                str(_draft_v_flag),
                                _draft_cache_type,
                            ]
                        )
                        logger.info("Draft KV cache dtype: %s", _draft_cache_type)
                    else:
                        logger.info(
                            "llama-server has no draft KV cache flags; skipping the requested %s.",
                            _draft_cache_type,
                        )
                # Remember where the spec block sits so a drafter-load failure
                # can be retried with these flags swapped out (see below).
                _spec_start = len(cmd)
                cmd.extend(spec_flags)

                # A *separate* drafter does not inherit the main --gpu-layers:
                # common_base_params_to_speculative overwrites n_gpu_layers with
                # params.speculative.draft.n_gpu_layers, whose default -1 means auto, so
                # the drafter would run the corrupt path the CPU pin exists to avoid. An
                # embedded MTP head needs nothing here: with no draft model that override
                # is skipped (has_draft is false) and the head follows the main
                # placement. Probe-gated like the other optional flags so the name
                # matches the build (-ngld predates --spec-draft-ngl) and an unknown
                # argument never refuses the start; a build advertising none of them had
                # its drafter dropped above. extra_args is inspected alongside spec_flags
                # because a user-owned --spec-type makes _build_speculative_flags return
                # nothing, leaving their --model-draft unpinned. Emitted after the
                # pass-through extras below, not here: the parser is last-wins and the
                # paravirtual strip covers only the *main* offload flags, so a user
                # -ngld/--spec-draft-ngl would otherwise undo this.
                _pv_draft_cpu_pin: List[str] = []
                _pv_mmproj_cpu_pin: List[str] = []
                _pv_split_mode_pin: List[str] = []
                # --gpu-layers 0 alone does not keep work off the device: with op_offload
                # on (the default) ggml_backend_sched still sends ops whose weights sit
                # in host buffers to a higher-priority backend, and Metal accepts them at
                # batch >= 32. --device none drops the device from the list outright.
                _pv_device_pin: List[str] = ["--device", "none"] if _paravirtual_cpu_forced else []
                if (
                    _paravirtual_cpu_forced
                    # Same env the child will see: when the extras own --spec-type the
                    # launch keeps LLAMA_ARG_SPEC_DRAFT_*, so a drafter named only there
                    # still loads and would take the corrupt device unpinned.
                    and _extra_args_mtp_draft_path(
                        [*spec_flags, *(extra_args or [])], env = _child_spec_env(extra_args)
                    )
                    is not None
                    and _paravirtual_draft_ngl_flag(server_caps)
                ):
                    # The layer count alone is not enough, for the same reason
                    # --gpu-layers 0 was not: common_base_params_to_speculative replaces
                    # the draft context's device list with the draft one, so the main
                    # --device none never reaches it and an empty draft list leaves every
                    # device visible. --device-draft is spelled the same across the
                    # whole supported range.
                    _pv_draft_cpu_pin = [
                        str(_paravirtual_draft_ngl_flag(server_caps)),
                        "0",
                        "--device-draft",
                        "none",
                    ]
                    logger.warning(
                        "Pinning the speculative drafter to CPU: this Mac's Metal "
                        "device is virtualised."
                    )

                # Emitted after the pass-through extras too, same last-wins reason.
                if _paravirtual_cpu_forced:
                    _pv_split_mode_pin = _paravirtual_split_mode_pin(extra_args)

                # Apply custom chat template override if provided.
                self._chat_template_override = chat_template_override
                if chat_template_override:
                    import tempfile

                    flags = detect_reasoning_flags(
                        chat_template_override,
                        self._model_identifier,
                        log_source = "GGUF chat template override",
                    )
                    self._supports_reasoning = flags["supports_reasoning"]
                    self._reasoning_style = flags["reasoning_style"]
                    self._reasoning_effort_levels = flags.get("reasoning_effort_levels", [])
                    self._reasoning_always_on = flags["reasoning_always_on"]
                    self._supports_preserve_thinking = flags["supports_preserve_thinking"]
                    self._preserve_thinking_default = flags["preserve_thinking_default"]
                    self._supports_tools = flags["supports_tools"]

                    self._chat_template_file = tempfile.NamedTemporaryFile(
                        mode = "w",
                        encoding = "utf-8",
                        suffix = ".jinja",
                        delete = False,
                        prefix = "unsloth_chat_template_",
                    )
                    self._chat_template_file.write(chat_template_override)
                    self._chat_template_file.close()
                    cmd.extend(["--chat-template-file", self._chat_template_file.name])
                    logger.info(f"Using custom chat template file: {self._chat_template_file.name}")

                # Default thinking mode for reasoning models. The Qwen3.5 Small tier
                # (0.8B, 2B, 4B, 9B) ships with reasoning off by default and the rest of
                # the family has it on; the templates are byte-identical across sizes, so
                # this tier split only exists as a launch flag. Always-on templates ignore
                # the kwarg, so skip.
                if self._supports_reasoning and not self._reasoning_always_on:
                    thinking_default = True
                    mid = (model_identifier or "").lower()
                    if "qwen3.5" in mid or "qwen3.6" in mid:
                        # extract_model_size_b prefers MoE active params, reading
                        # 35B-A3B as 3B. Match total params instead: scan segments
                        # right to left so the size nearest the leaf beats a size-like
                        # parent dir, and keep its \s* / M-suffix spellings.
                        size_re = r"(?:^|[-_.])(\d+\.?\d*)\s*([bm])(?:$|[-_.])"
                        size_match = None
                        for seg in reversed(mid.replace("\\", "/").split("/")):
                            size_match = re.search(size_re, seg)
                            if size_match:
                                break
                        if size_match:
                            size_b = float(size_match.group(1))
                            if size_match.group(2) == "m":
                                size_b /= 1000.0
                            # <= 9, not < 9: 9B is the top of the Small tier, so it is off too.
                            if size_b <= 9:
                                thinking_default = False
                    self._reasoning_default = thinking_default
                    reasoning_kw = self._reasoning_kwargs(thinking_default)
                    # preserve_thinking is independent of the thinking gate.
                    # Qwen3.8 defaults it on; Qwen3.6, Gemma 4, and every other
                    # supporting family keep the existing off default. The
                    # frontend receives the same resolved value via load/status.
                    if self._supports_preserve_thinking:
                        reasoning_kw["preserve_thinking"] = self._preserve_thinking_default
                    cmd.extend(
                        [
                            "--chat-template-kwargs",
                            json.dumps(reasoning_kw),
                        ]
                    )
                    logger.info(f"Reasoning model: {reasoning_kw} by default")

                if launch_mmproj_path and effective_is_vision:
                    cmd.extend(["--mmproj", launch_mmproj_path])
                    logger.info(f"Using mmproj for vision: {launch_mmproj_path}")
                    # The projector never reads --gpu-layers: clip.cpp picks a GPU
                    # backend from the boolean mmproj_use_gpu, which defaults true, so
                    # the vision encoder would keep running the corrupt path the CPU pin
                    # exists to avoid and encode every image from garbage. A build that
                    # conclusively lacks the flag never gets here (the projector is
                    # dropped up front); an inconclusive probe still pins, since every
                    # build that can start here has had the flag since b5178. Deferred
                    # past the pass-through extras like the drafter pin, since
                    # --mmproj-offload is a real flag a user can pass and llama.cpp is
                    # last-wins.
                    # One flag whichever reason pinned it: the corrupt paravirtual Metal
                    # device, or the fit deciding the projector does not fit in VRAM.
                    # Both already checked the capability.
                    if _mmproj_cpu_pinned:
                        _pv_mmproj_cpu_pin = ["--no-mmproj-offload"]
                        if _paravirtual_cpu_forced:
                            logger.warning(
                                "Disabling mmproj GPU offload: this Mac's Metal "
                                "device is virtualised."
                            )

                # Option C: --api-key for direct client access when enabled
                import secrets as _secrets

                if os.getenv("UNSLOTH_DIRECT_STREAM", "0") == "1":
                    self._api_key = _secrets.token_urlsafe(32)
                    cmd.extend(["--api-key", self._api_key])
                    logger.info("llama-server started with --api-key for direct streaming")
                else:
                    self._api_key = None

                # Windows + full offload: drop the host-RAM KV checkpoints that cause
                # WDDM/PCI-E overhead, but keep prompt caching (in-VRAM prefix reuse) so
                # a repeated prompt is not re-prefilled on every request. #5692.
                if sys.platform == "win32" and full_offload_tuning_active:
                    unsupported_cache_flags: list[str] = []
                    # An explicit control wins over the platform tuning: llama.cpp
                    # is last-wins, so a 0 emitted after it would overrule the panel
                    # while the panel still showed the value that was typed.
                    if cache_ram is not None:
                        pass
                    elif server_caps.get("supports_cache_ram"):
                        cmd.extend(["--cache-ram", "0"])
                    else:
                        unsupported_cache_flags.append("--cache-ram")
                    if ctx_checkpoints is not None:
                        pass
                    elif server_caps.get("ctx_checkpoints_flag"):
                        cmd.extend([str(server_caps["ctx_checkpoints_flag"]), "0"])
                    else:
                        unsupported_cache_flags.append("--ctx-checkpoints")
                    if unsupported_cache_flags:
                        logger.info(
                            "Skipping unsupported Windows cache flags for llama-server: %s",
                            ", ".join(unsupported_cache_flags),
                        )

                # Record the pin actually applied (fit-narrowed gpu_indices, else the raw
                # request) for the keep-warm loop, dedupe, and /status, so an explicit
                # [0, 1] narrowed to [0] records [0] and /status never echoes an ordinal
                # the child never saw. Auto selection (no gpu_ids) stays None (#7239).
                if _paravirtual_cpu_forced:
                    # --device none pins nothing, so record no effective pin here either.
                    # Ahead of the backend branches: this is the authoritative record and
                    # would otherwise re-echo the device the child never saw.
                    self._gpu_ids = None
                elif is_vulkan_backend:
                    # Only record an EXPLICIT Vulkan pin: an auto pick still narrows +
                    # pins below, but recording it would misreport an explicit pin and
                    # make dedupe miss the loaded server; mirrors the CUDA/ROCm branch.
                    self._gpu_ids = (
                        sorted(int(x) for x in _vulkan_pin_ids)
                        if (gpu_ids and _vulkan_pin_ids)
                        else None
                    )
                elif gpu_ids:
                    # Physical pin: the fit-selected subset when the fit ran, else the raw
                    # user selection so an explicit choice is honoured even when the fit
                    # could not size the model.
                    _effective_pin_ids = (
                        [int(x) for x in gpu_indices]
                        if gpu_indices is not None
                        else [int(x) for x in gpu_ids]
                    )
                    self._gpu_ids = (
                        sorted(int(x) for x in _effective_pin_ids) if _effective_pin_ids else None
                    )
                else:
                    self._gpu_ids = None

                # Also record the RAW requested pin (before the fit narrowed it). Load
                # dedupe compares this so a [0, 1] narrowed to [0] and re-sent as [0, 1]
                # still matches, while /status keeps echoing the effective pin (#7239).
                self._requested_gpu_ids = sorted(int(x) for x in gpu_ids) if gpu_ids else None

                if is_vulkan_backend and _vulkan_pin_ids is not None:
                    cmd += LlamaCppBackend._vulkan_pin_args(_vulkan_pin_ids)

                # Model Memory settings. Managed flag lands before the extras, and
                # vetoed ones are dropped from a launch-only copy: extra_args keeps
                # None-vs-[] (inherit vs clear) for the commit block below, and the
                # user's saved flags survive turning the toggle back off.
                # mlock pins a mapping in HOST RAM, so it only implements
                # residency where the weights actually live there: unified
                # memory, or any load that is not fully offloaded. On a discrete
                # GPU with full offload it would hold a second copy of the model
                # in system RAM and do nothing for VRAM, so it is not emitted
                # and the idle-unload veto carries residency by itself.
                from utils.model_memory_settings import should_mlock

                # fully_gpu_offloaded is only set by the auto branch. Manual mode
                # and a user -ngl reach the same placement by their own routes,
                # so derive those too or they would still be pinned. The CPU
                # placement guard applies to BOTH: an auto fit that offloads
                # every layer still leaves weights in RAM if an extra pins them
                # there, so it cannot short-circuit past the check.
                # Asked on EVERY launch, not just when a lock is on the table:
                # _memory_mlock_applicable is recorded from it, and a LATER
                # "keep resident" save is compared against that. Assuming host
                # residency by default made enabling the toggle demand a reload
                # and reject the duplicate-load fast path, tearing down a healthy
                # server to relaunch identical argv. Only the Vulkan probe stays
                # gated, so the default path still spawns nothing.
                # The same view of the environment the child will get: manual
                # mode drops the placement vars below, so reading os.environ
                # would pin for a CPU-MoE setting the child never sees.
                _mem_env = dict(os.environ)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(_mem_env)
                # A gpu_ids pin drops the device flags from argv and env below,
                # so classifying on them would pin for a --device cpu the child
                # never sees. Same helpers the launch uses, so they cannot drift.
                _mem_extra_args = extra_args
                if gpu_ids is not None:
                    _mem_extra_args = self._strip_device_extra_args(extra_args)
                    self._clear_device_placement_env(_mem_env)
                _mem_host_resident = self._weights_in_host_memory(
                    fully_gpu_offloaded = fully_gpu_offloaded,
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    extra_args = _mem_extra_args,
                    gpu_indices = gpu_indices,
                    is_vulkan_backend = is_vulkan_backend,
                    binary = binary,
                    env = _mem_env,
                    probe_vulkan = should_mlock(),
                    # Over the built cmd AND the extras, so Unsloth's own --fit
                    # counts and a later user --fit still wins by last-arg.
                    fit_active = fit_is_effectively_on([*cmd, *(_mem_extra_args or [])], _mem_env),
                )
                # The gate masks every device away, so the child runs from host RAM
                # whatever was asked, while _weights_in_host_memory answered for the
                # ORIGINAL placement. Without this the page-lock is skipped and
                # _memory_mlock_applicable records that as deliberate, which no
                # relaunch undoes.
                if _arch_gate_forced_cpu:
                    _mem_host_resident = True
                _mem_managed, _mem_extras = apply_model_memory_policy(
                    extra_args,
                    supports_load_mode = bool(server_caps.get("supports_load_mode")),
                    weights_in_host_memory = _mem_host_resident,
                )
                # After Model Memory and on the extras it returned, because it
                # defers to those settings: while either one owns host placement
                # the per-model pick emits nothing at all.
                #
                # The fit's "none" only fills in for a model with no pick of its own,
                # and sits here rather than inside the policy so the whole precedence
                # chain stays in one place: the per-model mode wins over the fit, Model
                # Memory wins over both, and a hand-typed flag still wins by last-arg.
                #
                # An INHERITED loader mode is an explicit choice too: llama.cpp reads
                # LLAMA_ARG_LOAD_MODE (and the deprecated twins) before argv and both
                # assign the same params.load_mode, so the managed block below would
                # beat one silently. Only the FIT's mode stands aside, since a per-model
                # pick is a choice made for THIS model. Asked AFTER the same scrub the
                # child gets, so a var a Model Memory toggle drops vetoes nothing.
                _fit_load_mode_env_view = dict(_mem_env)
                scrub_memory_env(_fit_load_mode_env_view)
                if (
                    _fit_load_mode
                    and not load_mode
                    and memory_env_selects_load_mode(_fit_load_mode_env_view)
                ):
                    logger.info(
                        "Load mode: the environment already selects a loader mode; "
                        "leaving the fit's --load-mode %s off this launch.",
                        _fit_load_mode,
                    )
                    _fit_load_mode = None
                # And a mode the EXTRAS pick. Their flag already wins by last-arg, but
                # the retry rungs below strip the pair by VALUE and take the FIRST match
                # (_without_subsequence), so a user who typed the same "--load-mode none"
                # leaves two identical pairs: one rung removes the fit's and records the
                # stripped argv, and the next, respawning from it, removes theirs.
                # Standing aside costs nothing and leaves every strip below the no-op
                # its docstring already claims to be.
                if _fit_load_mode and not load_mode and extra_args_select_load_mode(_mem_extras):
                    logger.info(
                        "Load mode: the extra arguments already select a loader mode; "
                        "leaving the fit's --load-mode %s off this launch.",
                        _fit_load_mode,
                    )
                    _fit_load_mode = None
                _resolved_load_mode = load_mode or _fit_load_mode
                _load_mode_managed, _mem_extras = apply_load_mode_policy(
                    _mem_extras,
                    supports_load_mode = bool(server_caps.get("supports_load_mode")),
                    weights_in_host_memory = _mem_host_resident,
                    requested_load_mode = _resolved_load_mode,
                )
                # Only when the FIT chose it: a user's own pick survives every fallback
                # below, but a conclusion about a placement has to go when that
                # placement does.
                self._fit_load_mode_flags = (
                    list(_load_mode_managed) if (_fit_load_mode and not load_mode) else []
                )
                # Remembered so the reload hint and the duplicate-load comparator do
                # not demand an mlock this launch deliberately skipped.
                self._memory_mlock_applicable = _mem_host_resident
                if should_mlock() and not _mem_host_resident:
                    logger.info(
                        "Model Memory: skipping page-lock, the weights are fully "
                        "offloaded to a discrete GPU; residency is kept by not "
                        "unloading the model."
                    )
                if _mem_managed:
                    cmd.extend(_mem_managed)
                    logger.info(
                        "Model Memory: keeping weights pinned in place (%s)",
                        " ".join(_mem_managed),
                    )
                if _load_mode_managed:
                    cmd.extend(_load_mode_managed)
                    logger.info("Load mode: %s", " ".join(_load_mode_managed))

                # User pass-through args go last. Placement flags are removed
                # below when the Unsloth picker owns the GPU selection.
                if _mem_extras:
                    _emit_extra_args = list(_mem_extras)
                    if gpu_ids is not None:
                        # gpu_ids owns placement, so remove competing device flags.
                        _before_device_strip = list(_emit_extra_args)
                        _emit_extra_args = self._strip_device_extra_args(_emit_extra_args)
                        if _emit_extra_args != _before_device_strip:
                            logger.info(
                                "Dropped user device placement flags from extra args: "
                                "explicit gpu_ids owns placement."
                            )
                    cmd.extend(str(a) for a in _emit_extra_args)
                    logger.info(
                        f"Appending user extra args to llama-server: {list(_emit_extra_args)}"
                    )

                # Last so it wins: the drafter CPU pin on a virtualised Metal device
                # is a correctness fix, not a preference, and llama.cpp is last-wins.
                if _pv_draft_cpu_pin:
                    cmd.extend(_pv_draft_cpu_pin)
                if _pv_mmproj_cpu_pin:
                    cmd.extend(_pv_mmproj_cpu_pin)
                # Also last, and for the same last-wins reason: suppressing Unsloth's own
                # --mmproj and scrubbing the env vars still leaves a remembered
                # --mmproj-auto in the extras above, and that flag asks llama-server to
                # rediscover the adjacent projector by itself. Vision would come back on
                # a load that reports it off and whose fit budget never charged the
                # projector's VRAM. Only when the projector really was suppressed. Both
                # ways of keeping an audio-only one are excluded: the resolved path keeps
                # launch_mmproj_path set, and an inherited LLAMA_ARG_MMPROJ keeps neither
                # that nor anything else this gate can see, so it needs the same predicate
                # the env scrub used. --no-mmproj-auto does not actually unload either of
                # them -- server-context.cpp gates the load on a non-empty mmproj.path and
                # never reads no_mmproj, which only suppresses the HF auto-download and
                # the router's capability report -- but advertising a model as text-only
                # while loading its encoder is its own bug, and one flag away from a real
                # one if that gate ever starts reading no_mmproj.
                if disable_vision and not launch_mmproj_path and not _dv_env_mmproj_kept:
                    cmd.append("--no-mmproj-auto")
                # Also last: _zero_offload_keeps_gpu_visible reads the finished cmd, so
                # the override must be in it before the env block below judges this a
                # zero-VRAM server.
                if _pv_split_mode_pin:
                    cmd.extend(_pv_split_mode_pin)
                if _pv_device_pin:
                    cmd.extend(_pv_device_pin)

                # A build with no --flash-attn cannot run a quantized V cache
                # either: llama.cpp aborts init with "V cache quantization
                # requires flash_attn", and the KV type is emitted from the
                # user's setting with no flash-attn coupling. The crash-recovery
                # rung resets V for exactly that abort, but it only fires when
                # the argv had a flag to turn off, so on a build that never had
                # one nothing would catch it. Before the log below, so what is
                # logged is what launches; length is preserved, so _spec_start
                # still indexes the same tokens.
                if _flash_attn_known_off:
                    cmd = self._reset_quantized_v_cache(
                        cmd,
                        "this build has no --flash-attn",
                        mla = self._target_kv_symmetry(),
                        # No env argument: the child environment is not built until
                        # below, and reading it here is an UnboundLocalError. The
                        # inherited os.environ is the right source anyway, since
                        # Unsloth never rewrites LLAMA_ARG_SPEC_DRAFT_MODEL.
                        draft_mla = self._draft_kv_symmetry(cmd),
                    )

                kv_cache_unified = _kv_unified_from_args(cmd)

                logger.info(f"Starting llama-server: {' '.join(self._redacted_cmd_for_log(cmd))}")

                # Library paths so llama-server finds its shared libs and CUDA DLLs.
                env = self._llama_server_env_for_binary(binary)
                # The GGUF header controls pooling; ignore inherited defaults.
                for _pooling_var in (
                    "LLAMA_ARG_POOLING",
                    "LLAMA_ARG_RERANKING",
                    "LLAMA_ARG_EMBEDDINGS",
                ):
                    env.pop(_pooling_var, None)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(env)
                # llama.cpp reads LLAMA_ARG_MLOCK / _MMAP / _LOAD_MODE before argv,
                # so stripping the tokens alone would leave an inherited value in
                # force. Only when a toggle is on, so existing setups are untouched.
                _mem_scrubbed = scrub_memory_env(env)
                if _mem_scrubbed:
                    logger.info(
                        "Model Memory owns placement; dropped inherited %s",
                        ", ".join(_mem_scrubbed),
                    )
                # Same reasoning one level up: a flag validate_extra_args refuses has
                # an env twin llama.cpp reads before argv, so denying the token alone
                # would leave the capability reachable and unrecorded.
                _denied_scrubbed = scrub_denied_env(env)
                if _denied_scrubbed:
                    logger.info(
                        "dropped inherited %s: managed by Unsloth Studio",
                        ", ".join(_denied_scrubbed),
                    )
                # Record what the child will ACTUALLY run with (env defaults plus
                # last-wins argv), not just what Unsloth emitted, so the reload
                # hint also catches a user-supplied --mlock / --no-mmap.
                #
                # In argv order, including the load-mode pair: "none" holds a full
                # anonymous host copy (llama-model-loader.cpp sets use_mmap only for
                # mmap/mmap+mlock/auto), so leaving it out records the launch as
                # non-reserving and a later "Don't reserve system RAM" is judged already
                # satisfied, keeping the reservation instead of relaunching with mmap.
                self._memory_state = resolve_effective_memory_state(
                    list(_mem_managed) + list(_load_mode_managed) + list(_mem_extras), env
                )
                # Did the policy change this launch at all: emitted a flag,
                # suppressed a requested one, or scrubbed an inherited env var.
                # Turning both toggles off must relaunch to undo any of those,
                # but must not fight a launch it never touched.
                # Split out: the fit-off retry can drop _mem_managed, and what is
                # left decides whether that child still differs from an unmanaged one.
                _mem_policy_touched_extras = bool(_mem_scrubbed) or _mem_extras != list(
                    extra_args or []
                )
                self._memory_policy_active = bool(_mem_managed) or _mem_policy_touched_extras
                # What `cmd` itself means, snapshotted before any respawn edits it.
                # _spawn_and_wait's --fit retries append a page-lock to THEIR argv
                # and write the policy back; the arch-crash retry (#7624) respawns
                # `cmd`, which never carried that lock, so it restores these.
                _mem_policy_for_cmd = (
                    _mem_host_resident,
                    self._memory_state,
                    self._memory_policy_active,
                    self._memory_mlock_applicable,
                )
                # Omitting --threads relies on llama.cpp's physical-core default, so
                # drop an inherited LLAMA_ARG_THREADS that would otherwise feed the
                # arg handler and silently force hardware_concurrency(). #5692
                if "--threads" not in cmd:
                    env.pop("LLAMA_ARG_THREADS", None)
                # Same shape, for the context. Auto-layers omits -c so --fit can size
                # it, and with no -c to win the env-then-argv race an inherited
                # LLAMA_ARG_CTX_SIZE=0 pins the native length and the fit never runs.
                # Only a zero, and only where a pass-through zero would go too, so a
                # positive inherited context stays the legitimate way to set one.
                if (
                    not any(token in cmd for token in ("-c", "--ctx-size"))
                    and _env_asks_for_the_native_context(env)
                    and self._metal_drops_zero_ctx_override(0, _caller_owns_budget)
                ):
                    env.pop("LLAMA_ARG_CTX_SIZE", None)
                    logger.warning(
                        "Dropping the inherited LLAMA_ARG_CTX_SIZE=0: on Metal it pins "
                        "the model's native length and disables --fit."
                    )
                # A build whose help has no --flash-attn never registers the option,
                # so it never reads LLAMA_ARG_FLASH_ATTN either (llama.cpp resolves
                # each env var through the arg that declares it). Leaving an
                # inherited one in place would only fool the accounting below, which
                # reads env plus argv and would then record flash attention as on for
                # a server running without it, under-sizing the padded V cache.
                if _flash_attn_known_off and self._drop_env_flash_attn(env):
                    logger.info(
                        "Dropped inherited LLAMA_ARG_FLASH_ATTN: this build has no --flash-attn."
                    )
                # Same for an env-only quantized V cache, which the argv reset
                # above cannot reach.
                if _flash_attn_known_off and self._drop_env_quantized_v_cache(
                    env,
                    mla = self._target_kv_symmetry(),
                    draft_mla = self._draft_kv_symmetry(cmd, env),
                ):
                    logger.info(
                        "Dropped inherited quantized V-cache env: this build has no --flash-attn."
                    )

                # An inherited type kv_cache_type_from_str cannot parse aborts the child
                # at argument parsing, and the layer retry inherits the same env, so
                # BOTH attempts fail and the user is left with no server. The managed
                # path has long been normalised and allow-listed (_VALID_CACHE_TYPES);
                # the env path only stopped being scrubbed once the tensor gate went
                # away, so give it the same two protections. Split-mode independent,
                # since llama.cpp parses it identically either way.
                for _ct_var in ("LLAMA_ARG_CACHE_TYPE_K", "LLAMA_ARG_CACHE_TYPE_V"):
                    # Compared against the ORIGINAL, not a stripped copy:
                    # common_arg::get_value_from_env hands the raw getenv string to
                    # kv_cache_type_from_str, which does an exact ggml_type_name(t) == s
                    # compare and throws otherwise. So " q8_0 " is as fatal as a typo,
                    # and normalising against an already-stripped copy would compare
                    # equal, write nothing back, and leave the whitespace on the child.
                    _ct_orig = env.get(_ct_var) or ""
                    _ct_norm = _ct_orig.strip().lower()
                    if not _ct_norm:
                        continue
                    if _ct_norm not in _VALID_CACHE_TYPES:
                        env.pop(_ct_var, None)
                        logger.info(
                            "Dropped inherited %s=%s: llama.cpp does not accept that "
                            "KV cache type, and it would abort the load.",
                            _ct_var,
                            _ct_orig,
                        )
                    elif _ct_norm != _ct_orig:
                        # Case and surrounding whitespace both matter to that
                        # compare, so "Q8_0" and " q8_0 " are rewritten alike.
                        env[_ct_var] = _ct_norm

                # Reconcile the inherited LLAMA_ARG_* env with Unsloth's final
                # decision: stripping CLI extras on a tensor->layer downgrade
                # can't remove env vars, so the child could run a mode Unsloth
                # didn't budget.
                if not tensor_parallel:
                    # Layer split: clear a non-layer inherited split mode (and any
                    # paired tensor-split) so the child can't override the layer plan.
                    _inherited_sm = (env.get("LLAMA_ARG_SPLIT_MODE") or "").strip().lower()
                    if _inherited_sm and _inherited_sm != "layer":
                        env.pop("LLAMA_ARG_SPLIT_MODE", None)
                        env.pop("LLAMA_ARG_TENSOR_SPLIT", None)
                else:
                    # Unsloth owns the tensor split: it emits --tensor-split when it
                    # picks an uneven one (CLI wins) and nothing when an even split
                    # is safe. Clear any inherited LLAMA_ARG_TENSOR_SPLIT so the even
                    # case can't be overridden by a stale env (the layer branch above
                    # clears it too).
                    env.pop("LLAMA_ARG_TENSOR_SPLIT", None)

                # A gpu_ids pin also owns inherited device placement.
                if gpu_ids is not None:
                    self._clear_device_placement_env(env)

                # After the scrubs above, so a placement this launch already dropped
                # cannot disqualify the replay of a child that never saw it.
                _cpu_fallback_eligible = self._auto_vulkan_cpu_fallback_eligible(
                    binary,
                    intent,
                    extra_args,
                    env,
                )

                # The unpinnable-drafter drop above rewrites argv, which cannot reach the
                # drafter the child picks up from its own env. The spec type goes too,
                # for the same reason the CLI one did: llama.cpp appends types rather
                # than replacing them, so an inherited draft-simple would outlive the
                # model it needs. Unsloth owns the spec block whenever the extras do not
                # name a --spec-type, and nothing _build_speculative_flags emits can undo
                # an inherited LLAMA_ARG_SPEC_TYPE (env applied first, then appended), so
                # a managed non-MTP launch would still start MTP, a crash-recovery replay
                # could not drop it, and the fit never budgeted the drafter the env adds.
                # Clearing it makes the emitted flags final. A user-owned --spec-type is
                # left alone: their flags and the env accumulate, which is what the slot
                # clamp above reads.
                if _pv_draft_unpinnable or not _extra_args_set_spec_type(extra_args):
                    for _pv_spec_var in _SPEC_ENV_VARS:
                        env.pop(_pv_spec_var, None)

                # The projector guard has a worse blind spot: it only clears Unsloth's
                # resolved path, so an inherited LLAMA_ARG_MMPROJ loads a projector the
                # guard believes it dropped, unpinned and independent of --gpu-layers 0.
                # LLAMA_ARG_MMPROJ_URL goes too: its download overwrites mmproj.path, so
                # it outranks even the --mmproj Unsloth emits. Unsloth always passes its
                # own projector on the command line (with --no-mmproj-offload), so an
                # inherited one is only ever the corrupt path.
                # Turning vision off has the same blind spot, and it is the whole point
                # of the switch: suppressing Unsloth's own --mmproj leaves an inherited
                # LLAMA_ARG_MMPROJ / LLAMA_ARG_MMPROJ_URL untouched, so llama-server
                # loads a projector anyway (arg.cpp sets params.mmproj.path / .url
                # straight from those vars). The load would then report text-only over a
                # server that is still multimodal, and the fit budget that gave the
                # projector's bytes to context is short by exactly those bytes.
                if disable_vision:
                    # With the same audio-only exception the resolved path gets, and for
                    # the same reason: a projector is not always a vision tower, so
                    # clearing an inherited ultravox / Voxtral / Qwen3-ASR encoder takes
                    # the model's audio input away and gives no image VRAM back. Asked of
                    # the file rather than assumed, and unknown still reads image-capable,
                    # so the switch is honored wherever it might mean anything.
                    _dv_env_mmproj = (env.get("LLAMA_ARG_MMPROJ") or "").strip()
                    if not _mmproj_env_is_audio_only(_dv_env_mmproj):
                        # Same signal the resolved path records, for the same reason:
                        # this one IS restored by turning Vision back on, so the composer
                        # must point at the switch rather than at a missing mmproj. Only
                        # for a file that exists -- a stale path drops nothing, and
                        # blaming the switch there sends the user to a control that
                        # cannot help. Unknown-but-present reads image-capable, matching
                        # the rule the scrub itself just used.
                        if _dv_env_mmproj and Path(_dv_env_mmproj).is_file():
                            _dv_dropped_image_projector = True
                        env.pop("LLAMA_ARG_MMPROJ", None)
                    # No such reprieve for the URL: it names a download that has not
                    # happened, so there is no file to classify and nothing to do but
                    # honor the switch.
                    env.pop("LLAMA_ARG_MMPROJ_URL", None)
                if _paravirtual_cpu_forced:
                    for _pv_mmproj_var in ("LLAMA_ARG_MMPROJ", "LLAMA_ARG_MMPROJ_URL"):
                        env.pop(_pv_mmproj_var, None)
                    # LLAMA_ARG_OVERRIDE_TENSOR is the one placement var --gpu-layers 0
                    # cannot answer: applied during weight-buft selection, before any
                    # layer is assigned, so it puts weights back on the corrupt Metal
                    # buffer on its own. Same CPU-target rule as the argv strip, so an
                    # inherited exps=CPU override keeps working and only GPU-bound goes.
                    _pv_env_ot = env.get("LLAMA_ARG_OVERRIDE_TENSOR")
                    if _pv_env_ot and not _paravirtual_strip_gpu_overrides(
                        ["-ot", str(_pv_env_ot)]
                    ):
                        env.pop("LLAMA_ARG_OVERRIDE_TENSOR", None)

                # Windows + full offload: PASSIVE OMP + 2 threads stop
                # spin-wait burning CPU. CPU/partial offload keeps default
                # OMP parallelism. #5692.
                if sys.platform == "win32" and full_offload_tuning_active:
                    env.setdefault("OMP_WAIT_POLICY", "PASSIVE")
                    if not threads_overridden:
                        env.setdefault("OMP_NUM_THREADS", "2")

                # AMD unified-memory APUs (gfx1150/gfx1151): let llama.cpp use shared
                # system RAM. Not on Vulkan (nor DC below): gpu_indices are ggml
                # ordinals, not CUDA/ROCm ids. Ownership-tracked, so the arch-crash
                # retry withdraws it only when THIS launch set it.
                _unified_env_applied = False
                _unified_opt_out = self._unified_memory_opted_out(env)
                if _unified_opt_out:
                    # ggml tests presence, so passing a user's "0" through would
                    # ENABLE what they turned off (#8651). Only absence is off.
                    if env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None) is not None:
                        logger.info(
                            "Unified memory opted out: unset GGML_CUDA_ENABLE_UNIFIED_MEMORY"
                        )
                elif not is_vulkan_backend and self._amd_apu_wants_unified_memory(gpu_indices):
                    _unified_env_applied = "GGML_CUDA_ENABLE_UNIFIED_MEMORY" not in env
                    env.setdefault("GGML_CUDA_ENABLE_UNIFIED_MEMORY", "1")
                    logger.info("AMD unified-memory APU: set GGML_CUDA_ENABLE_UNIFIED_MEMORY=1")

                # DC NVIDIA GPUs: FP32 accum (+ P2P / launch queues for multi-GPU).
                # See _apply_datacenter_env; opt out with UNSLOTH_DISABLE_DC_TUNING=1.
                if not is_vulkan_backend and self._apply_datacenter_env(env, gpu_indices):
                    multi_gpu = self._effective_gpu_count(gpu_indices) > 1
                    logger.info(
                        f"Data-center GPU detected: applied DC llama.cpp env tuning (multi_gpu={multi_gpu})"
                    )

                # Pin to selected GPU(s) (issue #7164; resolved above into gpu_indices).
                # On ROCm, narrowing only CUDA_VISIBLE_DEVICES leaves the AMD child
                # seeing the full set, so set HIP_VISIBLE_DEVICES too. Vulkan is pinned
                # via --device (above), not here.
                # A deliberate zero-offload load with no GPU companions runs entirely
                # on CPU, yet a visible CUDA device still costs the child ~0.5 GB
                # (context + compute scratch) that the CPU-only classification below
                # reports as free. Hide the GPUs so the load is exactly what it
                # claims. Companion loads keep the normal masking, and a user device
                # pin (extras or an inherited LLAMA_ARG_DEVICE) keeps control of its
                # own devices, the child aborting on a pin it cannot see. The
                # draft-device forms count too: parsed with no drafter loaded.
                _cpu_only_zero_offload = (
                    gpu_memory_mode == "manual"
                    and gpu_layers == 0
                    and not is_vulkan_backend
                    and not self._zero_offload_keeps_gpu_visible(cmd, env)
                )
                # The CUDA SM gate goes here, where the child's GPU visibility is
                # finally known: both arms below write CUDA_VISIBLE_DEVICES=-1, so no
                # kernel image loads and the abort this pre-empts cannot happen.
                # Deciding it from the request over-refused -- speculative "auto", a
                # --no-mmproj-offload projector and a --spec-draft-ngl 0 drafter all
                # read as GPU-bearing there, only the resolved argv knows. Still
                # before every spawn below and outside the fit's try/except, so the
                # refusal cannot be swallowed into the --fit on fallback.
                if not (_cpu_only_zero_offload or _arch_gate_forced_cpu):
                    _sm_gate = self._cuda_sm_gate_error(binary)
                    if _sm_gate:
                        raise RuntimeError(_sm_gate)
                # The arch gate emptying the pool lands here for the same reason
                # (#7624): no device set this binary can launch on, so the child must
                # not see the cards it would enumerate and abort on. gpu_indices is
                # None there, so this branch writes the mask.
                if _cpu_only_zero_offload or _arch_gate_forced_cpu:
                    self._emit_child_gpu_visibility(env, "-1")
                    # Manual mode admits tensor parallelism on the FULL device count,
                    # which still counts the dropped cards, so --split-mode tensor can
                    # reach a child that sees none. llama_prepare_model_devices then
                    # fails with "LLAMA_SPLIT_MODE_TENSOR needs >= 1 devices" and
                    # llama-server exits 1 rather than falling back, so normalise to
                    # layer/CPU. Gate-scoped: the zero-offload arm already dropped
                    # Unsloth's flags, and a user --split-mode there is overridden.
                    _cpu_cmd = (
                        self._without_flags(cmd, ("--split-mode", "-sm", "--tensor-split", "-ts"))
                        if _arch_gate_forced_cpu
                        else None
                    )
                    if _cpu_cmd is not None:
                        logger.info(
                            "Forced-CPU launch: dropped the split-mode/tensor-split "
                            "flags, which abort a server with no visible device."
                        )
                        cmd = _cpu_cmd
                        # Recorded, or the next Apply reads the normalized server as a
                        # different one and rebuilds a multi-GB model every time.
                        if self._tensor_parallel:
                            self._arch_gate_dropped_tensor_parallel = True
                        if self._tensor_split:
                            self._arch_gate_dropped_tensor_split = tuple(self._tensor_split)
                        self._tensor_parallel = False
                        self._tensor_split = None
                    if _arch_gate_forced_cpu:
                        # Not gated on the argv strip: llama.cpp reads the LLAMA_ARG_*
                        # twins whether or not we emitted the flags, so an inherited
                        # tensor mode aborts a child with no visible device on its own.
                        self._clear_split_placement_env(env)
                elif gpu_indices is not None and not is_vulkan_backend:
                    # When the user picked GPUs by index, align CUDA's ordering with
                    # the PCI-bus order the picker enumerated, so "GPU 1" in the UI is
                    # GPU 1 to llama.cpp, not CUDA's FASTEST_FIRST default (#5025).
                    if gpu_ids:
                        env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
                    # Mask on AMD at the ROCr/HSA layer: HIP-only masking still
                    # enumerates every agent first, which segfaults on a deselected
                    # unsupported GPU (e.g. gfx1036 iGPU under a gfx103X prebuilt).
                    self._emit_child_gpu_visibility(
                        env, ",".join(str(i) for i in gpu_indices), prefer_rocr = True
                    )
                    _launch_pinned_ids = list(gpu_indices)
                elif not is_vulkan_backend and not gpu_ids:
                    # Nothing above pinned the child. Two shapes land here and the gate
                    # breaks both the same way, so they share one probe: `--fit on`
                    # owning placement, and a manual per-GPU ratio across ALL GPUs.
                    # Either way gpu_indices is None, the reactive retry's guard cannot
                    # fire, and an uncovered card reaches the child. gpu_ids is falsy
                    # by construction, an explicit pick taking the arm above.
                    _survivors = self._arch_gate_survivors(binary)
                    if _survivors:
                        # The manual ratio was validated against the FULL visible
                        # count and masking re-indexes the survivors under it -- the
                        # positional mismatch _without_tensor_split exists for. Drop it
                        # and let llama.cpp split the survivors by free VRAM.
                        _gated_cmd = self._without_tensor_split(cmd)
                        if _gated_cmd is not None:
                            logger.warning(
                                "Dropping the manual --tensor-split: it was sized "
                                "for every visible GPU, and the installed build "
                                "has no kernels for some of them."
                            )
                            cmd = _gated_cmd
                            # The argv lost the ratio but the request still carries
                            # it and the next Apply re-sends it verbatim. Record it, or
                            # the duplicate-load check reads the normalized server as a
                            # different one and rebuilds it on every Apply.
                            self._arch_gate_dropped_tensor_split = (
                                tuple(self._tensor_split) if self._tensor_split else None
                            )
                            self._tensor_split = None
                        # Narrowing to one survivor leaves --split-mode tensor a no-op
                        # still REPORTED as active (tensor_parallel drives the UI and
                        # arms the MTP crash watchdog), manual mode having admitted it
                        # on the FULL device count. _without_tensor_split takes only the
                        # ratio, so drop the mode too, as the arch-crash retry does.
                        if len(_survivors) < 2 and self._tensor_parallel:
                            _no_tensor_mode = self._without_flags(cmd, ("--split-mode", "-sm"))
                            if _no_tensor_mode is not None:
                                cmd = _no_tensor_mode
                            self._arch_gate_dropped_tensor_parallel = True
                            self._tensor_parallel = False
                            logger.info(
                                "The arch gate leaves one GPU; dropped tensor "
                                "parallelism, which needs at least two."
                            )
                        logger.info(
                            "The installed llama.cpp build has no kernels for GPU(s) "
                            "left visible; pinning the child to %s.",
                            _survivors,
                        )
                        # The argv strips above cannot reach an inherited split
                        # mode or ratio, and the mask re-indexes the survivors
                        # under both.
                        self._clear_split_placement_env(env)
                        # GGML_CUDA_ENABLE_UNIFIED_MEMORY was decided against
                        # gpu_indices, None here, so an uncovered APU anywhere on the
                        # host turned it on -- and this narrowing hands the child only
                        # discrete cards, where _amd_apu_wants_unified_memory's docstring
                        # calls it harmful. Same withdrawal and ownership check as the
                        # arch-crash retry: only the value THIS launch set.
                        if _unified_env_applied and not self._amd_apu_wants_unified_memory(
                            _survivors
                        ):
                            env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None)
                            _unified_env_applied = False
                            logger.info(
                                "Arch gate narrowed the launch to discrete GPU(s); "
                                "dropped GGML_CUDA_ENABLE_UNIFIED_MEMORY."
                            )
                        self._emit_child_gpu_visibility(
                            env, ",".join(str(i) for i in _survivors), prefer_rocr = True
                        )
                        # Narrower than any pin above, so it replaces it.
                        _launch_pinned_ids = list(_survivors)
                    elif manual_tensor_split_emitted:
                        # A manual per-GPU ratio across ALL GPUs (no explicit pick, so
                        # no mask above): the UI built --tensor-split in ascending
                        # physical/PCI order, so pin the child's enumeration to match.
                        # The whole visible set stays in use, only its order is fixed.
                        self._pin_visible_gpu_order_for_split(env)

                _child_has_no_gpu = (
                    # each names a device present but unusable, so it owns the empty pool
                    _arch_gate_forced_cpu
                    or _paravirtual_cpu_forced
                    # neither says a device exists, so an empty pool stays unreadable
                    or (
                        bool(_detected_gpus)
                        and (
                            _cpu_only_zero_offload or self._binary_ships_no_gpu_backend(binary, env)
                        )
                    )
                )
                # The host pool as it stands before ANYTHING spawns, kept for the Vulkan
                # CPU replay to re-price against. That replay only runs once a CPU-only
                # child is healthy and holding the whole model in system RAM, where a
                # live reading is the pool minus the very model being priced. Taken
                # here, and handed to the guard below as well, so the two verdicts
                # differ in exactly one term -- the VRAM credit the replay loses -- and
                # never in the pool they were read against. Only on the path that can
                # use it: a load with no CPU replay available pays for no probe, and
                # None restores the guard's own live reading.
                _preflight_avail_mib = (
                    self._available_system_memory_mib() if _cpu_fallback_eligible else None
                )
                # Only the cards this child can reach. VRAM on a card this launch
                # pinned away is not VRAM it can spend: crediting it prices the spill
                # too low and leaves an unmapped oversized load unrewritten, which is
                # an OOM rather than the slow load the override exists to produce.
                _reachable_gpus = self._rows_the_child_can_reach(_detected_gpus, _launch_pinned_ids)
                # reads the argv the child gets, not the mid-fit state that produced it
                _offload_msg = self._launch_host_shortfall_message(
                    cmd,
                    _reachable_gpus,
                    env,
                    child_has_no_gpu = _child_has_no_gpu,
                    avail_mib = _preflight_avail_mib,
                    shared_gpu_ids = _shared_gpu_ids,
                )
                # Snapshotted BEFORE the override note is appended below, so a re-price
                # that promotes this notice appends that note once rather than twice.
                _host_ram_msg = _offload_msg

                def _launch_is_oversized() -> bool:
                    """Whether SOMETHING about to launch does not fit, warning aside.

                    Three readings, because one alone misses a shape the override has
                    to cover. The APU preflight, whose shortfall this guard cannot see:
                    _shared_gpu_ids covers Vulkan only, so a ROCm APU's reported pool is
                    credited here as if it were dedicated VRAM and the spill prices out
                    at zero. The warning just produced, which is the discrete case. And,
                    only when the deprecated opt-out silenced that warning, the same
                    pricing with the opt-out ignored: the variable's contract is that it
                    hides a message, and hiding a message must not withdraw the rewrite
                    that makes the load possible.
                    """
                    if _apu_ram_oversized or _offload_msg:
                        return True
                    if not self._host_offload_warning_opted_out():
                        return False
                    return bool(
                        self._launch_host_shortfall_message(
                            cmd,
                            _reachable_gpus,
                            env,
                            child_has_no_gpu = _child_has_no_gpu,
                            shared_gpu_ids = _shared_gpu_ids,
                            honor_opt_out = False,
                        )
                    )

                cmd, _pageable_note = self._page_an_oversized_unmapped_load(
                    cmd, env, _launch_is_oversized
                )
                if _pageable_note:
                    # Only onto a warning that is actually emitted; when the opt-out
                    # suppressed it the override still went to the log, which is what
                    # keeps a silenced load traceable.
                    if _offload_msg:
                        _offload_msg += _pageable_note
                    # And onto whatever is already recorded, which is not the same
                    # thing. First notice wins, so when the APU preflight also warned
                    # its text is what the route hands back and the _offload_msg
                    # amended just above is dropped by _record_load_warning below --
                    # leaving memory_warning silent about an override that did change
                    # the child's argv. A no-op when nothing was recorded, including a
                    # load the opt-out silenced, and it cannot double-append: the note
                    # reaches at most one of the two strings.
                    self._amend_load_warning(_pageable_note)
                    # The recorded state has to describe the argv that launches, or the
                    # reload comparator judges this child against a mode it no longer
                    # runs. The snapshot too: the arch-crash retry restores it over
                    # `cmd`, which now carries the override.
                    self._memory_state = resolve_effective_memory_state(cmd, env)
                    _mem_policy_for_cmd = (
                        _mem_host_resident,
                        self._memory_state,
                        self._memory_policy_active,
                        self._memory_mlock_applicable,
                    )
                self._record_load_warning(_offload_msg)

                # Captured before any text-only fallback strips it from cmd.
                launched_with_mmproj = "--mmproj" in cmd

                # One-shot --fit off retry: recent llama.cpp runs a "fitting
                # params to device memory" step by default (--fit defaults to
                # 'on') even when -ngl is explicit. That step has aborted on
                # some ROCm hosts (ggml-cuda.cu ROCm error during worst-case
                # estimation, e.g. MTP + mmproj models on gfx1151). When
                # Unsloth's own VRAM math already placed the model
                # (use_fit=False), the step is redundant second-guessing --
                # retry once with --fit off before declaring the load failed.
                # Never retry when fit was requested (use_fit) or the caller
                # passed an explicit fit flag via extra args.
                # Argv actually launched (post --fit off / MTP); text-only retry strips this.
                _last_spawn_cmd = list(cmd)
                _spawn_cwd: Optional[str] = None
                # Load-scoped, not per call: the correction edits the shared env,
                # so it outlives this spawn, and the launch that finally comes up
                # healthy is often a later one (drafterless, no-flash, arch
                # fallback). A per-call flag left those successes unrecorded.
                _did_rocm_retry = False

                def _drop_fit_load_mode_for_no_flash(fa_cmd: list) -> list:
                    """The fit's ``--load-mode none`` off a --flash-attn off respawn.

                    The FA-off rewrite changes the very footprint the fit priced. On an
                    MLA model it takes the K cache down to f16 with V, because llama.cpp
                    rejects a split K/V there before it rejects a quantized V without
                    flash attention (llama-context.cpp checks type_k == type_v first),
                    and the MLA branch of the KV estimator prices that latent cache at
                    the K width alone. The non-flash attention path also materialises a
                    full [n_kv, n_ubatch, n_head] F32 KQ tensor (llama-graph.cpp
                    build_attn_mha) that the flash-attn-shaped compute-buffer estimate
                    does not model. Under an active fitter the child answers a bigger
                    requirement by offloading fewer layers and spilling more weights to
                    host RAM, where "--load-mode none" makes them anonymous rather than
                    file-backed: an OOM kill where the mapping would only have paged.

                    Only Unsloth's own tokens; a user's --load-mode is theirs. The
                    record is NOT cleared, for the same reason the --fit on retry keeps
                    it: the CPU fallback below still respawns from an argv that carries
                    these tokens and has to be able to name them. Stripping an
                    already-stripped argv is a no-op.
                    """
                    if not self._fit_load_mode_flags:
                        return fa_cmd
                    stripped = _without_subsequence(fa_cmd, self._fit_load_mode_flags)
                    if stripped != fa_cmd:
                        # The record follows the argv: without "none" the child is back
                        # on llama.cpp's auto, which maps, so a record still saying
                        # "reserving" spends a full reload on the next "Don't reserve
                        # system RAM". From the argv, not _mem_managed + _mem_extras:
                        # this descends from _last_spawn_cmd, which carries any page-lock
                        # the --fit on retry appended, and rebuilding would drop it.
                        self._memory_state = resolve_effective_memory_state(stripped, env)
                        logger.info(
                            "Load mode: dropping the fit's --load-mode none for the "
                            "--flash-attn off retry; the no-flash launch has a "
                            "footprint the fit did not price."
                        )
                    return stripped

                def _spawn_and_wait(run_cmd, *, label = ""):
                    """Start llama-server with run_cmd and wait for health.

                    Up to three launches: the first, one ROCm env correction,
                    and one --fit recovery. Separate flags, so a library mix
                    does not spend the fit slot and a VRAM crash after the
                    correction can still fit-retry.
                    """
                    # _mem_host_resident too: the --fit on retry re-arms the
                    # page-lock and writes it back, which without this makes the
                    # read below an UnboundLocalError instead.
                    nonlocal _last_spawn_cmd, _mem_host_resident, _did_rocm_retry
                    # One revocation point for the tensor-spill plan instead of a
                    # strip per retry site. `label` is empty ONLY on the first
                    # spawn, so a retry added later is covered automatically. The
                    # plan's arithmetic assumed this launch's devices, cache dtype
                    # and projector placement, and each retry changes one of them.
                    if label:
                        run_cmd = self._drop_tensor_spill(run_cmd, label.lstrip("-") or "retry")
                    _fit_retry_allowed = self._fit_off_retry_eligible(run_cmd, use_fit)
                    _did_fit_retry = False
                    for _spawn_attempt in (0, 1, 2):
                        # Defensive kill: drop an orphan Popen a concurrent load may
                        # have stored before we overwrite the reference (#5161).
                        # Also reaps the crashed first attempt on the retry pass.
                        self._kill_process()

                        self._stdout_lines = []
                        # Tee llama-server output to a dedicated log file so a
                        # post-mortem has the full trail even when the parent only
                        # kept the last 50 lines. Path is under the studio home.
                        # ``label`` (MTP fallback) and the attempt index (--fit
                        # off retry) keep a respawn within the same epoch second
                        # from truncating the crash log a retry warning just
                        # pointed the user at.
                        self._llama_log_fh = None
                        try:
                            log_dir = _swa_cache_path().parent / "logs" / "llama-server"
                            log_dir.mkdir(parents = True, exist_ok = True)
                            self._llama_log_path = log_dir / (
                                f"llama-{int(time.time())}{label}-port-{self._port}"
                                f"-try{_spawn_attempt}.log"
                            )
                            self._llama_log_fh = open(
                                self._llama_log_path,
                                "w",
                                encoding = "utf-8",
                                buffering = 1,
                            )
                            # After the open, so the cap counts this file and never deletes
                            # it. On the retry path the earlier attempts' logs are what a
                            # reader wants, and keep-newest holds on to them.
                            prune_log_dir(log_dir, "llama-*.log", protect = self._llama_log_path)
                            logger.info(f"llama-server stdout/stderr -> {self._llama_log_path}")
                        except (OSError, UnicodeDecodeError) as e:
                            # Best-effort; never block the load on logging.
                            logger.debug(f"Could not open llama-server log file: {e}")
                            self._llama_log_path = None
                        _last_spawn_cmd = list(run_cmd)
                        self._process = subprocess.Popen(
                            run_cmd,
                            stdout = subprocess.PIPE,
                            stderr = subprocess.STDOUT,
                            text = True,
                            encoding = "utf-8",
                            errors = "replace",
                            env = env,
                            cwd = _spawn_cwd,
                            **_windows_hidden_subprocess_kwargs(),
                            **_child_popen_kwargs(),
                        )
                        self._record_server_pid(self._process.pid)
                        # is_active covers it from here, so drop the pre-spawn flag.
                        self._memory_launch_pending = False

                        # Background thread to drain stdout (prevents pipe deadlock)
                        self._stdout_thread = threading.Thread(
                            target = self._drain_stdout, daemon = True, name = "llama-stdout"
                        )
                        self._stdout_thread.start()
                        if self._wait_for_health(timeout = 600.0):
                            if _did_rocm_retry:
                                # Proved on this host: every later child skips the
                                # prepend instead of crashing into it first.
                                self._remember_bundle_only_rocm(binary)
                            return True
                        _startup_crashed = (
                            self._process.poll() is not None and self._process.returncode != 0
                        )
                        # A split-axis abort (#6415) is fit-independent: skip the
                        # --fit off retry and let the caller latch it. So is a
                        # pre-b9455 build refusing a quantized KV cache in tensor mode:
                        # a capability the binary lacks, where re-spawning to let it
                        # offload spends a second full model load on a theory unrelated
                        # to the failure. The caller latches both, so both skip alike.
                        _startup_output = "\n".join(self._stdout_lines[-50:])
                        _tensor_capability_crash = self._is_tensor_split_assert(
                            _startup_output
                        ) or self._is_tensor_quant_kv_unsupported(_startup_output)
                        _hip_rocr_mismatch = self._is_bundled_hip_rocr_mismatch(_startup_output)
                        if (
                            not _did_rocm_retry
                            and _startup_crashed
                            and not _tensor_capability_crash
                            and _hip_rocr_mismatch
                        ):
                            # The prepend is what a shell launch does not do, which
                            # is why the same binary runs from a terminal. Drop
                            # those dirs only: the rest of env holds the pooling
                            # and memory scrubs.
                            _bundle_only = self._llama_server_env_for_binary(
                                binary, use_system_rocm = False
                            )
                            _retry_ld = _bundle_only.get("LD_LIBRARY_PATH", "")
                            # "" on a host that never had the var: nothing to undo.
                            if _retry_ld and _retry_ld != env.get("LD_LIBRARY_PATH"):
                                logger.warning(
                                    "llama-server crashed during startup (exit code %s) "
                                    "because a bundled ROCm library could not resolve a "
                                    "symbol against the system ROCm; retrying once "
                                    "with the bundled runtime only. Crash log: %s",
                                    self._process.returncode,
                                    self._llama_log_path,
                                )
                                env["LD_LIBRARY_PATH"] = _retry_ld
                                _did_rocm_retry = True
                                continue
                        if (
                            not _did_fit_retry
                            and _startup_crashed
                            and not _tensor_capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            # A spill-planned launch that crashed on startup. The
                            # two recoveries below cannot reach it: the spill arm
                            # leaves fully_gpu_offloaded False and runs under
                            # use_fit=True with an explicit --fit, so
                            # _fit_off_retry_eligible is False on both counts and
                            # the load would skip to the terminal/CPU fallbacks
                            # even though the --fit on placement it replaced would
                            # have worked. A crash means the prediction was wrong,
                            # so hand placement back to llama.cpp. Self-gating:
                            # _drop_tensor_spill returns run_cmd unchanged when no
                            # plan is present.
                            _reverted = self._drop_tensor_spill(run_cmd, "startup failure")
                            if _reverted != run_cmd:
                                logger.warning(
                                    "llama-server crashed during startup (exit code %s) "
                                    "with a tensor-spill plan; the plan was optimistic, "
                                    "retrying once with --fit on so llama.cpp can place "
                                    "the model itself. Crash log: %s",
                                    self._process.returncode,
                                    self._llama_log_path,
                                )
                                run_cmd = _reverted
                                self._memory_state = resolve_effective_memory_state(run_cmd, env)
                                _did_fit_retry = True
                                continue
                        if (
                            not _did_fit_retry
                            and fully_gpu_offloaded
                            and _startup_crashed
                            and not _tensor_capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            # We forced --fit off because Unsloth's (conservative) VRAM
                            # math placed the model fully on GPU. A startup crash here
                            # means that estimate was optimistic, so fall back to --fit
                            # on and let llama.cpp offload rather than fail the load.
                            # DSpark takes this path too: fitting only skips its
                            # unmeasurable sidecar reserve, the drafter still loads.
                            logger.warning(
                                "llama-server crashed during startup (exit code %s) "
                                "with forced --fit off; the fit estimate was optimistic, "
                                "retrying once with --fit on so it can offload. "
                                "Crash log: %s",
                                self._process.returncode,
                                self._llama_log_path,
                            )
                            # Flip Unsloth's own --fit off (added first, before any
                            # user extra args) to on; a user's later --fit still wins
                            # by last-arg. Defensive: if absent, the default is already
                            # --fit on, so leave it.
                            _run = list(run_cmd)
                            if "--fit" in _run:
                                _run[_run.index("--fit") + 1] = "on"
                            # Same reasoning as the page-lock below, one step
                            # earlier: the fit picked "none" because it had proved
                            # the load fits, and that proof is what just failed, so
                            # give the retry llama.cpp's auto back. Only Unsloth's
                            # own tokens; a user's --load-mode is untouched.
                            if self._fit_load_mode_flags:
                                _run = _without_subsequence(_run, self._fit_load_mode_flags)
                                # The record is NOT cleared: it describes `cmd`, which
                                # this retry never touched and the arch-crash and CPU
                                # fallbacks respawn from, so clearing here would leave
                                # them carrying a --load-mode none they can no longer
                                # name. Stripping an already-stripped argv is a no-op.
                                logger.info(
                                    "Load mode: dropping the fit's --load-mode none "
                                    "for the --fit on retry; the fit it was derived "
                                    "from did not hold."
                                )
                            # The full-offload prediction that suppressed the
                            # page-lock was the very thing that just proved
                            # wrong, so llama.cpp may now leave weights in host
                            # RAM. Re-arm residency for the retry (last-wins, so
                            # appending is enough) and re-record the state.
                            if should_mlock() and not _mem_host_resident:
                                _run.extend(
                                    ["--load-mode", "mmap+mlock"]
                                    if server_caps.get("supports_load_mode")
                                    else ["--mlock"]
                                )
                                _mem_host_resident = True
                                self._memory_mlock_applicable = True
                                self._memory_policy_active = True
                                logger.info(
                                    "Model Memory: re-applying the page-lock for "
                                    "the --fit on retry; the full-offload "
                                    "prediction did not hold."
                                )
                            run_cmd = _run
                            self._memory_state = resolve_effective_memory_state(_run, env)
                            _did_fit_retry = True
                            continue
                        if (
                            not _did_fit_retry
                            and _fit_retry_allowed
                            and _startup_crashed
                            and not _tensor_capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            logger.warning(
                                "llama-server crashed during startup (exit code %s) "
                                "with the default memory-fit step enabled; Unsloth "
                                "already verified the model fits, retrying once "
                                "with --fit off. Crash log: %s",
                                self._process.returncode,
                                self._llama_log_path,
                            )
                            run_cmd = [*run_cmd, "--fit", "off"]
                            # The mirror of the --fit on retry above. Turning the
                            # fitter off leaves -ngl at its default, which llama.cpp
                            # resolves to every layer, so the fitted attempt's
                            # host-resident verdict can stop holding. Drop a
                            # page-lock the retry no longer needs rather than
                            # reserving a full host copy of a fully offloaded model.
                            if _mem_managed and _mem_host_resident:
                                if not self._weights_in_host_memory(
                                    fully_gpu_offloaded = True,
                                    gpu_memory_mode = gpu_memory_mode,
                                    gpu_layers = gpu_layers,
                                    extra_args = _mem_extra_args,
                                    gpu_indices = gpu_indices,
                                    is_vulkan_backend = is_vulkan_backend,
                                    binary = binary,
                                    env = _mem_env,
                                ):
                                    run_cmd = _without_subsequence(run_cmd, _mem_managed)
                                    _mem_host_resident = False
                                    # Recorded so a later "keep resident" save is not
                                    # compared against a lock this launch dropped,
                                    # which would demand a pointless reload.
                                    self._memory_mlock_applicable = False
                                    # The managed flag was the policy's only mark on
                                    # this child unless it also scrubbed or stripped,
                                    # and a child equal to an unmanaged one must not
                                    # be torn down when the toggles go off.
                                    self._memory_policy_active = _mem_policy_touched_extras
                                    logger.info(
                                        "Model Memory: dropping the page-lock for "
                                        "the --fit off retry; it offloads every layer."
                                    )
                                self._memory_state = resolve_effective_memory_state(run_cmd, env)
                            _did_fit_retry = True
                            continue
                        return False

                _launched_mmproj_has_audio = self._mmproj_has_audio

                def _raise_terminal_load_failure(detail: str) -> NoReturn:
                    if intent.cpu_fallback:
                        self._cleanup_failed_cpu_fallback()
                    # No child will carry this budget; left set, the route reads it
                    # ahead of is_active and asks for a reload with nothing loaded.
                    self._vram_fraction_pending = None
                    raise RuntimeError(detail)

                def _try_auto_vulkan_cpu_fallback(
                    failed_cmd: list[str],
                    failed_rc: Optional[int],
                    *,
                    terminal: bool = True,
                ) -> bool:
                    """Replay an eligible signal crash without devices.

                    ``terminal`` off reports a failed CPU spawn as "not recovered"
                    instead of raising, for a caller that still holds another argv
                    worth replaying.
                    """
                    nonlocal intent, gpu_memory_mode, gpu_layers, n_cpu_moe
                    nonlocal _replay_pageable_override
                    nonlocal tensor_parallel, tensor_split, gpu_indices, use_fit, _spawn_cwd
                    # GGML_ASSERT is a signal on POSIX and a CRT abort (exit 3) on
                    # MSVC, so Windows needs both. Cancel-checked like every retry
                    # here: an /unload racing the crash must not leave a server up.
                    _crashed = self._is_signal_crash(failed_rc) or (
                        sys.platform == "win32" and self._is_abort_exit(failed_rc)
                    )
                    if not _crashed or not _cpu_fallback_eligible or _load_cancelled():
                        return False
                    fallback_has_mmproj = self._launch_has_mmproj(failed_cmd, env)
                    prepared = self._prepare_cpu_fallback_launch(
                        binary,
                        failed_cmd,
                        env,
                        server_caps,
                        drop_full_offload_threads = _drop_full_offload_threads,
                        # The same host pool the preflight and the reprice below read,
                        # so the rewrite and the advisory answer one question once.
                        avail_mib = _preflight_avail_mib,
                    )
                    if prepared is None:
                        return False
                    if _load_cancelled():
                        # Staging copies a whole runtime, so an /unload can land after
                        # the gate above with no runtime yet for unload_model() to
                        # remove; take it back here.
                        self._cleanup_cpu_fallback_runtime()
                        return False
                    replay, _spawn_cwd, _cpu_pageable_note = prepared
                    # The rewrite mutates the SHARED env in place, so it happens once
                    # even when several argvs are replayed. A non-terminal failure
                    # below returns without the note, and the next replay then finds an
                    # already-pageable env and produces none of its own -- so whichever
                    # attempt finally comes up would report ordinary paging and never
                    # say the user's load mode had been overridden. Carried instead.
                    if _cpu_pageable_note:
                        _replay_pageable_override = _cpu_pageable_note
                    _cpu_pageable_note = _cpu_pageable_note or _replay_pageable_override

                    logger.warning(
                        "The auto-selected Vulkan backend hard-crashed during "
                        "startup; retrying once with llama.cpp devices disabled."
                    )
                    if not _spawn_and_wait(replay, label = "-cpu"):
                        if not terminal:
                            # This argv's drafter may be why it cannot start at all,
                            # which the GPU crash says nothing about. Reap the child
                            # and keep the staged runtime for the caller's next argv.
                            self._kill_process()
                            return False
                        cpu_rc = self._process.poll() if self._process is not None else None
                        detail = self._classify_llama_start_failure(
                            "\n".join(self._stdout_lines[-50:]),
                            gguf_path,
                            self._model_identifier,
                            cpu_rc,
                            binary,
                            self._llama_log_path,
                            (self._api_key,),
                            self._extra_args,
                        )
                        self._cleanup_failed_cpu_fallback()
                        self._vram_fraction_pending = None
                        raise RuntimeError(detail)

                    # The replay dropped the fit's --load-mode none, so a record taken
                    # off the launch argv describes a reservation this child does not
                    # make, and a later "Don't reserve system RAM" would demand a
                    # pointless reload. From _last_spawn_cmd, the argv that really
                    # started, so this cannot undo a record a --fit retry wrote.
                    #
                    # Or the pageable override rewrote a mode this replay no longer runs
                    # with: the record has to describe the argv that started, whichever
                    # of the two changed it, or the reload comparator judges this child
                    # against a mode it does not have.
                    if self._fit_load_mode_flags or _cpu_pageable_note:
                        self._memory_state = resolve_effective_memory_state(_last_spawn_cmd, env)
                    intent = self._apply_cpu_fallback_state(
                        intent,
                        is_vision = fallback_has_mmproj,
                        mmproj_has_audio = (
                            _launched_mmproj_has_audio if fallback_has_mmproj else False
                        ),
                        disable_vision = disable_vision,
                        # The same expression the load's own assignment uses, since the
                        # replay carries the same switch and the same dropped projector.
                        vision_disabled_by_user = bool(
                            is_vision and disable_vision and _dv_dropped_image_projector
                        ),
                    )
                    gpu_memory_mode = intent.gpu_memory_mode
                    gpu_layers = intent.gpu_layers
                    n_cpu_moe = intent.n_cpu_moe
                    tensor_parallel = intent.tensor_parallel
                    tensor_split = intent.tensor_split
                    gpu_indices = None
                    use_fit = False
                    # Everything above records that this session runs on no GPU; the
                    # advisory has to say so too. Here and not at the decision above,
                    # because only a child that came up is evidence of what is running
                    # and a failed replay can still fall through to another argv.
                    self._reprice_after_cpu_only_fallback(
                        host_msg = _host_ram_msg,
                        cpu_cmd = _last_spawn_cmd,
                        env = env,
                        avail_mib = _preflight_avail_mib,
                        pageable_note = _cpu_pageable_note,
                    )
                    logger.warning(
                        "llama-server loaded successfully on CPU after the "
                        "auto-selected Vulkan backend crashed. GPU acceleration "
                        "is disabled for this model session."
                    )
                    return True

                # Store the resolved on-disk path, not the caller's kwarg: in
                # HF mode gguf_path is None and ``model_path`` is what
                # llama-server mmap's, which downstream consumers need. Must be
                # set BEFORE the spawn: load_progress() reads _gguf_path for
                # the mmap progress total while the health wait runs.
                self._gguf_path = model_path
                self._gguf_load_identity = self._gguf_load_source_identity(model_path, mmproj_path)
                self._hf_repo = hf_repo
                self._mtp_draft_path = launch_mtp_draft_path
                self._mtp_draft_suppressed_path = _pv_suppressed_draft_path
                # For local GGUF files, extract variant from filename if absent
                if hf_variant:
                    self._hf_variant = hf_variant
                elif gguf_path:
                    try:
                        from utils.models.model_config import _extract_quant_label
                        self._hf_variant = _extract_quant_label(gguf_path)
                    except Exception:
                        self._hf_variant = None
                else:
                    self._hf_variant = None
                self._is_vision = effective_is_vision
                self._disable_vision = bool(disable_vision)
                # is_vision, NOT effective_is_vision: the latter means "a projector is
                # attached", which this load deliberately made false, so it would report
                # False for the one case this field exists to describe. The intent flag
                # is the model's own capability.
                #
                # Three cases must NOT blame the switch, because turning it back on
                # would not restore images: a text-only GGUF with a stale toggle, an
                # audio-only projector (kept on purpose, no image encoder), and an
                # advanced argument that drops the projector (nothing reads the file, so
                # the capability default stays True). All three fall through to the
                # generic "cannot accept images".
                #
                # So this is one signal recorded where the decision was made rather than
                # re-derived from state that cannot tell the cases apart: True only where
                # a usable image projector was resolved and the switch dropped it. None
                # of the three reaches that assignment.
                self._vision_disabled_by_user = bool(
                    is_vision and disable_vision and _dv_dropped_image_projector
                )
                self._model_identifier = model_identifier

                # Store the effective (possibly capped) context separately; do
                # NOT overwrite _context_length (the native length for display).
                self._effective_context_length = (
                    effective_ctx if effective_ctx > 0 else self._context_length
                )
                self._max_context_length = (
                    max_available_ctx if max_available_ctx > 0 else self._effective_context_length
                )

                # LoadRequest carries this flag, so a stale rollback, an API caller or
                # a swapped-out runtime can ask for a replay that never happened. Hold
                # it to the crash path's bar (managed auto Vulkan, no explicit
                # placement) and otherwise run the request as sent.
                if intent.cpu_fallback:
                    if self._auto_vulkan_cpu_fallback_eligible(
                        binary, intent, extra_args, env, allow_manual_cpu = True
                    ):
                        prepared = self._prepare_cpu_fallback_launch(
                            binary,
                            cmd,
                            env,
                            server_caps,
                            drop_full_offload_threads = _drop_full_offload_threads,
                            avail_mib = _preflight_avail_mib,
                        )
                        if prepared is None:
                            _raise_terminal_load_failure(
                                "The prior Vulkan CPU fallback could not be reconstructed; run "
                                "`unsloth studio update` to repair the managed llama.cpp runtime."
                            )
                        cmd, _spawn_cwd, _replay_pageable_note = prepared
                        # Same reason as the crash path, recomputed from the stripped
                        # `cmd` before anything spawns. The arch-crash rung re-derives it
                        # from `cmd` too, so the _mem_policy_for_cmd snapshot it restores
                        # cannot put the stale pair back. The pageable override rewrites
                        # the same field, so either one having fired makes the record stale.
                        if self._fit_load_mode_flags or _replay_pageable_note:
                            self._memory_state = resolve_effective_memory_state(cmd, env)
                        # The preflight above priced and, where needed, rewrote the argv
                        # this replay was built FROM; an override settled here is news it
                        # could not have carried. Appended to whatever notice is recorded,
                        # the same way the APU preflight's override reaches the message,
                        # and a no-op on a load whose warning the opt-out silenced, which
                        # keeps the log line as its only record.
                        self._amend_load_warning(_replay_pageable_note)
                        # This replay is CPU-only by construction (--device none), so
                        # the advisory has to describe the whole model in host RAM. The
                        # amend above can only add to a notice that already exists, and
                        # on a restored fallback there often is none: an empty Vulkan
                        # probe leaves _child_has_no_gpu False, so the preflight
                        # abstained and memory_warning was null for a session paging
                        # everything from disk. Deferred rather than priced here,
                        # because only a child that came up is evidence of what runs.
                        _restored_cpu_reprice = _replay_pageable_note or True
                        # Same normalization the crash path applies, so a client that
                        # sent only the flag cannot leave a CPU-only server reporting
                        # an Auto/GPU placement (which then fails holds_no_vram).
                        intent = self._apply_cpu_fallback_state(
                            intent,
                            is_vision = self._is_vision,
                            mmproj_has_audio = self._mmproj_has_audio,
                            disable_vision = disable_vision,
                            vision_disabled_by_user = bool(
                                is_vision and disable_vision and _dv_dropped_image_projector
                            ),
                        )
                        gpu_memory_mode = intent.gpu_memory_mode
                        gpu_layers = intent.gpu_layers
                        n_cpu_moe = intent.n_cpu_moe
                        tensor_parallel = intent.tensor_parallel
                        tensor_split = intent.tensor_split
                        gpu_indices = None
                        use_fit = False
                    else:
                        # Phase 1 kept recovery state for a replay this request does
                        # not qualify for. Drop it, or this load reports the old crash
                        # and _preserve_cpu_fallback_intent rewrites later reloads.
                        intent = replace(intent, cpu_fallback = False)
                        self._cpu_fallback_reason = None
                        self._cleanup_cpu_fallback_runtime()
                # The placement above is now fixed for this child, but _process
                # is not set until Popen. Without this, a save landing in that
                # window sees no active backend and reports no reload while the
                # child is already committed. Popen clears it, and so does every
                # exit below, so a failed spawn cannot leave it stuck on.
                self._memory_launch_pending = True
                self._vram_fraction_pending = _budget_priced_placement()
                healthy = False
                try:
                    healthy = _spawn_and_wait(cmd)
                finally:
                    self._memory_launch_pending = False
                # #6415 split-mode tensor warmup abort. Latch it on THIS first spawn:
                # the flash-attn-off retry below can't run tensor (needs flash_attn),
                # so its output drops the marker and recording later would miss it,
                # looping every load. Record and raise to the route's layer fallback,
                # skipping the futile flash-attn/MTP retries.
                if not healthy and self._tensor_parallel and not _load_cancelled():
                    _ts_out = "\n".join(self._stdout_lines[-50:])
                    _ts_rc = self._process.poll() if self._process is not None else None
                    if self._should_record_tensor_split_abort(_ts_rc, _ts_out):
                        LlamaCppBackend._record_tensor_split_abort(
                            binary, model_identifier, _planned_cache_pair
                        )
                        self._kill_process()
                        raise RuntimeError(
                            "llama-server aborted on --split-mode tensor "
                            "(split-axis geometry); retrying with layer split."
                        )
                    # Pre-b9455 llama.cpp refusing a quantized KV cache in tensor mode.
                    # Latched on this first spawn for the same reason as the abort
                    # above: the retries below cannot fix a capability the binary
                    # lacks, and only the first spawn carries the marker.
                    if self._is_tensor_quant_kv_unsupported(_ts_out):
                        # Binary-wide: one detection spares every later model and
                        # every other quantized type the same doomed startup.
                        LlamaCppBackend._record_tensor_quant_kv_unsupported(binary)
                        self._kill_process()
                        raise RuntimeError(
                            "This llama.cpp build does not support a quantized KV "
                            "cache with --split-mode tensor (added in b9455, "
                            "ggml-org/llama.cpp#23792). Retrying with layer split; "
                            "update llama.cpp to use tensor parallelism with a "
                            "quantized cache."
                        )
                # "device kernel image is invalid": the auto-pinned device's arch has
                # no kernels in this binary (#7624: an iGPU whose shared-RAM "free
                # memory" outranked the dGPU). The proactive mapped_targets gate cannot
                # see custom-linked builds, so catch the crash and retry once on a
                # narrowed set. Auto selection only; an explicit pick keeps its error.
                if (
                    not healthy
                    and not self._cancel_event.is_set()
                    and not gpu_ids
                    and not is_vulkan_backend
                    and gpu_indices
                    and self._kernel_image_invalid("\n".join(self._stdout_lines[-80:]))
                ):
                    _crashed = sorted(set(gpu_indices))
                    # _detected_gpus, not gpus: the post-picker enumeration this launch
                    # planned against, and unlike `gpus` it survives the manual mode that
                    # empties the pool to bypass the planner.
                    _remaining = self._arch_crash_retry_gpu_ids(
                        gpu_indices, [i for i, _free in _detected_gpus]
                    )
                    if _remaining:
                        _retry_wants_unified = self._amd_apu_wants_unified_memory(_remaining)
                        # Everything recorded so far priced the CRASHED selection, and
                        # that placement is gone: the canonical #7624 shape pins the APU
                        # whose shared-pool "free memory" outranked the dGPU, warns that
                        # system RAM cannot hold the weights, then crashes and respawns
                        # on the discrete sibling that holds them in VRAM. First notice
                        # wins, so without this the served child reports a shortfall on
                        # a device it never touches. The two checks below price exactly
                        # the set the respawn reaches, and both are wider than their
                        # upstream twins (the same weights against a NARROWED pool), so
                        # a shortfall that still stands is re-recorded here.
                        #
                        # Both are also kept in a variable: the pageable-load override
                        # at the END of this block, after every rewrite `cmd` still has
                        # coming, reads them as its shortfall condition and amends
                        # whichever one first-notice-wins recorded.
                        self._begin_load_warnings()
                        # ...and the re-price snapshots go with the scope they describe:
                        # the preflight's pair priced the crashed placement, so leaving
                        # them standing would let the text-only fallback re-price the
                        # notice this block is about to record against the wrong pool.
                        _apu_ram_msg = None
                        _host_ram_msg = None
                        _apu_avail_mib = None
                        # The APU RAM preflight upstream ran against the CRASHED
                        # selection. The mirror shape (crash on the dGPU, retry on the
                        # unified-memory sibling) makes the respawn the first load into
                        # system RAM, so price it here too. Advisory: the respawn goes
                        # ahead either way.
                        _retry_apu_msg = None
                        if model_size is not None and _retry_wants_unified:
                            _apu_avail_mib = self._available_system_memory_mib()
                            _retry_apu_msg = self._apu_ram_shortfall_message(
                                model_size + _mmproj_pinned_bytes,
                                _apu_avail_mib,
                            )
                            # Same contract as the preflight above: the opt-out takes
                            # the message and nothing else. _retry_apu_msg itself stays
                            # set, so _retry_is_oversized below still sees the
                            # shortfall and the pageable rewrite still happens.
                            if not self._host_offload_warning_opted_out():
                                _apu_ram_msg = _retry_apu_msg
                                self._record_load_warning(_retry_apu_msg)
                        # host guard credited the whole pool; the respawn reaches only _remaining
                        _retry_rows = [row for row in _detected_gpus if row[0] in set(_remaining)]
                        _retry_host_msg = self._launch_host_shortfall_message(cmd, _retry_rows, env)
                        _host_ram_msg = _retry_host_msg
                        self._record_load_warning(_retry_host_msg)
                        logger.warning(
                            f"llama-server crashed with a HIP kernel-image error on "
                            f"GPU(s) {_crashed} -- the llama.cpp build has no kernels "
                            f"for that arch. Retrying on GPU(s) {_remaining}."
                        )
                        self._kill_process()
                        gpu_indices = _remaining
                        # GGML_CUDA_ENABLE_UNIFIED_MEMORY was decided for the CRASHED
                        # set. The canonical #7624 shape crashes on the APU and retries
                        # on the dGPU, where it is harmful, so withdraw it, but only
                        # the value this launch set. Both directions: a markerless
                        # mixed host can as easily crash on the dGPU and land on the
                        # APU, which needs it.
                        if _unified_env_applied and not _retry_wants_unified:
                            env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None)
                            _unified_env_applied = False
                            logger.info(
                                "Arch-crash retry targets discrete GPU(s); dropped "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY for the respawn."
                            )
                        elif (
                            _retry_wants_unified
                            and not _unified_opt_out  # the opt-out outlives the respawn
                            and "GGML_CUDA_ENABLE_UNIFIED_MEMORY" not in env
                        ):
                            env["GGML_CUDA_ENABLE_UNIFIED_MEMORY"] = "1"
                            _unified_env_applied = True
                            logger.info(
                                "Arch-crash retry targets a unified-memory APU; set "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY=1 for the respawn."
                            )
                        self._emit_child_gpu_visibility(
                            env, ",".join(str(i) for i in _remaining), prefer_rocr = True
                        )
                        # Same for the inherited env twins of the flags dropped
                        # below: the new mask re-indexes the survivors under them.
                        self._clear_split_placement_env(env)
                        # The mask re-indexes the survivors from 0, so a --tensor-split
                        # sized for the crashed set weights the wrong cards (see
                        # _without_tensor_split). Drop it and let llama.cpp split by
                        # free VRAM over the narrowed set.
                        _arch_retry_cmd = self._without_tensor_split(cmd)
                        if _arch_retry_cmd is not None:
                            logger.info(
                                "Dropped --tensor-split for the arch-crash retry: "
                                "its shares are positional over the visible "
                                "devices and the narrowed set re-indexes them."
                            )
                            cmd = _arch_retry_cmd
                            # No ratio record, unlike the proactive gate: _tensor_split
                            # is non-None only in manual mode, which leaves gpu_indices
                            # None, and this arm needs it truthy.
                            self._tensor_split = None
                        # A tensor split needs two devices, so narrowing to one makes
                        # --split-mode tensor a no-op still REPORTED as active
                        # (tensor_parallel drives the UI and the MTP watchdog). Strip it.
                        if len(_remaining) < 2 and self._tensor_parallel:
                            _no_tensor_mode = self._without_flags(cmd, ("--split-mode", "-sm"))
                            if _no_tensor_mode is not None:
                                cmd = _no_tensor_mode
                            self._arch_gate_dropped_tensor_parallel = True
                            self._tensor_parallel = False
                            logger.info(
                                "Arch-crash retry leaves one GPU; dropped tensor "
                                "parallelism, which needs at least two."
                            )
                        # The fit chose "none" because the WHOLE footprint fit the
                        # devices this launch PINNED, and the retry runs on a set that
                        # proof never covered. The two guards above are weights-only
                        # floors and cannot re-establish it, so KV and scratch can still
                        # push the load past RAM while mmap stays off. Hand the respawn
                        # llama.cpp's auto back, as the --fit on and CPU fallbacks do.
                        # Only Unsloth's own tokens; a user's --load-mode is theirs.
                        _fit_mode_left_cmd = bool(self._fit_load_mode_flags)
                        if self._fit_load_mode_flags:
                            cmd = _without_subsequence(cmd, self._fit_load_mode_flags)
                            self._fit_load_mode_flags = []
                            logger.info(
                                "Load mode: dropping the fit's --load-mode none for "
                                "the arch-crash retry; it runs on a different device "
                                "set than the fit was proved against."
                            )
                        # This respawn starts from `cmd`, but the crashed launch may
                        # have taken _spawn_and_wait's --fit retry, which appends a
                        # page-lock to its OWN argv and records it. `cmd` never carried
                        # that lock, so leaving the record alone lets
                        # memory_state_satisfies_settings judge the launch satisfied and
                        # dedupe away the reload that would apply the user's page-lock.
                        # Restore what `cmd` means (a no-op when no retry fired).
                        (
                            _mem_host_resident,
                            self._memory_state,
                            self._memory_policy_active,
                            self._memory_mlock_applicable,
                        ) = _mem_policy_for_cmd
                        # ...except the load-mode pair just removed: the snapshot was
                        # taken while `cmd` still carried it, so restoring it would
                        # record a reservation this respawn no longer makes. From the
                        # stripped argv, NOT rebuilt from _mem_managed + _mem_extras: by
                        # here `cmd` may be a fallback argv those parts no longer add up
                        # to, dropping whatever memory-relevant flags they added.
                        if _fit_mode_left_cmd:
                            self._memory_state = resolve_effective_memory_state(cmd, env)
                        # Residency is a property of the DEVICES, which the retry just
                        # changed: crash on the discrete card, land on the
                        # unified-memory APU, and the weights are host-backed after
                        # all, so the lock the first launch skipped is the one the user
                        # asked for. Left alone the respawn runs unlocked AND records
                        # _memory_mlock_applicable False, reading the missing lock as
                        # deliberate and deduping away the reload that would apply it.
                        # Through the same helpers, so the two cannot drift.
                        _retry_host_resident = self._weights_in_host_memory(
                            fully_gpu_offloaded = fully_gpu_offloaded,
                            gpu_memory_mode = gpu_memory_mode,
                            gpu_layers = gpu_layers,
                            extra_args = _mem_extra_args,
                            gpu_indices = _remaining,
                            is_vulkan_backend = is_vulkan_backend,
                            binary = binary,
                            env = env,
                            probe_vulkan = should_mlock(),
                            fit_active = fit_is_effectively_on([*cmd, *(_mem_extra_args or [])], env),
                        )
                        # Lock-ADDING direction only: `cmd` carries a policy-emitted
                        # lock only when the first launch found the weights
                        # host-resident, so this is the one direction that adds without
                        # taking anything back off argv. Removing flags would mean
                        # scanning for --mlock/--no-mmap, VALUELESS in llama.cpp's
                        # parser, so the scan would eat the user extra after them. The
                        # reverse direction leaves the crashed launch's lock in place,
                        # which stays truthful: the child does hold it.
                        if _retry_host_resident and not _mem_host_resident:
                            _retry_managed, _ = apply_model_memory_policy(
                                extra_args,
                                supports_load_mode = bool(server_caps.get("supports_load_mode")),
                                # Not the requested load mode: the first launch
                                # emitted it and this call only ADDS, so a second
                                # copy would land after the extras and mark
                                # _memory_policy_active for a launch it never touched.
                                weights_in_host_memory = _retry_host_resident,
                            )
                            if _retry_managed:
                                # After the user extras, so llama.cpp's last-wins parse
                                # gives it the final say over any hand-written memory
                                # flag. Nothing is stripped, so kept extras survive.
                                cmd.extend(_retry_managed)
                            _mem_host_resident = _retry_host_resident
                            self._memory_mlock_applicable = _retry_host_resident
                            # Stays active if it already was: the flag also
                            # covers extras this policy touched and env it
                            # scrubbed, neither of which the respawn undoes.
                            self._memory_policy_active = (
                                bool(_retry_managed) or self._memory_policy_active
                            )
                            # In argv order -- extras first, then the appended
                            # lock -- because the resolver is last-wins too.
                            self._memory_state = resolve_effective_memory_state(
                                list(_mem_extras) + list(_retry_managed), env
                            )
                            logger.info(
                                "Arch-crash retry changed where the weights live; "
                                "recomputed Model Memory (%s).",
                                " ".join(_retry_managed) if _retry_managed else "no page-lock",
                            )

                        # Last, because everything above still rewrites `cmd`: the
                        # tensor-split drop, the split-mode drop, the fit's load-mode
                        # strip and the re-armed page-lock. The narrowed pool is where a
                        # load that FIT its first placement can meet its first shortfall,
                        # and nothing upstream remapped it, so an unmapped respawn would
                        # allocate the whole model in host RAM and be OOM-killed. Same
                        # condition, same helper, before the respawn rather than after.
                        def _retry_is_oversized() -> bool:
                            if _retry_apu_msg or _retry_host_msg:
                                return True
                            # The opt-out silences the message, never the rewrite.
                            if not self._host_offload_warning_opted_out():
                                return False
                            return bool(
                                self._launch_host_shortfall_message(
                                    cmd, _retry_rows, env, honor_opt_out = False
                                )
                            )

                        cmd, _retry_pageable_note = self._page_an_oversized_unmapped_load(
                            cmd, env, _retry_is_oversized
                        )
                        if _retry_pageable_note:
                            # Onto whichever notice first-notice-wins kept above; a
                            # suppressed one leaves the log line as the only record,
                            # which is the intended contract for the opt-out.
                            self._amend_load_warning(_retry_pageable_note)
                            # From the argv, like the fit-strip above: `cmd` is what
                            # the respawn runs, and the record has to match it.
                            self._memory_state = resolve_effective_memory_state(cmd, env)
                        healthy = _spawn_and_wait(cmd, label = "-archfallback")

                # Flash-attention kernels hard-crash at startup on some ROCm/GPU
                # builds (frequently inside the vision tower). Disabling FA keeps
                # both vision and MTP, so retry that way before dropping either.
                # Only on a hard fault with FA on; a cancel/unload stops respawn.
                if not healthy and not _load_cancelled():
                    _fa_rc = self._process.poll() if self._process is not None else None
                    _fa_cmd = (
                        self._with_flash_attn_off(
                            _last_spawn_cmd,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        )
                        if self._is_signal_crash(_fa_rc)
                        else None
                    )
                    if _fa_cmd is not None:
                        logger.warning(
                            "llama-server hard-crashed at startup (exit %s) with "
                            "flash attention on; retrying once with --flash-attn "
                            "off (keeps vision and MTP).",
                            _fa_rc,
                        )
                        self._kill_process()
                        # The argv rewrite can't reach an env-only quantized V
                        # cache; drop it so the FA-off child doesn't abort on it.
                        if self._drop_env_quantized_v_cache(
                            env,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        ):
                            logger.info(
                                "Dropped inherited quantized V-cache env for the "
                                "--flash-attn off retry (requires flash attention)."
                            )
                        # Same reach problem for the flag itself: where the rewrite
                        # could only drop a bare --flash-attn, the env var alone
                        # still enables it.
                        if self._drop_env_flash_attn(env):
                            logger.info(
                                "Dropped inherited LLAMA_ARG_FLASH_ATTN for the "
                                "--flash-attn off retry."
                            )
                        _fa_cmd = _drop_fit_load_mode_for_no_flash(_fa_cmd)
                        _flash_attn_known_off = True
                        cmd = _fa_cmd
                        healthy = _spawn_and_wait(_fa_cmd, label = "-noflash")

                # MTP from Unsloth's spec flags or the user's (extra_args
                # --spec-type / LLAMA_ARG_SPEC_TYPE). The env survives to the child only
                # when the extras own --spec-type (the launch scrubs it otherwise), so
                # anything else would judge a server it is not starting.
                _launch_spec_env: Mapping[str, str] = _child_spec_env(extra_args)
                _spec_requested_mtp = any(
                    "mtp" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_mtp(extra_args, env = _launch_spec_env)
                _spec_requested_dspark = any(
                    "draft-dspark" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_dspark(extra_args, env = _launch_spec_env)
                _spec_requested_dflash = any(
                    "draft-dflash" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_dflash(extra_args, env = _launch_spec_env)
                # Is the launched server actually running MTP+tensor? Gates the
                # probe/watchdog/recovery; cleared if the MTP-drop fallback wins.
                _mtp_active_for_launched_server = bool(
                    self._tensor_parallel and _spec_requested_mtp
                )
                # MTP can pass /health then crash the flash-attn kernel on the
                # first decode under tensor; probe one generation so the fallback
                # catches that too. Tensor-only, so ordinary MTP stays probe-free.
                if (
                    healthy
                    and self._tensor_parallel
                    and _spec_requested_mtp
                    and not _load_cancelled()
                    and not self._probe_mtp_decode()
                ):
                    # A first-decode hard fault is usually the FA kernel: retry
                    # FA-off (keeps MTP) before dropping speculative decoding below.
                    _probe_rc = self._process.poll() if self._process is not None else None
                    _fa_cmd = (
                        self._with_flash_attn_off(
                            _last_spawn_cmd,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        )
                        if self._is_signal_crash(_probe_rc)
                        else None
                    )
                    healthy = False
                    if _fa_cmd is not None:
                        logger.warning(
                            "MTP first-decode hard-crashed (exit %s) with flash "
                            "attention on; retrying with --flash-attn off.",
                            _probe_rc,
                        )
                        self._kill_process()
                        # The argv rewrite can't reach an env-only quantized V
                        # cache; drop it so the FA-off child doesn't abort on it.
                        if self._drop_env_quantized_v_cache(
                            env,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        ):
                            logger.info(
                                "Dropped inherited quantized V-cache env for the "
                                "--flash-attn off retry (requires flash attention)."
                            )
                        # Same reach problem for the flag itself: where the rewrite
                        # could only drop a bare --flash-attn, the env var alone
                        # still enables it.
                        if self._drop_env_flash_attn(env):
                            logger.info(
                                "Dropped inherited LLAMA_ARG_FLASH_ATTN for the "
                                "--flash-attn off retry."
                            )
                        _fa_cmd = _drop_fit_load_mode_for_no_flash(_fa_cmd)
                        _flash_attn_known_off = True
                        cmd = _fa_cmd
                        healthy = (
                            _spawn_and_wait(_fa_cmd, label = "-noflash-mtp")
                            and self._probe_mtp_decode()
                        )
                    if not healthy:
                        logger.warning(
                            "MTP speculative decoding crashed on the first decode "
                            "under tensor parallelism; retrying without it."
                        )
                # Any MTP request can abort the server: a separate drafter
                # (Gemma) on a binary that predates its arch, or an embedded
                # head (Qwen) the binary cannot build. Retry once with the
                # spec slice replaced by --spec-default so the main model still
                # loads. Gate on the spec block (not the drafter path, which
                # off/ngram local loads also carry) and keep
                # _requested_spec_mode so a duplicate /load doesn't thrash. The
                # cancel check stops an /unload-killed attempt respawning. A
                # decode-probe failure above also routes here.
                # The retry replaces _last_spawn_cmd with a drafterless argv, but a GPU
                # init crash is not the drafter's fault: keep the requested launch so
                # the CPU replay below can still run it.
                _spec_cpu_replay_cmd: Optional[List[str]] = None
                if (
                    not healthy
                    and (_spec_requested_mtp or _spec_requested_dspark or _spec_requested_dflash)
                    and not _load_cancelled()
                ):
                    _spec_cpu_replay_cmd = list(_last_spawn_cmd)
                    # Blame the binary only when the output shows MTP itself
                    # failing (unknown arch / draft or context build); an
                    # unrelated crash (e.g. OOM) gets a neutral message.
                    _lo = "\n".join(self._stdout_lines).lower()
                    # Only an unknown architecture proves the prebuilt predates
                    # this MTP model (an update fixes it). The memory/context
                    # build failures are generic (VRAM / ctx pressure), where an
                    # update may not help, so classify those as runtime_error.
                    _arch_unsupported = "unknown model architecture" in _lo
                    if (
                        _arch_unsupported
                        or "failed to measure draft model memory" in _lo
                        or "failed to measure mtp context memory" in _lo
                        or "failed to create llama_context" in _lo
                    ):
                        _retry_reason = (
                            "the prebuilt may predate it; retrying without "
                            "speculative decoding -- run `unsloth studio "
                            "update` for this drafter"
                        )
                        self._spec_fallback_reason = (
                            "binary_outdated" if _arch_unsupported else "runtime_error"
                        )
                    else:
                        _retry_reason = (
                            "retrying without speculative decoding in case the drafter is the cause"
                        )
                        self._spec_fallback_reason = "runtime_error"
                    _drafter = (
                        Path(launch_mtp_draft_path).name
                        if launch_mtp_draft_path
                        else "embedded head"
                    )
                    logger.warning(
                        "llama-server failed to start with speculative drafter (%s); %s.",
                        _drafter,
                        _retry_reason,
                    )
                    self._kill_process()
                    # Re-locate rather than trust _spec_start: the arch gate may have
                    # narrowed cmd since, which slides the block left and would
                    # otherwise slice --api-key and friends out of the tail.
                    _spec_at = _subsequence_index(cmd, spec_flags, _spec_start)
                    _fb_tail = cmd[_spec_at + len(spec_flags) :]
                    _fb_stripped_extras: Optional[List[str]] = None
                    # Appending --spec-default cannot clear MTP the extras or the env
                    # carry: types accumulate, so it would retry the mode that just
                    # failed and lose a main model that loads fine without it. The
                    # tail loses its spec group and the env goes with it, the same way
                    # the crash replay does it.
                    if (
                        _extra_args_requests_mtp(extra_args, env = _launch_spec_env)
                        or _extra_args_requests_dspark(extra_args, env = _launch_spec_env)
                        or _extra_args_requests_dflash(extra_args, env = _launch_spec_env)
                    ):
                        _fb_tail = strip_shadowing_flags(
                            _fb_tail,
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                        for _fb_spec_var in _SPEC_ENV_VARS:
                            env.pop(_fb_spec_var, None)
                        _fb_stripped_extras = strip_shadowing_flags(
                            extra_args or [],
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                    fallback_cmd = cmd[:_spec_at] + ["--spec-default"] + _fb_tail
                    healthy = _spawn_and_wait(fallback_cmd, label = "-retry")
                    if healthy:
                        self._speculative_type = "default"
                        _mtp_active_for_launched_server = False
                        # The record below stores extra_args as what LAUNCHED, but this
                        # server launched without the spec group. Leaving the MTP list
                        # there would have the next inheriting Apply pick it back up and
                        # repeat the crash. Keep it as the requested state only, the way
                        # the runtime-crash replay does.
                        if _fb_stripped_extras is not None:
                            _pv_suppressed_spec_extra_args = (
                                _pv_suppressed_spec_extra_args
                                if _pv_suppressed_spec_extra_args is not None
                                else list(extra_args or [])
                            )
                            extra_args = _fb_stripped_extras

                # Keep a multimodal model multimodal when only its GPU projector
                # placement fails. llama.cpp owns mmproj offload separately from
                # --gpu-layers, so retry it on CPU before removing --mmproj.
                if not healthy:
                    out = "\n".join(self._stdout_lines[-50:])
                    # Read the crash code before _kill_process() clears _process.
                    _crash_rc = self._process.poll() if self._process is not None else None
                    self._kill_process()
                    # The #6415 split-axis abort is latched earlier (first spawn).
                    # Skip if a cancel/unload is pending (mirrors the MTP guard).
                    _projector_msg = self._is_projector_incompatibility(out)
                    _projector_memory = self._is_gpu_memory_start_failure(out)
                    _signal_mmproj_guess = self._is_signal_crash(
                        _crash_rc
                    ) and not self._output_has_nonprojector_diagnostic(out)
                    if (
                        launched_with_mmproj
                        and not _load_cancelled()
                        and (_projector_msg or _projector_memory or _signal_mmproj_guess)
                    ):
                        _vision_gpu_cmd = list(_last_spawn_cmd)
                        _cpu_projector_cmd = None
                        if not _projector_msg and _paravirtual_mmproj_pinnable(server_caps):
                            _cpu_projector_cmd = self._with_mmproj_offload_disabled(
                                _vision_gpu_cmd, env
                            )

                        if _cpu_projector_cmd is not None:
                            # The fit priced the projector as GPU-eligible, and this
                            # retry moves those bytes into host RAM, so neither the
                            # VRAM-only proof (which never asked what RAM holds) nor the
                            # VRAM-plus-RAM one (answered with the projector on the card)
                            # covers the launch this respawns. Only Unsloth's own tokens;
                            # a user's --load-mode is theirs. The record is NOT cleared:
                            # the fallbacks below respawn from an argv that carries these
                            # tokens and has to be able to name them.
                            if self._fit_load_mode_flags:
                                _stripped_cpu_projector_cmd = _without_subsequence(
                                    _cpu_projector_cmd, self._fit_load_mode_flags
                                )
                                if _stripped_cpu_projector_cmd != _cpu_projector_cmd:
                                    # Same as the no-flash rung: the record follows the
                                    # argv, or a stale "reserving" spends a full reload
                                    # the running server already satisfies.
                                    self._memory_state = resolve_effective_memory_state(
                                        _stripped_cpu_projector_cmd, env
                                    )
                                    logger.info(
                                        "Load mode: dropping the fit's --load-mode none "
                                        "for the CPU-projector retry; it moves the "
                                        "projector into host RAM the fit credited to VRAM."
                                    )
                                _cpu_projector_cmd = _stripped_cpu_projector_cmd
                            logger.warning(
                                "llama-server failed while loading this model's GPU "
                                "vision projector (--mmproj); retrying with the "
                                "projector on CPU to preserve image input."
                            )
                            cmd = _cpu_projector_cmd
                            healthy = _spawn_and_wait(cmd, label = "-mmproj-cpu")
                            if healthy:
                                self._mmproj_fallback_reason = "cpu_offload"
                                logger.warning(
                                    "Vision projector loaded on CPU after GPU startup "
                                    "failed; image input remains available for this session."
                                )
                            else:
                                _cpu_projector_out = "\n".join(self._stdout_lines[-50:])
                                _cpu_projector_rc = (
                                    self._process.poll() if self._process is not None else None
                                )
                                self._kill_process()
                                if _load_cancelled():
                                    return False
                                if self._is_projector_incompatibility(_cpu_projector_out):
                                    _projector_msg = True
                                elif self._is_gpu_memory_start_failure(_cpu_projector_out):
                                    # The projector was already off the GPU, so removing it
                                    # cannot repair this allocation failure; keep the real error.
                                    _raise_terminal_load_failure(
                                        self._classify_llama_start_failure(
                                            _cpu_projector_out,
                                            gguf_path,
                                            self._model_identifier,
                                            _cpu_projector_rc,
                                            binary,
                                            self._llama_log_path,
                                            (self._api_key,),
                                            self._extra_args,
                                        )
                                    )
                        elif _projector_memory and _paravirtual_mmproj_pinnable(server_caps):
                            # An env/argv pin already put mmproj on CPU. Text-only
                            # cannot free additional GPU memory, so surface the OOM.
                            _raise_terminal_load_failure(
                                self._classify_llama_start_failure(
                                    out,
                                    gguf_path,
                                    self._model_identifier,
                                    _crash_rc,
                                    binary,
                                    self._llama_log_path,
                                    (self._api_key,),
                                    self._extra_args,
                                )
                            )

                        if not healthy:
                            if _projector_msg:
                                logger.warning(
                                    "llama-server could not load this model's vision "
                                    "projector (--mmproj). The installed llama.cpp build is "
                                    "likely too old for it. Loading text-only for this "
                                    "session; run 'unsloth studio update' to enable vision."
                                )
                                self._mmproj_fallback_reason = "projector_incompatible"
                            else:
                                logger.warning(
                                    "llama-server could not start with this model's vision "
                                    "projector (--mmproj), including the CPU-projector "
                                    "recovery when available. Retrying text-only for this "
                                    "session; check memory, GPU/driver logs, or update Unsloth."
                                )
                                self._mmproj_fallback_reason = "projector_startup_failure"
                            cmd = self._strip_mmproj_args(_vision_gpu_cmd)
                            # This retry bypasses _spawn_and_wait, so refresh the
                            # launched-argv snapshot itself -- the zero-offload
                            # classification below must not see the stripped --mmproj.
                            _last_spawn_cmd = list(cmd)
                            self._is_vision = False
                            self._mmproj_has_audio = False
                            self._start_llama_process(cmd, env)
                            if self._wait_for_health(timeout = 600.0):
                                healthy = True
                                # The child that serves this session never read the
                                # CPU-pinned projector, so the host-memory advisory the
                                # APU preflight charged it against is now describing a
                                # load nothing is running. Priced again here, and not at
                                # the strip above, because a failed text-only retry can
                                # still replay the ORIGINAL vision argv on CPU further
                                # down -- projector and all -- and that child does load
                                # the bytes. Only a healthy text-only server is evidence.
                                self._reprice_after_dropping_pinned_projector(
                                    apu_msg = _apu_ram_msg,
                                    host_msg = _host_ram_msg,
                                    model_size = model_size,
                                    pinned_bytes = _mmproj_pinned_bytes,
                                    avail_mib = _apu_avail_mib,
                                )
                            else:
                                # Read the exit code before _kill_process() clears it, so
                                # an OS-killed text-only retry still gets the OOM message.
                                _retry_rc = (
                                    self._process.poll() if self._process is not None else None
                                )
                                self._kill_process()
                                # A text-only signal crash is independent evidence of a GPU
                                # startup fault. Keep a confirmed bad projector out of the
                                # replay; a guessed one still gets a CPU try with vision.
                                if self._is_signal_crash(_retry_rc):
                                    _cpu_replay_cmd = (
                                        _last_spawn_cmd if _projector_msg else _vision_gpu_cmd
                                    )
                                    if _try_auto_vulkan_cpu_fallback(
                                        _cpu_replay_cmd,
                                        _retry_rc,
                                    ):
                                        healthy = True
                                        # A whole-runtime CPU replay with the original
                                        # vision argv supersedes the text-only diagnosis.
                                        if not _projector_msg:
                                            self._mmproj_fallback_reason = None
                                    else:
                                        _raise_terminal_load_failure(
                                            self._gpu_init_crash_message(binary)
                                        )
                                if not healthy:
                                    _retry_detail = self._classify_llama_start_failure(
                                        "\n".join(self._stdout_lines[-50:]),
                                        gguf_path,
                                        self._model_identifier,
                                        _retry_rc,
                                        binary,
                                        self._llama_log_path,
                                        (self._api_key,),
                                        self._extra_args,
                                    )
                                    _raise_terminal_load_failure(
                                        self._mmproj_retry_failure_message(
                                            projector_confirmed = _projector_msg,
                                            detail = _retry_detail,
                                        )
                                    )
                    else:
                        # Try the drafter launch first, non-terminally: a build that
                        # can neither pin one to CPU nor start with it still recovers
                        # on the drafterless argv. Snapshot that argv, since a spawned
                        # replay rebinds _last_spawn_cmd to its own command line.
                        _drafterless_cpu_replay_cmd = list(_last_spawn_cmd)
                        _replayed = _spec_cpu_replay_cmd is not None and (
                            _try_auto_vulkan_cpu_fallback(
                                _spec_cpu_replay_cmd, _crash_rc, terminal = False
                            )
                        )
                        if _replayed:
                            # The drafter came back with the replay, so the
                            # speculative-disable diagnosis no longer holds.
                            self._spec_fallback_reason = None
                        elif _try_auto_vulkan_cpu_fallback(_drafterless_cpu_replay_cmd, _crash_rc):
                            _replayed = True
                        if _replayed:
                            healthy = True
                        else:
                            _raise_terminal_load_failure(
                                self._classify_llama_start_failure(
                                    out,
                                    gguf_path,
                                    self._model_identifier,
                                    _crash_rc,
                                    binary,
                                    self._llama_log_path,
                                    (self._api_key,),
                                    self._extra_args,
                                )
                            )

                if _restored_cpu_reprice is not None:
                    # The child that answered is the CPU-only replay, so price the
                    # advisory against the whole model in system RAM, against the pool
                    # the preflight read rather than a live one taken with the weights
                    # already resident.
                    self._reprice_after_cpu_only_fallback(
                        host_msg = _host_ram_msg,
                        cpu_cmd = _last_spawn_cmd or cmd,
                        env = env,
                        avail_mib = _preflight_avail_mib,
                        pageable_note = (
                            _restored_cpu_reprice
                            if isinstance(_restored_cpu_reprice, str)
                            else None
                        ),
                    )
                self._healthy = True
                self._commit_effective_parallel_slots(n_parallel)
                self._swa_full = swa_full
                self._kv_cache_unified = kv_cache_unified
                # Re-derived from the slot count that LAUNCHED, not the one the sizing
                # pass saw. The drafter drop and the non-MTP retry both hand slots back
                # after the batch flag is emitted, and this is recorded next to
                # _commit_effective_parallel_slots: pairing those slots with a micro-batch
                # derived at the clamped count under-states the cache the slot save
                # re-estimates from it.
                _launched_ubatch = _ubatch_for_slots(n_parallel)
                self._n_ubatch = max(
                    0,
                    int(self._DEFAULT_N_UBATCH if _launched_ubatch is None else _launched_ubatch),
                )
                self._flash_attn_enabled = (
                    _flash_attn_enabled_from_args(
                        _last_spawn_cmd, default = not _flash_attn_known_off, env = env
                    )
                    and self._architecture != "grok"
                )
                self._effective_cache_types = _effective_main_cache_types(
                    _last_spawn_cmd,
                    env,
                )
                # The pair the REQUEST resolved to, kept beside the pair that launched.
                # A launch-time rewrite makes them differ (no --flash-attn resets a
                # quantized V cache to f16, as does the flash-attn crash recovery), and
                # the matcher wants the request: comparing the running pair against an
                # unrewritten request rejects every identical repeat load.
                self._requested_cache_types = _planned_cache_pair
                self._kv_cache_context_total = effective_ctx if effective_ctx > 0 else None

                # Server is up: adopt the real per-request context it allocated
                # -- the length --fit chose, or a --parallel slot split -- so the
                # reported context_length matches reality. (Querying /props
                # before the spawn above always failed; the seeded value was the
                # requested/native length.)
                # Clear first, or a swap into a model without video inherits
                # the previous server's answer.
                self._has_video_input = False
                # The explicit override, not the field fallback: only a flag after
                # Studio's own -c can allocate past the fit, so it is the ceiling.
                self._reconcile_effective_ctx_with_server(ctx_override or 0)
                if self._kv_cache_context_total is not None:
                    self._n_ubatch = min(
                        self._n_ubatch,
                        self._kv_cache_context_total,
                    )

                # Commit caller intent only after _healthy=True so a failed start
                # can't poison the next inheritance check. None keeps prior, []
                # clears, list sets. Source records hf_variant for the route's
                # same_source check.
                if extra_args is not None:
                    # Persist the same device-stripped extras the command used when gpu_ids
                    # owns placement, so a later inheriting reload (after gpu_ids clears)
                    # can't resurrect the dropped --device (#7188).
                    self._extra_args = (
                        self._strip_device_extra_args(extra_args)
                        if gpu_ids is not None
                        else list(extra_args)
                    )
                    # Device-stripped the same way, so both comparator sides share a rule.
                    # _extra_args_as_requested first: it predates the Metal
                    # zero-context strip, whereas the drafter-drop snapshot is taken
                    # after it and would put that strip back into the comparator. The
                    # two never disagree otherwise, since the snapshot is only set
                    # alongside a non-None _extra_args_as_requested and the spec strip
                    # it guards runs later still.
                    _pv_requested = (
                        _extra_args_as_requested
                        if _extra_args_as_requested is not None
                        else (
                            _pv_suppressed_spec_extra_args
                            if _pv_suppressed_spec_extra_args is not None
                            else extra_args
                        )
                    )
                    self._requested_extra_args = (
                        self._strip_device_extra_args(_pv_requested)
                        if gpu_ids is not None
                        else list(_pv_requested)
                    )
                    self._extra_args_source = (model_identifier, hf_variant)
                self._requested_n_ctx = int(n_ctx)
                # Local n_parallel may have been reduced above; the snapshot has the ask.
                self._requested_n_parallel = max(1, int(intent.n_parallel))
                # Commit with the rest of the known-good state: only a launch that got
                # this far replaced the runtime, so a rejected preflight leaves the old
                # marker intact, and the diffusion runner returns well before it without
                # consuming, or paying for, any llama-server capability.
                self._capability_probe_inconclusive = _launch_probe_inconclusive
                # The budget this child was sized against, committed with the rest of
                # the known-good state so a duplicate-load fast path or failed launch
                # leaves the previous marker intact and the route keeps asking for the
                # reload. None when placement never used it (_budget_priced_placement).
                self._vram_fraction_launched = _budget_priced_placement()
                self._vram_fraction_pending = None
                self._requested_n_batch = intent.n_batch
                self._requested_n_ubatch = intent.n_ubatch
                self._requested_load_mode = intent.load_mode
                self._requested_spec_draft_cache_type = intent.spec_draft_cache_type
                self._requested_ctx_checkpoints = intent.ctx_checkpoints
                self._requested_cache_ram = intent.cache_ram
                # Commit the known-good snapshot + whether MTP+tensor is live, then
                # watch this load for a mid-generation crash. The verified-cache hint is
                # dropped: a respawn replays this snapshot arbitrarily later, so recovery
                # re-resolves the file instead of trusting a path this request verified.
                self._last_load_intent = replace(intent, verified_gguf = None)
                self._mtp_runtime_fallback_active = _mtp_active_for_launched_server
                self._start_mtp_crash_watchdog()

                # Catch silent CPU fallback when GPU was intended (#5106). Manual
                # offload (no picker) leaves gpu_indices None and use_fit False, so
                # include its GPU-layer intent; use the preserved probe since
                # auto-layers/manual empty `gpus`. A deliberate zero-offload load
                # classifies by its launched argv instead: CPU-only by construction, it
                # must read False (not None) or training needlessly unloads a server
                # holding no VRAM. An arch-gated launch is CPU-only for a stronger
                # reason still: the env block masked every device away ("-1").
                _deliberate_cpu_only = (
                    gpu_memory_mode == "manual" and gpu_layers == 0
                ) or _arch_gate_forced_cpu
                # Published on EVERY load, not only when true: load_model phase 1 only
                # kills the old process, so a stale value would answer holds_no_vram
                # for the child that replaced it. A host that gains coverage (a
                # llama.cpp update) would then report a VRAM-holding server as holding
                # none, and the arbiter leave it unclaimed.
                self._arch_gate_forced_cpu = bool(_arch_gate_forced_cpu)
                if _arch_gate_forced_cpu:
                    # False, never None: _classify_gpu_offload answers None here (the
                    # gated probe left _detected_gpus empty) and training spares only an
                    # exactly-False server, so None unloads one that frees no VRAM.
                    self._gpu_offload_active = False
                elif _deliberate_cpu_only:
                    self._gpu_offload_active = self._zero_offload_gpu_flag(
                        _last_spawn_cmd, _detected_gpus, env
                    )
                else:
                    self._gpu_offload_active = self._classify_gpu_offload(
                        gpu_indices is not None or use_fit or gpu_memory_mode == "manual",
                        _detected_gpus,
                    )
                if self._gpu_offload_active is False and not _deliberate_cpu_only:
                    logger.warning(
                        "llama-server appears to have loaded the model entirely "
                        "on CPU even though Unsloth detected at least one GPU. "
                        "This usually means the prebuilt binary's GPU backend "
                        "failed to load -- on Windows, cudart64_X.dll / "
                        "cublas64_X.dll could not be resolved. Reinstall the "
                        "Unsloth llama.cpp prebuilt or install a matching CUDA "
                        "toolkit (issue unslothai/unsloth#5106).",
                    )

                logger.info(
                    f"llama-server ready on port {self._port} for model '{model_identifier}'"
                )
                # Poll llama-server /metrics -> vLLM-style engine_stats logs
                # (only when the binary exposes /metrics).
                if server_caps.get("supports_metrics"):
                    try:
                        from core.inference.llama_stats import maybe_start_stats_logger
                        if self._stats_logger is not None:
                            self._stats_logger.stop()
                        self._stats_logger = maybe_start_stats_logger(self.base_url, logger)
                    except Exception as e:
                        logger.debug(f"engine-stats logger not started: {e}")
                else:
                    self._stats_logger = None

            # Probe outside _lock (interruptible by /unload); init inside.
            self._is_audio = False
            self._audio_type = None
            self._audio_probed = False
            self._has_audio_input = False
            try:
                detected = self._detect_audio_type_strict()
                self._audio_probed = True
            except Exception as exc:
                logger.debug("Audio probe failed: %s", exc)
                detected = None
            if not self._apply_detected_audio(detected):
                return False

            if not self._healthy:
                return False
            # Snapshot the files the server actually loaded. If a GGUF shard or a
            # LoRA/control-vector sidecar is swapped on disk afterwards while the
            # old weights stay mapped, save_slots_for_resume() compares against
            # this and refuses to persist KV that a reload could misapply.
            if self._slot_save_dir:
                self._slot_loaded_identity = (
                    self._gguf_file_identity(self._gguf_path),
                    self._slot_launch_fingerprint(),
                )
            return True

    def _build_speculative_flags(
        self,
        *,
        speculative_type: Optional[str],
        spec_draft_n_max: Optional[int],
        extra_args: Optional[List[str]],
        model_identifier: str,
        model_path: Optional[str],
        gpus: bool,
        binary: Optional[str],
        mtp_draft_path: Optional[str] = None,
        dspark_draft_path: Optional[str] = None,
        dspark_fit_sized: bool = True,
        dflash_draft_path: Optional[str] = None,
        dflash_fit_sized: bool = True,
        drafter_no_vram: bool = False,
        embedded_mtp_partial_offload: bool = False,
        draft_device: Optional[str] = None,
    ) -> List[str]:
        """Return the llama-server flag list for the requested spec mode.

        Side effects: sets ``self._speculative_type`` (resolved internal
        emit), ``self._requested_spec_mode`` (canonical UI mode for the
        status round-trip), and ``self._spec_draft_n_max`` (user override
        only; None when the platform default applies).

        Speculative decoding (n-gram self-speculation, zero VRAM):
        ngram-mod uses a ~16 MB shared hash pool, constant memory /
        complexity, variable draft lengths. Helps most when the model
        repeats existing text (code refactor, summarisation, reasoning);
        for low-repetition chat, overhead is ~5 ms.

        Benchmarks from upstream llama.cpp speculative-decoding PRs:
          Scenario                        | Without | With    | Speedup
          gpt-oss-120b code refactor      | 181 t/s | 446 t/s | 2.5x
          Qwen3-235B offloaded            |  12 t/s |  21 t/s | 1.8x
          gpt-oss-120b repeat (92% accept)| 181 t/s | 814 t/s | 4.5x
        Refs: https://github.com/ggml-org/llama.cpp/blob/master/docs/speculative.md
              https://github.com/ggml-org/llama.cpp/pull/19164
              https://github.com/ggml-org/llama.cpp/pull/18471
              MTP guide: unsloth.ai/docs/models/qwen3.6#mtp-guide

        Sub-3B dense MTP regresses vs spec-off when the head is baked into the
        main GGUF (Qwen): the draft head's per-token cost exceeds the
        acceptance savings at this scale. Q4_K_XL clean bench (each prompt once
        after an unrelated warmup) on B200 + x86 CPU:
          0.8B GPU: draft-mtp n=2 = 0.58x vs OFF; ngram-only = 1.10x
          2B   GPU: draft-mtp n=2 = 0.82x vs OFF; OFF or ngram = 1.00x
          0.8B CPU: chained n=2   = 0.86x vs OFF; ngram-only = 1.19x
          2B   CPU: chained n=2   = 0.83x vs OFF; ngram-only = 1.01x
          4B+ GPU/CPU: spec on is a net win (1.08x-1.46x).
        A separate drafter (Gemma's root mtp-*.gguf) is a different, cheaper
        mechanism that wins even below 3B, so it is exempt from the sub-3B drop
        (``mtp_draft_path`` set -> not too small). B200 Q4_K_XL bench, draft-mtp
        n=2 vs OFF: gemma-4-E2B (2B) = 1.21x, accept ~0.65 (vs ngram = 1.00x);
        gemma-4-E4B (4B) and 12B engage as usual.
        Auto falls back to ngram-mod (zero-VRAM, near-zero idle cost on
        diverse content) for an embedded sub-3B head; forced MTP on a model
        with no head/drafter defaults back (mtp -> spec-default, mtp+ngram ->
        ngram-mod) since llama-server aborts otherwise; a drafter the binary
        cannot build (older prebuilt, or a CUDA kernel limit) aborts the spawn
        and the load retries once without speculative decoding.
        """
        flags: List[str] = []
        # Reset; emit branches re-set on the resolved emission.
        self._spec_draft_n_max = None
        self._speculative_type = None
        self._spec_fallback_reason = None

        # Canonical UI-facing requested mode (legacy values mapped via
        # _canonicalize_spec_mode).
        canonical_mode = _canonicalize_spec_mode(speculative_type)
        # MTP signals: head baked into the main GGUF (Qwen, via metadata or
        # name), or a separate drafter resolved from the repo (Gemma).
        is_mtp_model = (
            bool(self._nextn_predict_layers)
            or _is_mtp_model_name(model_identifier, model_path)
            or bool(mtp_draft_path)
        )
        user_owns_spec_type = _extra_args_set_spec_type(extra_args)
        _mtp_size_b = _extract_model_size_b(model_identifier)
        # The sub-3B regression is an embedded-head cost; a separate drafter
        # (Gemma) is a cheap standalone model that wins below 3B, so exempt it.
        _mtp_too_small = (
            _mtp_size_b is not None and _mtp_size_b < _MTP_MIN_SIZE_B and not bool(mtp_draft_path)
        )
        # Drafterless Gemma (name-only MTP, no embedded head): emitting MTP
        # would abort llama-server, so every mode below falls back instead.
        _mtp_drafter_missing = (
            _is_gemma_mtp_name(model_identifier, model_path)
            and not mtp_draft_path
            and not self._nextn_predict_layers
        )
        # Embedded MTP head on an MLA model (GLM-5.2/DeepSeek/Kimi, detected by
        # kv_lora_rank): llama.cpp's MLA/DSA MTP path is ~2x slower than no spec,
        # so Auto drops it (override via the Settings dropdown / forced mtp, or
        # UNSLOTH_MLA_MTP_ENABLED=1). Separate drafters (Gemma, mtp_draft_path) and
        # non-MLA embedded heads (Qwen, no kv_lora_rank) are unaffected.
        _auto_mla_embedded_mtp = (
            bool(self._nextn_predict_layers)
            and self._kv_lora_rank is not None
            and not bool(mtp_draft_path)
            and not _mla_mtp_auto_enabled()
        )

        if user_owns_spec_type:
            # User --spec-type wins outright; suppress auto-emit to avoid a
            # duplicate spec block.
            self._requested_spec_mode = None
            return flags

        effective_mode = canonical_mode or "auto"
        self._requested_spec_mode = effective_mode
        if effective_mode == "off":
            return flags
        if effective_mode == "ngram-simple":
            flags.extend(["--spec-type", "ngram-simple"])
            self._speculative_type = "ngram-simple"
            return flags
        caps = self.probe_server_capabilities(binary)

        # Which drafter every branch below is about. Set once here, before any
        # fallback can erase the evidence: the UI names the recovery from this,
        # and under Auto neither the requested mode nor the resolved
        # _speculative_type ("default" after a fallback) still carries the kind.
        _auto_mode = (canonical_mode or "auto") == "auto"
        if canonical_mode == "dspark" or (
            _auto_mode and dspark_draft_path and caps.get("supports_dspark")
        ):
            self._spec_drafter_kind = "dspark"
        elif canonical_mode == "dflash" or (
            _auto_mode and dflash_draft_path and caps.get("supports_dflash")
        ):
            self._spec_drafter_kind = "dflash"
        else:
            self._spec_drafter_kind = "mtp"

        def _resolved_draft_n_max() -> int:
            # User override wins; else platform default (the B200 / x86
            # clean-sweep sweet spot from PR #5582 is n=2 GPU, n=3 CPU;
            # past 3 regresses on essay-style low-acceptance prompts).
            if spec_draft_n_max is not None:
                n = int(spec_draft_n_max)
                self._spec_draft_n_max = n
                return n
            return 2 if gpus else 3

        def _emit_dspark() -> None:
            """Append --model-draft <sidecar> --spec-type draft-dspark + n-max.

            Callers have already established the sidecar and the capability; Auto
            reaches this too, since DSpark is the default when both hold.
            """
            if not dspark_fit_sized:
                # Not a blocker: the sidecar ships no token_embd/output and borrows
                # the target's, so llama.cpp's fit step cannot build a standalone
                # draft context to measure it (llama-context.cpp:153-160) and skips
                # the reserve (server-context.cpp:1190-1193). The load still works;
                # only the ~11 GB is missing from the fit budget.
                logger.info(
                    "DSpark under --fit on: llama.cpp cannot size the sidecar during "
                    "fitting, so its ~%.1f GB is not reserved. Pin GPU Layers in "
                    "Manual mode if the load runs out of VRAM.",
                    (self._get_gguf_size_bytes(dspark_draft_path) or 0) / 1e9,
                )
            draft_n_max = int(spec_draft_n_max) if spec_draft_n_max is not None else 3
            if spec_draft_n_max is not None:
                self._spec_draft_n_max = draft_n_max
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            flags.extend(
                [
                    "--model-draft",
                    dspark_draft_path,
                    "--spec-type",
                    "draft-dspark",
                    str(n_max_flag),
                    str(draft_n_max),
                ]
            )
            self._speculative_type = "draft-dspark"
            logger.info("Spec decoding: draft-dspark using %s", dspark_draft_path)

        if effective_mode == "dspark":
            # Capability first: the fetch is gated on the same answer, so a missing
            # sidecar here is usually the binary's fault. Blaming the file instead
            # would tell the user to place one, and reload on every Apply.
            if not caps.get("supports_dspark"):
                logger.warning(
                    "DSpark requested but llama-server lacks --spec-type "
                    "draft-dspark; loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "binary_no_mtp"
                return flags
            if not dspark_draft_path:
                logger.warning(
                    "DSpark requested but no matching dspark-*.gguf sidecar was found; "
                    "loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "drafter_not_found"
                return flags
            _emit_dspark()
            return flags

        def _emit_dflash() -> None:
            """Append --model-draft <sidecar> --spec-type draft-dflash + n-max.

            Callers have already established the sidecar and the capability. Auto
            reaches this too, since DFlash is the default whenever the model
            ships one: unlike the ~11 GB DSpark sidecar it is ~1.5 GiB and comes
            from the model's own GGUF repo.
            """
            if not dflash_fit_sized:
                # Same shape as DSpark: the sidecar ships no token_embd/output and
                # borrows the target's, so llama.cpp cannot build a standalone
                # draft context to measure it (llama-context.cpp:153-160) and
                # skips the reserve (server-context.cpp:1190-1193). The load still
                # works; only the ~1.5 GB is missing from the fit budget, which is
                # an order of magnitude less than the DSpark case.
                logger.info(
                    "DFlash under --fit on: llama.cpp cannot size the sidecar during "
                    "fitting, so its ~%.1f GB is not reserved. Pin GPU Layers in "
                    "Manual mode if the load runs out of VRAM.",
                    (self._get_gguf_size_bytes(dflash_draft_path) or 0) / 1e9,
                )
            draft_n_max = _resolved_draft_n_max()
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            flags.extend(
                [
                    "--model-draft",
                    dflash_draft_path,
                    "--spec-type",
                    "draft-dflash",
                    str(n_max_flag),
                    str(draft_n_max),
                ]
            )
            if draft_device:
                # A separate drafter, like the Gemma MTP one, so it takes the same
                # device pin (_emit_mtp does this); a baked-in head has nowhere to
                # put it and DSpark's sidecar predates the flag being threaded here.
                flags.extend(["--spec-draft-device", draft_device])
            self._speculative_type = "draft-dflash"
            logger.info("Spec decoding: draft-dflash using %s", dflash_draft_path)

        if effective_mode == "dflash":
            # Capability first, for the same reason as DSpark: the fetch is gated
            # on the same answer, so a missing sidecar here is usually the
            # binary's fault, and blaming the file would tell the user to place
            # one and reload on every Apply.
            if not caps.get("supports_dflash"):
                logger.warning(
                    "DFlash requested but llama-server lacks --spec-type "
                    "draft-dflash; loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "binary_no_mtp"
                return flags
            if not dflash_draft_path:
                logger.warning(
                    "DFlash requested but no matching dflash-*.gguf sidecar was found; "
                    "loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "drafter_not_found"
                return flags
            _emit_dflash()
            return flags

        def _emit_mtp(*, chain_ngram: bool) -> bool:
            """Append --spec-type mtp[/draft-mtp][,ngram-mod] + n-max."""
            mtp_token = caps.get("mtp_token") if caps else None
            if not mtp_token:
                inconclusive = bool(caps.get("mtp_probe_inconclusive")) if caps else True
                if inconclusive:
                    logger.info(
                        "Requested MTP speculative decoding but llama-server MTP "
                        "capability probe was inconclusive; loading without "
                        "speculative decoding."
                    )
                else:
                    logger.warning(
                        "Requested MTP speculative decoding but "
                        "llama-server lacks --spec-type mtp/draft-mtp; "
                        "run `unsloth studio update`. Loading without "
                        "speculative decoding."
                    )
                # Override an inherited LLAMA_ARG_SPEC_TYPE=draft-mtp (CLI wins
                # over env) so the child matches the binary-capability gate and
                # the no-MTP budget, like the sibling no-head/non-MTP fallbacks.
                flags.append("--spec-default")
                self._speculative_type = "default"
                if inconclusive:
                    self._spec_fallback_reason = None
                else:
                    self._spec_fallback_reason = "binary_no_mtp"
                return False
            draft_n_max = _resolved_draft_n_max()
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            # Separate-file drafter (Gemma): point llama-server at it. Baked-in
            # heads (Qwen) pass no path -- llama-server reads them from the
            # main GGUF.
            if mtp_draft_path:
                flags.extend(["--model-draft", mtp_draft_path])
                if draft_device:
                    flags.extend(["--spec-draft-device", draft_device])
                logger.info(f"Using separate MTP drafter: {mtp_draft_path}")
            spec_value = mtp_token
            ngram_knobs: list[str] = []
            if chain_ngram:
                ngram_knobs = _build_ngram_mod_flags(caps)
                if ngram_knobs:
                    spec_value = f"ngram-mod,{mtp_token}"
                else:
                    logger.warning(
                        "llama-server lacks ngram-mod tuning "
                        "flags; loading MTP only (no ngram chain)"
                    )
            flags.extend(["--spec-type", spec_value, n_max_flag, str(draft_n_max)])
            flags.extend(ngram_knobs)
            self._speculative_type = "draft-mtp"
            chain_label = "chained ngram-mod" if chain_ngram else "MTP-only"
            logger.info(f"Spec decoding: {mtp_token} ({chain_label})")
            return True

        def _emit_ngram_mod() -> bool:
            """Append --spec-type ngram-mod + flag-set knobs."""
            ngram_knobs = _build_ngram_mod_flags(caps)
            flags.extend(["--spec-type", "ngram-mod"])
            if not ngram_knobs:
                logger.warning(
                    "llama-server lacks ngram-mod tuning "
                    "flags; loading without --spec-ngram-mod-* knobs"
                )
            flags.extend(ngram_knobs)
            self._speculative_type = "ngram-mod"
            logger.info("Spec decoding: ngram-mod")
            return True

        def _fallback_drafter_not_found() -> None:
            """Drafterless Gemma: use ngram-mod (or spec-default) and record why."""
            logger.warning(
                "Model %s is MTP-capable but no drafter or head was found; "
                "falling back. Check network or run `unsloth studio update`.",
                model_identifier,
            )
            if caps.get("supports_ngram_mod"):
                _emit_ngram_mod()
            else:
                flags.append("--spec-default")
                self._speculative_type = "default"
            self._spec_fallback_reason = "drafter_not_found"

        if effective_mode == "ngram":
            _emit_ngram_mod()
            return flags
        if effective_mode in ("mtp", "mtp+ngram"):
            chain_ngram = effective_mode == "mtp+ngram"
            if not is_mtp_model:
                if chain_ngram:
                    logger.warning(
                        "MTP+Ngram requested but this GGUF has no MTP head or "
                        "drafter; loading ngram-mod only."
                    )
                    _emit_ngram_mod()
                else:
                    logger.warning(
                        "MTP requested but this GGUF has no MTP head or drafter; "
                        "loading without speculative decoding."
                    )
                    flags.append("--spec-default")
                    self._speculative_type = "default"
                return flags
            if _mtp_drafter_missing:
                _fallback_drafter_not_found()
                return flags
            if _mtp_too_small:
                logger.warning(
                    f"Forcing {effective_mode.upper()} on a {_mtp_size_b:.1f}B model; "
                    "the bench shows MTP regresses below 3B. "
                    "Engaging anyway (user override)."
                )
            _emit_mtp(chain_ngram = chain_ngram)
            return flags

        # Embedded Hybrid Mamba MTP shares the target model's device placement.
        # Under an automatic fit, its rollback states push more target layers to CPU;
        # at a fixed partial layer count, the draft and rollback work still regresses
        # decode. Auto therefore preserves ordinary llama-server performance by
        # disabling speculation. Forced MTP remains available as the explicit override.
        # Only where MTP is the thing being stood down. On a build whose --spec-type
        # has no MTP spelling the emit path below already loads without speculation
        # and names the real cause (binary_no_mtp, with the update affordance), so
        # claiming a placement policy would send the user to force a mode this build
        # cannot run, and "none" is not a value every such build's enum carries.
        if embedded_mtp_partial_offload and caps.get("mtp_token"):
            logger.info(
                "Auto: embedded MTP is disabled because the Hybrid Mamba target "
                "requires partial CPU offload; ordinary decoding is faster at this "
                "placement. Choose MTP explicitly to force it."
            )
            flags.extend(["--spec-type", "none"])
            self._speculative_type = "none"
            self._spec_fallback_reason = "mtp_partial_offload"
            # Record the depth this decision was made at (user override only, as
            # everywhere else). The rollback copies priced into the fit are
            # base_recurrent * spec_draft_n_max, so a changed depth can move the
            # placement and must reload -- and without a recorded value the
            # comparison in _runtime_matches_intent would see 0 forever and reload
            # on every Apply instead of once.
            if spec_draft_n_max is not None:
                self._spec_draft_n_max = int(spec_draft_n_max)
            return flags

        # effective_mode == "auto": the promotion path. No vision gate on any drafter
        # kind. MTP's mmproj compatibility is llama.cpp #22673; DFlash is a different
        # --spec-type and #22105 says nothing, so it was measured: Muse-Glimmer-30B
        # UD-Q4_K_XL + mmproj-kquant + dflash-kquant, b10342, B200, n_max=2, greedy,
        # ~545 image tokens gave 92.1 -> 114.2 tok/s at 0.646 acceptance with output
        # byte-identical to the drafter-free run.
        # Which drafter Auto would have emitted had VRAM allowed. An MLA model with no
        # sidecar is already dropped by policy below, and reporting the VRAM reason
        # would invite forcing MTP at a smaller context: slower than the ngram-mod it
        # gets. Let it fall through to the MLA branch, which gives the real reason.
        _no_vram_drops_a_real_drafter = (
            bool(dspark_draft_path and caps.get("supports_dspark"))
            or bool(dflash_draft_path and caps.get("supports_dflash"))
            or not _auto_mla_embedded_mtp
        )
        if drafter_no_vram and _no_vram_drops_a_real_drafter:
            # The fit found room for the target but not for the drafter's reserve,
            # and reserved nothing for it, so emitting one now would OOM the load.
            # Same downgrade as the MLA branch below: ngram-mod costs no VRAM, and
            # spec-off when the build lacks it. The drafter paths stay recorded, so
            # the UI still names the kind and a repeat Apply still dedupes.
            self._spec_fallback_reason = "drafter_no_vram"
            if caps.get("supports_ngram_mod"):
                logger.info(
                    "Auto: the drafter does not fit in VRAM alongside the model at this "
                    "context, so it is dropped and ngram-mod (zero-VRAM) takes its "
                    "place. Choose the drafter in the Speculative Decoding dropdown to "
                    "force it at a smaller context."
                )
                _emit_ngram_mod()
            else:
                # spec-off: --spec-type ngram-mod is not a value this build's enum
                # carries, and llama-server aborts on one it cannot parse rather than
                # ignoring it. Mirrors the MLA and sub-3B branches below.
                logger.info(
                    "Auto: the drafter does not fit in VRAM alongside the model at this "
                    "context, so speculative decoding is disabled (this llama-server "
                    "does not advertise ngram-mod). Choose the drafter in the "
                    "Speculative Decoding dropdown to force it at a smaller context."
                )
        elif dspark_draft_path and caps.get("supports_dspark"):
            # DSpark first: load_model only hands a sidecar down once it has one
            # this binary can launch, and it beats every other Auto outcome for
            # this architecture (1.84x on 4x B200, 1.91x on one). Without it these
            # models fall through to --spec-default, i.e. no drafter at all.
            _emit_dspark()
        elif dflash_draft_path and caps.get("supports_dflash"):
            # DFlash next, on the same reasoning as DSpark and with the same
            # capability gate: load_model only hands a sidecar down once it has
            # one this binary can launch. Unlike DSpark this needs no opt-in: the
            # published sidecar is ~1.5 GiB and already sits in the model's own
            # GGUF repo, so Auto pays roughly what the MTP drafter costs. DSpark
            # keeps first refusal so a repo shipping both is unchanged.
            _emit_dflash()
        elif _auto_mla_embedded_mtp:
            # MLA embedded-MTP (GLM-5.2 et al.): the MTP path regresses vs spec-off
            # on llama.cpp today, so Auto drops it and falls back to ngram-mod (or
            # spec-off if unsupported), mirroring the sub-3B branch. Forced mtp /
            # mtp+ngram (handled above) still engage; UNSLOTH_MLA_MTP_ENABLED=1
            # re-enables this promotion once upstream optimizes the path.
            self._spec_fallback_reason = "mla_mtp_disabled"
            if caps.get("supports_ngram_mod"):
                logger.info(
                    "Auto: MLA embedded-MTP model detected; llama.cpp's MLA/DSA "
                    "MTP path is slower than no speculation, so using ngram-mod "
                    "instead. Override via the Unsloth Speculative Decoding "
                    "dropdown or UNSLOTH_MLA_MTP_ENABLED=1."
                )
                _emit_ngram_mod()
            else:
                logger.info(
                    "Auto: MLA embedded-MTP model detected; disabling speculative "
                    "decoding (this llama-server does not advertise ngram-mod). "
                    "Override via the dropdown or UNSLOTH_MLA_MTP_ENABLED=1."
                )
                # spec-off: emit nothing, mirroring the sub-3B no-ngram path.
        elif is_mtp_model and not _mtp_too_small:
            if _mtp_drafter_missing:
                # Name-only MTP, drafter did not resolve (download failed/absent).
                _fallback_drafter_not_found()
            else:
                # GPU: MTP-only. CPU/Mac: chain ngram-mod + MTP.
                _emit_mtp(chain_ngram = not gpus)
        elif is_mtp_model and _mtp_too_small:
            # Sub-3B fallback: drop the MTP draft head, keep ngram-mod when
            # the binary supports it.
            if _mtp_drafter_missing:
                _fallback_drafter_not_found()
            elif caps.get("supports_ngram_mod"):
                logger.info(
                    f"MTP GGUF detected but model size {_mtp_size_b:.1f}B "
                    "is below the 3B speedup threshold; using ngram-mod "
                    "only (zero-VRAM, no draft head). Override via "
                    "--spec-type or the Unsloth Speculative Decoding "
                    "dropdown."
                )
                _emit_ngram_mod()
            else:
                logger.info(
                    f"MTP GGUF detected but model size {_mtp_size_b:.1f}B "
                    "is below the 3B speedup threshold and the bundled "
                    "llama-server does not advertise ngram-mod; "
                    "auto-disabling speculative decoding."
                )
        else:
            # Non-MTP model: let llama-server choose its default strategy.
            flags.append("--spec-default")
            self._speculative_type = "default"
        return flags

    def adopt_load_intent_if_matched(self, intent: GgufLoadIntent) -> bool:
        """Match live state and adopt the caller's compatible GPU placement."""
        if not self.matches_load_source(intent):
            return False
        # A custom-path save leaves the model intent unchanged, but the
        # resident process still belongs to the previously selected runtime.
        if self._binary_changed_since_launch():
            logger.info("llama-server selection changed since launch; forcing a reload")
            return False
        intent = self._preserve_cpu_fallback_intent(intent, source_matches = True)
        # The stored state is what LAUNCHED, and on a virtualised Metal device that is
        # the CPU-pinned rewrite, not the request. Apply the same rewrite here
        # (idempotent, so load_model's own call is a no-op) or a client that keeps
        # sending Auto mismatches on every call.
        if _metal_device_is_paravirtual():
            (
                _pv_mode,
                _pv_layers,
                _pv_tp,
                _pv_split,
                _pv_cpu_moe,
                _pv_extras,
            ) = paravirtual_normalized_request(
                gpu_memory_mode = intent.gpu_memory_mode,
                gpu_layers = intent.gpu_layers,
                tensor_parallel = intent.tensor_parallel,
                tensor_split = list(intent.tensor_split) if intent.tensor_split else None,
                n_cpu_moe = intent.n_cpu_moe,
                extra_args = list(intent.extra_args) if intent.extra_args is not None else None,
                log_dropped = False,
            )
            intent = replace(
                intent,
                gpu_memory_mode = _pv_mode,
                gpu_layers = _pv_layers,
                tensor_parallel = _pv_tp,
                tensor_split = tuple(_pv_split) if _pv_split else None,
                n_cpu_moe = _pv_cpu_moe,
                extra_args = tuple(_pv_extras) if _pv_extras is not None else None,
            )
        effective_extra_args = (
            list(intent.extra_args) if intent.extra_args is not None else self._extra_args
        )
        candidate_extra_args = list(effective_extra_args) if effective_extra_args else []
        if intent.extra_args is not None and intent.gpu_ids is not None:
            candidate_extra_args = self._strip_device_extra_args(candidate_extra_args)
        # A Model Memory toggle changes only the launch flags, so the intent is
        # unchanged and this would otherwise report already-loaded and leave the
        # running process on the old placement.
        if not memory_state_satisfies_settings(
            self._memory_state,
            self._memory_policy_active,
            self._memory_mlock_applicable,
        ):
            logger.info("Model Memory policy changed since launch; forcing a reload")
            return False
        # Same shape as the Model Memory check above: the budget is server-wide, so
        # a save leaves the intent identical and this would report already-loaded with
        # the child still on the old fraction. None means placement never used it
        # (manual, or no discrete GPU), where a reload would change nothing.
        _launched_frac = self._vram_fraction_launched
        # The pending marker, not a fresh read: a load in flight captured its budget
        # under the lock, and re-reading could decide against a different number than
        # the plan that follows. The route's fast path finds it unset and resolves
        # live as before. Reading the marker rather than taking a parameter keeps the
        # signature every caller and test double already has.
        _pending_frac = self._vram_fraction_pending
        _active_frac = _pending_frac if _pending_frac is not None else _active_vram_fraction()
        if _launched_frac is not None and float(_launched_frac) != _active_frac:
            logger.info("VRAM budget changed since launch; forcing a reload")
            return False
        if not self._runtime_matches_intent(intent, candidate_extra_args):
            return False
        self._record_matching_gpu_request(
            list(intent.gpu_ids) if intent.gpu_ids is not None else None
        )
        return True

    def matches_load_source(self, intent: GgufLoadIntent) -> bool:
        """Whether the resident model has the intent's identity and weights."""
        if not self.is_loaded or (self._model_identifier or "").lower() != (
            intent.model_identifier.lower()
        ):
            return False
        if intent.gguf_path is not None and self._gguf_path:
            resident_identity = getattr(self, "_gguf_load_identity", None)
            if resident_identity is not None:
                candidate_identity = LlamaCppBackend._gguf_load_source_identity(
                    intent.gguf_path, intent.mmproj_path
                )
                return candidate_identity == resident_identity
            try:
                return Path(self._gguf_path).resolve() == Path(intent.gguf_path).resolve()
            except OSError:
                return False
        return (self._hf_variant or "").lower() == (intent.hf_variant or "").lower()

    def _classify_gpu_offload(
        self, expected_gpu: bool, detected_gpus: list[tuple[int, int]]
    ) -> Optional[bool]:
        """True if the model landed on a GPU, False if only CPU buffers landed
        despite GPU intent, None when there's no signal. Delegates to the shared
        classifier so it tracks current llama.cpp logs (offloaded-layer counts /
        device_info), not just the older "model buffer size" lines."""
        if not detected_gpus or not expected_gpu:
            return None
        return classify_gpu_offload_lines(self._stdout_lines)

    @staticmethod
    def _cmd_has_gpu_companion(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """True when the argv/env carries a GPU companion: any --mmproj form, or
        a drafter (Unsloth's --model-draft, the extras aliases, or the
        LLAMA_ARG_SPEC_DRAFT_* env) -- these offload to the GPU regardless of
        the main ``--gpu-layers``. A drafter explicitly forced to CPU
        (--spec-draft-ngl 0 / --spec-draft-device cpu) doesn't count."""
        _args = [str(a) for a in cmd]
        if any(a.startswith("--mmproj") for a in _args):
            # --no-mmproj-offload clears mmproj_use_gpu and clip.cpp gates the whole
            # GPU backend on it, so the projector holds no VRAM. Last flag wins.
            _off = [a for a in _args if a in ("--mmproj-offload", "--no-mmproj-offload")]
            if not _off or _off[-1] != "--no-mmproj-offload":
                return True
        if _extra_args_mtp_draft_path(cmd, env) is None:
            return False
        return not _extra_args_draft_offloaded_to_cpu(cmd, env)

    @staticmethod
    def _zero_offload_keeps_gpu_visible(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """Whether a zero-layer launch still has a reason to use visible GPUs.

        Keep this shared by child masking and post-launch residency bookkeeping:
        a device pin, surviving tensor mode, mmproj, or GPU drafter prevents the
        launch from being a confirmed zero-VRAM server.
        """
        return (
            LlamaCppBackend._cmd_has_gpu_device_pin(cmd, env)
            or _effective_tensor_parallel(cmd, False, env)
            or LlamaCppBackend._cmd_has_gpu_companion(cmd, env)
        )

    @staticmethod
    def _cmd_has_gpu_device_pin(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """True when the effective main or draft ``--device`` pin names a GPU."""
        main_flags = {"--device", "-dev"}
        draft_flags = {"--spec-draft-device", "-devd", "--device-draft"}
        last_main: Optional[str] = None
        last_draft: Optional[str] = None
        args = [str(arg) for arg in cmd]
        for index, raw in enumerate(args):
            flag = _flag_name(raw)
            _, equals, inline = raw.partition("=")
            if flag not in main_flags and flag not in draft_flags:
                continue
            value = inline if equals else (args[index + 1] if index + 1 < len(args) else "")
            if flag in main_flags:
                last_main = value
            else:
                last_draft = value
        if last_main is None:
            last_main = (env or {}).get("LLAMA_ARG_DEVICE")

        def _names_gpu(value: Optional[str]) -> bool:
            if value is None:
                return False
            devices = [item.strip().lower() for item in value.split(",") if item.strip()]
            return not devices or any(item not in ("cpu", "none") for item in devices)

        return _names_gpu(last_main) or _names_gpu(last_draft)

    @staticmethod
    def _zero_offload_gpu_flag(
        spawn_cmd: list,
        detected_gpus: list,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[bool]:
        """GPU-residency flag for a deliberate manual zero-offload load. The
        main model is CPU-only by construction, but device pins, tensor mode,
        mmproj, and GPU drafters can still make the server hold VRAM. The counted
        offload classifier cannot see those allocations. This uses the same
        predicate as the launch-time zero-VRAM mask; None means no GPU signal."""
        if LlamaCppBackend._is_vulkan_backend():
            # Unlike -ngl 0, the recovery's last-wins --device none removes Vulkan.
            main_device = (_extra_args_main_device(spawn_cmd) or "").strip().lower()
            if main_device in ("cpu", "none"):
                return LlamaCppBackend._zero_offload_keeps_gpu_visible(spawn_cmd, env)
            if detected_gpus:
                return True
        if not detected_gpus:
            return None
        return LlamaCppBackend._zero_offload_keeps_gpu_visible(spawn_cmd, env)

    def load_cancelled(self) -> bool:
        """True if a load was cancelled (e.g. via unload/_cancel_event) and not
        yet consumed by the next load_model. Lets the tensor->layer fallback
        avoid restarting a load the user just cancelled."""
        return self._cancel_event.is_set()

    def unload_model(self) -> bool:
        """Terminate the subprocess and cancel any in-flight download."""
        self._cancel_event.set()
        with self._lock:
            self._unload_epoch += 1
            self._kill_process()
            self._cleanup_cpu_fallback_runtime()
            logger.info(f"Unloaded GGUF model: {self._model_identifier}")
            self._model_identifier = None
            self._gguf_path = None
            self._gguf_load_identity = None
            self._hf_repo = None
            self._mtp_draft_path = None
            self._mtp_draft_suppressed_path = None
            self._spec_fallback_reason = None

            self._mmproj_fallback_reason = None
            self._capability_probe_inconclusive = False
            self._spec_drafter_kind = None
            self._dspark_sidecar_absent = False
            self._dflash_sidecar_absent = False
            self._dflash_retry_needed = False
            self._launch_binary_revision = ()
            self._cpu_fallback_reason = None
            self._last_load_intent = None
            self._mtp_runtime_fallback_active = False
            self._hf_variant = None
            self._is_vision = False
            self._disable_vision = False
            self._vision_disabled_by_user = False
            self._is_audio = False
            self._audio_type = None
            self._audio_probed = False
            self._has_audio_input = False
            self._has_video_input = False
            self._mmproj_has_audio = False
            self._mmproj_accepts_image = True
            self._port = None
            self._healthy = False
            self._context_length = None
            self._effective_context_length = None
            self._max_context_length = None
            self._reset_effective_parallel_slots()
            self._slot_save_dir = None
            self._slot_save_binary = None
            self._slot_loaded_identity = None
            self._prompt_cache_disabled = False
            self._swa_full = False
            self._kv_cache_unified = False
            self._memory_state = None
            self._memory_policy_active = False
            self._memory_mlock_applicable = True
            self._memory_launch_pending = False
            self._vram_fraction_pending = None
            self._loaded_by_user_action = False
            self._n_ubatch = self._DEFAULT_N_UBATCH
            self._flash_attn_enabled = True
            self._effective_cache_types = ("f16", "f16")
            self._requested_cache_types = ("f16", "f16")
            self._kv_cache_context_total = None
            self._chat_template = None
            self._markup_tokens = []
            self._markup_profile = None
            self._chat_template_override = None
            self._supports_reasoning = False
            self._reasoning_always_on = False
            self._reasoning_style = "enable_thinking"
            self._reasoning_effort_levels = []
            self._reasoning_default = True
            self._supports_preserve_thinking = False
            self._preserve_thinking_default = False
            self._supports_tools = False
            self._cache_type_kv = None
            # GPU-pin state describes the active runner only; clear it so an explicit
            # pin never leaks into the next (or diffusion) runner.
            self._gpu_ids = None
            self._requested_gpu_ids = None
            self._tensor_parallel = False
            self._gpu_memory_mode = "auto"
            self._gpu_layers = -1
            self._n_cpu_moe = 0
            self._tensor_split = None
            self._arch_gate_forced_cpu = False
            self._layer_preserves_tensor_intent = False
            self._speculative_type = None
            self._requested_spec_mode = None
            self._spec_draft_n_max = None
            self._n_layers = None
            self._n_experts = None
            self._leading_dense_block_count = None
            self._n_kv_heads = None
            self._n_kv_heads_by_layer = None
            self._n_heads = None
            self._embedding_length = None
            self._pooling_type = None
            self._kv_key_length = None
            self._kv_value_length = None
            self._sliding_window = None
            self._sliding_window_pattern = None
            self._full_attention_interval = None
            self._kv_lora_rank = None
            self._key_length_mla = None
            self._kv_key_length_swa = None
            self._kv_value_length_swa = None
            self._ssm_inner_size = None
            self._ssm_state_size = None
            self._ssm_group_count = None
            self._ssm_conv_kernel = None
            self._kda_head_dim = None
            self._shared_kv_layers = None
            self._nextn_predict_layers = None
            # Clean up temp chat template file.
            if hasattr(self, "_chat_template_file") and self._chat_template_file:
                try:
                    os.unlink(self._chat_template_file.name)
                except Exception:
                    pass
                self._chat_template_file = None
            # Free audio codec GPU memory.
            if LlamaCppBackend._codec_mgr is not None:
                LlamaCppBackend._codec_mgr.unload()
                LlamaCppBackend._codec_mgr = None
                import torch

                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            return True

    @staticmethod
    def _leading_process_group(pid):
        """The pid's own process group, when it leads one. None otherwise.

        `not pid` rejects 0 and None but not 1, and `getpgid(1) == 1`, so init
        reads as a group leader here and the caller below would then broadcast
        SIGKILL to every process the user owns. The pid comes from a live Popen
        today so it cannot be 1, but the floor is a line and the consequence of
        losing that property later is not recoverable.
        """
        if not _is_signalable_pid(pid):
            return None
        if os.name != "posix" or not hasattr(os, "getpgid"):
            return None
        try:
            pgid = os.getpgid(pid)
        except OSError:
            return None
        return pgid if pgid == pid else None

    @staticmethod
    def _kill_process_group(pgid):
        """Take down what the leader left behind, if anything is still there."""
        if not _is_signalable_pid(pgid):
            return  # killpg(1) is kill(-1); killpg(0) is our own group
        if not hasattr(os, "killpg"):
            return
        try:
            os.killpg(pgid, signal.SIGKILL)
        except OSError:
            pass

    @staticmethod
    def _collect_descendants(pid):
        """The server's own children, for the kill below. Empty when unreadable."""
        try:
            from utils.process_lifetime import collect_descendants
            return collect_descendants(pid)
        except Exception:
            return []

    @staticmethod
    def _terminate_descendants(collected):
        """The diffusion shim's visual server, and anything else it started."""
        if not collected:
            return
        try:
            from utils.process_lifetime import terminate_descendants
            terminate_descendants(collected, timeout = 5.0)
        except Exception as e:
            logger.debug(f"Could not terminate server descendants: {e}")

    def _kill_process(self):
        """Terminate the subprocess if running."""
        # Stop the watchdog before a deliberate kill so a planned reload/unload
        # isn't seen as a crash; a real crash never routes through here.
        self._stop_mtp_crash_watchdog()
        self._reset_effective_parallel_slots()
        # Cleared before the early return, not in the finally below, so a stale split never
        # outlives its runner even when there was no process to kill.
        self._diffusion_requested_ngl = None
        if self._process is None:
            return
        # Not every _process is a Popen: tests stand one in to mean "a server is
        # loaded" without spawning anything. Terminating what cannot be terminated
        # is not an error worth reporting, but everything else still has to happen,
        # so this skips only the signalling and falls through to the finally rather
        # than returning early and duplicating part of it.
        terminable = hasattr(self._process, "terminate")
        if not terminable:
            logger.debug("no terminable llama-server process to kill; clearing state")
        # Both read before the terminate below: getpgid stops answering once the
        # wait reaps the leader, and the shim's children are reparented the
        # moment it exits. This is the only stop the desktop shutdown waits for,
        # so the visual server has to be named while that link still exists.
        _pid = getattr(self._process, "pid", None)
        _pgid = self._leading_process_group(_pid)
        _descendants = self._collect_descendants(_pid)
        try:
            if terminable:
                self._process.terminate()
                self._process.wait(timeout = 5)
        except subprocess.TimeoutExpired:
            # Signal first, report after. logger here is a structlog PrintLogger
            # writing straight to stdout, so a closed stream raises out of the
            # warning; doing it first meant SIGKILL was skipped and the server
            # left running with the reference about to be dropped below.
            self._process.kill()
            # Between the two, deliberately. After kill() so the signal never
            # depends on a log write, and before this wait() because a second
            # TimeoutExpired raised in here is not caught by the handler it is
            # raised from -- it escapes, and a truly unkillable server would then
            # be reported by nothing at all.
            logger.warning("llama-server did not exit on SIGTERM, sent SIGKILL")
            self._process.wait(timeout = 5)
        except Exception as e:
            logger.warning(f"Error killing llama-server process: {e}")
        finally:
            self._kill_process_group(_pgid)
            self._terminate_descendants(_descendants)
            # getattr: teardown must tolerate a partially-built backend (failed
            # __init__ or a __new__-built instance), as with _llama_log_fh below.
            if getattr(self, "_stats_logger", None) is not None:
                self._stats_logger.stop()
                self._stats_logger = None
            # Drop it from the lifetime record only once it is confirmed gone.
            # A server that survived a failed kill has to stay recorded, or the
            # next startup sweep cannot reap it. The record stores a start-time
            # identity, so a recycled pid is never signalled either way.
            _killed_pid = getattr(self._process, "pid", None)
            _exited = getattr(self._process, "poll", lambda: None)() is not None
            if _killed_pid is not None and _exited:
                try:
                    from utils.process_lifetime import forget_pid
                    forget_pid(_killed_pid)
                except Exception:
                    pass
            self._process = None
            self._clear_server_pid()
            # Clear healthy so a /load during the replacement's warm-up can't
            # short-circuit against the previous server's health (#5401).
            self._healthy = False
            # Reset to unknown so the training guard treats the next (still
            # loading) server as VRAM-resident rather than reading the killed
            # server's stale zero-offload flag until the health probe reclassifies.
            self._gpu_offload_active = None
            # Drives _wait_for_vram_settle in the next load_model; set in finally
            # so both in-process and frontend Apply paths record the kill.
            self._last_kill_monotonic = time.monotonic()
            stdout_thread = getattr(self, "_stdout_thread", None)
            if stdout_thread is not None:
                stdout_thread.join(timeout = 2)
                self._stdout_thread = None
            fh = getattr(self, "_llama_log_fh", None)
            if fh is not None:
                try:
                    fh.close()
                except Exception:
                    pass
                self._llama_log_fh = None

    @staticmethod
    def _server_pidfile_path() -> Optional[Path]:
        """Pidfile recording the live llama-server PID, under the active studio root
        (per-root, so concurrent Unsloth instances with distinct UNSLOTH_STUDIO_HOME stay
        isolated, mirroring the reaper's custom-root isolation)."""
        try:
            from utils.paths.storage_roots import studio_root  # noqa: WPS433
            return studio_root() / "llama-server.pid"
        except Exception:
            return None

    @classmethod
    def _record_server_pid(cls, pid: int) -> None:
        """Best-effort record of the spawned llama-server PID for orphan reaping.

        Stores ``pid:starttime`` so a later startup can reject a PID that has
        since been recycled to a different process (see ``_pid_start_identity``).
        A bare ``pid`` (no identity) is still accepted on read for compatibility.
        """
        # Track it generically too: the pidfile holds one server, while the
        # process-lifetime record covers every child and is what the startup
        # sweep reads where there is no parent-death signal (macOS).
        try:
            from utils.process_lifetime import adopt_pid
            adopt_pid(pid)
        except Exception as e:
            logger.debug(f"Could not track llama-server for lifetime sweep: {e}")
        path = cls._server_pidfile_path()
        if path is None:
            return
        try:
            path.parent.mkdir(parents = True, exist_ok = True)
            path.write_text(f"{pid}:{cls._pid_start_identity(pid)}", encoding = "utf-8")
        except Exception as e:
            logger.debug(f"Could not write llama-server pidfile: {e}")

    @classmethod
    def _clear_server_pid(cls) -> None:
        """Best-effort removal of the llama-server pidfile."""
        path = cls._server_pidfile_path()
        if path is None:
            return
        try:
            path.unlink(missing_ok = True)
        except Exception as e:
            logger.debug(f"Could not remove llama-server pidfile: {e}")

    @staticmethod
    def _pid_is_llama_server(pid: int) -> bool:
        """True only if pid is a live process whose binary is a llama-server. Guards
        against PID reuse before killing a recorded orphan; returns False on any
        uncertainty so an unrelated process is never killed."""
        try:
            import psutil
            try:
                proc = psutil.Process(pid)
                if (proc.name() or "").lower().startswith("llama-server"):
                    return True
                return Path(proc.exe() or "").name.lower().startswith("llama-server")
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                return False
        except ImportError:
            pass
        if sys.platform != "linux":
            return False
        try:
            if Path(os.readlink(f"/proc/{pid}/exe")).name.lower().startswith("llama-server"):
                return True
        except OSError:
            pass
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as fh:
                tokens = fh.read().split(b"\x00")
            first = tokens[0].decode("utf-8", "replace") if tokens else ""
            return Path(first).name.lower().startswith("llama-server")
        except OSError:
            return False

    @staticmethod
    def _pid_start_identity(pid: int) -> str:
        """Stable per-PID identity (process start time) guarding against PID reuse.

        Returns a token string, or "" when it cannot be determined (the caller
        then falls back to the llama-server name check only)."""
        try:
            import psutil
            try:
                return str(psutil.Process(pid).create_time())
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                return ""
        except ImportError:
            pass
        if sys.platform == "linux":
            try:
                with open(f"/proc/{pid}/stat", "rb") as fh:
                    data = fh.read()
                # field 22 (starttime), counted from after the ")" that closes comm.
                return data[data.rfind(b")") + 2 :].split()[19].decode()
            except (OSError, IndexError):
                return ""
        return ""

    @staticmethod
    def _pid_parent_is_alive(pid: int) -> bool:
        """True if the recorded server's parent is still running, i.e. the server is
        NOT orphaned. Lets the cross-session reap kill only a true orphan (parent
        gone) and never a live server owned by a running Unsloth, regardless of which
        process performs the sweep. Biased toward "alive" on uncertainty so a live
        server is never mistakenly reaped."""
        try:
            import psutil

            try:
                ppid = psutil.Process(pid).ppid()
            except psutil.NoSuchProcess:
                return False  # the recorded server itself is gone
            except psutil.Error:
                return True  # cannot tell -- never risk killing a live server
            if ppid <= 1:
                return False  # reparented to init -> orphan
            return psutil.pid_exists(ppid)
        except ImportError:
            pass
        if sys.platform == "linux":
            try:
                with open(f"/proc/{pid}/stat", "rb") as fh:
                    data = fh.read()
                ppid = int(data[data.rfind(b")") + 2 :].split()[1])
            except (OSError, IndexError, ValueError):
                return False
            if ppid <= 1:
                return False
            return Path(f"/proc/{ppid}").exists()
        return False

    @staticmethod
    def _unlink_pidfile(path: Path) -> None:
        """Best-effort removal of a resolved pidfile path."""
        try:
            path.unlink(missing_ok = True)
        except Exception:
            pass

    @classmethod
    def _reap_recorded_pid(cls) -> int:
        """Kill the exact llama-server PID recorded at spawn, but only when it is a
        genuine orphan -- its parent (the Unsloth that spawned it) is gone. This is
        the cross-session backstop the parent-death reaper (Job Object /
        PR_SET_PDEATHSIG) cannot cover: an orphan left by an already-dead Unsloth
        (macOS, a best-effort failure, or a pre-existing orphan). Path-independent,
        so it also catches an orphan the install-root match would miss.

        A live server whose parent is still running is never reaped, so constructing
        a second backend in-process (the helper / advisor paths each build a
        LlamaCppBackend) cannot kill the active chat server. A recorded PID that has
        been recycled to a different process is rejected by the start-time identity
        and the llama-server name check, so unrelated user processes are never
        touched. SIGKILL falls back to SIGTERM on Windows, where os.kill maps it to
        TerminateProcess and SIGKILL is undefined."""
        path = cls._server_pidfile_path()
        if path is None or not path.exists():
            return 0

        pid = -1
        identity = ""
        try:
            pid_str, _, identity = path.read_text(encoding = "utf-8").strip().partition(":")
            pid = int(pid_str)
        except Exception:
            pid = -1

        # `pid <= 0` let pid 1 through. The cmdline check further down is what
        # actually keeps this honest and init cannot pass it, but the reaper in
        # process_lifetime had a start-time identity check that was just as
        # convincing and a record naming pid 1 still went through it, so the
        # cheap bound goes in front of the clever one here too.
        if not _is_signalable_pid(pid):
            cls._unlink_pidfile(path)  # garbage record
            return 0
        if pid == os.getpid():
            return 0  # never our own pid; leave the record alone

        if cls._pid_parent_is_alive(pid):
            # Live server with a running parent -> not an orphan; keep the record so
            # a later startup can still reap it if that parent later dies abnormally.
            return 0

        # Parent is gone: candidate orphan. Reject a PID recycled to something else.
        if identity and cls._pid_start_identity(pid) != identity:
            cls._unlink_pidfile(path)
            return 0

        killed = 0
        if cls._pid_is_llama_server(pid):
            try:
                os.kill(pid, getattr(signal, "SIGKILL", signal.SIGTERM))
                killed = 1
                logger.info(f"Killed orphaned llama-server from pidfile (pid={pid})")
            except (ProcessLookupError, PermissionError):
                pass
            except Exception as e:
                logger.debug(f"Could not kill recorded llama-server pid {pid}: {e}")
        cls._unlink_pidfile(path)
        return killed

    @staticmethod
    def _kill_orphaned_servers() -> int:
        """Kill orphaned llama-server processes started by studio.

        Only kills processes whose resolved binary lives under a known
        Unsloth install dir (or matches an exact env-var override), to avoid
        terminating unrelated llama-server instances. Mirrors every location
        _find_llama_server_binary() can return, so orphans from any
        supported install path are cleaned up.

        Reads /proc directly on Linux and uses psutil elsewhere (macOS, Windows).
        The pgrep fallback the psutil-less path used to take is gone: /proc is
        what that fallback read anyway, and psutil is a hard dependency, so it
        was unreachable from both directions.

        Candidates are collected first and killed afterwards, so an enumeration
        that fails part way kills nothing rather than some. The parent check
        therefore runs after enumeration rather than during it; a parent that
        exits in between makes the process a genuine orphan, and the start-time
        check below still refuses to signal a PID that has been reused.

        Returns the count of processes killed; callers arm the VRAM-settle
        wait on a positive count.
        """
        # Cross-session backstop first: reap the exact PID we recorded at spawn,
        # but only if it is a true orphan whose parent is gone (so a helper backend
        # built while a chat server is live can never kill it). The root-gated
        # enumeration below stays as a fallback.
        killed = LlamaCppBackend._reap_recorded_pid()
        try:
            # -- Build the ownership allowlist --------------------------------
            # exact_binaries -- env var overrides (exact path match).
            # install_roots  -- Unsloth-owned dir trees (binary must be under one).
            install_roots: list[Path] = []

            # Env-mode custom root (mirrors _find_llama_server_binary).
            _resolved_sr, _is_legacy = LlamaCppBackend._resolved_studio_root_and_is_legacy()
            _is_custom_root = not _is_legacy
            if _is_custom_root:
                install_roots.append(_resolved_sr / "llama.cpp")

            # Primary install dir (default mode only). Env-mode skips this so a
            # custom-root Unsloth can't kill a default-install Unsloth's server.
            if not _is_custom_root:
                install_roots.append(Path.home() / ".unsloth" / "llama.cpp")

            # Legacy in-tree build dirs (older setup.sh)
            project_root = Path(__file__).resolve().parents[4]
            install_roots.append(project_root / "llama.cpp")

            # Legacy: extracted binary
            install_roots.append(project_root / "bin")

            # UNSLOTH_LLAMA_CPP_PATH env var (custom install dir)
            custom_dir = os.environ.get("UNSLOTH_LLAMA_CPP_PATH")
            if custom_dir:
                install_roots.append(Path(custom_dir))

            # LLAMA_SERVER_PATH env var (exact binary path)
            exact_binaries: list[Path] = []
            env_binary = os.environ.get("LLAMA_SERVER_PATH")
            if env_binary:
                try:
                    exact_binaries.append(Path(env_binary).resolve())
                except OSError:
                    pass

            # Resolve all roots so is_relative_to works reliably.
            resolved_roots: list[Path] = []
            for root in install_roots:
                try:
                    # A --with-llama-cpp-dir local link (symlink/junction)
                    # resolves into the user's own checkout. Adding it would let
                    # us treat the user's externally-launched llama-server as our
                    # orphan and kill it, so leave such roots out of the
                    # allowlist (we forgo orphan-reaping for local-link installs).
                    if _is_external_link(root):
                        continue
                    resolved_roots.append(root.resolve())
                except OSError:
                    pass

            my_pid = os.getpid()

            # -- Enumerate candidate processes ---------------------------------
            # (pid, resolved binary, kill callable) per llama-server-looking process;
            # ownership, orphan and kill handling is shared below so the paths agree.
            candidates = []

            def _looks_like_server(name):
                return bool(name) and name.lower().startswith("llama-server")

            def _stat_start_time(line):
                right = line.rfind(b")")
                fields = line[right + 2 :].split()
                return fields[19] if len(fields) > 19 else None

            def _proc_start_time(proc_dir):
                """Field 22 of /proc/<pid>/stat, in jiffies since boot."""
                try:
                    with open(f"{proc_dir}/stat", "rb") as fh:
                        line = fh.read()
                except OSError:
                    return None
                right = line.rfind(b")")
                if right < 0:
                    return None
                # Fields after comm start at field 3, so starttime is index 19.
                fields = line[right + 2 :].split()
                return fields[19] if len(fields) > 19 else None

            def _make_signal_killer(proc_dir, pid, start_time):
                def _kill():
                    # psutil.Process.kill() refuses to signal a reused PID, so re-check
                    # identity here too: starttime never changes for a process and a reused
                    # PID gets a later one, so a mismatch means this is not our process.
                    if start_time is None or _proc_start_time(proc_dir) != start_time:
                        return False
                    try:
                        os.kill(pid, signal.SIGKILL)
                    except (ProcessLookupError, PermissionError):
                        return False
                    return True

                return _kill

            # /proc is Linux only; a missing one falls back to psutil rather than finding
            # nothing. Tests point _PROC_ROOT elsewhere to drive either path.
            proc_root = _PROC_ROOT
            if sys.platform == "linux" and os.path.isdir(proc_root):
                # psutil.process_iter(["pid", "name", "exe"]) reads /proc/<pid>/stat several
                # times per process and resolves exe for every one before the name rejects
                # almost all. This sweep runs on every backend start and every temporary
                # LlamaCppBackend(), so read comm once and resolve exe only on a name match.
                def _proc_exe(proc_dir):
                    try:
                        target = os.readlink(f"{proc_dir}/exe")
                    except OSError:
                        return None
                    if not target:
                        return None
                    # The kernel appends " (deleted)" once the binary is replaced or removed,
                    # which is what an upgrade's orphan looks like. psutil strips the marker,
                    # so strip it here too or that orphan stops being recognised as ours.
                    if target.endswith(" (deleted)") and not os.path.exists(target):
                        target = target[: -len(" (deleted)")]
                    try:
                        return Path(target).resolve()
                    except OSError:
                        return None

                with os.scandir(proc_root) as entries:
                    for entry in entries:
                        if not entry.name.isdigit():
                            continue
                        try:
                            pid = int(entry.name)
                        except ValueError:
                            continue
                        if pid == my_pid:
                            continue
                        try:
                            with open(f"{entry.path}/stat", "rb") as fh:
                                stat_line = fh.read()
                        except OSError:
                            continue  # the process exited mid-scan
                        left = stat_line.find(b"(")
                        right = stat_line.rfind(b")")
                        if left < 0 or right <= left:
                            continue
                        # comm is truncated to 15 bytes, which still leaves the 12-byte
                        # "llama-server" prefix intact, so this selects the names psutil does.
                        name = stat_line[left + 1 : right].decode("utf-8", "replace")
                        if not _looks_like_server(name):
                            continue
                        exe_path = _proc_exe(entry.path)
                        if exe_path is None:
                            continue
                        candidates.append(
                            (
                                pid,
                                exe_path,
                                _make_signal_killer(entry.path, pid, _stat_start_time(stat_line)),
                            )
                        )
            else:
                try:
                    import psutil
                except ImportError:
                    psutil = None

                if psutil is not None:

                    def _make_psutil_killer(psutil_mod, proc):
                        def _kill():
                            try:
                                proc.kill()
                            except (
                                psutil_mod.NoSuchProcess,
                                psutil_mod.AccessDenied,
                                psutil_mod.ZombieProcess,
                            ):
                                return False
                            return True

                        return _kill

                    for proc in psutil.process_iter(["pid", "name", "exe"]):
                        try:
                            pid = proc.info["pid"]
                            if pid == my_pid:
                                continue
                            if not _looks_like_server(proc.info.get("name") or ""):
                                continue
                            exe = proc.info.get("exe")
                            if not exe:
                                continue
                            candidates.append(
                                (pid, Path(exe).resolve(), _make_psutil_killer(psutil, proc))
                            )
                        except (
                            psutil.NoSuchProcess,
                            psutil.AccessDenied,
                            psutil.ZombieProcess,
                        ):
                            pass
                else:
                    # Unreachable while the Linux branch above exists; kept so the
                    # psutil-less path stays correct if that changes.
                    return killed

            # -- Ownership check, orphan check, kill ---------------------------
            for pid, binary, kill in candidates:
                # Floored here rather than in each enumerator: both the /proc scan
                # and the psutil scan feed this loop, and a third one added later
                # would too. Not hypothetical for pid 1 either, since #7894
                # established Unsloth can run as a container entrypoint, and a
                # container whose entrypoint is llama-server puts a process this
                # sweep recognises at pid 1. Killing it takes the container down.
                if not _is_signalable_pid(pid):
                    continue
                # Ownership: exact match OR binary under a known root.
                is_ours = binary in exact_binaries or any(
                    binary.is_relative_to(root) for root in resolved_roots
                )
                if not is_ours:
                    continue

                # A live parent means a running Unsloth (or the user's shell) still owns it.
                if LlamaCppBackend._pid_parent_is_alive(pid):
                    continue

                if kill():
                    killed += 1
                    logger.info(f"Killed orphaned llama-server process (pid={pid})")
        except Exception:
            logger.warning("Error during orphan server cleanup", exc_info = True)
        return killed

    def _cleanup(self):
        """atexit handler to ensure llama-server is terminated.

        Nothing here may report a failure through the logging machinery. By the
        time atexit runs, the streams the handlers write to can already be closed,
        and a write then fails -- which is how this was found, as several unrelated
        tracebacks printed after the test summary.

        Two different mechanisms, because there are two kinds of logger in play.
        This module's own logger is a structlog PrintLogger writing straight to
        stdout (loggers/config.py), which has no error handling of its own and does
        not consult raiseExceptions at all, so only the except below covers it.
        raiseExceptions covers the stdlib loggers other libraries install, which
        report a broken handler by printing their own traceback instead of raising.
        Neither one alone is enough.
        """
        raise_exceptions = logging.raiseExceptions
        logging.raiseExceptions = False
        try:
            self._kill_process()
            # TemporaryDirectory's exit hook runs first and cannot delete a staged
            # runtime whose server is alive (Windows locks the exe). Retry post-kill.
            self._cleanup_cpu_fallback_runtime()
        except Exception:
            # atexit swallows this anyway, and there is nowhere left to report it.
            pass
        finally:
            logging.raiseExceptions = raise_exceptions

    def _planned_tensor_spill(
        self,
        inputs: Optional[dict],
        *,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> "Optional[SpillPlan]":
        """A ``-ot`` spill plan for a load Unsloth could not fit, or None to abstain.

        Abstaining reproduces today's ``--fit on`` byte for byte, so every
        uncertain input abstains rather than guessing. That is the whole safety
        argument: the only behaviour that changes is the case where a plan was
        produced, and a plan is only produced when the numbers are known.

        The planner must NOT run when anything else owns placement. Pricing a
        placement the child will not actually get is the single bug class behind
        most of the review traffic on the load-mode work, and the cheap way to
        avoid it is to decline rather than to model the override.
        """
        from core.inference.offload_cost_model import HostProfile
        from core.inference.offload_planner import (
            PlanOptions,
            plan_placement,
            smart_offload_enabled,
        )

        source_env = os.environ if env is None else env
        if not smart_offload_enabled(source_env) or not inputs:
            return None

        # Unified memory: spilling moves bytes inside one pool, so the trade does
        # not exist. Metal also keeps mmap zero copy via buffer_from_host_ptr.
        from utils.hardware import is_apple_silicon

        if is_apple_silicon():
            return None

        # An integrated CUDA SoC (Jetson, DGX Spark) is unified memory too, and
        # nothing else here sees it: _amd_apu_wants_unified_memory answers only for
        # ROCm, and shared_gpu_ids is populated only on Vulkan, which reports total
        # 0 for an iGPU. CUDA states it directly (cudaDeviceProp::integrated, torch's
        # is_integrated), and Studio's diffusion policy already classifies such a
        # device as unified memory for exactly this reason -- CPU offload frees
        # nothing there (diffusion_memory.py:292-294). A spill would count one pool
        # twice and then pin the result with --fit off.
        if self._integrated_cuda_unified_memory(inputs.get("gpu_indices")):
            logger.debug("Tensor spill: declined, an integrated CUDA device is unified memory")
            return None

        # Someone else owns the placement -- decline. Each of these re-places the
        # model out from under a plan made here: -ot / --cpu-moe (or its env twin)
        # already moves tensors, a layer count overrides -ngl -1, a device list
        # changes which cards the resident half was sized against.
        if (
            _args_place_tensors_on_cpu(extra_args)
            or _env_places_tensors_on_cpu(source_env)
            or _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
            or str(source_env.get("LLAMA_ARG_N_GPU_LAYERS", "")).strip()
            or _extra_args_set_any_flag(extra_args, _DEVICE_FLAGS)
            or str(source_env.get("LLAMA_ARG_DEVICE", "")).strip()
            # A pinned DRAFT device is placement too and is not in _DEVICE_FLAGS.
            # Its reserve rides in extra_resident_bytes, which
            # _per_device_shortfall books onto device 0, while llama.cpp puts the
            # drafter on the pinned card -- approving a footprint for the wrong
            # device, then pinning it with --fit off. cpu/none are not a pin.
            or _extra_args_draft_device_pin(extra_args)
            # -sm row and -sm tensor split WITHIN a tensor rather than handing out
            # whole rows of layers, so the row model below does not describe them.
            # `tensor` is a real accepted value (common/arg.cpp:2762-2776) and goes
            # further than `row`: llama.cpp collapses every card into ONE meta
            # device (llama.cpp:157-215), so per-device budgets are meaningless,
            # and llama.cpp's own fitter refuses it (common/fit.cpp:182-183).
            # `none` and `layer` ARE describable and are handled after this gate.
            or (_extra_args_split_mode(extra_args, source_env) in ("row", "tensor"))
            # An INHERITED -sm none may never reach the child: on a layer-split
            # launch load_model pops LLAMA_ARG_SPLIT_MODE (plus the paired
            # LLAMA_ARG_TENSOR_SPLIT) for any non-"layer" mode
            # (llama_cpp.py:20452-20458). That runs AFTER this and its predicate is
            # not visible here, so budgeting the single main GPU below would plan
            # against a mode the child never sees and skip the per-device check
            # entirely (it short-circuits on one device). argv is the only spelling
            # that provably survives to the child.
            or (
                _extra_args_split_mode(extra_args, source_env) == "none"
                and _extra_args_split_mode(extra_args, {}) != "none"
            )
            # -mg is declined above as a device flag; its env twin is not a flag
            # and reaches the child anyway. Under -sm none llama.cpp keeps
            # devices[main_gpu] (llama.cpp:288-299), so budgeting the first
            # retained card would price the wrong GPU.
            or str(source_env.get("LLAMA_ARG_MAIN_GPU", "")).strip()
            # ANY explicit --fit, not just an enabling one. A retry revokes the
            # plan by appending "--fit on", and extras are appended BEFORE that,
            # so planning over a user's "--fit off" would let the revocation
            # silently overturn it. Same test _fit_off_retry_eligible uses.
            or any(
                str(a) in ("-fit", "--fit") or str(a).startswith(("-fit=", "--fit="))
                for a in (extra_args or ())
            )
            or str(source_env.get("LLAMA_ARG_FIT", "")).strip()
            # --rpc devices are REMOTE and go at the FRONT of the list
            # (llama.cpp:275), so the free-memory row split hands the first slice
            # of layers to a card Studio never detected. Every number here comes
            # from the local `gpus` snapshot, so the plan would credit local VRAM
            # for layers that went elsewhere and pin it with --fit off.
            or (_extra_args_device(extra_args, {"--rpc"}) or "").strip()
            or str(source_env.get("LLAMA_ARG_RPC", "")).strip()
            # --fit-target is VRAM the user told the fitter it may not spend
            # (common/fit.cpp:282-288). Emitting --fit off skips
            # common_params_fit_impl and drops the margin silently, while this
            # planner spends it. Decline, like any other explicit --fit.
            or fit_target_margin_in(extra_args, source_env) is not None
        ):
            logger.debug("Tensor spill: declined, pass-through arguments own the placement")
            return None

        # Slots are SIZING, not placement, and these numbers were priced at Unsloth's
        # own --parallel. A pass-through is appended after it and llama.cpp is
        # last-wins, so a larger one grows the attention cache and the recurrent
        # state under a deficit computed for the smaller count. Only larger matters:
        # a smaller value leaves the plan over-reserved, the safe direction.
        priced_parallel = int(inputs.get("n_parallel") or 1)
        override_parallel = _extra_args_n_parallel(extra_args, source_env)
        if override_parallel is not None and override_parallel > priced_parallel:
            logger.debug(
                "Tensor spill: declined, --parallel %d overrides the %d slots this was priced at",
                override_parallel,
                priced_parallel,
            )
            return None

        model_size = int(inputs.get("model_size") or 0)
        kv_cache_bytes = int(inputs.get("kv_cache_bytes") or 0)
        rows = list(inputs.get("gpus") or ())
        if not model_size or not kv_cache_bytes or not rows:
            return None
        if not self._can_estimate_kv():
            return None

        layout = self._tensor_spill_layout(inputs.get("model_path"))
        if layout is None or not layout.complete:
            return None

        # Per-device VRAM the planner may credit. SHARED rows are dropped, not
        # summed: an APU or iGPU reports host RAM as VRAM, so crediting it and then
        # spilling into the same RAM counts one pool twice.
        pinned = inputs.get("gpu_indices")
        shared = set(inputs.get("shared_gpu_ids") or ())
        pinned_set = None if pinned is None else set(pinned)
        # Dropping a shared device from the BUDGET only helps if the child stops
        # using it, and nothing here can promise that: the auto-Vulkan arm pins
        # every DETECTED gpu, iGPU included, and runs after this snapshot (so
        # gpu_indices reads None here); with no --device the child sees every card
        # anyway. llama.cpp splits rows by free memory and an iGPU's "free" is the
        # whole host pool, so it draws the MAJORITY of the layers and their caches
        # -- the opposite of this planner's premise. Decline instead.
        if shared and (pinned_set is None or (shared & pinned_set)):
            logger.debug(
                "Tensor spill: declined, a shared-memory GPU stays in the child's device list"
            )
            return None
        # The USABLE budget Unsloth's fit tested, not raw free: it carries the
        # VRAM-budget fraction and the per-card reserve floor. Falling back to free
        # keeps a caller that supplies no map working.
        usable_mib = inputs.get("gpu_usable_mib") or {}
        kept = [
            (idx, free_mib)
            for idx, free_mib in rows
            if idx not in shared and (pinned_set is None or idx in pinned_set)
        ]
        # -sm none is not a reason to decline, it is a device list of one:
        # llama.cpp keeps only devices[main_gpu] (llama.cpp:288-299), the
        # single-GPU case this planner has the most evidence for. -mg and
        # LLAMA_ARG_MAIN_GPU are declined above, so main_gpu is llama.cpp's default
        # of 0 -- the first kept row. ARGV only, deliberately: the env spelling is
        # declined above because load_model may strip it before launch, so it does
        # not describe the child's device list.
        if _extra_args_split_mode(extra_args, {}) == "none" and kept:
            kept = kept[:1]
        vram_per_device = [
            int(usable_mib.get(idx, free_mib) * 1024 * 1024) for idx, free_mib in kept
        ]
        # llama.cpp sizes its row ranges from RAW free VRAM (llama-model.cpp:1433),
        # so the split must be modelled on the raw numbers. The budget subtracts a
        # reserve that depends on each card's TOTAL, preserving the ratios only when
        # every card has the same free/total. Same filter and order as above, so
        # index i means the same device in both lists.
        split_weights = [int(free_mib * 1024 * 1024) for _idx, free_mib in kept]
        # -ts REPLACES that free-memory split rather than skewing it: llama.cpp
        # copies tensor_split into `splits` verbatim and prefix-sums it
        # (llama-model.cpp:1436-1447), so it IS the row-ownership weight, not a
        # reason to decline. A share of 0 draws no rows, which _device_slots
        # already models, and the length must match `kept` or the two lists stop
        # describing the same devices.
        # Read the env the CHILD will get: load_model pops LLAMA_ARG_TENSOR_SPLIT
        # together with a non-layer LLAMA_ARG_SPLIT_MODE (llama_cpp.py:20505-20511),
        # so an inherited -ts riding alongside such a mode never reaches the child
        # -- proving row ownership against the scrubbed shares approves the wrong
        # device and pins it with --fit off. argv is untouched by that
        # reconciliation, so it is always read.
        _inherited_sm = str(source_env.get("LLAMA_ARG_SPLIT_MODE", "")).strip().lower()
        _ts_env = source_env if _inherited_sm in ("", "layer") else {}
        _ts = _extra_args_tensor_split(extra_args, _ts_env)
        if _ts is None and (
            _extra_args_set_any_flag(extra_args, _TENSOR_SPLIT_FLAGS)
            or str(_ts_env.get("LLAMA_ARG_TENSOR_SPLIT", "")).strip()
        ):
            # A -ts we could not read is NOT "no -ts": the child still gets one,
            # and free-VRAM proportions under it are the shortfall this avoids.
            logger.debug("Tensor spill: declined, -ts is present but could not be parsed")
            return None
        if _ts is not None:
            if len(_ts) < len(kept):
                logger.debug(
                    "Tensor spill: declined, -ts names %d shares for %d devices",
                    len(_ts),
                    len(kept),
                )
                return None
            _scale = max(split_weights) if split_weights else 1
            split_weights = [int(round(p * _scale)) for p in _ts[: len(kept)]]
        if not vram_per_device:
            return None
        avail_mib = self._available_system_memory_mib()
        if avail_mib is None:
            return None

        # A separate drafter is a second MODEL, and an UNPINNED one is placed like
        # any other: common_base_params_to_speculative copies the draft device list
        # verbatim (common/speculative.cpp:2319-2331), and an empty one drops
        # llama_prepare_model_devices into its default enumeration of every visible
        # GPU (llama.cpp:184-276), so the drafter's weights AND its context follow
        # the free-memory row split onto every card. A PINNED one already declined
        # above. Its reserve rides in extra_resident_bytes, which
        # _per_device_shortfall books entirely on device 0, so every other card is
        # under-booked by its share -- and --fit off means common/fit.cpp never runs
        # to catch the overflow. Nothing here says how llama.cpp will split a model
        # this layout knows nothing about, so decline, like the pass-through adapter
        # below.
        if inputs.get("separate_draft_on_gpu") and len(vram_per_device) > 1:
            logger.debug(
                "Tensor spill: declined, a separate drafter's bytes cannot be placed "
                "across %d devices",
                len(vram_per_device),
            )
            return None

        # The trailing nextn/MTP blocks the layout dropped, charged back when a
        # draft will engage. Unsloth's budget already assumed they were paid for (an
        # embedded head contributes 0 to _mtp_draft_weights because its weights sit
        # inside model_size), but the planner rebuilds from the tensor table, where
        # they are gone -- leaving the deficit short by the whole MTP head.
        extra_gpu_bytes = int(inputs.get("extra_gpu_bytes") or 0)
        if inputs.get("mtp_will_engage") and layout.excluded_block_bytes:
            extra_gpu_bytes += layout.excluded_block_bytes

        # The compute buffer, on the same terms as the fit that sent us here:
        # ctx_compute is per device, compute_buffer_flat is one lump charged once
        # against the pool and booked onto device 0, where it lives.
        extra_gpu_bytes += int(inputs.get("compute_buffer_flat") or 0)

        # A projector Studio never resolved but the child loads anyway. arg.cpp
        # applies LLAMA_ARG_MMPROJ before argv (common/arg.cpp:780-802) and a
        # LLAMA_ARG_MMPROJ_URL download overwrites even the --mmproj this launch
        # emits (common/arg.cpp:500-503, :632-634), and the projector is GPU
        # resident unless --no-mmproj-offload says otherwise. extra_gpu_bytes above
        # carries only the RESOLVED projector, so those bytes sit in no term here
        # and the plan pins the shortfall with --fit off. The seam hands over the
        # same numbers the load-mode fit used, including its abstain for a URL or
        # an unreadable path.
        if inputs.get("env_mmproj_unsized"):
            logger.debug("Tensor spill: declined, an inherited projector could not be sized")
            return None
        extra_gpu_bytes += int(inputs.get("env_mmproj_bytes") or 0)

        # Pass-through --lora / --lora-scaled / --control-vector weights, GPU
        # resident and in no other term here. Both land on the base layer's buffer
        # type (llama-adapter.cpp:335, :67) and neither mmaps: the file is staged
        # with ggml_backend_tensor_set (:407), so the bytes are resident whatever
        # --load-mode says, and `model_size` is the base GGUF alone. Same treatment
        # _fits_without_paging gives them: a term, and an unreadable file abstains.
        sidecar_bytes = _sidecar_adapter_bytes(extra_args)
        if sidecar_bytes is None:
            logger.debug("Tensor spill: declined, a pass-through adapter could not be sized")
            return None
        # ...but a flat term is only right on ONE device. extra_resident_bytes is
        # charged entirely to device 0 (_per_device_shortfall), while a LoRA tensor
        # is allocated on its BASE tensor's buffer (llama-adapter.cpp:335) and a
        # control-vector row on model.select_buft(il) (:67) -- so on a layer split
        # they follow the layers onto every card. Booking them all on the main GPU
        # under-books the others, and --fit off means common/fit.cpp never runs to
        # catch the overflow. The layout is built from the base GGUF alone and holds
        # no adapter tensor table, so the per-device share cannot be derived here.
        # Decline, like every other placement this planner cannot price.
        if sidecar_bytes and len(vram_per_device) > 1:
            logger.debug(
                "Tensor spill: declined, a pass-through adapter's bytes cannot be placed "
                "across %d devices",
                len(vram_per_device),
            )
            return None
        extra_gpu_bytes += sidecar_bytes

        return plan_placement(
            layout,
            vram_per_device,
            avail_mib * 1024 * 1024,
            int(inputs.get("n_ctx") or 0),
            split_weights_per_device = split_weights,
            kv_layer_weights = list(inputs.get("kv_layer_weights") or ()),
            opts = PlanOptions(
                overhead_bytes_per_device = (
                    int(inputs.get("soft_overhead") or 0)
                    + self._PIPELINE_PER_DEVICE_OVERHEAD_MIB * 1024 * 1024
                    + int(inputs.get("ctx_compute_per_device") or 0)
                ),
                # Module-level, unlike the line above, so not reachable through self.
                host_ram_headroom_bytes = _HOST_RAM_HEADROOM_MIB * 1024 * 1024,
                # -nkvo is not a reason to decline: it moves the cache and the
                # recurrent state OUT of VRAM, so the deficit is smaller, not
                # larger.
                kv_on_host = not _kv_offload_from_args(extra_args, env = source_env),
                # GPU-resident allocations the layout cannot see, since it is built
                # from the target GGUF alone: the vision projector and the MTP draft
                # reserve. Both are in the footprint that produced the use_fit
                # verdict, so omitting them makes the deficit too small.
                extra_resident_bytes = extra_gpu_bytes,
                # Spilled decode runs on the CPU backend (ggml migrates an op to the
                # GPU only at batch >= 32, and decode is batch 1), so the penalty
                # tracks core count. Read the real one, not a default.
                host = HostProfile(
                    threads = os.cpu_count() or 1,
                    # Wired, not defaulted. On a unified-memory APU the credited
                    # "VRAM" IS system RAM, so an -ot spill frees no device memory
                    # and only buys the CPU backend's slower read path. The planner
                    # abstains on those, but only if told: left at False it would
                    # plan a spill on every Strix Halo (gfx1151), Strix Point
                    # (gfx1150), Krackan (gfx1152) and Phoenix iGPU. Unsloth already
                    # classifies these from the driver's integrated flag, then
                    # gcnArchName, then the device-name substrings.
                    unified_memory = self._amd_apu_wants_unified_memory(inputs.get("gpu_indices")),
                ),
            ),
            # The cache Unsloth already priced for THIS launch, byte-accurately:
            # cache dtype, SWA windows, MLA latents, unified vs per-slot streams,
            # cell padding and flash-attention V padding. layout.kv_bytes() is a
            # bare f16 GQA product with none of those, so on an MLA or f32-cache
            # load it lands well UNDER the real cache. A floor, not a replacement,
            # so the layout still wins where it is the more conservative.
            kv_bytes_floor = kv_cache_bytes,
        )

    @staticmethod
    def _spill_plan_flags_for(plan: "Optional[SpillPlan]") -> "list[str]":
        """The argv tokens for ``plan``, or ``[]`` when it must not be emitted.

        The emptiness test is the point. ``Plan`` is a dataclass with no
        ``__bool__``/``__len__``, so EVERY instance is truthy -- including the
        ones ``plan_placement`` returns to report that it could not place the
        load (``insufficient``), that it abstained (incomplete layout, unified
        memory, no creditable VRAM), or that the load already fits. Emitting for
        those would append ``-ngl -1 --fit off`` with no tensor moved to the
        host, i.e. pin every layer to the GPU and switch the fitter off on
        exactly the loads the planner just said do not fit. Only a plan that
        actually spills something earns the flags; everything else falls through
        to ``--fit on``, which is what this arm did before the planner existed.

        One flag per pattern: llama-server ACCUMULATES repeated ``-ot``
        (common/arg.cpp:2657 push_backs into the shared override vector). Do not
        join with ";" -- that is llama-bench's separator; llama-server splits an
        ``-ot`` value on ",".

        ``--fit off`` is REQUIRED, not tidiness. The fitter aborts only on an
        n_gpu_layers the USER set (common/fit.cpp:377) and -1 is llama.cpp's own
        default (llama-model.cpp:2453), so ``-ngl -1`` does not hold it off: left
        on, it would re-place layers over this plan and put the cache back on the
        host. ``-ngl -1`` keeps every layer assigned to a GPU so the cache stays
        there (llama-kv-cache.cpp:215); the ``-ot`` patterns move only the named
        weights.
        """
        if plan is None or not plan.spills_anything:
            return []
        tokens = [tok for pat in plan.ot_patterns for tok in ("-ot", f"{pat}=CPU")]
        if not tokens:
            return []
        return ["-ngl", "-1", "--fit", "off", *tokens]

    def _drop_tensor_spill(self, run_cmd: "list[str]", why: str) -> "list[str]":
        """Take the spill plan back out of an argv and restore ``--fit on``.

        Every retry that re-places the model or resizes the cache invalidates the
        arithmetic the plan was built on: a no-flash retry changes the KV dtype, an
        arch fallback changes the device set, a projector move changes the resident
        floor. Rather than re-plan on a path that is already recovering from a
        crash, hand the placement back to llama.cpp, which is what this arm did
        before the planner existed.

        The record is deliberately NOT cleared: the CPU fallback respawns later
        from an argv that may still carry these tokens.
        """
        if not self._spill_plan_flags:
            return run_cmd
        stripped = _without_subsequence(run_cmd, self._spill_plan_flags)
        if stripped == run_cmd:
            return run_cmd
        logger.info("Tensor spill: dropping the plan for the %s retry; %s", why, "using --fit on")
        return [*stripped, "--fit", "on"]

    def _tensor_spill_layout(self, model_path: "Optional[str]") -> "Optional[ModelLayout]":
        """The GGUF's placement buckets, read once per path and cached.

        Per BLOCK, not per bucket total, so the planner can spill the minimum set
        that closes the deficit rather than the whole FFN. That matters: the spill
        penalty is linear in bytes (measured 5.544 ms/GiB across 16/32/48/65
        blocks, intercept -0.10 ms), so every byte spilled beyond the deficit is
        paid on every token for nothing.

        Any read failure returns None and the whole feature abstains, leaving the
        argv byte-identical to today. A guess here would be priced as a fit.
        """
        from core.inference.offload_layout import layout_from_gguf

        if not model_path:
            return None
        # Keyed on file IDENTITY, not name: the backend outlives a load, so
        # re-downloading or re-quantising to the same path would otherwise plan
        # against the OLD tensor table and understate the deficit. Same
        # (size, mtime_ns) stat identity _slot_launch_fingerprint uses.
        try:
            st = os.stat(model_path)
            key = (model_path, st.st_size, st.st_mtime_ns)
        except OSError:
            key = (model_path, None, None)
        cached = getattr(self, "_spill_layout_cache", None)
        if cached is not None and cached[0] == key:
            return cached[1]
        try:
            layout = layout_from_gguf(model_path)
        except Exception as e:  # unreadable, truncated, or an arch we cannot bucket
            logger.debug("Tensor spill: cannot read layout from %s (%s)", model_path, e)
            layout = None
        self._spill_layout_cache = (key, layout)
        return layout

    @staticmethod
    def _fit_off_retry_eligible(cmd: "list[str]", use_fit: bool) -> bool:
        """Whether a llama-server startup crash may be retried with --fit off.

        Only when Unsloth's own VRAM math placed the model (use_fit=False)
        and nothing on the command line set the fit mode explicitly
        (-fit / --fit, space- or equals-form). --fit-ctx / --fit-target /
        -fitc / -fitt tune the fit step but do not select the mode, so
        they do not block the retry.
        """
        if use_fit:
            return False
        for a in cmd:
            if a in ("-fit", "--fit") or a.startswith(("-fit=", "--fit=")):
                return False
        return True

    def _probe_mtp_decode(self, timeout: float = 60.0) -> bool:
        """One tiny /completion to confirm MTP survives the first decode.

        MTP-draft can pass /health yet crash the flash-attn kernel only once
        tokens generate (e.g. under --split-mode tensor). False on any error so
        the caller can drop MTP and retry.
        """
        url = f"{self.base_url}/completion"
        payload = {"prompt": "Hi", "n_predict": 4, "temperature": 0.0, "stream": False}
        try:
            resp = httpx.post(
                url,
                json = payload,
                timeout = timeout,
                headers = self._auth_headers,
                trust_env = False,
            )
        except Exception as e:
            logger.debug(f"MTP decode probe failed: {e}")
            return False
        if resp.status_code != 200:
            logger.debug(f"MTP decode probe returned HTTP {resp.status_code}")
            return False
        # A crash can drop the connection or kill the process right after a reply.
        if self._process is not None and self._process.poll() is not None:
            return False
        return True

    def _slot_launch_fingerprint(self) -> tuple:
        # KV validity keys on extra args, stat'd sidecar weights, effective ctx.
        sidecars = []
        for path in self._sidecar_weight_files():
            try:
                st = os.stat(path)
                sidecars.append((path, st.st_size, st.st_mtime_ns))
            except OSError:
                sidecars.append((path, None, None))
        return (
            tuple(self._extra_args or ()),
            tuple(sidecars),
            self._requested_n_ctx,
            self._effective_context_length,
            self._effective_cache_types,
            self.effective_parallel_slots,
            self._swa_full,
            self._kv_cache_unified,
            self._n_ubatch,
            self._flash_attn_enabled,
        )

    @staticmethod
    def _gguf_load_source_identity(path: str, mmproj_path: Optional[str] = None) -> Optional[tuple]:
        """Identity of the exact GGUF inode(s) handed to the resident process."""
        p = Path(path)
        paths = [p]
        match = _SHARD_FULL_RE.match(p.name)
        if match:
            prefix, _first, total = match.groups()
            paths = [
                p.with_name(f"{prefix}-{index:05d}-of-{total}{p.suffix}")
                for index in range(1, int(total) + 1)
            ]
        try:
            identity = []
            for shard in paths:
                resolved = shard.resolve()
                stat = shard.stat()
                identity.append(
                    (
                        str(resolved),
                        stat.st_dev,
                        stat.st_ino,
                        stat.st_size,
                        stat.st_mtime_ns,
                    )
                )
            if mmproj_path:
                projector = Path(mmproj_path)
                resolved = projector.resolve()
                stat = projector.stat()
                identity.append(
                    (
                        "mmproj",
                        str(resolved),
                        stat.st_dev,
                        stat.st_ino,
                        stat.st_size,
                        stat.st_mtime_ns,
                    )
                )
            return tuple(identity)
        except (OSError, RuntimeError):
            return None

    def _gguf_file_identity(self, path) -> Optional[tuple]:
        # (size, mtime_ns) per shard: a split GGUF keys KV validity on every sibling.
        p = Path(path)
        paths = [p]
        m = _SHARD_FULL_RE.match(p.name)
        if m:
            prefix, _first, total = m.groups()
            paths = [
                p.with_name(f"{prefix}-{i:05d}-of-{total}{p.suffix}")
                for i in range(1, int(total) + 1)
            ]
        try:
            return tuple((sp.stat().st_size, sp.stat().st_mtime_ns) for sp in paths)
        except OSError:
            return None

    _SIDECAR_WEIGHT_FLAGS = (
        "--lora",
        "--lora-scaled",
        "--control-vector",
        "--control-vector-scaled",
    )

    def _sidecar_weight_files(self) -> list[str]:
        # llama.cpp: comma-separated paths, FNAME:SCALE on -scaled (older builds: FNAME SCALE).
        args = [str(a).strip() for a in (self._extra_args or ())]
        files: list[str] = []
        for i, arg in enumerate(args):
            flag = _flag_name(arg)
            _, sep, inline = arg.partition("=")
            if flag not in self._SIDECAR_WEIGHT_FLAGS:
                continue
            operand = inline if sep else (args[i + 1] if i + 1 < len(args) else "")
            if not operand:
                continue
            candidates = [operand]
            pieces = [p for p in operand.split(",") if p]
            if len(pieces) > 1:
                candidates.extend(pieces)
            if flag.endswith("-scaled"):
                for item in list(candidates):
                    # ":<number>" tail is a scale; rpartition spares drive letters.
                    head, colon, tail = item.rpartition(":")
                    if not (colon and head):
                        continue
                    try:
                        float(tail)
                    except ValueError:
                        continue
                    candidates.append(head)
            for cand in candidates:
                if cand not in files:
                    files.append(cand)
        return files

    def _prompt_cache_off(self) -> bool:
        # Caching off makes restores useless; last prompt-cache flag wins, env only when unset.
        last = None
        for arg in self._extra_args or ():
            flag = arg.strip().split("=", 1)[0]
            if flag in ("--cache-prompt", "--no-cache-prompt"):
                last = flag
        if last is not None:
            return last == "--no-cache-prompt"
        if self._prompt_cache_disabled:
            return True
        if os.environ.get("LLAMA_ARG_NO_CACHE_PROMPT") is not None:
            return True
        env = (os.environ.get("LLAMA_ARG_CACHE_PROMPT") or "").strip().lower()
        return env in _LLAMA_ARG_FALSE_VALUES

    def save_slots_for_resume(
        self, should_abort: Optional[Callable[[], bool]] = None
    ) -> Optional[dict]:
        if (
            not self.is_loaded
            or not self._slot_save_dir
            or not self._gguf_path
            or self._prompt_cache_off()
        ):
            return None
        # Same predicate as the estimator's SWA path: a window alone is not enough.
        # phi3 GGUFs carry attention.sliding_window but no key/value length, and
        # llama.cpp forces them back to a non-SWA cache, so their slots do restore.
        if (
            (self._sliding_window or 0) > 0
            and self._kv_key_length is not None
            and self._kv_value_length is not None
            and not self._swa_full
        ):
            logger.debug("Skipping slot save: compact SWA cache cannot be reused after restart")
            return None
        save_dir = Path(self._slot_save_dir)
        gguf_stat = self._gguf_file_identity(self._gguf_path)
        if gguf_stat is None:
            return None
        launch = self._slot_launch_fingerprint()
        # If the GGUF or a sidecar was swapped on disk while the original weights
        # stayed mapped, the live KV belongs to the old weights but a reload would
        # load the new file. Persisting it would let restore misapply stale KV.
        if self._slot_loaded_identity is not None and self._slot_loaded_identity != (
            gguf_stat,
            launch,
        ):
            logger.debug("Skipping slot save: model files changed on disk since load")
            return None
        try:
            estimate = self._estimate_kv_cache_bytes(
                self._kv_cache_context_total
                or self._effective_context_length
                or self._context_length
                or 0,
                max(self._effective_cache_types, key = _kv_bytes_per_elem),
                n_parallel = self.effective_parallel_slots,
                swa_full = self._swa_full,
                kv_unified = self._kv_cache_unified,
                n_ubatch = self._n_ubatch,
                flash_attn = self._flash_attn_enabled,
            )
            # Skip before writing anything when the estimate alone blows the cap,
            # rather than fully writing a slot and discarding it afterwards.
            if estimate > _SLOT_SAVE_MAX_BYTES:
                logger.debug(
                    "Skipping slot save: estimated %d bytes exceeds cap %d",
                    estimate,
                    _SLOT_SAVE_MAX_BYTES,
                )
                return None
            # A 0 estimate means metadata was insufficient, not a zero-byte cache:
            # a slot can still be many GiB, so demand room for the whole cap before
            # trusting the post-write check.
            required = (estimate if estimate > 0 else _SLOT_SAVE_MAX_BYTES) + (1 << 30)
            if shutil.disk_usage(save_dir).free < required:
                logger.debug("Skipping slot save: insufficient free disk")
                return None
        except Exception:
            pass
        token = uuid.uuid4().hex[:8]
        entries: list[dict] = []
        total_bytes = 0
        for slot in range(self.effective_parallel_slots):
            # A request pending mid-save waits on the gate; stop wasting its time.
            if should_abort is not None and should_abort():
                break
            filename = f"resume-{token}-slot{slot}.bin"
            path = save_dir / filename
            try:
                resp = httpx.post(
                    f"{self.base_url}/slots/{slot}",
                    params = {"action": "save"},
                    json = {"filename": filename},
                    headers = self._auth_headers,
                    timeout = _SLOT_SAVE_HTTP_TIMEOUT,
                    trust_env = False,
                )
            except Exception as e:
                logger.debug(f"slot {slot} save failed: {e}")
                with contextlib.suppress(OSError):
                    path.unlink()
                break
            if resp.status_code != 200:
                logger.debug(f"slot {slot} save returned HTTP {resp.status_code}")
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            try:
                body = resp.json()
                if not isinstance(body, dict):
                    raise ValueError("slot save response was not a JSON object")
                n_saved = int(body.get("n_saved") or 0)
            except Exception as e:
                # A 200 that still wrote a file but returns a malformed body must
                # clean up like the transport/HTTP error paths above, or the file
                # (which holds chat KV) is orphaned until the next startup sweep.
                logger.debug(f"slot {slot} save returned an invalid response: {e}")
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            if n_saved <= 0:
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            # Account by the bytes actually on disk, not the server-reported
            # count, so the cap holds even if a custom binary under-reports.
            try:
                n_written = path.stat().st_size
            except OSError:
                n_written = 0
            total_bytes += n_written
            entries.append({"id": slot, "filename": filename, "n_saved": n_saved})
            if total_bytes > _SLOT_SAVE_MAX_BYTES:
                break  # already over the cap; the discard below cleans up
        if not entries:
            return None
        if total_bytes > _SLOT_SAVE_MAX_BYTES:
            logger.debug(
                "Discarding slot save: %d bytes exceeds cap %d",
                total_bytes,
                _SLOT_SAVE_MAX_BYTES,
            )
            for entry in entries:
                with contextlib.suppress(OSError):
                    (save_dir / entry["filename"]).unlink()
            return None
        return {
            "dir": self._slot_save_dir,
            "binary": self._slot_save_binary,
            "gguf": str(self._gguf_path),
            "gguf_stat": gguf_stat,
            "launch": launch,
            "slots": entries,
        }

    def restore_slots_for_resume(self, manifest: dict) -> None:
        if not self.is_loaded or not self._slot_save_dir:
            return
        for entry in manifest.get("slots") or []:
            try:
                resp = httpx.post(
                    f"{self.base_url}/slots/{int(entry['id'])}",
                    params = {"action": "restore"},
                    json = {"filename": str(entry["filename"])},
                    headers = self._auth_headers,
                    timeout = _SLOT_SAVE_HTTP_TIMEOUT,
                    trust_env = False,
                )
            except Exception as e:
                logger.debug(f"slot restore failed: {e}")
                break
            if resp.status_code != 200:
                logger.debug(f"slot {entry.get('id')} restore returned HTTP {resp.status_code}")

    def _maybe_recover_from_mtp_crash(self, exc: Optional[BaseException] = None) -> bool:
        """Schedule one background reload without MTP after a mid-generation death.

        MTP+tensor can crash the flash-attn kernel on a later request, after
        load_model returned, past the load-time fallback and decode probe. Not a
        persistent ban: a fresh load re-tries MTP. Returns True if scheduled.
        """
        # Cheap async-safe gate: only our live MTP+tensor launch, not cancelled,
        # with a snapshot to replay.
        if self._cancel_event.is_set():
            return False
        if not self._mtp_runtime_fallback_active:
            return False
        # Read before claiming: a raise after the claim strands the flag, and nothing
        # else clears it, blocking every later respawn.
        snapshot = self._last_load_intent
        proc = self._process
        if snapshot is None or proc is None:
            return False
        # Single-flight: the first failure claims the reload.
        with self._mtp_runtime_fallback_lock:
            if self._mtp_runtime_fallback_in_progress:
                return False
            self._mtp_runtime_fallback_in_progress = True

        def _recover():
            try:
                # Confirm the process really exited (the error can arrive a beat
                # early) so a transient stream error can't disable MTP.
                deadline = time.monotonic() + 5.0
                while proc.poll() is None and time.monotonic() < deadline:
                    time.sleep(0.1)
                if proc.poll() is None:
                    logger.debug("Generation error but llama-server is alive; keeping MTP.")
                    return
                logger.warning(
                    "llama-server exited mid-generation with MTP under tensor "
                    "parallelism (%s); reloading without speculative decoding.",
                    type(exc).__name__ if exc is not None else "server exited",
                )
                # Re-check under the load lock (RLock allows the nested
                # load_model) so a newer load isn't clobbered by this stale replay.
                requested_mode = snapshot.speculative_type
                with self._serial_load_lock:
                    if self._cancel_event.is_set():
                        logger.info("MTP-crash reload skipped: load was cancelled/unloaded.")
                        return
                    if self._process is not proc:
                        logger.info("MTP-crash reload skipped: a newer load is already active.")
                        return
                    if self._last_load_intent != snapshot:
                        logger.info("MTP-crash reload skipped: load settings changed.")
                        return
                    # Appending --spec-default cannot drop MTP: llama.cpp appends spec
                    # types rather than replacing, so the extras have to lose theirs.
                    # Once they do, Unsloth owns the block and the launch scrubs the
                    # inherited env for the replay too.
                    _ea = list(snapshot.extra_args or ())
                    fallback_extra_args = snapshot.extra_args
                    if _extra_args_requests_mtp(_ea, env = _child_spec_env(_ea)):
                        fallback_extra_args = tuple(
                            strip_shadowing_flags(
                                _ea,
                                strip_context = False,
                                strip_cache = False,
                                strip_spec = True,
                                strip_template = False,
                                strip_split_mode = False,
                            )
                        )
                    fallback = replace(
                        snapshot,
                        speculative_type = "off",
                        extra_args = fallback_extra_args,
                    )
                    self.load_model(fallback)
                    # Same reason the mode is restored below: the replay launched a
                    # stripped list but the caller keeps sending the original, so a
                    # comparator seeing only the stripped one would reload the very MTP
                    # configuration that just crashed.
                    if fallback_extra_args is not snapshot.extra_args:
                        self._requested_extra_args = (
                            self._strip_device_extra_args(_ea)
                            if snapshot.gpu_ids is not None
                            else list(_ea)
                        )
                    # Restore the requested mode + reason load_model("off") cleared,
                    # so /status shows the user's mode + note (like the startup fallback).
                    self._requested_spec_mode = _canonicalize_spec_mode(requested_mode)
                    self._spec_fallback_reason = "runtime_error"
                logger.info("Reloaded without MTP after the tensor-parallel crash.")
            except Exception as e:
                logger.error(f"Reload without MTP failed: {e}")
            finally:
                with self._mtp_runtime_fallback_lock:
                    self._mtp_runtime_fallback_in_progress = False

        try:
            threading.Thread(target = _recover, daemon = True, name = "mtp-crash-reload").start()
        except RuntimeError as exc:
            # Release the claim: a reload that never started would block respawn forever.
            with self._mtp_runtime_fallback_lock:
                self._mtp_runtime_fallback_in_progress = False
            logger.error(f"Could not start the MTP-crash reload: {exc}")
            return False
        return True

    def _start_mtp_crash_watchdog(self) -> None:
        """Background poll that recovers on an MTP+tensor crash even when no
        request observes it (direct proxy endpoints, or nothing in flight).

        Armed only for a live MTP+tensor launch; the no-MTP reload disarms it, so
        it can't loop.
        """
        if not self._mtp_runtime_fallback_active:
            return
        proc = self._process
        if proc is None:
            return
        # Replace any prior watchdog (loads are serialised, so at most one).
        self._stop_mtp_crash_watchdog()
        stop = threading.Event()
        self._mtp_watchdog_stop = stop

        def _watch():
            # Exit on stop or process death. _kill_process sets stop before
            # terminating, so re-check it: only a real crash (stop unset) recovers.
            while not stop.wait(1.0):
                if proc.poll() is not None:
                    if not stop.is_set():
                        self._maybe_recover_from_mtp_crash()
                    return

        t = threading.Thread(target = _watch, daemon = True, name = "mtp-crash-watchdog")
        self._mtp_watchdog_thread = t
        t.start()

    def _stop_mtp_crash_watchdog(self) -> None:
        """Signal the crash watchdog to exit; called before any deliberate kill."""
        stop = getattr(self, "_mtp_watchdog_stop", None)
        if stop is not None:
            stop.set()
        self._mtp_watchdog_thread = None

    def _wait_for_health(
        self,
        timeout: float = 120.0,
        interval: float = 0.5,
    ) -> bool:
        """Poll llama-server's /health until 200; also detect early exit/crash."""
        deadline = time.monotonic() + timeout
        url = f"{self.base_url}/health"
        health_probe_event = getattr(self, "_health_probe_event", None)
        if health_probe_event is None:  # Backward-compatible with lightweight test doubles.
            health_probe_event = self._health_probe_event = threading.Event()

        while time.monotonic() < deadline:
            # Cleared before probing so output during the request stays latched for
            # the fallback wait below.
            health_probe_event.clear()
            # Process crashed?
            if self._process.poll() is not None:
                # Let the drain thread collect final output.
                if self._stdout_thread is not None:
                    self._stdout_thread.join(timeout = 2)
                output = "\n".join(self._stdout_lines[-50:])
                # Keep the TAIL: crash details (abort reason, ROCm/CUDA error
                # text) print last, after the long startup banner. Head
                # truncation has cut off exactly the diagnostic line before.
                _log_hint = (
                    f" Full log: {self._llama_log_path}"
                    if getattr(self, "_llama_log_path", None)
                    else ""
                )
                logger.error(
                    f"llama-server exited with code {self._process.returncode}. "
                    f"Output (tail): {output[-2000:]}{_log_hint}"
                )
                return False

            try:
                # trust_env=False: skip ambient HTTP(S)_PROXY, which if it 503s
                # for 127.0.0.1 loops the probe until timeout and hangs load.
                resp = httpx.get(url, timeout = 2.0, trust_env = False)
                if resp.status_code == 200:
                    return True
            except (
                httpx.ConnectError,
                httpx.TimeoutException,
                # ReadError covers TCP RST mid-read while still binding the port
                # (Windows: WinError 10054); the crash branch catches real exits.
                httpx.ReadError,
                httpx.RemoteProtocolError,
                httpx.WriteError,
            ):
                pass

            health_probe_event.wait(interval)

        # Leave a marker so _classify_llama_start_failure tells a live but
        # never-healthy load (too large, or a proxy hijacking the loopback
        # probe) apart from a bad GGUF (#5740).
        self._stdout_lines.append(f"llama-server health check timed out after {timeout}s")
        logger.error(f"llama-server health check timed out after {timeout}s")
        return False

    @staticmethod
    def _fit_target_margin_mib(
        *,
        auto_fit: bool,
        fit_target_delta_mib: float = 0.0,
        supports_fit_target: bool = True,
    ) -> float:
        """Free VRAM per device llama.cpp's fitter keeps for itself under ``--fit on``.

        One reader for the flag and for the load-mode fit, so the margin the child is
        told to keep and the margin the fit refuses to spend cannot drift. A server
        too old for ``--fit-target`` still keeps llama.cpp's own 1024 MiB default
        (common/common.h, ``fit_params_target``), which is also what the legacy path
        deliberately stays silent about.
        """
        if not supports_fit_target:
            return _LLAMA_FIT_TARGET_DEFAULT_MIB
        base = _VRAM_FLOOR_RESERVE_MIB if auto_fit else _LLAMA_FIT_TARGET_DEFAULT_MIB
        return max(_VRAM_FLOOR_RESERVE_MIB, base + fit_target_delta_mib)

    @staticmethod
    def _ctx_integrity_flags(
        n_parallel: int,
        use_fit: bool,
        auto_fit: bool,
        requested_ctx: int,
        effective_ctx: int,
        caps: dict,
        *,
        fit_target_delta_mib: float = 0.0,
    ) -> list[str]:
        """Flags that keep the per-request window equal to the advertised ctx.

        Explicit ``--parallel`` disables llama-server's auto-slots
        ``--kv-unified`` default, silently splitting ``-c`` into per-slot
        windows of ``-c / N``; restore the shared pool so one request can use
        the full context. With ``--fit on``, ``--fit-ctx`` floors the fit step
        at an explicitly requested ctx so it offloads or fails instead of
        silently shrinking the window. The 8192 auto-floor applies only under
        Manual + Auto (``auto_fit``), which omits ``-c``: on the legacy auto path
        ``-c 0`` already pins the native window and ``--fit-ctx 8192`` would
        override it down to 8192. ``--fit-target`` starts from the tighter 512 MiB
        margin there and from llama.cpp's own default on the legacy path, moved by
        whatever the VRAM budget asks for either way (``fit_target_delta_mib``)
        and never below the 512 MiB floor.
        """
        flags: list[str] = []
        if n_parallel > 1 and caps.get("supports_kv_unified"):
            flags.append("--kv-unified")
        if use_fit and caps.get("supports_fit_ctx"):
            if requested_ctx > 0 and effective_ctx > 0:
                # Floor the fit step at the explicitly requested ctx.
                flags.extend(["--fit-ctx", str(effective_ctx)])
            elif auto_fit:
                # Manual + Auto omits -c, so floor at 8192 so --fit doesn't
                # shrink the window below a usable size.
                flags.extend(["--fit-ctx", "8192"])
        if use_fit and caps.get("supports_fit_target"):
            # Each path keeps its own starting margin: the tighter 512 under Manual
            # + Auto, so llama.cpp packs more on before spilling to system RAM, and
            # llama.cpp's own 1024 on the legacy path, which passes nothing today.
            # The budget moves that margin from where the path already sits, so the
            # default changes neither, and a raise stops at the same 512 floor every
            # other reserve here respects.
            _target = LlamaCppBackend._fit_target_margin_mib(
                auto_fit = auto_fit,
                fit_target_delta_mib = fit_target_delta_mib,
            )
            # The legacy path stays silent when it would only restate llama.cpp's
            # own default, so an untouched slider leaves the command unchanged.
            if auto_fit or _target != _LLAMA_FIT_TARGET_DEFAULT_MIB:
                flags.extend(["--fit-target", str(int(_target))])
        return flags

    def _query_server_props(self) -> Optional[dict]:
        """llama-server's ``/props``, or None when it cannot be read."""
        url = f"{self.base_url}/props"
        try:
            # /props is not one of llama-server's public endpoints, so under
            # UNSLOTH_DIRECT_STREAM=1 (which launches the child with --api-key)
            # an unauthenticated read 401s: the context readback silently keeps
            # the requested -c, and video reads as unsupported on a model that
            # supports it. None when there is no child key, which is httpx's
            # default and what every other call site here relies on.
            resp = httpx.get(url, headers = self._auth_headers, timeout = 5.0, trust_env = False)
            if resp.status_code != 200:
                return None
            props = resp.json()
            return props if isinstance(props, dict) else None
        except Exception:
            return None

    def _query_server_n_ctx(self) -> Optional[int]:
        """Per-slot context llama-server actually allocated, from ``/props``.

        The memory-fit step or ``--parallel`` slot split can leave this below
        the requested ``-c``; requests are validated against this value.

        Records the declared modalities on the way past: video input depends on
        build flags and ffmpeg, neither visible from the GGUF.
        """
        props = self._query_server_props()
        if props is None:
            return None
        modalities = props.get("modalities")
        if isinstance(modalities, dict):
            self._has_video_input = bool(modalities.get("video"))
        settings = props.get("default_generation_settings") or {}
        n_ctx = settings.get("n_ctx")
        return int(n_ctx) if n_ctx else None

    def _reconcile_effective_ctx_with_server(self, requested_n_ctx: int = 0) -> None:
        """Adopt the server's real ``n_ctx`` within an explicit requested ceiling.

        Keeps ``context_length`` (load response, status route, passthrough
        ``max_tokens`` ceiling) honest; clients sized to the requested value
        would otherwise hit ``exceed_context_size_error`` 400s early. A trailing
        pass-through ``--ctx-size`` can also make the server larger than Studio's
        pre-launch VRAM-fit estimate; publish that confirmed allocation without
        advertising beyond the user's resolved explicit request.

        ``requested_n_ctx`` is the EXPLICIT pass-through override (0 when absent),
        not ``resolve_requested_ctx``'s field fallback: only a flag emitted after
        Studio's own ``-c`` can allocate past the fit, so gating on the flag keeps
        llama.cpp's context padding from being published as an override that does
        not exist.

        ``_max_context_length`` deliberately stays put: /props confirms what was
        ALLOCATED, not that it fits VRAM without spilling, so the "may use system
        RAM" warning is right and ``max_context_length < context_length`` is legal.
        """
        actual_n_ctx = self._query_server_n_ctx()
        if not actual_n_ctx or actual_n_ctx <= 0:
            return
        slots = 1 if self._kv_cache_unified else self.effective_parallel_slots
        self._kv_cache_context_total = actual_n_ctx * slots
        effective_n_ctx = self._effective_context_length
        if not effective_n_ctx:
            # Same ceiling as the raise below, or a missing seed would advertise
            # past the explicit request.
            self._effective_context_length = (
                min(actual_n_ctx, requested_n_ctx) if requested_n_ctx > 0 else actual_n_ctx
            )
            return
        if actual_n_ctx < effective_n_ctx:
            logger.warning(
                "llama-server allocated a smaller per-request context than "
                f"requested ({effective_n_ctx} -> {actual_n_ctx}; "
                "memory fit or --parallel slot split); clients must treat "
                f"{actual_n_ctx} as the real context window."
            )
            self._effective_context_length = actual_n_ctx
            return
        if requested_n_ctx > effective_n_ctx:
            confirmed_n_ctx = min(actual_n_ctx, requested_n_ctx)
            if confirmed_n_ctx > effective_n_ctx:
                logger.info(
                    "llama-server confirmed a larger per-request context from "
                    f"the explicit override ({effective_n_ctx} -> {confirmed_n_ctx})."
                )
                self._effective_context_length = confirmed_n_ctx

    # ── Message building (OpenAI format) ──────────────────────────

    @staticmethod
    def _parse_tool_calls_from_text(
        content: str,
        *,
        allow_incomplete: bool = True,
        enabled_tool_names: Optional[set] = None,
    ) -> list[dict]:
        """Wrapper around the shared parser; ``enabled_tool_names`` gates the markerless bare-JSON form."""
        return _shared_parse_tool_calls_from_text(
            content,
            allow_incomplete = allow_incomplete,
            enabled_tool_names = enabled_tool_names,
        )

    @staticmethod
    def _build_openai_messages(messages: list[dict], image_b64: Optional[str] = None) -> list[dict]:
        """Build OpenAI-format messages, optionally injecting an image_url part
        into the last user message for vision models. As-is if no image."""
        if not image_b64:
            return messages

        # Convert the last user message to multimodal content parts
        result = [msg.copy() for msg in messages]
        last_user_idx = None
        for i, msg in enumerate(result):
            if msg["role"] == "user":
                last_user_idx = i

        if last_user_idx is not None:
            text_content = result[last_user_idx].get("content", "")
            result[last_user_idx]["content"] = [
                {"type": "text", "text": text_content},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/png;base64,{image_b64}",
                    },
                },
            ]

        return result

    # ── Generation (proxy to llama-server) ────────────────────────

    @contextlib.contextmanager
    def _open_stream(self, url: str, payload: dict, cancel_event):
        """Open a streaming POST to llama-server, retrying through prefill, and
        yield ``(response, first_token_deadline)`` once a 200 lands. Owns the
        httpx.Client + auth headers for the stream's lifetime; raises
        RuntimeError on a non-200. Shared scaffold for the streaming consumers,
        which differ only in how they parse the SSE body."""
        stream_timeout = httpx.Timeout(connect = 10, read = 0.5, write = 10, pool = 10)
        with httpx.Client(
            timeout = stream_timeout,
            limits = httpx.Limits(max_keepalive_connections = 0),
            trust_env = False,
        ) as client:
            first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
            with self._stream_with_retry(
                client,
                url,
                payload,
                cancel_event,
                headers = self._auth_headers,
                first_token_deadline = first_token_deadline,
            ) as response:
                if response.status_code != 200:
                    error_body = response.read().decode()
                    raise RuntimeError(
                        f"llama-server returned {response.status_code}: {error_body}"
                    )
                yield response, first_token_deadline

    @staticmethod
    def _sse_event_has_generated_output(event: str) -> bool:
        """Return true when a complete SSE event carries model-generated output."""
        payload_lines = [
            line[5:].lstrip() for line in event.splitlines() if line.startswith("data:")
        ]
        if not payload_lines:
            return False
        try:
            data = json.loads("\n".join(payload_lines))
        except (TypeError, json.JSONDecodeError):
            return False
        if not isinstance(data, dict):
            return False
        if data.get("type") == "diffusion_frame":
            return True
        choices = data.get("choices")
        if not isinstance(choices, list):
            return False
        for choice in choices:
            if not isinstance(choice, dict):
                continue
            delta = choice.get("delta")
            if isinstance(delta, dict) and any(
                value not in (None, "", []) for key, value in delta.items() if key != "role"
            ):
                return True
            if choice.get("text") not in (None, ""):
                return True
        return False

    @staticmethod
    def _iter_text_cancellable(
        response: "httpx.Response",
        cancel_event: Optional[threading.Event] = None,
        stall_timeout_s: float = _DEFAULT_STREAM_STALL_TIMEOUT_S,
        first_token_deadline: Optional[float] = None,
        post_first_chunk_read_timeout_s: Optional[float] = _DEFAULT_STREAM_STALL_TIMEOUT_S,
    ) -> Generator[str, None, None]:
        """Iterate a stream while polling cancel and stall timeouts."""
        text_iter = response.iter_text()
        if first_token_deadline is None:
            first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
        last_chunk_at: Optional[float] = None
        prefill_sse_buffer = ""
        while True:
            if cancel_event is not None and cancel_event.is_set():
                response.close()
                return
            try:
                if last_chunk_at is None:
                    remaining_s = first_token_deadline - time.monotonic()
                    if remaining_s <= 0:
                        raise httpx.ReadTimeout("The model did not produce a first token in time.")
                    LlamaCppBackend._set_stream_read_timeout(response, remaining_s)
                chunk = next(text_iter)
                starts_output = last_chunk_at is not None
                if chunk and last_chunk_at is None:
                    prefill_sse_buffer += chunk
                    while match := re.search(r"(?:\r\n|\r|\n){2}", prefill_sse_buffer):
                        event = prefill_sse_buffer[: match.start()]
                        prefill_sse_buffer = prefill_sse_buffer[match.end() :]
                        if LlamaCppBackend._sse_event_has_generated_output(event):
                            starts_output = True
                            prefill_sse_buffer = ""
                            break
                if chunk and starts_output:
                    if last_chunk_at is None and post_first_chunk_read_timeout_s is not None:
                        LlamaCppBackend._set_stream_read_timeout(
                            response,
                            post_first_chunk_read_timeout_s,
                        )
                    last_chunk_at = time.monotonic()
                yield chunk
            except StopIteration:
                return
            except httpx.ReadTimeout:
                now = time.monotonic()
                if last_chunk_at is None:
                    if now >= first_token_deadline:
                        raise
                elif now - last_chunk_at >= stall_timeout_s:
                    raise httpx.ReadTimeout("The model stopped producing tokens mid-response.")
                continue

    @staticmethod
    def _set_stream_read_timeout(response: "httpx.Response", read_timeout_s: float) -> None:
        """Lower only post-header stream reads; keep prefill timeout long."""
        try:
            timeout_ext = response.request.extensions.get("timeout")
            if isinstance(timeout_ext, dict):
                timeout_ext["read"] = read_timeout_s
        except Exception:
            logger.debug("Could not lower response read timeout", exc_info = True)

    @staticmethod
    def _shutdown_active_httpx_sockets(client: "httpx.Client") -> None:
        """Best-effort interrupt for a sync httpx read blocked in recv(), whether
        parked before headers (prefill) or mid-stream."""
        try:
            pool = getattr(getattr(client, "_transport", None), "_pool", None)
            connections = list(getattr(pool, "_connections", []) or [])
            for connection in connections:
                inner = getattr(connection, "_connection", None)
                stream = getattr(inner, "_network_stream", None)
                sock = getattr(stream, "_sock", None)
                if sock is None:
                    continue
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
                try:
                    sock.close()
                except OSError:
                    pass
        except Exception:
            logger.debug("Could not shutdown active httpx socket", exc_info = True)
        try:
            client.close()
        except Exception:
            logger.debug("Could not close httpx client", exc_info = True)

    @staticmethod
    def _install_cancel_aware_read(
        client: "httpx.Client",
        cancel_event: threading.Event,
        response: Optional["httpx.Response"] = None,
        poll_s: float = 0.2,
    ) -> None:
        """Wrap the httpcore stream so the reader interrupts its own blocked recv() on cancel.

        A cross-thread socket shutdown wakes a parked recv() on POSIX but not on
        Windows (Winsock), so read in short slices and poll cancel_event between them
        (plain or TLS); slice timeouts are swallowed so a slow-but-alive stream survives.
        httpcore snapshots request.extensions["timeout"]["read"] once at body start, so
        given ``response`` we re-read the live value per call to honor the post-first-token
        stall timeout instead of the long prefill timeout."""
        import httpcore

        def _live_read_timeout() -> Optional[float]:
            if response is None:
                return None
            try:
                ext = response.request.extensions.get("timeout")
                if isinstance(ext, dict):
                    value = ext.get("read")
                    if isinstance(value, (int, float)):
                        return float(value)
            except Exception:
                pass
            return None

        try:
            pool = getattr(getattr(client, "_transport", None), "_pool", None)
            for connection in list(getattr(pool, "_connections", []) or []):
                inner = getattr(connection, "_connection", None)
                stream = getattr(inner, "_network_stream", None)
                if stream is None or getattr(stream, "_unsloth_cancel_wrapped", False):
                    continue
                orig_read = stream.read

                def read(
                    max_bytes,
                    timeout = None,
                    _orig = orig_read,
                ):
                    live = _live_read_timeout()
                    effective = live if live is not None else timeout
                    deadline = None if effective is None else time.monotonic() + effective
                    while True:
                        if cancel_event.is_set():
                            raise httpcore.ReadError("stream cancelled by user")
                        if deadline is None:
                            step = poll_s
                        else:
                            remaining = deadline - time.monotonic()
                            if remaining <= 0:
                                raise httpcore.ReadTimeout("read operation timed out")
                            step = min(poll_s, remaining)
                        try:
                            return _orig(max_bytes, timeout = step)
                        except httpcore.ReadTimeout:
                            if deadline is not None and time.monotonic() >= deadline:
                                raise
                            continue  # slow but alive: keep reading

                stream.read = read
                stream._unsloth_cancel_wrapped = True
        except Exception:
            logger.debug("Could not install cancel-aware read", exc_info = True)

    @staticmethod
    @contextlib.contextmanager
    def _stream_with_retry(
        client: "httpx.Client",
        url: str,
        payload: dict,
        cancel_event: Optional[threading.Event] = None,
        headers: Optional[dict] = None,
        first_token_deadline: Optional[float] = None,
    ):
        """Open one streaming POST and let cancel interrupt prefill or reads."""
        if cancel_event is not None and cancel_event.is_set():
            raise _LlamaStreamCancelled

        _cancel_closed = threading.Event()
        _response_ref: list = [None]

        def _cancel_watcher():
            while not _cancel_closed.is_set():
                if cancel_event.wait(timeout = 0.3):
                    while not _cancel_closed.is_set():
                        r = _response_ref[0]
                        try:
                            # response.close() can't wake a read already blocked in
                            # recv(); only a socket shutdown does, so shut down first.
                            LlamaCppBackend._shutdown_active_httpx_sockets(client)
                            if r is not None:
                                r.close()
                            return
                        except Exception as e:
                            logger.debug(f"Error closing request in cancel watcher: {e}")
                        _cancel_closed.wait(timeout = 0.1)
                    return

        watcher = None
        if cancel_event is not None:
            watcher = threading.Thread(target = _cancel_watcher, daemon = True, name = "prefill-cancel")
            watcher.start()

        try:
            if first_token_deadline is None:
                first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
            prefill_read_timeout = max(0.1, first_token_deadline - time.monotonic())
            prefill_timeout = httpx.Timeout(
                connect = 30,
                read = prefill_read_timeout,
                write = 10,
                pool = 10,
            )
            with client.stream(
                "POST",
                url,
                json = payload,
                timeout = prefill_timeout,
                headers = headers,
            ) as response:
                _response_ref[0] = response
                if cancel_event is not None:
                    # Portable mid-stream cancel: the reader polls cancel itself, so
                    # Stop interrupts a stalled read where the watcher's Windows socket
                    # shutdown does not. Pass response to honor the live stall timeout.
                    LlamaCppBackend._install_cancel_aware_read(client, cancel_event, response)
                if cancel_event is not None and cancel_event.is_set():
                    raise _LlamaStreamCancelled
                yield response
                return
        except (httpx.RequestError, RuntimeError):
            # Response was closed by the cancel watcher
            if cancel_event is not None and cancel_event.is_set():
                raise _LlamaStreamCancelled
            raise
        finally:
            _cancel_closed.set()

    def _server_socket_is_open(self, timeout_s: float = 0.15) -> bool:
        """True if anything still accepts on the server port.

        The listening socket dies with the process, so this tells a live server
        from a dead one without waiting for the child to become reapable.
        """
        port = self._port
        if not port:
            return False
        try:
            with socket.create_connection(("127.0.0.1", port), timeout = timeout_s):
                return True
        except OSError:
            return False

    def _respawn_if_dead(self) -> bool:
        """Relaunch the llama-server if its process has exited.

        A loaded chat model can be SIGKILL'd mid-session (usually GPU/RAM pressure
        from a training run on the same box), leaving a defunct process while
        ``is_loaded`` still reads True. Replay the last ``load_model`` call to
        recover, returning True once healthy. Serialised on ``_respawn_lock`` so
        many generations hitting the dead server trigger at most one reload.
        """
        # Read outside the lock so a queued caller can tell the replacement from the child
        # its own error came from; otherwise each burns the grace wait below, and that
        # sleep is held under the lock, so the waits serialise.
        served_by = self._process
        with self._respawn_lock:
            proc = self._process
            if proc is None:
                return False
            if self._cancel_event.is_set():
                # unload_model sets this before it kills, so the child can still be
                # accepting. Reporting it healthy would aim the retry at a server
                # that is deliberately going away.
                return False
            if proc is not served_by:
                # Replaced while we queued: this child never served our request.
                return self._healthy
            if proc.poll() is None:
                # Still serving, so the error was transient. Charging it the grace below
                # would cost a second per caller, serialised under this lock.
                if self._server_socket_is_open():
                    return self._healthy
                # A closing server can beat its own exit status: calling it alive returns
                # the stale _healthy and spends the retry on the corpse.
                deadline = time.monotonic() + _RESPAWN_REAP_GRACE_S
                while proc.poll() is None and time.monotonic() < deadline:
                    time.sleep(0.05)
            if proc.poll() is None:
                # Alive: either a concurrent caller already respawned it (healthy), or
                # this connection error wasn't a dead server.
                return self._healthy
            with self._mtp_runtime_fallback_lock:
                if self._mtp_runtime_fallback_in_progress:
                    # An MTP-free reload owns this corpse; replaying the old kwargs
                    # restarts the crashing config and aborts that reload.
                    logger.info("Respawn skipped: an MTP-free reload is already recovering.")
                    return False
            # The RLock lets the load_model below re-enter it.
            with self._serial_load_lock:
                if self._process is not proc:
                    logger.info("Respawn skipped: a newer load is already active.")
                    return self._healthy
                # Snapshot under _lock, the one unload_model holds, so a teardown is
                # either wholly before us (flag set) or wholly after (epoch bumped).
                # _serial_load_lock alone would not exclude it: unload never takes it.
                with self._lock:
                    if self._cancel_event.is_set():
                        logger.info("Respawn skipped: the model was unloaded.")
                        return False
                    intent = self._last_load_intent
                    if intent is None:
                        return False
                    epoch = self._unload_epoch
                    self._healthy = False
                logger.warning(
                    f"llama-server for '{self._model_identifier}' exited "
                    f"(code {proc.returncode}); respawning to recover the session"
                )
                try:
                    started = bool(self.load_model(intent))
                except Exception as exc:
                    logger.error(f"Failed to respawn llama-server: {exc}")
                    return False
                if started and self._unload_epoch != epoch:
                    # An unload landed mid-reload. load_model cleared _cancel_event on
                    # the way in, so the epoch is the only surviving evidence; undo the
                    # replacement rather than leave a model the user stopped running.
                    logger.info("Respawn undone: the model was unloaded during the reload.")
                    self.unload_model()
                    return False
                return started

    @contextlib.contextmanager
    def _open_chat_stream_with_respawn_retry(
        self,
        payload: dict,
        cancel_event,
        on_respawn: Optional[Callable[[], None]] = None,
    ):
        """Open a chat stream, respawning a dead llama-server once before streaming.

        Retry only when opening the response fails: once it is open a consumer may
        already have emitted content or tool events, so a replay could duplicate
        output and side effects. ``base_url`` is resolved per attempt because a
        respawn may pick a new port. The budget is one retry per model request, not
        per chat turn, so a long tool loop never discards a completed tool.

        A child dying after the accept but before the headers surfaces as
        ReadError/WriteError/RemoteProtocolError rather than ConnectError, and which
        one differs per OS. llama-server flushes its 200 at slot start, so that window
        is an upload still in flight or a request behind busy slots; a death during
        decode arrives with the response open and is not replayed. Timeouts are
        excluded: the server is slow, not dead, and a replay would spend the
        first-token budget twice.
        """
        for attempt in range(2):
            response_opened = False
            try:
                url = f"{self.base_url}/v1/chat/completions"
                with self._open_stream(url, payload, cancel_event) as opened:
                    response_opened = True
                    yield opened
                    return
            except (httpx.NetworkError, httpx.RemoteProtocolError) as exc:
                if response_opened:
                    raise
                if self._maybe_recover_from_mtp_crash(exc):
                    raise RuntimeError("Lost connection to llama-server") from exc
                if attempt == 0 and self._respawn_if_dead():
                    logger.warning(
                        "llama-server was unreachable; respawned it and retrying the generation"
                    )
                    if on_respawn is not None:
                        on_respawn()
                    continue
                raise

    def generate_chat_completion(
        self,
        messages: list[dict],
        image_b64: Optional[str] = None,
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 20,
        min_p: float = 0.01,
        max_tokens: Optional[int] = None,
        repetition_penalty: float = 1.0,
        presence_penalty: float = 0.0,
        frequency_penalty: float = 0.0,
        logit_bias: Optional[dict] = None,
        stop: Optional[list[str]] = None,
        cancel_event: Optional[threading.Event] = None,
        enable_thinking: Optional[bool] = None,
        reasoning_effort: Optional[str] = None,
        preserve_thinking: Optional[bool] = None,
        continue_final_message: bool = False,
        seed: Optional[int] = None,
        promote_reasoning_only: bool = True,
        perf_callback: Optional[Callable[[dict], None]] = None,
        reasoning_provenance: Optional[dict] = None,
        context_overflow: Optional[str] = None,
        context_policy: Optional[str] = None,
        compaction_headroom_ratio: Optional[float] = None,
        thread_id: Optional[str] = None,
        tools_withheld: bool = False,
        _allow_respawn_retry: bool = True,
    ) -> Generator[Union[str, dict], None, None]:
        """
        Send a chat completion to llama-server and stream tokens back.

        Uses /v1/chat/completions -- llama-server applies the chat template
        and handles vision (multimodal image_url parts) natively.

        Yields cumulative text (matching InferenceBackend's convention).
        """
        if not self.is_loaded:
            raise RuntimeError("llama-server is not loaded")

        from core.inference.chat_template_helpers import (
            neutralize_control_markup_in_messages,
            trailing_assistant_text,
        )

        openai_messages = self._build_openai_messages(messages, image_b64)
        continue_final_message = continue_final_message and bool(
            trailing_assistant_text(openai_messages)
        )

        payload = {
            # llama-server applies the chat template itself (#7066).
            "messages": neutralize_control_markup_in_messages(
                openai_messages, None, self.markup_profile
            ),
            "stream": True,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
            "presence_penalty": presence_penalty,
            "frequency_penalty": frequency_penalty,
        }
        retry_messages = messages
        retry_image_b64 = image_b64
        retry_max_tokens = max_tokens
        retry_context_overflow = context_overflow
        retry_preflight_context_length = None
        if perf_callback is not None:
            payload["return_progress"] = True
            payload["timings_per_token"] = True
        if logit_bias:
            payload["logit_bias"] = logit_bias
        # Per-request enable_thinking / reasoning_effort / preserve_thinking
        _reasoning_kw = self._request_reasoning_kwargs(
            enable_thinking, reasoning_effort, preserve_thinking
        )
        if _reasoning_kw is not None:
            payload["chat_template_kwargs"] = _reasoning_kw
        if continue_final_message:
            # llama-server applies the template; it rejects both flags set true.
            payload["continue_final_message"] = True
            payload["add_generation_prompt"] = False
        # Default cap to the model context when known.
        payload["max_tokens"] = (
            max_tokens
            if max_tokens is not None
            else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
        )
        if (
            context_overflow == "truncate_oldest"
            and self._effective_context_length
            and not messages_have_media(openai_messages)
        ):
            try:
                _before_fit = openai_messages
                # One value for both the boundary read and the fit: a boundary the fit
                # would not consume as an epoch must not be discarded as if it would.
                _can_reset = _can_reset_epoch(
                    thread_id,
                    _backend_supports_tools(self),
                    tools_withheld = tools_withheld,
                )
                _sticky, _sticky_is_checkpoint = _sticky_compaction_state(
                    thread_id,
                    _before_fit,
                    context_policy = context_policy,
                    can_reset = _can_reset,
                    compaction_headroom_ratio = compaction_headroom_ratio,
                )
                openai_messages, truncation = _fit_with_instruction_pins(
                    openai_messages,
                    context_length = self._effective_context_length,
                    max_tokens = payload["max_tokens"],
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(fitted, None, self.markup_profile),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        continue_final_message = continue_final_message,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    reserve_tokens = _conversation_recall_reserve(thread_id),
                    sticky_dropped = _sticky,
                    sticky_is_checkpoint = _sticky_is_checkpoint,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _can_reset,
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                if truncation:
                    # Inline, not a forged tool exchange: this path sends no tools array,
                    # and strict templates reject a tool role with no catalogue.
                    _recalled = _archive_and_recall(
                        openai_messages,
                        _before_fit,
                        branch_messages = _before_fit,
                        thread_id = thread_id,
                        style = "inline",
                        # Checkpoint mode recalls once, on the turn that reset; rolling has no
                        # such key and keeps recalling on every turn that evicted anything.
                        force_recall = bool(truncation.get("checkpoint_started", True)),
                        # A rescued refusal may evict messages; archive them without recall.
                        recall_done = not truncation["fits"],
                        # This single-shot answer never returns to the prompt.
                        recall_budget_tokens = _retrieval_budget(
                            self._effective_context_length,
                            payload["max_tokens"],
                            truncation.get("prompt_tokens_after") or 0,
                        ),
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                fitted, None, self.markup_profile
                            ),
                            None,
                            None,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = continue_final_message,
                        ),
                    )
                    openai_messages = _recalled["conversation"]
                    truncation = {**truncation, **_recalled["counts"]}
                if truncation and _records_boundary(truncation):
                    truncation = {
                        **truncation,
                        **_boundary_metadata(
                            openai_messages, _before_fit, compaction_headroom_ratio
                        ),
                    }
                payload["messages"] = neutralize_control_markup_in_messages(
                    openai_messages, None, self.markup_profile
                )
                # Reuse the fitted request on respawn; re-running the preflight would
                # emit the same truncation event twice.
                retry_messages = openai_messages
                retry_image_b64 = None
                retry_max_tokens = payload["max_tokens"]
                retry_context_overflow = None
                retry_preflight_context_length = self._effective_context_length
                # `fits` False too: it carries the diagnosis the client needs to explain
                # WHY. Otherwise the user only sees llama-server's error, which reports
                # the whole conversation's size and advises shortening it even when the
                # single message just sent is the part that does not fit.
                if truncation:
                    yield {"type": "context_truncated", **truncation}
            except Exception as exc:
                logger.warning("Could not preflight the rolling context window: %s", exc)
        if stop:
            payload["stop"] = stop
        if seed is not None:
            payload["seed"] = seed
        payload["stream_options"] = {"include_usage": True}

        url = f"{self.base_url}/v1/chat/completions"
        cumulative = ""
        in_thinking = False
        _stream_done = False
        _metadata_usage = None
        _metadata_timings = None
        _metadata_finish_reason = None

        try:
            with self._open_stream(url, payload, cancel_event) as (
                response,
                first_token_deadline,
            ):
                buffer = ""
                has_content_tokens = False
                reasoning_text = ""
                _prov_entry = None
                for raw_chunk in self._iter_text_cancellable(
                    response,
                    cancel_event,
                    first_token_deadline = first_token_deadline,
                ):
                    buffer += raw_chunk
                    while "\n" in buffer:
                        line, buffer = buffer.split("\n", 1)
                        line = line.strip()

                        if not line:
                            continue
                        if line == "data: [DONE]":
                            if in_thinking:
                                if has_content_tokens:
                                    # Real thinking + content: close the tag
                                    cumulative += "</think>"
                                    _prov_entry = None
                                    yield cumulative
                                else:
                                    # Only reasoning_content, no content:
                                    # model put its whole reply in reasoning
                                    # (e.g. Qwen3 always-think). Show it as
                                    # the main response, not a thinking block.
                                    cumulative = _finalize_reasoning_only_cumulative(
                                        cumulative,
                                        reasoning_text,
                                        _metadata_finish_reason,
                                        promote_reasoning_only,
                                    )
                                    _prov_entry = None
                                    yield cumulative
                            _stream_done = True
                            break  # exit inner while
                        if not line.startswith("data: "):
                            continue

                        try:
                            data = json.loads(line[6:])
                            _report_live_llama_timings(perf_callback, data)
                            # Diffusion frame (per-step canvas) from the shim: forward untouched so
                            # the frontend renders it in place. No assistant text, so it never enters
                            # the cumulative content.
                            if data.get("type") == "diffusion_frame":
                                yield data
                                continue
                            # Capture server timings/usage from final chunks.
                            _chunk_timings = data.get("timings")
                            if _chunk_timings:
                                _metadata_timings = _chunk_timings
                            _chunk_usage = data.get("usage")
                            if _chunk_usage:
                                _metadata_usage = _chunk_usage
                            # An error chunk carries no choices, so without this the loop
                            # ignored it and the reply ended with no finish_reason and no
                            # incomplete stamp: to the user, a mid-sentence stop for no
                            # stated reason. Raise so the failure is surfaced.
                            _stream_error = stream_error_from_chunk(data)
                            if _stream_error is not None:
                                raise _stream_error
                            choices = data.get("choices", [])
                            if choices:
                                delta = choices[0].get("delta", {})
                                _fr = choices[0].get("finish_reason")
                                if _fr:
                                    _metadata_finish_reason = _fr

                                # Reasoning/thinking tokens: llama-server
                                # sends these as "reasoning_content"; wrap
                                # in <think> tags for the frontend parser.
                                reasoning = delta.get("reasoning_content", "")
                                if reasoning:
                                    reasoning_text += reasoning
                                    if not in_thinking:
                                        # Provenance for think-aware consumers: a
                                        # leading <think> we open here is genuine
                                        # reasoning, unlike literal tags in content.
                                        if reasoning_provenance is not None and not cumulative:
                                            reasoning_provenance["wrapped"] = (
                                                reasoning_provenance.get("wrapped", 0) + 1
                                            )
                                            _prov_entry = {"len": 0}
                                            reasoning_provenance.setdefault("wraps", []).append(
                                                _prov_entry
                                            )
                                        cumulative += "<think>"
                                        in_thinking = True
                                    cumulative += reasoning
                                    if _prov_entry is not None:
                                        _prov_entry["len"] += len(reasoning)
                                    yield cumulative

                                token = delta.get("content", "")
                                if token:
                                    has_content_tokens = True
                                    if in_thinking:
                                        cumulative += "</think>"
                                        in_thinking = False
                                        _prov_entry = None
                                    cumulative += token
                                    yield cumulative
                        except json.JSONDecodeError:
                            logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                    if _stream_done:
                        break  # exit outer for
                if _metadata_usage or _metadata_timings or _metadata_finish_reason:
                    _metadata_usage = _backfill_usage_from_timings(
                        _metadata_usage, _metadata_timings
                    )
                    yield {
                        "type": "metadata",
                        # Never None: a finish-only metadata event (no usage,
                        # no timings) would otherwise crash consumers that do
                        # usage.get(...) on the non-streaming paths.
                        "usage": _metadata_usage or {},
                        "timings": _metadata_timings,
                        "finish_reason": _metadata_finish_reason,
                    }

        except _LlamaStreamCancelled:
            return
        except httpx.ConnectError as e:
            # Server already down. If this was an MTP+tensor crash, recover by
            # reloading without MTP (scheduled in the background) and fail this
            # request. Otherwise the server was likely SIGKILL'd by GPU pressure
            # from a concurrent training run: respawn the same config and retry the
            # generation once (bounded by the private flag, no duplicate output).
            if self._maybe_recover_from_mtp_crash(e):
                raise RuntimeError("Lost connection to llama-server")
            if _allow_respawn_retry and not cumulative and self._respawn_if_dead():
                logger.warning(
                    "llama-server was unreachable; respawned it and retrying the generation"
                )
                if (
                    retry_preflight_context_length is not None
                    and retry_preflight_context_length != self._effective_context_length
                ):
                    # Refit the compacted prompt against the replacement server's window;
                    # any event now reports only additional evictions.
                    retry_context_overflow = context_overflow
                    if max_tokens is None:
                        retry_max_tokens = None
                yield from self.generate_chat_completion(
                    retry_messages,
                    image_b64 = retry_image_b64,
                    temperature = temperature,
                    top_p = top_p,
                    top_k = top_k,
                    min_p = min_p,
                    max_tokens = retry_max_tokens,
                    repetition_penalty = repetition_penalty,
                    presence_penalty = presence_penalty,
                    frequency_penalty = frequency_penalty,
                    logit_bias = logit_bias,
                    stop = stop,
                    cancel_event = cancel_event,
                    enable_thinking = enable_thinking,
                    reasoning_effort = reasoning_effort,
                    preserve_thinking = preserve_thinking,
                    continue_final_message = continue_final_message,
                    seed = seed,
                    promote_reasoning_only = promote_reasoning_only,
                    perf_callback = perf_callback,
                    reasoning_provenance = reasoning_provenance,
                    context_overflow = retry_context_overflow,
                    context_policy = context_policy,
                    compaction_headroom_ratio = compaction_headroom_ratio,
                    # The retry refits for the replacement window and can evict more than
                    # the first attempt did. Without the thread those extra turns are
                    # archived nowhere and no reserve or boundary applies, on the one path
                    # that deliberately compacts again.
                    thread_id = thread_id,
                    # The retry refits, so it must be told the same about this request's
                    # tools as the first attempt was.
                    tools_withheld = tools_withheld,
                    _allow_respawn_retry = False,
                )
                return
            raise RuntimeError("Lost connection to llama-server")
        except Exception as e:
            if cancel_event is not None and cancel_event.is_set():
                return
            # Died mid-generation: recover MTP, re-raise unchanged for this request.
            self._maybe_recover_from_mtp_crash(e)
            raise

    # ── Tool-calling agentic loop ──────────────────────────────

    def generate_chat_completion_with_tools(
        self,
        messages: list[dict],
        tools: list[dict],
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 20,
        min_p: float = 0.01,
        max_tokens: Optional[int] = None,
        repetition_penalty: float = 1.0,
        presence_penalty: float = 0.0,
        frequency_penalty: float = 0.0,
        logit_bias: Optional[dict] = None,
        stop: Optional[list[str]] = None,
        cancel_event: Optional[threading.Event] = None,
        enable_thinking: Optional[bool] = None,
        reasoning_effort: Optional[str] = None,
        preserve_thinking: Optional[bool] = None,
        continue_final_message: bool = False,
        max_tool_iterations: int = 25,
        auto_heal_tool_calls: bool = True,
        nudge_tool_calls: Optional[bool] = None,
        tool_call_timeout: int = 300,
        session_id: Optional[str] = None,
        thread_id: Optional[str] = None,
        rag_scope: Optional[dict] = None,
        seed: Optional[int] = None,
        disable_parallel_tool_use: bool = False,
        confirm_tool_calls: bool = False,
        bypass_permissions: bool = False,
        permission_mode: Optional[str] = None,
        promote_reasoning_only: bool = True,
        perf_callback: Optional[Callable[[dict], None]] = None,
        reasoning_provenance: Optional[dict] = None,
        context_overflow: Optional[str] = None,
        context_policy: Optional[str] = None,
        compaction_headroom_ratio: Optional[float] = None,
        tool_choice: Any = None,
    ) -> Generator[dict, None, None]:
        """
        Agentic loop: let the model call tools, execute them, and continue.

        permission_mode: "ask" confirms every call (with confirm_tool_calls),
        "auto" only pauses calls detected as potentially unsafe, "off" never
        pauses (sandbox stays on), "full" is the same as bypass_permissions.
        Unset/unknown behaves as "ask".

        Yields dicts:
          {"type": "status", "text": "Searching: ..."/"Reading: ..."}   -- tool status updates
          {"type": "content", "text": "token"}            -- streamed content tokens (cumulative)
          {"type": "reasoning", "text": "token"}          -- streamed reasoning tokens (cumulative)
        """
        from core.inference.tool_stream_exec import (
            accepts_kwarg,
            accepts_output_callback,
            search_images_kwargs,
            stream_tool_execution,
        )
        from core.inference.tools import (
            build_rag_autoinject,
            execute_tool,
            has_text_only_provisional_card,
            is_always_safe_tool,
            is_high_risk_tool_call,
        )

        # "full" and bypass_permissions are the same switch, whichever arrives
        # first wins. "off" keeps the sandbox but never prompts. Unset defaults to
        # "auto"; unknown falls back to the stricter "ask". An explicit
        # confirm_tool_calls=True with no mode is already resolved to "ask" at the
        # request layer, so it never arrives here as an ambiguous unset.
        if permission_mode == "full":
            bypass_permissions = True
        elif bypass_permissions:
            permission_mode = "full"
        elif permission_mode is None:
            permission_mode = "auto"
        elif permission_mode not in ("ask", "auto", "off"):
            permission_mode = "ask"

        if not self.is_loaded:
            raise RuntimeError("llama-server is not loaded")

        conversation = list(messages)
        _rolling_anchor_ids: set[int] = set()
        # The loop refits on every iteration; recall must fire once per request, or each
        # pass stacks another block of recalled turns onto the prompt.
        _conversation_recall_done = False
        # The sticky boundary describes the ORIGINAL transcript, so apply it at most once
        # per request. Each later refit runs on what the previous fit returned, so
        # re-applying the count evicts another boundary-sized block of live history, and
        # the summed events persist the inflated total into the next request.
        _sticky_boundary_applied = False
        # Exact templated prompt tokens minus the estimator's view of the same messages,
        # measured once by the preflight. The estimator cannot see the tool catalogue or
        # the template framing, thousands of tokens with a large (MCP) catalogue: enough
        # for a conversation search to be told there is room it does not have. Carrying
        # the difference makes the estimate exact where it was measured.
        _prompt_token_offset: Optional[int] = None
        # The branch this request is on, kept aside before anything is evicted from or
        # injected into `conversation`. The archive is keyed by thread and the stored rows
        # are the whole DAG (Retry keeps the replaced response as a sibling), so recall
        # has to be told which branch is live, and the client's messages are the answer.
        _request_branch: list[dict] = list(messages)
        # ...and everything this request adds to it. A long agent run can evict its own
        # earlier tool exchange, which is archived; filtered against the messages the
        # client sent, that document looks like an abandoned branch and is refused, so the
        # model cannot get back a tool result it still needs to answer. Accumulated rather
        # than read off `conversation`, which has already lost what earlier fits evicted.
        _live_branch: list[dict] = list(messages)
        _live_branch_ids: set[int] = {id(message) for message in messages}

        def _extend_live_branch(current: list[dict]) -> list[dict]:
            for message in current:
                if id(message) not in _live_branch_ids:
                    _live_branch_ids.add(id(message))
                    _live_branch.append(message)
            return _live_branch

        for message in reversed(conversation):
            if message.get("role") == "user":
                _rolling_anchor_ids.add(id(message))
                break

        def _attach_internal_feedback_to_tool_result(feedback: str) -> bool:
            """Keep controller instructions inside the current tool exchange."""
            if not conversation or conversation[-1].get("role") != "tool":
                return False
            content = conversation[-1].get("content")
            if not isinstance(content, str):
                return False
            # Replaced, not mutated: ``conversation`` copies the list, not the dicts, and
            # /v1/messages passes a caller's own history through, which may end on a tool
            # result. An in-place edit would leave the nudge there and re-send it next turn.
            conversation[-1] = {**conversation[-1], "content": f"{content}\n\n{feedback}"}
            return True

        # Forced first-pass RAG so a doc question doesn't lose to web_search. Emits
        # the same tool card + citations a real call would. Skip it only when a
        # retrieval call would actually prompt (ask mode); auto never gates the
        # safe search_knowledge_base tool, so retrieval must still run there.
        # off never prompts either, so it also keeps first-pass retrieval.
        from core.inference.chat_template_helpers import forced_tool_name, trailing_assistant_text

        initial_forced_name = forced_tool_name(tool_choice)
        if initial_forced_name and initial_forced_name not in _gguf_active_tool_names(tools):
            raise ValueError(
                f"Forced tool '{initial_forced_name}' is not enabled for this request."
            )

        # A resumed turn must keep the partial trailing: autoinject appends a tool call
        # plus its result, moving the boundary so the model opens a fresh answer.
        _skip_autoinject = (
            tool_choice == "none"
            or (
                confirm_tool_calls
                and not bypass_permissions
                and permission_mode not in ("auto", "off")
            )
        ) or bool(continue_final_message and trailing_assistant_text(conversation))
        _auto = None if _skip_autoinject else build_rag_autoinject(conversation, rag_scope)
        if _auto:
            for _ev in _auto["events"]:
                yield _ev
            conversation.extend(_auto["messages"])
        _auto_satisfies_forced_choice = bool(_auto) and (
            tool_choice == "required" or forced_tool_name(tool_choice) == "search_knowledge_base"
        )

        _accumulated_completion_tokens = 0
        _accumulated_predicted_ms = 0.0
        _accumulated_predicted_n = 0
        # GGUF buffers reasoning; emit server-side timing before answer text.
        _reasoning_started_at: Optional[float] = None
        _reasoning_summary_emitted = False

        # Gate telling a genuine NAME[ARGS] rehearsal from inactive-name prose; built from the
        # ORIGINAL tools list so a spent one-shot still reads as a tool name. None = no gate.
        _enabled_names_gate = set(_gguf_active_tool_names(tools)) if tools else None
        # Detection must see the same names as the strip gate (ORIGINAL list, incl. a spent
        # one-shot), else its repeat is stripped but never drained and the turn ends blank.
        _detect_tools = list(tools or [])

        def _reasoning_summary_event(started_at: float) -> dict:
            return {
                "type": "reasoning_summary",
                "duration_ms": round((time.monotonic() - started_at) * 1000.0),
            }

        # Enabled-name gate for the markerless Gemma strip (disabled/example
        # names stay visible). Set per iteration; None = pre-loop name-agnostic.
        _enabled_tool_names = None

        def _strip_tool_markup(
            text: str,
            *,
            final: bool = False,
            force: bool = False,
        ) -> str:
            if not (auto_heal_tool_calls or force):
                return text
            # Delegate to the shared parser-side strip so the GGUF cleanup covers every family the
            # parser promotes (Llama <|python_tag|>, Mistral [TOOL_CALLS], bare rehearsal, function
            # XML, Gemma) and stays aligned with detection; tool_healing's strip omits the loop-only
            # forms (python_tag / Mistral name) and would leak them into display.
            return _shared_strip_tool_markup(
                text, final = final, enabled_tool_names = _enabled_names_gate
            )

        # Wraps the parser's ``strip_segment`` so the accumulated response is not rescanned
        # end to end on every content token (that was quadratic in the response length).
        # Think blocks stay verbatim inside it: a rehearsed call in one must not be deleted.
        _streaming_stripper = _StreamingMarkupStripper(_enabled_names_gate)

        # The final-answer loop has its own buffer and strips with ``final = False``, so it
        # needs its own instance rather than sharing the one above.
        _final_answer_stripper = _StreamingMarkupStripper(_enabled_names_gate, seg_final = False)

        def _strip_tool_markup_streaming(text: str, *, force: bool = False) -> str:
            if not (auto_heal_tool_calls or force):
                return text
            return _streaming_stripper.strip(text)

        def _build_metadata_event(usage, timings, finish_reason):
            """Final usage+timings metadata event for the given pass, merging its
            usage/timings with the running cross-iteration accumulators. None when
            there is nothing to report."""
            _fu = _backfill_usage_from_timings(usage, timings) or {}
            _fp = _fu.get("prompt_tokens", 0)
            _tc = _fu.get("completion_tokens", 0) + _accumulated_completion_tokens
            if not (usage or timings or _accumulated_completion_tokens or finish_reason):
                return None
            _mt = dict(timings) if timings else {}
            if _accumulated_predicted_ms or _accumulated_predicted_n:
                _mt["predicted_ms"] = _mt.get("predicted_ms", 0) + _accumulated_predicted_ms
                _mt["predicted_n"] = _mt.get("predicted_n", 0) + _accumulated_predicted_n
                if _mt["predicted_ms"] > 0:
                    _mt["predicted_per_second"] = _mt["predicted_n"] / (
                        _mt["predicted_ms"] / 1000.0
                    )
            _usage = {
                "prompt_tokens": _fp,
                "completion_tokens": _tc,
                "total_tokens": _fp + _tc,
            }
            # Preserve KV-cache hit details (cached_tokens) so the tool path
            # reports them like the standard non-tool path does, not always 0.
            if _fu.get("prompt_tokens_details"):
                _usage["prompt_tokens_details"] = _fu["prompt_tokens_details"]
            return {
                "type": "metadata",
                "usage": _usage,
                "timings": _mt,
                "finish_reason": finish_reason,
            }

        def _flush_reasoning_and_buffer():
            """Close a live-streamed <think> block (or emit the buffered reasoning
            as one block if it never streamed), then append the held
            content_buffer to the cumulative display text."""
            nonlocal cumulative_display, in_thinking, _prov_entry
            if in_thinking:
                cumulative_display += "</think>"
                in_thinking = False
                _prov_entry = None
            elif reasoning_accum:
                if (
                    reasoning_provenance is not None
                    and not cumulative_display
                    and not _suppress_visible_output
                ):
                    reasoning_provenance["wrapped"] = reasoning_provenance.get("wrapped", 0) + 1
                    reasoning_provenance.setdefault("wraps", []).append(
                        {"len": len(reasoning_accum)}
                    )
                cumulative_display += "<think>" + reasoning_accum + "</think>"
            cumulative_display += content_buffer

        def _close_streamed_think() -> bool:
            """Close a live-streamed <think> before a tool call drains, so
            consumers without a reasoning extractor (Anthropic) get a balanced
            block. Returns True when the caller should yield the result."""
            nonlocal cumulative_display, in_thinking, _last_emitted, _prov_entry
            if not in_thinking:
                return False
            cumulative_display += "</think>"
            in_thinking = False
            _prov_entry = None
            if len(cumulative_display) > len(_last_emitted) and not _suppress_visible_output:
                _last_emitted = cumulative_display
                return True
            return False

        def _looks_like_enabled_bare_json(text: str, enabled_tool_names: set) -> bool:
            """True when ``text`` opens with an ENABLED markerless bare-JSON call; an ordinary JSON answer returns False."""
            probe = strip_llama3_leading_sentinels(text.lstrip())
            if not (probe.startswith("{") and ('"name"' in probe or '"function"' in probe)):
                return False
            return strip_leading_bare_json_call(probe, enabled_tool_names) != probe

        # Sanitized at construction, not at each gate: the controller authorizes execution,
        # and llama-server's structured delta.tool_calls path reaches prepare_call without
        # _enabled_tool_names at all. A tool dropped for unsafe markup is absent from the
        # prompt, so it must leave the controller too or it stays executable by name (#7066).
        from core.inference.chat_template_helpers import (
            neutralize_tool_descriptions as _neutralize_tool_descriptions,
        )

        controller_tools = (
            []
            if tool_choice == "none"
            else _neutralize_tool_descriptions(tools, None, self.markup_profile)
        )
        tool_controller = ToolLoopController(
            tools = controller_tools,
            auto_heal_tool_calls = auto_heal_tool_calls,
        )

        def _tool_succeeded(tool_name: str) -> bool:
            key_prefix = f"{tool_name}:"
            return any(
                record.executed and not record.is_error and record.key.startswith(key_prefix)
                for record in tool_controller.history
            )

        _MAX_BUFFER_CHARS = 32
        # Hold a leading ``{`` well past the 32-char XML cap until it balances (mirrors safetensors).
        _MAX_BARE_JSON_BUFFER = 16384
        _append_budget_exhausted_nudge = True
        # RAG: cap knowledge-base searches per assistant turn. The controller is
        # tool-agnostic, so this gate stays in the loop.
        _kb_search_count = 0

        # ── Re-prompt on plan-without-action ─────────────────
        # Model describes intent without calling a tool: re-prompt once. A
        # direct answer ("4", "Hello!") won't match. Pattern shared with the
        # safetensors loop (tool_call_parser.INTENT_SIGNAL).
        _reprompt_count = 0
        # Budgeted apart from _reprompt_count so a pre-tool nudge can't spend it.
        _post_tool_reprompts = 0
        # Text that triggered the last nudge; if the retry restates it, stop.
        _last_reprompt_text = ""
        # Gates ``max_tool_iterations`` on real tool turns (not the enlarged range) so reserved
        # re-prompt slots don't extend the budget. Mirrors the safetensors guard.
        _tool_iters_done = 0
        _forced_tool_call_pending = False

        # Reserve extra iterations for re-prompts so they don't consume the
        # caller's tool-call budget; only when tool iterations are allowed.
        _extra = _MAX_REPROMPTS + 1 if max_tool_iterations > 0 else 0
        # Owned by this request and dropped with it: the sweep below re-reads every earlier
        # turn on each iteration, and the rewrite is a function of the text alone (#7066).
        from core.inference.chat_template_helpers import sweep_cache as _sweep_cache

        _markup_cache = _sweep_cache()
        # A forced function applies until the model produces it; execution or denial resolves it.
        _forced_choice_resolved = _auto_satisfies_forced_choice
        for iteration in range(max_tool_iterations + _extra):
            if cancel_event is not None and cancel_event.is_set():
                return
            # Whether this turn ran a tool; a no-op-only turn stays False and doesn't consume budget.
            _turn_executed_real_tool = False

            active_tools = tool_controller.active_tools()
            if not active_tools:
                _append_budget_exhausted_nudge = False
                break
            from core.inference.chat_template_helpers import (
                neutralize_tool_descriptions,
                reconciled_tool_choice,
            )

            # An MCP server's description and inputSchema are remote text the template renders
            # into the system turn (#7066). Computed above the gate: a tool dropped for unsafe
            # markup is absent from the prompt and must be absent from what we EXECUTE too,
            # else the model names it and the raw gate lets the call through.
            safe_tools = neutralize_tool_descriptions(
                active_tools, _markup_cache, self.markup_profile
            )
            requested_choice = "auto" if tool_choice is None else tool_choice
            if _forced_choice_resolved and requested_choice not in ("auto", "none"):
                requested_choice = "auto"
            requested_choice = reconciled_tool_choice(requested_choice, tools, safe_tools) or "auto"
            forced_name = forced_tool_name(requested_choice)
            if forced_name:
                matching_tools = [
                    tool
                    for tool in safe_tools
                    if (tool.get("function") or {}).get("name") == forced_name
                ]
                if matching_tools:
                    safe_tools = matching_tools
                    requested_choice = "required"
            # Gate the markerless bare-JSON form on enabled names so an ordinary JSON answer isn't misread as a call.
            _enabled_tool_names = {
                (tool.get("function") or {}).get("name")
                for tool in safe_tools
                if (tool.get("function") or {}).get("name")
            }
            # Shared signal tuple so GGUF BUFFERING wakes on every format the parser knows (like safetensors).
            _tool_xml_signals = _SHARED_TOOL_XML_SIGNALS

            # Build payload -- stream: True so we detect tool signals
            # in the first 1-2 chunks without a non-streaming penalty.
            from core.inference.chat_template_helpers import (
                append_assistant_turn,
                neutralize_control_markup,
                neutralize_control_markup_in_messages,
            )

            _reasoning_kw = self._request_reasoning_kwargs(
                enable_thinking, reasoning_effort, preserve_thinking
            )
            _preflight_context_length = None
            _preflight_succeeded = False
            if (
                context_overflow == "truncate_oldest"
                and self._effective_context_length
                and not messages_have_media(conversation)
            ):
                _preflight_context_length = self._effective_context_length
                try:
                    _before_fit = conversation
                    _iteration_can_reset = _can_reset_epoch(
                        thread_id,
                        _backend_supports_tools(self),
                        tools_withheld = _memory_tool_withheld(thread_id, tools),
                    )
                    _iteration_sticky, _iteration_sticky_is_checkpoint = (
                        (0, True)
                        if _sticky_boundary_applied
                        else _sticky_compaction_state(
                            thread_id,
                            _request_branch,
                            context_policy = context_policy,
                            can_reset = _iteration_can_reset,
                            compaction_headroom_ratio = compaction_headroom_ratio,
                        )
                    )
                    conversation, truncation = _fit_with_instruction_pins(
                        conversation,
                        context_length = self._effective_context_length,
                        max_tokens = max_tokens,
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                fitted, _markup_cache, self.markup_profile
                            ),
                            None,
                            safe_tools,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = bool(
                                continue_final_message and trailing_assistant_text(fitted)
                            ),
                            should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                        ),
                        anchor_ids = _rolling_anchor_ids,
                        keeps_boundary = _keeps_compaction_boundary(thread_id),
                        can_reset = _iteration_can_reset,
                        reserve_tokens = _conversation_recall_reserve(thread_id),
                        sticky_dropped = _iteration_sticky,
                        sticky_is_checkpoint = _iteration_sticky_is_checkpoint,
                        **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                    )
                    # Accounted for in this request now, whatever the fit decided.
                    _sticky_boundary_applied = True
                    if truncation and truncation.get("fits"):
                        # Before the recall injection, so both sides describe the same
                        # messages, priced by the fit with the catalogue and template.
                        _prompt_token_offset = int(
                            truncation.get("prompt_tokens_after") or 0
                        ) - estimate_messages_tokens(conversation)
                    if truncation:
                        _recalled = _archive_and_recall(
                            conversation,
                            _before_fit,
                            branch_messages = _extend_live_branch(_before_fit),
                            thread_id = thread_id,
                            # Tool style forges an assistant tool_call plus a tool result
                            # for search_conversation, safe only when the request
                            # advertises it. On the FIRST compaction the archive did not
                            # exist at tool-selection time, so it is absent, and a tool
                            # role with no catalogue entry breaks strict templates.
                            style = (
                                "tool" if "search_conversation" in _enabled_tool_names else "inline"
                            ),
                            # Checkpoint mode recalls once, on the turn that reset; rolling has
                            # no such key and recalls on every turn that evicted anything.
                            force_recall = bool(truncation.get("checkpoint_started", True)),
                            # A rescued refusal may evict messages; archive them without recall.
                            recall_done = _conversation_recall_done or not truncation["fits"],
                            # Leave room for the answer appended on the next iteration.
                            recall_budget_tokens = _retrieval_budget(
                                self._effective_context_length,
                                max_tokens,
                                truncation.get("prompt_tokens_after") or 0,
                                reply_returns = True,
                            ),
                            count_tokens = lambda fitted: self.count_chat_tokens(
                                neutralize_control_markup_in_messages(
                                    fitted, _markup_cache, self.markup_profile
                                ),
                                None,
                                safe_tools,
                                strict = True,
                                chat_template_kwargs = _reasoning_kw,
                            ),
                        )
                        conversation = _recalled["conversation"]
                        truncation = {**truncation, **_recalled["counts"]}
                        if _recalled["recalled"]:
                            _conversation_recall_done = True
                            # Anchor exactly what the injection added, so a later refit
                            # cannot evict what we just paid to bring back. NOT the last
                            # two messages: inline recall appends nothing and rewrites the
                            # latest user turn in place, so that slice also pinned a whole
                            # eviction unit the fit was entitled to drop.
                            for _message in _recalled["anchored"]:
                                _rolling_anchor_ids.add(id(_message))
                            for _ev in _recalled["events"]:
                                yield _ev
                    if truncation and _records_boundary(truncation):
                        truncation = {
                            **truncation,
                            **_boundary_metadata(
                                conversation, _request_branch, compaction_headroom_ratio
                            ),
                        }
                    # `fits` False too: it carries the does-not-fit diagnosis.
                    if truncation:
                        yield {"type": "context_truncated", **truncation}
                    _preflight_succeeded = True
                except Exception as exc:
                    logger.warning("Could not preflight the rolling context window: %s", exc)

            payload = {
                # Re-run every iteration: tool results land in ``conversation`` as the
                # loop goes, and a forged turn in one would render for real (#7066).
                "messages": neutralize_control_markup_in_messages(
                    conversation, _markup_cache, self.markup_profile
                ),
                "stream": True,
                "stream_options": {"include_usage": True},
                "temperature": temperature,
                "top_p": top_p,
                "top_k": top_k if top_k >= 0 else 0,
                "min_p": min_p,
                "repeat_penalty": repetition_penalty,
                "presence_penalty": presence_penalty,
                "frequency_penalty": frequency_penalty,
            }

            if perf_callback is not None:
                payload["return_progress"] = True
                payload["timings_per_token"] = True
            if logit_bias:
                payload["logit_bias"] = logit_bias
            # As in the passthrough builder: if every name carried markup the catalog is
            # now empty, and "tools": [] would still advertise tool use.
            if safe_tools:
                payload["tools"] = safe_tools
                payload["tool_choice"] = requested_choice
            if _reasoning_kw is not None:
                payload["chat_template_kwargs"] = _reasoning_kw
            # Re-checked per iteration: once a tool result is appended the partial is
            # no longer trailing, so later turns are normal.
            if continue_final_message and trailing_assistant_text(conversation):
                payload["continue_final_message"] = True
                payload["add_generation_prompt"] = False
            payload["max_tokens"] = (
                max_tokens
                if max_tokens is not None
                else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
            )
            if stop:
                payload["stop"] = stop
            if seed is not None:
                payload["seed"] = seed

            _respawn_truncations: list[dict] = []

            def _refit_iteration_after_respawn() -> None:
                nonlocal conversation
                _before_respawn_fit = conversation
                if (
                    _preflight_context_length is None
                    or not self._effective_context_length
                    or (
                        _preflight_succeeded
                        and _preflight_context_length == self._effective_context_length
                    )
                ):
                    return
                if max_tokens is None:
                    payload["max_tokens"] = self._effective_context_length
                try:
                    conversation, truncation = _fit_with_instruction_pins(
                        conversation,
                        context_length = self._effective_context_length,
                        max_tokens = max_tokens,
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                fitted, _markup_cache, self.markup_profile
                            ),
                            None,
                            safe_tools,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = bool(
                                continue_final_message and trailing_assistant_text(fitted)
                            ),
                            should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                        ),
                        anchor_ids = _rolling_anchor_ids,
                        keeps_boundary = _keeps_compaction_boundary(thread_id),
                        can_reset = _can_reset_epoch(
                            thread_id,
                            _backend_supports_tools(self),
                            tools_withheld = _memory_tool_withheld(thread_id, tools),
                        ),
                        **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                    )
                    # Recorded here, not left to the forwarding below. That list is
                    # drained from INSIDE the reopened stream, so a replacement server
                    # that came back with a smaller window and then refused this prompt
                    # raises at the door and the refusal reaches `_friendly_error` as
                    # nothing at all -- which then advises shortening a conversation
                    # eviction has already emptied. Idempotent, and safe on a fit:
                    # `record_fit` clears whatever the last one left.
                    from core.inference import context_refusal  # noqa: PLC0415

                    context_refusal.record_fit(truncation)
                    if truncation:
                        # Archive only. The replacement fit reserves no recall room, and a
                        # rescued refusal may still have evicted messages.
                        truncation.update(
                            _archive_and_recall(
                                conversation,
                                _before_respawn_fit,
                                thread_id = thread_id,
                                style = "inline",
                                recall_done = True,
                                branch_messages = _extend_live_branch(conversation),
                            )["counts"]
                        )
                    payload["messages"] = neutralize_control_markup_in_messages(
                        conversation, _markup_cache, self.markup_profile
                    )
                    if truncation:
                        if _records_boundary(truncation):
                            truncation.update(
                                _boundary_metadata(
                                    conversation, _request_branch, compaction_headroom_ratio
                                )
                            )
                        # Report every shortened retry, including a rescued refusal.
                        _respawn_truncations.append(truncation)
                except Exception as exc:
                    logger.warning("Could not refit rolling context after respawn: %s", exc)
                    raise

            try:
                # ── Speculative buffer state machine ──────────────────
                # BUFFERING: accumulate content, check for tool signals
                # STREAMING: no tool detected, yield tokens to caller
                # DRAINING:  tool signal found, silently consume rest
                _S_BUFFERING = 0
                _S_STREAMING = 1
                _S_DRAINING = 2

                detect_state = _S_BUFFERING
                content_buffer = ""  # Raw content held during BUFFERING
                content_accum = ""  # All content tokens (for tool parsing)
                reasoning_accum = ""
                _prov_entry = None
                # Time each reasoning pass so final answers can replace tool timing.
                _reasoning_started_at = None
                _reasoning_summary_emitted = False
                _deferred_reasoning_summary = None
                cumulative_display = ""  # Cumulative yielded text (with <think>)
                # A new buffer, not a continuation of the previous iteration's.
                _streaming_stripper.reset()
                in_thinking = False
                has_content_tokens = False
                tool_calls_acc = {}  # Structured delta.tool_calls fragments
                # accumulator key each index maps to now, (index, call_id) after a fork
                tool_calls_open_key: dict[Any, Any] = {}
                tool_calls_synthetic_ids: set[Any] = set()  # slots still on a placeholder id
                has_structured_tc = False
                _iter_usage = None
                _iter_timings = None
                _iter_finish_reason = None
                _stream_done = False
                _last_emitted = ""
                # Provisional tool_start cards already shown, keyed by tool_call_id.
                provisional_started_tool_calls: dict[str, str] = {}
                resolved_provisional_tool_call_ids: set[str] = set()
                _suppress_visible_output = _forced_tool_call_pending
                # Cards that already got their first tool_args event; later
                # fragments stream individually so a big payload isn't a dead spinner.
                arg_streamed_tool_call_ids: set[str] = set()
                # TEXT tool-call path: a committed call's raw text streams to a
                # provisional card under the parser's first-call id ("call_0"), so
                # the final tool_start reconciles in place.
                _text_args_call_start = -1
                _text_args_streamed_upto = -1
                _text_args_id = ""
                _text_args_name = ""
                _confirm_gated_iteration = bool(confirm_tool_calls) and not bypass_permissions

                with self._open_chat_stream_with_respawn_retry(
                    payload,
                    cancel_event,
                    on_respawn = _refit_iteration_after_respawn,
                ) as (
                    response,
                    first_token_deadline,
                ):
                    for truncation in _respawn_truncations:
                        yield {"type": "context_truncated", **truncation}
                    raw_buf = ""
                    for raw_chunk in self._iter_text_cancellable(
                        response,
                        cancel_event,
                        first_token_deadline = first_token_deadline,
                    ):
                        raw_buf += raw_chunk
                        while "\n" in raw_buf:
                            line, raw_buf = raw_buf.split("\n", 1)
                            line = line.strip()

                            if not line:
                                continue
                            if line == "data: [DONE]":
                                # Flush thinking state for STREAMING
                                if detect_state == _S_STREAMING and in_thinking:
                                    if has_content_tokens:
                                        cumulative_display += "</think>"
                                        _prov_entry = None
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": _strip_tool_markup(
                                                    cumulative_display,
                                                    final = True,
                                                ),
                                            }
                                    else:
                                        cumulative_display = _finalize_reasoning_only_cumulative(
                                            cumulative_display,
                                            reasoning_accum,
                                            _iter_finish_reason,
                                            promote_reasoning_only,
                                        )
                                        _prov_entry = None
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": cumulative_display,
                                            }
                                _stream_done = True
                                break  # exit inner while
                            if not line.startswith("data: "):
                                continue

                            try:
                                chunk_data = json.loads(line[6:])

                                _report_live_llama_timings(perf_callback, chunk_data)
                                _ct = chunk_data.get("timings")
                                if _ct:
                                    _iter_timings = _ct
                                _cu = chunk_data.get("usage")
                                if _cu:
                                    _iter_usage = _cu

                                # See the note on the first stream loop: an error chunk has
                                # no choices, so `continue` below would drop it silently.
                                _stream_error = stream_error_from_chunk(chunk_data)
                                if _stream_error is not None:
                                    raise _stream_error
                                choices = chunk_data.get("choices", [])
                                if not choices:
                                    continue

                                delta = choices[0].get("delta", {})
                                _fr = choices[0].get("finish_reason")
                                if _fr:
                                    _iter_finish_reason = _fr

                                # ── Structured tool_calls ──
                                tc_deltas = delta.get("tool_calls")
                                if tc_deltas:
                                    # Preserve any visible preface before draining
                                    # the structured tool call.
                                    has_structured_tc = True
                                    detect_state = _S_DRAINING
                                    # Close the reasoning prefix before the tool card
                                    # (mirrors the is_match path).
                                    if _close_streamed_think():
                                        yield {"type": "content", "text": cumulative_display}
                                    for tc_d in tc_deltas:
                                        idx = tc_d.get("index", 0)
                                        tc_id = tc_d.get("id")
                                        # a second call at a reused index forks its own slot; bare fragments follow whichever call owns the index now
                                        acc_key = tool_calls_open_key.get(idx, idx)
                                        if isinstance(tc_id, str) and tc_id:
                                            open_id = tool_calls_acc.get(acc_key, {}).get("id")
                                            # a synthetic placeholder is not a rival call, so a first real id still lands on the slot that is open
                                            if (
                                                open_id
                                                and acc_key not in tool_calls_synthetic_ids
                                                and open_id != tc_id
                                            ):
                                                first_id = tool_calls_acc.get(idx, {}).get("id")
                                                acc_key = idx if first_id == tc_id else (idx, tc_id)
                                        tool_calls_open_key[idx] = acc_key
                                        if acc_key not in tool_calls_acc:
                                            tool_calls_acc[acc_key] = {
                                                "id": tc_id or f"call_{idx}",
                                                "type": "function",
                                                "function": {
                                                    "name": "",
                                                    "arguments": "",
                                                },
                                            }
                                            if not tc_id:
                                                tool_calls_synthetic_ids.add(acc_key)
                                        elif tc_id:
                                            # Update ID if a real one
                                            # arrives on a later delta.
                                            tool_calls_acc[acc_key]["id"] = tc_id
                                            tool_calls_synthetic_ids.discard(acc_key)
                                        func = tc_d.get("function", {})
                                        if func.get("name"):
                                            tool_calls_acc[acc_key]["function"]["name"] += func[
                                                "name"
                                            ]
                                        if func.get("arguments"):
                                            tool_calls_acc[acc_key]["function"]["arguments"] += (
                                                func["arguments"]
                                            )
                                        current_name = tool_calls_acc[acc_key]["function"].get(
                                            "name", ""
                                        )
                                        fallback_id = f"call_{idx}"
                                        current_id = tool_calls_acc[acc_key].get("id", fallback_id)
                                        is_first_accumulated_call = (
                                            next(iter(tool_calls_acc)) == acc_key
                                        )
                                        already_started = (
                                            current_id in provisional_started_tool_calls
                                        )
                                        # Empty/synthetic ids cannot reconcile with real starts.
                                        has_real_id = bool(current_id) and current_id != fallback_id
                                        # Show one early card per eligible streamed tool call.
                                        _is_completed_one_shot = (
                                            current_name == "render_html"
                                            and _tool_succeeded("render_html")
                                        )
                                        # render_html is one-shot.
                                        _one_shot_already_provisional = (
                                            current_name == "render_html"
                                            and "render_html"
                                            in provisional_started_tool_calls.values()
                                        )
                                        # Later parallel cards only reconcile when parallel use is enabled.
                                        # In auto mode an always-safe tool (render_html) never
                                        # prompts, so it must stream its early card too; mirror
                                        # that here instead of gating on the raw confirm flag.
                                        _confirm_gated = (
                                            confirm_tool_calls
                                            and not bypass_permissions
                                            and not (
                                                permission_mode == "auto"
                                                and is_always_safe_tool(current_name)
                                            )
                                            # A text-preview card still streams while gated;
                                            # hiding it blanks the chat.
                                            and not has_text_only_provisional_card(current_name)
                                        )
                                        # Keep small-argument tools on the normal path.
                                        _args_len = len(
                                            tool_calls_acc[acc_key]["function"].get("arguments", "")
                                        )
                                        _payload_is_large = (
                                            current_name == "render_html"
                                            or _args_len >= _PROVISIONAL_ARGS_MIN_CHARS
                                        )
                                        if (
                                            current_name
                                            and (
                                                is_first_accumulated_call
                                                or not disable_parallel_tool_use
                                            )
                                            and has_real_id
                                            and not already_started
                                            and not _is_completed_one_shot
                                            and not _one_shot_already_provisional
                                            and not _confirm_gated
                                            and _payload_is_large
                                            and any(
                                                (tool.get("function") or {}).get("name")
                                                == current_name
                                                for tool in safe_tools
                                            )
                                        ):
                                            provisional_started_tool_calls[current_id] = (
                                                current_name
                                            )
                                            yield {
                                                "type": "tool_start",
                                                "tool_name": current_name,
                                                "tool_call_id": current_id,
                                                "arguments": {},
                                                "provenance": provisional_tool_provenance(
                                                    current_name
                                                ),
                                            }
                                        # Stream argument text so the UI shows the code being
                                        # written: first event the backlog, later the fragment.
                                        # Display only; accumulator untouched.
                                        if current_id in provisional_started_tool_calls:
                                            if current_id not in arg_streamed_tool_call_ids:
                                                arg_streamed_tool_call_ids.add(current_id)
                                                _args_backlog = tool_calls_acc[acc_key][
                                                    "function"
                                                ].get("arguments", "")
                                                if _args_backlog:
                                                    yield {
                                                        "type": "tool_args",
                                                        "tool_call_id": current_id,
                                                        "tool_name": current_name,
                                                        "text": _args_backlog,
                                                    }
                                            elif func.get("arguments"):
                                                yield {
                                                    "type": "tool_args",
                                                    "tool_call_id": current_id,
                                                    "tool_name": current_name,
                                                    "text": func["arguments"],
                                                }
                                    continue

                                # ── Reasoning tokens ──
                                # Stream live except while DRAINING: reasoning is
                                # orthogonal to tool detection (content_buffer
                                # only), and the route resets prev_text on
                                # tool_start, so the <think> block stays a
                                # monotonic prefix like the no-tool path.
                                reasoning = delta.get("reasoning_content", "")
                                if reasoning:
                                    if _reasoning_started_at is None:
                                        _reasoning_started_at = time.monotonic()
                                    reasoning_accum += reasoning
                                    if detect_state != _S_DRAINING:
                                        if not in_thinking:
                                            # Suppressed (forced-retry) iterations
                                            # yield no content events, so recording
                                            # their wraps would desync the ledger
                                            # from the emitted stream.
                                            if (
                                                reasoning_provenance is not None
                                                and not cumulative_display
                                                and not _suppress_visible_output
                                            ):
                                                reasoning_provenance["wrapped"] = (
                                                    reasoning_provenance.get("wrapped", 0) + 1
                                                )
                                                _prov_entry = {"len": 0}
                                                reasoning_provenance.setdefault("wraps", []).append(
                                                    _prov_entry
                                                )
                                            cumulative_display += "<think>"
                                            in_thinking = True
                                        cumulative_display += reasoning
                                        if _prov_entry is not None:
                                            _prov_entry["len"] += len(reasoning)
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": cumulative_display,
                                            }

                                # ── Content tokens ──
                                token = delta.get("content", "")
                                if token:
                                    # First answer token ends reasoning.
                                    if (
                                        _reasoning_started_at is not None
                                        and not _reasoning_summary_emitted
                                    ):
                                        _reasoning_summary_emitted = True
                                        _summary = _reasoning_summary_event(_reasoning_started_at)
                                        if _suppress_visible_output:
                                            _deferred_reasoning_summary = _summary
                                        else:
                                            yield _summary
                                    has_content_tokens = True
                                    content_accum += token

                                    if detect_state == _S_DRAINING:
                                        # Accumulate silently for parsing, but stream the drained
                                        # TEXT call to a provisional card. Gated on an enabled-name
                                        # sniff + size floor so prose/small calls spawn no pane; id
                                        # matches the first call so the final tool_start reconciles.
                                        if not has_structured_tc and _text_args_call_start >= 0:
                                            if not _text_args_id:
                                                _call_text = content_accum[_text_args_call_start:]
                                                _sniffed = _sniff_text_tool_name(
                                                    _call_text, _enabled_tool_names
                                                )
                                                # Structured-path rule: gated calls
                                                # stream only from a text-preview card.
                                                if (
                                                    _sniffed
                                                    and not (
                                                        _confirm_gated_iteration
                                                        and not has_text_only_provisional_card(
                                                            _sniffed
                                                        )
                                                    )
                                                    and (
                                                        _sniffed == "render_html"
                                                        or len(_call_text)
                                                        >= _PROVISIONAL_ARGS_MIN_CHARS
                                                    )
                                                ):
                                                    _text_args_id = "call_0"
                                                    _text_args_name = _sniffed
                                                    if (
                                                        _text_args_id
                                                        not in provisional_started_tool_calls
                                                    ):
                                                        provisional_started_tool_calls[
                                                            _text_args_id
                                                        ] = _sniffed
                                                        yield {
                                                            "type": "tool_start",
                                                            "tool_name": _sniffed,
                                                            "tool_call_id": _text_args_id,
                                                            "arguments": {},
                                                            "provenance": provisional_tool_provenance(
                                                                _sniffed
                                                            ),
                                                        }
                                                    yield {
                                                        "type": "tool_args",
                                                        "tool_call_id": _text_args_id,
                                                        "tool_name": _sniffed,
                                                        "text": _call_text,
                                                    }
                                                    _text_args_streamed_upto = len(content_accum)
                                            elif len(content_accum) > _text_args_streamed_upto:
                                                yield {
                                                    "type": "tool_args",
                                                    "tool_call_id": _text_args_id,
                                                    "tool_name": _text_args_name,
                                                    "text": content_accum[
                                                        _text_args_streamed_upto:
                                                    ],
                                                }
                                                _text_args_streamed_upto = len(content_accum)

                                    elif detect_state == _S_STREAMING:
                                        if in_thinking:
                                            cumulative_display += "</think>"
                                            in_thinking = False
                                            _prov_entry = None
                                        cumulative_display += token
                                        cleaned = _strip_tool_markup_streaming(cumulative_display)
                                        # Hold a trailing bare active-tool-name (split rehearsal)
                                        # until [ARGS] arrives; released by later prose or stream end.
                                        _hold = _held_rehearsal_tail_len(cleaned, _detect_tools)
                                        _emit = (
                                            cleaned[: len(cleaned) - _hold] if _hold else cleaned
                                        )
                                        if len(_emit) > len(_last_emitted):
                                            _last_emitted = _emit
                                            if not _suppress_visible_output:
                                                yield {
                                                    "type": "content",
                                                    "text": _emit,
                                                }

                                    elif detect_state == _S_BUFFERING:
                                        content_buffer += token
                                        stripped_buf = content_buffer.lstrip()
                                        if not stripped_buf:
                                            continue

                                        # Bracket tags arrive mid-buffer, so substring-check too;
                                        # ``[ARGS]`` counts only as a regex-matched NAME[ARGS].
                                        is_prefix = False
                                        is_match = False
                                        for sig in _tool_xml_signals:
                                            if stripped_buf.startswith(sig):
                                                is_match = True
                                                break
                                            if sig.startswith(stripped_buf):
                                                is_prefix = True
                                                break
                                            if sig == "[ARGS]":
                                                # Active NAME[ARGS] only; inactive-name prose
                                                # is gated out, not drained/parsed.
                                                if (
                                                    _gguf_rehearsal_signal_pos(
                                                        stripped_buf, _detect_tools
                                                    )
                                                    >= 0
                                                ):
                                                    is_match = True
                                                    break
                                            elif sig.startswith("[") and sig in stripped_buf:
                                                is_match = True
                                                break

                                        # Split rehearsal: hold the bare name until
                                        # its [ARGS] arrives and matches above.
                                        is_rehearsal_prefix = False
                                        if (
                                            not is_match
                                            and not is_prefix
                                            and _is_rehearsal_prefix(stripped_buf, _detect_tools)
                                        ):
                                            is_prefix = True
                                            is_rehearsal_prefix = True

                                        # Signal-less call shapes (mirror the safetensors
                                        # loop): Llama-3.2 bare {"name":..} and Gemma
                                        # call:NAME{...} would otherwise stream raw.
                                        _hold_buffer = False
                                        # Whole buffer is the call (no visible prefix) -- drain silently.
                                        _drain_silently = False
                                        if not is_match and not is_prefix:
                                            _bare = strip_llama3_leading_sentinels(stripped_buf)
                                            if _bare.startswith("{"):
                                                if _balanced_brace_end(_bare, 0) is None:
                                                    if len(stripped_buf) < _MAX_BARE_JSON_BUFFER:
                                                        _hold_buffer = True
                                                    elif _looks_like_enabled_bare_json(
                                                        _bare, _enabled_tool_names
                                                    ):
                                                        # Oversized still-open enabled call: drain
                                                        # rather than leak; a giant ordinary JSON
                                                        # answer still streams.
                                                        _drain_silently = True
                                                elif self._parse_tool_calls_from_text(
                                                    content_buffer,
                                                    allow_incomplete = auto_heal_tool_calls,
                                                    enabled_tool_names = _enabled_tool_names,
                                                ):
                                                    _drain_silently = True
                                            elif (
                                                "call:".startswith(stripped_buf)
                                                or _GEMMA_BARE_TC_PREFIX_RE.match(stripped_buf)
                                                is not None
                                                or _GEMMA_BARE_TC_RE.match(stripped_buf) is not None
                                            ):
                                                # Whitespace-tolerant like the parser.
                                                if _GEMMA_BARE_TC_RE.match(stripped_buf):
                                                    _drain_silently = True
                                                elif len(stripped_buf) < _MAX_BUFFER_CHARS:
                                                    _hold_buffer = True

                                        if _drain_silently:
                                            # The buffered content IS the call; drain it
                                            # without yielding. A live <think> prefix is
                                            # separate from it -- close that.
                                            detect_state = _S_DRAINING
                                            # Call text begins at the held buffer
                                            # (live arg display only; UI extracts the code).
                                            _text_args_call_start = len(content_accum) - len(
                                                content_buffer
                                            )
                                            if _close_streamed_think():
                                                yield {
                                                    "type": "content",
                                                    "text": cumulative_display,
                                                }
                                        elif is_match:
                                            # Tool signal -- flush any visible
                                            # prefix before DRAINING so the
                                            # route sends it before tool_start.
                                            # Use the final strip (all families incl. Llama
                                            # <|python_tag|> / Mistral name): the buffer holds
                                            # the whole call, so a streaming closed-only strip
                                            # would leak its open-ended markup as display text.
                                            _flush_reasoning_and_buffer()
                                            cleaned = _strip_tool_markup(
                                                cumulative_display,
                                                final = True,
                                                force = True,
                                            )
                                            if len(cleaned) > len(_last_emitted):
                                                _last_emitted = cleaned
                                                if not _suppress_visible_output:
                                                    yield {
                                                        "type": "content",
                                                        "text": cleaned,
                                                    }
                                            detect_state = _S_DRAINING
                                            # Live-arg display starts at the held buffer
                                            # (visible prefix flushed above; UI extracts the code).
                                            _text_args_call_start = len(content_accum) - len(
                                                content_buffer
                                            )
                                        elif _hold_buffer or (
                                            is_prefix
                                            and (
                                                is_rehearsal_prefix
                                                or len(stripped_buf) < _MAX_BUFFER_CHARS
                                            )
                                        ):
                                            # A rehearsal prefix is self-bounded; the buffer
                                            # cap must not cut long MCP names short.
                                            pass  # keep buffering
                                        else:
                                            # Not a tool -- flush buffer
                                            detect_state = _S_STREAMING
                                            # Flush reasoning accumulated
                                            # during BUFFERING.
                                            _flush_reasoning_and_buffer()
                                            cleaned = _strip_tool_markup(
                                                cumulative_display,
                                            )
                                            # Same trailing-name hold as STREAMING for this
                                            # first flush out of BUFFERING.
                                            _hold = _held_rehearsal_tail_len(cleaned, _detect_tools)
                                            _emit = (
                                                cleaned[: len(cleaned) - _hold]
                                                if _hold
                                                else cleaned
                                            )
                                            if len(_emit) > len(_last_emitted):
                                                _last_emitted = _emit
                                                if not _suppress_visible_output:
                                                    yield {
                                                        "type": "content",
                                                        "text": _emit,
                                                    }

                            except json.JSONDecodeError:
                                logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                        if _stream_done:
                            break  # exit outer for

                # ── Resolve BUFFERING at stream end ──
                if detect_state == _S_BUFFERING:
                    stripped_buf = content_buffer.lstrip()
                    # A held bare-JSON fragment has no XML signal; route it to DRAINING (the signal-only
                    # gate below would flush the raw JSON to the user).
                    _bare_eos = strip_llama3_leading_sentinels(stripped_buf)
                    # Gate on enabled names so an ordinary JSON answer isn't routed to DRAINING and dropped.
                    _is_bare_tc = bool(active_tools) and _looks_like_enabled_bare_json(
                        _bare_eos, _enabled_tool_names
                    )
                    if stripped_buf and _gguf_has_genuine_tool_signal(
                        stripped_buf, _tool_xml_signals, _detect_tools
                    ):
                        detect_state = _S_DRAINING
                    elif _is_bare_tc:
                        detect_state = _S_DRAINING
                    elif content_accum or reasoning_accum:
                        detect_state = _S_STREAMING
                        if content_buffer:
                            # Flush reasoning first.
                            _flush_reasoning_and_buffer()
                            if not _suppress_visible_output:
                                yield {
                                    "type": "content",
                                    "text": _strip_tool_markup(
                                        cumulative_display,
                                        final = True,
                                    ),
                                }
                        elif reasoning_accum and not has_content_tokens:
                            # Reasoning-only reply: show it as the main response,
                            # not a thinking block (mirrors the no-tool path; the
                            # route's extractor closes the streamed <think>).
                            if _reasoning_started_at is not None and not _reasoning_summary_emitted:
                                _reasoning_summary_emitted = True
                                _summary = _reasoning_summary_event(_reasoning_started_at)
                                if _suppress_visible_output:
                                    _deferred_reasoning_summary = _summary
                                else:
                                    yield _summary
                            cumulative_display = _finalize_reasoning_only_cumulative(
                                cumulative_display,
                                reasoning_accum,
                                _iter_finish_reason,
                                promote_reasoning_only,
                            )
                            _prov_entry = None
                            if not _suppress_visible_output:
                                yield {
                                    "type": "content",
                                    "text": cumulative_display,
                                }
                    else:
                        # Held buffer was no tool signal and no enabled bare-JSON call: a leading ``{`` is an
                        # ordinary JSON answer and must be shown; any other partial-markup prefix is dropped.
                        _held = strip_llama3_leading_sentinels(content_buffer.lstrip())
                        if _held.startswith("{") and not _suppress_visible_output:
                            yield {"type": "content", "text": _held}
                        return

                # ── STREAMING path: no tool call ──
                if detect_state == _S_STREAMING:
                    # Safety net: re-parse the full content for tool calls. The
                    # route layer resets prev_text on tool_start, so post-tool
                    # synthesis streams correctly even if content was emitted
                    # before the tool XML.
                    # Unconditional (not gated on _tool_xml_signals): bare-JSON and Gemma wrapper-less
                    # calls carry no XML signal, so a signal gate would let them slip past.
                    _safety_tc = self._parse_tool_calls_from_text(
                        content_accum,
                        allow_incomplete = auto_heal_tool_calls,
                        enabled_tool_names = _enabled_tool_names,
                    )
                    if not _safety_tc:
                        # ── Re-prompt on plan-without-action ──
                        # Intent described without a tool call: nudge it to act. Up
                        # to _MAX_REPROMPTS times, only on short responses with intent
                        # signals -- "4" or "Hello!" won't trigger it. Uses content,
                        # else reasoning text (reasoning-only stalls).
                        _stripped = content_accum.strip()
                        if not _stripped:
                            _stripped = reasoning_accum.strip()
                        _render_html_already_done_intent = _tool_succeeded(
                            "render_html"
                        ) and re.search(
                            r"(?i)\brender[_\s-]?html\b",
                            _stripped,
                        )
                        # A post-tool stall still deserves a nudge, but each retry
                        # re-runs tools, so allow only one. RAG autoinject never lands
                        # in history, so _auto keeps a doc-grounded turn from reading
                        # as pre-tool (mirrors safetensors rag_autoinjected).
                        _already_acted = bool(_auto) or any(
                            record.executed for record in tool_controller.history
                        )
                        if _already_acted:
                            _reprompt_used, _reprompt_cap = _post_tool_reprompts, 1
                        else:
                            _reprompt_used, _reprompt_cap = _reprompt_count, _MAX_REPROMPTS
                        # None follows the shared process default; explicit values win.
                        if (
                            auto_heal_tool_calls
                            and _nudge_enabled(nudge_tool_calls)
                            and active_tools
                            and not _render_html_already_done_intent
                            and _reprompt_used < _reprompt_cap
                            and not _is_reprompt_repeat(_stripped, _last_reprompt_text)
                            and _is_short_intent_without_action(_stripped)
                        ):
                            _reprompt_count += 1
                            if _already_acted:
                                _post_tool_reprompts += 1
                            _last_reprompt_text = _stripped
                            logger.info(
                                f"Re-prompt {_reprompt_used + 1}/{_reprompt_cap}: "
                                f"model responded without calling tools "
                                f"({len(_stripped)} chars)"
                            )
                            # Merges into a resumed partial: the nudge that follows is a
                            # user turn, so a second assistant turn breaks alternation.
                            append_assistant_turn(
                                conversation,
                                {"role": "assistant", "content": _stripped},
                                continue_final_message = continue_final_message,
                            )
                            available_tool_names = [
                                (tool.get("function") or {}).get("name")
                                for tool in active_tools
                                if isinstance(tool, dict) and isinstance(tool.get("function"), dict)
                            ]
                            available_tool_names = [name for name in available_tool_names if name]
                            tool_hint = " or ".join(available_tool_names) or "an available tool"
                            _forced_tool_call_pending = True
                            conversation.append(
                                {
                                    "role": "user",
                                    "content": _reprompt_to_act_message(tool_hint),
                                }
                            )
                            # Accumulate tokens and timing from this iteration.
                            _fu_r = _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                            _accumulated_completion_tokens += _fu_r.get("completion_tokens", 0)
                            _it_r = _iter_timings or {}
                            _accumulated_predicted_ms += _it_r.get("predicted_ms", 0)
                            _accumulated_predicted_n += _it_r.get("predicted_n", 0)
                            # Blank first (the route resets its text cursor only on an
                            # empty status), then the badge so the retry is not a hang.
                            yield {"type": "status", "text": ""}
                            yield {"type": "status", "text": _NUDGE_TOOL_CALLS_STATUS}
                            continue

                        if _forced_tool_call_pending:
                            _forced_tool_call_pending = False
                            if not _should_suppress_forced_no_tool_output(
                                _stripped,
                                _last_reprompt_text,
                            ):
                                if cumulative_display:
                                    forced_visible_text = _strip_tool_markup(
                                        cumulative_display,
                                        final = True,
                                    )
                                elif content_accum:
                                    forced_visible_text = _strip_tool_markup(
                                        content_accum,
                                        final = True,
                                    )
                                else:
                                    forced_visible_text = reasoning_accum
                                if forced_visible_text:
                                    yield {
                                        "type": "content",
                                        "text": forced_visible_text,
                                    }
                                    if _deferred_reasoning_summary is not None:
                                        yield _deferred_reasoning_summary
                        elif not _suppress_visible_output:
                            # Turn ended as a plain answer (no [ARGS] followed): the held
                            # rehearsal tail is real prose, release it.
                            _final_clean = _strip_tool_markup_streaming(cumulative_display)
                            if len(_final_clean) > len(_last_emitted):
                                yield {"type": "content", "text": _final_clean}

                        # Content was already streamed.  Yield metadata.
                        yield {"type": "status", "text": ""}
                        _meta = _build_metadata_event(
                            _iter_usage, _iter_timings, _iter_finish_reason
                        )
                        if _meta is not None:
                            yield _meta
                        return

                    # Safety net caught tool XML -- treat as tool call.
                    tool_calls = _safety_tc
                    content_text = _strip_tool_markup(
                        content_accum,
                        final = True,
                        force = True,
                    )
                    logger.info(
                        f"Safety net: parsed {len(tool_calls)} tool call(s) from streamed content"
                    )
                else:
                    # ── DRAINING path: assemble tool_calls ──
                    tool_calls = None
                    content_text = content_accum
                    if has_structured_tc:
                        # Drop incomplete fragments (e.g. from max_tokens
                        # truncation or disconnect).
                        # first-seen order: a call forked onto a reused index arrived after every call already open, so it must execute and replay last
                        tool_calls = [
                            call
                            for call in tool_calls_acc.values()
                            if (call.get("function", {}).get("name", "").strip())
                        ] or None
                    if not tool_calls:
                        # Unconditional re-parse: we only reach DRAINING when the buffer looked like a
                        # call, and bare-JSON / Gemma wrapper-less calls carry no XML signal to gate on.
                        tool_calls = self._parse_tool_calls_from_text(
                            content_accum,
                            allow_incomplete = auto_heal_tool_calls,
                            enabled_tool_names = _enabled_tool_names,
                        )
                    if tool_calls and not has_structured_tc:
                        content_text = _strip_tool_markup(
                            content_text,
                            final = True,
                            force = True,
                        )
                        # ``_strip_tool_markup`` only knows XML; also drop a leading bare-JSON call so the
                        # executed call isn't replayed as text or next-turn history.
                        content_text = strip_leading_bare_json_call(
                            content_text, _enabled_tool_names
                        )
                    if tool_calls:
                        logger.info(
                            f"Parsed {len(tool_calls)} tool call(s) from "
                            f"{'structured delta' if has_structured_tc else 'content text'}"
                        )
                    if not tool_calls:
                        # DRAINING but no tool calls (false positive): close any
                        # provisional cards (a sniff can open one whose call never
                        # parses); without a tool_end the card spins forever.
                        for _pid, _pname in provisional_started_tool_calls.items():
                            if _pid not in resolved_provisional_tool_call_ids:
                                resolved_provisional_tool_call_ids.add(_pid)
                                yield {
                                    "type": "tool_end",
                                    "tool_name": _pname,
                                    "tool_call_id": _pid,
                                    "result": "",
                                    "provenance": provisional_tool_provenance(_pname),
                                }
                        # Merge metrics from prior tool iterations so they aren't dropped.
                        yield {"type": "status", "text": ""}
                        if content_accum:
                            # Strip leaked tool-call XML before yielding.
                            content_accum = _strip_tool_markup(content_accum, final = True)
                        # A truncated bare-JSON call has no XML markup to strip and didn't parse. With
                        # Auto-Heal on, drop a leading ENABLED-tool fragment (ordinary JSON answers untouched);
                        # off keeps it visible per the strict contract.
                        if content_accum and active_tools and auto_heal_tool_calls:
                            content_accum = strip_leading_bare_json_call(
                                content_accum, _enabled_tool_names
                            )
                        if content_accum:
                            yield {"type": "content", "text": content_accum}
                        _meta = _build_metadata_event(
                            _iter_usage, _iter_timings, _iter_finish_reason
                        )
                        if _meta is not None:
                            yield _meta
                        return

                # ── Execute tool calls ──
                _accumulated_completion_tokens += (
                    _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                ).get("completion_tokens", 0)
                _it = _iter_timings or {}
                _accumulated_predicted_ms += _it.get("predicted_ms", 0)
                _accumulated_predicted_n += _it.get("predicted_n", 0)

                # Collapse exact-duplicate calls and cap the count for the TEXTUAL
                # fallback (mirrors the safetensors loop; see _MAX_TOOL_CALLS_PER_TURN).
                if tool_calls and not has_structured_tc and len(tool_calls) > 1:
                    _seen_keys: set = set()
                    _deduped: list = []
                    for _tc in tool_calls:
                        _fn = _tc.get("function", {}) or {}
                        _key = (_fn.get("name", ""), str(_fn.get("arguments", "")))
                        if _key in _seen_keys:
                            continue
                        _seen_keys.add(_key)
                        _deduped.append(_tc)
                        if len(_deduped) >= _MAX_TOOL_CALLS_PER_TURN:
                            break
                    if len(_deduped) != len(tool_calls):
                        logger.info(
                            "GGUF textual fallback: collapsed %d repeated tool call(s) "
                            "in one turn to %d",
                            len(tool_calls),
                            len(_deduped),
                        )
                    tool_calls = _deduped

                # disable_parallel_tool_use: execute only the first tool call
                # this turn. Truncate before building assistant_msg so the
                # conversation stays consistent and extra calls are never executed.
                if disable_parallel_tool_use and tool_calls and len(tool_calls) > 1:
                    tool_calls = tool_calls[:1]

                assistant_msg: dict = {"role": "assistant", "content": content_text}
                if reasoning_accum.strip():
                    assistant_msg["reasoning_content"] = reasoning_accum
                assistant_appended = False
                # Collect no-op feedback and flush it after the batch, so a
                # suppressed call never drops a later parallel call.
                deferred_noop_msgs: list = []
                # Which tools those no-ops were about, so the flush below can tell
                # whether the trailing result belongs to the same tool.
                deferred_noop_tools: set = set()

                # The text-path provisional card uses the parser's default id ("call_0");
                # a Mistral-style call carries its own id and would open a duplicate. Reuse
                # the card's id for the first matching call (same tool name) to reconcile.
                _text_provisional_id = _text_args_id if not has_structured_tc else ""

                for _call_index, tc in enumerate(tool_calls or []):
                    func = tc.get("function", {})
                    tool_name = func.get("name", "")
                    if (
                        _text_provisional_id
                        and _text_provisional_id in provisional_started_tool_calls
                        and _text_provisional_id not in resolved_provisional_tool_call_ids
                        and tc.get("id") not in provisional_started_tool_calls
                        and provisional_started_tool_calls[_text_provisional_id] == tool_name
                    ):
                        tc = {**tc, "id": _text_provisional_id}
                    provisional_match = tc.get("id") in provisional_started_tool_calls
                    decision = tool_controller.prepare_call(
                        tc,
                        forced = _forced_tool_call_pending,
                        provisional = provisional_match,
                        allowed_tool_names = {forced_name} if forced_name else None,
                    )

                    if not decision.should_execute:
                        if provisional_match:
                            # A provisional tool card is already on screen for this
                            # id; close it so it never dangles when the controller
                            # turns the call into an internal no-op (duplicate /
                            # disabled / render_html_repeat).
                            resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                            yield {
                                "type": "tool_end",
                                "tool_name": decision.tool_name,
                                "tool_call_id": decision.tool_call_id,
                                "result": "",
                                "provenance": decision.provenance,
                            }
                        completion = tool_controller.record_noop(decision)
                        deferred_noop_msgs.append(completion.model_message())
                        deferred_noop_tools.add(decision.tool_name)
                        if _forced_tool_call_pending:
                            _forced_tool_call_pending = False
                        logger.info(
                            "Suppressed local GGUF tool call as internal no-op: "
                            f"action={decision.action} tool={decision.tool_name}"
                        )
                        continue

                    if not assistant_appended:
                        assistant_msg["tool_calls"] = [decision.as_assistant_tool_call()]
                        # Merges into a resumed partial, so a continued turn that calls
                        # a tool stays one assistant message.
                        append_assistant_turn(
                            conversation,
                            assistant_msg,
                            continue_final_message = continue_final_message,
                        )
                        assistant_appended = True
                    else:
                        assistant_msg.setdefault("tool_calls", []).append(
                            decision.as_assistant_tool_call()
                        )

                    # Bypass wins here too, so a direct internal caller with both
                    # flags never prompts. "auto" pauses only high-risk calls;
                    # "off" never prompts (sandbox stays on).
                    needs_confirm = (
                        bool(confirm_tool_calls)
                        and not bypass_permissions
                        and permission_mode != "off"
                    )
                    if needs_confirm and permission_mode == "auto":
                        needs_confirm = is_high_risk_tool_call(
                            decision.tool_name, decision.arguments
                        )
                    approval_id = new_approval_id() if needs_confirm else ""
                    decision_slot = (
                        begin_tool_decision(session_id, approval_id) if needs_confirm else None
                    )
                    start_event = decision.tool_start_event()
                    start_event["approval_id"] = approval_id
                    start_event["awaiting_confirmation"] = needs_confirm

                    try:
                        # Gated calls are not running yet; a "Running ..." badge
                        # counting up while it waits on a human reads as a hang.
                        yield {
                            "type": "status",
                            "text": (
                                awaiting_approval_status(decision.tool_name)
                                if needs_confirm
                                else decision.status_text
                            ),
                        }
                        yield start_event

                        _decision = (
                            wait_tool_decision(
                                decision_slot,
                                approval_id,
                                cancel_event = cancel_event,
                            )
                            if decision_slot is not None
                            else None
                        )
                        if _decision is not None and _decision != "deny":
                            # Approved: now it really is running.
                            yield {"type": "status", "text": decision.status_text}
                        if _decision == "deny":
                            decision_slot = None
                            _forced_choice_resolved = True
                            resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                            yield {
                                "type": "tool_end",
                                "tool_name": decision.tool_name,
                                "tool_call_id": decision.tool_call_id,
                                "result": TOOL_REJECTED_MESSAGE,
                                "provenance": decision.provenance,
                            }
                            denied_message = {
                                "role": "tool",
                                "name": decision.tool_name,
                                "content": TOOL_REJECTED_MESSAGE,
                            }
                            if decision.tool_call_id:
                                denied_message["tool_call_id"] = decision.tool_call_id
                            conversation.append(denied_message)
                            if _forced_tool_call_pending:
                                _forced_tool_call_pending = False
                            continue
                        decision_slot = None
                    finally:
                        if decision_slot is not None:
                            abort_tool_decision(decision_slot, approval_id)

                    _effective_timeout = None if tool_call_timeout >= 9999 else tool_call_timeout
                    # RAG: cap paraphrased KB re-searches that slip past the dup guard.
                    if (
                        decision.tool_name in RAG_SEARCH_TOOLS
                        and _kb_search_count >= RAG_MAX_SEARCHES_PER_TURN
                    ):
                        result = RAG_SEARCH_CAP_NUDGE
                    else:
                        # Execute in a worker thread so live stdout chunks and heartbeats
                        # stream while the tool blocks (the SSE route turns heartbeats into
                        # keepalives). Result is byte-identical to a direct call.
                        def _invoke_tool(_output_callback, _decision = decision):
                            # execute_tool is injectable and may be monkey-patched with the
                            # pre-PR signature; forward output_callback only if it's accepted.
                            kwargs = dict(
                                cancel_event = cancel_event,
                                timeout = _effective_timeout,
                                session_id = session_id,
                                thread_id = thread_id,
                                rag_scope = rag_scope,
                                disable_sandbox = bypass_permissions,
                            )
                            # Same branch the forced recall is filtered against, so a
                            # model-initiated search cannot reach a sibling response the
                            # forced recall correctly refused.
                            if accepts_kwarg(execute_tool, "conversation_branch"):
                                kwargs["conversation_branch"] = _extend_live_branch(conversation)
                            # And the room actually left: the model picks its own top_k and
                            # the result lands in the current tool exchange, which rolling
                            # truncation protects, so a top_k the window cannot hold ends
                            # the turn in an unrecoverable context-length error.
                            if self._effective_context_length:
                                # Priced against the catalogue too: the messages alone
                                # leave the tools array out, and a big catalogue can put
                                # the request near its budget while this still reports
                                # room for several 500-token chunks.
                                # `fit_rolling_context` returns None when it dropped
                                # nothing, so a prompt that simply FITS leaves
                                # `_prompt_token_offset` unset -- after a context-length
                                # increase, or on a shorter branch. The character estimate
                                # that stood in for it there leaves out the template's own
                                # framing, so it can report room that is not there, the
                                # recall appends a passage too large for the real window,
                                # and the next iteration cannot evict it again because the
                                # current tool exchange is protected.
                                #
                                # So price it exactly instead, here. A failure falls back
                                # to the estimate, which is what this did before.
                                #
                                # Once per TOOL CALL, not once per retrieval: every result
                                # is now sized against this figure, not only a retrieval's,
                                # because a `cat` of a large file overflows the window the
                                # same way a too-large recall does and is likewise
                                # protected from eviction once appended. One tokenizer pass
                                # over the conversation next to running the tool itself.
                                #
                                # Recomputed on EVERY search, not cached for the request.
                                # The count is absolute, and the loop appends the assistant
                                # call and the tool result of every intervening tool to
                                # `conversation`, so a cached figure understates the prompt
                                # by exactly those exchanges and hands the search room that
                                # is already spent. The offset on the other leg is a
                                # framing correction rather than a total, so it stays valid
                                # as the conversation grows.
                                # Unconditionally, not only when the fit dropped nothing.
                                # Gated on `_prompt_token_offset is None`, a request that
                                # HAD compacted priced every later search as a character
                                # estimate plus an offset measured before the loop's own
                                # tool exchanges existed, so a dense ASCII result appended
                                # after that fit -- code, minified JSON, command output --
                                # was undercounted and the recall spent room that was
                                # already gone. The exact count covers the same ground as
                                # the offset leg, since it prices the conversation WITH
                                # the tool catalogue, so the offset stays only as the
                                # fallback for a tokenizer call that raises.
                                _exact_prompt_tokens: Optional[int] = None
                                try:
                                    _exact_prompt_tokens = self.count_chat_tokens(
                                        neutralize_control_markup_in_messages(
                                            conversation, _markup_cache, self.markup_profile
                                        ),
                                        None,
                                        safe_tools,
                                        strict = True,
                                        chat_template_kwargs = _reasoning_kw,
                                    )
                                except Exception:
                                    logger.debug(
                                        "recall budget: exact prompt count failed",
                                        exc_info = True,
                                    )
                                # Dense on the fallback leg only: `_prompt_token_offset`
                                # already carries the fit's exact tokenizer count, so it
                                # needs no correction, while the estimate that stands in
                                # for it undercounts CJK and emoji by about half.
                                _spent = (
                                    _exact_prompt_tokens
                                    if _exact_prompt_tokens is not None
                                    else estimate_messages_tokens_dense(conversation)
                                    + (
                                        _prompt_token_offset
                                        if _prompt_token_offset is not None
                                        else estimate_messages_tokens_dense(safe_tools or [])
                                    )
                                )
                                # What ANY result may add before the next prompt is over
                                # budget, for every tool and not just the retrieval ones.
                                # The old cap was a share of the WINDOW and never fell as
                                # the thread filled, so the last result before an overflow
                                # claimed as much as the first, and nothing downstream
                                # recovers: the fit protects the newest turn.
                                if accepts_kwarg(execute_tool, "result_budget_tokens"):
                                    # Split across the calls still to run in this batch,
                                    # and after their arguments. One assistant turn can
                                    # call several tools, and the loop appends each call
                                    # only as it runs it, so `_spent` here knows nothing
                                    # about the rest of the batch: sized as if it were
                                    # alone, the first result can take all the room the
                                    # other calls and their results still need, and the
                                    # finished exchange is protected as the newest turn.
                                    _pending = list(tool_calls or [])[_call_index + 1 :]
                                    _pending_msgs = [
                                        {
                                            "role": "assistant",
                                            "content": json.dumps(_call, default = str),
                                        }
                                        for _call in _pending
                                    ]
                                    # Measured, not estimated: the estimator charges ASCII
                                    # four characters per token, and a pending call can
                                    # carry base64, minified JSON or a block of code, which
                                    # run nearer one or two. Under-priced, the first result
                                    # is handed room the later ARGUMENTS already occupy.
                                    _pending_args = 0
                                    if _pending_msgs:
                                        try:
                                            _pending_args = self.count_chat_tokens(
                                                _pending_msgs, None, None, strict = True
                                            )
                                        except Exception:
                                            logger.debug(
                                                "result budget: pending call count failed",
                                                exc_info = True,
                                            )
                                            _pending_args = 2 * estimate_messages_tokens_dense(
                                                _pending_msgs
                                            )
                                    kwargs["result_budget_tokens"] = tool_result_budget(
                                        self._effective_context_length,
                                        max_tokens,
                                        _spent + _pending_args,
                                    ) // (len(_pending) + 1)
                                if accepts_kwarg(execute_tool, "conversation_budget_tokens"):
                                    if accepts_kwarg(execute_tool, "conversation_token_counter"):
                                        # The admission check estimates a result's size by
                                        # characters, which is optimistic for ASCII that
                                        # tokenises densely: code, minified JSON, hashes and
                                        # command output all run nearer two or three
                                        # characters per token than four. This path has a
                                        # tokenizer, so hand it over and let the check spend
                                        # the budget as exactly as it computes it.
                                        kwargs["conversation_token_counter"] = lambda text: (
                                            self.count_chat_tokens(
                                                [{"role": "tool", "content": text}],
                                                None,
                                                None,
                                                strict = False,
                                            )
                                        )
                                    # The result and reply are protected on the next fit, so
                                    # the result cannot spend their entire shared budget.
                                    kwargs["conversation_budget_tokens"] = _retrieval_budget(
                                        self._effective_context_length,
                                        max_tokens,
                                        _spent,
                                        reply_returns = True,
                                    )
                            if accepts_output_callback(execute_tool):
                                kwargs["output_callback"] = _output_callback
                            kwargs.update(search_images_kwargs(execute_tool, _decision.tool_name))
                            return execute_tool(
                                _decision.tool_name,
                                _decision.arguments,
                                **kwargs,
                            )

                        # Without this the handler below re-raises and a bad
                        # argument kills the whole answer. A raising tool is the
                        # tool's failure; the other two loops hand it back.
                        try:
                            result = yield from stream_tool_execution(
                                _invoke_tool,
                                tool_name = decision.tool_name,
                                tool_call_id = decision.tool_call_id,
                                cancel_event = cancel_event,
                            )
                        except _LlamaStreamCancelled:
                            # Subclasses Exception, so the arm below would eat
                            # the cancel signal. CancelledError needs no arm:
                            # a BaseException passes straight through.
                            raise
                        except Exception as _tool_exc:
                            if cancel_event is not None and cancel_event.is_set():
                                raise
                            logger.exception(
                                "Tool %s raised: %s",
                                decision.tool_name,
                                _tool_exc,
                            )
                            result = f"Error: tool raised an exception: {_tool_exc}"
                        if decision.tool_name in RAG_SEARCH_TOOLS:
                            _kb_search_count += 1
                    completion = tool_controller.record_result(decision, result)
                    resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                    # A real execution opens the post-tool phase; carrying the pre-tool
                    # stall text over would read the same sentence as a repeat and
                    # swallow the one post-tool nudge.
                    _last_reprompt_text = ""
                    # A tool ran this turn, so it counts against the caller's budget.
                    _turn_executed_real_tool = True
                    _forced_choice_resolved = True
                    yield completion.tool_end_event()
                    conversation.append(completion.tool_message())

                    if _forced_tool_call_pending:
                        _forced_tool_call_pending = False

                # A mixed execute/no-op batch already has a real tool result, so keeping the
                # feedback with that result beats appending a newer user turn, which makes
                # templates hide this turn's structured reasoning. Only when the result is
                # the SAME tool the feedback is about: templates label the whole block with
                # the result's own tool name (gemma-4.jinja resolves tool_call_id -> name and
                # wraps the body), so folding a note about tool A into tool B's result reads
                # as B's own output. Then the user turn is the lesser loss.
                _fold_target_matches = (
                    len(deferred_noop_tools) == 1
                    and bool(conversation)
                    and conversation[-1].get("role") == "tool"
                    and conversation[-1].get("name") in deferred_noop_tools
                )
                if deferred_noop_msgs and assistant_appended and _fold_target_matches:
                    if not _attach_internal_feedback_to_tool_result(
                        deferred_nudge_text(deferred_noop_msgs)
                    ):
                        append_deferred_nudges(conversation, deferred_noop_msgs)
                elif deferred_noop_msgs and assistant_appended:
                    append_deferred_nudges(conversation, deferred_noop_msgs)
                else:
                    # A blank trace is not a turn: reuse the same emptiness test as
                    # the field above so a whitespace-only split never appends an
                    # empty assistant message.
                    if not assistant_appended and (
                        content_text or assistant_msg.get("reasoning_content")
                    ):
                        if assistant_msg.get("reasoning_content"):
                            assistant_msg["content"] = neutralize_control_markup(
                                reasoning_accum,
                                self.markup_profile,
                            )
                            _continued_partial = (
                                trailing_assistant_text(conversation)
                                if continue_final_message
                                else None
                            )
                            if _continued_partial and not _continued_partial.endswith("\n"):
                                assistant_msg["content"] = f"\n{assistant_msg['content']}"
                            if content_text:
                                assistant_msg["content"] += f"\n{content_text}"
                            del assistant_msg["reasoning_content"]
                        append_assistant_turn(
                            conversation,
                            assistant_msg,
                            continue_final_message = continue_final_message,
                        )
                        assistant_appended = True
                    append_deferred_nudges(conversation, deferred_noop_msgs)

                # Close provisional cards not resolved by execution/no-op handling.
                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "",
                            "provenance": provisional_tool_provenance(_pname),
                        }

                # Clear tool status badge before next generation/final pass.
                yield {"type": "status", "text": ""}
                if tool_controller.force_final_answer or not tool_controller.active_tools():
                    _append_budget_exhausted_nudge = False
                    break
                # Count only real tool turns against the cap so reserved re-prompt slots can't become
                # extra tool rounds; a no-op correction turn doesn't consume budget (GGUF parity).
                if _turn_executed_real_tool:
                    _tool_iters_done += 1
                    if _tool_iters_done >= max_tool_iterations:
                        break
                continue

            except _LlamaStreamCancelled:
                return
            except httpx.ConnectError:
                # Mark unresolved provisional cards as failed before raising.
                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "Error: lost connection to llama-server before the tool call completed.",
                            "provenance": provisional_tool_provenance(_pname),
                        }
                raise RuntimeError("Lost connection to llama-server")
            except Exception as e:
                if cancel_event is not None and cancel_event.is_set():
                    return
                # Same cleanup for other mid-iteration failures.
                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "Error: the tool call was interrupted before it completed.",
                            "provenance": provisional_tool_provenance(_pname),
                        }
                raise

        # ── Tool iteration cap reached -- synthesize final answer ──
        # The model used all iterations without a final text response. Nudge
        # the final streaming pass to produce a useful answer instead of
        # continuing to request tools.
        if max_tool_iterations > 0 and _append_budget_exhausted_nudge:
            if not _attach_internal_feedback_to_tool_result(BUDGET_EXHAUSTED_NUDGE):
                conversation.append({"role": "user", "content": BUDGET_EXHAUSTED_NUDGE})

        # Clear status.
        yield {"type": "status", "text": ""}

        # Final streaming pass with the full conversation context.
        from core.inference.chat_template_helpers import neutralize_control_markup_in_messages

        _reasoning_kw = self._request_reasoning_kwargs(
            enable_thinking, reasoning_effort, preserve_thinking
        )
        _final_max_tokens = (
            max_tokens
            if max_tokens is not None
            else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
        )
        _final_preflight_context_length = None
        _final_preflight_succeeded = False
        if (
            context_overflow == "truncate_oldest"
            and self._effective_context_length
            and not messages_have_media(conversation)
        ):
            _final_preflight_context_length = self._effective_context_length
            try:
                _before_final_fit = conversation
                # Withheld, not `tools`: this is the synthesised final answer and
                # `stream_payload` below sends no tools array at all, so the request's
                # catalogue answers a question it does not pose and would let a NEW epoch
                # start on the one pass that can never call `search_conversation`.
                # Replaying an epoch already in force is unaffected.
                _final_can_reset = _can_reset_epoch(
                    thread_id, _backend_supports_tools(self), tools_withheld = True
                )
                _final_sticky, _final_sticky_is_checkpoint = (
                    (0, True)
                    if _sticky_boundary_applied
                    else _sticky_compaction_state(
                        thread_id,
                        _request_branch,
                        context_policy = context_policy,
                        can_reset = _final_can_reset,
                        compaction_headroom_ratio = compaction_headroom_ratio,
                    )
                )
                conversation, truncation = _fit_with_instruction_pins(
                    conversation,
                    context_length = self._effective_context_length,
                    max_tokens = _final_max_tokens,
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(fitted, None, self.markup_profile),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    anchor_ids = _rolling_anchor_ids,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _final_can_reset,
                    reserve_tokens = _conversation_recall_reserve(thread_id),
                    sticky_dropped = _final_sticky,
                    sticky_is_checkpoint = _final_sticky_is_checkpoint,
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                _sticky_boundary_applied = True
                if truncation:
                    _recalled = _archive_and_recall(
                        conversation,
                        _before_final_fit,
                        branch_messages = _extend_live_branch(_before_final_fit),
                        thread_id = thread_id,
                        # Inline, not tool: this final-answer request is counted and sent
                        # with no tools array, so a forged tool role has no catalogue to
                        # match and breaks strict templates.
                        style = "inline",
                        # Checkpoint mode recalls once, on the turn that reset; rolling has no
                        # such key and keeps recalling on every turn that evicted anything.
                        force_recall = bool(truncation.get("checkpoint_started", True)),
                        # A rescued refusal may evict messages; archive them without recall.
                        recall_done = _conversation_recall_done or not truncation["fits"],
                        # The synthesized final answer never returns to the prompt.
                        recall_budget_tokens = _retrieval_budget(
                            self._effective_context_length,
                            max_tokens,
                            truncation.get("prompt_tokens_after") or 0,
                        ),
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                fitted, None, self.markup_profile
                            ),
                            None,
                            None,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                        ),
                    )
                    conversation = _recalled["conversation"]
                    truncation = {**truncation, **_recalled["counts"]}
                    if _recalled["recalled"]:
                        _conversation_recall_done = True
                        for _message in _recalled["anchored"]:
                            _rolling_anchor_ids.add(id(_message))
                        for _ev in _recalled["events"]:
                            yield _ev
                if truncation and _records_boundary(truncation):
                    truncation = {
                        **truncation,
                        **_boundary_metadata(
                            conversation, _request_branch, compaction_headroom_ratio
                        ),
                    }
                # `fits` False too: it carries the diagnosis the client needs to explain
                # WHY. Otherwise the user only sees llama-server's error, which reports
                # the whole conversation's size and advises shortening it even when the
                # single message just sent is the part that does not fit.
                if truncation:
                    yield {"type": "context_truncated", **truncation}
                _final_preflight_succeeded = True
            except Exception as exc:
                logger.warning("Could not preflight the rolling context window: %s", exc)

        stream_payload = {
            "messages": neutralize_control_markup_in_messages(
                conversation, None, self.markup_profile
            ),
            "stream": True,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
            "presence_penalty": presence_penalty,
            "frequency_penalty": frequency_penalty,
        }
        if logit_bias:
            stream_payload["logit_bias"] = logit_bias
        if _reasoning_kw is not None:
            stream_payload["chat_template_kwargs"] = _reasoning_kw
        stream_payload["max_tokens"] = _final_max_tokens
        if stop:
            stream_payload["stop"] = stop
        if seed is not None:
            stream_payload["seed"] = seed
        stream_payload["stream_options"] = {"include_usage": True}

        if perf_callback is not None:
            stream_payload["return_progress"] = True
            stream_payload["timings_per_token"] = True

        _final_respawn_truncations: list[dict] = []

        def _refit_final_after_respawn() -> None:
            nonlocal conversation
            _before_respawn_fit = conversation
            if (
                _final_preflight_context_length is None
                or not self._effective_context_length
                or (
                    _final_preflight_succeeded
                    and _final_preflight_context_length == self._effective_context_length
                )
            ):
                return
            if max_tokens is None:
                stream_payload["max_tokens"] = self._effective_context_length
            try:
                conversation, truncation = _fit_with_instruction_pins(
                    conversation,
                    context_length = self._effective_context_length,
                    max_tokens = max_tokens,
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(fitted, None, self.markup_profile),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    anchor_ids = _rolling_anchor_ids,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _can_reset_epoch(
                        thread_id,
                        _backend_supports_tools(self),
                        # The final pass again, so again no tools array is sent.
                        tools_withheld = True,
                    ),
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                if truncation:
                    # Archive only; see the iteration respawn refit above.
                    truncation.update(
                        _archive_and_recall(
                            conversation,
                            _before_respawn_fit,
                            thread_id = thread_id,
                            style = "inline",
                            recall_done = True,
                            branch_messages = _extend_live_branch(conversation),
                        )["counts"]
                    )
                # Recorded rather than only forwarded, for the same reason as the
                # iteration refit above.
                from core.inference import context_refusal  # noqa: PLC0415

                context_refusal.record_fit(truncation)
                stream_payload["messages"] = neutralize_control_markup_in_messages(
                    conversation, None, self.markup_profile
                )
                if truncation:
                    if _records_boundary(truncation):
                        truncation.update(
                            _boundary_metadata(
                                conversation, _request_branch, compaction_headroom_ratio
                            )
                        )
                    _final_respawn_truncations.append(truncation)
            except Exception as exc:
                logger.warning("Could not refit rolling context after respawn: %s", exc)
                raise

        cumulative = ""
        _last_emitted = ""
        in_thinking = False
        has_content_tokens = False
        reasoning_text = ""
        _prov_entry = None
        _final_reasoning_started_at: Optional[float] = None
        _final_reasoning_summary_emitted = False
        _metadata_usage = None
        _metadata_timings = None
        _metadata_finish_reason = None
        _stream_done = False

        try:
            with self._open_chat_stream_with_respawn_retry(
                stream_payload,
                cancel_event,
                on_respawn = _refit_final_after_respawn,
            ) as (
                response,
                first_token_deadline,
            ):
                for truncation in _final_respawn_truncations:
                    yield {"type": "context_truncated", **truncation}
                buffer = ""
                for raw_chunk in self._iter_text_cancellable(
                    response,
                    cancel_event,
                    first_token_deadline = first_token_deadline,
                ):
                    buffer += raw_chunk
                    while "\n" in buffer:
                        line, buffer = buffer.split("\n", 1)
                        line = line.strip()

                        if not line:
                            continue
                        if line == "data: [DONE]":
                            if in_thinking:
                                if (
                                    _final_reasoning_started_at is not None
                                    and not _final_reasoning_summary_emitted
                                ):
                                    _final_reasoning_summary_emitted = True
                                    yield _reasoning_summary_event(_final_reasoning_started_at)
                                if has_content_tokens:
                                    cumulative += "</think>"
                                    _prov_entry = None
                                    yield {
                                        "type": "content",
                                        "text": _strip_tool_markup(cumulative, final = True),
                                    }
                                else:
                                    cumulative = _finalize_reasoning_only_cumulative(
                                        cumulative,
                                        reasoning_text,
                                        _metadata_finish_reason,
                                        promote_reasoning_only,
                                    )
                                    _prov_entry = None
                                    yield {"type": "content", "text": cumulative}
                            _stream_done = True
                            break  # exit inner while
                        if not line.startswith("data: "):
                            continue

                        try:
                            chunk_data = json.loads(line[6:])

                            _report_live_llama_timings(perf_callback, chunk_data)
                            # Capture server timings/usage from final chunks.
                            _chunk_timings = chunk_data.get("timings")
                            if _chunk_timings:
                                _metadata_timings = _chunk_timings
                            _chunk_usage = chunk_data.get("usage")
                            if _chunk_usage:
                                _metadata_usage = _chunk_usage
                            # See the note on the first stream loop.
                            _stream_error = stream_error_from_chunk(chunk_data)
                            if _stream_error is not None:
                                raise _stream_error
                            choices = chunk_data.get("choices", [])
                            if choices:
                                delta = choices[0].get("delta", {})
                                _fr = choices[0].get("finish_reason")
                                if _fr:
                                    _metadata_finish_reason = _fr

                                reasoning = delta.get("reasoning_content", "")
                                if reasoning:
                                    if _final_reasoning_started_at is None:
                                        _final_reasoning_started_at = time.monotonic()
                                    reasoning_text += reasoning
                                    if not in_thinking:
                                        if reasoning_provenance is not None and not cumulative:
                                            reasoning_provenance["wrapped"] = (
                                                reasoning_provenance.get("wrapped", 0) + 1
                                            )
                                            _prov_entry = {"len": 0}
                                            reasoning_provenance.setdefault("wraps", []).append(
                                                _prov_entry
                                            )
                                        cumulative += "<think>"
                                        in_thinking = True
                                    cumulative += reasoning
                                    if _prov_entry is not None:
                                        _prov_entry["len"] += len(reasoning)
                                    yield {"type": "content", "text": cumulative}

                                token = delta.get("content", "")
                                if token:
                                    if (
                                        _final_reasoning_started_at is not None
                                        and not _final_reasoning_summary_emitted
                                    ):
                                        _final_reasoning_summary_emitted = True
                                        yield _reasoning_summary_event(_final_reasoning_started_at)
                                    has_content_tokens = True
                                    if in_thinking:
                                        cumulative += "</think>"
                                        in_thinking = False
                                        _prov_entry = None
                                    cumulative += token
                                    cleaned = (
                                        _final_answer_stripper.strip(cumulative)
                                        if auto_heal_tool_calls
                                        else cumulative
                                    )
                                    # Emit only when cleaned text grows (monotonic).
                                    if len(cleaned) > len(_last_emitted):
                                        _last_emitted = cleaned
                                        yield {"type": "content", "text": cleaned}
                        except json.JSONDecodeError:
                            logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                    if _stream_done:
                        break  # exit outer for
                _meta = _build_metadata_event(
                    _metadata_usage, _metadata_timings, _metadata_finish_reason
                )
                if _meta is not None:
                    yield _meta

        except _LlamaStreamCancelled:
            return
        except httpx.ConnectError:
            raise RuntimeError("Lost connection to llama-server")
        except Exception as e:
            if cancel_event is not None and cancel_event.is_set():
                return
            raise

    # ── Prompt token counting ──────────────────────────────────

    def count_chat_tokens(
        self,
        messages,
        system = None,
        tools = None,
        strict: bool = False,
        chat_template_kwargs = None,
        continue_final_message: bool = False,
        should_abort = None,
    ) -> int:
        """Count prompt tokens for a chat request via llama-server.

        Non-strict callers keep the historical best-effort behavior and get 0 when a
        count cannot be determined. Strict callers (public count_tokens endpoints)
        raise instead: the text-only fallback is an approximation, not a count.

        ``chat_template_kwargs`` reaches /apply-template unchanged, so a caller can
        price a request rendered in a non-default reasoning mode.

        ``should_abort`` is polled between the two llama-server calls. Admission is the
        caller's job; this only stops a count that was admitted while idle from spending its
        second round trip once the answer stopped mattering. Raises when it fires.
        """
        if not self.is_loaded:
            if strict:
                raise RuntimeError("llama-server is not loaded")
            return 0

        def _block_text(content) -> str:
            if isinstance(content, str):
                return content
            if isinstance(content, list):
                parts = []
                for block in content:
                    if isinstance(block, dict):
                        if isinstance(block.get("text"), str):
                            parts.append(block["text"])
                    elif isinstance(block, str):
                        parts.append(block)
                return "".join(parts)
            return ""

        # Normalize system into a leading message / plain text.
        system_text = ""
        if isinstance(system, str):
            system_text = system
        elif isinstance(system, list):
            system_text = _block_text(system)

        # Count the neutralized prompt: raw text budgets a prompt generation never sends (#7066).
        from core.inference.chat_template_helpers import (
            neutralize_control_markup,
            neutralize_control_markup_in_messages,
            neutralize_tool_descriptions,
        )

        _profile = self.markup_profile
        messages = neutralize_control_markup_in_messages(messages, None, _profile)
        # The model's own profile, like its two neighbours. The curated sweep here made the
        # count describe a different prompt from the one generation sends: a Llama profile
        # has no "</think>", so generation leaves that text byte-exact while the count path
        # was turning it into "< /think>" before /apply-template (#7066).
        system_text = (
            neutralize_control_markup(system_text)
            if _profile is None
            else _profile.rewrite_control(system_text)
        )
        tools = neutralize_tool_descriptions(tools, None, _profile)

        try:
            with httpx.Client(timeout = 10, headers = self._auth_headers, trust_env = False) as client:

                def _tokenize(text: str) -> int:
                    r = client.post(
                        f"{self.base_url}/tokenize",
                        json = {"content": text, "add_special": True},
                    )
                    if r.status_code != 200:
                        if strict:
                            raise RuntimeError("llama-server tokenizer failed")
                        return 0
                    tokens = r.json().get("tokens", [])
                    if not isinstance(tokens, list):
                        if strict:
                            raise RuntimeError("llama-server tokenizer returned invalid tokens")
                        return 0
                    return len(tokens)

                # 1. Try /apply-template to render the real chat prompt.
                template_messages = list(messages) if messages else []
                if system_text:
                    template_messages = [
                        {"role": "system", "content": system_text}
                    ] + template_messages
                # An empty list is passed through as-is: llama-server renders through minja, not
                # jinja2, so messages[0] yields undefined rather than raising and the template
                # returns its bare preamble. A placeholder turn would add a system block instead.
                apply_template_failed = False
                try:
                    # llama-server's /apply-template renders tool declarations
                    # into the prompt when ``tools`` is supplied, so pass them
                    # through, otherwise tool-schema tokens go uncounted.
                    template_body = {"messages": template_messages}
                    if tools:
                        template_body["tools"] = tools
                    # Layered over the load-time --chat-template-kwargs: only keys sent here move.
                    if chat_template_kwargs:
                        template_body["chat_template_kwargs"] = chat_template_kwargs
                    if continue_final_message:
                        template_body["continue_final_message"] = True
                        template_body["add_generation_prompt"] = False
                    resp = client.post(
                        f"{self.base_url}/apply-template",
                        json = template_body,
                    )
                    if resp.status_code == 200:
                        prompt = resp.json().get("prompt", "")
                        if isinstance(prompt, str):
                            if should_abort is not None and should_abort():
                                raise CountAborted()
                            return _tokenize(prompt)
                    apply_template_failed = True
                except CountAborted:
                    # Not a template failure: swallowed, the text fallback tokenizes anyway,
                    # which is the work being declined. Must precede the generic except.
                    raise
                except Exception:
                    apply_template_failed = True

                # The fallback drops role markers, special tokens and tool schemas (~30% of a
                # six-turn two-tool prompt), so strict callers error rather than undercount.
                if strict and apply_template_failed:
                    raise RuntimeError("llama-server could not render the chat template")

                # 2. Fallback: concatenate plain text and tokenize. Append a
                # serialized form of the tools so they still contribute to the
                # count when /apply-template is unavailable.
                parts = []
                if system_text:
                    parts.append(system_text)
                for msg in messages or []:
                    if isinstance(msg, dict):
                        parts.append(_block_text(msg.get("content", "")))
                if tools:
                    try:
                        parts.append(json.dumps(tools, ensure_ascii = False))
                    except Exception:
                        pass
                return _tokenize("\n".join(p for p in parts if p))
        except Exception:
            if strict:
                raise
            return 0

    # ── TTS support ────────────────────────────────────────────

    def detect_audio_type(self) -> Optional[str]:
        """Detect audio/TTS codec; swallows errors (use _strict to distinguish)."""
        try:
            return self._detect_audio_type_strict()
        except Exception as e:
            logger.debug(f"Audio type detection failed: {e}")
            return None

    def _apply_detected_audio(self, detected: Optional[str]) -> bool:
        """Apply a probed audio codec under self._lock. Returns True to continue
        the load (codec inited OK, or nothing to init), False to abort (server
        unhealthy or codec init failed). Shared by the fast-path retry and the
        main load path."""
        if detected in ("snac", "bicodec", "dac"):
            with self._lock:
                if not self._healthy:
                    return False
                try:
                    self.init_audio_codec(detected)
                    self._is_audio = True
                    self._audio_type = detected
                except Exception as exc:
                    # Surface as HTTP 500 (matches pre-PR contract).
                    logger.warning("Failed to init audio codec '%s': %s", detected, exc)
                    self._audio_probed = False
                    return False
        elif detected:
            # csm / whisper / audio_vlm: track type but keep _is_audio False --
            # GGUF TTS routing only fires for snac/bicodec/dac.
            with self._lock:
                if not self._healthy:
                    return False
                self._audio_type = detected
        # Audio input = token probe (audio_vlm/whisper) OR mmproj encoder.
        from utils.models.model_config import is_audio_input_type

        self._has_audio_input = bool(is_audio_input_type(self._audio_type)) or bool(
            self._mmproj_has_audio
        )
        return True

    def _detect_audio_type_strict(self) -> Optional[str]:
        """Codec name on match, None on non-audio, raises on transport/JSON errors."""
        if not self.is_loaded:
            return None
        with httpx.Client(timeout = 10, headers = self._auth_headers, trust_env = False) as client:

            def _detok(tid: int) -> str:
                # Non-200 means "marker not in vocab" -- keep probing.
                # Transport / JSON errors still raise.
                r = client.post(f"{self.base_url}/detokenize", json = {"tokens": [tid]})
                if r.status_code != 200:
                    return ""
                return r.json().get("content", "")

            def _tok(text: str) -> list[int]:
                r = client.post(
                    f"{self.base_url}/tokenize",
                    json = {"content": text, "add_special": False},
                )
                if r.status_code != 200:
                    return []
                return r.json().get("tokens", [])

            # Codec-specific tokens (not generic ones that non-audio models may have)
            if "<custom_token_" in _detok(128258) and "<custom_token_" in _detok(128259):
                return "snac"
            if len(_tok("<|AUDIO|>")) == 1 and len(_tok("<|audio_eos|>")) == 1:
                return "csm"
            if len(_tok("<|startoftranscript|>")) == 1:
                return "whisper"
            # Gemma 3n: <audio_soft_token>; Gemma 4: <|audio|> (not csm's <|AUDIO|>).
            if len(_tok("<audio_soft_token>")) == 1 or len(_tok("<|audio|>")) == 1:
                return "audio_vlm"
            if len(_tok("<|bicodec_semantic_0|>")) == 1 and len(_tok("<|bicodec_global_0|>")) == 1:
                return "bicodec"
            if len(_tok("<|c1_0|>")) == 1 and len(_tok("<|c2_0|>")) == 1:
                return "dac"
        return None

    # Prompt format per codec: (template, stop_tokens, needs_token_ids).
    # Matches InferenceBackend._generate_snac/bicodec/dac.
    _TTS_PROMPTS = {
        "snac": (
            "<custom_token_3>{text}<|eot_id|><custom_token_4>",
            ["<custom_token_2>"],
            True,
        ),
        "bicodec": (
            "<|task_tts|><|start_content|>{text}<|end_content|><|start_global_token|>",
            ["<|im_end|>", "</s>"],
            False,
        ),
        "dac": (
            "<|im_start|>\n<|text_start|>{text}<|text_end|>\n<|audio_start|><|global_features_start|>\n",
            ["<|im_end|>", "<|audio_end|>"],
            False,
        ),
    }

    _codec_mgr = None  # Shared AudioCodecManager instance

    def init_audio_codec(self, audio_type: str) -> None:
        """Load the audio codec at model load time (mirrors the non-GGUF path)."""
        import torch
        from core.inference.audio_codecs import AudioCodecManager

        if LlamaCppBackend._codec_mgr is None:
            LlamaCppBackend._codec_mgr = AudioCodecManager()

        device = "cuda" if torch.cuda.is_available() else "cpu"
        model_repo_path = None

        # BiCodec needs a repo with BiCodec/ weights -- download canonical SparkTTS
        if audio_type == "bicodec":
            from huggingface_hub import snapshot_download
            import os

            repo_path = snapshot_download("unsloth/Spark-TTS-0.5B")
            model_repo_path = os.path.abspath(repo_path)

        LlamaCppBackend._codec_mgr.load_codec(audio_type, device, model_repo_path = model_repo_path)
        logger.info(f"Loaded audio codec for GGUF TTS: {audio_type}")

    def generate_audio_response(
        self,
        text: str,
        audio_type: str,
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 50,
        min_p: float = 0.0,
        max_new_tokens: int = 2048,
        repetition_penalty: float = 1.1,
        cancel_event: Optional[threading.Event] = None,
    ) -> tuple:
        """
        Generate TTS audio via llama-server /completion + codec decode.
        Returns (wav_bytes, sample_rate).

        ``cancel_event`` lets a Stop or a forced model swap end the request: the
        decode is one blocking POST, so a watcher closes the client out from under
        it rather than polling. Raises RuntimeError once cancelled.
        """
        if audio_type not in self._TTS_PROMPTS:
            raise RuntimeError(f"GGUF TTS does not support '{audio_type}' codec.")

        tpl, stop, need_ids = self._TTS_PROMPTS[audio_type]
        # Raw prompt, not messages: codec delimiters are the only structure to break (#7066).
        from core.inference.chat_template_helpers import neutralize_tts_prompt_text

        payload: dict = {
            "prompt": tpl.format(text = neutralize_tts_prompt_text(text, audio_type)),
            "stream": False,
            "n_predict": max_new_tokens,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
        }
        if stop:
            payload["stop"] = stop
        if need_ids:
            payload["n_probs"] = 1

        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("Audio generation cancelled")

        # Scale with the request the way the subprocess path does: a flat 300s aborts a
        # legitimate long generation on a CPU-only or slow host now that the page offers
        # more tokens than the old ceiling. Scaled from this backend's own 300s floor,
        # not the subprocess one: llama.cpp answers in seconds, and /audio/speech is in
        # _INFERENCE_SUFFIXES, so a wedged server holds other_inference_request_count()
        # up for the whole window, blocking idle auto-unload and 409-ing a training start.
        # Imported here to keep the module import acyclic.
        from core.inference.orchestrator import _audio_generation_timeout

        read_timeout = _audio_generation_timeout(max_new_tokens, base = _GGUF_AUDIO_READ_TIMEOUT)
        with httpx.Client(
            timeout = httpx.Timeout(read_timeout, connect = 10),
            headers = self._auth_headers,
            trust_env = False,
        ) as client:
            finished = threading.Event()
            watcher: Optional[threading.Thread] = None
            if cancel_event is not None:

                def _close_when_cancelled() -> None:
                    while not finished.wait(0.05):
                        if cancel_event.is_set():
                            # Closing mid-request makes the blocking post raise
                            # httpx.RequestError, the only way out of it.
                            with contextlib.suppress(Exception):
                                client.close()
                            return

                watcher = threading.Thread(target = _close_when_cancelled, daemon = True)
                watcher.start()
            try:
                resp = client.post(f"{self.base_url}/completion", json = payload)
            except httpx.RequestError:
                if cancel_event is not None and cancel_event.is_set():
                    raise RuntimeError("Audio generation cancelled") from None
                raise
            finally:
                finished.set()
                if watcher is not None:
                    watcher.join(timeout = 0.5)
            if resp.status_code != 200:
                raise RuntimeError(f"llama-server returned {resp.status_code}: {resp.text}")

        # The codec decode below is GPU work with no interruption point, so check here:
        # cancelling after this only wastes the decode it cannot stop.
        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("Audio generation cancelled")

        data = resp.json()
        token_ids = (
            [p["id"] for p in data.get("completion_probabilities", []) if "id" in p]
            if need_ids
            else None
        )

        import torch

        device = "cuda" if torch.cuda.is_available() else "cpu"
        return LlamaCppBackend._codec_mgr.decode(
            audio_type, device, token_ids = token_ids, text = data.get("content", "")
        )
